window.CBT_EXPL={"2020-2-기관1-1":{"w":"무기 분사식 디젤기관(고압 연료를 직접 분사)은 복합(사바테) 사이클을 기본으로 합니다.","x":["정답. 복합 사이클","가솔린기관입니다.","공기 분사식 저속기관입니다.","증기 사이클입니다."],"t":"무기 분사식 = 복합 사이클"},"2020-2-기관1-2":{"w":"1[PS] ≒ 0.736[kW]이므로 1[kW] ≒ 1.36[PS]입니다.","x":["틀립니다.","1[PS]의 [kW] 값입니다.","1[PS]의 [kgf·m/s] 값입니다.","정답. 1.36[PS]"],"t":"1kW = 1.36PS"},"2020-2-기관1-9":{"w":"과부하 운전은 정격출력 이상의 출력으로 운전하는 상태입니다.","x":["정답. 정격출력 이상","과속 운전입니다.","과부하의 한 증상일 뿐 정의가 아닙니다.","정의가 아닙니다."],"t":"과부하 = 정격출력 초과"},"2020-2-기관1-11":{"w":"크랭크실 이상(과열, 오일 미스트)으로 기관을 멈추면 인디케이터 밸브를 열고 터닝해 고착을 막습니다. 폭발 위험이 있으므로 크랭크실 문을 바로 열면 안 되고, 윤활유 펌프는 계속 돌려 냉각합니다.","x":["정답. 인디케이터 밸브 열고 터닝","윤활유 펌프는 계속 운전합니다.","냉각수 펌프는 계속 운전합니다.","바로 열면 공기 유입으로 폭발할 수 있습니다."],"t":"크랭크실 이상 = 문 바로 열지 않기"},"2020-2-기관1-19":{"w":"프로펠러 진동은 날개 변형·손상, 피치 불균일, 불평형 등으로 생깁니다.","x":["과급기 문제입니다.","프로펠러 진동 원인이 아닙니다.","정답. 날개의 변형","기관 문제입니다."],"t":"프로펠러 진동 = 날개 변형·불평형"},"2020-2-기관1-20":{"w":"프로펠러는 알루미늄 청동, 고력 황동, 스테인리스강, 주강 등으로 만듭니다. 주철은 약하고 잘 깨져 쓰지 않습니다.","x":["재료입니다.","재료입니다.","재료입니다.","정답(아닌 것). 고급 주철"],"t":"프로펠러 = 동합금·스테인리스"},"2020-2-기관1-21":{"w":"선박용 중유의 인화점은 안전을 위해 60[℃] 이상이어야 합니다.","x":["너무 낮습니다.","너무 낮습니다.","너무 낮습니다.","정답. 60[℃] 이상"],"t":"선박 연료 인화점 ≥ 60℃"},"2020-2-기관1-23":{"w":"왕복 48해리 ÷ 12노트 = 4시간, 연료 40리터, 예비 20[%] 8리터를 더해 48리터입니다.","x":["정답. 48리터","틀립니다.","틀립니다.","틀립니다."],"t":"연료 = 시간 × 소비량 × 1.2"},"2020-2-기관1-24":{"w":"윤활유 열화 원인은 물 혼입, 연료유 희석, 산화 등입니다. 청정기 연속 운전은 오히려 열화를 막습니다.","x":["원인입니다.","원인입니다.","정답(아닌 것). 청정기 연속 운전","원인입니다."],"t":"청정기 연속 운전 = 열화 방지"},"2020-2-기관2-2":{"w":"청정기는 진동이 심하면 멈춰 점검하고, 통유 직후 출구를 점검하며, 처리량을 적게 할수록 청정 효과가 좋습니다. 청정에 알맞은 점도는 약 13~15[cSt] 정도로 100[cSt]는 너무 높습니다.","x":["맞습니다.","맞습니다.","맞습니다.","정답(옳지 않은 것). 100[cSt]는 너무 높습니다."],"t":"청정 적정 점도 ≒ 13~15cSt"},"2020-2-기관2-3":{"w":"원심펌프의 흡입밸브를 조여 유량을 조절하면 흡입 압력이 떨어져 캐비테이션이 생길 수 있습니다.","x":["틀립니다.","틀립니다.","틀립니다.","정답. 캐비테이션 발생"],"t":"흡입밸브 조임 = 캐비테이션"},"2020-2-기관2-5":{"w":"닻줄 1섀클(shackle)의 길이는 27.5[m]입니다.","x":["틀립니다.","틀립니다.","정답. 27.5[m]","틀립니다."],"t":"1섀클 = 27.5m"},"2020-2-기관2-8":{"w":"기관실 선저폐수를 선외로 배출하려면 15[ppm] 기름여과장치가 필요합니다.","x":["정답. 15[ppm] 기름여과장치","청정장치가 아닙니다.","오수처리장치가 아닙니다.","소각장치가 아닙니다."],"t":"빌지 배출 = 기름여과장치"},"2020-2-기관2-12":{"w":"냉동 효과는 냉매 1[kg](단위 중량)이 증발기에서 흡수하는 열량입니다. 단위 시간당 흡수 열량은 냉동능력입니다.","x":["냉동능력입니다.","틀립니다.","정답. 단위 중량당 흡수 열량","응축기 방열량입니다."],"t":"냉동효과 = kcal/kg, 냉동능력 = kcal/h"},"2020-2-기관2-15":{"w":"중앙 공기조화 방식은 각 선실의 취출구 댐퍼 개도로 공기량을 조절해 온도를 조절합니다.","x":["정답. 취출구 댐퍼","유인 방식입니다.","재열 방식입니다.","2중 덕트 방식입니다."],"t":"중앙식 = 댐퍼"},"2020-2-기관2-23":{"w":"밸러스트 탱크는 종경사·횡경사 조절과 복원성 향상에 씁니다. 만선 항해 때는 이미 흘수가 깊으므로 밸러스트를 넣어 추진효율을 높이지 않습니다(공선 항해 때 넣습니다).","x":["역할입니다.","역할입니다.","역할입니다.","정답(옳지 않은 것). 밸러스트는 공선 때 넣습니다."],"t":"밸러스트 = 공선 항해 시 흘수 확보"},"2020-2-기관2-25":{"w":"기계 제도에는 실선, 파선, 1점·2점 쇄선, 자유실선을 씁니다. 2점파선은 없습니다.","x":["파단선으로 씁니다.","정답(아닌 것). 2점파선","숨은선으로 씁니다.","가상선으로 씁니다."],"t":"선 종류 = 실선·파선·쇄선"},"2020-2-기관3-3":{"w":"Z = √(3² + 4²) = 5[Ω], 역률 = R ÷ Z = 3 ÷ 5 = 0.6입니다.","x":["정답. 0.6","틀립니다.","무효율(4/5)입니다.","틀립니다."],"t":"cosθ = R / Z"},"2020-2-기관3-5":{"w":"콘덴서만 있는 회로에서는 전류 I가 전압 E보다 90° 빠릅니다.","x":["60°가 아닙니다.","정답. 90° 빠름","틀립니다.","코일 회로입니다."],"t":"C = 전류 90° 앞섬"},"2020-2-기관3-7":{"w":"저항만의 회로에서 I = E ÷ R 입니다(옴의 법칙).","x":["틀립니다.","틀립니다.","정답. I = E/R","틀립니다."],"t":"I = E / R"},"2020-2-기관3-8":{"w":"전류계는 부하와 직렬, 전압계는 부하와 병렬로 연결합니다. 전력계는 전류 코일(직렬)과 전압 코일(병렬)을 함께 연결합니다.","x":["①은 틀립니다.","정답. ②만 옳다","①, ③ 모두 틀립니다.","①, ③은 틀립니다."],"t":"전류계 직렬, 전압계 병렬"},"2020-2-기관3-10":{"w":"유도성(지상) 부하가 걸리면 전기자 반작용은 계자 자속을 줄이는 감자작용입니다.","x":["해당하지 않습니다.","정답. 감자작용","용량성 부하입니다.","저항 부하입니다."],"t":"유도성 = 감자"},"2020-2-기관3-12":{"w":"Y결선에서 선간전압은 상전압의 √3배입니다.","x":["틀립니다.","정답. √3배","틀립니다.","틀립니다."],"t":"Y = 전압 √3배"},"2020-2-기관3-13":{"w":"전해액은 증류수에 진한 황산을 조금씩 부어 만듭니다. 황산에 물을 부으면 급격히 끓어 튀어 매우 위험합니다.","x":["위험합니다.","정답. 증류수에 황산을 조금씩","매우 위험합니다.","틀립니다."],"t":"물에 황산을(반대 금지)"},"2020-2-기관3-14":{"w":"유도전동기의 회전자는 회전자계보다 조금 느리게 돕니다.","x":["정답. 회전자계가 더 빠름","반대입니다.","같으면 토크 0","틀립니다."],"t":"동기속도 > 회전자"},"2020-2-기관3-16":{"w":"V2 = 600 × 400 ÷ 2,000 = 120[V]입니다.","x":["정답. 120[V]","틀립니다.","틀립니다.","곱한 값입니다."],"t":"V2 = V1 × N2/N1"},"2020-2-기관3-17":{"w":"납축전지는 방전하면 황산이 소모되어 전해액 비중과 전압이 함께 내려갑니다.","x":["충전 때입니다.","틀립니다.","정답. 함께 내려감","틀립니다."],"t":"방전 = 비중·전압↓"},"2020-2-기관3-18":{"w":"납축전지는 과방전을 피하고, 전해액이 줄면 증류수를 보충하며, 축전지실을 환기합니다. 액마개는 정상적으로 닫아 두며 가스는 마개의 통기 구멍으로 나갑니다.","x":["맞습니다.","맞습니다.","정답(옳지 않은 것). 액마개를 열어 두지 않습니다.","맞습니다."],"t":"축전지 = 환기, 마개는 닫기"},"2020-2-기관3-20":{"w":"실리콘 반도체의 불순물은 붕소(3가, P형), 인·비소(5가, N형) 등입니다. 수소는 불순물로 쓰지 않습니다.","x":["맞습니다.","맞습니다.","맞습니다.","정답(옳지 않은 것). 수소는 아닙니다."],"t":"P형 = 붕소, N형 = 인·비소"},"2020-2-기관3-22":{"w":"전압에 따라 저항이 변하는 소자는 배리스터(Varistor)입니다. 과전압 보호에 씁니다.","x":["SSS는 양방향 사이리스터입니다.","CdS는 빛으로 변합니다.","정답. Varistor","LED는 발광 소자입니다."],"t":"배리스터 = 전압 → 저항 변화"},"2020-2-기관3-23":{"w":"GTO(Gate Turn-Off) 사이리스터는 게이트 신호만으로 켜고 끌 수 있습니다.","x":["SCR은 게이트로 끌 수 없습니다.","PUT는 발진용입니다.","SCS는 해당하지 않습니다.","정답. GTO"],"t":"GTO = 게이트로 ON/OFF"},"2020-2-기관3-24":{"w":"진성 반도체는 불순물이 없는 순수한 반도체로 전자와 정공의 밀도가 같습니다.","x":["정답. 정공과 전자의 밀도가 같다","P형입니다.","P형입니다.","P형입니다."],"t":"진성 = 전자 수 = 정공 수"},"2020-2-직무일반-1":{"w":"당직기관사는 당직 중 일어난 일을 그때그때 기관일지에 기록해야 합니다. 당직이 끝난 뒤 몰아서 기록하는 것은 옳지 않습니다(출제 기준).","x":["맞습니다.","맞습니다.","맞습니다.","정답(옳지 않은 것)."],"t":"일지 = 즉시 기록"},"2020-2-직무일반-8":{"w":"수급 중 유출되면 즉시 수급을 멈추고, 관련 기관에 알리며, 오일펜스를 칩니다. 모든 밸브를 갑자기 잠그면 관 속 압력이 급상승해 호스·배관이 터질 수 있으므로 펌프 정지(공급선 연락)가 먼저입니다.","x":["맞습니다.","맞습니다.","정답(옳지 않은 것). 밸브를 먼저 모두 잠그면 위험합니다.","맞습니다."],"t":"수급 중 유출 = 공급 중지 먼저"},"2020-2-직무일반-9":{"w":"HCFC 냉매 장치의 팽창밸브를 교환하려면 냉매 계통을 열어야 하므로 냉매(오존층파괴물질)가 샐 수 있습니다.","x":["해당하지 않습니다.","냉매 계통을 열지 않습니다.","정답. 팽창밸브 교환","냉각수 쪽 작업입니다."],"t":"냉매 계통 개방 = ODS 누설"},"2020-2-직무일반-18":{"w":"A급 구획(A-0 등)은 강 또는 동등한 재료로 만듭니다. B·C급은 불연재입니다.","x":["정답. A-0급","B급은 불연재입니다.","B급은 불연재입니다.","C급은 불연재입니다."],"t":"A급 = 강재"},"2020-2-직무일반-19":{"w":"열작업 때는 반대편 격실에도 감시원을 두고, 가스 용기는 세우며, 혼자 작업하지 않습니다. 개폐구를 닫으면 통풍이 안 되어 위험합니다.","x":["맞습니다.","맞습니다.","맞습니다.","정답(옳지 않은 것). 통풍을 유지합니다."],"t":"열작업 = 통풍·감시원"},"2020-2-직무일반-21":{"w":"기관실 화재 때는 선교에 알리고, 소화부서 배치를 발령해 소화합니다. 비상전원을 차단하면 소화펌프·조명이 멈춰 위험합니다.","x":["맞습니다.","맞습니다.","맞습니다.","정답(옳지 않은 것). 비상전원은 유지합니다."],"t":"화재 = 비상전원 유지"},"2020-2-직무일반-22":{"w":"플라스틱류는 어떤 해역에서도 바다에 버릴 수 없습니다.","x":["정답(위반). 플라스틱 배출","12해리 이상은 가능합니다.","기준에 맞습니다.","기준에 맞습니다."],"t":"플라스틱 = 전면 금지"},"2020-2-영어-2":{"w":"압력은 [MPa](파스칼) 단위로 잽니다.","x":["정답. MPa","N은 힘","cal은 열량","kW는 일률"],"t":"압력 = Pa"},"2020-2-영어-5":{"w":"\"지방표준시에 맞추려고 시계를 1시간 전진시켰다(앞당겼다).\"","x":["측정이 아닙니다.","후진은 retard입니다.","조정보다 구체적으로 전진입니다.","정답. 시간을 전진시켰다"],"t":"advance clock = 앞당김"},"2020-2-영어-9":{"w":"기관부를 지휘하는 책임자는 기관장(chief engineer)입니다.","x":["정답. chief engineer","1기사","당직 기관사","1등 항해사"],"t":"기관부 책임 = 기관장"},"2020-2-영어-11":{"w":"scavenging ports = 소기공 입니다.","x":["정답. 소기공","배기공이 아닙니다.","절구틈이 아닙니다.","배기 통로가 아닙니다."],"t":"scavenging port = 소기공"},"2020-2-영어-12":{"w":"액체에 에너지를 주어 압력을 높이고 움직이게 하는 장치는 pump입니다.","x":["정답. pump","관","냉각기","증발기"],"t":"pump"},"2020-2-영어-20":{"w":"탱크 드레인과 화물탱크 세정수를 모으는 탱크는 Slop tank(슬롭 탱크, 혼합물 탱크)입니다.","x":["중앙 탱크","윙 탱크","밸러스트 탱크","정답. Slop tank"],"t":"slop tank = 혼합물 탱크"},"2020-2-영어-24":{"w":"전기를 만드는 기계는 generator(발전기)입니다.","x":["전동기는 전기를 씁니다.","조속기","정답. generator","축전지는 저장합니다."],"t":"generator = 발전기"},"2020-2-영어-25":{"w":"보일러 압력을 방출해 폭발을 막는 것은 Safety valve입니다.","x":["점화기","정답. Safety valve","Relief valve는 주로 액체용","전동기"],"t":"보일러 = safety valve"},"2020-3-기관1-1":{"w":"피스톤을 뺐을 때 라이너는 안지름으로 마멸량을 재고, 마멸·스케일·윤활 상태를 봅니다. 두께는 라이너를 빼지 않으면 잴 수 없어 점검사항이 아닙니다.","x":["정답(아닌 것). 두께 측정","점검합니다.","점검합니다.","점검합니다."],"t":"라이너 = 안지름(마멸량) 계측"},"2020-3-기관1-3":{"w":"연접봉의 길이는 소단부(피스톤핀) 중심과 대단부(크랭크핀) 중심 사이 거리입니다. 그림의 ①~④ 바깥 끝 사이 길이가 아닙니다.","x":["정답(옳지 않은 것). 중심 간 거리로 잽니다.","맞습니다.","맞습니다.","맞습니다(심 두께↑ → 압축비↑)."],"t":"연접봉 길이 = 중심 간 거리"},"2020-3-기관1-4":{"w":"2행정: Pi = P·A·L·N·Z ÷ 4,500 = 7.5 × 400 × 0.2 × 300 × 6 ÷ 4,500 = 240[PS] ≒ 176[kW]입니다.","x":["4행정으로 잘못 계산한 값입니다.","정답. 176[kW]","틀립니다.","틀립니다."],"t":"2행정 N 그대로, 4행정 N/2"},"2020-3-기관1-5":{"w":"풋라이너(심)는 연접봉 길이를 바꿔 피스톤 위치(압축비)만 바꿉니다. 행정은 크랭크 반지름으로 정해지므로 변하지 않습니다.","x":["정답. 변화 없음","행정은 바뀌지 않습니다.","행정은 바뀌지 않습니다.","행정은 바뀌지 않습니다."],"t":"심 → 압축비 변화, 행정 불변"},"2020-3-기관1-7":{"w":"노킹은 분사가 너무 빠를 때, 냉각수 온도가 낮을 때, 노즐 누설(후적) 때 생깁니다. 분사압력이 높으면 무화가 좋아져 노킹 원인이 아닙니다.","x":["원인입니다.","원인입니다.","정답(아닌 것). 분사압력이 높은 경우","원인입니다."],"t":"분사압력 높음 = 무화 좋음"},"2020-3-기관1-8":{"w":"성능곡선에는 출력에 따른 연료소비율, 효율, 최고압력, 배기온도 등이 나타납니다. 연료분사압력은 나오지 않습니다.","x":["알 수 있습니다.","알 수 있습니다.","알 수 있습니다.","정답(아닌 것). 연료분사압력"],"t":"성능곡선 ≠ 분사압력"},"2020-3-기관1-9":{"w":"냉각수 온도가 너무 낮으면 열손실이 커져 효율이 떨어지고 연료소비가 늘며 저온부식이 생깁니다. 압축압력은 오히려 떨어집니다.","x":["맞습니다.","정답(옳지 않은 것). 압축압력은 증가하지 않습니다.","맞습니다.","맞습니다."],"t":"냉각수 과냉 = 효율↓, 저온부식"},"2020-3-기관1-13":{"w":"보일러수의 불순물·물방울이 증기와 함께 나가는 현상은 기수공발(캐리오버)입니다.","x":["펌프·프로펠러 현상입니다.","분리장치입니다.","알칼리에 의한 균열입니다.","정답. 기수공발"],"t":"carry over = 기수공발"},"2020-3-기관1-14":{"w":"수관보일러는 효율과 증발률이 높고 좋은 급수가 필요하지만 구조가 복잡합니다.","x":["맞습니다.","정답(옳지 않은 것). 구조가 복잡합니다.","맞습니다.","맞습니다."],"t":"수관 = 고효율·복잡"},"2020-3-기관1-15":{"w":"내부손실은 증기 통로 안에서 생기는 노즐·블레이드·회전 손실 등입니다. 베어링 마찰 손실은 외부손실입니다.","x":["내부손실입니다.","정답(아닌 것). 외부손실","내부손실입니다.","내부손실입니다."],"t":"베어링 마찰 = 외부손실"},"2020-3-기관1-16":{"w":"글랜드 누설은 슬리브 마멸, 선미관 간극 과대, 패킹 조임 불균일 때문입니다. 추진기 슬립은 관계가 없습니다.","x":["원인입니다.","정답(아닌 것). 슬립 과대","원인입니다.","원인입니다."],"t":"선미관 누설 = 슬리브·간극·패킹"},"2020-3-기관1-19":{"w":"프로펠러 보스를 속이 빈 중공으로 만드는 것은 무게를 줄이기 위해서입니다.","x":["틀립니다.","틀립니다.","틀립니다.","정답. 중량 경감"],"t":"중공 = 경량"},"2020-3-기관1-20":{"w":"공동현상(캐비테이션)은 기포가 터지면서 날개 표면을 침식(점식)시킵니다.","x":["해당하지 않습니다.","탈아연은 화학적 부식입니다.","정답. 표면 침식","해당하지 않습니다."],"t":"캐비테이션 = 침식"},"2020-3-기관1-21":{"w":"연료의 유황이 연소해 황산이 되어 저온부식을 일으킵니다. 바나듐·나트륨은 고온부식 원인입니다.","x":["정답. 유황","고온부식입니다.","고온부식입니다.","해당하지 않습니다."],"t":"저온 = S, 고온 = V·Na"},"2020-3-기관1-24":{"w":"유체마찰은 두 면 사이에 유막이 완전히 형성된 상태로 마찰이 가장 작습니다.","x":["유막이 얇습니다.","마찰이 큽니다.","마찰이 가장 큽니다.","정답. 유체마찰"],"t":"유체 < 경계 < 고체"},"2020-3-기관1-25":{"w":"청정기는 통유량을 적게 해야 분리효과가 좋아집니다.","x":["맞습니다.","맞습니다.","맞습니다.","정답(옳지 않은 것). 통유량은 적게"],"t":"청정 = 통유량 적게"},"2020-3-기관2-3":{"w":"행정을 바꿔 유량과 방향을 조절하는 펌프는 가변 용량형 펌프(예: 헬레쇼 펌프)입니다.","x":["유량이 고정됩니다.","정용량입니다.","해당하지 않습니다.","정답. 가변 용량형"],"t":"가변 용량형 = 유량·방향 조절"},"2020-3-기관2-7":{"w":"전동유압식 조타장치는 주로 가변 용량형 펌프(헬레쇼·워터베리)를 씁니다. 정 용량형이 아닙니다.","x":["정답(옳지 않은 것). 가변 용량형을 씁니다.","맞습니다.","맞습니다.","맞습니다."],"t":"조타 펌프 = 가변 용량형"},"2020-3-기관2-9":{"w":"불활성가스(IG)는 연돌 → 세정탑(냉각·세척) → 송풍기 → 데크실(역류 방지) → 탱크 순서로 흐릅니다.","x":["정답. 연돌→세정탑→송풍기→데크실→탱크","순서가 틀립니다.","순서가 틀립니다.","순서가 틀립니다."],"t":"IG = 세정 → 송풍 → 데크실"},"2020-3-기관2-12":{"w":"증발 잠열이 가장 큰 냉매는 암모니아입니다(약 313[kcal/kg]).","x":["작습니다.","정답. 암모니아","작습니다.","작습니다."],"t":"잠열 최대 = NH3"},"2020-3-기관2-13":{"w":"1냉동톤은 0℃ 물 1톤을 24시간에 0℃ 얼음으로 만드는 능력으로 3,320[kcal/h]입니다.","x":["틀립니다.","틀립니다.","정답. 24시간, 3,320","틀립니다."],"t":"1RT = 3,320kcal/h"},"2020-3-기관2-16":{"w":"수나사는 다이스로 깎고, 암나사는 탭으로 깎습니다.","x":["암나사용입니다.","정답. 다이스","절단용입니다.","다듬질용입니다."],"t":"수나사 = 다이스, 암나사 = 탭"},"2020-3-기관2-17":{"w":"알루미늄은 전기전도율이 구리보다 작고, 산과 알칼리에 약합니다.","x":["맞습니다.","맞습니다.","맞습니다.","정답(옳지 않은 것)."],"t":"Al 전도율 < Cu"},"2020-3-기관2-21":{"w":"기관실을 선미에 두면 가운데를 모두 화물창으로 쓸 수 있어 화물 용적이 최대가 됩니다.","x":["축 터널 때문에 줄어듭니다.","정답. 선미 기관선","선미보다 작습니다.","쓰지 않는 방식입니다."],"t":"선미 기관 = 화물창 최대"},"2020-3-기관2-22":{"w":"조파저항은 배의 속도에 가장 큰 영향을 받습니다(속도가 빨라질수록 급증).","x":["틀립니다.","틀립니다.","틀립니다.","정답. 속도"],"t":"조파저항 ∝ 속도"},"2020-3-기관2-23":{"w":"선저의 날개(수중익)에서 생기는 양력으로 선체를 띄우는 배는 수중익선입니다.","x":["공기로 띄웁니다.","정답. 수중익선","틀립니다.","수면 위를 납니다(WIG)."],"t":"수중익 = 양력"},"2020-3-기관2-24":{"w":"단면의 절단면에는 해칭선(가는 빗금)을 긋습니다.","x":["숨은선입니다.","중심선입니다.","가상선입니다.","정답. 해칭선"],"t":"절단면 = 해칭"},"2020-3-기관2-25":{"w":"중심선은 가는 1점 쇄선을 씁니다.","x":["외형선입니다.","치수선 등입니다.","정답. 1점 쇄선","가상선입니다."],"t":"중심선 = 1점 쇄선"},"2020-3-기관3-3":{"w":"전선 굵기는 흐르는 부하전류(허용전류)에 따라 정합니다.","x":["절연 두께와 관계됩니다.","정답. 부하전류","틀립니다.","틀립니다."],"t":"전선 굵기 = 허용전류"},"2020-3-기관3-5":{"w":"저항을 직렬로 더하면 합성저항이 커져 전류는 줄어듭니다(I = V/R).","x":["정답. 감소","틀립니다.","틀립니다.","틀립니다."],"t":"직렬 R↑ → I↓"},"2020-3-기관3-7":{"w":"P = V × I × cosθ = 100 × 5 × 0.8 = 400[W]입니다.","x":["틀립니다.","틀립니다.","정답. 400[W]","틀립니다."],"t":"P = VIcosθ"},"2020-3-기관3-8":{"w":"병렬 2[F]+2[F] = 4[F], 이것과 4[F] 직렬: 4×4 ÷ (4+4) = 2[F]입니다.","x":["틀립니다.","정답. 2[F]","병렬 부분만입니다.","모두 더한 값입니다."],"t":"C 병렬 = 합, 직렬 = 곱/합"},"2020-3-기관3-10":{"w":"그림처럼 계자(F)가 전기자(A)와 병렬로 연결되면 분권발전기입니다.","x":["직·병렬 두 계자가 있습니다.","정답. 분권","직렬 연결입니다.","별도 전원입니다."],"t":"분권 = 계자 병렬"},"2020-3-기관3-11":{"w":"한시동작 순시복귀 접점(타이머 ON 딜레이)은 접점 위에 삿갓(∧) 모양이 붙은 기호입니다.","x":["정답. ∧ 표시 접점","해당하지 않습니다.","일반 접점입니다.","일반 접점입니다."],"t":"한시동작 = ∧ 표시"},"2020-3-기관3-14":{"w":"직류발전기에서 교류 기전력을 일정한 방향의 직류로 바꾸는 것은 정류자입니다.","x":["정답. 정류자","자속을 만듭니다.","기전력을 만듭니다.","전류를 끌어냅니다."],"t":"정류자 = 교류 → 직류"},"2020-3-기관3-17":{"w":"농형 유도전동기는 값싸고 구조가 간단하지만 시동전류가 크고 속도 조정이 어렵습니다.","x":["정답(아닌 것). 속도 조정이 어렵습니다.","특징입니다.","특징입니다.","특징입니다."],"t":"농형 = 간단·저렴, 속도조정 어려움"},"2020-3-기관3-18":{"w":"입력은 베이스, 출력은 컬렉터, 이미터가 공통(접지)인 회로로 이미터 공통접지 증폭회로입니다.","x":["베이스가 접지입니다.","컬렉터가 접지입니다.","정답. 이미터 공통","두 트랜지스터를 연결한 회로입니다."],"t":"이미터 공통 = 가장 흔한 증폭회로"},"2020-3-기관3-19":{"w":"3상 단자 색은 R 적색, S 흰색, T 청색 순서로 표시합니다(출제 기준).","x":["정답. 적·흰·청","틀립니다.","틀립니다.","틀립니다."],"t":"R·S·T = 적·백·청"},"2020-3-기관3-20":{"w":"입력 A가 1이면 트랜지스터가 ON되어 X = 0, A가 0이면 OFF되어 X = 1(5V)입니다. NOT 회로입니다.","x":["틀립니다.","정답. 1→0, 0→1","입력과 같습니다(버퍼).","틀립니다."],"t":"트랜지스터 인버터 = NOT"},"2020-3-기관3-21":{"w":"입력이 모두 1일 때만 0이 되는 것은 NAND입니다.","x":["AND입니다.","정답. NAND","OR입니다.","NOR입니다."],"t":"11 → 0 = NAND"},"2020-3-기관3-22":{"w":"PNP는 컬렉터(P)-베이스(N)-이미터(P) 구조입니다. 다이오드 화살표는 P→N 방향이므로 컬렉터에서 베이스로, 이미터에서 베이스로 향합니다.","x":["정답. 두 화살표가 베이스 쪽으로","틀립니다.","NPN(베이스에서 바깥쪽)입니다.","틀립니다."],"t":"PNP = 화살표가 베이스로"},"2020-3-기관3-23":{"w":"P형 반도체는 3가 불순물을 넣어 정공이 많고, 주 반송자는 정공입니다. 자유전자가 정공보다 많은 것은 N형입니다.","x":["맞습니다.","맞습니다.","맞습니다.","정답(옳지 않은 것). N형입니다."],"t":"P형 = 정공 다수"},"2020-3-기관3-24":{"w":"빛을 받으면 전류가 흐르는 포토 다이오드가 광센서로 쓰입니다.","x":["증폭 소자입니다.","빛을 냅니다.","정답. 포토 다이오드","교류 스위칭 소자입니다."],"t":"빛 검출 = 포토 다이오드"},"2020-3-기관3-25":{"w":"P에 -, N에 +를 걸면 역방향 바이어스로 공핍층이 넓어져 전류가 흐르지 않습니다.","x":["전류가 흐르지 않습니다.","역방향입니다.","전위 장벽이 커집니다.","정답. 역방향 바이어스"],"t":"P(-) N(+) = 역방향"},"2020-3-직무일반-1":{"w":"황천 때 연료 계통 필터를 바이패스하면 떠오른 슬러지가 그대로 기관으로 들어가 위험합니다. 오히려 필터를 자주 점검·청소합니다.","x":["맞습니다.","맞습니다.","맞습니다.","정답(옳지 않은 것). 필터 바이패스 금지"],"t":"황천 = 공회전 주의, 필터 점검"},"2020-3-직무일반-2":{"w":"기관일지에는 데이워크 내용, 주기관 온도·압력, 회전수 변경 시각과 사유 등을 적습니다. 예비품 수량·잔량은 예비품 대장에 기록합니다.","x":["기입합니다.","기입합니다.","기입합니다.","정답(아닌 것). 예비품 대장"],"t":"예비품 = 별도 대장"},"2020-3-직무일반-4":{"w":"시체스트, 선외밸브, 선미관 베어링은 선저 쪽이라 입거해야 점검할 수 있습니다. 스러스트 베어링은 선내에 있어 항상 점검 가능합니다.","x":["입거 필요","정답(아닌 것). 스러스트 베어링","입거 필요","입거 필요"],"t":"스러스트 베어링 = 선내"},"2020-3-직무일반-7":{"w":"유흡착재, 오일펜스, 유겔화제는 방제 방법입니다. 침강제는 기름을 바닥에 가라앉혀 2차 오염을 일으키므로 쓰지 않습니다.","x":["방제 방법입니다.","정답(옳지 않은 것). 침강 처리","방제 방법입니다.","방제 방법입니다."],"t":"침강제 사용 금지"},"2020-3-직무일반-12":{"w":"열사병 환자는 체온을 서서히(시간당 약 1℃) 낮춥니다. 알코올, 찬물 목욕, 너무 찬 실내는 급격한 변화로 위험합니다.","x":["너무 급합니다.","너무 급합니다.","정답. 서서히","너무 춥습니다."],"t":"체온은 서서히"},"2020-3-직무일반-13":{"w":"지혈대는 수시로 풀었다 조이면 출혈이 반복되어 위험합니다. 한 번 맨 뒤 시간을 기록하고 의료진이 풀게 합니다.","x":["정답(옳지 않은 것). 수시로 풀지 않습니다.","맞습니다.","맞습니다.","맞습니다."],"t":"지혈대 = 풀지 말고 시간 기록"},"2020-3-직무일반-14":{"w":"심한 진동은 베드 볼트 이완, 위험회전수 운전, 실린더 간 최고압력 차이 등으로 생깁니다. 윤활유 압력 저하는 진동과 직접 관계가 없습니다.","x":["점검사항입니다.","점검사항입니다.","정답(옳지 않은 것). 윤활유 압력","점검사항입니다."],"t":"진동 = 볼트·위험회전수·압력 불균형"},"2020-3-직무일반-15":{"w":"기관이 갑자기 멈추는 것은 윤활유 압력 저하 트립, 비상정지 작동, 퀵클로징 밸브 동작 등 때문입니다. 과급기 오손은 출력 저하·배기온도 상승을 일으킬 뿐입니다.","x":["정답(옳지 않은 것). 과급기 오손","원인입니다.","원인입니다.","원인입니다."],"t":"과급기 오손 = 출력 저하"},"2020-3-직무일반-18":{"w":"소방원 장구는 방호복, 안전등, 방화 도끼, 호흡구 등입니다. 방진 마스크는 해당하지 않습니다.","x":["장구입니다.","장구입니다.","장구입니다.","정답(아닌 것). 방진 마스크"],"t":"소방원 장구 = 호흡구(방진 마스크 X)"},"2020-3-직무일반-19":{"w":"열식 화재탐지기는 약 54~78[℃]에서 작동합니다.","x":["틀립니다.","정답. 54~78℃","틀립니다.","틀립니다."],"t":"열식 = 54~78℃"},"2020-3-직무일반-22":{"w":"선박법은 국적, 등록, 톤수 측정 등을 정합니다. 감항성(검사)은 선박안전법 내용입니다.","x":["선박법입니다.","선박법입니다.","정답(아닌 것). 선박안전법","선박법입니다."],"t":"감항성 = 선박안전법"},"2020-3-직무일반-24":{"w":"소년선원은 2시간 연속 근로 후 즉시 15분 이상 쉬어야 합니다(출제 당시 기준).","x":["틀립니다.","정답. 2시간 후 15분","틀립니다.","틀립니다."],"t":"소년선원 = 2시간마다 15분"},"2020-3-직무일반-25":{"w":"기름 배출 시 신고 의무자는 선장, 발견자, 원인 행위자 등입니다. 선박 소유자는 신고 의무자로 규정되어 있지 않습니다(출제 기준).","x":["신고 의무자","신고 의무자","정답(아닌 것). 선박 소유자","신고 의무자"],"t":"신고 = 선장·행위자·발견자"},"2020-3-영어-1":{"w":"indicator card = 지압도(인디케이터 선도)로, 연소 상태를 살필 때 씁니다.","x":["틀립니다.","정답. 지압도","틀립니다.","틀립니다."],"t":"indicator card = 지압도"},"2020-3-영어-2":{"w":"태핏 간극은 틈새 게이지(thickness gauge)로 잽니다.","x":["바깥지름 측정","나사산 측정","금긋기","정답. Thickness gauge"],"t":"간극 = thickness gauge"},"2020-3-영어-4":{"w":"테스트 콕을 \"열고(Opened)\" \"공기운전(air running)\"을 했습니다.","x":["연료 운전이 아닙니다.","정답. Opened, air running","분해정비가 아닙니다.","분해정비가 아닙니다."],"t":"air running = 공기운전"},"2020-3-영어-6":{"w":"수트 블로어(그을음 제거기)는 보일러·이코노마이저 전열관의 그을음을 불어냅니다.","x":["관련이 적습니다.","관련이 없습니다.","관련이 없습니다.","정답. Economizer"],"t":"soot blower = 보일러·이코노마이저"},"2020-3-영어-7":{"w":"Refrigerant = 냉매입니다.","x":["정답. 냉매","refrigeration","cold storage","cooling"],"t":"refrigerant = 냉매"},"2020-3-영어-9":{"w":"\"주문하였다\" = Ordered 입니다.","x":["수급했다","정답. Ordered","이송했다","다시 채웠다"],"t":"order = 주문"},"2020-3-영어-10":{"w":"메거로 재는 것은 절연저항(insulation resistance)입니다.","x":["분사","정답. insulation","연소","냉동"],"t":"megger = 절연저항"},"2020-3-영어-11":{"w":"교류발전기 = Alternator 입니다.","x":["조타기","정답. Alternator","시동 전동기","전기자"],"t":"alternator = 교류발전기"},"2020-3-영어-13":{"w":"\"시스템유 압력을 0.5[MPa]로 조정했다\" = Regulated 입니다.","x":["보충했다","정답. Regulated","퍼냈다","전진시켰다"],"t":"regulate = 조정"},"2020-3-영어-15":{"w":"4행정 기관에서 가스는 배기(exhaust) 행정에서 배출됩니다.","x":["정답. exhaust","흡입","연소","압축"],"t":"exhaust stroke"},"2020-3-영어-19":{"w":"전기 점화로 운전하는 기관은 불꽃 점화(spark ignition) 기관입니다.","x":["디젤(압축 점화)입니다.","정답. spark ignition","소구기관입니다.","틀립니다."],"t":"전기 점화 = spark ignition"},"2020-3-영어-20":{"w":"standby feed pumps = 예비 급수펌프들 입니다.","x":["사용 중이 아닙니다.","사용 중·청수가 아닙니다.","정답. 예비 급수펌프","청수가 아닙니다."],"t":"standby = 예비, feed = 급수"},"2020-3-영어-23":{"w":"연료분사밸브 압력은 노즐 테스터(nozzle tester)로 점검합니다.","x":["길이 측정","정답. nozzle tester","압력계(일반)","진공계"],"t":"분사밸브 = nozzle tester"},"2020-3-영어-24":{"w":"상사점과 하사점 사이 거리는 행정(stroke)입니다.","x":["실린더 지름","정답. stroke","크랭크 변형","틈새"],"t":"TDC~BDC = stroke"},"2020-3-영어-25":{"w":"bore = 실린더의 지름(안지름)입니다.","x":["면적","반지름","부피","정답. 지름"],"t":"bore = 지름"},"2020-3-기관3-2":{"w":"전선 저항 R = ρ × ℓ ÷ S 입니다. 길이에 비례하고 단면적에 반비례합니다.","x":["정답. R = ρℓ/S","틀린 식입니다.","식을 풀면 ρℓ/S와 같지만, 공식 정답은 가)입니다.","틀린 식입니다."],"t":"R = ρℓ / S","c":"사)도 수학적으로는 같은 값이지만 공식 정답은 가)입니다."},"2020-4-기관1-11":{"w":"플런저가 압축을 시작해 분사밸브가 열리고 분사가 시작될 때까지의 시간 지연을 분사 늦음이라 합니다.","x":["분사 후 착화까지의 지연입니다.","실제 연료를 보내는 행정입니다.","정답. 분사 늦음","해당하지 않습니다."],"t":"분사 늦음 = 압축 시작 → 분사 시작"},"2020-4-기관1-14":{"w":"복수기는 터빈 배기를 냉각·응축해 물로 되돌리고 진공을 만들어 효율을 높입니다.","x":["정답. 배기의 응축","급수가열기입니다.","과열기입니다.","틀립니다."],"t":"복수기 = 배기 응축"},"2020-4-기관1-20":{"w":"속력이 일정하면 연료소비량은 배수량의 2/3 제곱에 비례합니다(애드미럴티 계수).","x":["틀립니다.","정답. 2/3 제곱","틀립니다.","속력과의 관계(3제곱)입니다."],"t":"연료 ∝ Δ^(2/3) × V³"},"2020-4-기관1-22":{"w":"저질중유는 점도가 높고, 유황분이 많으며, 발화성이 나쁘고, 유동점이 높습니다.","x":["정답(아닌 것). 유동점은 높습니다.","특성입니다.","특성입니다.","특성입니다."],"t":"저질유 = 유동점 높음"},"2020-4-기관1-24":{"w":"점도가 너무 높으면 유동 저항이 커져 시동이 곤란하고 마찰손실이 커집니다.","x":["점도가 낮을 때입니다.","내부 마찰은 커집니다.","유막은 두꺼워집니다.","정답. 시동 곤란"],"t":"점도 높음 = 시동 곤란"},"2020-4-기관2-1":{"w":"저압식 조수기는 진공으로 증발 온도를 낮춰 운전합니다. 증발 온도가 낮은 것은 정상 설계 조건이므로 생산량 감소 원인이 아닙니다. 스케일, 증발 압력 과다(진공 불량), 가열 부족은 원인입니다.","x":["원인입니다.","원인입니다.","원인입니다.","정답(옳지 않은 것). 저온 증발은 정상"],"t":"저압 조수기 = 진공 불량 시 감소"},"2020-4-기관2-4":{"w":"유압식 조종장치(텔레모터)는 작동이 신속·확실하고 설치면적이 작으며 작동유로 글리세린 혼합액도 씁니다. 소음이 큰 것은 특징이 아닙니다.","x":["정답(아닌 것). 소음이 크지 않습니다.","특징입니다.","특징입니다.","특징입니다."],"t":"유압 텔레모터 = 조용·신속"},"2020-4-기관2-13":{"w":"암모니아 누설은 유황초(흰 연기), 리트머스·페놀프탈레인 시험지(색 변화)로 찾습니다. 핼라이드 토치는 프레온 누설검사용입니다.","x":["암모니아용입니다.","암모니아용입니다.","정답(아닌 것). 프레온용","암모니아용입니다."],"t":"핼라이드 토치 = 프레온"},"2020-4-기관2-18":{"w":"쇠톱날 크기는 날을 끼우는 양쪽 구멍의 중심거리로 표시합니다.","x":["틀립니다.","틀립니다.","정답. 구멍 중심거리","틀립니다."],"t":"톱날 = 구멍 중심거리"},"2020-4-기관2-22":{"w":"2중저·선수·선미탱크는 밸러스트를 넣어 안정성·트림을 조절합니다. 빌지탱크는 폐수를 모으는 곳으로 직접 관계가 없습니다.","x":["관계있습니다.","관계있습니다.","정답(아닌 것). 빌지탱크","관계있습니다."],"t":"빌지탱크 = 폐수 저장"},"2020-4-기관2-25":{"w":"물·기름 배관의 연결과 작동 관계를 나타낸 도면은 계통도입니다.","x":["손으로 그린 도면입니다.","구조를 선으로 나타냅니다.","정답. 계통도","전기 배선입니다."],"t":"배관 흐름 = 계통도"},"2020-4-기관3-1":{"w":"I = Q ÷ t = 20 ÷ 10 = 2[A]입니다.","x":["거꾸로 나눈 값입니다.","정답. 2[A]","곱한 값입니다.","틀립니다."],"t":"I = Q / t"},"2020-4-기관3-2":{"w":"인덕턴스(코일)만의 회로에서는 전류가 전압보다 90° 뒤집니다. 전압 V를 기준으로 전류 I가 90° 아래(시계 방향)에 그려집니다.","x":["저항 회로(동상)입니다.","정답. I가 90° 뒤짐","콘덴서 회로(90° 앞섬)입니다.","R-L 회로입니다."],"t":"L = 전류 90° 뒤짐"},"2020-4-기관3-3":{"w":"최대값 = 실효값 × √2 입니다.","x":["정답. √2배","실효값/최대값입니다.","평균값/최대값입니다.","틀립니다."],"t":"Vm = √2 V"},"2020-4-기관3-4":{"w":"위쪽 2개 직렬 = 50[μF], 아래 4개 직렬 = 25[μF], 이 둘을 병렬로 합하면 75[μF]입니다.","x":["150[μF]입니다.","120[μF]입니다.","약 66.7[μF]입니다.","정답. 50 + 25 = 75[μF]"],"t":"직렬 n개 = C/n, 병렬 = 합"},"2020-4-기관3-6":{"w":"접속점에 들어오는 전류의 합과 나가는 전류의 합이 같다는 것은 키르히호프의 제1법칙(전류 법칙)입니다.","x":["V = IR입니다.","정답. 제1법칙","제2법칙은 전압 법칙입니다.","전류와 자기장입니다."],"t":"KCL = 제1법칙"},"2020-4-기관3-7":{"w":"μ(마이크로) = 10^-6 이므로 1[μA] = 10^-6[A]입니다.","x":["정답. 10^-6배","메가입니다.","킬로입니다.","틀립니다."],"t":"μ = 10^-6"},"2020-4-기관3-9":{"w":"정전용량 C = ε·A ÷ d 이므로 전극 간 거리가 멀수록 용량은 줄어듭니다.","x":["맞습니다.","맞습니다.","맞습니다.","정답(옳지 않은 것). 거리가 크면 감소"],"t":"C = εA/d"},"2020-4-기관3-10":{"w":"저항은 길이에 비례하고 단면적에 반비례합니다. R = ρ × ℓ ÷ A","x":["정답. ρℓ/A","틀립니다.","틀립니다.","틀립니다."],"t":"R = ρℓ/A"},"2020-4-기관3-11":{"w":"농형 유도전동기는 회전자가 단락된 도체 막대(농형)라 브러시가 없습니다.","x":["정답. 농형 유도전동기","브러시 있음","슬립링·브러시 있음","브러시 있음"],"t":"농형 = 브러시 없음"},"2020-4-기관3-13":{"w":"직권전동기는 시동 토크가 매우 커서 시동용 전동기(셀 모터)에 알맞습니다.","x":["정속도(유도)가 알맞습니다.","유도전동기입니다.","정답. 시동용 전동기","해당하지 않습니다."],"t":"직권 = 큰 시동 토크"},"2020-4-기관3-15":{"w":"공칭전압은 납축전지 2[V], 알칼리 축전지 1.2[V]입니다.","x":["틀립니다.","틀립니다.","정답. 2[V], 1.2[V]","반대입니다."],"t":"납 2V, 알칼리 1.2V"},"2020-4-기관3-20":{"w":"소수 캐리어는 P형의 전자, N형의 정공입니다.","x":["다수 캐리어입니다.","틀립니다.","틀립니다.","정답. P형 전자, N형 정공"],"t":"소수 = 반대 부호"},"2020-4-기관3-21":{"w":"NPN에서 베이스-이미터는 순방향이므로 베이스(P)가 이미터(N)보다 높습니다. 즉 이미터는 베이스보다 부(-)전위입니다.","x":["정답. 부전위","반대입니다.","틀립니다.","틀립니다."],"t":"NPN: E < B < C"},"2020-4-기관3-25":{"w":"PNP는 컬렉터(P)-베이스(N)-이미터(P) 구조입니다. 다이오드 화살표는 P→N 방향이므로 컬렉터와 이미터에서 모두 베이스 쪽을 향합니다.","x":["정답. 두 화살표가 베이스 쪽으로","틀립니다.","NPN입니다.","틀립니다."],"t":"PNP = 화살표가 베이스로"},"2020-4-직무일반-2":{"w":"입항한 외국선박의 협약 준수를 항만국 정부가 직접 확인하는 검사는 PSC(항만국통제)입니다.","x":["선급협회 검사입니다.","선박안전법상 검사입니다.","정답. PSC","해당하지 않습니다."],"t":"PSC = 항만국통제"},"2020-4-직무일반-5":{"w":"실린더 커버 분해·조립에는 체인블록, 아이볼트, 토크렌치를 씁니다. 디플렉션 게이지는 크랭크축 개폐 측정용입니다.","x":["필요합니다.","정답(아닌 것). 디플렉션 게이지","필요합니다.","필요합니다."],"t":"디플렉션 게이지 = 크랭크축"},"2020-4-직무일반-12":{"w":"환자관리 3대 원칙은 자세, 보온, 음료수(수분)입니다. 약물은 해당하지 않습니다.","x":["정답(아닌 것). 약물","원칙입니다.","원칙입니다.","원칙입니다."],"t":"자세·보온·음료수"},"2020-4-직무일반-15":{"w":"메인 베어링 과열 때는 기관을 서서히 감속하면서 윤활유 공급을 늘려 냉각합니다. 급정지하면 베어링이 소착될 수 있습니다(출제 기준).","x":["정답. 서서히 감속 + 윤활유 증량","급정지는 소착 위험","압력을 낮추면 안 됩니다.","적절하지 않습니다."],"t":"베어링 과열 = 서서히 감속","c":"다른 회차에서는 \"즉시 정지 후 윤활유 펌프 계속 운전\"을 정답으로 한 문제도 있어, 문제 문구를 잘 보세요."},"2020-4-직무일반-16":{"w":"원격제어가 고장나면 주기관 옆(기기 측, 기측)에서만 수동으로 조종할 수 있습니다.","x":["원격 장소입니다.","정답. 기기 측","조타기 조종 장소입니다.","원격 장소입니다."],"t":"원격 고장 = 기측 조종"},"2020-4-직무일반-18":{"w":"국제육상시설연결구와 함께 볼트·너트, 개스킷, 와셔를 비치합니다. 리듀서는 해당하지 않습니다.","x":["비치합니다.","비치합니다.","정답(아닌 것). 리듀서","비치합니다."],"t":"국제육상연결구 = 볼트·너트·개스킷·와셔"},"2020-4-영어-3":{"w":"절연저항은 메거(Megger)로 잽니다.","x":["전류 측정","전류 측정","전압 측정","정답. Megger"],"t":"절연저항 = megger"},"2020-4-영어-5":{"w":"\"실린더 커버 손상으로 2번 실린더의 연료를 차단했다\" = Cut off 입니다.","x":["공급했다","점검했다","정답. Cut off","시험했다"],"t":"cut off = 차단"},"2020-4-영어-9":{"w":"피스톤을 빼려면 실린더 커버(cylinder cover)를 엽니다.","x":["정답. cylinder cover","라이너","연접봉","배기밸브"],"t":"커버 열고 피스톤 발출"},"2020-4-영어-12":{"w":"\"저위 시체스트의 그레이팅을 떼어내고(Removed) 청소했다.\"","x":["조정했다","측정했다","정답. Removed","다시 감았다"],"t":"remove = 떼어내다"},"2020-4-영어-14":{"w":"증기압축 냉동장치의 4대 요소는 압축기, 응축기, 팽창밸브, 증발기입니다. cooler는 아닙니다.","x":["정답(아닌 것). cooler","요소입니다.","요소입니다.","요소입니다."],"t":"압축 → 응축 → 팽창 → 증발"},"2020-4-영어-18":{"w":"프로펠러 추력을 추력 베어링으로 전하는 축은 추력축(thrust shaft)입니다.","x":["캠축","크랭크축","프로펠러축(추력의 출발점)","정답. thrust shaft"],"t":"thrust shaft"},"2020-4-영어-19":{"w":"선체 내부를 세로로 나누어 수밀 구획을 만드는 것은 격벽(bulkhead)입니다.","x":["정답. Bulkheads","갑판","이중저 탱크","선수루 갑판"],"t":"bulkhead = 격벽"},"2020-4-영어-20":{"w":"계통에서 수분을 제거하는 장치는 dehydrator(건조기)입니다.","x":["감압밸브","정답. dehydrator","공기 주입기","트랩"],"t":"dehydrator = 건조기"},"2020-4-영어-23":{"w":"4행정 디젤기관은 압축 끝~팽창 사이 공기 속에 연료유(fuel oil)를 분사합니다.","x":["틀립니다.","정답. fuel oil","틀립니다.","틀립니다."],"t":"분사 = fuel oil"},"2021-1-기관1-1":{"w":"기관을 시동하면 윤활유 온도가 올라 점도가 낮아지고, 점도가 낮아지면 윤활유 압력도 낮아집니다. '점도가 높아진다'는 설명이 틀렸습니다.","x":["맞는 설명입니다(출제 기준).","정답(옳지 않은 것). 시동 후 온도가 오르면 점도는 낮아집니다.","배기밸브는 고온 가스에 노출되어 빨리 손상됩니다.","실린더와 베드를 잇는 부분이 프레임입니다."],"t":"온도↑ → 점도↓ → 유압↓"},"2021-1-기관1-2":{"w":"크랭크가 어느 위치에 있어도 시동공기로 시동하려면 항상 어느 한 실린더가 작동행정 위치에 있어야 합니다. 이를 위해 최소 2행정은 4실린더, 4행정은 6실린더가 필요합니다.","x":["4행정이 틀립니다.","정답. 2행정 4, 4행정 6","반대입니다.","2행정이 틀립니다."],"t":"공기 시동 최소 = 2행정 4, 4행정 6"},"2021-1-기관1-4":{"w":"가장 위쪽 링은 가장 뜨거워 많이 늘어나므로 상부 링의 틈새를 하부 링보다 크게 합니다.","x":["정답(옳지 않은 것). 상부 링 틈새를 크게 합니다.","맞습니다.","맞습니다.","맞습니다."],"t":"링 틈새 = 위쪽일수록 크게"},"2021-1-기관1-5":{"w":"피스톤링 플러터는 링이 링 홈 안에서 떨리는 현상으로, 피스톤 속도가 빠를 때(고속 회전) 관성력 때문에 잘 생깁니다. 링이 가볍고 장력이 크면 줄어듭니다.","x":["속도가 느리면 잘 생기지 않습니다.","가벼우면 줄어듭니다.","정답. 피스톤 속도가 빠를 때","장력이 크면 줄어듭니다."],"t":"플러터 = 고속에서 발생"},"2021-1-기관1-7":{"w":"크랭크암 개폐량 측정은 축의 일직선 상태, 메인 베어링 편마멸 확인, 크랭크축 절손 예방을 위해 합니다. 출력 계산과는 관계없습니다.","x":["정답(아닌 것). 출력 계산","목적입니다.","목적입니다.","목적입니다."],"t":"디플렉션 = 축심·베어링 확인"},"2021-1-기관1-9":{"w":"크랭크핀 볼트는 베어링을 조이기 위해 인장응력을 받습니다(볼트를 당겨 조임). 배기 때의 관성력은 인장력을 더하고, 굽힘응력도 받으며, 강인한 단강·니켈크롬강으로 만듭니다.","x":["맞습니다.","정답(옳지 않은 것). 볼트는 인장응력을 받습니다.","맞습니다.","맞습니다."],"t":"크랭크핀 볼트 = 인장응력"},"2021-1-기관1-10":{"w":"출력이 줄어드는 원인은 분사밸브 막힘, 피스톤링 고착(압축 누설), 연료펌프 누설 등입니다. 냉각수 온도 상승(정상 범위)은 출력 감소의 원인이 아닙니다.","x":["원인입니다.","원인입니다.","원인입니다.","정답(아닌 것). 냉각수 온도 상승"],"t":"출력↓ = 연료·압축 불량"},"2021-1-기관1-11":{"w":"과급의 주된 목적은 공기를 많이 넣어 기관 출력을 늘리는 것입니다.","x":["착화지연은 짧아집니다.","회전수와 관계없습니다.","목적이 아닙니다.","정답. 출력 증가"],"t":"과급 = 출력↑"},"2021-1-기관1-12":{"w":"점화 전에 노 안의 폭발성 가스를 송풍기로 배출(프리퍼지)하면 역화를 막을 수 있습니다.","x":["역화와 관계없습니다.","역화와 관계없습니다.","정답. 폭발성 가스 배제","역화와 관계없습니다."],"t":"역화 방지 = 프리퍼지"},"2021-1-기관1-13":{"w":"회전식(로터리) 버너는 고속 회전하는 컵의 원심력으로 기름을 무화하므로 연료 압력이 가장 낮아도 됩니다.","x":["정답. 회전식 버너","압력 분무식은 고압이 필요합니다.","증기로 무화합니다.","공기로 무화합니다."],"t":"회전식 버너 = 저압 연료"},"2021-1-기관1-14":{"w":"증기터빈의 노즐은 증기를 팽창시켜 열에너지를 속도에너지로 바꿉니다.","x":["로터는 회전체입니다.","블레이드는 속도에너지를 회전력으로 바꿉니다.","정답. 노즐","더미 피스톤은 추력 평형 장치입니다."],"t":"노즐 = 열 → 속도"},"2021-1-기관1-15":{"w":"충동터빈은 길이가 짧고 작으며, 고온·고압 증기를 쓸 수 있고, 노즐 수로 증기량을 조절할 수 있습니다. 저압부에서 효율이 좋은 것은 반동터빈의 장점입니다.","x":["장점입니다.","장점입니다.","정답(아닌 것). 반동터빈의 장점입니다.","장점입니다."],"t":"충동 = 고압부, 반동 = 저압부 유리"},"2021-1-기관1-17":{"w":"감속장치는 기관 회전수를 줄여 프로펠러 효율을 높이며, 주로 중·고속 기관에 씁니다. 대형 저속기관은 프로펠러에 직결하므로 감속장치가 없습니다.","x":["맞습니다.","맞습니다.","맞습니다.","정답(옳지 않은 것). 대형 저속기관은 직결입니다."],"t":"저속기관 = 직결, 중·고속 = 감속기"},"2021-1-기관1-19":{"w":"프로펠러 재료는 피로강도·인장강도가 크고 침식에 강해야 합니다. 아연이 많으면 탈아연 부식이 생기므로 적어야 합니다.","x":["조건입니다.","조건입니다.","조건입니다.","정답(아닌 것). 아연이 많으면 탈아연 부식"],"t":"프로펠러 = 아연 적게"},"2021-1-기관1-20":{"w":"추진기가 물에 대해 실제로 유효하게 작용한 동력은 추진(추력) 마력입니다.","x":["제동 마력은 기관 출력입니다.","전달 마력은 프로펠러에 전달된 마력입니다.","정답. 추진 마력","유효 마력은 선체를 예인하는 마력입니다."],"t":"BHP → DHP → THP(추진) → EHP"},"2021-1-기관1-22":{"w":"중유의 바나듐(V)은 연소해 저융점 산화물이 되어 배기밸브 등 고온부를 부식시킵니다(고온부식). 황은 저온부식의 원인입니다.","x":["칼륨이 아닙니다.","마그네슘은 부식 억제제로 씁니다.","황은 저온부식입니다.","정답. 바나듐"],"t":"고온부식 = V, 저온부식 = S"},"2021-1-기관1-23":{"w":"점도가 높으면 유막은 두꺼워지지만 마찰 저항(점성 저항)은 커집니다.","x":["정답(옳지 않은 것). 점도가 높으면 마찰 저항이 커집니다.","맞습니다.","맞습니다.","맞습니다."],"t":"고하중 = 고점도, 고속 = 저점도"},"2021-1-기관1-25":{"w":"윤활유 첨가제는 산화 방지제, 청정 분산제, 유성 향상제, 유동점 강하제, 점도지수 향상제 등입니다.","x":["정답.","촉진제·강하제·상승제는 틀립니다.","일부가 틀립니다.","촉진제·강하제가 틀립니다."],"t":"첨가제 = 방지·분산·향상·강하"},"2021-1-기관2-1":{"w":"원심펌프는 회전차(임펠러)의 원심력으로 물을 보냅니다.","x":["정답. 원심력","양력은 축류펌프의 원리입니다.","축류펌프입니다.","마찰력이 아닙니다."],"t":"원심펌프 = 원심력"},"2021-1-기관2-2":{"w":"관 안에서 프로펠러 모양 회전차가 돌며 액체를 축 방향으로 보내는 펌프는 축류펌프입니다.","x":["정답. 축류펌프","원심펌프는 반지름 방향입니다.","왕복펌프가 아닙니다.","회전펌프가 아닙니다."],"t":"축류펌프 = 축 방향 흐름"},"2021-1-기관2-3":{"w":"플래시식 조수장치에서 가열용 증기 압력이 높으면 오리피스로 감압합니다.","x":["이젝터는 진공을 만듭니다.","증발기가 아닙니다.","정답. 오리피스","기수분리기는 물방울을 분리합니다."],"t":"오리피스 = 감압"},"2021-1-기관2-8":{"w":"조타 신호를 동력장치(원동기)에 전달하는 것은 조종장치(텔레모터 등)입니다.","x":["원동기는 동력을 냅니다.","추종장치는 타를 명령 각도에 멈춥니다.","정답. 조종장치","타장치는 타입니다."],"t":"조종장치 = 신호 전달"},"2021-1-기관2-10":{"w":"기름의 부상속도는 기름 입자가 클수록, 물과 기름의 밀도 차가 클수록 빨라집니다. 밀도 차를 작게 하면 느려집니다.","x":["경계면을 크게 하면 좋습니다.","응집제는 입자를 키웁니다.","부피가 크면 빨라집니다.","정답(옳지 않은 것). 밀도 차는 커야 합니다."],"t":"부상속도 ∝ 밀도차 × 지름²"},"2021-1-기관2-11":{"w":"암모니아는 구리 합금을 부식시키고, 공기 중에 약 16~25[%] 섞이면 폭발할 수 있습니다.","x":["CO₂는 불연성입니다.","아황산가스가 아닙니다.","프레온은 불연성입니다.","정답. 암모니아"],"t":"암모니아 = 폭발성·동 부식"},"2021-1-기관2-12":{"w":"언로더 피스톤은 송출가스 또는 윤활유 압력으로 작동합니다.","x":["정답. 송출가스 또는 윤활유","흡입가스가 아닙니다.","틀립니다.","틀립니다."],"t":"언로더 = 유압"},"2021-1-기관2-14":{"w":"냉매 유량은 압축기 언로더(용량 제어), 증발압력 조정밸브, 팽창밸브로 조절합니다. 윤활 장치의 유량으로는 조절하지 않습니다.","x":["조절 방법입니다.","조절 방법입니다.","조절 방법입니다.","정답(아닌 것). 윤활유량"],"t":"냉매 유량 = 팽창밸브·언로더"},"2021-1-기관2-15":{"w":"공기조화는 온도, 습도, 기류(유속), 청정도를 조절합니다. 압력은 조절하지 않습니다.","x":["기능입니다.","기능입니다.","기능입니다.","정답(아닌 것). 압력"],"t":"공조 = 온도·습도·기류·청정도"},"2021-1-기관2-19":{"w":"바이트는 돌출 거리를 짧게 하고, 심은 적게(되도록 1장) 써서 흔들리지 않게 고정합니다.","x":["심은 적게 씁니다.","정답. 돌출 거리를 짧게","심은 바이트 전체 면에 닿게 합니다.","필요하면 넣습니다."],"t":"바이트 = 짧게, 심은 적게"},"2021-1-기관2-21":{"w":"선도(line drawing)는 선체를 길이·나비·깊이 방향으로 자른 단면선을 나타내 선체의 모양을 보여 줍니다.","x":["정답. 선도","일반배치도는 구획 배치입니다.","외판전개도는 외판을 펼친 그림입니다.","기관실 배치도입니다."],"t":"선도 = 선체 곡면 형상"},"2021-1-기관2-22":{"w":"횡강력재는 늑골, 늑판, 갑판보 등입니다. 용골은 종강력재입니다.","x":["정답(아닌 것). 용골은 종강력재","횡강력재입니다.","횡강력재입니다.","횡강력재입니다."],"t":"용골 = 종강력재"},"2021-1-기관2-23":{"w":"구상선수(벌버스 바우)는 선수에서 생기는 파도를 상쇄해 조파저항을 줄입니다.","x":["마찰저항이 아닙니다.","공기저항이 아닙니다.","정답. 조파저항","조와저항이 아닙니다."],"t":"구상선수 = 조파저항↓"},"2021-1-기관2-24":{"w":"부분 단면도의 파단선은 자유 실선(손으로 그린 불규칙한 가는 실선)으로 긋습니다.","x":["가상선입니다.","숨은선입니다.","중심선입니다.","정답. 자유실선"],"t":"파단선 = 자유 실선"},"2021-1-기관3-2":{"w":"전체 2[kW]를 1,000[V]로 쓰므로 I = 2[A]. 1[Ω]의 전압강하 = 2 × 1 = 2[V], 소비전력 = 2² × 1 = 4[W]입니다.","x":["틀립니다.","틀립니다.","전력이 틀립니다.","정답. 2[V], 4[W]"],"t":"P = I²R"},"2021-1-기관3-5":{"w":"e = Em sin(ωt − θ) 에서 괄호 안의 (ωt − θ)가 시간 t에서의 위상입니다.","x":["부호가 틀립니다.","정답. ωt − θ","각속도입니다.","초기 위상입니다."],"t":"위상 = sin 괄호 안"},"2021-1-기관3-6":{"w":"NAND(와 NOR)는 한 종류만으로 AND, OR, NOT 등 모든 논리를 만들 수 있는 만능 게이트입니다.","x":["OR만으로는 NOT을 못 만듭니다.","정답. NAND","XOR는 만능이 아닙니다.","AND만으로는 NOT을 못 만듭니다."],"t":"만능 게이트 = NAND·NOR"},"2021-1-기관3-8":{"w":"한시동작 순시복귀 접점(ON 딜레이)은 접점 위에 위로 향한 삼각형(∧)이 있는 기호입니다.","x":["정답. ∧ 표시 = 한시동작","다른 접점입니다.","일반 a접점입니다.","일반 b접점입니다."],"t":"∧ = 한시동작, ∨ = 한시복귀"},"2021-1-기관3-9":{"w":"동기속도 = 120 × 60 ÷ 6 = 1,200[rpm]이고, 부하 운전 중에는 슬립 때문에 약간 느린 1,145[rpm] 정도가 됩니다.","x":["정답. 1,145[rpm]","동기속도입니다(부하 운전 불가).","4극에 가깝습니다.","4극 동기속도입니다."],"t":"부하 시 = 동기속도보다 약간 느림"},"2021-1-기관3-10":{"w":"농형 유도전동기 기동법은 직입, 리액터, Y-△, 기동보상기 기동법입니다. 2차 저항 기동법은 권선형 전동기의 기동법입니다.","x":["농형 기동법입니다.","정답(아닌 것). 2차 저항은 권선형","농형 기동법입니다.","농형 기동법입니다."],"t":"2차 저항 = 권선형"},"2021-1-기관3-12":{"w":"AVR은 계자(여자)전류를 조정해 발전기 전압을 일정하게 유지합니다.","x":["극수는 고정입니다.","주파수는 거버너가 조정합니다.","정답. 여자전류 조정","속도는 거버너가 조정합니다."],"t":"AVR = 여자전류"},"2021-1-기관3-13":{"w":"절연저항은 온도와 관계없이 항상 클수록 좋습니다.","x":["작으면 누전됩니다.","틀립니다.","틀립니다.","정답. 모두 큰 것이 좋다"],"t":"절연저항 = 클수록 좋음"},"2021-1-기관3-15":{"w":"3상 유도전동기 고정자에 3상 전류가 흐르면 회전자계가 생깁니다.","x":["정답. 회전자계","단상입니다.","틀립니다.","틀립니다."],"t":"3상 = 회전자계"},"2021-1-기관3-16":{"w":"코일 피치를 극 피치보다 짧게 감는 것을 단절권이라 합니다(고조파 감소). 같게 감는 것은 전절권입니다.","x":["중권은 권선 방식입니다.","파권은 권선 방식입니다.","전절권은 코일 피치 = 극 피치","정답. 단절권"],"t":"단절권 = 코일 피치 < 극 피치"},"2021-1-기관3-18":{"w":"그림은 88F(정회전)와 88R(역회전)을 쓰는 정·역회전 회로입니다. 88F-a, 88R-a는 자기유지, 88R-b, 88F-b는 인터록 접점이며, THR-b는 과전류 시 열동계전기가 자동으로 열어 회로를 끊습니다.","x":["정·역회전 회로입니다.","a접점은 자기유지용입니다.","b접점은 인터록용입니다.","정답. THR-b는 과전류 시 자동 동작"],"t":"정역 회로 = a접점 자기유지, b접점 인터록"},"2021-1-기관3-20":{"w":"다이오드에서 P형 쪽 단자는 애노드, N형 쪽 단자는 캐소드입니다.","x":["P형 쪽입니다.","정답. 캐소드","트랜지스터 단자입니다.","트랜지스터 단자입니다."],"t":"P = 애노드, N = 캐소드"},"2021-1-기관3-21":{"w":"맥동 직류를 평탄하게 만드는 회로는 콘덴서를 쓴 평활회로(R-C 평활회로 등)입니다.","x":["정류회로입니다.","저항만으로는 평활이 안 됩니다.","정류회로입니다.","정답. R-C 평활회로"],"t":"평활 = C 사용"},"2021-1-기관3-23":{"w":"역방향 항복 현상으로 전압을 일정하게 유지하는 소자는 제너 다이오드입니다.","x":["틀립니다.","정답. 제너 다이오드","가변용량은 전압에 따라 용량이 변합니다.","터널은 부성저항을 씁니다."],"t":"제너 = 정전압"},"2021-1-기관3-24":{"w":"G(게이트), D(드레인), S(소스) 단자를 가진 기호는 FET(전계효과 트랜지스터)입니다.","x":["BJT는 B·C·E 단자입니다.","SCR은 A·K·G입니다.","정답. FET","UJT는 E·B1·B2입니다."],"t":"FET = G·D·S"},"2021-1-직무일반-3":{"w":"가스 중독 예방은 환기, 2인 이상 작업, 감시원 배치입니다. 탱크 안에 가연성 가스를 넣는 것은 폭발 위험을 키웁니다.","x":["맞습니다.","맞습니다.","맞습니다.","정답(옳지 않은 것). 가연성 가스 공급은 위험합니다."],"t":"탱크 진입 = 환기·2인·감시원"},"2021-1-직무일반-4":{"w":"PSC(항만국 통제)의 기준 미달선은 감항성이 확보되지 않았거나 승선자가 위험한 경우, 정비 불량으로 장비 성능이 크게 떨어진 경우입니다.","x":["틀립니다.","틀립니다.","틀립니다.","정답. ③, ④"],"t":"기준 미달선 = 감항성·장비 불량"},"2021-1-직무일반-6":{"w":"HCFC 냉매 장치의 팽창밸브를 교환하려면 냉매 배관을 열어야 하므로 오존층파괴물질(냉매)이 샐 수 있습니다.","x":["해당 없습니다.","제상은 냉매 계통을 열지 않습니다.","정답. 팽창밸브 교환","냉각관 소제는 냉각수 쪽입니다."],"t":"냉매 계통 개방 = ODS 누설"},"2021-1-직무일반-7":{"w":"연료유 이송·수급·측심 실수는 선외 유출로 이어질 수 있습니다. 기관실 안 윤활유 여과기 소제는 기관실 안에서 끝나는 작업입니다.","x":["유출 가능 작업입니다.","유출 가능 작업입니다.","유출 가능 작업입니다.","정답(아닌 것). 여과기 소제"],"t":"유출 위험 = 이송·수급"},"2021-1-직무일반-8":{"w":"일산화탄소(CO)는 헤모글로빈과 산소보다 훨씬 강하게 결합해 적은 양으로도 산소 운반을 막습니다.","x":["정답. 일산화탄소","이산화탄소가 아닙니다.","미연탄화수소가 아닙니다.","이산화질소가 아닙니다."],"t":"CO = 헤모글로빈 결합"},"2021-1-직무일반-9":{"w":"호기성 박테리아로 유기물을 분해하는 오수처리 방식은 미생물(생물학적) 분해식입니다.","x":["저장 분쇄식이 아닙니다.","정답. 미생물 분해식","염소 순환식은 화학식입니다.","틀립니다."],"t":"오수처리 = 호기성 미생물"},"2021-1-직무일반-11":{"w":"성인에게 하루에 필요한 수분은 약 2,000[cc](2리터)입니다.","x":["부족합니다.","부족합니다.","부족합니다.","정답. 약 2,000[cc]"],"t":"하루 수분 ≒ 2L"},"2021-1-직무일반-12":{"w":"의식이 없는 환자에게 음료를 주면 기도로 넘어가 질식할 수 있습니다.","x":["수분을 줍니다.","상황에 따라 다릅니다.","줄 수 있습니다.","정답. 의식이 없는 환자"],"t":"무의식 = 음료 금지"},"2021-1-직무일반-13":{"w":"더운 찜질은 혈관을 넓혀 통증과 근육 경련을 완화하고 화농을 촉진합니다. 혈관을 수축시키는 것은 냉찜질입니다.","x":["목적입니다.","정답(아닌 것). 혈관 수축은 냉찜질","목적입니다.","목적입니다."],"t":"온찜질 = 혈관 확장, 냉찜질 = 수축"},"2021-1-직무일반-14":{"w":"침수 방지는 빌지 변화 관찰, 배수설비 정비, 해수관 부식 점검 등입니다. 냉각해수 밸브를 최소로 여는 것은 냉각 부족을 일으키며 침수 방지책이 아닙니다.","x":["맞습니다.","맞습니다.","맞습니다.","정답(옳지 않은 것). 냉각수 밸브 최소 개방"],"t":"침수 방지 = 빌지 감시·해수관 점검"},"2021-1-직무일반-15":{"w":"시동공기로 돌려도 회전하지 않으면 공기 압력, 시동밸브 누설, 시동 관제(분배)밸브 등 시동공기 계통을 점검합니다. 연료분사펌프는 회전한 뒤 착화와 관계됩니다.","x":["점검합니다.","점검합니다.","정답(옳지 않은 것). 연료펌프는 회전 불량과 관계없습니다.","점검합니다."],"t":"회전 안 됨 = 시동공기 계통"},"2021-1-직무일반-16":{"w":"정전 시에는 원인 파악, 예비발전기 기동·ACB 투입, 선교 통보를 합니다. 조타기 2대 운전은 전원이 복구된 뒤 필요에 따라 하는 것이지 정전 중 조치가 아닙니다.","x":["맞습니다.","맞습니다.","맞습니다.","정답(옳지 않은 것)."],"t":"정전 = 원인·예비발전기·선교 통보"},"2021-1-직무일반-17":{"w":"조타장치는 최대 전진 속력에서 한쪽 35°부터 반대쪽 35°까지 돌릴 수 있어야 하고, 35°에서 반대쪽 30°까지 28초 이내에 돌려야 합니다.","x":["틀립니다.","틀립니다.","틀립니다.","정답. 35°, 28초"],"t":"35° → 반대 30° = 28초"},"2021-1-직무일반-19":{"w":"기관구역 소화호스는 지름 40[mm], 최대 길이 15[m]입니다(갑판은 20[m]).","x":["길이가 틀립니다.","정답. 40[mm], 15[m]","틀립니다.","틀립니다."],"t":"기관실 소화호스 = 40mm·15m"},"2021-1-직무일반-21":{"w":"스프링클러에 물을 즉시 공급하기 위해 압력탱크를 둡니다.","x":["위생펌프가 아닙니다.","정답. 압력탱크","소화약제탱크가 아닙니다.","팽창탱크가 아닙니다."],"t":"스프링클러 = 압력탱크"},"2021-1-직무일반-24":{"w":"폐기물 소각 시 폐기물기록부에는 선박 위치, 소각 시작·종료 일시, 소각량 등을 기록합니다. 기름 소모량은 기록하지 않습니다.","x":["기록합니다.","기록합니다.","정답(아닌 것). 기름 소모량","기록합니다."],"t":"소각 기록 = 위치·시간·양"},"2021-1-직무일반-25":{"w":"분뇨오염방지설비 대상은 최대 승선인원 16명 이상 선박, 400톤 이상 선박 등이며, 어선도 16명 이상이 기준입니다.","x":["맞습니다.","정답(옳지 않은 것). 15명이 아니라 16명","맞습니다.","맞습니다."],"t":"분뇨설비 = 16인 이상"},"2021-1-영어-1":{"w":"\"2번 실린더 커버를 열고(opened) 피스톤을 꺼냈다(took out).\"","x":["정답. Opened, took out","조립하고 꺼낼 수 없습니다.","피스톤을 닫을 수 없습니다.","틀립니다."],"t":"take out = 꺼내다"},"2021-1-영어-2":{"w":"\"주기관을 2시간 동안 워밍업(난기)했다.\" warm up = 데우다.","x":["정답. Warmed","다시 채웠다","줄였다","조정했다"],"t":"warm up = 난기"},"2021-1-영어-4":{"w":"기관 출력은 [kW]로 나타냅니다.","x":["전력량입니다.","일의 단위입니다.","회전수입니다.","정답. kW"],"t":"출력 = kW"},"2021-1-영어-5":{"w":"주기관의 효율적인 운전을 책임지는 사람은 1등 기관사(1st engineer)입니다.","x":["정답. 1st engineer","2기사는 발전기·연료입니다.","3기사는 보조기기입니다.","실습 기관사입니다."],"t":"1기사 = 주기관"},"2021-1-영어-7":{"w":"Hydraulic control system = 유압제어장치입니다.","x":["전기가 아닙니다.","전자가 아닙니다.","정답. 유압제어장치","공기압은 pneumatic입니다."],"t":"hydraulic = 유압"},"2021-1-영어-9":{"w":"하루는 자정부터 4시간씩 6개의 당직 시간으로 나눕니다.","x":["정답. four","틀립니다.","틀립니다.","틀립니다."],"t":"당직 = 4시간씩"},"2021-1-영어-10":{"w":"프로펠러축이 지나가는 관은 stern tube(선미관)입니다.","x":["덕트가 아닙니다.","틀립니다.","정답. stern tube","틀립니다."],"t":"stern tube = 선미관"},"2021-1-영어-11":{"w":"배 밑바닥에 고인 물(빌지)을 빼는 펌프는 bilge pump입니다.","x":["소화 펌프","급수 펌프","화물 펌프","정답. bilge pump"],"t":"bilge pump"},"2021-1-영어-16":{"w":"배기가스 속 오염물질(pollutants)에 해당하는 것은 NOx(질소산화물)입니다.","x":["물은 오염물질이 아닙니다.","산소는 오염물질이 아닙니다.","수소가 아닙니다.","정답. NOx"],"t":"pollutants = NOx·SOx·CO"},"2021-1-영어-17":{"w":"배를 조종하는 장치는 rudder(타)입니다.","x":["윈치","조속기","정답. rudder","발전기"],"t":"rudder = 타"},"2021-1-영어-19":{"w":"메거는 절연(insulation) 저항을 재는 기구입니다.","x":["틀립니다.","정답. insulation","틀립니다.","틀립니다."],"t":"megger = insulation resistance"},"2021-1-영어-20":{"w":"배관의 역류를 막는 것은 Check valves입니다.","x":["스톱밸브","정답. Check valves","글로브 밸브","나비밸브"],"t":"check valve = 역류 방지"},"2021-1-영어-21":{"w":"\"과열기(superheater)는 주로 증기 속의 수분을 없애는 데 쓴다.\" 포화증기를 더 가열해 건조한 과열증기로 만듭니다.","x":["연료 가열이 아닙니다.","급수 가열은 절탄기입니다.","압력은 높이지 않습니다.","정답. remove moisture from steam"],"t":"superheater = 수분 제거·과열"},"2021-1-영어-24":{"w":"기름이 선외로 배출되는 것을 막으려면 15[ppm] 기름여과장치가 필요합니다.","x":["소각기","청정기","정답. 15[ppm] oil filtering equipment","자동 역세 여과기"],"t":"선외 기름 방지 = 기름여과장치"},"2021-1-영어-25":{"w":"뜨겁고 찬 정도를 재는 도구는 Thermometer(온도계)입니다.","x":["습도계","정답. Thermometer","열량계","염분계"],"t":"thermometer = 온도계"},"2021-2-기관1-3":{"w":"피스톤핀 보스부는 열팽창으로 핀이 끼이지 않도록 핀과 직각 방향의 열팽창이 작아야(또는 여유가 있게 설계) 합니다. 열팽창이 커야 한다는 것은 틀립니다.","x":["맞습니다.","맞습니다.","정답(옳지 않은 것). 보스부 열팽창은 작아야 합니다.","맞습니다."],"t":"피스톤 = 열팽창 작게"},"2021-2-기관1-4":{"w":"크랭크암 개폐량이 허용치를 넘으면 기관 베드 변형, 베드 조립너트 풀림, 메인 베어링 틈새(마멸) 등을 점검합니다. 캠축 변형은 관계가 없습니다.","x":["정답(옳지 않은 것). 캠축은 관계없습니다.","점검합니다.","점검합니다.","점검합니다."],"t":"디플렉션 과대 = 베드·메인 베어링 점검"},"2021-2-기관1-6":{"w":"과급기관은 평균유효압력이 높고, 연료소비율이 작으며, 저질 연료도 쓰기 쉽습니다. 시동할 때는 과급기가 돌지 않아 시동성이 좋아지지 않습니다.","x":["장점입니다.","장점입니다.","정답(아닌 것). 시동성은 좋아지지 않습니다.","장점입니다."],"t":"과급 ≠ 시동성 향상"},"2021-2-기관1-11":{"w":"유압조속기의 보상조절 니들밸브를 너무 많이 열면 회전수가 오르내리는 헌팅(난조)이 생깁니다.","x":["정답. 헌팅","틀립니다.","반대입니다.","틀립니다."],"t":"니들밸브 과다 개방 = 헌팅"},"2021-2-기관1-12":{"w":"상당 증발량은 실제 증발량을 100[℃] 물을 100[℃] 증기로 만드는 양으로 환산한 것으로, Ge = G × (증기 엔탈피 − 급수 엔탈피) ÷ 539 입니다.","x":["정답. G(i1 − i0)/539","부호가 반대입니다.","틀립니다.","틀립니다."],"t":"상당증발량 = G(i1 − i0) / 539"},"2021-2-기관1-15":{"w":"복수기 진공은 냉각수 부족, 공기 침입, 드레인 배출 불량의 직접 영향을 받습니다. 급수처리는 보일러수 수질 문제로 진공과 직접 관계가 없습니다.","x":["영향을 줍니다.","영향을 줍니다.","영향을 줍니다.","정답(아닌 것). 급수처리"],"t":"진공 = 냉각·공기·드레인"},"2021-2-기관1-16":{"w":"해수 윤활식 선미관 베어링에는 합성 고무(또는 리그넘바이티, 합성수지)를 많이 씁니다. 화이트 메탈은 기름 윤활식에 씁니다.","x":["슬리브 재료입니다.","켈밋은 기관 베어링용입니다.","정답. 합성 고무","화이트 메탈은 기름 윤활식입니다."],"t":"해수 윤활 = 고무·리그넘바이티"},"2021-2-기관1-18":{"w":"공동현상은 날개 단면 형상, 수류 입사각, 원주 속도(회전수), 심도 등에 따라 생깁니다. 날개의 재질은 공동현상의 발생 원인이 아니라 침식 정도와 관계됩니다.","x":["원인입니다.","정답(옳지 않은 것). 재질은 발생 원인이 아닙니다.","원인입니다.","원인입니다."],"t":"공동현상 원인 = 형상·입사각·속도"},"2021-2-기관1-22":{"w":"디젤 연료는 세탄값이 적당히 높고, 유황이 적으며, 화재 위험이 작아야(인화점이 높아야) 합니다. 발화점은 적당히 낮아야 착화가 잘 됩니다.","x":["맞습니다.","정답(옳지 않은 것). 발화점은 낮아야 착화가 쉽습니다.","맞습니다.","맞습니다."],"t":"디젤 연료 = 착화성 좋게(발화점 낮게)"},"2021-2-기관1-24":{"w":"하중이 크고 속도가 느릴 때는 유막이 끊어지기 쉬우므로 점도가 높은 윤활유가 필요합니다.","x":["저점도가 적합합니다.","틀립니다.","틀립니다.","정답. 고하중·저속"],"t":"고하중·저속 = 고점도"},"2021-2-기관2-1":{"w":"유압 동력원은 유압펌프입니다. 어큐뮬레이터는 압력을 저장했다가 보충하는 보조 기기입니다.","x":["맞습니다.","맞습니다.","맞습니다.","정답(옳지 않은 것). 어큐뮬레이터는 동력원이 아닙니다."],"t":"동력원 = 펌프, 어큐뮬레이터 = 축압"},"2021-2-기관2-8":{"w":"전동식 캡스턴은 웜 기어로 전동기 회전을 크게 감속해 워핑드럼을 돌립니다.","x":["거버너는 속도 조절기입니다.","클러치는 연결·차단입니다.","정답. 웜 기어","래칫은 역회전 방지입니다."],"t":"캡스턴 감속 = 웜 기어"},"2021-2-기관2-9":{"w":"배유용 전자밸브를 여는 유면검출기는 분리된 기름이 모이는 상부 공간의 하한 레벨에 설치합니다.","x":["틀립니다.","틀립니다.","정답. 기름 공간 하한 레벨","상한 레벨이 아닙니다."],"t":"유면검출기 = 기름층 하한"},"2021-2-기관2-21":{"w":"만재 배수톤수와 경하 배수톤수의 차이는 재화중량톤수(DWT)입니다.","x":["총톤수는 용적입니다.","정답. 재화중량톤수","순톤수는 용적입니다.","배수량 자체입니다."],"t":"DWT = 만재 − 경하"},"2021-2-기관2-23":{"w":"잉여저항은 전체 저항에서 마찰저항을 뺀 나머지(조파·와류·공기저항)입니다.","x":["잉여저항입니다.","잉여저항입니다.","잉여저항입니다.","정답(아닌 것). 마찰저항"],"t":"잉여저항 = 전체 − 마찰"},"2021-2-기관2-24":{"w":"부품표에는 품명, 재료, 수량, 무게 등을 적습니다. 투상도는 도면 본체에 그립니다.","x":["기재합니다.","정답(아닌 것). 투상도","기재합니다.","기재합니다."],"t":"부품표 = 품명·재료·수량"},"2021-2-기관3-4":{"w":"평형 3상의 세 상 기전력 순시값을 합하면 항상 0입니다.","x":["정답. 0","틀립니다.","틀립니다.","틀립니다."],"t":"평형 3상 합 = 0"},"2021-2-기관3-5":{"w":"P = V² ÷ R = 100² ÷ 10 = 1,000[W]입니다.","x":["틀립니다.","틀립니다.","틀립니다.","정답. 1,000[W]"],"t":"P = V² / R"},"2021-2-기관3-9":{"w":"피상전력의 단위는 [kVA]입니다.","x":["유효전력","무효전력","정답. [kVA]","축전지 용량"],"t":"피상 = VA"},"2021-2-기관3-12":{"w":"역률 1일 때 3상 전력 P = √3 × 선간전압 × 선전류 입니다.","x":["틀립니다.","정답. √3배","틀립니다.","상 기준일 때 3배입니다."],"t":"P = √3 VI"},"2021-2-기관3-14":{"w":"3상 유도전동기는 3선 중 임의의 두 선을 바꾸면 역회전합니다.","x":["정답. 두 선 교체","세 선을 돌려 바꾸면 그대로입니다.","틀립니다.","틀립니다."],"t":"역회전 = 2선 교체"},"2021-2-기관3-15":{"w":"동기속도 Ns = 120f ÷ P [rpm]입니다.","x":["정답. 120f / P","틀립니다.","주파수 식입니다.","틀립니다."],"t":"Ns = 120f / P"},"2021-2-기관3-17":{"w":"변압기 용량은 [kVA]로 표시합니다.","x":["마력","마력","정답. [kVA]","유효전력"],"t":"변압기 = kVA"},"2021-2-기관3-20":{"w":"중간 탭 변압기와 다이오드 2개를 쓴 전파 정류회로이므로 출력은 반원이 연속으로 이어진 파형입니다.","x":["해당하지 않습니다.","해당하지 않습니다.","정답. 전파 정류 파형","해당하지 않습니다."],"t":"중간탭 + 다이오드 2개 = 전파"},"2021-2-기관3-21":{"w":"다이오드 캐소드가 입력 쪽이고 출력이 풀업 저항(+5V)에 연결되어, 입력 중 하나라도 0이면 출력이 0이 되는 AND 회로입니다.","x":["정답. AND","NAND가 아닙니다.","OR가 아닙니다.","NOR가 아닙니다."],"t":"다이오드 + 풀업 = AND"},"2021-2-기관3-22":{"w":"PNP 트랜지스터는 P(컬렉터)-N(베이스)-P(이미터) 구조입니다. 다이오드로 나타내면 컬렉터와 이미터 쪽(P, 애노드)에서 베이스(N, 캐소드) 쪽을 향하는 두 다이오드가 됩니다.","x":["정답. 두 다이오드 모두 베이스를 향함","틀립니다.","NPN 구조입니다.","틀립니다."],"t":"PNP = 화살표가 베이스로"},"2021-2-기관3-23":{"w":"이상적인 연산증폭기는 증폭도·입력 임피던스·대역폭이 무한대이고, 출력 임피던스는 0입니다.","x":["특징입니다.","정답(아닌 것). 입력 임피던스는 무한대입니다.","특징입니다.","특징입니다."],"t":"입력 Z = ∞, 출력 Z = 0"},"2021-2-기관3-24":{"w":"다이오드를 직렬로 연결하면 역방향 전압이 나뉘어 걸리므로 높은 역방향 전압(과전압)에 견딜 수 있습니다.","x":["병렬 연결의 효과입니다.","정답. 역방향 과전압 보호","평활회로의 역할입니다.","순방향 전압 강하는 커집니다."],"t":"직렬 = 내전압↑, 병렬 = 전류↑"},"2021-2-기관3-25":{"w":"연산증폭기(비교기)에서 V1(−입력) > V2(+입력)이면 출력은 음의 전원 전압(−15[V])으로 포화됩니다.","x":["전원 전압을 넘을 수 없습니다.","정답. −15[V]","30[V]는 나올 수 없습니다.","틀립니다."],"t":"비교기 = ±전원 포화"},"2021-2-직무일반-1":{"w":"입거 중에는 선내 화장실을 쓰지 않고, 화재 작업 때 소화기를 두며, 탱크 진입 표지판을 겁니다. 폐유·쓰레기는 조선소 육상 시설로 처리하며 선내 소각기를 쓰지 않습니다.","x":["맞습니다.","맞습니다.","정답(아닌 것). 입거 중 소각은 하지 않습니다.","맞습니다."],"t":"입거 중 = 소각 금지"},"2021-2-직무일반-2":{"w":"기름 탱크에 들어갈 때는 환기, 라이프라인 사용, 공구 회수에 주의합니다. 작업등 커버는 누전에 대비해 반드시 접지해야 합니다.","x":["맞습니다.","맞습니다.","맞습니다.","정답(옳지 않은 것). 작업등은 접지합니다."],"t":"탱크 작업등 = 방폭·접지"},"2021-2-직무일반-11":{"w":"3도 화상은 피부와 피하조직까지 손상되어 신경이 파괴되므로 통증이 거의 없고, 피부가 괴사해 굳고 검게 변합니다.","x":["1도는 붉어집니다.","2도는 물집이 생깁니다.","정답. 3도 화상","해당하지 않습니다."],"t":"3도 = 괴사·무통"},"2021-2-직무일반-12":{"w":"근육주사는 바늘을 찌른 뒤 피스톤을 살짝 당겨 피가 들어오지 않는지 확인하고 주입합니다. 피가 들어오면 혈관에 들어간 것이므로 다시 찔러야 합니다.","x":["맞습니다.","맞습니다.","맞습니다.","정답(옳지 않은 것). 피가 들어오면 안 됩니다."],"t":"근육주사 = 피 역류 없음 확인"},"2021-2-직무일반-13":{"w":"얼굴이나 피부가 붉으면 혈압이 높은 상태일 수 있습니다(창백하면 낮음).","x":["정답. 높은 상태","창백할 때입니다.","틀립니다.","틀립니다."],"t":"붉음 = 고혈압, 창백 = 저혈압"},"2021-2-직무일반-15":{"w":"보일러가 저수위가 되면 즉시 버너를 끄고 원인(급수관 누설, 수면계 상태)을 점검합니다. 과열된 보일러에 갑자기 급수하면 급격한 증기 발생으로 폭발할 수 있습니다.","x":["맞습니다.","맞습니다.","맞습니다.","정답(옳지 않은 것). 급히 급수하면 위험합니다."],"t":"저수위 = 소화, 급수 금지"},"2021-2-직무일반-16":{"w":"기관실 화재 비상 정지 스위치는 청정기, 통풍 팬, 유류 펌프 등 연료·공기를 공급하는 기기를 멈춥니다. 청수펌프는 해당하지 않습니다.","x":["정지 대상입니다.","정지 대상입니다.","정지 대상입니다.","정답(아닌 것). 청수펌프"],"t":"비상정지 = 연료·통풍 계통"},"2021-2-직무일반-18":{"w":"기관실 대형 화재는 통풍 차단, 구획 폐쇄 후 고정식 소화설비로 끕니다. 휴대식 소화기로는 대형 화재를 끌 수 없습니다.","x":["맞습니다.","맞습니다.","정답(옳지 않은 것). 휴대식은 초기 화재용","맞습니다."],"t":"대형 화재 = 고정식 소화설비"},"2021-2-직무일반-19":{"w":"전기화재를 막으려면 절연저항을 규정치 이상으로 유지해야 합니다.","x":["예방법입니다.","예방법입니다.","정답(아닌 것). 절연저항은 높게","예방법입니다."],"t":"절연저항 = 높게"},"2021-2-영어-1":{"w":"크랭크축 1회전에 캠축이 반 회전하는 것은 4행정 기관입니다(캠축 = 크랭크축의 1/2 속도).","x":["없습니다.","2행정은 같은 속도입니다.","없습니다.","정답. 4 stroke cycle engine"],"t":"4행정 캠축 = 1/2 속도"},"2021-2-영어-2":{"w":"구명설비(Lifesaving Appliances)는 구명정, 구명벌, 구명조끼 등입니다. life style은 생활 방식입니다.","x":["구명정","구명벌","구명조끼","정답(아닌 것). life style"],"t":"LSA = 구명설비"},"2021-2-영어-11":{"w":"\"분사 압력(injection pressure)을 30[MPa]로 조정했다.\"","x":["온도","정답. pressure","유량","점도"],"t":"injection pressure = 분사 압력"},"2021-2-영어-13":{"w":"출항하다 = leave. \"S/B eng. for leaving Busan.\"","x":["입항입니다.","입항입니다.","정답. leaving Busan","from이 불필요합니다."],"t":"leave = 출항"},"2021-2-영어-14":{"w":"exciters = 여자기 입니다.","x":["전기자는 armature입니다.","정류기는 rectifier입니다.","정답. 여자기","차단기는 breaker입니다."],"t":"exciter = 여자기"},"2021-2-영어-18":{"w":"기관은 배 뒤쪽(stern)의 프로펠러를 돌립니다.","x":["정답. stern","bow = 선수","beam = 폭","port side = 좌현"],"t":"stern = 선미"},"2021-2-영어-19":{"w":"실린더에 공기를 채우는 방법(air charging, 급기 방식)에 따라 기관을 4행정과 2행정으로 나눕니다.","x":["공랭식이 아닙니다.","연료 펌핑이 아닙니다.","정답. air charging","연료 분사가 아닙니다."],"t":"급기 방식 = 4행정·2행정"},"2021-3-기관1-3":{"w":"베어링 메탈은 마찰 저항이 작고, 열팽창이 작으며, 열전도가 좋아야 합니다. 또 축보다 무르게 만들어 축을 보호하고 이물질을 묻어 들이는 성질(매립성)이 필요하므로, 강도(경도)가 클수록 좋은 것은 아닙니다(출제 기준).","x":["요구 사항입니다.","요구 사항입니다.","요구 사항입니다.","정답(옳지 않은 것, 출제 기준). 너무 단단하면 축이 손상됩니다."],"t":"베어링 메탈 = 축보다 무르게","c":"베어링 메탈도 하중을 견딜 피로강도는 필요하지만, 공식 정답은 ㉵입니다."},"2021-3-기관1-5":{"w":"피스톤링은 적당한 장력, 좋은 열전도성, 충분한 내마멸성이 필요합니다. 윤활유 함침성은 피스톤링의 요구 조건으로 보지 않습니다(출제 기준).","x":["요구 조건입니다.","요구 조건입니다.","요구 조건입니다.","정답(옳지 않은 것, 출제 기준)."],"t":"피스톤링 = 장력·열전도·내마멸"},"2021-3-기관1-8":{"w":"대형 디젤기관의 크랭크축은 너무 커서 한 덩어리로 만들기 어려우므로 저널·암·핀을 따로 만들어 끼우는 조립형을 주로 씁니다.","x":["일체형은 중소형에 씁니다.","정답. 조립형","일체 주조형은 소형에 씁니다.","해당하지 않습니다."],"t":"대형 크랭크축 = 조립형"},"2021-3-기관1-10":{"w":"평균유효압력은 연료 분사량을 늘리면 높아집니다. 지압선도(P-V 선도)로 계산합니다.","x":["정답. 분사량 증가 시 높아짐","최고·압축압력만으로 계산할 수 없습니다.","한 행정의 압력이 아닙니다.","수인선도는 연소 상태를 봅니다."],"t":"평균유효압력 ∝ 출력"},"2021-3-기관1-12":{"w":"보일러 수압시험은 상온의 물로 압력을 가해 용접부 상태, 변형, 균열, 누설을 확인합니다. 고온에 견디는지는 알 수 없습니다.","x":["목적입니다.","목적입니다.","목적입니다.","정답(아닌 것). 고온 시험이 아닙니다."],"t":"수압시험 = 강도·누설"},"2021-3-기관1-13":{"w":"강제 순환 보일러는 펌프로 물을 순환시켜 순환이 좋고, 비등이 빠르며, 전열 효과가 좋습니다. 관이 가늘고 복잡해 검사·청소는 어렵습니다.","x":["특징입니다.","정답(옳지 않은 것). 검사·청소가 어렵습니다.","특징입니다.","특징입니다."],"t":"강제 순환 = 청소 어려움"},"2021-3-기관1-15":{"w":"증기 작동 방식에 따른 터빈 분류는 충동터빈, 반동터빈, 혼식(충동·반동 혼합)터빈입니다. 진동터빈은 없습니다.","x":["해당합니다.","정답(아닌 것). 진동터빈","해당합니다.","해당합니다."],"t":"터빈 = 충동·반동·혼식"},"2021-3-기관1-17":{"w":"간접 역전장치는 유체 클러치 역전장치, 유니언식(기어) 역전장치, 가변 피치 프로펠러 등입니다. 캠축 이동식은 기관 자체를 역회전시키는 직접 역전장치입니다.","x":["간접 역전입니다.","간접 역전입니다.","간접 역전입니다.","정답(아닌 것). 캠축 이동식은 직접 역전"],"t":"캠축 이동식 = 직접 역전"},"2021-3-기관1-19":{"w":"조파저항은 선형에 민감하고, 횡파와 발산파로 나뉘며, 선수·선미에 파도를 만듭니다. 속도가 높을수록 영향이 커집니다.","x":["맞습니다.","정답(옳지 않은 것). 고속에서 영향이 큽니다.","맞습니다.","맞습니다."],"t":"조파저항 = 고속에서 큼"},"2021-3-기관1-24":{"w":"청정 분산제를 많이 넣은 윤활유는 기관 내부의 찌꺼기를 씻어 내는 플러싱유입니다(출제 기준).","x":["해당하지 않습니다.","해당하지 않습니다.","해당하지 않습니다.","정답. 플러싱유"],"t":"플러싱유 = 세척용","c":"실린더유·시스템유에도 청정 분산제가 들어가지만, 공식 정답은 ㉵입니다."},"2021-3-기관1-25":{"w":"완전윤활은 두 면이 유막으로 완전히 분리된 상태로, 액체(유체)마찰만 일어납니다.","x":["고체마찰은 건조 마찰입니다.","정답. 액체마찰","혼합마찰은 불완전윤활입니다.","경계마찰은 얇은 유막 상태입니다."],"t":"완전윤활 = 액체마찰"},"2021-3-기관2-3":{"w":"속이 빈 삼각형(공기압)이 원 안쪽을 향하면(모터) 공기압 모터 기호입니다.","x":["해당하지 않습니다.","해당하지 않습니다.","해당하지 않습니다.","정답. 빈 삼각형 + 안쪽"],"t":"빈 삼각형 = 공기압"},"2021-3-기관2-4":{"w":"관 속에서 압력이 낮아진 부분의 액체가 기화해 기포가 생기는 현상은 공동현상(캐비테이션)입니다.","x":["노킹은 이상 연소입니다.","수격현상은 압력파 충격입니다.","서징은 압력·유량의 주기적 변동입니다.","정답. 공동현상"],"t":"저압 → 기포 = 캐비테이션"},"2021-3-기관2-6":{"w":"전동 유압식 조타장치의 전동기는 항해 중 항상 회전합니다.","x":["틀립니다.","정답. 항상 회전","틀립니다.","틀립니다."],"t":"조타 전동기 = 상시 운전"},"2021-3-기관2-17":{"w":"탭은 용도에 따라 테이퍼 탭(1번), 플러그 탭(2번), 보터밍 탭(3번)으로 나눕니다. 다이스는 수나사 가공 공구입니다.","x":["해당합니다.","해당합니다.","정답(아닌 것). 다이스","해당합니다."],"t":"다이스 = 수나사"},"2021-3-기관2-18":{"w":"연동척은 3개의 조가 함께 움직여 둥근 일감을 빨리 고정합니다. 4개의 조가 따로 움직이는 것은 단동척입니다.","x":["맞습니다.","맞습니다.","정답(옳지 않은 것). 단동척의 설명입니다.","맞습니다."],"t":"연동척 = 3조 동시, 단동척 = 4조 독립"},"2021-3-기관2-20":{"w":"용접봉 E4316에서 E는 피복 아크 용접봉, 43은 용착금속 최소 인장강도, 16(뒤 두 자리)은 용접 자세와 피복제 종류를 나타냅니다.","x":["E는 Electrode(용접봉)입니다.","틀립니다.","최소 인장강도입니다.","정답. 16 = 자세·피복제"],"t":"EXX16 = 저수소계"},"2021-3-기관2-22":{"w":"벌크선의 수밀격벽은 침수 구역을 한정하고, 방화벽 역할을 하며, 선체 강도를 형성합니다. 화물을 분산 적재해 횡경사를 조정하는 역할은 아닙니다.","x":["역할입니다.","정답(옳지 않은 것). 횡경사 조정은 역할이 아닙니다.","역할입니다.","역할입니다."],"t":"수밀격벽 = 침수·방화·강도"},"2021-3-기관2-23":{"w":"마찰저항은 선속의 제곱과 접촉면적에 비례하고, 저속에서는 전체 저항의 70~80[%]를 차지합니다. 고속일수록 조파저항 비율이 커지고 마찰저항 비율은 줄어듭니다.","x":["맞습니다.","맞습니다.","맞습니다.","정답(옳지 않은 것). 고속일수록 비율은 줄어듭니다."],"t":"저속 마찰, 고속 조파"},"2021-3-기관2-24":{"w":"공차는 최대허용치수와 최소허용치수의 차입니다.","x":["정답. 최대 − 최소","틀립니다.","위 치수 허용차입니다.","아래 치수 허용차입니다."],"t":"공차 = 최대 − 최소"},"2021-3-기관2-25":{"w":"파선은 숨은선(보이지 않는 부분)에 씁니다. 기준선은 가는 1점 쇄선입니다.","x":["맞습니다.","맞습니다.","맞습니다.","정답(잘못된 것). 파선은 숨은선"],"t":"파선 = 숨은선"},"2021-3-기관3-4":{"w":"e = Em sin(ωt − θ)에서 시각 t1의 위상은 괄호 안의 ωt1 − θ 입니다.","x":["부호가 틀립니다.","정답. ωt1 − θ","각속도입니다.","초기 위상입니다."],"t":"위상 = sin 괄호 안"},"2021-3-기관3-7":{"w":"i = 5√2 sinωt 에서 최대값은 5√2[A]입니다.","x":["틀립니다.","틀립니다.","실효값입니다.","정답. 5√2[A]"],"t":"최대값 = sin 앞 계수"},"2021-3-기관3-8":{"w":"[Var]는 무효전력의 단위입니다.","x":["유효전력은 W입니다.","효율은 단위가 없습니다.","정답. 무효전력","피상전력은 VA입니다."],"t":"Var = 무효전력"},"2021-3-기관3-9":{"w":"절연저항은 메거로 측정합니다.","x":["정답. 메거","저전압 측정용입니다.","일반 저항용입니다.","접지 저항용입니다."],"t":"메거 = 절연저항"},"2021-3-기관3-10":{"w":"동기전동기는 일정 속도로 돌고 역률을 조절할 수 있으며 직류 여자가 필요합니다. 기동 토크가 없어 스스로 기동하지 못합니다.","x":["정답(옳지 않은 것). 기동 토크가 없습니다.","맞습니다.","맞습니다.","맞습니다."],"t":"동기전동기 = 기동 토크 없음"},"2021-3-기관3-12":{"w":"MCCB = 배선용 차단기(Molded Case Circuit Breaker)입니다.","x":["정답. 배선용 차단기","누전 차단기는 ELB입니다.","전자 개폐기는 MC입니다.","과전류 계전기는 OCR입니다."],"t":"MCCB = 배선용 차단기"},"2021-3-기관3-15":{"w":"동기 발전기의 계자에는 직류 여자 전류를 흘립니다.","x":["맥류가 아닙니다.","교류가 아닙니다.","정답. 직류","틀립니다."],"t":"여자 = 직류"},"2021-3-기관3-17":{"w":"90° 지상(뒤진) 전류, 즉 유도성 부하에서는 전기자 반작용이 계자 자속을 줄이는 감자작용을 합니다.","x":["정답. 감자작용","동상 전류(저항)일 때입니다.","진상 전류(용량성)일 때입니다.","해당하지 않습니다."],"t":"지상 = 감자, 진상 = 증자"},"2021-3-기관3-19":{"w":"직렬 저항 Rz와 부하에 병렬로 연결된 제너 다이오드 Dz로 출력 전압을 일정하게 유지하는 정전압회로입니다.","x":["평활회로는 콘덴서를 씁니다.","정전류회로가 아닙니다.","정답. 정전압회로","승압회로가 아닙니다."],"t":"제너 + 직렬 저항 = 정전압"},"2021-3-기관3-23":{"w":"NPN 트랜지스터는 베이스 전류와 컬렉터 전류가 합쳐져 이미터로 나갑니다(IE = IB + IC).","x":["틀립니다.","정답. IB + IC → IE","틀립니다.","틀립니다."],"t":"NPN = 이미터로 나감"},"2021-3-직무일반-6":{"w":"염소가 들어 있는 냉매(프레온류)를 쓰는 냉동장치에서 불응축가스를 뺄 때 냉매가 함께 새어 나올 수 있습니다.","x":["해당하지 않습니다.","해당하지 않습니다.","정답. 불응축가스 배제","황산화물 배출입니다."],"t":"냉매 배출 = ODS 누설"},"2021-3-직무일반-8":{"w":"대량 유출 시에는 손상 부위 수리, 오일펜스 설치, 선체 경사 조정 등을 합니다. 탱크 안에 유처리제를 뿌리는 것은 틀린 조치입니다.","x":["맞습니다.","정답(옳지 않은 것). 탱크 내 유처리제 살포","맞습니다.","맞습니다."],"t":"유출 = 수리·오일펜스·경사 조정"},"2021-3-직무일반-18":{"w":"전기화재가 나면 가장 먼저 전원을 차단해야 합니다. 그래야 감전 없이 소화할 수 있습니다.","x":["정답. 전원 차단","그다음입니다.","그다음입니다.","전원 차단 후 합니다."],"t":"전기화재 = 전원 차단 먼저"},"2021-3-직무일반-20":{"w":"과전류가 흐를수록 전선·기기가 과열되어 전기화재 위험이 가장 큽니다.","x":["정답. 과전류","절연저항이 높으면 안전합니다.","부하용량 자체는 위험이 아닙니다.","정격 이내면 괜찮습니다."],"t":"전기화재 = 과전류"},"2021-3-직무일반-21":{"w":"정전기는 습도가 낮을수록, 마찰이 많을수록, 유류가 관을 흐를 때 많이 생깁니다. 정전기가 생긴다고 주위 물질이 가열되지는 않으며, 방전 불꽃이 위험합니다.","x":["맞습니다.","정답(옳지 않은 것). 주위를 가열하지 않습니다.","맞습니다.","맞습니다."],"t":"정전기 위험 = 방전 불꽃"},"2021-3-직무일반-23":{"w":"선원법상 해원은 선장을 제외한 선원입니다. 선장은 해원이 아닙니다.","x":["정답(해원이 아님). 선장","해원입니다.","해원입니다.","해원입니다."],"t":"해원 = 선장 외 선원"},"2021-3-직무일반-25":{"w":"선박해양오염비상계획서에는 기름 유출을 줄이기 위한 방제조치, 보고 절차, 방제 조직 등이 들어갑니다.","x":["기름기록부는 별도 서류입니다.","평형수 관리계획서의 내용입니다.","정답. 방제조치 사항","해당하지 않습니다."],"t":"비상계획서 = 유출 방제"},"2021-3-영어-2":{"w":"watertight doors = 수밀문 입니다.","x":["수압문이 아닙니다.","수중문이 아닙니다.","수밀격벽은 watertight bulkhead입니다.","정답. 수밀문"],"t":"watertight = 수밀"},"2021-3-영어-4":{"w":"Oily mixture = 유성혼합물(기름이 섞인 혼합물)입니다.","x":["정답. 유성혼합물","틀립니다.","슬러지는 sludge입니다.","틀립니다."],"t":"oily mixture = 유성혼합물"},"2021-3-영어-6":{"w":"Tail shaft = 프로펠러축입니다.","x":["중간축은 intermediate shaft입니다.","스러스트축은 thrust shaft입니다.","정답. 프로펠러축","캠축은 camshaft입니다."],"t":"tail shaft = 프로펠러축"},"2021-3-영어-8":{"w":"decreased(줄였다) ≒ reduced.","x":["올렸다","정답. Reduced","바꿨다","지켜봤다"],"t":"decrease ≒ reduce"},"2021-3-영어-11":{"w":"adjusted(조정했다) ≒ regulated(조절했다).","x":["붙였다","정답. Regulated","올렸다","내렸다"],"t":"adjust ≒ regulate"},"2021-3-영어-16":{"w":"\"주기관의 크랭크 디플렉션을 측정했다.\" measure = 측정하다.","x":["수리했다","정답. Measured","교체했다","돌렸다"],"t":"measure deflection"},"2021-3-영어-18":{"w":"청정기의 보울을 여는 작동수는 메인 실린더(슬라이딩 보울)를 내려 슬러지를 배출하게 하는 물입니다.","x":["정답. 메인 실린더를 내리고 슬러지 배출","드레인이 아닙니다.","올리면 닫힙니다.","닫는 물입니다."],"t":"열림 작동수 = 슬러지 배출"},"2021-3-영어-20":{"w":"plumber(plummer) block = 중간축 베어링입니다.","x":["추력 베어링이 아닙니다.","정답. 중간축 베어링","메인 베어링이 아닙니다.","추진기 베어링이 아닙니다."],"t":"plummer block = 중간축 베어링"},"2021-3-영어-21":{"w":"기관실의 주발전기는 보통 교류(alternating current)를 만듭니다.","x":["틀립니다.","정답. alternating current","틀립니다.","직류가 아닙니다."],"t":"주발전기 = AC"},"2021-4-기관1-2":{"w":"직접분사식 기관은 흡입밸브에 슈라우드(가림판)를 달아 흡입공기가 회전(와류)하며 들어오게 해 분사된 연료와 잘 섞이게 합니다.","x":["압력을 높이는 장치가 아닙니다.","압축압력과 관계없습니다.","손실 방지가 목적이 아닙니다.","정답. 흡입공기에 와류를 주어 혼합 촉진"],"t":"슈라우드 = 흡기 와류"},"2021-4-기관1-3":{"w":"저질 중유 사용 시 라이너 마멸을 막으려면 청정을 잘하고, 적합한 윤활유를 쓰며, 냉각수 온도를 높게 유지해 황산 응결(저온 부식)을 막습니다. 저속 운전은 실린더 온도를 낮춰 부식을 키웁니다.","x":["대책입니다.","대책입니다.","대책입니다.","정답(옳지 않은 것). 저속 운전은 저온 부식을 키웁니다."],"t":"저질유 = 저온 부식 → 온도 높게"},"2021-4-기관1-5":{"w":"피스톤링은 열팽창을 고려해 적절한 절구틈(끊어진 틈)을 가져야 합니다. 재료는 주로 주철이고, 크롬 도금 링은 크롬 도금 라이너와 함께 쓰지 않습니다. 익스펜더 링은 오일링용입니다.","x":["크롬끼리는 쓰지 않습니다.","주로 주철을 씁니다.","익스펜더 링은 오일링에 씁니다.","정답. 적절한 절구틈"],"t":"링 절구틈 = 열팽창 여유"},"2021-4-기관1-7":{"w":"크랭크암 개폐작용(디플렉션)은 크랭크암 사이에 끼우는 디플렉션 다이얼 게이지로 잽니다.","x":["정답. 디플렉션 다이얼 게이지","텔레스코핑 게이지는 안지름용입니다.","브리지 게이지는 메인 베어링 처짐용입니다.","필러 게이지는 틈새용입니다."],"t":"디플렉션 = 다이얼 게이지"},"2021-4-기관1-9":{"w":"4행정 기관의 지시마력 IHP = Pi × A × L × N ÷ (2 × 4,500) [PS]입니다. 4행정은 2회전에 한 번 폭발하므로 N을 2로 나누고, 1[PS] = 4,500[kgf·m/min]입니다.","x":["6,120은 [kW] 환산값이고 2가 빠졌습니다.","2행정 기관의 식입니다.","[kW] 환산 식입니다.","정답. PiALN / (2 × 4,500)"],"t":"4행정 IHP = PiALN / 9,000 [PS]"},"2021-4-기관1-13":{"w":"캐스케이드 탱크는 급수를 저장하고, 이물질(기름)을 거르며, 급수를 데우는 역할을 합니다. 증기를 발생시키지는 않습니다.","x":["역할입니다.","역할입니다.","역할입니다.","정답(옳지 않은 것). 증기 발생"],"t":"캐스케이드 탱크 = 급수 저장·여과"},"2021-4-기관1-15":{"w":"충동터빈은 한 단에서 하는 일이 많아 길이가 짧고, 고온·고압 증기를 쓸 수 있으며, 노즐 수로 증기량을 조절할 수 있습니다. 저압부에서 효율이 좋은 것은 반동터빈입니다.","x":["장점입니다.","장점입니다.","정답(옳지 않은 것). 반동터빈의 특징입니다.","장점입니다."],"t":"충동 = 고압부, 반동 = 저압부"},"2021-4-기관1-16":{"w":"미첼형 스러스트 베어링은 칼라 하나의 앞뒤에 6~8개의 부채꼴 패드가 있어 쐐기형 유막으로 큰 추력을 받습니다. 추력 칼라는 1개입니다.","x":["맞습니다.","맞습니다.","정답(옳지 않은 것). 추력 칼라는 1개","맞습니다."],"t":"미첼형 = 칼라 1개 + 부채꼴 패드"},"2021-4-기관1-17":{"w":"전진할 때 프로펠러가 배를 앞으로 미는 추력이 축을 선체 쪽으로 밀어 축에는 압축력이 작용합니다.","x":["정답. 전진 때 압축력","전진 때는 압축력입니다.","후진 때는 인장력입니다.","전단력이 아닙니다."],"t":"전진 = 압축, 후진 = 인장"},"2021-4-기관1-19":{"w":"스큐 백은 날개를 회전 반대 방향으로 휘게 한 것으로, 불규칙한 수류에 의한 추력 변동을 줄이고 선미 진동을 막습니다. 너무 크면 공동현상이 생깁니다.","x":["맞습니다.","정답(옳지 않은 것). 추력 변동을 줄여 줍니다.","맞습니다.","맞습니다."],"t":"스큐 백 = 진동·추력 변동 감소"},"2021-4-기관1-23":{"w":"윤활유 열화를 막으려면 다른 윤활유와 섞지 않고, 교환할 때 전부 바꾸며, 공기와의 접촉을 줄이고 적정 순환량을 유지합니다.","x":["정답. 혼합 사용을 피한다","일부만 바꾸면 열화유가 새 기름을 오염시킵니다.","순환량을 줄이면 과열됩니다.","공기 접촉은 산화를 촉진합니다."],"t":"윤활유 = 섞지 않기"},"2021-4-기관1-25":{"w":"온도 변화가 큰 곳에 한 가지 윤활유를 쓰려면 온도에 따른 점도 변화가 작은 점도지수가 큰 윤활유가 적합합니다.","x":["점도만 높으면 저온에서 너무 뻑뻑합니다.","정답. 점도지수가 큰 윤활유","주요 조건이 아닙니다.","주요 조건이 아닙니다."],"t":"온도 변화 큼 = 점도지수↑"},"2021-4-기관2-1":{"w":"공동현상을 막으려면 펌프를 낮게 설치해 흡입양정을 작게 하고, 배관을 짧고 완만하게 하며, 회전수를 정격 이하로 유지하고, 흡입관 손실을 줄입니다.","x":["정답(옳지 않은 것). 흡입양정은 작게 해야 합니다.","방지법입니다.","방지법입니다.","방지법입니다."],"t":"캐비테이션 방지 = 흡입양정 작게"},"2021-4-기관2-2":{"w":"축류펌프는 송출밸브를 닫으면 소요 동력이 오히려 커지므로 밸브를 열고 기동합니다(원심펌프는 닫으면 동력이 작아짐).","x":["맞습니다.","맞습니다.","맞습니다.","정답(옳지 않은 것). 닫으면 동력이 커집니다."],"t":"축류펌프 = 송출밸브 열고 기동"},"2021-4-기관2-5":{"w":"이론상 흡입 한계는 약 10.33[m]이지만, 손실 때문에 실제로 흡입할 수 있는 높이는 약 6~7[m]입니다.","x":["너무 낮습니다.","너무 낮습니다.","정답. 약 6~7[m]","이론값보다 높아 불가능합니다."],"t":"실제 흡입 높이 ≒ 6~7m"},"2021-4-기관2-6":{"w":"운전 중 베어링 상태는 청진봉을 베어링 하우징에 대고 소리를 들어 확인합니다.","x":["송출밸브를 닫고 운전하면 안 됩니다.","정지할 때가 아니라 운전 중에 확인합니다.","송출관이 아닙니다.","정답. 청진봉을 베어링 하우징에"],"t":"베어링 점검 = 청진봉"},"2021-4-기관2-8":{"w":"자동 장력 무어링윈치는 계선로프의 장력을 설정값 이하로 유지해 로프가 끊어지지 않게 합니다.","x":["결박 장치가 아닙니다.","푸는 장치가 아닙니다.","계측 장치가 아닙니다.","정답. 장력 유지·파단 방지"],"t":"자동 장력 윈치 = 장력 유지"},"2021-4-기관2-11":{"w":"냉매는 압축기 → 유분리기 → 응축기 → 수액기 → (건조기) → 팽창밸브 → 증발기 순서로 흐릅니다.","x":["액분리기는 증발기 뒤입니다.","정답. 유분리기, 수액기","순서가 틀립니다.","틀립니다."],"t":"압축기 → 유분리기 → 응축기 → 수액기"},"2021-4-기관2-12":{"w":"프레온 누설은 할로겐 누설검지기, 핼라이드 토치, 비눗물로 찾습니다. 리트머스 시험지는 암모니아(알칼리성) 누설 검지에 씁니다.","x":["프레온용입니다.","프레온용입니다.","정답(관계없는 것). 리트머스는 암모니아용","공통입니다."],"t":"리트머스 = 암모니아"},"2021-4-기관2-15":{"w":"중앙 공기조화 방식은 중앙 조화기에서 만든 공기를 그대로 보내며 선실에서는 취출구 댐퍼로 양만 조절합니다.","x":["정답. 중앙 공기조화 방식","재열 방식은 말단에서 가열합니다.","2중 덕트는 냉·온풍을 섞습니다.","유인 방식은 실내 공기를 유인합니다."],"t":"중앙식 = 댐퍼로만 조절"},"2021-4-기관2-17":{"w":"밀링, 보링, 드릴링은 깎아내는 절삭가공입니다. 단조는 두드려 모양을 만드는 소성가공입니다.","x":["절삭가공입니다.","절삭가공입니다.","정답(아닌 것). 단조는 소성가공","절삭가공입니다."],"t":"단조 = 소성가공"},"2021-4-기관2-18":{"w":"녹인 금속을 틀(주형)에 부어 모양을 만드는 작업은 주조입니다.","x":["정답. 주조","소성가공은 힘을 가해 변형합니다.","단조는 두드리는 가공입니다.","해당하지 않습니다."],"t":"주조 = 녹여 부어 성형"},"2021-4-기관2-19":{"w":"산소·아세틸렌 용기는 반드시 세워서 고정해 사용합니다. 특히 아세틸렌은 눕히면 아세톤이 흘러나와 위험합니다.","x":["정답(옳지 않은 것). 용기는 세워서 씁니다.","맞습니다.","맞습니다.","맞습니다."],"t":"가스 용기 = 세워서 고정"},"2021-4-기관2-20":{"w":"기계적 시험은 인장시험, 충격시험, 경도시험, 굽힘시험 등입니다. 이음성능시험은 기계적 시험의 종류가 아닙니다.","x":["기계적 시험입니다.","기계적 시험입니다.","정답(아닌 것). 이음성능시험","기계적 시험입니다."],"t":"기계적 시험 = 인장·충격·경도·굽힘"},"2021-4-기관2-24":{"w":"위치 결정의 근거가 되는 기준선은 가는 1점 쇄선으로 그립니다.","x":["실선은 외형선 등입니다.","점선은 해당하지 않습니다.","정답. 1점 쇄선","2점 쇄선은 가상선입니다."],"t":"기준선·중심선 = 1점 쇄선"},"2021-4-기관2-25":{"w":"길이를 1/2로 줄이면 면적은 (1/2)² = 1/4배가 됩니다.","x":["틀립니다.","길이의 비율입니다.","틀립니다.","정답. 1/4배"],"t":"면적 = 길이 비율²"},"2021-4-기관3-1":{"w":"인덕턴스만의 회로에서는 전류가 전압보다 90° 늦습니다(㉯).","x":["R 회로입니다.","정답. 전류 90° 늦음","C 회로입니다.","RL 회로입니다."],"t":"L = 전류 늦음"},"2021-4-기관3-4":{"w":"접속점으로 들어오는 전류의 합과 나가는 전류의 합이 같다는 것은 키르히호프의 제1법칙입니다.","x":["옴의 법칙은 V = IR입니다.","정답. 키르히호프의 법칙","쿨롱의 법칙은 전하 사이의 힘입니다.","앙페르의 법칙은 전류와 자기장입니다."],"t":"키르히호프 1법칙 = 전류"},"2021-4-기관3-7":{"w":"P = I²R = 10² × 20 = 2,000[W] = 2[kW]입니다.","x":["틀립니다.","틀립니다.","틀립니다.","정답. 2[kW]"],"t":"P = I²R"},"2021-4-기관3-8":{"w":"직렬회로는 같은 전류가 흐르므로 전압은 저항에 비례합니다. 3[Ω]의 전압은 6[Ω]의 3/6 = 1/2배입니다.","x":["정답. 1/2배","반대입니다.","틀립니다.","틀립니다."],"t":"직렬 = 전압 ∝ 저항"},"2021-4-기관3-10":{"w":"직류 100[V]와 같은 열을 내는 교류는 실효값 100[V]이고, 그 최대값은 100 × √2 ≒ 141.4[V]입니다.","x":["평균값에 가깝습니다.","틀립니다.","실효값입니다.","정답. 141.4[V]"],"t":"최대값 = √2 × 실효값"},"2021-4-기관3-13":{"w":"열동 과전류 계전기의 출력접점은 동작 후 손으로 되돌리는 수동복귀 접점으로, 가운데에 ×가 있는 기호입니다.","x":["정답. × 표시 수동복귀 접점","한시 접점입니다.","한시 접점입니다.","푸시 버튼입니다."],"t":"열동계전기 = × 표시 접점"},"2021-4-기관3-14":{"w":"R = V² ÷ P = 100² ÷ 500 = 20[Ω]입니다.","x":["틀립니다.","정답. 20[Ω]","틀립니다.","틀립니다."],"t":"R = V² / P"},"2021-4-기관3-15":{"w":"V2 = V1 × N2 ÷ N1 = 200 × 1,000 ÷ 2,000 = 100[V]입니다.","x":["정답. 100[V]","틀립니다.","틀립니다.","틀립니다."],"t":"V2 = V1 × N2/N1"},"2021-4-기관3-16":{"w":"동손(구리손)은 권선 저항에 흐르는 전류로 생기는 손실로 전류의 제곱에 비례합니다(I²R).","x":["틀립니다.","기계손입니다.","철손(히스테리시스)입니다.","정답. 전류의 제곱에 비례"],"t":"동손 = I²R"},"2021-4-기관3-17":{"w":"f = P × N ÷ 120 = 6 × 1,200 ÷ 120 = 60[Hz]입니다.","x":["틀립니다.","틀립니다.","정답. 60[Hz]","틀립니다."],"t":"f = PN / 120"},"2021-4-기관3-19":{"w":"정류된 맥동 전압을 일정하게 만드는 회로는 평활회로입니다.","x":["발진회로가 아닙니다.","정류회로입니다.","증폭회로가 아닙니다.","정답. 평활회로"],"t":"평활 = 맥동 제거"},"2021-4-기관3-20":{"w":"직렬 저항 R과 출력에 병렬로 연결된 제너 다이오드로 이루어진 정전압 회로입니다.","x":["정답. 정전압","정전류가 아닙니다.","구형파가 아닙니다.","톱니파가 아닙니다."],"t":"제너 + 직렬 저항 = 정전압"},"2021-4-기관3-23":{"w":"다이오드는 순방향 전압이 문턱 전압(약 0.7[V])을 넘으면 전류가 급격히 증가하는 지수 곡선 특성을 가집니다.","x":["정답. 급격히 증가하는 곡선","포화 특성이 아닙니다.","직선(저항) 특성입니다.","터널 다이오드 특성입니다."],"t":"다이오드 = 문턱 전압 후 급증"},"2021-4-기관3-24":{"w":"다이오드 기호에서 화살표가 밖으로 나가는 것은 빛을 내는 발광다이오드(LED)입니다.","x":["일반 다이오드는 화살표가 없습니다.","정답. 발광다이오드","정류기가 아닙니다.","FET가 아닙니다."],"t":"화살표 밖으로 = LED"},"2021-4-기관3-25":{"w":"SCR은 P-N-P-N 4층 구조이며, 애노드(P1) 쪽부터 P1-N1-P2-N2 순서이고 게이트는 캐소드 쪽 P2층에 연결됩니다.","x":["순서가 틀립니다.","게이트 위치가 틀립니다.","정답. P1-N1-P2(G)-N2","순서가 틀립니다."],"t":"SCR = PNPN, 게이트 = P2"},"2021-4-직무일반-3":{"w":"입거 중에는 시체스트 내부, 선저 해수 흡입 밸브, 보일러 수저방출 선외 밸브 등 물에 잠기는 부분을 반드시 점검합니다. 해수펌프 흡입 스트레이너는 항해 중에도 점검할 수 있습니다.","x":["반드시 점검합니다.","반드시 점검합니다.","반드시 점검합니다.","정답(아닌 것). 스트레이너는 언제든 점검 가능"],"t":"입거 = 수선 아래 밸브·시체스트"},"2021-4-직무일반-4":{"w":"실린더 헤드 균열은 침투탐상법(컬러 체크)으로 가장 많이 검사합니다.","x":["정답. 침투탐상법","자성체에만 쓸 수 있습니다.","장비가 필요합니다.","내부 결함용입니다."],"t":"표면 균열 = 침투탐상"},"2021-4-직무일반-7":{"w":"유해액체물질 중 경미한 위해를 끼쳐 배출을 일부 제한하는 것은 Z류입니다.","x":["X류는 심각, 배출 금지입니다.","Y류는 위해입니다.","정답. Z류","기타 물질은 무해로 간주됩니다."],"t":"X 심각, Y 위해, Z 경미"},"2021-4-직무일반-8":{"w":"선박에너지효율설계지수(EEDI)는 선박의 이산화탄소 배출량을 기준으로 합니다.","x":["정답. 이산화탄소","황산화물이 아닙니다.","배기가스 전체가 아닙니다.","질소산화물이 아닙니다."],"t":"EEDI = CO₂"},"2021-4-직무일반-9":{"w":"유해방오도료의 유기주석 화합물(TBT)은 해양 생물에 큰 해를 끼칩니다.","x":["해당하지 않습니다.","PCB는 다른 유해물질입니다.","대기오염물질입니다.","정답. 유기주석 화합물"],"t":"TBT = 방오도료 유해물질"},"2021-4-직무일반-10":{"w":"에너지효율 관련 보고 사항은 운항거리, 운항시간, 연료유 종류와 사용량입니다. 폐기물기록부는 보고 대상이 아닙니다.","x":["보고합니다.","보고합니다.","정답(아닌 것). 폐기물기록부","보고합니다."],"t":"에너지효율 보고 = 거리·시간·연료"},"2021-4-직무일반-12":{"w":"소독에는 약 70~75[%] 에틸알코올이 가장 효과적입니다. 메틸알코올은 독성이 있어 쓰지 않습니다.","x":["100[%]는 소독 효과가 오히려 떨어집니다.","정답. 75[%] 에틸알코올","메틸알코올은 독성이 있습니다.","메틸알코올은 독성이 있습니다."],"t":"소독 = 70~75% 에탄올"},"2021-4-직무일반-14":{"w":"기관실 침수 원인은 해수관 파공, 선미관 해수 유입, 해수펌프 글랜드 누수 등입니다. 상갑판의 시체스트 에어벤트 밸브가 열린 것은 침수 원인이 아닙니다.","x":["원인입니다.","원인입니다.","원인입니다.","정답(옳지 않은 것). 에어벤트 밸브"],"t":"침수 = 해수관·선미관·글랜드"},"2021-4-직무일반-15":{"w":"시동공기로는 돌지만 연료로 운전이 안 되면 연료 공급, 연료 계통 공기 혼입, 연료펌프 래크 고착 등을 점검합니다. 터닝기어가 물려 있으면 아예 회전하지 않습니다.","x":["정답(옳지 않은 것). 회전한다면 터닝기어는 관계없습니다.","점검합니다.","점검합니다.","점검합니다."],"t":"회전 O, 착화 X = 연료 계통"},"2021-4-직무일반-16":{"w":"배기가 갑자기 흰색이 되는 것은 실린더 안으로 냉각수가 새어 수증기가 나오기 때문입니다.","x":["틀립니다.","틀립니다.","윤활유 연소는 청백색입니다.","정답. 냉각수 누설"],"t":"흰 배기 = 물"},"2021-4-직무일반-19":{"w":"열식 화재탐지기는 바이메탈식, 가용금속식, 감온전선식 등입니다. 광전자식은 연기식입니다.","x":["열식입니다.","정답(아닌 것). 광전자식은 연기식","열식입니다.","열식입니다."],"t":"광전자식 = 연기식"},"2021-4-직무일반-21":{"w":"운전 중인 전동기 화재는 전원을 차단하고 CO₂ 소화기로 끈 뒤 절연저항을 잽니다. 포말 소화기는 전기가 통해 감전 위험이 있고 기기를 손상시킵니다.","x":["맞습니다.","정답(적절하지 않은 것). 포말은 전기화재에 부적합","맞습니다.","맞습니다."],"t":"전기화재 = CO₂"},"2021-4-직무일반-22":{"w":"선박국적증서에는 IMO 번호, 선박의 주요 치수, 기관의 종류와 수 등을 기재합니다. 최대승선인원은 선박검사증서에 기재합니다.","x":["정답(아닌 것). 최대승선인원","기재합니다.","기재합니다.","기재합니다."],"t":"최대승선인원 = 검사증서"},"2021-4-직무일반-23":{"w":"해양사고 발생 지점이 확실하면 제1심은 그 지점을 관할하는 지방해양안전심판원에서 합니다.","x":["중앙은 2심입니다.","틀립니다.","발생 지점이 불명확할 때 등입니다.","정답. 발생 지점 관할 지방심판원"],"t":"1심 = 사고 지점 관할"},"2021-4-직무일반-24":{"w":"최저 승무기준을 처음 위반하면 행정처분은 경고입니다.","x":["정답. 경고","너무 무겁습니다.","틀립니다.","틀립니다."],"t":"승무기준 첫 위반 = 경고"},"2021-4-직무일반-25":{"w":"400톤 이상 1만톤 미만 비유조선의 기관구역에는 배출관장치, 기름여과장치, 유성찌꺼기 탱크를 설치합니다. 기름배출감시제어장치(ODME)는 유조선 화물구역 설비입니다.","x":["설치합니다.","설치합니다.","설치합니다.","정답(아닌 것). ODME는 유조선용"],"t":"ODME = 유조선"},"2021-4-영어-1":{"w":"\"연료유를 2번 이중저 탱크(D.B.T.)에 적재했다.\"","x":["정답. D.B.T.","sump tank는 윤활유용입니다.","A.P.T.는 선미 탱크입니다.","F.W.T.는 청수 탱크입니다."],"t":"D.B.T. = 이중저 탱크"},"2021-4-영어-4":{"w":"검사 = survey. \"No.2 intermediate shaft bearing to be opened for survey.\"","x":["overhaul은 정비입니다.","정답. survey","증서가 아닙니다.","프로펠러가 아닙니다."],"t":"for survey = 검사를 위해"},"2021-4-영어-5":{"w":"PSC = Port State Control(항만국 통제)입니다.","x":["틀립니다.","정답. Port State Control","틀립니다.","틀립니다."],"t":"PSC = 항만국 통제"},"2021-4-영어-7":{"w":"해양오염방지설비는 기름여과장치, 소각기, 오수처리장치 등입니다. Sterilizer(살균기)는 해당하지 않습니다.","x":["해당합니다.","해당합니다.","정답(아닌 것). 살균기","해당합니다."],"t":"sterilizer = 살균기"},"2021-4-영어-9":{"w":"ratings of the engine department = 기관부원(부원)입니다.","x":["기관사는 engineer입니다.","갑판원이 아닙니다.","항해사가 아닙니다.","정답. 기관부원"],"t":"ratings = 부원"},"2021-4-영어-10":{"w":"propeller shaft = tail shaft 입니다.","x":["크랭크축","정답. tail shaft","추력축","중간축"],"t":"tail shaft = 프로펠러축"},"2021-4-영어-11":{"w":"\"주기관 1번 배기온도가 너무 높은 것을 발견했다.\" found = 발견했다.","x":["교체했다","정답. Found","받았다","주문했다"],"t":"found = 발견"},"2021-4-영어-12":{"w":"portable fire extinguisher = 휴대식 소화기 입니다.","x":["고정식은 fixed입니다.","정답. 휴대식 소화기","경보기가 아닙니다.","자동이 아닙니다."],"t":"portable = 휴대식"},"2021-4-영어-14":{"w":"중유를 가열해 적정 점도로 만드는 것은 분무(atomization)를 잘 하기 위해서입니다.","x":["승화","정답. atomization = 무화","기화","응고"],"t":"atomization = 무화"},"2021-4-영어-18":{"w":"조절했다 = regulated, 출구 = outlet. \"Regulated cooling water outlet temperature.\"","x":["정답.","examined, inlet이 틀립니다.","changed, inlet이 틀립니다.","watched는 지켜봤다입니다."],"t":"outlet 출구, inlet 입구"},"2021-4-영어-19":{"w":"Flash point = 인화점입니다.","x":["발화점은 ignition point입니다.","정답. 인화점","착화점이 아닙니다.","연소점은 fire point입니다."],"t":"flash point = 인화점"},"2021-4-영어-20":{"w":"연료·윤활유 청정이나 기름여과장치에서 나오는 폐유 찌꺼기는 Oil residue(유성잔류물, 슬러지)입니다.","x":["빌지입니다.","정답. Oil residue","폐연료유가 아닙니다.","중유가 아닙니다."],"t":"oil residue = 슬러지"},"2021-4-영어-23":{"w":"RPR = Reverse Power Relay(역전력 계전기)입니다. Regulator가 아닙니다.","x":["맞습니다.","맞습니다.","정답(잘못된 것). RPR = Reverse Power Relay","맞습니다."],"t":"RPR = 역전력 계전기"},"2021-4-영어-24":{"w":"\"자동화는 일부 작업을 사람(man)보다 훨씬 효과적으로 할 수 있다.\"","x":["기계","공구","기관","정답. man"],"t":"automation vs man"},"2021-4-영어-25":{"w":"전동기에서 움직이는 부분은 rotor(회전자)이고, 고정된 부분은 stator(고정자)입니다.","x":["정답. rotor","stator는 고정자입니다.","air gap은 공극입니다.","mouth ring은 펌프 부품입니다."],"t":"rotor 회전자, stator 고정자"},"2022-1-기관1-1":{"w":"무기 분사식(사바테) 사이클의 열효율은 압축비, 압력비, 분사차단비(와 비열비)로 정해집니다. 온도비는 들어가지 않습니다.","x":["영향을 줍니다.","영향을 줍니다.","정답(아닌 것). 온도비","영향을 줍니다."],"t":"사바테 효율 = 압축비·압력비·차단비"},"2022-1-기관1-3":{"w":"디젤 연소실은 직접분사식과 부실식(예연소실식, 와류실식, 공기실식)으로 나눕니다. 기계분사식은 연소실 종류가 아닙니다.","x":["연소실 종류입니다.","정답(아닌 것). 기계분사식","연소실 종류입니다.","연소실 종류입니다."],"t":"연소실 = 직접분사·예연소실·와류실·공기실"},"2022-1-기관1-4":{"w":"4행정 기관에서 배기행정 종말(상사점 부근)에는 가스 압력 없이 관성력이 크랭크축을 끌어올려 메인 베어링 캡에 최대 하중이 걸립니다.","x":["틀립니다.","정답. 배기행정 종말","틀립니다.","압축 종말에는 하중이 아래쪽에 걸립니다."],"t":"캡 최대 하중 = 배기 말"},"2022-1-기관1-5":{"w":"중·대형 2행정 디젤기관은 배기밸브로 위로 배기하고 소기공으로 아래에서 소기하는 유니플로 소기식을 많이 씁니다. 소기 효율이 가장 좋습니다.","x":["정답. 유니플로 소기식","루프 소기식은 중소형에 씁니다.","횡단 소기식은 소형에 씁니다.","와류 소기식이 아닙니다."],"t":"대형 2행정 = 유니플로 소기"},"2022-1-기관1-8":{"w":"윤활유 냉각기가 오손되면 냉각이 잘 안 되어 윤활유 온도가 올라갑니다.","x":["저부하면 온도가 낮아집니다.","해수 온도가 낮으면 냉각이 잘 됩니다.","정답. 냉각기 오손","순환량이 많으면 온도가 낮아집니다."],"t":"윤활유 온도↑ = 냉각기 오손"},"2022-1-기관1-9":{"w":"직접분사식 기관에는 연료를 연소실 전체에 퍼뜨리기 위해 다공식 노즐을 많이 씁니다. 단공식(핀틀·스로틀)은 부실식 기관에 씁니다.","x":["맞는 설명입니다.","정답(옳지 않은 것). 직접분사식은 다공식입니다.","맞는 설명입니다.","맞는 설명입니다."],"t":"직접분사 = 다공 노즐"},"2022-1-기관1-10":{"w":"보슈식 연료분사펌프에서는 래크로 분사량을, 캠·태핏 조정으로 분사시기를 조정할 수 있습니다. 분사압력은 분사밸브 스프링으로 조정합니다.","x":["분사압력은 분사밸브에서 조정합니다.","분사압력은 분사밸브에서 조정합니다.","정답. 분사시기와 분사량","분사형태는 노즐이 정합니다."],"t":"연료펌프 = 시기·양, 분사밸브 = 압력"},"2022-1-기관1-11":{"w":"과급하면 같은 기관에서 출력이 늘고, 마력당 무게가 줄며, 평균유효압력이 높아집니다.","x":["가벼워집니다.","저질유 사용과 관계없습니다.","정답. 출력 증대","높아집니다."],"t":"과급 = 출력↑"},"2022-1-기관1-13":{"w":"보일러를 정지할 때는 가장 먼저 연료 공급을 차단해 불을 끕니다. 그다음 노 안을 환기하고 증기·급수 밸브를 정리합니다.","x":["정답. 연료 차단 먼저","환기(포스트퍼지)를 위해 공기는 나중에 끊습니다.","나중에 합니다.","나중에 합니다."],"t":"보일러 정지 = 연료 차단 먼저"},"2022-1-기관1-14":{"w":"증기가 물로 바뀌는 것은 응축입니다.","x":["증발은 물 → 증기입니다.","정답. 응축","비등은 끓음입니다.","응고는 액체 → 고체입니다."],"t":"응축 = 증기 → 물"},"2022-1-기관1-16":{"w":"미첼형 추력 베어링은 칼라와 기울어진 패드 사이에 기름이 쐐기 모양으로 들어가 높은 유압으로 추력을 받습니다.","x":["보통형이 아닙니다.","정답. 미첼형","말굽형은 칼라 여러 개를 쓰는 옛 형식입니다.","해당하지 않습니다."],"t":"미첼형 = 경사 패드 쐐기 유막"},"2022-1-기관1-17":{"w":"스러스트 베어링이 많이 닳으면 크랭크축이 축 방향으로 밀려 메인 베어링 측면 발열, 크랭크암 개폐량 증대, 라이너 편마멸이 생깁니다. 배기밸브 누설과는 관계없습니다.","x":["나타납니다.","나타납니다.","나타납니다.","정답(아닌 것). 배기밸브 누설과 관계없습니다."],"t":"스러스트 마멸 = 축방향 이동"},"2022-1-기관1-18":{"w":"기름 윤활식 선미관은 베어링 길이를 짧게 할 수 있고, 마멸이 작으며, 해수 침입이 적습니다. 대신 윤활유 압력을 유지하기 위한 중력유 탱크가 필요합니다.","x":["장점입니다.","장점입니다.","장점입니다.","정답(옳지 않은 것). 중력유 탱크가 필요합니다."],"t":"유윤활 선미관 = 중력 탱크 필요"},"2022-1-기관1-19":{"w":"피치비 = 피치 ÷ 지름 = 25 ÷ 125 = 1/5 입니다.","x":["틀립니다.","틀립니다.","틀립니다.","정답. 25/125 = 1/5"],"t":"피치비 = P / D"},"2022-1-기관1-20":{"w":"고정 피치 프로펠러 선박의 출력은 속도의 세제곱에 비례합니다.","x":["틀립니다.","틀립니다.","정답. 세제곱 비례","틀립니다."],"t":"출력 ∝ 속도³"},"2022-1-기관1-22":{"w":"인화점은 불꽃(점화원)을 가까이 했을 때 불이 붙는 최저 온도입니다. 점화원 없이 스스로 불이 붙는 온도는 발화점입니다.","x":["맞는 설명입니다.","정답(옳지 않은 것). 발화점의 정의입니다.","맞는 설명입니다.","맞는 설명입니다."],"t":"인화점 = 불꽃 대면, 발화점 = 스스로"},"2022-1-기관1-23":{"w":"청정분산성은 카본 같은 탄화물을 기름 속에 흩어 놓아 퇴적되지 않게 하는 성질입니다.","x":["열안정성은 열에 견디는 성질입니다.","소포성은 거품을 없애는 성질입니다.","산중화성은 산을 중화하는 성질입니다.","정답. 청정분산성"],"t":"청정분산성 = 탄화물 퇴적 방지"},"2022-1-기관1-25":{"w":"온도에 따른 점도 변화 정도를 나타내는 것은 점도지수입니다.","x":["아닐린점은 착화성 관련입니다.","정답. 점도지수","API는 비중입니다.","해당하지 않습니다."],"t":"점도지수"},"2022-1-기관2-1":{"w":"마우스링은 임펠러와 케이싱 사이에서 송출측 물이 흡입측으로 역류하는 것을 막습니다.","x":["파손 방지가 목적이 아닙니다.","외부 누설은 패킹이 막습니다.","공기 유입은 패킹이 막습니다.","정답. 내부 역류 방지"],"t":"마우스링 = 역류 방지"},"2022-1-기관2-3":{"w":"헬레쇼 펌프는 부동링(편심링)의 이동 방향을 바꿔 흡입·송출 방향과 양을 바꿉니다.","x":["회전 방향은 일정합니다.","정답. 부동링 이동","해당하지 않습니다.","해당하지 않습니다."],"t":"헬레쇼 = 부동링으로 방향·유량 제어"},"2022-1-기관2-5":{"w":"터빈펌프는 임펠러 바깥에 안내날개(디퓨저)가 있어 속도를 압력으로 바꿉니다. 벌류트 펌프는 안내날개가 없습니다.","x":["정답(옳지 않은 것). 터빈펌프에는 안내날개가 있습니다.","마중물이 필요합니다.","벌류트는 저양정용입니다.","양흡입은 대유량용입니다."],"t":"터빈펌프 = 안내날개 있음"},"2022-1-기관2-8":{"w":"정전 용량식 유면검출기는 물과 기름의 유전율 차이를 이용합니다. 물의 유전율은 약 80, 기름은 약 3입니다.","x":["순서가 반대입니다.","틀립니다.","정답. 물 80, 기름 3","틀립니다."],"t":"유전율 물 80, 기름 3"},"2022-1-기관2-9":{"w":"산기기로 공기를 불어 넣어 호기성 박테리아가 오물을 분해하는 탱크는 폭기탱크입니다.","x":["멸균탱크는 소독합니다.","침전탱크는 슬러지를 가라앉힙니다.","정답. 폭기탱크","해당하지 않습니다."],"t":"폭기탱크 = 공기 + 박테리아"},"2022-1-기관2-13":{"w":"부하가 낮으면 온도가 금방 설정값에 도달해 냉동기가 자주 기동·정지를 반복합니다.","x":["정상 운전에서는 드뭅니다.","과부하면 계속 운전합니다.","정답. 낮은 부하","관계없습니다."],"t":"저부하 = 잦은 기동·정지"},"2022-1-기관2-14":{"w":"냉매는 대기압에서 증발온도(비등점)가 낮아야 낮은 온도를 얻을 수 있습니다. 임계온도는 높고, 응축압력은 낮고, 응고온도는 낮아야 합니다.","x":["정답(옳지 않은 것). 증발온도는 낮아야 합니다.","맞습니다.","맞습니다.","맞습니다."],"t":"냉매 = 비등점 낮게"},"2022-1-기관2-16":{"w":"철판 두께는 외경 마이크로미터로 정밀하게 잴 수 있습니다.","x":["다이얼 게이지는 변위를 잽니다.","정답. 외경 마이크로미터","틈새 게이지는 틈을 잽니다.","서피스 게이지는 금긋기용입니다."],"t":"두께 = 외경 마이크로미터"},"2022-1-기관2-18":{"w":"프레스 가공은 전단(자르기), 굽힘(휨), 성형(드로잉), 압축 가공 등입니다. 인장가공은 프레스 가공에 속하지 않습니다.","x":["프레스 가공입니다.","프레스 가공입니다.","프레스 가공입니다.","정답(아닌 것). 인장가공"],"t":"프레스 = 전단·굽힘·성형"},"2022-1-기관2-20":{"w":"용접부 잔류응력은 풀림(어닐링)으로 없앱니다.","x":["담금질은 경화입니다.","뜨임은 인성 부여입니다.","불림은 조직 균일화입니다.","정답. 풀림"],"t":"잔류응력 제거 = 풀림"},"2022-1-기관2-21":{"w":"가운데에 무겁게 싣고 앞뒤에 가볍게 실으면 가운데가 처지는 새깅이 됩니다.","x":["호깅은 가운데가 솟는 상태입니다.","정답. 새깅","러칭은 급격한 횡요입니다.","슬래밍은 선수 충격입니다."],"t":"가운데 무거움 = 새깅"},"2022-1-기관2-22":{"w":"종강력재는 용골, 종격벽, 중심선 거더 등 배 길이 방향 부재입니다. 늑골은 횡강력재입니다.","x":["정답(아닌 것). 늑골은 횡강력재","종강력재입니다.","종강력재입니다.","종강력재입니다."],"t":"늑골 = 횡강력재"},"2022-1-기관2-23":{"w":"선체 저항은 마찰 저항, 조파 저항, 조와(와류) 저항, 공기 저항입니다.","x":["경계·충격·잉여 저항은 분류가 아닙니다.","정답. 마찰·조파·조와·공기","틀립니다.","틀립니다."],"t":"선체 저항 = 마찰·조파·조와·공기"},"2022-1-기관2-24":{"w":"치수공차는 최대허용치수와 최소허용치수의 차입니다.","x":["틀립니다.","틀립니다.","정답. 최대 − 최소","틀립니다."],"t":"공차 = 최대 − 최소"},"2022-1-기관2-25":{"w":"기계의 설치 위치를 나타내는 도면은 배치도입니다.","x":["설치도가 아닙니다.","배선도는 전선 연결도입니다.","배관도는 관 연결도입니다.","정답. 배치도"],"t":"배치도 = 위치"},"2022-1-기관3-1":{"w":"거주실 전원 220[V]는 실효값(실효치)입니다.","x":["최대치가 아닙니다.","순시치가 아닙니다.","정답. 실효치","평균치가 아닙니다."],"t":"전원 = 실효값"},"2022-1-기관3-4":{"w":"역기전력도 전압이므로 단위는 [V]입니다.","x":["정전용량 단위입니다.","정답. [V]","저항 단위입니다.","전력 단위입니다."],"t":"기전력 = V"},"2022-1-기관3-7":{"w":"정전용량은 전극 간격이 좁을수록 커집니다.","x":["맞습니다.","맞습니다.","맞습니다.","정답(옳지 않은 것). 간격이 좁을수록 커집니다."],"t":"C ∝ 1/간격"},"2022-1-기관3-8":{"w":"같은 저항 n개를 병렬로 연결하면 10 ÷ n = 1.25 이므로 n = 8개입니다.","x":["2.5[Ω]입니다.","약 1.67[Ω]입니다.","정답. 8개","1[Ω]입니다."],"t":"병렬 n개 = R/n"},"2022-1-기관3-10":{"w":"주기(1사이클 시간)와 주파수(1초당 사이클 수)는 서로 역수로 반비례합니다. 각속도는 주파수에 2π를 곱한 것입니다.","x":["주기의 정의입니다.","주파수의 정의입니다.","주파수에 2π를 곱합니다.","정답. 반비례"],"t":"f = 1/T, ω = 2πf"},"2022-1-기관3-11":{"w":"I = P ÷ V = 450 ÷ 100 = 4.5[A]입니다.","x":["틀립니다.","정답. 4.5[A]","틀립니다.","틀립니다."],"t":"I = P / V"},"2022-1-기관3-12":{"w":"병렬 투입 직전에는 주파수와 위상(과 전압)을 일치시켜야 합니다.","x":["유효전력은 투입 후 분담합니다.","역률은 조건이 아닙니다.","정답. 주파수와 위상","역률은 조건이 아닙니다."],"t":"병렬 투입 = 전압·주파수·위상"},"2022-1-기관3-13":{"w":"역률계는 전압과 전류의 위상 차이(역률)를 나타냅니다.","x":["전력계는 전력을 나타냅니다.","정답. 역률계","누전등은 누전 확인용입니다.","MCCB는 차단기입니다."],"t":"위상 = 역률계"},"2022-1-기관3-14":{"w":"동기속도는 주파수와 극수로만 정해지므로 전압이 낮아져도 변하지 않습니다. 토크·출력은 줄고 슬립은 커집니다.","x":["토크는 전압² 비례로 줄어듭니다.","슬립은 커집니다.","출력은 줄어듭니다.","정답. 동기속도"],"t":"Ns = 120f / P (전압 무관)"},"2022-1-기관3-15":{"w":"정전압 충전은 단전지당 약 2.3~2.4[V]의 일정 전압으로 충전하며, 처음에는 큰 전류가 흐르고 끝에는 거의 흐르지 않습니다. 1.5[V]는 너무 낮습니다.","x":["맞습니다.","맞습니다.","맞습니다.","정답(옳지 않은 것). 1.5[V]로는 충전되지 않습니다."],"t":"정전압 충전 ≒ 2.3~2.4V/셀"},"2022-1-기관3-16":{"w":"Lower/Raise 표시가 있는 것은 거버너 모터 스위치로, 주파수(부하 분담)를 조정합니다.","x":["ACB는 차단기입니다.","싱크로스코프는 Fast/Slow입니다.","주파수계는 계기입니다.","정답. 거버너 모터 스위치"],"t":"Lower/Raise = 거버너"},"2022-1-기관3-17":{"w":"전압변동률 = (무부하 전압 − 정격 전압) ÷ 정격 전압 × 100 입니다.","x":["정답. 100 × (V0 − Vn) / Vn","틀립니다.","분모가 틀렸습니다.","틀립니다."],"t":"전압변동률 = (V0 − Vn) / Vn"},"2022-1-기관3-18":{"w":"피상전력 = √3 × 450 × 20 ≒ 15.6[kVA]. 유효전력이 0[kW]이므로 역률 = 0 ÷ 15.6 = 0입니다. (무효전력만 흐르는 상태)","x":["틀립니다.","정답. 약 15.6[kVA], 역률 0","단위가 틀립니다.","피상전력의 단위는 kVA입니다."],"t":"3상 S = √3 VI"},"2022-1-기관3-19":{"w":"진리표에서 X1, X2 중 하나라도 1이면 Y가 1이므로 OR입니다.","x":["NOR는 둘 다 0일 때만 1입니다.","정답. OR","AND는 둘 다 1일 때만 1입니다.","NAND는 둘 다 1일 때만 0입니다."],"t":"하나라도 1이면 1 = OR"},"2022-1-기관3-20":{"w":"정류된 맥동 전압을 평탄하게 만드는 회로는 평활회로입니다.","x":["맥동회로는 없습니다.","정답. 평활회로","배압회로는 전압을 높입니다.","정전압회로는 전압을 일정하게 합니다."],"t":"평활 = 맥동 제거"},"2022-1-기관3-21":{"w":"불순물을 넣어 남는 전자(과잉전자)로 전기가 통하는 반도체는 N형입니다.","x":["P-N은 접합입니다.","진성은 불순물이 없습니다.","정답. N형","P형은 정공으로 통합니다."],"t":"과잉전자 = N형"},"2022-1-기관3-22":{"w":"다이오드 막대(캐소드)의 끝이 꺾인 기호는 제너 다이오드입니다.","x":["FET가 아닙니다.","TR이 아닙니다.","정답. Zener diode","SCR은 게이트가 있습니다."],"t":"꺾인 막대 = 제너"},"2022-1-기관3-23":{"w":"TRIAC(트라이액)은 게이트 신호가 들어오면 T1, T2 전압 방향과 관계없이 양방향으로 도통합니다. 한쪽 방향만 도통하는 것은 SCR입니다.","x":["①은 틀립니다.","①은 틀립니다.","정답. ②, ③","①은 틀립니다."],"t":"TRIAC = 양방향"},"2022-1-기관3-25":{"w":"양방향 전류를 제어할 수 있는 교류용 사이리스터는 TRIAC입니다.","x":["PUT는 발진용입니다.","SCR은 단방향입니다.","GTO는 단방향입니다.","정답. TRIAC"],"t":"교류 제어 = TRIAC"},"2022-1-직무일반-1":{"w":"밀폐 공간의 산소 결핍은 철판이 녹슬면서 산소를 소비하는 것(부식)과 통풍 불량이 주된 원인입니다.","x":["습도는 주된 원인이 아닙니다.","정답. ①, ⑤","틀립니다.","온도 저하는 원인이 아닙니다."],"t":"산소 결핍 = 부식 + 통풍 불량"},"2022-1-직무일반-2":{"w":"피스톤 개방에는 피스톤링 확장기, 마이크로미터, 아이볼트(들어 올리기) 등이 필요합니다. 브리지게이지는 메인 베어링 마멸(처짐) 측정용입니다.","x":["정답(아닌 것). 브리지게이지는 베어링 측정용입니다.","필요합니다.","필요합니다.","필요합니다."],"t":"브리지게이지 = 메인 베어링"},"2022-1-직무일반-3":{"w":"입거 전에는 도면, 특수공구, 냉각수 연결 위치를 준비합니다. 소모품 재고 확인은 입거 준비의 핵심 사항이 아닙니다(출제 기준).","x":["준비합니다.","정답(적절하지 않은 것, 출제 기준).","확인합니다.","준비합니다."],"t":"입거 준비 = 도면·공구·연결 위치"},"2022-1-직무일반-6":{"w":"윤활유 냉각기 커버 패킹을 교환하면 냉각기 안의 해수가 빠져나와 바로 선저폐수(빌지)가 늘어납니다.","x":["정답. 선저폐수","유성찌꺼기가 아닙니다.","해당하지 않습니다.","해당하지 않습니다."],"t":"냉각기 분해 = 빌지 증가"},"2022-1-직무일반-7":{"w":"기름여과장치의 입·출구 압력차가 너무 크면 필터가 막힌 것이므로 소제합니다. 압력차가 작으면 막힌 것이 아닙니다.","x":["맞습니다.","맞습니다.","맞습니다.","정답(옳지 않은 것). 압력차가 클 때 필터 막힘입니다."],"t":"압력차↑ = 필터 막힘"},"2022-1-직무일반-8":{"w":"황산화물배출규제해역(SECA)에서는 황 함유량 0.1[%] 이하 연료유만 쓸 수 있습니다.","x":["정답. 0.1[%]","틀립니다.","틀립니다.","틀립니다."],"t":"ECA = 0.1%"},"2022-1-직무일반-9":{"w":"선박해양오염비상계획서에는 방제 조직, 교육·훈련, 방제 조치, 보고 절차 등이 들어갑니다. 오존층파괴물질 비상 차단은 해당하지 않습니다.","x":["포함됩니다.","정답(아닌 것). 오존층파괴물질은 해당하지 않습니다.","포함됩니다.","포함됩니다."],"t":"비상계획서 = 기름 유출 대응"},"2022-1-직무일반-10":{"w":"분뇨오염방지설비 대상은 400톤 이상 선박, 최대 승선인원 16명 이상 선박, 승선인원 16명 이상 군함·경찰용 선박 등이며 낚시 어선도 기준에 따라 대상입니다.","x":["맞습니다.","맞습니다.","맞습니다.","정답(맞지 않는 것). 낚시 어선도 대상입니다."],"t":"분뇨설비 = 400톤↑ 또는 16인↑"},"2022-1-직무일반-11":{"w":"혈액에서 산소를 운반하는 것은 적혈구(헤모글로빈)입니다.","x":["백혈구는 면역을 담당합니다.","정답. 적혈구","혈소판은 혈액 응고를 담당합니다.","감마 글로불린은 항체입니다."],"t":"적혈구 = 산소 운반"},"2022-1-직무일반-12":{"w":"감염 예방에 가장 효과적인 기본 방법은 손씻기입니다.","x":["정답. 손씻기","효과가 제한적입니다.","부상자 마스크가 아닙니다.","도움이 되지만 가장 기본은 손씻기입니다."],"t":"감염 예방 = 손씻기"},"2022-1-직무일반-13":{"w":"열사병 환자는 시원한 곳으로 옮기고, 옷을 느슨하게 하고, 찬물·부채질로 체온을 낮춥니다. 알코올은 탈수와 체온 조절 장애를 악화시키므로 주면 안 됩니다.","x":["맞습니다.","맞습니다.","맞습니다.","정답(옳지 않은 것). 알코올 금지"],"t":"열사병 = 체온 낮추기, 알코올 금지"},"2022-1-직무일반-17":{"w":"화재 시 유류 탱크 출구 밸브를 원격으로 닫는 장치는 급속차단밸브(Quick closing valve)입니다.","x":["해당하지 않습니다.","비상 정지 장치는 펌프·팬을 멈춥니다.","해당하지 않습니다.","정답. Quick closing valve"],"t":"탱크 출구 원격 차단 = 급속차단밸브"},"2022-1-직무일반-18":{"w":"불활성 가스장치는 화물탱크 안의 산소 농도를 낮춰 폭발을 방지합니다.","x":["정답. 폭발 방지","부식 방지가 주목적이 아닙니다.","오염 방지가 아닙니다.","질식 방지가 아닙니다."],"t":"IGS = 폭발 방지"},"2022-1-직무일반-19":{"w":"전기화재를 막으려면 절연저항을 일정값 이상으로 유지해야 합니다.","x":["대책입니다.","대책입니다.","대책입니다.","정답(옳지 않은 것). 절연저항은 높게 유지합니다."],"t":"절연저항 = 높게"},"2022-1-직무일반-20":{"w":"열작업(용접 등) 때는 가연성 가스가 차지 않도록 통풍을 잘 시켜야 합니다.","x":["정답(옳지 않은 것). 통풍은 유지합니다.","소화기와 감시원을 둡니다.","가스용기는 세워서 씁니다.","가연물을 옮깁니다."],"t":"열작업 = 통풍·소화기·감시원"},"2022-1-직무일반-23":{"w":"유해액체물질(X·Y·Z류)은 12해리 이상, 수심 25미터 이상에서 자항선 7노트·비자항선 4노트 이상으로 항해하며 수면 아래 배출구로 배출해야 합니다.","x":["기준입니다.","기준입니다.","정답(옳지 않은 것). 수면 아래 배출구로 배출합니다.","기준입니다."],"t":"유해액체 = 수면하 배출구"},"2022-1-영어-1":{"w":"\"지압도(indicator card)를 채취하고 연소 상태를 점검했다.\" take an indicator card = 지압도를 채취하다.","x":["바꿨다","검사했다","조정했다","정답. Took"],"t":"take indicator card = 지압도 채취"},"2022-1-영어-2":{"w":"\"터닝기어를 연결하고 주기관을 20분간 돌렸다.\" engage = 연결하다.","x":["정답. Engaged","분리했다","데웠다","시도했다"],"t":"engage turning gear"},"2022-1-영어-4":{"w":"여자기 = exciter. \"Rewound exciter windings in the generator.\"","x":["armature = 전기자","brush = 브러시","coil = 코일","정답. exciter = 여자기"],"t":"exciter = 여자기"},"2022-1-영어-5":{"w":"general service pump = 잡용수(GS) 펌프입니다.","x":["주냉각수펌프가 아닙니다.","정답. 잡용수펌프","추기펌프가 아닙니다.","복수펌프가 아닙니다."],"t":"G.S. pump = 잡용수 펌프"},"2022-1-영어-8":{"w":"The classification society = 선급협회(선급)입니다.","x":["해기사협회가 아닙니다.","조선협회가 아닙니다.","안전협회가 아닙니다.","정답. 선급협회"],"t":"classification society = 선급"},"2022-1-영어-9":{"w":"기관 회전수는 tachometer(회전계)로 잽니다.","x":["온도계","압력계","정답. tachometer","동력계"],"t":"tachometer = 회전계"},"2022-1-영어-11":{"w":"\"흡입밸브가 부러진 것을 발견하고(Found) 새것으로 교체했다(replaced).\"","x":["틀립니다.","정답. Found, replaced","틀립니다.","틀립니다."],"t":"found broken → replaced"},"2022-1-영어-12":{"w":"\"각 부의 온도와 압력을 자주 점검하시오.\" check = 점검.","x":["교체","줄임","정답. Checked","배출"],"t":"check = 점검"},"2022-1-영어-14":{"w":"흡입행정은 TDC에서 시작해 BDC에서 끝납니다.","x":["정답. TDC, BDC","반대입니다.","틀립니다.","틀립니다."],"t":"흡입 = TDC → BDC"},"2022-1-영어-17":{"w":"\"기관 내부 부품을 냉각한다\" — 윤활유(Lubricating oil)의 냉각 작용입니다.","x":["배기가스가 아닙니다.","연료유가 아닙니다.","제어공기가 아닙니다.","정답. Lubricating oil"],"t":"윤활유 = 냉각 작용"},"2022-1-영어-18":{"w":"\"냉매(refrigerant)는 가능하면 독성·폭발성·가연성·부식성이 없어야 한다.\"","x":["동사입니다.","정답. refrigerant","냉장고입니다.","냉동(명사)입니다."],"t":"refrigerant = 냉매"},"2022-1-영어-19":{"w":"선박의 열교환기는 대부분 뜨거운 액체를 해수와 청수로 식히는 냉각기입니다.","x":["틀립니다.","틀립니다.","정답. sea water and fresh water","틀립니다."],"t":"cooler = 해수·청수"},"2022-1-영어-20":{"w":"교류발전기는 여자(excitation)가 없으면 전압이 생기지 않습니다.","x":["전압이 낮을 뿐 생깁니다.","정답. 여자가 없을 때","정상 속도에서는 생깁니다.","무부하에서도 전압은 생깁니다."],"t":"여자 없음 = 전압 없음"},"2022-1-영어-22":{"w":"두 개의 구멍이 있고 90° 꺾는 관 이음은 elbow(엘보)입니다.","x":["정답. elbow","coupling = 직선 연결","tee = T자 분기","union = 분해 가능한 이음"],"t":"elbow = 90° 꺾임"},"2022-1-영어-23":{"w":"기관 성능(출력)은 dynamometer(동력계)로 평가합니다.","x":["온도계","회전계","정답. dynamometer","염분계"],"t":"dynamometer = 동력계"},"2022-1-직무일반-16":{"w":"급정지 요청 시 텔레그래프에 즉시 응답하고 조작(⑤) → 조작 시간 기록(①) → 기관장·1기사에게 연락(③) → 다음 명령 준비(④) → 선교에 사유 확인(②) 순서가 가장 적절합니다.","x":["정답. ⑤ → ① → ③ → ④ → ②","순서가 다릅니다.","조작이 먼저입니다.","조작이 먼저입니다."],"t":"급정지 = 즉시 조작 → 기록 → 보고"},"2022-2-기관1-1":{"w":"밸브 개폐시기 선도는 밸브가 열리고 닫히는 시기를 크랭크축의 회전 각도로 나타냅니다.","x":["피스톤 위치가 아닙니다.","정답. 크랭크축 회전 각도","연접봉 위치가 아닙니다.","연소 진행이 아닙니다."],"t":"밸브 선도 = 크랭크 각도"},"2022-2-기관1-2":{"w":"배압이 높으면 배기가 잘 빠지지 않아 소기가 나빠지고 연소가 불량해져 출력(마력)과 평균유효압력이 떨어집니다.","x":["소기가 나빠집니다.","마력이 줄어듭니다.","정답(옳지 않은 것). 평균유효압력은 낮아집니다.","연소가 나빠집니다."],"t":"배압↑ = 소기·연소 불량"},"2022-2-기관1-3":{"w":"1[PS] ≒ 0.736[kW]이므로 1[kW] ≒ 1 ÷ 0.736 ≒ 1.36[PS]입니다.","x":["틀립니다.","1[PS]의 [kW] 값입니다.","1[PS]의 [kgf·m/s] 값입니다.","정답. 1.36[PS]"],"t":"1PS = 0.736kW, 1kW = 1.36PS"},"2022-2-기관1-6":{"w":"착화지연은 연료의 세탄가, 분무(분포) 상태, 압축공기 온도·압력 등에 영향을 받습니다. 연료유 공급펌프 압력은 관계가 없습니다.","x":["영향을 줍니다.","영향을 줍니다.","영향을 줍니다.","정답(아닌 것). 공급펌프 압력"],"t":"착화지연 = 세탄가·분무·압축온도"},"2022-2-기관1-7":{"w":"배기밸브는 더 뜨거워 많이 늘어나므로 태핏 간극을 흡기밸브와 같거나 더 크게 합니다. 간극은 그 실린더가 압축행정 상사점(밸브가 완전히 닫힌 상태)에 있을 때 조정합니다.","x":["정답. ①, ② 모두 옳다","②도 옳습니다.","둘 다 옳습니다.","①도 옳습니다."],"t":"태핏 간극 = 압축 TDC에서, 배기 ≥ 흡기"},"2022-2-기관1-9":{"w":"과급하면 더 많은 공기와 연료를 태울 수 있어 평균유효압력이 커지고 출력이 늘어납니다.","x":["급기온도 상승은 오히려 불리합니다.","압축압력 상승은 결과입니다.","정답. 평균유효압력 증가","회전수는 그대로입니다."],"t":"과급 → 평균유효압력↑"},"2022-2-기관1-10":{"w":"플런저가 기름을 압축하기 시작해서 분사밸브가 열리고 분사가 시작될 때까지의 지연을 분사 지연이라 합니다.","x":["착화 지연은 분사 후 착화까지입니다.","유효행정은 실제 송출 행정입니다.","정답. 분사 지연","해당하지 않습니다."],"t":"분사 지연 = 펌프 압축 ~ 분사 시작"},"2022-2-기관1-12":{"w":"캐리오버는 수위가 너무 높을 때, 유지분 등 불순물이 많을 때, 증기 사용량이 급변할 때 생깁니다. pH가 높은 것(알칼리성)은 정상 관리 상태입니다(지나치면 문제).","x":["원인입니다.","정답(옳지 않은 것, 출제 기준). pH","원인입니다.","원인입니다."],"t":"캐리오버 = 고수위·유지분·급부하"},"2022-2-기관1-13":{"w":"과열증기를 쓰면 엔탈피가 커 증기 소비가 줄고, 습분이 없어 마찰·부식이 줄어듭니다. 온도차에 의한 변형 방지는 과열증기의 이점이 아닙니다.","x":["이점입니다.","이점입니다.","이점입니다.","정답(아닌 것). 변형 방지는 이점이 아닙니다."],"t":"과열증기 = 증기 소비↓·부식↓"},"2022-2-기관1-14":{"w":"진동연소는 기름에 공기·수분이 섞였을 때, 급유 압력이 변동할 때, 가열 온도가 너무 높을 때 생깁니다. 착화되지 않은 상태로 기름을 보내는 것은 역화(폭발)의 원인입니다.","x":["정답(아닌 것). 역화의 원인입니다.","원인입니다.","원인입니다.","원인입니다."],"t":"미착화 상태 급유 = 역화 위험"},"2022-2-기관1-17":{"w":"추진축계는 스러스트축, 중간축, 프로펠러축으로 구성됩니다. 캠축은 기관 내부 부품입니다.","x":["축계 요소입니다.","축계 요소입니다.","축계 요소입니다.","정답(아닌 것). 캠축"],"t":"축계 = 스러스트·중간·프로펠러축"},"2022-2-기관1-18":{"w":"프로펠러에 의한 축계 진동은 피치 불균일, 캐비테이션, 정적·동적 불평형 등으로 생깁니다. 날개 전개면적이 작은 것은 직접 원인이 아닙니다.","x":["원인입니다.","정답(아닌 것). 전개면적","원인입니다.","원인입니다."],"t":"프로펠러 진동 = 피치·캐비테이션·불평형"},"2022-2-기관1-19":{"w":"에어로포일형(날개형) 단면은 원호형 단면보다 배면(흡입면) 압력이 더 크게 떨어져 배면 공동현상을 일으키기 쉽습니다.","x":["맞는 설명입니다.","맞는 설명입니다.","맞는 설명입니다.","정답(옳지 않은 것). 에어로포일형이 더 쉽습니다."],"t":"에어로포일형 = 배면 공동현상 쉬움"},"2022-2-기관1-20":{"w":"출력 = 저항 × 속도 입니다. 저항은 속도의 제곱에 비례하므로 출력은 속도의 세제곱에 비례합니다.","x":["저항은 속도에 비례해 커집니다.","정답. 출력 = 저항 × 속도","속도는 회전수에 비례합니다.","출력은 회전수의 세제곱에 비례합니다."],"t":"P = R × V"},"2022-2-기관1-21":{"w":"15/4[℃] 비중은 같은 부피의 15[℃] 기름 무게와 4[℃] 물 무게의 비입니다.","x":["점도가 아닙니다.","점도가 아닙니다.","정답. 15[℃] 기름 / 4[℃] 물","반대입니다."],"t":"비중 15/4℃ = 기름(15℃) / 물(4℃)"},"2022-2-기관1-22":{"w":"연료유 청정 방법은 침전법, 원심분리법, 여과법 등입니다. 백토처리법은 윤활유 재생 방법입니다.","x":["청정 방법입니다.","청정 방법입니다.","청정 방법으로 쓰입니다.","정답(아닌 것). 백토처리는 윤활유 재생"],"t":"백토처리 = 윤활유 재생"},"2022-2-기관1-23":{"w":"연료유를 저장·운반할 때 화재 위험의 기준이 되는 성질은 인화점입니다.","x":["착화점이 아닙니다.","발화점이 아닙니다.","정답. 인화점","유동점이 아닙니다."],"t":"화재 위험 = 인화점"},"2022-2-기관2-1":{"w":"표준 대기압은 수은주 760[mm]입니다.","x":["정답. 760[mm]","틀립니다.","수주 높이[m]입니다.","틀립니다."],"t":"1기압 = 760mmHg"},"2022-2-기관2-2":{"w":"용적식 펌프는 자흡 능력이 있어 호수(마중물) 장치가 필요 없습니다. 고양정·소유량이고 맥동이 있습니다.","x":["터보식의 특성입니다.","정답. 호수 장치 불필요","터보식의 특성입니다.","왕복식은 밸브가 있고 맥동이 큽니다."],"t":"용적식 = 자흡 가능"},"2022-2-기관2-3":{"w":"헬리컬 기어는 축방향 추력이 생기므로, 방향이 반대인 헬리컬을 합친 이중 헬리컬(헤링본) 기어를 써서 추력을 상쇄합니다.","x":["축마력 증가가 목적이 아닙니다.","송출 방향과 관계없습니다.","송출량 증가가 주목적이 아닙니다.","정답. 축방향 추력 상쇄"],"t":"이중 헬리컬 = 추력 상쇄"},"2022-2-기관2-4":{"w":"벙커 A에서 벙커 C로 바꾸면 점도와 비중이 달라지므로 가열 온도를 높이고 비중판(조정판)을 다시 맞춰야 합니다.","x":["회전수는 바꾸지 않습니다.","봉수 온도가 주 조정 사항이 아닙니다.","정답. 가열온도와 비중판","송출밸브가 주 조정 사항이 아닙니다."],"t":"유종 변경 = 가열온도 + 비중판"},"2022-2-기관2-5":{"w":"기어식 조타장치는 피니언, 쿼드런트(부채꼴 기어), 완충스프링 등으로 이루어집니다. 램은 유압식(램식) 조타장치의 부품입니다.","x":["구성품입니다.","구성품입니다.","정답(아닌 것). 램은 유압식","구성품입니다."],"t":"램 = 유압 조타기"},"2022-2-기관2-6":{"w":"전동유압식 조타장치에는 송출 방향·양을 바꿀 수 있는 가변 용량형 펌프(윌리엄 재니 펌프, 헬레쇼 펌프)를 많이 씁니다.","x":["평기어 펌프가 아닙니다.","나사 펌프가 아닙니다.","정답. 윌리엄 재니 펌프","축류 펌프가 아닙니다."],"t":"조타 펌프 = 가변 용량(재니·헬레쇼)"},"2022-2-기관2-7":{"w":"캡스턴 워핑드럼의 역회전은 래칫 기어(톱니와 멈춤쇠)로 막습니다.","x":["웜 기어는 감속용입니다.","스퍼 기어는 동력 전달용입니다.","정답. 래칫 기어","밴드 브레이크는 제동용입니다."],"t":"역회전 방지 = 래칫"},"2022-2-기관2-12":{"w":"냉장고 온도가 높아도 압축기가 서 있으면 과전류 계전기, 고압 스위치, 윤활유 저압 스위치 등 보호장치가 동작한 것입니다. 흡입 압력이 높으면 저압 스위치가 켜져 오히려 기동됩니다.","x":["원인입니다.","원인입니다.","원인입니다.","정답(옳지 않은 것). 흡입 압력이 높으면 기동합니다."],"t":"압축기 미기동 = 보호장치 동작"},"2022-2-기관2-15":{"w":"공기조화장치는 송풍기, 공기 가열기·냉각기, 가습기, 공기 여과기 등으로 이루어집니다. 절탄기는 보일러의 급수 예열기입니다.","x":["구성품입니다.","구성품입니다.","정답(아닌 것). 절탄기는 보일러 부속","구성품입니다."],"t":"절탄기 = 보일러"},"2022-2-기관2-17":{"w":"드릴 날 끝의 여유각(릴리프 각)은 보통 10~15°입니다. (선단각은 118°)","x":["정답. 10~15°","틀립니다.","틀립니다.","틀립니다."],"t":"드릴 여유각 10~15°, 선단각 118°"},"2022-2-기관2-19":{"w":"단면적 = π × 10² ÷ 4 ≒ 78.5[mm²]. 인장응력 = 1,000 ÷ 78.5 ≒ 12.74[N/mm²]입니다.","x":["틀립니다.","틀립니다.","정답. 약 12.74[N/mm²]","틀립니다."],"t":"응력 = 힘 / 단면적(πd²/4)"},"2022-2-기관2-20":{"w":"용접 끝부분의 용융지가 식으며 오목하게 들어가 생기는 결함은 크레이터이며, 균열·슬래그 섞임이 생기기 쉽습니다.","x":["정답. 크레이터","스패터는 튀는 금속 알갱이입니다.","언더컷은 모재가 파인 결함입니다.","오버랩은 용착금속이 넘친 결함입니다."],"t":"크레이터 = 용접 끝의 오목부"},"2022-2-기관2-22":{"w":"배수중량 = 배수용적 × 비중량, 즉 W = V × r 입니다.","x":["정답. W = Vr","틀립니다.","틀립니다.","틀립니다."],"t":"무게 = 부피 × 비중량"},"2022-2-기관2-24":{"w":"정투상도법 중 가장 많이 쓰이는 것은 제3각법입니다(KS 기준).","x":["일부 국가에서 씁니다.","쓰지 않습니다.","정답. 제3각법","쓰지 않습니다."],"t":"제3각법"},"2022-2-기관2-25":{"w":"치수공차 = 최대허용치수 − 최소허용치수 입니다.","x":["위 치수 허용차입니다.","아래 치수 허용차입니다.","정답. 최대 − 최소","틀립니다."],"t":"공차 = 최대 − 최소"},"2022-2-기관3-1":{"w":"자기장 속에서 도체가 회전할 때 생기는 전류 방향은 플레밍의 오른손 법칙으로 구합니다. 그림의 회전에서 한 변은 A → B, 반대편 변은 C → D 방향으로 전류가 흘러 코일 전체로 한 방향으로 이어집니다.","x":["정답. A → B, C → D","틀립니다.","틀립니다.","틀립니다."],"t":"발전기 전류 방향 = 오른손 법칙"},"2022-2-기관3-5":{"w":"20[Ω] 두 개 병렬 = 10[Ω]. I = 200 ÷ 10 = 20[A]입니다.","x":["틀립니다.","직렬(40Ω)일 때의 값입니다.","저항 하나의 전류입니다.","정답. 20[A]"],"t":"같은 저항 2개 병렬 = 절반"},"2022-2-기관3-7":{"w":"XL = 2πfL = 2 × 3.14 × 60 × 1 ≒ 377[Ω]입니다.","x":["틀립니다.","틀립니다.","틀립니다.","정답. 약 377[Ω]"],"t":"2π × 60 ≒ 377"},"2022-2-기관3-8":{"w":"P = EIcosθ는 유효전력이므로 단위는 [W], [kW]입니다. [kVA]는 피상전력 단위입니다.","x":["맞습니다.","맞습니다.","맞습니다.","정답(옳지 않은 것). 단위는 [W]"],"t":"유효전력 = W"},"2022-2-기관3-9":{"w":"병렬 부분에서 전류는 저항에 반비례해 나뉩니다. I1 = 2 × 12/(4 + 12) = 1.5[A], I2 = 2 × 4/(4 + 12) = 0.5[A]입니다.","x":["정답. I1 = 1.5[A], I2 = 0.5[A]","반대입니다.","합이 2가 아닙니다.","저항이 다르므로 같지 않습니다."],"t":"병렬 분배: I1 = I × R2/(R1+R2)"},"2022-2-기관3-10":{"w":"전동 유압식 조타장치의 전동기는 튼튼하고 간단한 농형 유도전동기를 많이 씁니다.","x":["동기전동기가 아닙니다.","정답. 농형 유도전동기","권선형이 아닙니다.","정류자 전동기가 아닙니다."],"t":"선박 전동기 = 대부분 농형"},"2022-2-기관3-11":{"w":"직류발전기의 정류자 편수(코일 수)를 많게 하면 맥동이 줄어 매끄러운 직류를 얻습니다.","x":["전압 크기와 관계됩니다.","극수는 주된 방법이 아닙니다.","정답. 정류자 편수 증가","브러시 개수는 관계없습니다."],"t":"정류자 편수↑ = 맥동↓"},"2022-2-기관3-13":{"w":"맴돌이(와류) 전류 손실은 얇은 철판을 여러 장 겹쳐(성층) 철심을 만들어 줄입니다.","x":["콘덴서와 관계없습니다.","동선과 관계없습니다.","정답. 성층 철심","보상권선은 전기자 반작용 대책입니다."],"t":"와류손 = 성층"},"2022-2-기관3-16":{"w":"전기자 권선(구리선)의 저항에 전류가 흘러 생기는 열 손실은 구리손(동손)입니다.","x":["정답. 구리손","철손은 철심 손실입니다.","포유부하손은 기타 부하 손실입니다.","무부하손은 부하와 관계없는 손실입니다."],"t":"동손 = I²R"},"2022-2-기관3-17":{"w":"셰이딩 코일형 단상 유도전동기는 자극 일부에 셰이딩 코일을 감아 이동 자계를 만들어 기동하며, 구조상 회전 방향을 바꿀 수 없습니다.","x":["분상형의 특징입니다.","콘덴서형의 특징입니다.","정답. 역회전이 안 됩니다.","구조가 다릅니다."],"t":"셰이딩 코일 = 역회전 불가"},"2022-2-기관3-18":{"w":"납축전지를 충전하면 폭발성인 수소가스가 발생합니다.","x":["정답. 수소가스","아황산가스가 아닙니다.","염소가스가 아닙니다.","질소가스가 아닙니다."],"t":"축전지 = 수소"},"2022-2-기관3-19":{"w":"다이오드의 캐소드가 입력 A, B 쪽이고 출력 X가 저항으로 +5[V]에 연결된 회로입니다. 입력 중 하나라도 0이면 X가 0으로 끌려 내려가고, 둘 다 1일 때만 X가 1이므로 AND 회로입니다.","x":["정답. AND","NAND가 아닙니다.","OR는 다이오드 방향이 반대입니다.","NOR가 아닙니다."],"t":"다이오드 + 풀업 저항 = AND"},"2022-2-기관3-20":{"w":"집적회로(IC)는 작고, 신뢰성이 높고, 설계·제작이 간단합니다. 큰 전력을 다루기는 어렵습니다.","x":["장점입니다.","장점입니다.","정답(아닌 것). 대전력은 어렵습니다.","장점입니다."],"t":"IC = 소형·고신뢰·소전력"},"2022-2-기관3-22":{"w":"VCB는 베이스(B)를 기준으로 한 컬렉터(C)의 전압입니다. 아래 첨자의 뒤 문자가 기준입니다.","x":["정답. 베이스 기준 컬렉터 전압","반대입니다.","VBE입니다.","VCE입니다."],"t":"VXY = Y 기준 X 전압"},"2022-2-기관3-23":{"w":"교류 전력 제어용 양방향 3단자 스위칭 소자는 TRIAC입니다.","x":["FET가 아닙니다.","정답. TRIAC","UJT가 아닙니다.","SSS는 2단자 소자입니다."],"t":"TRIAC = 양방향 3단자"},"2022-2-기관3-24":{"w":"역방향 항복전압에서 큰 전류가 흐르고 전압이 거의 일정하게 유지되어 정전압 회로에 쓰이는 소자는 제너 다이오드입니다.","x":["일반 다이오드가 아닙니다.","LED가 아닙니다.","정답. 제너 다이오드","포토 다이오드가 아닙니다."],"t":"제너 = 정전압"},"2022-2-기관3-25":{"w":"PLC 스캔 타임은 입력을 읽고 전체 프로그램을 한 번 실행해 출력을 내기까지 걸리는 시간입니다.","x":["클럭 주기가 아닙니다.","정답. 전체 프로그램 1회 실행 시간","틀립니다.","틀립니다."],"t":"스캔 타임 = 프로그램 1회전"},"2022-2-직무일반-2":{"w":"전기용접 때는 보호복·안전화를 입고, 눈을 보호하며, 끝나면 전류를 차단합니다. 용접 연기와 가스가 차지 않도록 통풍은 유지해야 합니다.","x":["맞습니다.","맞습니다.","정답(옳지 않은 것). 통풍은 유지합니다.","맞습니다."],"t":"용접 = 통풍 유지"},"2022-2-직무일반-3":{"w":"산소결핍 장소는 환기 후 산소 농도를 확인하고, 2인 1조로 작업하며, 감시원을 둡니다. 전원을 모두 끄면 환기·조명도 멈춰 위험합니다.","x":["맞습니다.","맞습니다.","맞습니다.","정답(옳지 않은 것). 환기·조명 전원은 필요합니다."],"t":"산소결핍 작업 = 환기·2인 1조·감시원"},"2022-2-직무일반-6":{"w":"선내 소각기는 출구 연소가스 온도를 850[℃] 이상 1,200[℃] 미만으로 유지해야 합니다.","x":["틀립니다.","정답. 850~1,200[℃]","기준값이 다릅니다.","기준값이 다릅니다."],"t":"소각기 = 850~1,200℃"},"2022-2-직무일반-7":{"w":"해양오염방지장치는 기름여과장치, 폐유소각기, 분뇨처리장치 등입니다. 유청정기는 연료·윤활유를 깨끗이 하는 장치입니다.","x":["정답(아닌 것). 유청정기","오염방지장치입니다.","오염방지장치입니다.","오염방지장치입니다."],"t":"청정기 ≠ 오염방지장치"},"2022-2-직무일반-8":{"w":"오존층파괴물질기록부에는 수급, 충전, 육상 배출, 수리 등을 기록합니다. 보관장소 변경은 기재 사항이 아닙니다.","x":["기재합니다.","정답(아닌 것). 보관장소 변경","기재합니다.","기재합니다."],"t":"보관장소 변경 = 기재 안 함"},"2022-2-직무일반-9":{"w":"유면 검출기는 기름층의 두께(유수 경계면)를 검출해 배유밸브를 여는 신호를 줍니다. 멈춤은 타이머가 합니다. 기름 '농도'를 재는 것은 빌지 경보기(15ppm)입니다.","x":["맞습니다.","맞습니다.","정답(적절하지 않은 것). 유면검출기는 경계면을 검출합니다.","맞습니다."],"t":"유면검출기 = 경계면, 15ppm 경보기 = 농도"},"2022-2-직무일반-11":{"w":"화상 부위의 물집은 감염을 막아 주므로 터뜨리면 안 됩니다.","x":["맞습니다.","맞습니다.","맞습니다.","정답(옳지 않은 것). 물집을 터뜨리지 않습니다."],"t":"화상 물집 = 터뜨리지 않기"},"2022-2-직무일반-12":{"w":"동상 부위는 미지근한 물(약 40[℃])에 담가 서서히 녹입니다. 문지르거나 불에 직접 쬐면 조직이 손상됩니다.","x":["찬물은 효과가 없습니다.","문지르면 조직이 상합니다.","직접 불은 화상 위험이 있습니다.","정답. 미지근한 물"],"t":"동상 = 미지근한 물로 서서히"},"2022-2-직무일반-13":{"w":"개방성 상처의 출혈 부위는 심장보다 높게 들어 올려 출혈을 줄입니다.","x":["맞습니다.","맞습니다.","정답(옳지 않은 것). 심장보다 높게 합니다.","맞습니다."],"t":"출혈 = 심장보다 높게"},"2022-2-직무일반-18":{"w":"열작업 때는 반대편 격실에도 감시원을 두고, 가스 용기를 세우고, 혼자 작업하지 않습니다. 작업 구역은 통풍이 되어야 하므로 개폐구를 모두 닫아 두는 것은 옳지 않습니다.","x":["맞습니다.","맞습니다.","맞습니다.","정답(옳지 않은 것). 통풍을 유지합니다."],"t":"열작업 = 통풍·감시원"},"2022-2-직무일반-20":{"w":"CO₂를 방출하기 전에는 모든 인원을 철수시키고, 문을 닫고, 통풍을 차단합니다. 방출량은 설비 설계 때 정해져 있어 그때 계산하지 않습니다.","x":["합니다.","합니다.","합니다.","정답(옳지 않은 것). 방출량은 이미 정해져 있습니다."],"t":"CO₂ 방출 전 = 인원 철수·밀폐"},"2022-2-직무일반-23":{"w":"선박법은 국적, 톤수 측정·등록, 한국선박의 권리·의무 등을 정합니다. 안전설비는 선박안전법의 내용입니다.","x":["선박법입니다.","정답(아닌 것). 안전설비는 선박안전법","선박법입니다.","선박법입니다."],"t":"안전설비 = 선박안전법"},"2022-2-직무일반-24":{"w":"선원법은 근로계약, 근로시간, 재해보상 등 선원의 근로조건을 정합니다. 선박직원의 승무기준은 선박직원법의 내용입니다.","x":["정답(아닌 것). 승무기준은 선박직원법","선원법입니다.","선원법입니다.","선원법입니다."],"t":"승무기준 = 선박직원법"},"2022-2-영어-1":{"w":"\"검사관의 내부 검사를 위해 연료유 탱크를 가스 프리하고 청소할 것.\"","x":["데운","보충한","정답. gasfreed","충전한"],"t":"gas free = 가스 제거"},"2022-2-영어-3":{"w":"절연저항 = insulation resistance 입니다.","x":["틀립니다.","틀립니다.","정답. insulation resistance","틀립니다."],"t":"insulation resistance"},"2022-2-영어-4":{"w":"발전기관은 선박에 전력(electric power)과 조명(lighting)을 공급합니다.","x":["틀립니다.","틀립니다.","정답. electric power, lighting","틀립니다."],"t":"generator = power & lighting"},"2022-2-영어-5":{"w":"SOPEP = Shipboard Oil Pollution Emergency Plan(선박해양오염비상계획서)입니다.","x":["틀립니다.","틀립니다.","정답. Shipboard Oil Pollution Emergency Plan","틀립니다."],"t":"SOPEP"},"2022-2-영어-7":{"w":"\"1번 공기 냉각기의 새는 부분을 수리했다.\" repair = 수리하다.","x":["측정했다","정답. Repaired","옮겼다","받았다"],"t":"repaired leaky parts"},"2022-2-영어-8":{"w":"ascertain(확인하다) ≒ confirm.","x":["조정했다","퍼냈다","정답. Confirmed","발견했다"],"t":"ascertained ≒ confirmed"},"2022-2-영어-9":{"w":"\"대리점을 통해(through) 연료유 500톤을 주문했지요?\"","x":["정답. through = ~을 통해","during = ~동안","before = ~전에","after = ~후에"],"t":"through agent = 대리점을 통해"},"2022-2-영어-14":{"w":"Hydraulic power systems = 유압장치 입니다.","x":["정답. 유압장치","전동구동장치가 아닙니다.","자동제어장치가 아닙니다.","공기압장치는 pneumatic입니다."],"t":"hydraulic = 유압"},"2022-2-영어-17":{"w":"벌류트 펌프를 기동하기 위해 물을 붓는 것을 Priming(마중물 넣기)이라 합니다.","x":["Sounding = 측심","정답. Priming","Warming = 난기","Turning = 터닝"],"t":"priming = 마중물"},"2022-2-영어-18":{"w":"밸러스트 계통은 배의 트림을 적절히 유지하는 데 필요합니다.","x":["정답. 트림 유지","냉각수 공급은 해수 계통입니다.","해당하지 않습니다.","해당하지 않습니다."],"t":"ballast = 트림·경사 조정"},"2022-2-영어-22":{"w":"탱크 바닥부터 기름 윗면까지 재는 것은 Bottom sounding, 측심관 윗면에서 기름 윗면까지 재는 것은 Ullage sounding입니다.","x":["정답. A: Bottom, B: Ullage","반대입니다.","틀립니다.","틀립니다."],"t":"ullage = 빈 공간 깊이"},"2022-2-영어-23":{"w":"선박의 주기관·보조기관 시동 공기압은 약 2.5~3.0[MPa](25~30[bar])입니다.","x":["너무 낮습니다.","너무 높습니다.","너무 낮습니다.","정답. 2.5~3.0[MPa]"],"t":"시동공기 ≒ 30bar"},"2022-2-영어-24":{"w":"보일러 연도(uptake)에 설치해 배기가스 흐름을 조절하는 장치는 댐퍼(damper)입니다.","x":["정답. damper","수트 블로어는 그을음 제거","버너는 연소 장치","송풍기는 통풍 장치"],"t":"damper = 가스 흐름 조절"},"2022-3-기관1-5":{"w":"배기가 검은색이 되는 원인은 불완전 연소, 과부하, 연소 공기량 부족(소기 압력 저하) 등입니다. 소기 압력이 높으면 공기가 충분해 오히려 연소가 좋아집니다.","x":["정답(옳지 않은 것). 소기 압력이 높으면 연소가 좋습니다.","원인입니다.","원인입니다.","원인입니다."],"t":"흑색 배기 = 공기 부족·과부하"},"2022-3-기관1-9":{"w":"오일 스크레이퍼링(오일링)은 라이너 벽의 윤활유를 긁어내려 연소실로 올라가는 것을 막고 라이너 내벽에 고르게 분포시킵니다. 압축링은 가스 기밀과 피스톤 열을 라이너로 전달합니다.","x":["열은 피스톤에서 실린더(라이너) 쪽으로 방출합니다.","압축링은 연소가스의 누설을 막습니다.","연소실로 들어가는 것을 막습니다.","정답. 윤활유를 고르게 분포"],"t":"오일링 = 윤활유 분포·긁어내림"},"2022-3-기관1-20":{"w":"프로펠러 날개 끝과 선체 사이의 간격을 두기 위해 날개를 선미 방향으로 약 10~15° 기울입니다(레이크).","x":["선수 방향이 아닙니다.","우현 방향이 아닙니다.","좌현 방향이 아닙니다.","정답. 선미 방향 10~15°"],"t":"레이크 = 선미 쪽 10~15°"},"2022-3-기관1-22":{"w":"연료유의 주성분은 탄소(C)와 수소(H)입니다(탄화수소).","x":["질소는 주성분이 아닙니다.","정답. C와 H","산소는 주성분이 아닙니다.","질소는 주성분이 아닙니다."],"t":"연료유 = 탄화수소(C, H)"},"2022-3-기관1-23":{"w":"윤활유는 항유화성이 크고, 유성이 좋고, 점도가 적당하며, 응고점이 낮아야 합니다.","x":["맞습니다.","정답(옳지 않은 것). 응고점은 낮아야 합니다.","맞습니다.","맞습니다."],"t":"윤활유 = 응고점 낮게"},"2022-3-기관1-25":{"w":"마찰부의 불순물을 씻어 내 깨끗하게 하는 것은 윤활유의 청정작용입니다.","x":["감마작용은 마찰 감소입니다.","방청작용은 녹 방지입니다.","정답. 청정작용","기밀작용은 가스 누설 방지입니다."],"t":"청정작용 = 불순물 제거"},"2022-3-기관2-1":{"w":"셀프젝터 청정기는 정상 청정 중에는 저압수(작동수)를 공급해 회전통을 닫아 두고, 슬러지를 배출할 때는 고압수를 공급해 회전통을 엽니다.","x":["정답. 청정 중 = 저압수 공급, 고압수 차단","반대입니다.","배출 시에는 고압수를 공급합니다.","배출 시에는 고압수를 공급합니다."],"t":"저압수 = 닫힘, 고압수 = 열림(배출)"},"2022-3-기관2-4":{"w":"어큐뮬레이터(축압기)는 유압 에너지를 저장했다가 필요할 때 내보내는 기기로, 맥동·충격 흡수와 보조 동력원 역할을 합니다. 저압 대유량을 고압 소유량으로 바꾸는 것은 증압기입니다.","x":["맞습니다.","맞습니다.","맞습니다.","정답(옳지 않은 것). 증압기의 설명입니다."],"t":"어큐뮬레이터 = 압력 저장"},"2022-3-기관2-5":{"w":"왕복펌프는 흡입 성능이 좋고, 운전 조건이 변해도 효율 변화가 적지만, 송출이 불균일합니다. 소용량 고압용이며 대용량 저압용은 원심·축류펌프입니다.","x":["특징입니다.","정답(아닌 것). 왕복펌프는 소용량 고압용입니다.","특징입니다.","특징입니다."],"t":"왕복펌프 = 소용량·고압"},"2022-3-기관2-7":{"w":"원심펌프의 기계적 손실은 베어링·축봉부의 마찰 손실입니다. 안내 날개·케이싱 손실은 수력 손실, 역류 손실은 누설(체적) 손실입니다.","x":["정답. 베어링 마찰 손실","수력 손실입니다.","수력 손실입니다.","누설 손실입니다."],"t":"기계 손실 = 베어링·패킹 마찰"},"2022-3-기관2-14":{"w":"암모니아는 증발잠열이 크지만, 수분이 있으면 구리합금을 부식시키고 독성·자극성 냄새가 있으며, 물에 잘 녹아 새면 식품을 상하게 할 수 있습니다.","x":["맞습니다.","맞습니다.","맞습니다.","정답(옳지 않은 것). 암모니아는 물에 잘 흡수됩니다."],"t":"암모니아 = 물에 잘 녹음, 동 부식"},"2022-3-기관2-16":{"w":"어미자 눈금 1[mm]를 아들자 20등분으로 읽는 버니어 캘리퍼스의 최소 측정값은 1 ÷ 20 = 0.05[mm]입니다.","x":["틀립니다.","아들자 한 눈금의 실제 길이(19/20)입니다.","틀립니다.","정답. 0.05[mm]"],"t":"20등분 버니어 = 0.05mm"},"2022-3-기관2-17":{"w":"가열 후 노 안에서 천천히 식혀 재료를 무르게 하고 내부 응력을 없애는 열처리는 풀림입니다.","x":["뜨임은 담금질 후 인성을 주는 처리입니다.","담금질은 급랭 경화입니다.","불림은 공기 중 냉각입니다.","정답. 풀림(노냉)"],"t":"풀림 = 노 안에서 서냉"},"2022-3-기관2-20":{"w":"용접 이음은 리벳·볼트 이음보다 재료와 공수가 절약되고 이음 효율(강도)이 높습니다. 잔류 응력과 경화는 오히려 단점입니다.","x":["가장 큰 장점이 아닙니다.","잔류 응력은 단점입니다.","정답. 재료·공수 절감, 이음효율 높음","경화는 균열 원인이 되는 단점입니다."],"t":"용접 = 이음효율↑"},"2022-3-기관2-21":{"w":"계약 단계의 기본 설계 도면은 일반 배치도, 중앙 횡단면도, 외판 전개도 등입니다. 선저 구조도는 상세 설계 단계 도면입니다.","x":["기본 설계 도면입니다.","기본 설계 도면입니다.","정답(아닌 것). 상세 설계 도면입니다.","기본 설계 도면입니다."],"t":"기본 설계 = 일반배치도·중앙횡단면도"},"2022-3-기관2-23":{"w":"아르키메데스의 원리에 따라 부력의 크기는 물체가 밀어낸 물의 무게와 같습니다.","x":["정답. 같다","틀립니다.","틀립니다.","틀립니다."],"t":"부력 = 배제한 물의 무게"},"2022-3-기관2-25":{"w":"기계의 설치 위치를 나타내는 도면은 배치도입니다.","x":["부품도는 부품 하나를 그린 도면입니다.","배선도는 전선 도면입니다.","배관도는 관 도면입니다.","정답. 배치도"],"t":"배치도 = 위치"},"2022-3-기관3-5":{"w":"유도전동기의 회전자는 항상 회전자계(동기속도)보다 조금 느리게 돕니다.","x":["정답. 회전자계가 더 빠름","반대입니다.","같으면 토크 0","틀립니다."],"t":"동기속도 > 회전자 속도"},"2022-3-기관3-7":{"w":"같은 1,000[W]를 쓰려면 ①(1,000V)은 1[A], ②(100V)는 10[A]가 흐릅니다. 선로 손실 I²R은 ①이 1[W], ②가 100[W]로 ②가 더 큽니다.","x":["전류가 달라 전압강하도 다릅니다.","②의 전류가 더 큽니다.","정답. ②의 선로 손실이 더 큼","열량은 ②가 더 큽니다."],"t":"고전압 송전 = 손실↓"},"2022-3-기관3-8":{"w":"평형 3상 교류는 크기가 같고 120°씩 차이 나므로 세 상의 순시값을 더하면 항상 0입니다.","x":["정답. 0","틀립니다.","틀립니다.","틀립니다."],"t":"평형 3상 합 = 0"},"2022-3-기관3-10":{"w":"XL = XC 이면 서로 상쇄되어 Z = R = 100[Ω]입니다(직렬 공진).","x":["0이 아닙니다.","정답. 100[Ω]","틀립니다.","모두 더한 값입니다."],"t":"공진 시 Z = R"},"2022-3-기관3-12":{"w":"Z = √(8² + 6²) = 10[Ω], I = 100 ÷ 10 = 10[A]입니다.","x":["틀립니다.","틀립니다.","틀립니다.","정답. 10[A]"],"t":"6-8-10 삼각형"},"2022-3-기관3-13":{"w":"전구가 콘덴서와 병렬로 연결되어 있어, 스위치를 닫는 순간 빈 콘덴서가 전류를 받아들여 전구 양단 전압이 0입니다. 콘덴서가 충전되며 전압이 올라가 전구가 서서히 밝아집니다.","x":["틀립니다.","정답. 꺼진 상태에서 서서히 밝아짐","전구가 콘덴서와 직렬일 때입니다.","결국 켜집니다."],"t":"C와 병렬 전구 = 서서히 밝아짐"},"2022-3-기관3-14":{"w":"오른쪽 5 + 5 = 10[Ω]이 가운데 10[Ω]과 병렬이면 5[Ω]. 전체 10 + 5 = 15[Ω], I1 = 15 ÷ 15 = 1[A]. 두 가지 저항이 같으므로 I2 = I3 = 0.5[A]입니다.","x":["틀립니다.","정답. 1, 0.5, 0.5[A]","틀립니다.","틀립니다."],"t":"같은 저항 병렬 = 전류 반씩"},"2022-3-기관3-15":{"w":"I = 10√2 sinωt 에서 최대값이 10√2[A]이므로 실효값 = 최대값 ÷ √2 = 10[A]입니다.","x":["정답. 10[A]","최대값입니다.","틀립니다.","틀립니다."],"t":"실효값 = 최대값 / √2"},"2022-3-기관3-16":{"w":"그림은 (+)와 (−)를 차례로 이은 직렬 연결입니다. 직렬은 전압이 더해져 36[V], 용량은 그대로 80[Ah]입니다.","x":["축전지 1개입니다.","병렬 연결입니다.","정답. 36[V], 80[Ah]","틀립니다."],"t":"직렬 = 전압 합, 용량 그대로"},"2022-3-기관3-17":{"w":"PB1을 누르면 타이머 T가 여자되고 자기유지됩니다. RL은 T의 한시 b접점에 연결되어 켜져 있다가 설정 시간 2초 후 T-b가 열려 꺼집니다(GL은 T-a가 닫혀 2초 후 켜짐). PB2는 정지 버튼입니다.","x":["틀립니다.","GL은 2초 후에 켜집니다.","정답. RL은 2초 후 꺼짐","PB2는 정지 버튼입니다."],"t":"한시 b접점 = 설정 시간 후 열림"},"2022-3-기관3-21":{"w":"중간 탭 변압기와 다이오드 2개를 쓴 전파 정류회로이므로 출력은 반원이 연속으로 이어진 파형입니다.","x":["정답이 아닙니다.","정답이 아닙니다.","정답. 전파 정류 파형","정답이 아닙니다."],"t":"중간탭 + 다이오드 2개 = 전파"},"2022-3-기관3-22":{"w":"다이오드 캐소드가 입력 쪽, 출력이 풀업 저항(+5V)에 연결되어 있어 입력 중 하나라도 0이면 출력이 0, 둘 다 1일 때만 1이 되는 AND 회로입니다.","x":["정답. AND","NAND가 아닙니다.","OR가 아닙니다.","NOR가 아닙니다."],"t":"다이오드 + 풀업 = AND"},"2022-3-기관3-23":{"w":"연산증폭기는 이득이 매우 커서 V1(−입력) > V2(+입력)이면 출력이 음의 전원 전압(−15[V])으로 포화됩니다. 출력은 전원 전압을 넘을 수 없습니다.","x":["전원 전압을 넘을 수 없습니다.","정답. V1 > V2 → −15[V]","30[V]는 나올 수 없습니다.","틀립니다."],"t":"비교기 출력 = ±전원 전압"},"2022-3-기관3-24":{"w":"전압 이득[dB] = 20 log(증폭률) = 20 × log100 = 20 × 2 = 40[dB]입니다.","x":["10배일 때입니다.","정답. 40[dB]","1,000배일 때입니다.","틀립니다."],"t":"dB = 20 log A"},"2022-3-직무일반-5":{"w":"황천 때는 이동물을 고정하고, 조속기 상태와 배기 온도 변화에 주의합니다. 냉각수 팽창탱크는 적정 수위로 유지하며 가득 채우지 않습니다(팽창 여유 필요).","x":["맞습니다.","맞습니다.","정답(옳지 않은 것). 팽창탱크는 가득 채우지 않습니다.","맞습니다."],"t":"팽창탱크 = 여유 공간 필요"},"2022-3-직무일반-9":{"w":"NOx는 질소산화물입니다.","x":["틀립니다.","틀립니다.","황산화물은 SOx입니다.","정답. 질소산화물"],"t":"NOx 질소, SOx 황"},"2022-3-직무일반-17":{"w":"감전 사고 때는 전원을 차단하고, 구조자가 추가 감전되지 않게 주의하며, 호흡이 없으면 인공호흡을 합니다. 비상발전기로 전환하는 것은 응급조치가 아닙니다.","x":["맞습니다.","정답(옳지 않은 것). 전원 전환은 조치가 아닙니다.","맞습니다.","맞습니다."],"t":"감전 = 전원 차단 → 구조 → 인공호흡"},"2022-3-직무일반-18":{"w":"정전기를 막으려면 접지하고, 마찰을 줄이고, 합성섬유 옷을 피하며, 전도성 물질을 씁니다. 비전도성 물질은 정전기를 쌓이게 합니다.","x":["대책입니다.","정답(옳지 않은 것). 비전도성 물질은 정전기를 쌓습니다.","대책입니다.","대책입니다."],"t":"정전기 = 접지·전도성"},"2022-3-직무일반-23":{"w":"선원법상 선원에게 임의의 24시간 동안 10시간 이상의 휴식시간을 주어야 합니다.","x":["틀립니다.","정답. 10시간","틀립니다.","틀립니다."],"t":"휴식 = 24시간 중 10시간 이상"},"2022-3-직무일반-25":{"w":"유조선 화물구역의 기름 섞인 물은 항해 중일 것, 순간 배출률 1해리당 30리터 이하, 총량이 화물의 3만분의 1 이하, 그리고 영해 기선에서 50해리 이상 떨어진 곳에서 배출해야 합니다.","x":["기준입니다.","기준입니다.","정답(옳지 않은 것). 50해리 이상입니다.","기준입니다."],"t":"유조선 화물구역 배출 = 50해리 이상"},"2022-3-영어-2":{"w":"2행정 기관은 크랭크축 1회전(one revolution)에 1사이클을 마칩니다.","x":["틀립니다.","정답. One revolution","4행정입니다.","틀립니다."],"t":"2행정 = 1회전, 4행정 = 2회전"},"2022-3-영어-3":{"w":"indicator card(지압도)는 압력-부피 선도(P-V diagram)입니다.","x":["분사시기 선도가 아닙니다.","틀립니다.","정답. Pressure - volume diagram","틀립니다."],"t":"indicator card = P-V 선도"},"2022-3-영어-4":{"w":"액체에 에너지를 주어 압력을 높이고 이동시키는 장치는 Pump입니다.","x":["정답. Pump","Pipe = 관","Cooler = 냉각기","Evaporator = 증발기"],"t":"pump"},"2022-3-영어-6":{"w":"실린더 안 가스 온도는 연소가 일어나는 작동(working) 행정에서 가장 높습니다.","x":["흡입이 아닙니다.","압축이 아닙니다.","정답. working","배기가 아닙니다."],"t":"최고 온도 = 작동행정"},"2022-3-영어-7":{"w":"오일 미스트 검출기는 크랭크실 안 유증기의 농도(concentration)가 발화 전 위험 수준에 이르면 경보를 울리고 감속시킵니다.","x":["연소가 아닙니다.","정답. concentration = 농도","증발이 아닙니다.","응축이 아닙니다."],"t":"mist concentration = 유증기 농도"},"2022-3-영어-8":{"w":"보일러 압력을 방출해 폭발을 막는 것은 Safety valve(안전밸브)입니다.","x":["역지밸브","정답. Safety valve","Relief valve는 주로 액체용","바이패스 밸브"],"t":"보일러 = safety valve"},"2022-3-영어-11":{"w":"\"주기관 시동 실패로 ( )을(를) 점검했다\" — 공기탱크 압력, 시동공기밸브, 시동공기 분배기는 점검 대상이지만 시동공기의 습도는 시동 실패 점검 항목이 아닙니다.","x":["정답(적절하지 않은 것). 습도","점검합니다.","점검합니다.","점검합니다."],"t":"시동 실패 = 공기압·시동밸브·분배기"},"2022-3-영어-12":{"w":"조수장치에서 증기로 해수를 가열해 증발시키는 열교환기는 Evaporator(증발기)입니다.","x":["정답. Evaporator","진공 차단기","절탄기","응축기"],"t":"evaporator = 조수기 증발기"},"2022-3-영어-16":{"w":"유조선 탱크를 대기와 완전히 격리해 보호하는 방법은 불활성 가스(inert gas)입니다.","x":["오일 미스트가 아닙니다.","원유가 아닙니다.","정답. inert gas","독성가스가 아닙니다."],"t":"IGS = 탱크 보호"},"2022-3-영어-17":{"w":"유도전동기(Induction motor)는 여자전류 때문에 지상(뒤진) 역률을 만듭니다.","x":["정답. Induction motor","직류기는 역률이 없습니다.","직류기입니다.","직류기입니다."],"t":"유도전동기 = 지상 역률"},"2022-3-영어-18":{"w":"급유관 = filling pipe, 수리할 것 = to be repaired. \"Port side F.O. filling pipe to be repaired.\"","x":["sounding은 측심입니다.","정답. filling, repaired","틀립니다.","replaced는 교체입니다."],"t":"filling pipe = 주입관"},"2022-3-영어-19":{"w":"\"1번 주윤활유 펌프를 재조립하고 작동 상태(working condition)에서 시험할 것.\"","x":["틀립니다.","틀립니다.","틀립니다.","정답. working condition"],"t":"tested under working condition"},"2022-3-영어-20":{"w":"\"검사를 위해 개방 정비하고 오일 간극을 조정할 것\" — 메인·크랭크핀·크로스헤드 베어링은 오일 간극(유막 틈새)을 조정하는 평베어링이지만, 볼 베어링은 간극 조정 대상이 아닙니다.","x":["정답(적절하지 않은 것). Ball bearing","해당합니다.","해당합니다.","해당합니다."],"t":"oil clearance = 평베어링"},"2022-4-기관1-3":{"w":"후연소가 길어지면 연소가 늦게까지 이어져 배기온도가 오르고, 연료소비율이 늘며, 기관이 과열되고 배기색이 나빠집니다.","x":["배기온도는 올라갑니다.","연료소비율은 늘어납니다.","배기색은 검어집니다.","정답. 기관이 과열됩니다."],"t":"후연소↑ = 과열·배기온도↑"},"2022-4-기관1-4":{"w":"과급하면 같은 기관에서 출력이 늘고, 출력당 중량이 줄며, 평균유효압력이 높아집니다.","x":["가벼워집니다.","관계없습니다.","정답. 출력 증대","높아집니다."],"t":"과급 = 출력↑"},"2022-4-기관1-5":{"w":"플런저가 압축을 시작해 분사밸브가 열려 분사가 시작될 때까지의 기간을 분사 지연 기간이라 합니다.","x":["착화 지연은 분사 후 착화까지입니다.","제어 연소 기간이 아닙니다.","정답. 분사 지연 기간","후연소 기간이 아닙니다."],"t":"분사 지연 = 펌프 압축 ~ 분사 시작"},"2022-4-기관1-8":{"w":"피스톤 평균속도 = 2 × 행정 × 매분 회전수 ÷ 60 [m/s]입니다(1회전에 2행정).","x":["2를 곱하지 않았습니다.","정답. 2LN / 60","틀립니다.","틀립니다."],"t":"Vm = 2LN / 60"},"2022-4-기관1-10":{"w":"성능 곡선에는 회전수, 연료소비율, 압축·최고압력, 배기온도 등이 나오며, 연료분사시기는 포함되지 않습니다.","x":["포함됩니다.","포함됩니다.","포함됩니다.","정답(아닌 것). 연료분사시기"],"t":"성능곡선 ≠ 분사시기"},"2022-4-기관1-13":{"w":"보일러 효율은 증기 발생에 실제로 쓰인 열량을 연료의 총 발열량으로 나눈 비율입니다.","x":["전열면적은 면적입니다.","증발량은 증기 양입니다.","보일러 마력은 능력 단위입니다.","정답. 보일러 효율"],"t":"보일러 효율 = 유효열 / 공급열"},"2022-4-기관1-14":{"w":"복수장치(복수기)는 배기압력을 진공으로 낮춰 열효율을 높이고, 증기를 물로 되돌려 급수로 회수합니다.","x":["조속장치는 속도 조절용입니다.","정답. 복수장치","증발장치가 아닙니다.","팽창장치가 아닙니다."],"t":"복수기 = 진공 + 급수 회수"},"2022-4-기관1-15":{"w":"증기를 보낼 때는 드레인을 빼고, 증기밸브를 조금만 열어 증기관을 서서히 데운 뒤(난기) 천천히 열어 수격작용을 막습니다. 처음부터 완전히 열면 수격작용이 생깁니다.","x":["정답(옳지 않은 것). 밸브는 조금씩 엽니다.","드레인을 뺍니다.","충분히 난기합니다.","서서히 엽니다."],"t":"송기 = 드레인 → 난기 → 서서히 개방"},"2022-4-기관1-16":{"w":"역전장치에는 직접 역전(캠축 이동식 등)과 간접 역전(역전기어, 가변 피치 프로펠러)이 있습니다. 대형 선박은 주로 기관 자체를 역회전시키는 직접 역전방식을 씁니다.","x":["맞습니다.","맞습니다.","정답(옳지 않은 것). 대형선은 직접 역전입니다.","맞습니다."],"t":"대형 저속기관 = 직접 역전"},"2022-4-기관1-18":{"w":"대형 선박에는 미첼형(세그먼트형) 추력 베어링을 주로 씁니다.","x":["말굽형은 옛 형식입니다.","상자형은 소형선용입니다.","정답. 미첼형","해당하지 않습니다."],"t":"추력 베어링 = 미첼형"},"2022-4-기관1-19":{"w":"추진 축계는 프로펠러축, 추력축, 중간축으로 이루어집니다. 캠축은 기관 내부 부품입니다.","x":["구성 요소입니다.","구성 요소입니다.","구성 요소입니다.","정답(아닌 것). 캠축"],"t":"캠축 = 기관 부품"},"2022-4-기관1-21":{"w":"디젤 연료의 착화성은 세탄가로 나타냅니다. 옥탄가는 가솔린의 노킹 저항성입니다.","x":["옥탄가는 가솔린용입니다.","헵탄가는 없습니다.","정답. 세탄가","전산가는 산성도입니다."],"t":"디젤 = 세탄가, 가솔린 = 옥탄가"},"2022-4-기관1-23":{"w":"윤활유가 밖에서 오염되어 열화되는 원인은 냉각수, 연료유, 먼지 혼입 등입니다. 새 윤활유 보충은 열화 원인이 아닙니다.","x":["원인입니다.","원인입니다.","원인입니다.","정답(아닌 것). 새 윤활유 보충"],"t":"열화 = 외부 오염"},"2022-4-기관1-24":{"w":"1,000리터 물은 1,000[kg]이므로 비중 0.95인 기름 1,000리터는 950[kg]입니다.","x":["틀립니다.","틀립니다.","틀립니다.","정답. 950[kg]"],"t":"무게 = 부피 × 비중"},"2022-4-기관2-1":{"w":"한쪽으로만 물을 빨아들이는 편흡입 임펠러는 앞뒤 압력 차가 커서 축 추력이 생기기 쉽습니다. 양흡입, 평형공, 스러스트 베어링은 추력 대책입니다.","x":["추력이 상쇄됩니다.","추력 대책입니다.","추력 대책입니다.","정답. 편흡입 임펠러"],"t":"편흡입 = 축 추력 발생"},"2022-4-기관2-8":{"w":"저압 침관형 조수장치는 먼저 이젝터 펌프를 돌려 조수기 안을 진공으로 만든 뒤, 해수를 넣고 가열합니다.","x":["진공을 만든 뒤 합니다.","진공을 만든 뒤 합니다.","정답. 먼저 진공","진공을 만든 뒤 합니다."],"t":"조수기 기동 = 진공 먼저"},"2022-4-기관2-9":{"w":"운전 중 자동으로 슬러지를 배출할 수 있어 선박에서 가장 많이 쓰는 것은 셀프젝터형 청정기입니다.","x":["정답. 셀프젝터","샤플레스는 분해 청소형입니다.","드라발은 분해 청소형입니다.","틀립니다."],"t":"자동 배출 = 셀프젝터"},"2022-4-기관2-13":{"w":"물질이 가진 전체 에너지(내부 에너지 + 압력×부피)를 엔탈피라 합니다.","x":["정답. 엔탈피","엔트로피는 무질서도입니다.","성적계수는 냉동기 효율입니다.","비엔트로피는 단위 질량당 엔트로피입니다."],"t":"엔탈피 = 전체 열에너지"},"2022-4-기관2-15":{"w":"습공기의 수증기 분압과 같은 온도의 포화 수증기 분압의 비[%]를 상대습도라 합니다.","x":["절대습도는 수증기 kg/건공기 kg입니다.","정답. 상대습도","비교습도는 절대습도의 비입니다.","포화도는 비교습도와 같습니다."],"t":"상대습도 = 분압 비"},"2022-4-기관2-18":{"w":"높이를 재는 게이지는 하이트 게이지입니다.","x":["다이얼 게이지는 변위를 잽니다.","정답. 하이트 게이지","블록 게이지는 기준 치수 블록입니다.","스트레인 게이지는 변형률을 잽니다."],"t":"하이트 = 높이"},"2022-4-기관2-19":{"w":"탄산가스(CO₂) 아크 용접은 와이어가 연속으로 공급되어 연속 용접이 가능하므로 생산성이 높습니다. 실드가스는 CO₂이고, 전류 밀도가 높으며, 스패터는 많은 편입니다.","x":["아르곤·헬륨은 TIG·MIG용입니다.","스패터가 많습니다.","전류 밀도가 높습니다.","정답. 연속 용접, 생산성 높음"],"t":"CO₂ 용접 = 와이어 연속 공급"},"2022-4-기관2-23":{"w":"수면 아랫부분이 받는 물의 저항은 마찰저항, 조파저항, 와류저항입니다. 공기저항은 수면 위 부분에 작용합니다.","x":["정답. ①, ②, ③","공기저항은 수면 위입니다.","공기저항은 수면 위입니다.","공기저항은 수면 위입니다."],"t":"수면 아래 = 마찰·조파·와류"},"2022-4-기관2-25":{"w":"부품의 제조 과정(공정)을 나타내는 도면은 공정도입니다.","x":["조립도는 조립 상태를 나타냅니다.","정답. 공정도","기초도는 기초 구조를 나타냅니다.","배치도는 위치를 나타냅니다."],"t":"공정도 = 제조 과정"},"2022-4-기관3-1":{"w":"인덕턴스만의 회로에서는 전류가 전압보다 90° 늦습니다. 전압(V)을 오른쪽으로 두면 전류(I)는 아래로 향하는 ㉯입니다.","x":["위상이 같은 R 회로입니다.","정답. 전류 90° 늦음","전류가 앞선 C 회로입니다.","RL 회로입니다."],"t":"L = 전류 90° 늦음"},"2022-4-기관3-3":{"w":"마이크로(μ) = 10⁻⁶ 입니다. 1[μA] = 10⁻⁶[A]입니다.","x":["정답. 10⁻⁶배","메가(M)입니다.","킬로(k)입니다.","밀리(m)입니다."],"t":"μ = 10⁻⁶, m = 10⁻³"},"2022-4-기관3-5":{"w":"열선 길이를 절반으로 하면 저항이 절반이 됩니다. P = V²/R 이므로 같은 전압에서 전력은 2배, 2[kW]가 됩니다.","x":["틀립니다.","틀립니다.","틀립니다.","정답. 2[kW]"],"t":"R 절반 → P 2배"},"2022-4-기관3-8":{"w":"i = 5√2 sinωt 에서 sin 앞의 5√2가 최대값입니다.","x":["틀립니다.","틀립니다.","실효값입니다.","정답. 5√2[A]"],"t":"sin 앞 계수 = 최대값"},"2022-4-기관3-9":{"w":"P = V × I × 역률 = 100 × 1 × 0.8 = 80[W]입니다.","x":["틀립니다.","정답. 80[W]","피상전력입니다.","틀립니다."],"t":"P = VI cosθ"},"2022-4-기관3-10":{"w":"농형 회전자는 회전자 철심, 도체 막대, 단락환, 통풍 날개로 이루어집니다. 슬립링은 권선형 회전자에 있습니다.","x":["정답(아닌 것). 슬립링은 권선형","구성 요소입니다.","구성 요소입니다.","구성 요소입니다."],"t":"농형 = 슬립링 없음"},"2022-4-기관3-11":{"w":"철심을 얇은 철판으로 성층하면 맴돌이 전류 손실이 줄어듭니다.","x":["히스테리시스 손실은 규소강으로 줄입니다.","정답. 맴돌이 전류 손실 감소","주목적이 아닙니다.","주목적이 아닙니다."],"t":"성층 = 와류손↓"},"2022-4-기관3-15":{"w":"변압기 정격 용량은 피상전력 단위인 [kVA]로 나타냅니다.","x":["무효전력 단위입니다.","전력량 단위입니다.","정답. [kVA]","유효전력 단위입니다."],"t":"변압기·발전기 용량 = kVA"},"2022-4-기관3-16":{"w":"축전지 단자 작업에 일반 강재 스패너를 쓰면 양극과 음극이 닿아 단락·불꽃이 생길 수 있으므로 절연 공구를 써야 합니다.","x":["맞습니다.","맞습니다.","맞습니다(바셀린 등).","정답(옳지 않은 것). 절연 공구를 씁니다."],"t":"축전지 작업 = 절연 공구"},"2022-4-기관3-17":{"w":"유도전동기의 회전자는 항상 회전자계 속도보다 조금 느립니다.","x":["정답. 회전자계가 더 빠름","반대입니다.","같으면 토크 0","틀립니다."],"t":"동기속도 > 회전자"},"2022-4-기관3-22":{"w":"NPN 트랜지스터에서 베이스 전류와 컬렉터 전류가 합쳐져 이미터로 흘러 나갑니다(IE = IB + IC).","x":["방향이 틀립니다.","정답. IB + IC → IE","틀립니다.","틀립니다."],"t":"NPN = 이미터로 나감"},"2022-4-기관3-25":{"w":"FET는 다수 반송자 한 종류만으로 동작하는 유니폴라(단극성) 소자로, 전압으로 전류를 제어합니다. 접합형·MOS형, P채널·N채널이 있습니다.","x":["정답(옳지 않은 것). FET는 유니폴라입니다.","맞습니다.","맞습니다.","맞습니다."],"t":"FET = 유니폴라·전압 제어, BJT = 바이폴라·전류 제어"},"2022-4-직무일반-3":{"w":"황천 때는 출입문을 잠그고, 이동물을 고정하며, 부하 변동에 주의합니다. 과급공기 압력을 임의로 낮추면 연소가 나빠지므로 옳지 않습니다.","x":["맞습니다.","맞습니다.","정답(옳지 않은 것). 과급압력을 낮추지 않습니다.","맞습니다."],"t":"황천 = 고정·밀폐·부하 주의"},"2022-4-직무일반-5":{"w":"한국선급 검사는 연차, 중간, 정기, 입거검사 등입니다. 특별검사는 선급 검사 종류가 아닙니다.","x":["선급 검사입니다.","선급 검사입니다.","선급 검사입니다.","정답(아닌 것). 특별검사"],"t":"선급 = 정기·중간·연차·입거"},"2022-4-직무일반-6":{"w":"오존층파괴물질기록부는 프레온 등 오존층파괴물질에 대한 사항을 기록합니다. 황산화물은 연료유 공급서 등으로 관리합니다.","x":["맞습니다.","맞습니다.","맞습니다.","정답(옳지 않은 것). 오존층파괴물질을 기록합니다."],"t":"ODS 기록부 = 프레온 등"},"2022-4-직무일반-7":{"w":"연료유 수급 후 기관일지에는 수급량, 수급 시간, 비중·점도 등 사양을 기록합니다. 선장과 책임사관의 성명은 기록 항목이 아닙니다.","x":["기록합니다.","기록합니다.","정답(아닌 것). 성명은 기록하지 않습니다.","기록합니다."],"t":"수급 기록 = 양·시간·사양"},"2022-4-직무일반-8":{"w":"연료가 연소하면 질소산화물(NOx), 황산화물(SOx) 등이 생깁니다. 염화불화탄소(CFC)는 냉매 등에서 나옵니다.","x":["냉매에서 나옵니다.","정답. 질소산화물","냉매 등에서 나옵니다.","오염물질이 아닙니다."],"t":"연소 = NOx·SOx"},"2022-4-직무일반-9":{"w":"마쇄·소독하지 않은 분뇨는 4노트 이상으로 항해하며 영해기선에서 12해리 넘는 곳에서 서서히 배출합니다.","x":["틀립니다.","속력이 틀립니다.","거리가 틀립니다.","정답. 4노트, 12해리"],"t":"미처리 분뇨 = 4노트·12해리"},"2022-4-직무일반-13":{"w":"검역 감염병에는 콜레라, 페스트, 황열 등이 있습니다. 장티푸스는 검역 감염병이 아닙니다.","x":["검역 감염병입니다.","정답(아닌 것). 장티푸스","검역 감염병입니다.","검역 감염병입니다."],"t":"검역 = 콜레라·페스트·황열"},"2022-4-직무일반-14":{"w":"기관구역 기름기록부에는 선저폐수 처리, 연료유 탱크 세정·밸러스트, 유성잔류물 처리, 연료유 수급 등을 기록합니다. 선내 이송은 기록 사항이 아닙니다.","x":["기재합니다.","기재합니다.","정답(아닌 것). 선내 이송","기재합니다."],"t":"선내 이송 = 기록 안 함"},"2022-4-직무일반-19":{"w":"물은 증발열이 커서 냉각 효과가 가장 뛰어난 소화제입니다.","x":["정답. 물","포말은 질식 효과가 큽니다.","분말은 억제 효과가 큽니다.","드라이파우더는 금속 화재용입니다."],"t":"냉각 = 물"},"2022-4-직무일반-20":{"w":"만능노즐에 애플리케이터(연장관)를 끼워 물안개를 뿌리면 제1번 사수를 화염의 열로부터 보호할 수 있습니다.","x":["포말용입니다.","고정식 설비입니다.","정답. 애플리케이터","CO₂용입니다."],"t":"애플리케이터 = 물안개 연장관"},"2022-4-직무일반-22":{"w":"해기사 면허의 유효기간은 5년입니다.","x":["틀립니다.","틀립니다.","틀립니다.","정답. 5년"],"t":"해기사 면허 5년"},"2022-4-직무일반-25":{"w":"선박법은 국적, 등록, 톤수 측정을 규정합니다. 감항성은 선박안전법의 내용입니다.","x":["선박법입니다.","선박법입니다.","정답(아닌 것). 감항성은 선박안전법","선박법입니다."],"t":"감항성 = 선박안전법"},"2022-4-영어-3":{"w":"절연저항은 megger(메거)로 잽니다.","x":["후크형 전류계","전류계","전압계","정답. megger"],"t":"megger = 절연저항"},"2022-4-영어-6":{"w":"plummer block = 중간축 베어링(intermediate bearing)입니다.","x":["중간축이 아니라 베어링입니다.","정답. intermediate bearing","프로펠러축입니다.","추력 베어링입니다."],"t":"plummer block = 중간축 베어링"},"2022-4-영어-9":{"w":"증기 압축식 냉동장치의 4대 요소는 압축기, 응축기, 팽창밸브, 증발기입니다. 냉각기(Cooler)는 아닙니다.","x":["정답(아닌 것). Cooler","4대 요소입니다.","4대 요소입니다.","4대 요소입니다."],"t":"냉동 4요소 = 압축·응축·팽창·증발"},"2022-4-영어-11":{"w":"병렬 운전에서 분리하다 = release from parallel running. \"Released No.2 generator in parallel running and stopped No.2 G/E.\"","x":["engage는 연결입니다.","engage는 연결입니다.","정답. Released, parallel running","병렬이 빠졌습니다."],"t":"release = 분리"},"2022-4-영어-13":{"w":"EEDI = Energy Efficiency Design Index = 에너지효율설계지수입니다.","x":["정답. 에너지효율설계지수","운항지수는 EEOI입니다.","틀립니다.","틀립니다."],"t":"EEDI = 설계지수"},"2022-4-영어-15":{"w":"축방향 간극(axial clearance)을 조정하는 것은 추력 베어링(thrust bearing)입니다.","x":["볼 베어링이 아닙니다.","중간 베어링이 아닙니다.","롤러 베어링이 아닙니다.","정답. thrust bearing"],"t":"axial clearance = 추력 베어링"},"2022-4-영어-16":{"w":"절연체(insulator)는 전류 흐름에 높은 저항을 주는 물질입니다.","x":["정답. 높은 저항","도체입니다.","틀립니다.","틀립니다."],"t":"insulator = 높은 저항"},"2022-4-영어-19":{"w":"발전기관의 피스톤과 피스톤링을 교체하려면 오일 스크레이퍼링, 압축링, 개스킷 등이 필요합니다. 기계식 실(Mechanical seal)은 펌프 부품입니다.","x":["필요합니다.","필요합니다.","필요합니다.","정답(아닌 것). Mechanical seal"],"t":"mechanical seal = 펌프 축 밀봉"},"2022-4-영어-21":{"w":"크랭크암 디플렉션, 배기밸브 정비, 라이너 마멸 측정은 주기관 정비입니다. 저압·고압 피스톤링은 공기압축기의 부품입니다.","x":["주기관 정비입니다.","주기관 정비입니다.","주기관 정비입니다.","정답(아닌 것). 공기압축기 정비"],"t":"L.P./H.P. piston ring = 공기압축기"},"2022-4-영어-22":{"w":"loaded(적재했다) ≒ received(받았다).","x":["정답. Received","옮겼다","측정했다","올렸다"],"t":"loaded ≒ received"},"2022-4-영어-23":{"w":"가열기에 들어가는 증기량을 조절해 연료유 온도(점도)를 맞추는 장치는 점도 제어기(viscosity controller)입니다.","x":["유량 제어기가 아닙니다.","압력 제어기가 아닙니다.","정답. viscosity controller","비중 제어기가 아닙니다."],"t":"viscosity controller = 점도 일정 유지"},"2023-1-기관1-1":{"w":"사바테(복합) 사이클의 이론 열효율은 압축비, 압력비(폭발비), 분사차단비(체절비)와 비열비로 결정됩니다. 온도비는 열효율 식에 들어가지 않습니다.","x":["압축비가 클수록 효율이 좋아집니다.","압력비는 영향을 줍니다.","정답(아닌 것). 온도비는 영향을 주지 않습니다.","분사차단비는 영향을 줍니다."],"t":"사바테 효율 = 압축비·압력비·차단비"},"2023-1-기관1-3":{"w":"냉각수 측 부식을 막으려면 공기량을 줄이고, 방식 첨가제를 넣고, 내식성 도료를 칠하며, 냉각수 압력을 적정하게 유지해 기포(캐비테이션) 생성을 막아야 합니다. 압력을 낮추면 캐비테이션 부식이 늘어납니다.","x":["공기가 적으면 부식이 줄어듭니다.","방식 첨가제는 대책입니다.","정답(옳지 않은 것). 압력을 낮추면 캐비테이션이 생깁니다.","내식성 도료는 대책입니다."],"t":"냉각수측 부식 = 공기↓·첨가제·적정 압력"},"2023-1-기관1-4":{"w":"라이너 마멸 원인은 불완전 연소(카본), 링 장력 과대, 윤활유 부족, 저온 부식 등입니다. 냉각수 압력이 높은 것은 라이너 마멸 원인이 아닙니다.","x":["불완전 연소는 원인입니다.","링 장력 과대는 원인입니다.","정답(아닌 것). 냉각수 압력은 원인이 아닙니다.","윤활유 부족은 원인입니다."],"t":"라이너 마멸 = 카본·링 장력·윤활 부족"},"2023-1-기관1-5":{"w":"실린더 헤드 균열은 부동 팽창, 냉각수 통로의 공기 체류로 인한 과열, 배기 통로 카본 부착(과열) 등으로 생깁니다. 순환 윤활유 압력은 헤드 균열과 관계없습니다.","x":["부동 팽창은 원인입니다.","공기 체류 과열은 원인입니다.","카본 부착은 원인입니다.","정답(아닌 것). 윤활유 압력은 관계없습니다."],"t":"헤드 균열 = 열응력·과열"},"2023-1-기관1-7":{"w":"크랭크암 개폐량(디플렉션)으로 위험 개폐량 도달, 메인 베어링 마멸, 축 중심선 불일치를 판단합니다. 위험 회전수는 비틀림 진동 계산으로 정하는 것으로 개폐량으로는 알 수 없습니다.","x":["판단할 수 있습니다.","판단할 수 있습니다.","정답(판단할 수 없는 것). 위험 회전수","판단할 수 있습니다."],"t":"디플렉션 = 베어링 마멸·축심"},"2023-1-기관1-8":{"w":"과급기는 공기를 압축해 더 많이 넣어 같은 기관에서 더 높은 출력을 얻게 하는 장치입니다.","x":["압축비를 바꾸지 않습니다.","정격회전수를 높이지 않습니다.","배기온도를 낮추는 것이 목적이 아닙니다.","정답. 출력 증가"],"t":"과급 = 출력 증가"},"2023-1-기관1-9":{"w":"플라이휠은 같은 무게라면 두께보다 지름을 크게 하는 것이 관성모멘트가 커서 회전을 고르게 하는 데 효과적입니다.","x":["정답(옳지 않은 것). 지름을 크게 하는 것이 효과적입니다.","저속 회전을 가능하게 합니다.","실린더 수가 적으면 더 커야 합니다.","고속기관은 작아도 됩니다."],"t":"플라이휠 = 지름이 효과적(관성모멘트)"},"2023-1-기관1-10":{"w":"디젤 연소 과정 중 후연소 기간이 일반적으로 가장 깁니다.","x":["착화지연은 짧습니다.","무제어연소는 짧습니다.","정답. 후연소 기간","제어연소보다 후연소가 깁니다."],"t":"가장 긴 기간 = 후연소"},"2023-1-기관1-11":{"w":"보슈식 펌프에서 플런저의 경사홈이 배럴의 흡입구멍과 일치하면 고압 연료가 흡입구로 빠져나가 분사가 끝납니다.","x":["정답. 경사홈 일치 = 분사끝","상사점과 관계없습니다.","하사점과 관계없습니다.","분사시작은 플런저 윗면이 구멍을 막을 때입니다."],"t":"경사홈 = 분사끝(분사량 조정)"},"2023-1-기관1-13":{"w":"수관 보일러는 고압에 견디고 증기 발생이 빠르며 효율이 좋습니다. 그러나 관 속 스케일에 약해 급수처리가 반드시 필요합니다.","x":["장점입니다.","장점입니다.","장점입니다.","정답(아닌 것). 급수처리가 꼭 필요합니다."],"t":"수관 보일러 = 급수처리 필수"},"2023-1-기관1-14":{"w":"증기터빈에는 물방울이 없는 과열증기가 가장 적당합니다. 습증기는 날개를 침식시킵니다.","x":["습증기는 날개를 침식시킵니다.","정답. 과열증기","포화증기는 팽창 중 습해집니다.","건포화증기도 팽창 중 습해집니다."],"t":"터빈 = 과열증기"},"2023-1-기관1-17":{"w":"축계 진동이 심하면 중간축 베어링 마멸, 프로펠러 날개 손상, 피치 불균일 등을 점검합니다. 날개의 강도 변화는 눈으로 점검할 수 있는 사항이 아닙니다.","x":["점검합니다.","정답(아닌 것). 강도 변화는 점검 사항이 아닙니다.","점검합니다.","점검합니다."],"t":"축계 진동 = 베어링·날개 손상·피치"},"2023-1-기관1-19":{"w":"공기실을 이용한 유윤활식 선미관에는 고무 립 실(lip seal)을 많이 씁니다.","x":["정답. 립 실","단면 실이 아닙니다.","글랜드 패킹은 해수 윤활식에 씁니다.","메커니컬 실은 일부 형식에만 씁니다."],"t":"유윤활 선미관 = 립 실"},"2023-1-기관1-21":{"w":"점도가 높은 기름(280cSt)은 가열하지 않으면 더 끈적해 펌프로 옮기기 어렵습니다. 점도가 낮은 기름이 더 비싸고, 둘 다 50[℃] 기준 동점도입니다.","x":["저점도유가 더 비쌉니다.","50[℃] 기준입니다.","고점도유를 더 가열해야 합니다.","정답(옳지 않은 것). 280cSt가 이송하기 더 어렵습니다."],"t":"고점도유 = 더 가열, 이송 어려움"},"2023-1-기관1-23":{"w":"마찰은 고체마찰, 경계마찰, 유체마찰(과 그 중간 상태)로 나눕니다. 기체마찰은 분류에 없습니다.","x":["고체마찰은 마찰 종류입니다.","정답(아닌 것). 기체마찰","경계마찰은 마찰 종류입니다.","유체마찰은 마찰 종류입니다."],"t":"마찰 = 고체·경계·유체"},"2023-1-기관1-24":{"w":"디젤기관 윤활유는 온도 변화에도 점도가 잘 변하지 않는 점도지수가 큰 윤활유가 적절합니다.","x":["점도가 크기만 하면 마찰 손실이 큽니다.","정답. 점도지수가 큰 윤활유","항유화성은 커야 합니다.","산화안정도는 커야 합니다."],"t":"좋은 윤활유 = 점도지수↑"},"2023-1-기관1-25":{"w":"윤활유에서 가장 중요한 성질은 유막을 만드는 점도와 유성입니다.","x":["비중·인화점은 가장 중요한 성질이 아닙니다.","정답. 점도와 유성","부차적입니다.","부차적입니다."],"t":"윤활유 핵심 = 점도·유성"},"2023-1-기관2-2":{"w":"기어펌프는 용적형 펌프이므로 흡입·송출 밸브를 모두 열고 기동해야 합니다. 흡입밸브를 닫고 운전하면 공회전·과열·손상이 생깁니다.","x":["개스킷 두께는 틈새에 영향을 줍니다.","밸브 정비가 필요합니다.","송출밸브는 반드시 엽니다.","정답(옳지 않은 것). 흡입밸브도 열어야 합니다."],"t":"기어펌프 = 흡입·송출 밸브 모두 열고 기동"},"2023-1-기관2-3":{"w":"원심펌프가 흡입수면보다 높으면 흡입관에 물을 채워야 하므로 풋 밸브, 진공펌프(자흡 장치), 호수 밸브와 공기빼기 콕 등을 설치합니다. 평형공은 축방향 추력을 줄이는 구멍입니다.","x":["진공펌프로 물을 끌어올립니다.","풋 밸브로 흡입관 물이 빠지지 않게 합니다.","정답(아닌 것). 평형공은 추력 감소용입니다.","호수(마중물)와 공기 빼기를 합니다."],"t":"평형공 = 추력 감소"},"2023-1-기관2-4":{"w":"헬레쇼(Hele-Shaw) 펌프는 반경 방향으로 배치된 플런저가 회전하는 방사식 회전 플런저 펌프로 유압 계통에 많이 씁니다.","x":["로브 펌프는 로터 펌프입니다.","정답. 헬레쇼 펌프","이모 펌프는 스크루 펌프입니다.","기어 펌프는 기어식입니다."],"t":"헬레쇼 = 방사식 플런저"},"2023-1-기관2-7":{"w":"타를 움직이는 힘을 내는 것은 원동기(전동기+유압펌프)입니다.","x":["조종장치는 명령을 보냅니다.","정답. 원동기","추종장치는 타를 명령 각도에 멈춥니다.","타장치는 타와 타두재입니다."],"t":"원동기 = 동력"},"2023-1-기관2-8":{"w":"화물탱크 바닥에 남은 기름을 마지막까지 퍼내는 펌프는 스트리퍼 펌프(Stripper pump)입니다.","x":["Cargo pump는 주 하역 펌프입니다.","정답. Stripper pump","버터워스는 탱크 세정 장치입니다.","Drain pump가 아닙니다."],"t":"stripping = 잔유 퍼내기"},"2023-1-기관2-9":{"w":"유면검출기는 분리된 기름이 모이는 상부 공간의 하한 레벨에 설치해, 기름층이 그 레벨까지 두꺼워지면 배유밸브를 엽니다.","x":["설치 위치가 아닙니다.","물층이 아닙니다.","정답. 기름 공간의 하한 레벨","상한 레벨이 아닙니다."],"t":"유면검출기 = 기름층 하한"},"2023-1-기관2-11":{"w":"브라인(간접 냉매)은 동결 온도가 낮고, 비열·열전달이 좋고, 점성이 작으며, 금속 부식성이 작아야 합니다.","x":["조건입니다.","정답(아닌 것). 부식성은 작아야 합니다.","조건입니다.","조건입니다."],"t":"브라인 = 부식성 작게"},"2023-1-기관2-12":{"w":"냉동톤 = 332,000 ÷ 3,320 = 100 RT. 동력 = 100 × 0.8 = 80[kW]입니다.","x":["틀린 값입니다.","틀린 값입니다.","정답. 100RT × 0.8 = 80[kW]","틀린 값입니다."],"t":"1RT = 3,320kcal/h"},"2023-1-기관2-13":{"w":"고속 다기통 압축기는 언로드(언로더) 장치로 일부 실린더의 흡입밸브를 열어 두어 용량(능력)을 조절합니다.","x":["정답. 언로드 장치","스터핑 박스는 축 밀봉 장치입니다.","안전밸브는 보호 장치입니다.","고압 차단 스위치는 보호 장치입니다."],"t":"언로더 = 용량 조절"},"2023-1-기관2-14":{"w":"이론적인 냉동 사이클은 역 카르노 사이클입니다.","x":["내연기관 사이클입니다.","해당하지 않습니다.","정답. 역 카르노 사이클","열기관 이론 사이클입니다."],"t":"냉동 = 역 카르노"},"2023-1-기관2-15":{"w":"감습(제습) 방법은 냉각식, 흡착식(실리카겔), 흡수식(염화리튬) 등입니다. 증기 분사는 가습 방법입니다.","x":["냉각식은 감습입니다.","정답(아닌 것). 증기 분사는 가습입니다.","흡착식은 감습입니다.","흡수식은 감습입니다."],"t":"증기 분사 = 가습"},"2023-1-기관2-16":{"w":"탭은 구멍 안쪽에 암나사를 내는 공구입니다.","x":["수나사는 다이스입니다.","정답. 암나사 가공","테이퍼 가공이 아닙니다.","절단이 아닙니다."],"t":"탭 = 암나사"},"2023-1-기관2-17":{"w":"외력에 대항해 재료 내부에 생기는 단위 면적당 저항력을 응력이라 합니다.","x":["정답. 응력","변형률은 늘어난 비율입니다.","하중은 외력입니다.","경도는 단단한 정도입니다."],"t":"응력 = 힘 / 면적"},"2023-1-기관2-18":{"w":"가용접(임시 용접)은 본 용접만큼 중요하며, 강도상 중요한 곳은 피하고, 필요한 만큼 짧게 합니다. 길고 많이 할수록 좋은 것이 아닙니다.","x":["중요한 용접입니다.","중요한 부분은 피합니다.","정답(옳지 않은 것). 가용접은 짧게 필요한 만큼만 합니다.","중요한 작업은 제거 후 본 용접합니다."],"t":"가용접 = 짧게, 필요한 만큼"},"2023-1-기관2-19":{"w":"파이프가 열로 늘어나고 줄어드는 것은 신축이음으로 흡수합니다.","x":["정답. 신축이음","소켓이음은 일반 연결입니다.","용접이음은 고정 연결입니다.","플랜지이음은 분해 가능한 연결입니다."],"t":"열팽창 = 신축이음"},"2023-1-기관2-21":{"w":"수밀격벽은 침수 범위를 한정하고 방화벽 역할을 하며, 기관실 앞·뒤는 수밀격벽으로 합니다. 주로 수직 횡격벽으로 설치해 횡강도를 형성합니다.","x":["침수를 한정합니다.","방화벽 역할도 합니다.","기관실 전후는 수밀격벽입니다.","정답(옳지 않은 것). 주로 수직 횡격벽입니다."],"t":"수밀격벽 = 수직 횡격벽"},"2023-1-기관3-1":{"w":"전체 1[kW] = 100[V] × I 이므로 I = 10[A]. 1[Ω]의 전압 = 10 × 1 = 10[V], 전력 = 10² × 1 = 100[W]입니다.","x":["틀립니다.","전력이 틀립니다.","정답. 10[V], 100[W]","틀립니다."],"t":"P = I²R"},"2023-1-기관3-2":{"w":"역률 = R ÷ Z 이므로 Z = 6 ÷ 0.6 = 10[Ω]입니다.","x":["틀립니다.","리액턴스 값입니다.","정답. 6 ÷ 0.6 = 10[Ω]","틀립니다."],"t":"cosθ = R / Z"},"2023-1-기관3-3":{"w":"R = V ÷ I = 75 ÷ 30 = 2.5[Ω]입니다.","x":["정답. 75 ÷ 30 = 2.5[Ω]","틀립니다.","틀립니다.","틀립니다."],"t":"R = V / I"},"2023-1-기관3-4":{"w":"선행동작 우선회로는 두 입력 중 먼저 들어온 신호의 출력만 나오고 나중 신호는 막는 회로(인터록)입니다.","x":["동시에 나오지 않습니다.","신입신호 우선회로입니다.","정답. 먼저 들어온 신호 우선","신입신호 우선회로입니다."],"t":"선행 우선 = 먼저 온 것만"},"2023-1-기관3-6":{"w":"직류 전력 P = EI = I²R = E²/R 입니다.","x":["정답. P = E²/R","틀린 식입니다.","틀린 식입니다.","틀린 식입니다."],"t":"P = E² / R"},"2023-1-기관3-8":{"w":"Y결선에서 선간전압은 상전압의 √3배입니다.","x":["틀립니다.","정답. √3배","틀립니다.","틀립니다."],"t":"Y = 전압 √3배"},"2023-1-기관3-11":{"w":"교류발전기 병렬 운전 조건은 기전력의 크기, 위상, 주파수, 파형(상회전 방향)이 같을 것입니다.","x":["극수는 같지 않아도 됩니다.","용량은 같지 않아도 됩니다.","출력은 같지 않아도 됩니다.","정답. 위상이 같을 것"],"t":"병렬 조건 = 전압·주파수·위상·파형"},"2023-1-기관3-12":{"w":"규소를 넣으면 히스테리시스 손실이, 얇게 성층하면 맴돌이 전류 손실이 줄어듭니다. 규소강판 성층 철심은 둘 다 줄입니다.","x":["동손은 권선 손실입니다.","감소합니다.","감소합니다.","정답. 두 손실 모두 감소"],"t":"규소 → 히스테리시스↓, 성층 → 와류↓"},"2023-1-기관3-13":{"w":"역률은 교류에서만 있는 개념이므로 역률계는 교류 배전반에만 있습니다.","x":["직류에도 있습니다.","직류에도 있습니다.","정답. 역률계","차단기는 둘 다 있습니다."],"t":"역률 = 교류 전용"},"2023-1-기관3-14":{"w":"여자전류는 고정자 권선에 흘러 회전자계(자속)를 만드는 전류입니다.","x":["회전자 도체의 전류는 유도전류입니다.","설명이 부정확합니다.","정답. 회전자계를 만드는 전류","슬립에 의한 전류는 유도전류입니다."],"t":"여자전류 = 자계를 만드는 전류"},"2023-1-기관3-15":{"w":"주파수를 바꾸지 않고 전압만 조정하려면 AVR 설정값을 바꿔 여자전류를 조정합니다. 원동기 속도를 바꾸면 주파수가 변합니다.","x":["주파수가 변합니다.","리액턴스 조정은 방법이 아닙니다.","정답. AVR 설정값 변경","부하 역률은 운전자가 바꾸지 않습니다."],"t":"전압 = AVR, 주파수 = 거버너"},"2023-1-기관3-16":{"w":"전동기 권선 6가닥이 기동반에 연결되어 있으면 Y-△ 기동입니다. 기동 시 Y결선으로 전류를 줄이고, 정상 운전 중에는 △결선으로 합니다.","x":["틀립니다.","반대입니다.","정답. 운전 △, 기동 Y","틀립니다."],"t":"6선 = Y-△ 기동"},"2023-1-기관3-17":{"w":"권수비 a = N1/N2 이므로 N2 = 600 ÷ 30 = 20회입니다.","x":["정답. 600 ÷ 30 = 20회","틀립니다.","틀립니다.","곱한 값입니다."],"t":"N2 = N1 / a"},"2023-1-기관3-18":{"w":"전압변동률 = (무부하 전압 − 정격전압) ÷ 정격전압 × 100 = (250 − 200) ÷ 200 × 100 = 25[%]입니다.","x":["틀립니다.","틀립니다.","정답. 50 ÷ 200 = 25[%]","틀립니다."],"t":"전압변동률 = (V0 − Vn) / Vn"},"2023-1-기관3-19":{"w":"다이오드에 순방향 전류가 흐르려면 전지의 (+)극이 다이오드의 애노드(삼각형 쪽), (−)극이 캐소드(막대 쪽)로 이어져야 합니다. 두 전지가 같은 방향으로 직렬 연결되어 애노드에 (+)가 걸리는 ㉯입니다.","x":["전류가 흐르지 않습니다.","정답. 애노드에 (+)","전류가 흐르지 않습니다.","전류가 흐르지 않습니다."],"t":"순방향 = 애노드(+), 캐소드(−)"},"2023-1-기관3-20":{"w":"CdS(황화카드뮴)는 빛을 받으면 저항이 줄어 빛의 밝기 검출에 씁니다.","x":["FET는 증폭·스위칭 소자입니다.","UJT는 발진 소자입니다.","SCR은 전력 제어 소자입니다.","정답. CdS"],"t":"빛 검출 = CdS"},"2023-1-기관3-22":{"w":"A, B 모두 1일 때만 X가 0이므로 NAND(㉯)입니다.","x":["AND입니다.","정답. NAND","OR입니다.","NOR입니다."],"t":"둘 다 1일 때만 0 = NAND"},"2023-1-기관3-23":{"w":"같은 다이오드를 병렬로 연결하면 전류가 나뉘어 흐르므로 전체 순방향 전류를 늘릴 수 있습니다. (직렬로 연결하면 역방향 내전압이 커짐)","x":["직렬 연결의 효과입니다.","정답. 순방향 전류 증가","틀립니다.","틀립니다."],"t":"병렬 = 전류↑, 직렬 = 내전압↑"},"2023-1-기관3-24":{"w":"연산증폭기는 증폭률이 매우 커서, V1(− 입력)이 V2(+ 입력)보다 조금만 커도 출력은 음(−)의 전원 전압(−15[V]) 쪽으로 포화됩니다. 출력은 전원 전압(±15[V])을 넘지 못합니다.","x":["전원 전압(15V)을 넘을 수 없습니다.","정답. V1 > V2 → −15[V]","30[V]는 나올 수 없습니다.","같으면 0[V] 근처입니다."],"t":"비교기 = 출력은 ±전원 전압으로 포화"},"2023-1-직무일반-1":{"w":"황천 항해 때는 회전수를 낮추고, 빌지를 미리 빼고, 물건을 고정합니다. 세틀링 탱크를 가득 채우면 배가 흔들릴 때 넘치거나 침전물이 휘저어질 수 있어 적정 수위로 유지합니다.","x":["회전수를 낮춥니다.","빌지를 미리 뺍니다.","정답(옳지 않은 것). 세틀링 탱크는 가득 채우지 않습니다.","물건을 고정합니다."],"t":"황천 = 감속·빌지 배출·고정"},"2023-1-직무일반-2":{"w":"기관일지에는 기관 운전 상황, 연료유·윤활유·청수 소비량, 이상 발생 시각과 처리 상황을 기록합니다. 수급 시 비중·시간·양은 기름기록부 등 수급 관련 서류에 기록합니다.","x":["③이 들어갑니다.","정답. ①, ②, ④","②가 빠졌습니다.","①이 빠졌습니다."],"t":"기관일지 = 운전·소비량·이상 처리"},"2023-1-직무일반-4":{"w":"기관 비품(예비품)은 피스톤, 실린더 라이너, 안전밸브 스프링처럼 교체용 부품입니다. 실린더 오일은 소모품입니다.","x":["정답(아닌 것). 실린더 오일은 소모품입니다.","비품(예비품)입니다.","비품입니다.","비품입니다."],"t":"오일 = 소모품, 부품 = 비품"},"2023-1-직무일반-5":{"w":"시체스트는 선저의 해수 흡입함으로, 해초·조개 등을 불어내기 위해 증기 배관을 설치하기도 합니다.","x":["냉각기가 아닙니다.","수면 가까이가 아닙니다.","항해 중 개방하지 않습니다.","정답. 청소용 증기배관"],"t":"시체스트 = 증기 청소"},"2023-1-직무일반-6":{"w":"기관구역 기름기록부의 슬러지는 청정기 슬러지, 자동 여과기 드레인, 세틀링 탱크 드레인 등 기름 찌꺼기입니다. 보일러 급수탱크 드레인은 물이므로 슬러지가 아닙니다.","x":["정답(아닌 것). 급수탱크 드레인은 물입니다.","슬러지입니다.","슬러지입니다.","슬러지입니다."],"t":"슬러지 = 기름 찌꺼기"},"2023-1-직무일반-9":{"w":"연료유 공급서(BDN)에는 제품명, 공급량, 15[℃] 비중, 황 함유량, 공급업자 정보 등을 적습니다. 질소 함유량은 기재 사항이 아닙니다.","x":["제품명을 적습니다.","정답(아닌 것). 질소 함유량은 적지 않습니다.","비중을 적습니다.","공급업자 정보를 적습니다."],"t":"BDN = 황 함유량 필수"},"2023-1-직무일반-10":{"w":"선저의 유성 혼합물은 기름여과장치로 처리해 배출하거나, 저장탱크에 모아 두었다가 육상으로 양륙합니다. 청정기로 처리하지 않습니다.","x":["여과 후 배출합니다.","정답(옳지 않은 것). 청정기로 처리하지 않습니다.","저장합니다.","양륙합니다."],"t":"빌지 = 여과장치·저장·양륙"},"2023-1-직무일반-12":{"w":"질식은 기도 폐쇄, 산소 부족, 호흡중추 마비 등으로 호흡이 안 되는 상태입니다. 혈액순환 장애는 질식의 원인으로 분류하지 않습니다.","x":["기도 폐쇄는 원인입니다.","정답(아닌 것). 혈액순환 장애","산소 부족은 원인입니다.","호흡중추 마비는 원인입니다."],"t":"질식 = 기도·산소·호흡중추"},"2023-1-직무일반-13":{"w":"인공호흡 시 머리를 뒤로 젖히고 턱을 들어 올리면 기도가 열립니다.","x":["정답. 머리를 뒤로 젖힌다","기도가 충분히 열리지 않습니다.","구토 시 옆으로 돌립니다.","숙이면 기도가 막힙니다."],"t":"기도 확보 = 머리 젖히고 턱 들기"},"2023-1-직무일반-14":{"w":"라이너 균열로 피스톤을 둔 채 감통 운전할 때는 연료유, 냉각수, 시동공기를 차단합니다. 피스톤이 계속 움직이므로 실린더유는 계속 공급해 라이너와 링이 긁히지 않게 합니다.","x":["연료유를 차단합니다.","균열로 새므로 냉각수를 차단합니다.","시동공기를 차단합니다.","정답(옳지 않은 것). 실린더유는 공급합니다."],"t":"피스톤 둔 감통 = 실린더유 계속 공급"},"2023-1-직무일반-15":{"w":"정전 후 예비발전기가 투입되면 Sequential start program(순차 기동 프로그램)이 주요 전동기를 차례로 자동 기동합니다.","x":["정답. 순차 기동","역전력 보호입니다.","우선 차단입니다.","수동 기동입니다."],"t":"sequential start = 순차 자동 기동"},"2023-1-직무일반-16":{"w":"급정지 요청 시 텔레그래프에 즉시 응답하고 조작(⑤) → 조작 시간 기록(①) → 기관장·1기사에게 연락(③) → 다음 명령 준비(④) → 선교에 사유 확인(②) 순서가 가장 적절합니다.","x":["정답. ⑤ → ① → ③ → ④ → ②","순서가 다릅니다.","조작이 먼저입니다.","조작이 먼저입니다."],"t":"급정지 = 즉시 조작 → 기록 → 보고"},"2023-1-직무일반-18":{"w":"화재의 3요소는 가연물질, 열(점화원), 산소입니다.","x":["정답. 가연물·열·산소","압력이 아닙니다.","질소는 불연성입니다.","질소는 불연성입니다."],"t":"화재 3요소 = 가연물·열·산소"},"2023-1-직무일반-20":{"w":"고정식 CO₂ 소화장치는 조작이 쉽고, 설명서를 게시하고, 승인된 기기를 써야 합니다. 사람이 있을 수 있으므로 자동 방출이 아니라 경보 후 수동으로 방출합니다.","x":["조건입니다.","조건입니다.","조건입니다.","정답(옳지 않은 것). CO₂는 자동 방출하지 않습니다."],"t":"CO₂ = 경보 후 수동 방출"},"2023-1-직무일반-21":{"w":"모든 선박은 다른 설비와 관계없이 수(물) 소화장치를 기본으로 갖춰야 합니다.","x":["정답. 수 소화장치","선택 설비입니다.","선택 설비입니다.","선택 설비입니다."],"t":"기본 = 물 소화"},"2023-1-직무일반-23":{"w":"해양사고는 선박의 구조·설비·운용과 관련해 생긴 사고(인명 사상, 선박 손상·좌초, 해양오염 등)입니다. 태풍으로 방파제가 파손된 것은 선박과 관련이 없어 해양사고가 아닙니다.","x":["정답(아닌 것). 선박과 관계없습니다.","해양사고입니다.","해양사고입니다.","해양사고입니다."],"t":"해양사고 = 선박 관련 사고"},"2023-1-직무일반-24":{"w":"유기 구제비용에는 송환 교통비, 송환 기간의 통상임금, 생존에 필요한 재화 비용 등이 포함됩니다. 퇴직금은 포함되지 않습니다.","x":["포함됩니다.","정답(아닌 것). 퇴직금","포함됩니다.","포함됩니다."],"t":"유기 구제비용 ≠ 퇴직금"},"2023-1-직무일반-25":{"w":"기관구역의 배출관 장치는 총톤수 50톤 이상의 유조선에 설치해야 합니다.","x":["틀립니다.","정답. 50톤 이상","틀립니다.","틀립니다."],"t":"유조선 배출관 = 50톤 이상"},"2023-1-영어-1":{"w":"조속기 = governor 입니다.","x":["accumulator = 축압기","정답. governor","accelerator = 가속기","regulator = 조정기"],"t":"governor = 조속기"},"2023-1-영어-2":{"w":"소각기 = Incinerator 입니다.","x":["오수처리","Evaporator = 증발기","정답. Incinerator","Calorifier = 온수기"],"t":"incinerator = 소각기"},"2023-1-영어-3":{"w":"프로펠러 추력을 선체에 전달하는 베어링은 Thrust bearing입니다.","x":["저널 베어링입니다.","중간축 베어링입니다.","정답. Thrust bearing","선미관 베어링입니다."],"t":"thrust bearing = 추력 베어링"},"2023-1-영어-4":{"w":"유량계 = Flowmeter 입니다.","x":["회전계","습도계","정답. Flowmeter","압력계"],"t":"flowmeter = 유량계"},"2023-1-영어-7":{"w":"MCR = Maximum Continuous Rating(최대 연속 출력)입니다.","x":["틀립니다.","정답. Maximum Continuous Rating","틀립니다.","틀립니다."],"t":"MCR = 최대 연속 출력"},"2023-1-영어-8":{"w":"FPT = Fore Peak Tank(선수 피크 탱크)입니다.","x":["맞는 약어입니다.","맞는 약어입니다.","맞는 약어입니다.","정답(옳지 않은 것). FPT = Fore Peak Tank"],"t":"FPT 선수탱크, APT 선미탱크"},"2023-1-영어-10":{"w":"ISM Code = International Safety Management Code 입니다.","x":["틀립니다.","틀립니다.","틀립니다.","정답. International Safety Management Code"],"t":"ISM = Safety Management"},"2023-1-영어-12":{"w":"기계적으로 압축된 공기의 높은 온도로 분사된 연료가 착화하는 내연기관은 디젤기관입니다.","x":["가스터빈이 아닙니다.","증기터빈은 외연기관입니다.","정답. Diesel engine","가솔린기관은 점화 플러그로 착화합니다."],"t":"압축 착화 = 디젤"},"2023-1-영어-14":{"w":"\"기관 내부의 먼지와 카본을 청소한다\"는 윤활유의 청정 작용입니다.","x":["냉각수가 아닙니다.","시동공기가 아닙니다.","역전공기가 아닙니다.","정답. Lubricating oil"],"t":"윤활유 = 청정 작용"},"2023-1-영어-15":{"w":"상사점과 하사점 사이의 거리는 행정(stroke)입니다.","x":["bore = 안지름","cycle = 사이클","정답. stroke","clearance = 틈새"],"t":"stroke = TDC~BDC"},"2023-1-영어-16":{"w":"냉매 온도는 압축기를 나와 응축기(condenser)에 들어가기 직전에 가장 높습니다.","x":["정답. condenser 직전","압축기 입구는 저온입니다.","팽창밸브 전은 응축 후입니다.","증발기 입구는 저온입니다."],"t":"최고 온도 = 압축기 출구(응축기 입구)"},"2023-1-영어-17":{"w":"IHP = Indicated Horse Power = 지시마력입니다.","x":["정답. IHP","제동마력","전달마력","유효마력"],"t":"IHP 지시, BHP 제동"},"2023-1-영어-19":{"w":"Inert gas system = 불활성 가스 장치 입니다.","x":["화재 탐지 장치가 아닙니다.","정답. 불활성 가스 장치","가스 제거 장치가 아닙니다.","소독 장치가 아닙니다."],"t":"inert gas = 불활성 가스"},"2023-1-영어-21":{"w":"fuel injection occurs too early = 연료분사가 너무 빠르면.","x":["연소가 아니라 분사입니다.","틀립니다.","늦으면이 아닙니다.","정답. 연료분사가 너무 빠르면"],"t":"too early = 너무 빠른"},"2023-1-영어-24":{"w":"탱크 안 물의 높이를 보여주는 장치는 Water level gauge(수면계)입니다.","x":["공기관입니다.","정답. Water level gauge","측심관은 재는 관입니다.","틀립니다."],"t":"level gauge = 수위계"},"2023-1-영어-25":{"w":"4행정 기관은 흡입(suction), 압축(compression), 작동(working), 배기(exhaust) 행정으로 이루어집니다.","x":["정답. suction, compression, working, exhaust","injection은 행정이 아닙니다.","틀립니다.","scavenging은 2행정 용어입니다."],"t":"흡입 → 압축 → 작동 → 배기"},"2023-1-기관1-18":{"w":"프로펠러축이 부러지는 원인은 재질 불량, 비틀림 진동, 부식에 의한 강도 저하, 축심 불일치 등입니다. 추력 베어링의 마멸은 프로펠러축 절손의 직접 원인이 아닙니다.","x":["재질 불량은 원인입니다.","정답(옳지 않은 것). 추력 베어링 마멸은 직접 원인이 아닙니다.","비틀림 진동은 원인입니다.","부식은 원인입니다."],"t":"프로펠러축 절손 = 재질·비틀림 진동·부식"},"2023-2-기관1-1":{"w":"시동밸브는 시동할 때 압축공기를 실린더에 넣어 피스톤을 밀어 내리는 밸브로, 작동(팽창)행정에서 열립니다.","x":["흡입행정에는 열리지 않습니다.","압축행정에 공기를 넣으면 역회전합니다.","정답. 작동행정","배기행정에는 열리지 않습니다."],"t":"시동밸브 = 작동행정에 열림"},"2023-2-기관1-2":{"w":"실린더 헤드는 연소실을 이루고 대각선으로 나누어 조이며 열응력으로 균열이 생기기 쉽습니다. 냉각수 측 부식 방지에는 주석이 아니라 아연봉(방식 아연)을 설치합니다.","x":["연소실을 형성합니다.","대각선으로 조입니다.","균열이 생기기 쉽습니다.","정답(옳지 않은 것). 방식용은 아연봉입니다."],"t":"방식봉 = 아연"},"2023-2-기관1-3":{"w":"트렁크형 기관의 피스톤핀은 피스톤이 받은 힘을 커넥팅로드에 전달합니다.","x":["크로스헤드형 기관의 설명입니다.","측압은 피스톤 스커트가 받습니다.","정답. 힘을 커넥팅로드에 전달","회전운동으로 바꾸는 것은 크랭크축입니다."],"t":"피스톤핀 = 힘 전달"},"2023-2-기관1-4":{"w":"크랭크암 개폐작용은 메인 베어링 편마멸, 크랭크축 중심 불일치, 기관 베드 변형 등으로 생깁니다. 중간축 베어링은 기관 밖 축계에 있어 크랭크암과 관계없습니다.","x":["정답(아닌 것). 중간축 베어링은 관계없습니다.","원인입니다.","원인입니다.","원인입니다."],"t":"디플렉션 = 메인 베어링·축심·베드"},"2023-2-기관1-5":{"w":"평형추는 실린더 수와 크랭크 배치에 따라 생기는 불평형 관성력을 고려해 설치합니다.","x":["저널 크기와 관계없습니다.","피스톤 구조가 주된 사항이 아닙니다.","정답. 실린더 수와 불평형 관성력","압력과 관계없습니다."],"t":"평형추 = 불평형 관성력 상쇄"},"2023-2-기관1-6":{"w":"분사압력이 낮으면 니들 밸브가 일찍 열려 분사시기가 빨라지고, 분무가 나빠 착화지연이 길어집니다.","x":["정답. 분사 빨라짐, 무화 불량, 착화지연 증가","분사시기는 빨라집니다.","무화는 나빠집니다.","착화지연은 길어집니다."],"t":"분사압력↓ = 빨라짐·무화 불량"},"2023-2-기관1-8":{"w":"태핏 간극은 그 실린더가 압축 상사점에 있을 때 맞춥니다. 5번을 맞춘 뒤 1회전(360°) 하면 착화순서 1-5-3-6-2-4에서 5번보다 세 칸(120° × 3) 뒤인 2번이 압축 상사점에 옵니다.","x":["정답. 5 → 3 → 6 → 2, 2번","틀립니다.","틀립니다.","한 칸 뒤입니다."],"t":"360° 회전 = 착화순서 세 칸"},"2023-2-기관1-9":{"w":"배기밸브를 상사점 후에 닫으면 배기가스의 관성으로 남은 가스를 더 잘 내보내 배기작용을 돕습니다.","x":["소기는 2행정 용어입니다.","정답. 배기작용을 돕기 위해","흡기온도와 관계없습니다.","배기온도와 관계없습니다."],"t":"배기밸브 늦게 닫음 = 배기 촉진"},"2023-2-기관1-10":{"w":"유압조속기의 보상 니들밸브를 너무 많이 열면 보상이 너무 빨라져 회전속도가 오르내리는 헌팅(난조)이 생깁니다.","x":["정답. 헌팅","과속이 유지되지 않습니다.","반대로 불안정해집니다.","정지하지 않습니다."],"t":"니들밸브 과다 개방 = 헌팅"},"2023-2-기관1-11":{"w":"보슈식 연료분사펌프는 배럴, 플런저, 토출밸브, 래크·피니언 등으로 구성됩니다. 스필밸브는 스필(밸브)식 펌프의 부품입니다.","x":["구성 요소입니다.","구성 요소입니다.","구성 요소입니다.","정답(아닌 것). 스필밸브는 없습니다."],"t":"보슈식 = 배럴·플런저·토출밸브"},"2023-2-기관1-12":{"w":"프라이밍·포밍이 생기면 수면이 요동치고 수위가 부정확해지며, 증기에 물이 섞여 나가(캐리오버) 증기온도가 떨어집니다. 증기 속 수분은 증가합니다.","x":["수면이 요동칩니다.","증기온도가 떨어집니다.","수위가 부정확합니다.","정답(아닌 것). 수분은 증가합니다."],"t":"포밍·프라이밍 → 수분 증가"},"2023-2-기관1-13":{"w":"드럼 수면에 떠 있는 불순물은 수면 방출밸브로 배출합니다.","x":["수트 블로어는 그을음 제거용입니다.","수저 방출은 가라앉은 슬러지 배출입니다.","정답. 수면 방출밸브","수면계 드레인이 아닙니다."],"t":"뜨는 것 = 수면 방출"},"2023-2-기관1-14":{"w":"급수제어는 수위, 증기유량, 급수유량을 검출해 제어합니다(1·2·3요소식). 연소량은 연소제어의 검출 요소입니다.","x":["정답(아닌 것). 연소량","검출 요소입니다.","검출 요소입니다.","검출 요소입니다."],"t":"급수제어 = 수위·증기량·급수량"},"2023-2-기관1-15":{"w":"복수기 진공이 떨어지는 원인은 공기 침입, 드레인 배출 불량, 순환수(냉각수) 부족, 냉각수 온도 상승 등입니다. 냉각수 온도가 낮으면 진공은 오히려 좋아집니다.","x":["원인입니다.","원인입니다.","원인입니다.","정답(아닌 것). 냉각수 온도가 낮으면 진공이 좋아집니다."],"t":"진공 저하 = 공기·냉각 부족"},"2023-2-기관1-16":{"w":"프로펠러축 절손 원인은 재질 불량, 비틀림 진동, 부식 등입니다. 추력 베어링 마멸은 직접 원인이 아닙니다.","x":["원인입니다.","정답(옳지 않은 것). 추력 베어링 마멸","원인입니다.","원인입니다."],"t":"프로펠러축 절손 = 재질·진동·부식"},"2023-2-기관1-18":{"w":"침투액, 솔벤트(세척제), 현상액을 쓰는 방법은 침투 탐상법(컬러 체크)입니다.","x":["자분 탐상은 자분을 씁니다.","정답. 침투 탐상법","방사선을 씁니다.","초음파를 씁니다."],"t":"침투 탐상 = 컬러 체크"},"2023-2-기관1-21":{"w":"연료유의 온도 순서는 발화점 > 인화점 > 유동점 > 응고점 입니다.","x":["인화점이 발화점보다 낮습니다.","정답. 발화점 → 인화점 → 유동점 → 응고점","순서가 틀렸습니다.","유동점이 응고점보다 높습니다."],"t":"발화 > 인화 > 유동 > 응고"},"2023-2-기관1-24":{"w":"선내에서 연료유 점도를 간단히 재는 기구는 비스코미터(점도계)입니다.","x":["정답. 비스코미터","스폿 테스트는 윤활유 오염도를 봅니다.","플로미터는 유량계입니다.","타코미터는 회전계입니다."],"t":"viscometer = 점도계"},"2023-2-기관1-25":{"w":"대형 기관의 실린더 라이너에는 주유기(루브리케이터)로 압력을 가해 기름을 주입하는 압력 급유 방식을 씁니다.","x":["중력 급유가 아닙니다.","정답. 압력 급유","비산식은 크랭크가 튀기는 방식입니다.","강제 순환식은 크랭크실 윤활입니다."],"t":"실린더 주유기 = 압력 급유"},"2023-2-기관2-2":{"w":"마우스링은 임펠러와 케이싱 사이에서 송출측 물이 흡입측으로 역류하는 것을 막습니다.","x":["와실은 속도를 압력으로 바꿉니다.","평형공은 추력을 줄입니다.","랜턴링은 봉수를 공급합니다.","정답. 마우스링"],"t":"마우스링 = 내부 역류 방지"},"2023-2-기관2-3":{"w":"왕복펌프는 흡입 성능이 좋고 고압을 낼 수 있지만, 같은 유량이면 원심펌프보다 크고, 왕복 운동 때문에 고속 운전이 어렵습니다.","x":["공기실로 맥동을 줄입니다.","크기가 큽니다.","정답(옳지 않은 것). 고속 운전이 어렵습니다.","흡입 성능이 좋습니다."],"t":"왕복펌프 = 저속·고압·흡입 양호"},"2023-2-기관2-4":{"w":"유체의 압력 에너지를 직선 왕복운동으로 바꾸는 것은 (유압·공압) 실린더입니다. 모터는 회전운동으로 바꿉니다.","x":["펌프는 동력을 유체 에너지로 바꿉니다.","모터는 회전운동입니다.","어큐뮬레이터는 압력을 저장합니다.","정답. 실린더 = 직선운동"],"t":"실린더 직선, 모터 회전"},"2023-2-기관2-5":{"w":"2단 공기압축기의 중간 냉각기는 저압 실린더에서 압축된 공기를 식혀 고압 실린더로 보냅니다. 압축 동력이 줄고 효율이 좋아집니다.","x":["압축비를 바꾸지 않습니다.","속도와 관계없습니다.","정답. 저압 단 공기를 냉각","고압 공기를 식히는 것은 후부 냉각기입니다."],"t":"중간 냉각기 = 저압단 후 냉각"},"2023-2-기관2-6":{"w":"중·대형 선박의 양묘기는 전동 유압식을 많이 씁니다.","x":["증기식은 옛 방식입니다.","기계식이 아닙니다.","전기식은 소형선에 씁니다.","정답. 전동 유압식"],"t":"양묘기 = 전동 유압식"},"2023-2-기관2-7":{"w":"유압 조타기의 유압관에 공기가 섞이면 공기가 압축·팽창하며 소리(소음)가 나고 동작이 불안정해집니다.","x":["기름이 새면 압력이 떨어집니다.","정답. 공기 혼입","유온 상승은 주 원인이 아닙니다.","펌프 소손은 해당하지 않습니다."],"t":"유압관 소음 = 공기 혼입"},"2023-2-기관2-8":{"w":"점도가 높은 폐유를 일정하게 보내는 데는 기어 펌프를 많이 씁니다.","x":["제트 펌프가 아닙니다.","정답. 기어 펌프","터빈 펌프가 아닙니다.","피스톤 펌프가 아닙니다."],"t":"폐유 = 기어 펌프"},"2023-2-기관2-12":{"w":"응축기 출구(액관)에는 건조기 → 전자밸브 → 자동팽창밸브 → (증발기) → 증발압력 조절밸브 순서로 설치합니다.","x":["순서가 틀렸습니다.","순서가 틀렸습니다.","순서가 틀렸습니다.","정답. 건조기 → 전자밸브 → 팽창밸브 → 증발압력 조절밸브"],"t":"건조기 → 전자밸브 → 팽창밸브"},"2023-2-기관2-13":{"w":"언로더 피스톤은 윤활유(또는 송출가스)의 압력으로 작동합니다.","x":["정답. 송출가스 또는 윤활유 압력","흡입가스 압력이 아닙니다.","바이패스 밸브가 아닙니다.","솔레노이드 밸브가 아닙니다."],"t":"언로더 = 유압으로 작동"},"2023-2-기관2-14":{"w":"가습은 물·온수 분무, 증기 분무, 가습 팬으로 합니다. 실리카겔은 제습제입니다.","x":["가습 방법입니다.","가습 방법입니다.","정답(아닌 것). 실리카겔은 제습","가습 방법입니다."],"t":"실리카겔 = 제습"},"2023-2-기관2-17":{"w":"핸드탭은 1번(테이퍼 탭) → 2번(플러그 탭) → 3번(보터밍 탭) 순서로 쓰며, 마지막 다듬질은 보터밍 탭으로 합니다.","x":["정답. 보터밍 탭","두 번째로 씁니다.","처음에 씁니다.","해당하지 않습니다."],"t":"탭 = 테이퍼 → 플러그 → 보터밍"},"2023-2-기관2-18":{"w":"용접봉 기호 E4301에서 E는 피복 아크 용접봉, 43은 용착금속의 최소 인장강도(43[kgf/mm²]), 01은 피복제 종류입니다.","x":["피복제 종류는 뒤의 두 숫자입니다.","정답. 최소 인장강도","최대가 아닙니다.","전류가 아닙니다."],"t":"E43XX = 최소 인장강도 43"},"2023-2-기관2-19":{"w":"플랜지 접합면처럼 움직이지 않는 면 사이에 넣어 누설을 막는 것은 개스킷입니다.","x":["정답. 개스킷","스크레이퍼링은 기름 긁기 링입니다.","기계식 실은 회전축용입니다.","글랜드 패킹은 축용입니다."],"t":"플랜지 = 개스킷"},"2023-2-기관2-23":{"w":"조파저항은 배가 만드는 파도에 의한 저항으로, 속력이 빨라질수록 급격히 커집니다.","x":["정답. 증가","감소하지 않습니다.","일정하지 않습니다.","계속 증가합니다."],"t":"조파저항 = 고속에서 커짐"},"2023-2-기관2-24":{"w":"척도 1:2는 도면 1이 실물 2라는 뜻으로, 그림이 실물의 절반 크기인 축척입니다.","x":["틀립니다.","1:1(현척)입니다.","2:1(배척)입니다.","정답. 실물의 절반"],"t":"1:2 = 축척(절반)"},"2023-2-기관3-2":{"w":"소비전력 P = V × I × 역률 = 200 × 2 × 0.9 = 360[W]입니다.","x":["틀립니다.","틀립니다.","정답. 360[W]","피상전력입니다."],"t":"P = VI cosθ"},"2023-2-기관3-3":{"w":"스위치 A와 B가 병렬이므로 하나만 닫혀도 전구가 켜지는 OR 회로입니다.","x":["AND는 직렬입니다.","정답. 병렬 = OR","해당하지 않습니다.","해당하지 않습니다."],"t":"병렬 = OR, 직렬 = AND"},"2023-2-기관3-4":{"w":"전선 저항 R = ρ × ℓ ÷ S 입니다.","x":["정답. R = ρℓ/S","틀립니다.","틀립니다.","틀립니다."],"t":"R = ρℓ / S"},"2023-2-기관3-6":{"w":"코일만의 회로에서는 전류가 전압보다 90° 늦습니다. 즉 전압이 전류보다 90° 앞섭니다.","x":["정답. 전압이 90° 앞섬","콘덴서 회로입니다.","45°가 아닙니다.","45°가 아닙니다."],"t":"L = 전압 앞섬(ELI)"},"2023-2-기관3-8":{"w":"코일 가지 전류(3[A], 90° 늦음)와 저항 가지 전류(4[A], 위상 같음)는 직각으로 더해집니다. √(3² + 4²) = 5[A]입니다.","x":["틀립니다.","틀립니다.","정답. √(9 + 16) = 5[A]","단순히 더한 값입니다."],"t":"교류 전류 합 = 벡터 합"},"2023-2-기관3-9":{"w":"전기자 권선 소손 원인은 권선 단락, 통풍 불량(과열), 베어링 마멸로 회전자와 고정자가 닿는 경우 등입니다. 여자전류가 차단되면 전압이 안 나올 뿐 전기자 권선이 타지는 않습니다.","x":["원인입니다.","원인입니다.","정답(아닌 것). 여자 차단은 소손 원인이 아닙니다.","원인입니다."],"t":"여자 차단 = 전압 소멸"},"2023-2-기관3-11":{"w":"축전지는 충전할 때 수소가스를 발생시키므로 폭발을 막기 위해 통풍이 잘 되어야 합니다.","x":["정답. 수소가스","질소가 아닙니다.","아황산가스가 아닙니다.","산소도 나오지만 위험은 수소입니다."],"t":"축전지실 = 수소"},"2023-2-기관3-12":{"w":"전동기의 회전 방향(힘의 방향)은 플레밍의 왼손 법칙으로 알 수 있습니다. 발전기의 기전력 방향은 오른손 법칙입니다.","x":["정답. 플레밍의 왼손 법칙","전류가 만드는 자기장 세기 법칙입니다.","발전기에 씁니다.","전자유도 법칙입니다."],"t":"전동기 왼손, 발전기 오른손"},"2023-2-기관3-13":{"w":"변압기 2차 전압은 2차 권수에 비례하므로 2차 권수를 늘리면 2차 전압이 올라갑니다.","x":["전압과 관계없습니다.","정답. 2차 권수 증가","전압과 관계없습니다.","1차 권수를 늘리면 2차 전압은 내려갑니다."],"t":"V2 ∝ N2"},"2023-2-기관3-14":{"w":"비례추이는 2차(회전자) 저항을 바꾸면 토크 곡선이 슬립 방향으로 비례해 옮겨가는 성질로, 3상 권선형 유도전동기에 해당합니다.","x":["동기전동기가 아닙니다.","농형은 2차 저항을 바꿀 수 없습니다.","직류기가 아닙니다.","정답. 3상 권선형 유도전동기"],"t":"비례추이 = 권선형 유도전동기"},"2023-2-기관3-15":{"w":"3상 유도전동기의 3선 중 2선만 서로 바꾸면 회전자계 방향이 바뀌어 반대로 돕니다.","x":["결선 방식을 바꿔도 방향은 같습니다.","3선 모두 돌려 바꾸면 방향이 같습니다.","방향이 바뀌지 않습니다.","정답. 2선 교체"],"t":"역회전 = 2선 교체"},"2023-2-기관3-16":{"w":"MCCB = 배선용 차단기(Molded Case Circuit Breaker), PB = 푸시 버튼 스위치입니다.","x":["열동 계전기는 THR입니다.","정답. 배선용 차단기, 푸시 버튼","틀립니다.","기중 차단기는 ACB입니다."],"t":"MCCB = 배선용 차단기"},"2023-2-기관3-17":{"w":"병렬운전 시 주파수와 위상이 맞는지 확인하는 계기는 동기검정기(싱크로스코프)입니다.","x":["주파수만 봅니다.","AVR은 전압 조정기입니다.","정답. 동기검정기","역률계는 역률을 봅니다."],"t":"동기검정기 = 주파수·위상 확인"},"2023-2-기관3-18":{"w":"Ns = 120f/P 이므로 f = P × N ÷ 120 입니다.","x":["틀린 식입니다.","정답. f = PN/120","틀린 식입니다.","틀린 식입니다."],"t":"f = PN / 120"},"2023-2-기관3-19":{"w":"IGBT는 MOSFET(입력)과 BJT(출력)의 장점을 합쳐 고전압·대전류 스위칭에 씁니다(인버터 등).","x":["SCR은 사이리스터입니다.","GTO는 게이트로 끌 수 있는 사이리스터입니다.","UJT는 발진용입니다.","정답. IGBT"],"t":"IGBT = MOSFET + BJT"},"2023-2-기관3-20":{"w":"이미터 전류 = 베이스 전류 + 컬렉터 전류 이므로 이미터 전류가 가장 큽니다.","x":["매우 작습니다.","가장 작습니다.","정답. 이미터 전류","이미터 전류보다 약간 작습니다."],"t":"IE = IB + IC"},"2023-2-기관3-21":{"w":"A, B 모두 1일 때만 X가 0이므로 NAND(㉯)입니다.","x":["AND입니다.","정답. NAND","OR입니다.","NOR입니다."],"t":"둘 다 1일 때만 0 = NAND"},"2023-2-기관3-22":{"w":"정류 출력을 평활하게 하려면 출력단에 콘덴서를 병렬로 연결합니다(코일은 직렬).","x":["콘덴서는 병렬입니다.","정답. 콘덴서 병렬","부하저항을 작게 하면 맥동이 커집니다.","코일은 직렬로 넣습니다."],"t":"평활 = C 병렬, L 직렬"},"2023-2-기관3-25":{"w":"PLC 디지털 입력 회로는 외부 신호와 내부 회로를 전기적으로 절연하기 위해 포토커플러(Photo-coupler)를 가장 많이 씁니다.","x":["OP Amp가 아닙니다.","FET가 아닙니다.","정답. 포토커플러","UJT가 아닙니다."],"t":"PLC 입력 = 포토커플러(절연)"},"2023-2-직무일반-1":{"w":"일반적으로 1등기관사는 주기관, 축계·선미관, 윤활유 관리 등을 맡습니다. 발전기는 주로 2등기관사가 담당합니다.","x":["정답(아닌 것). 발전기는 주로 2기사 업무입니다.","1기사 업무입니다.","1기사 업무입니다.","1기사 업무입니다."],"t":"1기사 = 주기관·축계"},"2023-2-직무일반-2":{"w":"배관용 밸브는 글러브, 슬루스(게이트), 나비, 체크밸브 등입니다. 분사밸브는 기관의 연료 분사 장치입니다.","x":["배관 밸브입니다.","배관 밸브입니다.","배관 밸브입니다.","정답(아닌 것). 분사밸브는 기관 부품입니다."],"t":"분사밸브 = 연료 분사"},"2023-2-직무일반-3":{"w":"황천 대비로 중량물을 고정하고, 갑판부에 협조하고, 속도 변경에 대비해 계통을 점검합니다. 윤활유 압력은 규정값으로 유지하며, 임의로 높이는 것은 적절하지 않습니다.","x":["고정합니다.","정답(옳지 않은 것). 윤활유 압력은 규정값 유지","협조합니다.","점검합니다."],"t":"황천 = 고정·점검·협조"},"2023-2-직무일반-4":{"w":"위험작업 전에는 전원 차단 여부, 비상 연락 체계, 작업 내용 공유 등을 확인합니다. 소모품 청구 여부는 안전 확인 사항이 아닙니다.","x":["확인합니다.","정답(옳지 않은 것). 소모품 청구는 안전 확인이 아닙니다.","확인합니다.","확인합니다."],"t":"위험작업 = 전원 차단·연락 체계·내용 공유"},"2023-2-직무일반-5":{"w":"한국선급의 검사는 정기검사, 중간검사, 연차검사, 입거검사 등입니다. '제1종 중간검사'는 선박안전법상의 용어입니다.","x":["선급 검사입니다.","정답(아닌 것). 선박안전법 용어입니다.","선급 검사입니다.","선급 검사입니다."],"t":"1종·2종 중간검사 = 선박안전법"},"2023-2-직무일반-6":{"w":"기름이 배출되면 즉시 신고하고, 확산을 막고, 흡착재 등으로 제거해야 합니다. 양을 확인할 때까지 기다리며 현장 보전만 하면 오염이 퍼집니다.","x":["즉시 제거합니다.","확산을 막습니다.","정답(옳지 않은 것). 즉시 방제해야 합니다.","신속히 신고합니다."],"t":"유출 = 신고·확산 방지·제거"},"2023-2-직무일반-7":{"w":"질소(N₂)는 공기의 주성분으로 무해합니다. 질소산화물(NO, NO₂)과 이산화황(SO₂)은 유해합니다.","x":["정답(아닌 것). 질소는 무해","유해합니다.","유해합니다.","유해합니다."],"t":"N₂ 무해"},"2023-2-직무일반-9":{"w":"합성 로프, 어망 등 플라스틱류는 어떤 경우에도 해양에 버릴 수 없습니다. 음식 찌꺼기, 무해한 화물 잔류물, 중수는 조건에 따라 배출할 수 있습니다.","x":["조건부 배출 가능","정답(배출 불가). 플라스틱류","조건부 배출 가능","배출 가능"],"t":"플라스틱 = 전면 배출 금지"},"2023-2-직무일반-10":{"w":"해양오염방지관리인은 선장을 제외한 사관(기관장, 1등 항해사, 1등 기관사 등) 중에서 임명합니다.","x":["정답(될 수 없음). 선장","될 수 있습니다.","될 수 있습니다.","될 수 있습니다."],"t":"오염방지관리인 ≠ 선장"},"2023-2-직무일반-11":{"w":"혈액순환 장애로 조직에 산소가 부족해져 생체 기능이 떨어지는 상태를 쇼크라 합니다.","x":["정답. 쇼크","부종은 붓는 것입니다.","혈전은 혈관 속 덩어리입니다.","질식은 호흡 장애입니다."],"t":"쇼크 = 순환 장애"},"2023-2-직무일반-12":{"w":"1도 화상은 표피 바깥층만 손상되어 피부가 붉어지고 아픕니다. 2도는 물집, 3도는 피부 전층 손상입니다.","x":["정답. 1도 화상","물집이 생깁니다.","피부가 괴사합니다.","해당하지 않습니다."],"t":"화상 1도 발적, 2도 물집, 3도 괴사"},"2023-2-직무일반-14":{"w":"이중저 탱크에는 연료유, 청수, 평형수 등을 저장합니다. 청정유는 서비스 탱크에 저장합니다.","x":["정답(아닌 것). 청정유는 서비스 탱크","저장합니다.","저장합니다.","저장합니다."],"t":"청정유 = 서비스 탱크"},"2023-2-직무일반-19":{"w":"기름걸레는 자연 발화 위험이 있으므로 뚜껑이 있는 금속 용기에 보관하고 서늘한 곳에 둡니다.","x":["예방법입니다.","예방법입니다.","예방법입니다.","정답(옳지 않은 것). 뚜껑 있는 금속 통에 보관합니다."],"t":"기름걸레 = 뚜껑 있는 금속 용기"},"2023-2-직무일반-21":{"w":"연기식 탐지기는 광전자형, 이온화형, 저항브리지형 등입니다. 가용금속형은 열에 녹는 금속을 쓰는 열식 탐지기입니다.","x":["연기식입니다.","연기식입니다.","정답(아닌 것). 가용금속형은 열식","연기식입니다."],"t":"가용금속 = 열식"},"2023-2-직무일반-22":{"w":"선박검사증서 유효기간이 끝나면 정기검사를 받습니다.","x":["중간검사가 아닙니다.","건조검사가 아닙니다.","정답. 정기검사","임시검사가 아닙니다."],"t":"유효기간 만료 = 정기검사"},"2023-2-직무일반-25":{"w":"영해 기선에서 3해리 이상 12해리 미만에서는 음식물 찌꺼기를 25[mm] 이하로 분쇄해야 배출할 수 있습니다. 12해리 이상은 분쇄하지 않아도 됩니다.","x":["정답. 25[mm] 이하","틀립니다.","틀립니다.","틀립니다."],"t":"3~12해리 = 25mm 이하 분쇄"},"2023-2-영어-2":{"w":"ACC = Automatic Combustion Control(자동 연소 제어)입니다.","x":["맞는 약어입니다.","맞는 약어입니다.","정답(옳지 않은 것). ACC = Automatic Combustion Control","맞는 약어입니다."],"t":"ACC = 자동연소제어"},"2023-2-영어-3":{"w":"\"기름이 ( )에서 조금 새고 있다.\" hose, flange, valve는 새는 곳으로 알맞지만 impeller(임펠러)는 펌프 내부 회전체로 알맞지 않습니다.","x":["호스","플랜지","정답(적당하지 않은 것). 임펠러","밸브"],"t":"spilling = 새다"},"2023-2-영어-4":{"w":"Out of order = 고장 입니다.","x":["정답. 고장","발밑 조심","수리 중","출입 금지"],"t":"out of order = 고장"},"2023-2-영어-5":{"w":"연료분사시기 = injection timing 입니다.","x":["ignition timing = 점화시기","틀립니다.","정답. injection timing","틀립니다."],"t":"injection timing = 분사시기"},"2023-2-영어-6":{"w":"Salinometer = 염분 농도계 입니다.","x":["산소 농도계가 아닙니다.","정답. 염분 농도계","틀립니다.","틀립니다."],"t":"saline = 염분"},"2023-2-영어-7":{"w":"\"피스톤링, 링 홈, 실린더 톱 클리어런스를 측정할 것.\" measure = 측정하다.","x":["충전","교체","정답. measured","다시 채움"],"t":"to be measured = 측정할 것"},"2023-2-영어-8":{"w":"\"주기관 섬프 탱크의 양을 확인했다.\" amount = 양.","x":["정답. amount","인화점","점도","연소점"],"t":"ascertain amount = 양 확인"},"2023-2-영어-9":{"w":"\"공기의 ( )을 확인하겠다\" — 온도, 누설, 압력은 알맞지만 점도(viscosity)는 공기에 쓰지 않습니다.","x":["알맞습니다.","정답(적합하지 않은 것). viscosity","알맞습니다.","알맞습니다."],"t":"viscosity = 액체 점도"},"2023-2-영어-10":{"w":"Molded case circuit breaker(MCCB) = 배선용 차단기 입니다.","x":["기중차단기는 ACB입니다.","진공차단기는 VCB입니다.","틀립니다.","정답. 배선용 차단기"],"t":"MCCB = 배선용 차단기"},"2023-2-영어-11":{"w":"pieces = 개. \"배기가스 온도계 20개를 받았다.\"","x":["틀립니다.","정답. 20개","틀립니다.","틀립니다."],"t":"piece = 개"},"2023-2-영어-12":{"w":"메거로 재는 것은 insulation resistance(절연저항)입니다.","x":["인덕턴스","어드미턴스","주파수","정답. resistance"],"t":"megger = insulation resistance"},"2023-2-영어-13":{"w":"ascertain(확인하다) ≒ confirm(확인하다).","x":["이송했다","바꿨다","옮겼다","정답. Confirmed"],"t":"ascertained ≒ confirmed"},"2023-2-영어-14":{"w":"\"각 부의 온도와 압력을 자주 점검하시오.\" check = 점검하다.","x":["교체","연결","정답. Checked","배출"],"t":"check = 점검"},"2023-2-영어-16":{"w":"축전지 전해액의 비중은 hydrometer(비중계)로 잽니다.","x":["고온계","점도계","정답. hydrometer","습도계"],"t":"hydrometer = 비중계"},"2023-2-영어-17":{"w":"디젤기관에서 연료는 피스톤이 가장 높은 위치(highest)인 상사점(TDC) 부근에서 분사됩니다.","x":["lowest가 틀립니다.","정답. TDC, highest","BDC가 틀립니다.","BDC가 틀립니다."],"t":"분사 = TDC 부근"},"2023-2-영어-18":{"w":"흡·배기밸브가 모두 닫히고 피스톤이 올라가며 공기를 압축하는 것은 압축행정입니다.","x":["흡입행정이 아닙니다.","배기행정이 아닙니다.","작동행정이 아닙니다.","정답. Compression stroke"],"t":"압축행정"},"2023-2-영어-19":{"w":"윤활유는 마찰·마모 감소, 냉각, 밀봉 등을 합니다. 속도를 제한하는 것은 윤활유의 목적이 아닙니다.","x":["정답(옳지 않은 것). 속도 제한","냉각은 목적입니다.","마찰 감소는 목적입니다.","밀봉은 목적입니다."],"t":"윤활유 ≠ 속도 제한"},"2023-2-영어-20":{"w":"기계효율 = BHP ÷ IHP 입니다.","x":["반대입니다.","틀립니다.","틀립니다.","정답. BHP/IHP"],"t":"기계효율 = BHP / IHP"},"2023-2-영어-21":{"w":"압력이 너무 높을 때 증기를 방출해 폭발을 막는 것은 safety valve(안전밸브)입니다.","x":["역지밸브","흡기밸브","정답. safety valve","배기밸브"],"t":"safety valve = 과압 방출"},"2023-2-영어-22":{"w":"기밀 유지, 열 전달, 라이너 윤활은 피스톤링(piston ring)의 역할입니다.","x":["정답. The purpose of piston ring","피스톤이 아닙니다.","배기밸브가 아닙니다.","라이너가 아닙니다."],"t":"piston ring = 기밀·열전달·윤활"},"2023-2-영어-23":{"w":"\"연료유는 청정된 뒤 서비스(service) 탱크에 저장된다.\"","x":["슬러지 탱크","정답. service tank","저장 탱크는 청정 전입니다.","넘침 탱크"],"t":"청정 후 = service tank"},"2023-2-영어-24":{"w":"\"선박의 대부분의 냉각기(coolers)는 뜨거운 유체의 열을 해수나 청수로 옮긴다.\"","x":["정답. coolers","보일러가 아닙니다.","연료 탱크가 아닙니다.","가열기가 아닙니다."],"t":"cooler = 냉각기"},"2023-3-기관1-1":{"w":"소기효율은 소기가 끝난 뒤 실린더 안에 남은 새 공기(급기)의 무게를 실린더 안 전체 가스 무게로 나눈 값입니다. 잔류 배기가스가 적을수록 높습니다.","x":["정답. 소기효율","급기효율은 공급 공기량 기준입니다.","충전효율은 표준 상태 공기량 기준입니다.","용적효율은 흡입 부피의 비율입니다."],"t":"소기효율 = 새 공기 / 전체 가스"},"2023-3-기관1-2":{"w":"4행정 기관은 흡·배기 기간이 길고, 흡·배기가 서로 간섭하지 않으며, 피스톤이 배기를 밀어내므로 가스 교환이 좋습니다. 소기 펌프가 없다는 것은 가스 교환이 좋은 이유가 아닙니다.","x":["정답(아닌 것). 소기 펌프 유무는 이유가 아닙니다.","이유입니다.","이유입니다.","이유입니다."],"t":"4행정 = 피스톤이 배기를 밀어냄"},"2023-3-기관1-4":{"w":"라이너 하부 냉각수 누설은 고무링의 재질 불량, 경화(탄성 저하), 홈 부식 등으로 생깁니다. 고무링의 탄성이 큰 것은 밀봉이 잘 되는 좋은 상태입니다.","x":["정답(아닌 것). 탄성이 크면 밀봉이 잘 됩니다.","원인입니다.","원인입니다.","원인입니다."],"t":"고무링 = 탄성 좋을수록 밀봉 양호"},"2023-3-기관1-5":{"w":"트렁크형 피스톤 윗면을 오목하게 만들면 공기의 와류가 생기고 연료와 잘 섞여 연소가 좋아집니다.","x":["정답. 연소 개선","강도가 목적이 아닙니다.","압축비는 오히려 작아집니다.","변형 감소가 목적이 아닙니다."],"t":"오목한 피스톤 윗면 = 와류·연소 개선"},"2023-3-기관1-6":{"w":"제동마력 = 지시마력 − 손실 = 400 × (1 − 0.22) = 312[PS]입니다.","x":["틀립니다.","정답. 400 × 0.78 = 312[PS]","틀립니다.","틀립니다."],"t":"BHP = IHP × 기계효율"},"2023-3-기관1-7":{"w":"배기밸브가 새면 압축압력이 떨어지고 출력이 줄며, 고온 가스가 새어 배기온도가 오릅니다. 압력이 떨어지므로 안전밸브는 열리지 않습니다.","x":["출력이 떨어집니다.","압축압력이 떨어집니다.","정답(옳지 않은 것). 안전밸브는 열리지 않습니다.","배기온도가 오릅니다."],"t":"배기밸브 누설 = 압축압력↓·배기온도↑"},"2023-3-기관1-8":{"w":"과급기는 공기를 더 많이 넣어 더 많은 연료를 태우게 하므로 평균유효압력을 높입니다.","x":["조속기는 회전수를 조절합니다.","시동공기 분배기는 시동용입니다.","정답. 과급기","소음기는 소음을 줄입니다."],"t":"평균유효압력↑ = 과급기"},"2023-3-기관1-11":{"w":"보슈형 펌프는 래크로 플런저를 회전시켜 경사홈의 위치를 바꿔 유효행정(토출량)을 조절합니다.","x":["토출밸브를 돌리지 않습니다.","정답. 플런저를 회전","스필밸브는 다른 형식입니다.","흡입밸브로 조절하지 않습니다."],"t":"보슈형 = 플런저 회전"},"2023-3-기관1-13":{"w":"버너의 진동 연소는 연료유 압력 변동, 수분 혼입, 가열 온도 과다(기포 발생) 등으로 생깁니다. 보일러 부하 변화는 진동 연소의 원인이 아닙니다.","x":["원인입니다.","정답(아닌 것). 부하 변화는 원인이 아닙니다.","원인입니다.","원인입니다."],"t":"진동 연소 = 연료 압력·수분·과열"},"2023-3-기관1-14":{"w":"화염검출기가 불꽃이 꺼진 것을 감지하면 그 신호로 연료차단밸브를 닫아 노 안에 연료가 쌓이는 것(폭발)을 막습니다.","x":["안전밸브가 아닙니다.","급수차단밸브가 아닙니다.","통풍 차단이 아닙니다.","정답. 연료차단밸브"],"t":"화염 소실 → 연료 차단"},"2023-3-기관1-15":{"w":"복수기 부속장치는 순환수(냉각수) 펌프, 복수 펌프, 공기 이젝터 등입니다. 급수펌프는 보일러에 급수하는 장치로 복수기 부속장치가 아닙니다.","x":["부속장치입니다.","정답(아닌 것). 급수펌프는 보일러용입니다.","부속장치입니다.","부속장치입니다."],"t":"복수기 = 순환수펌프·복수펌프·공기이젝터"},"2023-3-기관1-16":{"w":"축계 어스(접지)장치는 축에 붙인 슬립링에 브러시를 접촉시켜 축과 선체의 전위차를 줄입니다.","x":["정답. 브러시","증기밸브와 관계없습니다.","리그넘바이티는 선미관 베어링 재료입니다.","패킹글랜드와 관계없습니다."],"t":"축 접지 = 슬립링 + 브러시"},"2023-3-기관1-18":{"w":"겉보기 슬립 = (Vp − V) ÷ Vp 입니다.","x":["정답. (Vp − V) / Vp","틀린 식입니다.","틀린 식입니다.","틀린 식입니다."],"t":"슬립 = (이론 − 실제) / 이론"},"2023-3-기관1-19":{"w":"추진기가 수면 가까이 있어(심도가 얕아) 수압이 낮으면 공동현상이 잘 생깁니다. 슬립·추력·회전속도가 클수록 잘 생깁니다.","x":["슬립이 클 때 생깁니다.","추력이 클 때 생깁니다.","정답. 심도가 얕을 때","속도가 빠를 때 생깁니다."],"t":"공동현상 = 얕은 심도·고속·큰 슬립"},"2023-3-기관1-20":{"w":"프로펠러 회전에 의한 축계 진동은 캐비테이션, 심도 부족, 축 중심선 불일치 등으로 생깁니다. 보스 지름이 큰 것은 진동 원인이 아닙니다.","x":["원인입니다.","원인입니다.","정답(아닌 것). 보스 지름은 원인이 아닙니다.","원인입니다."],"t":"축계 진동 = 캐비테이션·심도·축심"},"2023-3-기관1-21":{"w":"건조 마찰은 윤활제 없이 고체끼리 직접 닿는 고체 마찰입니다.","x":["정답. 고체 마찰","경계 마찰은 얇은 유막이 있습니다.","유체 마찰은 유막으로 분리됩니다.","액체 마찰도 유막이 있습니다."],"t":"건조 마찰 = 고체 마찰"},"2023-3-기관1-22":{"w":"실린더유는 연료의 황이 만든 황산을 중화해야 하므로 산성이 아니라 알칼리성(고 TBN)이어야 합니다.","x":["인화점이 높아야 합니다.","정답(옳지 않은 것). 알칼리성이어야 합니다.","열전도가 좋아야 합니다.","점도 변화가 적어야 합니다."],"t":"실린더유 = 알칼리성(TBN)"},"2023-3-기관1-24":{"w":"윤활유 압력이 떨어지는 원인은 여과기 막힘(펌프 흡입측), 베어링 간극 과대, 펌프 공기 흡입, 온도 상승으로 인한 점도 저하 등입니다. 온도가 낮아 점도가 올라가면 압력은 오히려 올라갑니다.","x":["원인입니다.","원인입니다.","원인입니다.","정답(아닌 것). 점도가 오르면 압력은 올라갑니다."],"t":"윤활유 압력↓ = 간극↑·공기·점도↓"},"2023-3-기관2-1":{"w":"실제 흡입양정이 이론값(약 10.33[m])보다 낮은 이유는 완전 진공을 못 만들고, 흡입관 마찰 손실이 있으며, 오래 쓰면 손실이 늘기 때문입니다. 펌프 용량과는 관계없습니다.","x":["정답(아닌 것). 펌프 용량은 관계없습니다.","이유입니다.","이유입니다.","이유입니다."],"t":"흡입양정 한계 ≒ 10m보다 낮음"},"2023-3-기관2-2":{"w":"벌류트(원심) 펌프는 송출밸브를 조여 송출량을 조절합니다. 흡입밸브를 조이면 캐비테이션이 생깁니다.","x":["흡입밸브를 조이면 안 됩니다.","정답. 송출밸브로 조절","적절하지 않습니다.","해당하지 않습니다."],"t":"원심펌프 유량 = 송출밸브"},"2023-3-기관2-4":{"w":"원심식 송풍기는 진동·소음이 적고, 송출이 연속적이며, 작고 가볍습니다. 대신 고속 회전이 필요합니다.","x":["장점입니다.","정답(옳지 않은 것). 고속 회전이 적합합니다.","장점입니다.","장점입니다."],"t":"원심 송풍기 = 고속"},"2023-3-기관2-6":{"w":"워핑드럼이 수직축에 설치된 계선 장치는 캡스턴입니다.","x":["정답. 캡스턴(수직축)","무어링 윈치는 수평축입니다.","윈드라스는 양묘용입니다.","데릭 윈치는 하역용입니다."],"t":"캡스턴 = 수직축"},"2023-3-기관2-10":{"w":"자동배유장치는 유면검출기와 전자밸브(그리고 타이머)로 구성됩니다.","x":["교반기는 없습니다.","빌지펌프는 배유장치가 아닙니다.","정답. 유면검출기, 전자밸브","틀립니다."],"t":"자동배유 = 유면검출기 + 전자밸브"},"2023-3-기관2-11":{"w":"냉동장치는 증발기에서 냉매가 증발할 때 주위의 열(증발열, 잠열)을 흡수합니다.","x":["정답. 증발열","승화열이 아닙니다.","응고열이 아닙니다.","현열이 아닙니다."],"t":"냉동 = 증발잠열"},"2023-3-기관2-13":{"w":"냉매는 압축기 → 응축기 → 팽창밸브 → 증발기 순서로 순환합니다.","x":["순서가 틀렸습니다.","정답. 압축 → 응축 → 팽창 → 증발","순서가 틀렸습니다.","순서가 틀렸습니다."],"t":"압축 → 응축 → 팽창 → 증발"},"2023-3-기관2-14":{"w":"압축기 과열 원인은 윤활유 부족, 재킷 냉각 불충분, 불응축 가스(공기) 혼입, 압축비 과대 등입니다. 냉매가 부족하면 과열 원인이 될 수 있지만, 여기서 원인이 아닌 것으로 출제되었습니다.","x":["정답(아닌 것, 출제 기준).","원인입니다.","원인입니다.","원인입니다."],"t":"압축기 과열 = 윤활·냉각 부족·공기 혼입","c":"냉매가 부족하면 흡입 과열도가 커져 압축기가 과열될 수도 있으나, 공식 정답은 ㉮입니다."},"2023-3-기관2-16":{"w":"리머는 드릴로 뚫은 구멍의 내면을 정밀하게 다듬질하는 공구입니다.","x":["축 표면이 아닙니다.","정답. 구멍 내면 다듬질","나사산이 아닙니다.","모서리가 아닙니다."],"t":"리머 = 구멍 다듬질"},"2023-3-기관2-17":{"w":"선반으로 절삭, 보링, 널링, 나사 가공 등을 할 수 있습니다. 단조는 두드려 성형하는 작업으로 선반 작업이 아닙니다.","x":["선반 작업입니다.","정답(아닌 것). 단조","선반 작업입니다.","선반 작업입니다."],"t":"단조 = 해머·프레스"},"2023-3-기관2-18":{"w":"유체를 한 방향으로만 흐르게 해 역류를 막는 밸브는 체크 밸브입니다.","x":["릴리프 밸브는 압력 제한용입니다.","정답. 체크 밸브","안전 밸브는 과압 방출용입니다.","니들 밸브는 미세 유량 조절용입니다."],"t":"체크 밸브 = 역류 방지"},"2023-3-기관2-19":{"w":"핸드실드의 차광유리(필터 렌즈) 앞에 보호유리를 대는 것은 튀는 스패터로부터 비싼 필터 렌즈를 보호하기 위해서입니다.","x":["눈 보호는 차광유리의 역할입니다.","목적이 아닙니다.","정답. 필터 렌즈 보호","감전과 관계없습니다."],"t":"보호유리 = 필터 렌즈 보호"},"2023-3-기관2-20":{"w":"배관 색 구분에서 청색은 청수(물)를 나타냅니다. 증기는 은색·흰색, 공기는 하늘색 등, 기름은 갈색·황색 계열입니다.","x":["증기가 아닙니다.","정답. 청수","공기가 아닙니다.","윤활유가 아닙니다."],"t":"청색 = 청수"},"2023-3-기관2-21":{"w":"파도 마루(파정)가 선수·선미에, 골(파곡)이 가운데 있으면 가운데가 처지는 새깅 상태가 됩니다.","x":["래킹은 비틀림 변형입니다.","정답. 새깅","슬래밍은 선수가 수면을 치는 충격입니다.","호깅은 가운데가 솟는 상태입니다."],"t":"새깅 = 가운데 처짐, 호깅 = 가운데 솟음"},"2023-3-기관2-23":{"w":"선체 저항을 이기고 배를 예인하는 데 필요한 마력은 유효마력(EHP)입니다.","x":["제동마력은 기관 출력입니다.","정답. 유효마력","축마력은 축의 동력입니다.","전달마력은 프로펠러에 전달되는 동력입니다."],"t":"예인마력 = 유효마력"},"2023-3-기관2-24":{"w":"죔새는 축의 지름이 구멍의 지름보다 클 때 두 지름의 차입니다. 작을 때의 차는 틈새입니다.","x":["맞는 설명입니다.","맞는 설명입니다.","맞는 설명입니다.","정답(옳지 않은 것). 죔새는 축이 클 때입니다."],"t":"축 > 구멍 = 죔새, 축 < 구멍 = 틈새"},"2023-3-기관2-25":{"w":"물체의 특징을 가장 잘 나타내는 대표 투상도는 정면도입니다.","x":["평면도가 아닙니다.","측면도가 아닙니다.","배면도가 아닙니다.","정답. 정면도"],"t":"대표 투상도 = 정면도"},"2023-3-기관3-1":{"w":"3∥6 = 3×6/(3+6) = 2[Ω], 2∥2 = 1[Ω]. 두 부분이 직렬이므로 2 + 1 = 3[Ω]입니다.","x":["틀립니다.","한쪽만 계산했습니다.","정답. 2 + 1 = 3[Ω]","틀립니다."],"t":"두 저항 병렬 = 곱 / 합"},"2023-3-기관3-2":{"w":"금속(구리, 알루미늄, 철)은 온도가 오르면 저항이 커지고, 탄소·반도체는 온도가 오르면 저항이 작아집니다.","x":["금속은 저항이 커집니다.","금속은 저항이 커집니다.","정답. 탄소","금속은 저항이 커집니다."],"t":"탄소·반도체 = 부(−)의 온도계수"},"2023-3-기관3-6":{"w":"콘덴서 정전용량은 극판 면적이 넓을수록, 간격이 좁을수록, 유전율이 클수록 커집니다.","x":["전극이 2개입니다.","절연체(유전체)가 있습니다.","유전율이 크면 증가합니다.","정답(옳지 않은 것). 간격이 좁을수록 커집니다."],"t":"C = εA / d"},"2023-3-기관3-8":{"w":"코일은 전류의 급변을 억제하고(전류 평활), 주파수가 높을수록 저항(리액턴스)이 커지며, 전압이 전류보다 앞서게 합니다. 전압 변화를 완화하는 것은 콘덴서의 역할입니다.","x":["사용 목적에 해당합니다(출제 기준).","정답(아닌 것). 전압 완화는 콘덴서","코일의 성질입니다.","코일의 성질입니다."],"t":"L = 전류 변화 억제, C = 전압 변화 억제"},"2023-3-기관3-9":{"w":"△결선에서 선전류 = √3 × 상전류, 상전압 = 선간전압입니다.","x":["반대입니다.","정답. 선전류 = √3 상전류","Y결선입니다.","틀립니다."],"t":"△ = 전류 √3배"},"2023-3-기관3-10":{"w":"교류는 시간에 따라 크기와 방향이 계속 바뀌고, 직류는 방향이 일정합니다.","x":["직류는 방향이 바뀌지 않습니다.","정답. 교류는 크기·방향이 변함","틀립니다.","틀립니다."],"t":"교류 = 크기·방향 변화"},"2023-3-기관3-11":{"w":"주파수 f = 1 ÷ 주기 = 1 ÷ 0.2 = 5[Hz]입니다.","x":["틀립니다.","정답. 1 ÷ 0.2 = 5[Hz]","틀립니다.","틀립니다."],"t":"f = 1 / T"},"2023-3-기관3-12":{"w":"한시 접점 기호에서 아래로 향한 삼각형(∨)이 붙은 것이 순시동작 한시복귀(OFF 딜레이) 접점입니다.","x":["수동복귀 접점입니다.","정답. 순시동작 한시복귀","다른 접점입니다.","푸시 버튼입니다."],"t":"한시 접점 = 삼각형 표시"},"2023-3-기관3-13":{"w":"△-△ 결선의 3P에서 한 대가 고장 나 V-V 결선으로 쓰면 용량은 √3 P가 됩니다(이용률 86.6[%]).","x":["틀립니다.","원래 용량입니다.","틀립니다.","정답. √3 P"],"t":"V결선 용량 = √3 P"},"2023-3-기관3-14":{"w":"발전기 ACB는 과전류, 저전압(부족전압), 역전력 등일 때 자동으로 차단됩니다.","x":["정답. 저전압, 과전류","저부하·역률로 차단하지 않습니다.","역률로 차단하지 않습니다.","저부하로 차단하지 않습니다."],"t":"ACB 트립 = 과전류·저전압·역전력"},"2023-3-기관3-16":{"w":"납축전지 단전지 1개(공칭 2[V])의 방전종지전압은 약 1.75~1.8[V]입니다. 이 이하로 방전하면 수명이 줄어듭니다.","x":["너무 낮습니다.","정답. 1.75[V]","공칭 전압입니다.","충전 시 전압입니다."],"t":"납축전지 방전종지 ≒ 1.75V"},"2023-3-기관3-17":{"w":"동기발전기에 유도성(지상) 부하가 걸리면 전기자 반작용이 계자 자속을 줄이는 감자작용을 합니다. 용량성 부하는 증자작용, 저항 부하는 교차자화작용입니다.","x":["저항 부하입니다.","정답. 감자작용","용량성 부하입니다.","해당하지 않습니다."],"t":"유도성 = 감자, 용량성 = 증자"},"2023-3-기관3-19":{"w":"N형 반도체의 다수 반송자는 전자, P형은 정공입니다.","x":["P형의 다수 반송자입니다.","정답. 전자","틀립니다.","틀립니다."],"t":"N형 = 전자"},"2023-3-기관3-20":{"w":"A, B 모두 1일 때만 X가 0이므로 NAND(㉯)입니다.","x":["AND입니다.","정답. NAND","OR입니다.","NOR입니다."],"t":"둘 다 1일 때만 0 = NAND"},"2023-3-기관3-22":{"w":"이상적인 연산증폭기는 입력 저항 무한대, 출력 저항 0, 증폭 이득 무한대, 대역폭 무한대입니다.","x":["이상적 특성입니다.","정답(옳지 않은 것). 대역폭은 무한대입니다.","이상적 특성입니다.","이상적 특성입니다."],"t":"이상 OP앰프 = 이득·대역폭·입력저항 ∞"},"2023-3-기관3-24":{"w":"제너 다이오드는 역방향 항복 특성을 이용해 정전압 유지에 씁니다.","x":["정류용이 아닙니다.","검파용이 아닙니다.","정답. 정전압 유지","정류용이 아닙니다."],"t":"제너 = 정전압"},"2023-3-직무일반-1":{"w":"정박 중 기관일지에는 연료유 수급 시각과 양, 기관부 작업, 유류·청수 사용량과 잔량 등을 기록합니다. 조타기 유압유 잔량·압력은 기록 사항이 아닙니다.","x":["기록합니다.","기록합니다.","정답(아닌 것). 조타기 유압유는 기록하지 않습니다.","기록합니다."],"t":"정박 일지 = 수급·작업·소비량"},"2023-3-직무일반-2":{"w":"당직기관사는 주기관 정지·회전수 변경, 해양오염 우려 작업, 감속이 필요한 긴급 상황 등을 선교에 알립니다. 보일러 수저·수면 방출은 기관실 내부 작업입니다.","x":["통보합니다.","정답(아닌 것). 보일러 방출은 통보 사항이 아닙니다.","통보합니다.","통보합니다."],"t":"선교 통보 = 기관 변경·오염·긴급"},"2023-3-직무일반-3":{"w":"위험 방지를 위해 발전기 시동 시 터닝 바 위치, 밀폐 탱크 환기, 전기작업 시 차단기 차단을 확인합니다. 보일러 작업 시 안전밸브 조정 압력 확인은 위험 방지 수칙이 아닙니다.","x":["확인합니다.","정답(옳지 않은 것). 위험 방지 수칙이 아닙니다.","확인합니다.","확인합니다."],"t":"위험작업 = 터닝바·환기·전원 차단"},"2023-3-직무일반-4":{"w":"소모품은 개스킷, 형광등, 플랜지 등 쓰면 없어지거나 쉽게 교체하는 물품입니다. 실린더 헤드 스터드 볼트는 기관의 부품(비품)입니다.","x":["소모품입니다.","소모품입니다.","소모품입니다.","정답(아닌 것). 스터드 볼트는 비품입니다."],"t":"스터드 볼트 = 비품"},"2023-3-직무일반-7":{"w":"폐기물을 다른 선박이나 수용시설에 배출할 때는 배출 일시, 폐기물 종류·양, 수용 선박·시설명, 책임자 서명을 기재합니다. 선박의 위치는 해양 배출 때 기재합니다.","x":["기재합니다.","정답(옳지 않은 것). 위치는 해양 배출 때 기재합니다.","기재합니다.","기재합니다."],"t":"위치 = 해양 배출 기록"},"2023-3-직무일반-8":{"w":"연료 수급 전에는 갑판 배수구를 막아야 기름이 바다로 흐르지 않습니다.","x":["통신 수단을 점검합니다.","자주 측심합니다.","정답(옳지 않은 것). 배수구는 막습니다.","방제 자재를 비치합니다."],"t":"수급 = 스커퍼 폐쇄"},"2023-3-직무일반-9":{"w":"기름기록부는 최종 기재한 날로부터 3년간 보존합니다.","x":["틀립니다.","틀립니다.","정답. 3년","틀립니다."],"t":"기름기록부 3년"},"2023-3-직무일반-10":{"w":"기름방울이 클수록, 유속이 느릴수록, 온도가 높을수록 잘 떠올라 분리됩니다. 미세한 기름방울은 서로 뭉치게 해(조대화) 크게 만들어 분리합니다.","x":["클수록 빠릅니다.","느릴수록 분리가 잘 됩니다.","정답. 조대화로 분리","온도가 높을수록 빠릅니다."],"t":"조대화 = 기름방울 키우기"},"2023-3-직무일반-12":{"w":"혈액과 조직에 산소가 부족하고 이산화탄소가 쌓인 상태를 질식이라 합니다.","x":["정답. 질식","해당하지 않습니다.","쇼크는 순환 장애입니다.","기도폐쇄는 질식의 원인입니다."],"t":"질식 = O₂ 부족 + CO₂ 축적"},"2023-3-직무일반-13":{"w":"건강한 성인의 정상 맥박은 1분에 60~80회입니다.","x":["느립니다.","정답. 60~80회","빠릅니다.","빠릅니다."],"t":"맥박 60~80회"},"2023-3-직무일반-14":{"w":"수면 깊은 곳의 큰 파공은 방수매트를 선체 바깥에서 대면 수압이 매트를 눌러 붙여 막아 줍니다.","x":["즉시 용접은 불가능합니다.","큰 구멍은 걸레로 막을 수 없습니다.","안쪽에서는 수압을 이길 수 없습니다.","정답. 외부에서 수압으로 압착"],"t":"큰 파공 = 외부 방수매트"},"2023-3-직무일반-16":{"w":"급정지·후진 지시는 즉시 이행하고 텔레그래프로 응답하며 시각을 기록합니다. 사유를 먼저 확인하면 늦어 사고가 날 수 있습니다.","x":["즉시 조작합니다.","기관장에게 통보합니다.","정답(옳지 않은 것). 사유 확인보다 조작이 먼저입니다.","즉시 회신·기록합니다."],"t":"선교 명령 = 즉시 이행"},"2023-3-직무일반-17":{"w":"이송 중 누유하면 펌프 정지, 밸브 폐쇄, 관 속 기름 이송 후 수리합니다. 펌프 접지선은 정전기 방지용이므로 풀면 안 됩니다.","x":["펌프를 멈춥니다.","밸브를 잠급니다.","정답(옳지 않은 것). 접지선은 풀지 않습니다.","기름을 빼고 수리합니다."],"t":"접지선 = 정전기 방지"},"2023-3-직무일반-18":{"w":"연기식 탐지기는 광전자식, 이온화식, 안개실식 등입니다. 차동식은 온도 상승률로 작동하는 열식 탐지기입니다.","x":["정답(아닌 것). 차동식은 열식","연기식입니다.","연기식입니다.","연기식입니다."],"t":"차동식 = 열식"},"2023-3-직무일반-21":{"w":"세틀링 탱크 안에서 불이 나면 사람이 들어가지 말고 모든 개구부를 막아 산소를 차단(질식 소화)합니다.","x":["진입은 위험합니다.","물은 기름 화재에 부적합하고 진입은 위험합니다.","정답. 개구부 밀폐","진입은 위험합니다."],"t":"탱크 화재 = 밀폐 질식"},"2023-3-직무일반-22":{"w":"선박시설을 수리·개조할 때는 임시검사를 받습니다.","x":["정기검사가 아닙니다.","중간검사가 아닙니다.","정답. 임시검사","임시항해검사가 아닙니다."],"t":"수리·개조 = 임시검사"},"2023-3-직무일반-23":{"w":"선박안전법상 항해구역은 평수구역, 연해구역, 근해구역, 원양구역입니다. '연안구역'은 해당하지 않습니다.","x":["항해구역입니다.","정답(아닌 것). 연해구역이 맞습니다.","항해구역입니다.","항해구역입니다."],"t":"평수·연해·근해·원양"},"2023-3-직무일반-24":{"w":"선원법의 근로시간·휴식시간 기준은 원양어선 등 일부 어선에는 적용되지 않습니다(어선 특례).","x":["적용됩니다.","적용됩니다.","정답(적용 제외). 원양어선","적용됩니다."],"t":"원양어선 = 근로시간 기준 적용 제외"},"2023-3-영어-1":{"w":"insulation resistance = 절연저항 입니다.","x":["가변저항이 아닙니다.","틀립니다.","정답. 절연저항","틀립니다."],"t":"insulation resistance"},"2023-3-영어-2":{"w":"clearance(틈새) ≒ gap 입니다.","x":["지름","정답. gap = 틈","게이지","깊이"],"t":"clearance = gap"},"2023-3-영어-3":{"w":"R-22는 냉매이므로 refrigerant 입니다.","x":["냉동하다(동사)","정답. refrigerant = 냉매","냉장고","냉동(명사)"],"t":"refrigerant = 냉매"},"2023-3-영어-5":{"w":"주기관 = M/E. \"Overhauled No.3 Piston of M/E.\"","x":["정답. No.3 Piston of M/E","D/E = 디젤 발전기관","3번 주기관이 됩니다.","틀립니다."],"t":"M/E = 주기관"},"2023-3-영어-6":{"w":"BHP = Brake Horse Power = 제동마력입니다.","x":["지시마력","정답. BHP","추력마력","유효마력"],"t":"BHP = 제동마력"},"2023-3-영어-7":{"w":"\"시간당 몇 톤으로 펌핑하십니까?\" 시간당 공급량을 묻습니다.","x":["정답. 시간당 공급량","틀립니다.","틀립니다.","틀립니다."],"t":"per hour = 시간당"},"2023-3-영어-8":{"w":"F.O.T. = Fuel Oil Tank(연료유 탱크)입니다.","x":["맞습니다.","맞습니다.","정답(옳지 않은 것). F.O.T. = Fuel Oil Tank","맞습니다."],"t":"FOT = 연료유 탱크"},"2023-3-영어-9":{"w":"incineration = 소각 입니다.","x":["투기는 dumping입니다.","배출은 discharge입니다.","저장은 storage입니다.","정답. 소각"],"t":"incineration = 소각"},"2023-3-영어-11":{"w":"inspected(검사했다) ≒ examined(검사했다).","x":["배출했다","발견했다","분해 정비했다","정답. Examined"],"t":"inspect ≒ examine"},"2023-3-영어-12":{"w":"water pressure test = 수압 시험. \"윤활유 냉각기에 수압 시험을 했다.\"","x":["틀립니다.","정답. pressure","틀립니다.","틀립니다."],"t":"water pressure test = 수압시험"},"2023-3-영어-13":{"w":"주배전반에서 수리할 대상으로 MCCB(배선용 차단기)가 알맞습니다.","x":["ACC는 자동연소제어입니다.","DPT는 차압 발신기입니다.","FWC는 해당하지 않습니다.","정답. MCCB"],"t":"배전반 = MCCB·ACB"},"2023-3-영어-14":{"w":"system oil = 크랭크실 순환 윤활유(Crank chamber oil)입니다.","x":["정답. 크랭크실 윤활유","디젤유가 아닙니다.","유압유가 아닙니다.","기어유가 아닙니다."],"t":"system oil = 크랭크실 윤활유"},"2023-3-영어-15":{"w":"\"주 섬프 탱크 바닥의 기름을 퍼내고 내부를 청소했다.\" bail = 퍼내다.","x":["검사했다","교환했다","공급했다","정답. Bailed"],"t":"bail out = 퍼내다"},"2023-3-영어-16":{"w":"폐유, 슬러지, 고형 폐기물을 태우는 노는 incinerator(소각기)입니다.","x":["온수기","정답. incinerator","기름 보일러","배기가스 보일러"],"t":"incinerator = 소각기"},"2023-3-영어-21":{"w":"불꽃 점화 기관(spark-ignition engine)은 전기 점화(electric ignition)로 작동합니다(가솔린기관).","x":["정답. electric ignition","자연 착화가 아닙니다.","압축 착화는 디젤입니다.","디젤 착화가 아닙니다."],"t":"spark ignition = 가솔린, compression ignition = 디젤"},"2023-3-영어-22":{"w":"화재의 3요소는 연료(fuel), 열(heat), 산소(oxygen)입니다. power는 관계없습니다.","x":["3요소입니다.","3요소입니다.","3요소입니다.","정답(관계없는 것). power"],"t":"fire triangle = fuel·heat·oxygen"},"2023-4-기관1-1":{"w":"무기 분사식(고압 연료를 직접 분사하는 방식) 디젤기관은 정적·정압 연소가 섞인 복합(사바테) 사이클을 기본으로 합니다.","x":["정답. 복합 사이클","가솔린기관입니다.","공기 분사식 저속 디젤의 사이클입니다.","증기 사이클입니다."],"t":"무기 분사식 = 복합(사바테) 사이클"},"2023-4-기관1-2":{"w":"열기관은 연료가 탈 때 나오는 열 에너지를 기계적 에너지(일)로 바꾸는 기계입니다.","x":["틀립니다.","틀립니다.","정답. 열 → 기계 에너지","틀립니다."],"t":"열기관 = 열 → 일"},"2023-4-기관1-5":{"w":"4행정 기관에서 배기행정 말기(상사점 부근)에는 가스 압력이 없고 피스톤 등의 관성력이 크랭크축을 위로 끌어올리므로 메인 베어링 캡에 최대 하중이 걸립니다.","x":["틀립니다.","정답. 배기행정 말기","틀립니다.","압축 말기에는 하중이 베어링 아래쪽(받침)에 걸립니다."],"t":"캡 최대 하중 = 배기 말(관성력)"},"2023-4-기관1-6":{"w":"트렁크형 기관의 라이너 마멸 직접 원인은 불완전 연소, 링 기밀 불량, 크랭크실 윤활유 오손 등입니다. 라이너 내벽 온도 상승 자체는 직접 원인으로 보지 않습니다.","x":["원인입니다.","원인입니다.","원인입니다.","정답(아닌 것). 내벽 온도 상승"],"t":"트렁크형 = 크랭크실 윤활유가 라이너 윤활"},"2023-4-기관1-7":{"w":"백색합금(화이트 메탈)은 주석(Sn) 또는 납(Pb)을 주성분으로 한 베어링 합금입니다.","x":["청동·황동입니다.","경합금입니다.","정답. 주석 또는 납의 합금","틀립니다."],"t":"화이트 메탈 = 주석·납계"},"2023-4-기관1-9":{"w":"고정 피치 프로펠러를 구동하는 주기관의 출력은 회전수의 세제곱에 비례해 증가합니다(프로펠러 법칙).","x":["틀립니다.","토크는 제곱에 비례합니다.","정답. 세제곱 비례 증가","감소하지 않습니다."],"t":"출력 ∝ N³, 토크 ∝ N²"},"2023-4-기관1-10":{"w":"성능곡선(시운전 곡선)에는 회전수·출력에 따른 연료소비율, 기계효율, 최고압력, 배기온도 등이 나옵니다. 연료분사압력은 나오지 않습니다.","x":["알 수 있습니다.","알 수 있습니다.","알 수 있습니다.","정답(알 수 없는 것). 연료분사압력"],"t":"성능곡선 ≠ 분사압력"},"2023-4-기관1-11":{"w":"과급된 공기는 압축되며 온도가 올라가 밀도가 낮아집니다. 공기 냉각기로 식히면 밀도가 높아져 더 많은 공기를 실린더에 넣을 수 있습니다.","x":["주목적이 아닙니다.","주목적이 아닙니다.","정답. 공기 밀도를 높이기 위해","오히려 착화지연은 길어질 수 있습니다."],"t":"공기 냉각기 = 밀도 증가"},"2023-4-기관1-13":{"w":"보일러 안전밸브 스프링은 상온에서 밀착될 때까지 압축해 10분 두었을 때 영구 변형이 자유 높이의 1[%]를 넘으면 안 됩니다.","x":["정답. 1[%]","틀립니다.","틀립니다.","틀립니다."],"t":"안전밸브 스프링 영구변형 ≤ 1%"},"2023-4-기관1-14":{"w":"팽창 중인 증기 일부를 뽑아 급수를 가열하는 사이클은 재생 사이클입니다. 다시 가열해 터빈에 넣는 것은 재열 사이클입니다.","x":["이론 사이클입니다.","기본 증기 사이클입니다.","정답. 재생 사이클","재열 사이클은 증기를 다시 가열합니다."],"t":"재생 = 추기로 급수 가열, 재열 = 증기 재가열"},"2023-4-기관1-15":{"w":"복수기 진공을 유지하려면 공기 이젝터(공기 제거), 복수 펌프(복수 제거), 냉각수 펌프(냉각)가 필요합니다. 급수 펌프는 보일러에 물을 넣는 장치입니다.","x":["필요합니다.","필요합니다.","필요합니다.","정답(아닌 것). 급수 펌프"],"t":"진공 유지 = 공기이젝터·복수펌프·냉각수펌프"},"2023-4-기관1-16":{"w":"컬러 체크는 침투액과 현상액을 쓰는 침투 탐상법입니다.","x":["자분 탐상법입니다.","초음파 탐상법입니다.","고주파 탐상법입니다.","정답. 침투 탐상법"],"t":"컬러 체크 = 침투 탐상"},"2023-4-기관1-17":{"w":"기관 회전 방향은 그대로 두고 날개 각도를 바꿔 전진·후진하는 추진기는 가변 피치 프로펠러(CPP)입니다.","x":["분사추진기(워터제트)가 아닙니다.","고정 피치는 날개 각도가 고정됩니다.","외차추진기가 아닙니다.","정답. 가변 피치 프로펠러"],"t":"CPP = 날개 각도로 전후진"},"2023-4-기관1-18":{"w":"30°에서 20[cm]를 나아가면 한 바퀴(360°)에는 20 × (360 ÷ 30) = 240[cm]를 나아갑니다.","x":["틀립니다.","틀립니다.","틀립니다.","정답. 20 × 12 = 240[cm]"],"t":"피치 = 부분 피치 × 360 / 각도"},"2023-4-기관1-19":{"w":"물·공기 저항을 이기며 선체를 예인하는 데 필요한 마력은 유효마력입니다.","x":["도시마력은 실린더 안 마력입니다.","전달마력이 아닙니다.","제동마력이 아닙니다.","정답. 유효마력"],"t":"예인 = 유효마력"},"2023-4-기관1-20":{"w":"프로펠러 날개가 손상되면 진동이 생기고 추진력과 추진효율이 떨어집니다. 반류 증가는 날개 손상의 영향이 아닙니다.","x":["진동이 생깁니다.","추진력이 줄어듭니다.","정답(옳지 않은 것). 반류와 관계없습니다.","추진효율이 떨어집니다."],"t":"날개 손상 = 진동·추진력↓"},"2023-4-기관1-21":{"w":"수증기의 증발잠열을 뺀 발열량은 저위 발열량입니다.","x":["정답. 저위 발열량","고위 발열량은 증발잠열을 포함합니다.","틀립니다.","틀립니다."],"t":"저위 = 증발잠열 제외"},"2023-4-기관1-22":{"w":"세틀링 탱크는 기름을 가열하고 가만히 두어 물과 불순물을 중력으로 가라앉히는 침전법으로 분리합니다.","x":["정답. 침전법","원심분리는 청정기입니다.","여과는 여과기입니다.","틀립니다."],"t":"세틀링 탱크 = 침전"},"2023-4-기관1-24":{"w":"윤활유 열화 원인은 물·연료유·먼지 혼입, 고온, 산화 등입니다. 새 윤활유 보충은 오히려 성질을 개선합니다.","x":["원인입니다.","원인입니다.","원인입니다.","정답(아닌 것). 새 윤활유 보충"],"t":"열화 = 오염·고온·산화"},"2023-4-기관2-1":{"w":"원심펌프는 원심력으로 액체를 보내며, 고속 회전이 가능하고, 운전 전에 펌프 안을 액체로 채워야(마중물) 합니다. 송출이 연속적이어서 맥동이 거의 없습니다.","x":["맞는 설명입니다.","맞는 설명입니다.","정답(옳지 않은 것). 맥동이 거의 없습니다.","맞는 설명입니다."],"t":"원심펌프 = 맥동 없음, 마중물 필요"},"2023-4-기관2-2":{"w":"회전식 펌프는 기어, 나사, 베인 펌프 등입니다. 제트펌프는 고속 유체의 흐름으로 빨아올리는 특수 펌프입니다.","x":["정답(아닌 것). 제트펌프","회전식입니다.","회전식입니다.","회전식입니다."],"t":"제트펌프 = 이젝터 원리"},"2023-4-기관2-4":{"w":"전동 유압식 조타장치의 전동기는 항해 중 계속 회전하고, 조타할 때만 가변 용량 펌프의 송출 방향·양이 바뀌어 타를 움직입니다.","x":["정답. 항상 회전","틀립니다.","틀립니다.","틀립니다."],"t":"조타 전동기 = 상시 회전"},"2023-4-기관2-5":{"w":"불활성가스장치의 공급주관 가스 속 산소 농도는 5[%] 이하, 화물탱크 안은 8[%] 이하로 유지해야 합니다.","x":["틀립니다.","정답. 5[%] 이하","탱크 내 기준입니다.","틀립니다."],"t":"IGS 공급 5%↓, 탱크 8%↓"},"2023-4-기관2-6":{"w":"사이드 스러스터는 배가 거의 멈춰 있을 때(선속 0) 옆으로 미는 힘이 가장 큽니다. 속력이 나면 효과가 급격히 줄어듭니다.","x":["틀립니다.","전속에서는 효과가 거의 없습니다.","정답. 선속 0일 때","틀립니다."],"t":"사이드 스러스터 = 저속·정지 시 효과"},"2023-4-기관2-7":{"w":"기름배출감시제어장치(ODME)는 화물구역에서 배출되는 물의 기름 농도와 배출률을 감시·제어하는 장치입니다. 인화성 증기를 감시하는 장치가 아닙니다.","x":["맞는 설명입니다.","맞는 설명입니다.","정답(옳지 않은 것). ODME는 배출수의 기름을 감시합니다.","맞는 설명입니다."],"t":"ODME = 배출 기름 감시"},"2023-4-기관2-8":{"w":"유압식 계선 윈치는 조종 밸브로 유압모터에 가는 기름의 방향과 양을 바꿔 드럼의 회전 방향과 속도를 조절합니다.","x":["베벨 기어가 아닙니다.","펌프는 기름을 보낼 뿐입니다.","모터는 구동 장치입니다.","정답. 조종 밸브"],"t":"방향·속도 = 조종 밸브"},"2023-4-기관2-10":{"w":"오염된 물(오수)을 물리적·화학적·생물화학적으로 처리하는 장치는 오수처리장치입니다.","x":["공조장치가 아닙니다.","정답. 오수처리장치","기름을 분리하는 장치입니다.","폐유를 태우는 장치입니다."],"t":"오수처리장치 = 분뇨·오수 처리"},"2023-4-기관2-12":{"w":"불응축 가스(공기)가 들어가면 응축기에서 응축되지 않아 응축(압축) 압력이 높아지고, 동력이 늘며 냉동능력이 떨어집니다.","x":["흡입 압력과 관계없습니다.","응축 압력은 높아집니다.","냉동능력은 나빠집니다.","정답. 압축 압력 상승"],"t":"불응축 가스 = 고압 상승"},"2023-4-기관2-16":{"w":"버니어 캘리퍼스, 마이크로미터, 다이얼 게이지는 측정 공구이고, 바이스는 일감을 고정하는 공구입니다.","x":["측정 공구입니다.","측정 공구입니다.","측정 공구입니다.","정답(아닌 것). 바이스는 고정 공구입니다."],"t":"바이스 = 고정"},"2023-4-기관2-17":{"w":"드릴 작업 때는 가공물을 바이스로 고정하고, 장갑을 끼지 않으며(말려 들어감), 얇은 가공물은 나무 받침을 대고 작업합니다.","x":["손으로 잡으면 위험합니다.","장갑은 말려 들어가 위험합니다.","정답. 나무 받침대","가공물을 돌리면 위험합니다."],"t":"드릴 = 장갑 금지, 바이스 고정"},"2023-4-기관2-24":{"w":"기능상 지장이 없는 범위에서 미리 정한 치수의 허용량을 공차라 합니다.","x":["정답. 공차","해칭은 단면 표시입니다.","스머징은 단면 칠하기입니다.","거칠기는 표면 상태입니다."],"t":"공차 = 허용 범위"},"2023-4-기관2-25":{"w":"해칭(단면을 나타내는 빗금)은 가는 실선으로 그립니다.","x":["굵은 실선은 외형선입니다.","자유 실선은 파단선입니다.","정답. 가는 실선","2점 쇄선은 가상선입니다."],"t":"해칭 = 가는 실선"},"2023-4-기관3-1":{"w":"유도 리액턴스 XL = 2πfL [Ω]입니다.","x":["해당하지 않는 식입니다.","해당하지 않는 식입니다.","정답. XL = 2πfL","해당하지 않는 식입니다."],"t":"XL = 2πfL"},"2023-4-기관3-2":{"w":"저항, 유도 리액턴스, 용량 리액턴스를 합친 교류 회로의 전체 저항을 임피던스라 합니다.","x":["저항만이 아닙니다.","커패시턴스는 정전용량입니다.","정답. 임피던스","유도 리액턴스만입니다."],"t":"Z = √(R² + (XL − XC)²)"},"2023-4-기관3-4":{"w":"전압이 2배면 전류도 2배(I = V/R), 전력은 P = V²/R 이므로 4배가 됩니다.","x":["전력이 틀립니다.","정답. 전류 2배, 전력 4배","틀립니다.","틀립니다."],"t":"P ∝ V²"},"2023-4-기관3-5":{"w":"거주실 전원 220[V]는 실효값입니다.","x":["최대값이 아닙니다.","순시값이 아닙니다.","정답. 실효값","평균값이 아닙니다."],"t":"전원 표시 = 실효값"},"2023-4-기관3-6":{"w":"전기자 전류가 만드는 자속이 주 자극(계자)의 자속에 영향을 주는 현상을 전기자 반작용이라 합니다.","x":["전자력이 아닙니다.","유도 기전력이 아닙니다.","정류 작용이 아닙니다.","정답. 전기자 반작용"],"t":"전기자 반작용 = 전기자 자속의 영향"},"2023-4-기관3-7":{"w":"△결선에서는 상전압과 선간전압이 같습니다(1배).","x":["정답. 1배","틀립니다.","Y결선의 관계입니다.","틀립니다."],"t":"△ = 전압 같음"},"2023-4-기관3-9":{"w":"i = 5√2 sinωt 에서 sin 앞의 계수가 최대값이므로 5√2[A]입니다.","x":["틀립니다.","틀립니다.","실효값입니다.","정답. 5√2[A]"],"t":"i = Im sinωt"},"2023-4-기관3-10":{"w":"유도전동기의 회전자는 회전자계(동기속도)보다 조금 느리게 돕니다.","x":["정답. 회전자계가 더 빠름","반대입니다.","같으면 토크가 0입니다.","틀립니다."],"t":"동기속도 > 회전자 속도"},"2023-4-기관3-11":{"w":"철심을 얇게 성층하면 맴돌이 전류(와류) 손실을 줄일 수 있습니다.","x":["정답. 와류손 방지","히스테리시스손은 규소강으로 줄입니다.","마찰손과 관계없습니다.","표유부하손과 관계없습니다."],"t":"성층 = 와류손↓"},"2023-4-기관3-12":{"w":"여자기는 교류발전기의 계자 권선에 직류 전류를 공급해 자속을 만듭니다.","x":["주파수는 회전수로 정해집니다.","부하 분담은 거버너가 합니다.","정답. 계자에 직류 공급","속도는 거버너가 조절합니다."],"t":"여자기 = 계자 직류 공급"},"2023-4-기관3-13":{"w":"3상 유도전동기 속도 제어법은 주파수 변환, 극수 변환, 2차 저항 가감(권선형), 전압 제어 등입니다. 전류 변환법은 없습니다.","x":["정답(아닌 것). 전류 변환법","속도 제어법입니다.","속도 제어법입니다.","속도 제어법입니다."],"t":"속도 제어 = 주파수·극수·2차 저항"},"2023-4-기관3-14":{"w":"농형 유도전동기는 회전자가 도체 막대로 단락되어 있어 브러시가 필요 없습니다.","x":["직류기는 브러시가 있습니다.","직류기는 브러시가 있습니다.","정답. 농형 유도전동기","권선형은 슬립링·브러시가 있습니다."],"t":"농형 = 브러시 없음"},"2023-4-기관3-15":{"w":"선박의 동기발전기는 대부분 계자가 회전하는 회전계자형입니다. 슬립링은 2개(계자용 직류)이며 여자기가 있습니다.","x":["정답. 회전계자형","소형에만 씁니다.","슬립링은 2개입니다.","여자기가 있습니다."],"t":"동기발전기 = 회전계자형"},"2023-4-기관3-16":{"w":"아날로그 멀티테스터로는 직류·교류 전압, 직류 전류, 저항을 잴 수 있지만 주파수는 잴 수 없습니다.","x":["잴 수 있습니다.","잴 수 있습니다.","잴 수 있습니다.","정답(측정 불가). 주파수"],"t":"멀티테스터 = V·A·Ω"},"2023-4-기관3-17":{"w":"병렬 운전 중 두 발전기의 기전력 크기가 다르면 두 발전기 사이에 무효 순환전류가 흘러 권선이 과열됩니다.","x":["정답. 무효 순환전류","위상 차이 때의 현상입니다.","유효전력은 거버너가 정합니다.","위상과 관계없습니다."],"t":"전압 차 = 무효 순환전류"},"2023-4-기관3-18":{"w":"전기드릴의 접지선을 선체에 연결하면 누전 시 전류가 선체로 흘러 사람이 감전되지 않습니다.","x":["단락 방지가 아닙니다.","정답. 감전 예방","모터 보호가 아닙니다.","발전기 트립과 관계없습니다."],"t":"접지 = 감전 방지"},"2023-4-기관3-21":{"w":"적분회로에 구형파를 넣으면 출력은 일정하게 증가·감소를 반복하는 삼각파가 됩니다.","x":["사인파가 아닙니다.","구형파가 아닙니다.","정답. 삼각파","펄스파는 미분회로의 출력입니다."],"t":"적분 → 삼각파, 미분 → 펄스"},"2023-4-기관3-23":{"w":"일정한 기준전압을 얻는 데는 제너 다이오드를 씁니다.","x":["FET가 아닙니다.","UJT가 아닙니다.","정답. 제너 다이오드","해당하지 않습니다."],"t":"기준전압 = 제너"},"2023-4-기관3-24":{"w":"NPN 트랜지스터에서는 베이스 전류(IB)와 컬렉터 전류(IC)가 합쳐져 이미터(IE)로 흘러 나갑니다(IE = IB + IC).","x":["전류 방향이 틀립니다.","정답. IB + IC → IE","틀립니다.","틀립니다."],"t":"NPN = 전류가 이미터로 나감"},"2023-4-직무일반-4":{"w":"한국선급의 선급유지 검사는 정기, 중간, 연차, 입거, 보일러, 계속검사 등입니다. 임시항해검사는 선박안전법의 검사입니다.","x":["선급 검사입니다.","선급 검사입니다.","선급 검사입니다.","정답(아닌 것). 임시항해검사"],"t":"임시항해검사 = 선박안전법"},"2023-4-직무일반-6":{"w":"슬러지는 소각하거나, 육상으로 양륙하거나, 저장 후 수용시설로 보냅니다. 15[ppm] 기름여과장치로 처리하는 것은 빌지입니다.","x":["정답(옳지 않은 것). 여과장치는 빌지용입니다.","소각합니다.","양륙합니다.","저장 후 이송합니다."],"t":"슬러지 ≠ 여과장치"},"2023-4-직무일반-8":{"w":"소각 시 연소실 온도를 높이면 완전연소가 되어 유해 배기가스가 줄어듭니다.","x":["주목적이 아닙니다.","정답. 완전연소로 유해가스 감소","주목적이 아닙니다.","CO는 줄여야 합니다."],"t":"고온 소각 = 완전연소"},"2023-4-직무일반-11":{"w":"관절의 뼈가 제자리에서 빠져나온 상태를 탈구라 합니다.","x":["염좌는 인대가 늘어난 것입니다.","타박상은 부딪힌 상처입니다.","정답. 탈구","골절은 뼈가 부러진 것입니다."],"t":"탈구 = 관절이 빠짐"},"2023-4-직무일반-12":{"w":"2도 화상은 진피까지 손상되어 물집이 생기고 통증이 심합니다.","x":["1도는 붉어지기만 합니다.","정답. 2도 화상","3도는 피부 전층이 손상됩니다.","해당하지 않습니다."],"t":"2도 = 물집"},"2023-4-직무일반-13":{"w":"응급처치는 생명을 구하고, 악화를 막고, 고통을 줄이는 것이 목적입니다. 의약품으로 치료 기간을 줄이는 것은 치료의 목적입니다.","x":["목적입니다.","목적입니다.","목적입니다.","정답(아닌 것). 치료가 목적이 아닙니다."],"t":"응급처치 = 생명 구조·악화 방지"},"2023-4-직무일반-14":{"w":"침수 시에는 장소 확인, 방수 작업, 배수펌프 가동을 먼저 합니다. 모든 발전기를 멈추면 배수할 수 없습니다.","x":["배수합니다.","조사합니다.","방수합니다.","정답(옳지 않은 것). 발전기를 정지하면 안 됩니다."],"t":"침수 = 발전기 유지하며 배수"},"2023-4-직무일반-16":{"w":"디젤발전기의 경보·정지 조건은 과속도, 윤활유 압력 저하, 냉각수 온도 상승 등입니다. 소기 압력 저하는 발전기 정지 조건이 아닙니다.","x":["조건입니다.","조건입니다.","정답(아닌 것). 소기 압력 저하","조건입니다."],"t":"D/G 정지 = 과속·LO 압력↓·냉각수 온도↑"},"2023-4-직무일반-17":{"w":"화재 시에는 경보 발령, 전원 차단, 소화작업을 합니다. 소화기 약제 충전은 화재 후 정비 작업입니다.","x":["합니다.","합니다.","합니다.","정답(옳지 않은 것). 충전은 나중에 합니다."],"t":"화재 = 경보·차단·소화"},"2023-4-직무일반-20":{"w":"소화전에는 소화 호스, 노즐, 스패너(연결용)를 비치합니다. 안전등은 비치하지 않습니다.","x":["비치합니다.","비치합니다.","비치합니다.","정답(아닌 것). 안전등"],"t":"소화전 = 호스·노즐·스패너"},"2023-4-직무일반-22":{"w":"선박안전법상 검사는 건조·정기·중간(1종·2종)·임시·임시항해·국제협약검사 등입니다. 프로펠러축검사는 선급 검사 항목입니다.","x":["해당합니다.","해당합니다.","정답(아닌 것). 프로펠러축검사","해당합니다."],"t":"선박안전법 검사 = 정기·중간·임시·임시항해"},"2023-4-직무일반-23":{"w":"임시검사는 용도 변경, 길이 변경 등 개조, 무선설비 신설 때 받습니다. 검사증서 유효기간이 끝나면 정기검사를 받습니다.","x":["임시검사 대상입니다.","정답(아닌 것). 정기검사 대상입니다.","임시검사 대상입니다.","임시검사 대상입니다."],"t":"유효기간 만료 = 정기검사"},"2023-4-직무일반-25":{"w":"해양오염방지관리인은 선박의 오염방지설비 정비·점검, 방제 자재 관리, 기름·폐기물기록부 기록·보관 등을 합니다. 해양시설 오염물질기록부는 해양시설(육상)의 업무입니다.","x":["업무입니다.","정답(아닌 것). 해양시설 기록부","업무입니다.","업무입니다."],"t":"오염방지관리인 = 선박 기록부·설비"},"2023-4-영어-2":{"w":"수관(water tubes), 노(furnace), 연소실 청소는 보일러 정비입니다.","x":["정답. Boiler","소각기가 아닙니다.","냉각기가 아닙니다.","응축기가 아닙니다."],"t":"water tube·furnace = 보일러"},"2023-4-영어-3":{"w":"H.F.O. = Heavy Fuel Oil(중유)입니다.","x":["M.D.O. = 디젤유","정답. H.F.O.","L.O. = 윤활유","M.G.O. = 경유"],"t":"HFO = 중유"},"2023-4-영어-4":{"w":"\"모든 공기 ( )에 압축공기를 충전했다.\" vessels, tanks, reservoirs는 공기탱크지만 coolers(냉각기)는 알맞지 않습니다.","x":["공기 용기입니다.","정답(적합하지 않은 것). coolers","공기 탱크입니다.","공기 저장조입니다."],"t":"air reservoir = 공기탱크"},"2023-4-영어-5":{"w":"도착하다 = arrive at + 장소. \"Arrived at Busan.\"","x":["from은 출발지입니다.","to는 방향입니다.","정답. at","of가 아닙니다."],"t":"arrive at"},"2023-4-영어-6":{"w":"at once = 즉시 = instantly.","x":["때때로","자주","자주","정답. instantly"],"t":"at once = instantly"},"2023-4-영어-11":{"w":"Oil mist detector = 오일 미스트(유증기) 검출기입니다. 유량검출기가 아닙니다.","x":["맞습니다.","맞습니다.","정답(옳지 않은 것). 유증기 검출기입니다.","맞습니다."],"t":"oil mist = 유증기"},"2023-4-영어-12":{"w":"fire & boat drill = 소화훈련과 단정(구명정)훈련입니다.","x":["틀립니다.","틀립니다.","정답. 소화훈련과 단정훈련","틀립니다."],"t":"drill = 훈련"},"2023-4-영어-13":{"w":"응축기 덮개의 아연판(zinc plates)은 해수 부식을 막는 방식(anti-corrosion)용입니다.","x":["정답. anti-corrosion","노킹 방지가 아닙니다.","안정기가 아닙니다.","침식 방지가 아닙니다."],"t":"zinc = 부식 방지"},"2023-4-영어-15":{"w":"시간당 해리(nautical miles per hour)로 나타낸 속도는 knot(노트)입니다.","x":["배럴","와트","동력","정답. knot"],"t":"knot = 해리/시"},"2023-4-영어-16":{"w":"수선에서 용골 아래까지의 깊이는 Draft(흘수)입니다.","x":["캠버","정답. Draft = 흘수","Freeboard = 건현","Sheer = 현호"],"t":"draft 흘수, freeboard 건현"},"2023-4-영어-18":{"w":"용액의 염분을 재는 기구는 Salinometer(염분계)입니다.","x":["회전계","습도계","점도계","정답. Salinometer"],"t":"salinometer = 염분계"},"2023-4-영어-19":{"w":"기계의 속도를 일정하게 유지하는 장치는 Governor(조속기)입니다.","x":["정답. Governor","증발기","안정기","지시기"],"t":"governor = 조속기"},"2023-4-영어-20":{"w":"디젤기관의 연료 계통은 service tank(서비스 탱크, 청정된 연료)에서 연료를 끌어옵니다.","x":["드레인 탱크","정답. service tank","섬프 탱크(윤활유)","딥 탱크"],"t":"service tank = 사용 연료 탱크"},"2023-4-영어-22":{"w":"mechanical efficiency = 기계효율입니다.","x":["정답. 기계효율","추진효율","전달효율","지시열효율"],"t":"mechanical efficiency = BHP/IHP"},"2023-4-영어-23":{"w":"선박에서 기름과 오염물질을 분리하는 주 목적의 장치는 기름여과장치(oil filtering equipment)입니다.","x":["청정기는 연료·윤활유 정제용입니다.","소각기가 아닙니다.","빌지펌프가 아닙니다.","정답. oil filtering equipment"],"t":"해양 보호 = 기름여과장치"},"2023-4-영어-24":{"w":"흡·배기밸브가 닫힌 채 연소로 압력이 올라 피스톤을 밀어 내리는 것은 작동(폭발) 행정입니다.","x":["흡입행정이 아닙니다.","압축행정이 아닙니다.","정답. Working stroke","배기행정이 아닙니다."],"t":"연소 → 피스톤 하강 = 작동행정"},"2023-4-영어-25":{"w":"settling tank = 침전탱크(세틀링 탱크)입니다.","x":["중력탱크가 아닙니다.","정답. 침전탱크","저장탱크는 storage tank입니다.","틀립니다."],"t":"settling tank = 침전탱크"},"2024-1-기관1-1":{"w":"2행정 기관은 회전력 변화가 작고, 헤드 구조가 간단하며, 출력당 무게가 가볍습니다. 반면 소기 과정에서 연료·윤활유 소비율이 높은 것은 단점입니다.","x":["회전력 변화가 작은 것은 장점입니다.","헤드 구조가 간단한 것은 장점입니다.","정답(옳지 않은 것). 소비율이 높은 것은 단점입니다.","출력당 중량이 작은 것은 장점입니다."],"t":"2행정 단점 = 연료·윤활유 소비율↑, 열응력↑"},"2024-1-기관1-2":{"w":"디젤 연소는 착화지연 → 무제어(폭발) 연소 → 제어 연소 → 후연소 순서입니다. 제어 연소 기간에는 분사하는 대로 타면서 압력이 거의 일정하게 유지되므로 정압연소 기간입니다.","x":["착화지연은 연료가 아직 타지 않는 기간입니다.","무제어 연소는 급격히 압력이 오르는 정적연소에 가깝습니다.","정답. 제어 연소 = 정압연소","후연소는 분사가 끝난 뒤 남은 연료가 타는 기간입니다."],"t":"무제어 = 정적, 제어 = 정압"},"2024-1-기관1-3":{"w":"저온부식은 배기가스 속 황산화물이 노점 이하로 식은 곳에서 황산이 되어 생깁니다. 막으려면 배기가스 온도를 노점보다 높게 유지해야 합니다.","x":["저유황유 사용은 대책입니다.","정답(옳지 않은 것). 배기가스 온도는 노점보다 높게 유지합니다.","과잉공기를 줄이면 SO₃ 생성이 줄어듭니다.","연소 부하율을 낮추는 것도 대책입니다."],"t":"저온부식 방지 = 노점 이상 유지"},"2024-1-기관1-4":{"w":"배기밸브 고착은 스핀들과 가이드의 열전도 불량, 스핀들의 큰 열팽창, 간격이 너무 작을 때, 카본 퇴적 등으로 생깁니다. 밸브 박스를 충분히 냉각하는 것은 오히려 고착을 막습니다.","x":["열전도가 나쁘면 과열로 고착됩니다.","열팽창이 크면 틈이 없어져 고착됩니다.","정답(아닌 것). 냉각은 고착 방지 대책입니다.","간격이 작으면 고착됩니다."],"t":"밸브 고착 = 과열·틈새 부족·카본"},"2024-1-기관1-5":{"w":"피스톤핀은 트렁크형 기관에서 피스톤과 커넥팅로드를 연결하고 힘을 전달하며, 표면 경화강으로 만듭니다. 크로스헤드형 기관에는 피스톤핀이 없고 크로스헤드핀이 있습니다.","x":["트렁크형에서 피스톤과 커넥팅로드를 연결합니다.","힘을 전달합니다.","표면 경화강을 씁니다.","정답(옳지 않은 것). 크로스헤드형에는 피스톤핀이 없습니다."],"t":"피스톤핀 = 트렁크형 기관"},"2024-1-기관1-7":{"w":"6실린더 4행정 기관은 120°마다 착화합니다. 1번 착화 후 240°는 두 칸 뒤이므로 1 → 5 → 3, 즉 3번 실린더가 착화합니다.","x":["720° 후입니다.","정답. 두 칸 뒤 = 3번","다섯 칸 뒤입니다.","한 칸(120°) 뒤입니다."],"t":"착화 간격 × 칸 수로 계산"},"2024-1-기관1-8":{"w":"배압(배기 저항)이 높아지는 원인은 배기 계통의 카본 퇴적, 배기온도 상승(가스 팽창), 후연소 등입니다. 실린더 윤활 불량은 배압과 직접 관계가 없습니다.","x":["카본이 쌓이면 통로가 좁아집니다.","온도가 높으면 가스 부피가 커집니다.","후연소는 배기온도를 높입니다.","정답(옳지 않은 것). 실린더 윤활은 배압과 관계없습니다."],"t":"배압 상승 = 카본·고온 배기"},"2024-1-기관1-9":{"w":"냉각청수 계통에 염분이 급히 늘면 해수가 청수 쪽으로 들어온 것입니다. 해수로 청수를 식히는 청수 냉각기의 튜브가 새면 해수가 섞입니다.","x":["오손은 염분 원인이 아닙니다.","라이너 균열은 청수가 연소실로 새는 원인입니다.","정답. 청수 냉각기 튜브 누설","헤드 균열은 가스·청수 누설 원인입니다."],"t":"청수에 염분 = 냉각기 해수 누설"},"2024-1-기관1-10":{"w":"4행정 기관의 시스템유(크랭크실 윤활유)에는 냉각기 누설 수분, 카본, 금속 가루가 들어갈 수 있습니다. 연료유에 섞인 수분은 연소실에서 증발하므로 시스템유에 들어가지 않습니다.","x":["냉각기 누설로 물이 들어갈 수 있습니다.","블로바이로 카본이 들어갑니다.","정답(가능성 없는 것). 연료유 수분은 연소실에서 처리됩니다.","마모로 금속 가루가 들어갑니다."],"t":"시스템유 오염 = 물·카본·금속분"},"2024-1-기관1-12":{"w":"캐리오버는 발생 증기와 함께 보일러 물(물방울, 불순물)이 밖으로 딸려 나가는 현상입니다. 포밍, 프라이밍이 원인입니다.","x":["정상적인 증기 공급입니다.","정답. 보일러수가 증기와 함께 반출","응축 현상입니다.","수면계 착오입니다."],"t":"캐리오버 = 증기에 물이 섞여 나감"},"2024-1-기관1-13":{"w":"증기 분무식 버너는 증기로 기름을 잘게 부수어 무화가 좋아 고점도 중유에 적합하고, 낮은 유압·유온에서도 쓸 수 있으며, 분유량 조절 범위가 넓습니다. 다만 증기를 많이 씁니다.","x":["무화가 좋아 고점도유에 적합합니다.","유압·유온이 낮아도 됩니다.","정답(옳지 않은 것). 분유량 조절이 쉽고 범위가 넓습니다.","증기를 많이 씁니다."],"t":"증기 분무식 = 조절 범위 넓음, 증기 소비 큼"},"2024-1-기관1-14":{"w":"래버린스 패킹은 여러 개의 좁은 틈과 방을 거치며 증기가 교축·팽창을 반복해 압력이 떨어지게 하여 누설을 막습니다.","x":["탄소패킹은 탄소 링의 접촉으로 막습니다.","수봉패킹은 물로 막습니다.","정답. 교축 작용 = 래버린스","글랜드패킹은 패킹 재료로 누릅니다."],"t":"래버린스 = 교축 작용"},"2024-1-기관1-16":{"w":"추진기축을 선내로 빼내려면 중간축을 먼저 분리하고, 선미관 패킹을 빼고, 추진기를 분해한 뒤 축을 선내로 발출합니다.","x":["중간축 분리가 먼저입니다.","정답. ② → ① → ③ → ④","발출은 마지막입니다.","추진기 분해 전에 발출할 수 없습니다."],"t":"중간축 분리 → 패킹 → 추진기 → 축 발출"},"2024-1-기관1-17":{"w":"추진기축(프로펠러축)은 프로펠러가 달리는 축으로, 비틀림과 프로펠러 무게에 의한 굽힘을 함께 받고 해수 부식 여유도 필요하므로 중간축보다 지름이 큽니다.","x":["추진기가 설치되는 축입니다.","비틀림·굽힘을 받습니다.","정답(옳지 않은 것). 중간축보다 지름이 큽니다.","1종축(슬리브 있음)·2종축이 있습니다."],"t":"프로펠러축 > 중간축 (지름)"},"2024-1-기관1-18":{"w":"기름 윤활식 선미관의 선미측 실은 해수 유입과 윤활유 유출을 막고, 선수측(기관실 쪽) 실은 윤활유가 기관실로 새지 않게 막습니다.","x":["해수 유입 방지는 선미측 실의 역할입니다.","공기 누출과 관계없습니다.","정답. 윤활유 누출 방지","오수 유입과 관계없습니다."],"t":"선수측 실 = 윤활유 누출 방지"},"2024-1-기관1-19":{"w":"원호형 날개 단면의 프로펠러는 날개 앞면(배 쪽을 향한 흡입면)의 압력이 낮아져 그곳에서 공동현상이 주로 생깁니다.","x":["앞날(리딩 엣지)이 아닙니다.","뒷날이 아닙니다.","정답. 앞면","뒷면(압력면)이 아닙니다."],"t":"원호형 날개 = 앞면 공동현상"},"2024-1-기관1-23":{"w":"불꽃 없이 온도를 높여 저절로 불이 붙기 시작하는 최저 온도는 발화점(착화점)입니다.","x":["유동점은 흐를 수 있는 최저 온도입니다.","정답. 발화점","인화점은 불꽃을 대면 불이 붙는 온도입니다.","응고점은 굳는 온도입니다."],"t":"발화점 = 스스로, 인화점 = 불꽃 대면"},"2024-1-기관1-24":{"w":"윤활유는 고온, 카본 혼입, 물·금속 가루 혼입, 산화 등으로 열화됩니다. 펌프 송출압력이 높은 것은 열화 원인이 아닙니다.","x":["고온은 열화 원인입니다.","카본 혼입은 열화 원인입니다.","정답(아닌 것). 송출압력은 열화 원인이 아닙니다.","물·금속 가루는 열화 원인입니다."],"t":"윤활유 열화 = 열·오염·산화"},"2024-1-기관1-25":{"w":"유압 작동유는 유동점이 낮고, 점도지수가 크며, 중성이고, 인화점이 높아야 화재 위험이 적습니다.","x":["유동점이 낮아야 합니다.","점도지수가 커야 합니다.","중성이어야 합니다.","정답(옳지 않은 것). 인화점은 높아야 합니다."],"t":"작동유 = 인화점 높게"},"2024-1-기관2-1":{"w":"랜턴링은 글랜드패킹 가운데에 끼우는 링으로, 송출측 압력수를 받아 패킹부를 밀봉·냉각·윤활합니다. 추력을 상쇄하는 역할은 없습니다(추력 상쇄는 밸런스 디스크).","x":["정답(옳지 않은 것). 추력 상쇄는 랜턴링의 역할이 아닙니다.","패킹 가운데에 있습니다.","냉각과 윤활을 돕습니다.","송출측과 연결되어 압력수를 받습니다."],"t":"랜턴링 = 봉수 공급"},"2024-1-기관2-2":{"w":"회전속도를 바꿔 유량을 조절하면 밸브로 조이는 것처럼 저항 손실이 없어 효율이 가장 좋고 동력도 절약됩니다(인버터 제어).","x":["밸브 조임은 손실이 생깁니다.","흡입밸브를 조이면 캐비테이션이 생깁니다.","손실이 큽니다.","정답. 회전속도 조절"],"t":"가장 효율적 = 회전수 제어"},"2024-1-기관2-4":{"w":"왕복펌프는 피스톤·플런저·버킷이 왕복하며 액체를 보내는 펌프입니다. 트로코이드 펌프는 내접 기어 형태의 회전펌프입니다.","x":["피스톤 펌프는 왕복펌프입니다.","정답(아닌 것). 트로코이드 펌프는 회전펌프입니다.","플런저 펌프는 왕복펌프입니다.","버킷 펌프는 왕복펌프입니다."],"t":"트로코이드 = 회전펌프"},"2024-1-기관2-5":{"w":"콜레서 분리법은 콜레서 필터로 작은 기름방울을 서로 응집시켜 큰 방울로 만들어 분리합니다.","x":["평행판 분리법은 판 사이 흐름으로 분리합니다.","중력 분리법은 비중 차로 분리합니다.","원심 분리법은 원심력으로 분리합니다.","정답. 응집 = 콜레서"],"t":"응집(합체) = 콜레서"},"2024-1-기관2-6":{"w":"추종장치는 타가 명령한 각도까지 움직이면 원동기 송출을 멈춰 그 위치에 타를 고정시킵니다.","x":["타장치는 타와 타두재입니다.","조종장치는 조타륜 등 명령 장치입니다.","정답. 추종장치","고정장치는 4대 요소가 아닙니다."],"t":"추종장치 = 명령 각도에서 정지"},"2024-1-기관2-7":{"w":"계류(계선) 설비에는 비트, 볼라드(계선주), 페어리드(줄 안내), 계선 윈치 등이 있습니다. 태클은 도르래와 줄로 짐을 들어 올리는 도구입니다.","x":["비트는 계선 설비입니다.","정답(아닌 것). 태클은 하역 도구입니다.","볼라드는 계선 설비입니다.","페어리드는 계선 설비입니다."],"t":"계선 = 비트·볼라드·페어리드"},"2024-1-기관2-8":{"w":"유압 양묘장치는 유압펌프에서 보낸 기름으로 유압모터를 돌려 체인 드럼축을 직접 구동합니다.","x":["웜기어는 전동식에 씁니다.","클러치는 동력을 연결·차단합니다.","정답. 유압모터","스퍼기어는 감속용입니다."],"t":"유압 양묘기 = 유압모터 구동"},"2024-1-기관2-9":{"w":"폐유소각장치에서 보조 연료 없이 스스로 연소할 수 있는 폐유의 수분 함량은 약 40~50[%]까지입니다. 그 이상이면 보조 버너가 필요합니다.","x":["이보다 많아도 연소 가능합니다.","정답. 약 40∼50[%]","너무 많습니다.","너무 많습니다."],"t":"폐유 자체 연소 = 수분 약 50% 이하"},"2024-1-기관2-11":{"w":"냉동능력이 떨어지는 원인은 응축기 냉각수 부족, 냉매 부족, 압축기 마멸 등입니다. 언로더는 부하에 맞춰 용량을 줄이는 정상 작동이므로 고장 원인이 아닙니다.","x":["정답(아닌 것). 언로더 작동은 정상 용량 제어입니다.","냉각수 부족은 원인입니다.","냉매 부족은 원인입니다.","압축기 마멸은 원인입니다."],"t":"언로더 = 정상 용량 조절"},"2024-1-기관2-12":{"w":"응축기 냉각수의 출구와 입구 온도 차이는 약 5[℃] 이내가 이상적입니다. 너무 크면 냉각수량 부족, 너무 작으면 과다를 뜻합니다.","x":["너무 작습니다.","작습니다.","정답. 약 5[℃] 이내","너무 큽니다."],"t":"냉각수 온도차 약 5℃"},"2024-1-기관2-13":{"w":"프레온 누설은 비눗물, 핼라이드 토치(불꽃 색 변화), 할로겐 누설검지기로 찾습니다. 유황을 태워 흰 연기로 찾는 방법은 암모니아 누설 검지법입니다.","x":["정답(옳지 않은 것). 유황 초는 암모니아용입니다.","핼라이드 토치는 프레온용입니다.","비눗물은 공통으로 씁니다.","할로겐 검지기는 프레온용입니다."],"t":"프레온 = 핼라이드 토치, 암모니아 = 유황"},"2024-1-기관2-14":{"w":"공기조화 방식에는 유인 유닛 방식, 팬코일 유닛 방식, 단일·2중 덕트 방식 등이 있습니다. 랩슨 슬라이드는 조타장치의 형식입니다.","x":["유인 유닛은 공조 방식입니다.","팬코일 유닛은 공조 방식입니다.","2중 덕트는 공조 방식입니다.","정답(아닌 것). 랩슨 슬라이드는 조타장치입니다."],"t":"랩슨 슬라이드 = 조타장치"},"2024-1-기관2-16":{"w":"베어링 간극처럼 좁은 틈새는 필러 게이지(틈새게이지)로 잽니다.","x":["정답. 필러 게이지","센터 게이지는 나사 바이트 각도를 봅니다.","피치 게이지는 나사 피치를 잽니다.","곡률 게이지는 반지름을 잽니다."],"t":"틈새 = 필러 게이지"},"2024-1-기관2-17":{"w":"선박에서 나사는 주로 선반으로 깎아 만듭니다(나사 절삭). 손으로는 탭·다이스를 씁니다.","x":["정답. 선반 가공","밀링은 주로 평면·홈 가공입니다.","드릴링은 구멍 가공입니다.","호닝은 구멍 내면 다듬질입니다."],"t":"나사 가공 = 선반(탭·다이스)"},"2024-1-기관2-20":{"w":"용접부 잔류응력은 풀림(어닐링) 열처리로 제거합니다.","x":["담금질은 경화 처리입니다.","뜨임은 담금질 후 인성을 주는 처리입니다.","불림은 조직을 균일하게 하는 처리입니다.","정답. 풀림 = 잔류응력 제거"],"t":"풀림 = 응력 제거·연화"},"2024-1-기관2-22":{"w":"기속거리(프로펠러 거리)는 피치 × 회전수로 계산하므로 피치를 알아야 합니다.","x":["항주거리는 실제 측정 거리입니다.","연료소비율과 관계없습니다.","축마력과 관계없습니다.","정답. 기속거리 = 피치 × 회전수"],"t":"기속거리 = P × N"},"2024-1-기관2-24":{"w":"도면의 오른쪽 아래에는 도면 번호·명칭·척도·작성자 등을 적는 표제란을 반드시 둡니다.","x":["중심선은 위치가 정해져 있지 않습니다.","중심 마크는 도면 가장자리 중앙에 둡니다.","정답. 표제란","구역 기호는 테두리에 둡니다."],"t":"오른쪽 아래 = 표제란"},"2024-1-기관2-23":{"w":"선속과 필요한 동력은 3제곱 비례 관계이므로, 일정한 시간 동안 항해할 때의 연료 소비량은 선속의 3제곱에 비례합니다. (같은 거리를 갈 때는 제곱에 비례)","x":["반비례하지 않습니다.","같은 거리를 갈 때의 관계입니다.","정답. 시간당 연료 ∝ 선속³","4제곱이 아닙니다."],"t":"시간당 연료 ∝ 속력³, 거리당 연료 ∝ 속력²"},"2024-1-기관3-1":{"w":"10[Ω] 두 개가 병렬이므로 5[Ω]입니다. 여기에 4[Ω], 3[Ω]이 직렬로 붙어 4 + 3 + 5 = 12[Ω]입니다.","x":["직렬 부분만 더한 값입니다.","정답. 4 + 3 + (10∥10 = 5) = 12[Ω]","병렬 부분을 10으로 계산한 값입니다.","모두 더한 값입니다."],"t":"같은 저항 2개 병렬 = 절반"},"2024-1-기관3-2":{"w":"키르히호프의 제1법칙(전류 법칙)은 한 점으로 들어오고 나가는 전류의 대수합이 0이라는 법칙입니다.","x":["앙페르의 법칙은 전류와 자기장의 방향입니다.","정답. 키르히호프의 법칙","쿨롱의 법칙은 전하 사이의 힘입니다.","패러데이의 법칙은 전자유도입니다."],"t":"키르히호프 1법칙 = 전류, 2법칙 = 전압"},"2024-1-기관3-3":{"w":"I = V ÷ R = 440 ÷ 125 = 3.52[A]입니다.","x":["틀린 값입니다.","정답. 440 ÷ 125 = 3.52[A]","틀린 값입니다.","틀린 값입니다."],"t":"I = V / R"},"2024-1-기관3-4":{"w":"정격전압 100[V]는 실효값이므로 최대값 = 100 × √2 ≒ 141[V]입니다.","x":["평균값에 해당하는 값입니다.","실효값입니다.","정답. 100 × 1.414 ≒ 141[V]","틀린 값입니다."],"t":"최대값 = 실효값 × √2"},"2024-1-기관3-5":{"w":"e = Em sinωt 에서 e는 순시값, Em은 최대값, ω는 각속도(2πf), t는 시간[초]입니다.","x":["e는 순시값입니다.","t의 단위는 [초]입니다.","Em은 최대값입니다.","정답. ω = 각속도"],"t":"e 순시값, Em 최대값, ω = 2πf"},"2024-1-기관3-6":{"w":"콘덴서는 병렬로 연결하면 용량이 더해지므로 연결할수록 전체 용량이 커집니다. 직렬로 연결하면 C1C2/(C1 + C2)로 작아집니다.","x":["직렬 합성용량은 C1C2/(C1+C2)입니다.","병렬에서는 작은 용량을 무시할 수 있습니다.","병렬 합성용량은 C1 + C2입니다.","정답. 병렬로 연결할수록 용량 증가"],"t":"콘덴서 병렬 = 합, 직렬 = 곱/합"},"2024-1-기관3-7":{"w":"전위차 V = 일 W ÷ 전하량 Q 입니다. 1[C]의 전하가 1[J]의 일을 하면 1[V]입니다.","x":["정답. V = W / Q","틀린 식입니다.","틀린 식입니다.","틀린 식입니다."],"t":"V = W / Q (W = QV)"},"2024-1-기관3-8":{"w":"단선(한 가닥 전선)의 크기는 지름[mm]으로 나타냅니다. 여러 가닥을 꼰 연선은 단면적[mm²]으로 나타냅니다.","x":["단면적은 연선의 표시입니다.","반지름으로 표시하지 않습니다.","정답. 단선 = 지름[mm]","허용전류는 크기 표시가 아닙니다."],"t":"단선 = 지름, 연선 = 단면적"},"2024-1-기관3-9":{"w":"전기저항은 길이에 비례하고 단면적에 반비례합니다. 가는 선은 단면적이 작아 굵은 선보다 저항이 큽니다.","x":["도체는 저항이 작습니다.","길수록 저항이 커집니다.","구리·알루미늄은 저항이 작습니다.","정답(옳지 않은 것). 가는 선이 저항이 더 큽니다."],"t":"R ∝ 길이 / 단면적"},"2024-1-기관3-11":{"w":"UPS는 ①정류기로 교류를 직류로 바꿔 ③축전지를 충전하고, ②인버터로 다시 교류를 만들어 부하에 공급합니다. 정전되면 축전지가 인버터에 전력을 공급합니다. 따라서 ③은 축전지입니다.","x":["정류기는 ①입니다.","정답. ③ = 축전지","인버터는 ②입니다.","다이오드는 해당하지 않습니다."],"t":"UPS = 정류기 → 축전지 → 인버터"},"2024-1-기관3-12":{"w":"THR(Thermal Relay)은 열동 계전기입니다. 전동기에 과전류가 흐르면 바이메탈이 휘어 접점을 열어 전동기를 보호합니다.","x":["타임 릴레이는 TR 또는 T입니다.","정답. THR = 열동 계전기","차단기는 MCCB 등입니다.","역전력 계전기는 RPR입니다."],"t":"THR = 열동 계전기(과부하 보호)"},"2024-1-기관3-14":{"w":"일반 교류 전압계·전류계는 실효값을 나타냅니다.","x":["평균값이 아닙니다.","최대값이 아닙니다.","순시값이 아닙니다.","정답. 실효값"],"t":"교류 계기 = 실효값"},"2024-1-기관3-15":{"w":"소용량 농형 유도전동기는 기동 전류가 크지 않으므로 전전압을 바로 거는 직입 기동법이 가장 적합합니다.","x":["2차 저항 가감은 권선형 전동기의 방법입니다.","정답. 소용량 = 직입 기동","중용량에 쓰는 방법입니다.","대용량에 쓰는 방법입니다."],"t":"소용량 직입, 중용량 Y-△, 대용량 기동보상기"},"2024-1-기관3-17":{"w":"Ns = 120f ÷ P = 120 × 60 ÷ 6 = 1,200[rpm]이며, 이를 동기속도라 합니다.","x":["정답. 1,200[rpm], 동기속도","등가속도가 아닙니다.","1,800[rpm]은 4극일 때입니다.","틀립니다."],"t":"Ns = 120f / P"},"2024-1-기관3-18":{"w":"병렬운전 시 위상 일치는 동기검정기(싱크로스코프)와 동기검정등으로 확인합니다.","x":["주파수계·전압계는 위상을 보지 못합니다.","전력계는 위상을 보지 못합니다.","역전력 계전기는 보호장치입니다.","정답. 동기검정기, 동기검정등"],"t":"위상 확인 = 싱크로스코프·동기검정등"},"2024-1-기관3-19":{"w":"중간 탭 변압기와 다이오드 D1, D2를 쓴 단상 전파 정류 회로입니다. 반주기마다 다이오드가 번갈아 도통합니다.","x":["반파 정류는 다이오드 1개입니다.","정답. 단상 전파 정류","3상이 아닙니다.","3상이 아닙니다."],"t":"중간탭 + 다이오드 2개 = 단상 전파"},"2024-1-기관3-21":{"w":"A, B가 모두 1일 때만 X가 0이므로 NAND 게이트(㉯)입니다.","x":["AND 게이트입니다.","정답. NAND","OR 게이트입니다.","NOR 게이트입니다."],"t":"둘 다 1일 때만 0 = NAND"},"2024-1-기관3-22":{"w":"불 대수에서 1 · A = A 입니다. 1 · A = 1은 틀립니다.","x":["A + A = A 는 맞습니다.","1 + A = 1 은 맞습니다.","A · A = A 는 맞습니다.","정답(옳지 않은 것). 1 · A = A 입니다."],"t":"1 + A = 1, 1 · A = A, 0 · A = 0"},"2024-1-기관3-23":{"w":"순방향 바이어스는 P형에 (+), N형에 (−)를 연결해 전류가 잘 흐르게 하는 연결입니다.","x":["정답. P에 (+), N에 (−)","역방향 바이어스입니다.","틀립니다.","틀립니다."],"t":"순방향 = P(+), N(−)"},"2024-1-기관3-24":{"w":"제너 다이오드 기호는 다이오드 막대(캐소드) 끝이 꺾인 모양입니다.","x":["다른 소자의 기호입니다.","다른 소자의 기호입니다.","정답. 꺾인 막대 = 제너","일반 다이오드 등입니다."],"t":"제너 = 꺾인 막대"},"2024-1-기관3-25":{"w":"다이오드 기호에 게이트 단자가 붙은 것은 SCR(실리콘 제어 정류기)입니다.","x":["정답. SCR","UJT는 이미터 화살표가 있는 기호입니다.","TR은 베이스·컬렉터·이미터 기호입니다.","다이오드에는 게이트가 없습니다."],"t":"SCR = 다이오드 + 게이트"},"2024-1-직무일반-1":{"w":"Abstract log(적요일지)는 한 항차가 끝난 뒤 그 항차의 주요 내용(항해시간, 연료 소비 등)을 요약한 기록입니다.","x":["Bell book은 기관 명령 기록부입니다.","정답. Abstract log = 항차 요약","Condition report는 상태 보고서입니다.","Engine room log book은 매일 쓰는 기관일지입니다."],"t":"Abstract log = 항차 요약"},"2024-1-직무일반-2":{"w":"출거 전에는 물에 잠기는 곳(시체스트·선저밸브, 프로펠러·선미관, 선외밸브)의 조립 상태를 반드시 확인해야 합니다. 청정기 조립 상태는 출거 후에도 확인할 수 있습니다.","x":["정답(아닌 것). 청정기는 출거 전 필수 확인 사항이 아닙니다.","선저밸브는 반드시 확인합니다.","프로펠러·선미관은 반드시 확인합니다.","선외밸브는 반드시 확인합니다."],"t":"출거 전 = 수선 아래 장치 확인"},"2024-1-직무일반-3":{"w":"운전 회전수가 크게 변하는 원인은 프로펠러 심도 변화(황천 레이싱), 조속기 고장, 연료펌프 래크 연결부 고장 등입니다. 윤활유 압력 상승은 회전수 변동과 관계없습니다.","x":["프로펠러가 물 위로 나오면 회전수가 급변합니다.","조속기 고장은 원인입니다.","정답(아닌 것). 윤활유 압력은 관계없습니다.","래크 고장은 연료량을 불안정하게 합니다."],"t":"회전수 변동 = 조속기·래크·프로펠러 레이싱"},"2024-1-직무일반-4":{"w":"납축전지는 충전 중 물이 전기분해되어 수소가스가 발생합니다. 폭발 위험이 있어 통풍하고 화기를 금지합니다.","x":["탄산가스가 아닙니다.","불소가스가 아닙니다.","정답. 수소가스","질소가스가 아닙니다."],"t":"축전지실 = 수소"},"2024-1-직무일반-5":{"w":"선급 검사는 정기검사 5년, 연차검사 매년(기준일 전후 3개월), 보일러검사 2.5년 등입니다. 입거검사는 정기검사 기간(5년) 동안 2번 받습니다.","x":["정기검사는 5년입니다.","보일러검사는 2.5년입니다.","연차검사는 전후 3개월 이내입니다.","정답(옳지 않은 것). 입거검사는 5년에 2번입니다."],"t":"입거검사 = 5년에 2회"},"2024-1-직무일반-6":{"w":"선박에서 나오는 대기오염물질은 황산화물, 질소산화물, 오존층 파괴물질, 휘발성 유기화합물 등입니다. 유기주석 화합물은 선체 도료(방오도료)의 유해물질로 해양오염물질입니다.","x":["황산화물은 대기오염물질입니다.","오존층 파괴물질은 대기오염물질입니다.","질소산화물은 대기오염물질입니다.","정답(아닌 것). 유기주석은 방오도료 물질입니다."],"t":"유기주석(TBT) = 방오도료"},"2024-1-직무일반-7":{"w":"황산화물(SOx)은 대기 중 수분과 만나 황산이 되어 산성비를 만듭니다.","x":["정답. 황산화물","이산화탄소는 온실가스입니다.","일산화탄소는 독성 가스입니다.","탄화수소는 스모그 원인입니다."],"t":"산성비 = SOx(NOx도 기여)"},"2024-1-직무일반-8":{"w":"해양오염비상계획서는 총톤수 150톤 이상 유조선, 총톤수 400톤 이상 선박(군함·경찰용 선박 제외)이 갖추어야 합니다. 총톤수 600톤 어선이 대상입니다.","x":["군함은 제외됩니다.","정답. 400톤 이상인 600톤 어선","유조선은 150톤 이상부터입니다.","경찰용 선박은 제외됩니다."],"t":"비상계획서 = 유조선 150톤↑, 그 외 400톤↑"},"2024-1-직무일반-9":{"w":"오존층파괴물질기록부에는 해당 설비의 충전, 수리·정비, 대기 배출, 육상 처리 등을 기록합니다. 생산 업체의 생산량은 기재 사항이 아닙니다.","x":["대기 배출을 기록합니다.","충전을 기록합니다.","정답(아닌 것). 생산량은 기재하지 않습니다.","수리·정비를 기록합니다."],"t":"오존층파괴물질 기록 = 충전·수리·배출"},"2024-1-직무일반-11":{"w":"들것은 보통 환자의 발 쪽이 앞으로 가게 운반합니다(계단 오를 때는 머리 먼저). 뒤쪽 운반자가 환자 얼굴을 보며 상태를 살필 수 있습니다.","x":["4인 운반이 안전합니다.","부상에 맞는 체위로 운반합니다.","흔들리지 않게 합니다.","정답(옳지 않은 것). 보통 발 쪽이 앞입니다."],"t":"들것 = 발 먼저"},"2024-1-직무일반-12":{"w":"두드러기는 주로 음식(생선·조개 등)이나 약물에 대한 알레르기 반응으로 생깁니다.","x":["정답. 음식·약물 부작용(알레르기)","비타민 결핍은 주된 원인이 아닙니다.","바이러스는 주된 원인이 아닙니다.","신경 긴장은 주된 원인이 아닙니다."],"t":"두드러기 = 알레르기"},"2024-1-직무일반-13":{"w":"의식이 없는 사람에게 음료를 주면 기도로 넘어가 질식할 수 있으므로 절대 주면 안 됩니다.","x":["열사병 환자는 의식이 있으면 수분을 줍니다.","일사병 환자는 수분을 줍니다.","정답. 의식불명자","중독자는 상황에 따라 다릅니다."],"t":"의식 없으면 음료 금지"},"2024-1-직무일반-14":{"w":"정전 직후 기관실 비상전등은 축전지(비상배터리)에서 즉시 전원을 받아 켜집니다.","x":["주발전기는 정전된 상태입니다.","정답. 축전지","예비발전기는 기동에 시간이 걸립니다.","인버터는 변환 장치입니다."],"t":"정전 직후 = 축전지"},"2024-1-직무일반-15":{"w":"침몰 우려가 있으면 가장 먼저 선내 침수 상황을 전 승무원에게 알려 모두 대비하게 해야 합니다.","x":["귀중품 정리는 우선 조치가 아닙니다.","조난통신은 선교(선장)가 합니다.","정답. 전 승무원에게 알린다","그다음 조치입니다."],"t":"비상 시 1순위 = 전원에게 알림"},"2024-1-직무일반-16":{"w":"항해 중 급정지 명령은 충돌 등 긴급 상황이므로 당직기관사는 즉시 주기관을 조작하고 나중에 기관일지에 기록합니다.","x":["기다리면 늦습니다.","확인하면 늦습니다.","정답. 즉시 조작 후 기록","먼저 조작해야 합니다."],"t":"선교 명령 = 즉시 이행"},"2024-1-직무일반-17":{"w":"선택(우선) 차단은 발전기 과부하 시 덜 중요한 부하부터 차단하는 기능입니다. 발전기가 전동기처럼 도는 것을 막는 것은 역전력 계전기의 기능입니다.","x":["트립 코일이 있습니다.","덜 중요한 기기부터 차단합니다.","과부하 시 선택 부하를 차단합니다.","정답(옳지 않은 것). 역전력 보호에 대한 설명입니다."],"t":"선택 차단 = 과부하 시 비중요 부하 차단"},"2024-1-직무일반-19":{"w":"선내 화재 원인은 누전, 연료유 누유, 자연 발화 등입니다. 보일러 연소실 안의 연소온도는 정상적인 연소이므로 화재 원인이 아닙니다.","x":["누전은 화재 원인입니다.","누유는 화재 원인입니다.","자연 발화는 화재 원인입니다.","정답(아닌 것). 연소실 내부 연소는 정상입니다."],"t":"화재 원인 = 누전·누유·자연발화"},"2024-1-직무일반-20":{"w":"인화점이 낮을수록 불이 붙기 쉬우므로 인화점이 연료유 화재 위험성의 지표가 됩니다.","x":["정답. 인화점","연소점은 지표로 잘 쓰지 않습니다.","비등점은 끓는 온도입니다.","폭발범위는 가스의 지표입니다."],"t":"화재 위험 지표 = 인화점"},"2024-1-직무일반-21":{"w":"모든 선박은 다른 소화장치와 관계없이 소화펌프·소화전·호스로 된 수(물) 소화장치를 기본으로 갖춰야 합니다.","x":["정답. 수 소화장치","선택 설비입니다.","선택 설비입니다.","선택 설비입니다."],"t":"기본 소화장치 = 물(소화전)"},"2024-1-직무일반-22":{"w":"검사기준일은 선박검사증서 유효기간 시작일부터 해마다 1년이 되는 날입니다. 연차검사는 이 날 전후 3개월 이내에 받습니다.","x":["정답. 검사증서 유효기간 시작일부터 매년","종료일 기준이 아닙니다.","국적증서가 아닙니다.","국적증서가 아닙니다."],"t":"검사기준일 = 검사증서 시작일 기준"},"2024-1-직무일반-23":{"w":"선박법상 기관과 돛을 함께 쓰면서 주로 기관으로 추진하는 선박은 기선입니다. 주로 돛을 쓰면 범선입니다.","x":["정답. 주로 기관 = 기선","주로 돛 = 범선","부선은 추진장치가 없는 배입니다.","기범선은 선박법상 분류가 아닙니다."],"t":"주로 기관 = 기선"},"2024-1-직무일반-24":{"w":"4급 기관사는 연근해·평수구역에서 일정 추진력 이하 선박의 기관장이 될 수 있습니다. 무제한수역을 항행하는 추진력 1,500[kW] 이상, 총톤수 500톤 이상 어선의 기관장은 상위 면허가 필요합니다.","x":["승선 가능합니다.","승선 가능합니다.","승선 가능합니다.","정답(승선 불가). 무제한수역 대형 어선"],"t":"4급 기관장 = 제한된 수역·추진력"},"2024-1-직무일반-25":{"w":"선박에너지효율관리계획서에는 계획 수립, 시행, 시행 결과의 평가·개선에 관한 사항을 기재합니다. 기기 정비에 관한 사항은 기재 사항이 아닙니다.","x":["수립 사항은 기재합니다.","시행 사항은 기재합니다.","정답(아닌 것). 기기 정비는 기재하지 않습니다.","평가·개선 사항은 기재합니다."],"t":"SEEMP = 수립·시행·평가·개선"},"2024-1-영어-1":{"w":"Scavenging port(소기공)는 2행정 기관(2 stroke engine)의 실린더 아래쪽에 있는 공기 흡입구입니다.","x":["정답. 2 stroke engine","4행정 기관은 흡기밸브를 씁니다.","가스터빈에는 없습니다.","증기터빈에는 없습니다."],"t":"scavenging port = 2행정"},"2024-1-영어-3":{"w":"\"~할까요?\" = Shall we ~?, 시작하다 = start. \"Shall we start with the H.F.O.?\"","x":["명령문입니다.","stop은 멈추다입니다.","정답. Shall we start with the H.F.O.?","check는 확인하다입니다."],"t":"Shall we ~? = ~할까요?"},"2024-1-영어-4":{"w":"cracked parts = 균열된 부분. \"실린더 라이너의 균열 부분을 수리할 것.\"","x":["정답. 균열된 부분","틀립니다.","부식은 corroded입니다.","오염은 contaminated입니다."],"t":"crack = 균열"},"2024-1-영어-5":{"w":"유청정기 = Oil purifier 입니다.","x":["Oil agitator = 기름 교반기","Oily water separator = 기름여과장치(유수분리기)","정답. Oil purifier = 유청정기","Waste oil incinerator = 폐유소각기"],"t":"purifier = 청정기"},"2024-1-영어-6":{"w":"음식을 차갑게 하는 장치는 Refrigerator(냉장고·냉동기)입니다.","x":["Compressor = 압축기","Heater = 가열기","Air conditioner = 공기조화기","정답. Refrigerator"],"t":"refrigerator = 냉장고"},"2024-1-영어-7":{"w":"Frequency(주파수)의 단위는 [Hz]입니다.","x":["피상전력 단위입니다.","정답. [Hz]","유효전력 단위입니다.","축전지 용량 단위입니다."],"t":"frequency = Hz"},"2024-1-영어-8":{"w":"출항 직후에는 R/UP ENG(항해 속력 전환), 연료 전환(A → C 중유), 오수처리장치 가동 등을 기록합니다. 터닝기어 연결은 입항 후(F.W.E. 이후) 작업입니다.","x":["Rung up eng.은 출항 후 기록합니다.","정답(아닌 것). 터닝기어 연결은 입항 후 작업입니다.","연료 전환은 출항 후 기록합니다.","오수처리장치 가동은 출항 후 기록합니다."],"t":"engage turning gear = 정박 후"},"2024-1-영어-9":{"w":"insulation resistance = 절연저항 입니다.","x":["접촉저항은 contact resistance입니다.","고유저항은 resistivity입니다.","접지저항은 earth resistance입니다.","정답. 절연저항"],"t":"insulation = 절연"},"2024-1-영어-10":{"w":"증기를 만드는 큰 강철 용기는 boiler입니다.","x":["steam turbine = 증기터빈","air vessel = 공기탱크","정답. boiler = 보일러","calorifier = 온수기"],"t":"boiler = 증기 발생"},"2024-1-영어-11":{"w":"liquid refrigerant = 액체 냉매. \"이 제어밸브(팽창밸브)는 낮은 압력의 증발기로 들어가는 액 냉매의 양을 조절한다.\"","x":["정답. refrigerant = 냉매","증기는 vapor입니다.","냉각수는 cooling water입니다.","냉동기는 refrigerator입니다."],"t":"refrigerant = 냉매"},"2024-1-영어-14":{"w":"원심분리기로 두 액체(기름과 물)를 분리하는 것을 purifier(청정기)라 합니다. (고체만 분리하면 clarifier)","x":["cooler = 냉각기","정답. purifier = 청정기","condenser = 응축기","de-aerator = 탈기기"],"t":"두 액체 분리 = purifier, 고형물 분리 = clarifier"},"2024-1-영어-15":{"w":"수트 블로잉은 증기 압력 확인(③) → 수트 블로어 주증기밸브 열기(②) → 수트 블로잉 실시(④) → 주증기밸브 닫기(①) 순서입니다.","x":["순서가 틀렸습니다.","압력 확인이 먼저입니다.","정답. ③ → ② → ④ → ①","밸브를 열기 전에 실시할 수 없습니다."],"t":"확인 → 열기 → 실시 → 닫기"},"2024-1-영어-16":{"w":"\"기관의 마찰과 마모를 줄이기 위해\" 쓰는 것은 윤활유(Lubricating oil)입니다.","x":["해수는 냉각용입니다.","시동공기는 시동용입니다.","청수는 냉각용입니다.","정답. Lubricating oil"],"t":"reduce friction = lubricating oil"},"2024-1-영어-18":{"w":"청정기 그림에서 E는 전동기와 수평축 사이에서 동력을 서서히 전달하는 마찰 클러치(Friction clutch)입니다. 청정기는 기동할 때 마찰 클러치가 미끄러지며 서서히 회전을 올립니다.","x":["스파이럴 기어가 아닙니다.","수직축이 아닙니다.","수평축이 아닙니다.","정답. Friction clutch"],"t":"청정기 기동 = 마찰 클러치로 서서히"},"2024-1-영어-20":{"w":"실린더 라이너의 유막과 직접 닿는 면을 가진 것은 piston ring입니다.","x":["slip ring = 슬립링(전기)","정답. piston ring","O ring = 오링","mouth ring = 마우스링(펌프)"],"t":"piston ring face ↔ liner oil film"},"2024-1-영어-22":{"w":"the temperature and the humidity = 온도와 습도. \"쾌적한 조건은 주로 온도와 습도에 달려 있다.\"","x":["난방과 냉방이 아닙니다.","난방이 아닙니다.","정답. 온도와 습도","밀도가 아닙니다."],"t":"humidity = 습도"},"2024-1-영어-23":{"w":"주기관은 배 뒤쪽(stern)의 프로펠러(propeller)를 돌립니다.","x":["rudder = 타","정답. propeller","stern tube = 선미관","generator = 발전기"],"t":"stern = 선미"},"2024-1-영어-24":{"w":"압력이 너무 높을 때 증기를 방출해 폭발을 막는 것은 safety valve(안전밸브)입니다.","x":["drain valve = 드레인 밸브","정답. safety valve","by pass valve = 바이패스 밸브","non return valve = 역지밸브"],"t":"safety valve = 과압 방출"},"2024-1-영어-25":{"w":"빌지를 배출할 때 기름이 선외로 나가지 않게 하려면 15[ppm] 기름여과장치가 필요합니다.","x":["빌지펌프만으로는 기름을 거를 수 없습니다.","정답. 15[ppm] oil filtering equipment","소각기는 슬러지 처리용입니다.","오수처리장치는 분뇨 처리용입니다."],"t":"빌지 배출 = 15ppm 기름여과장치"},"2024-2-기관1-1":{"w":"내연기관의 이론 사이클은 정적(오토), 정압(디젤), 복합(사바테) 사이클입니다. 재열 사이클은 증기 원동소(랭킨 사이클을 개선한 것)의 사이클입니다.","x":["정적 사이클은 내연기관 사이클입니다.","정압 사이클은 내연기관 사이클입니다.","복합 사이클은 내연기관 사이클입니다.","정답(아닌 것). 재열 사이클은 증기 사이클입니다."],"t":"재열·재생·랭킨 = 증기 사이클"},"2024-2-기관1-3":{"w":"밸브 개폐시기 선도는 흡·배기밸브가 열리고 닫히는 시기를 상사점·하사점 전후의 크랭크 각도로 나타낸 그림입니다.","x":["정답. 크랭크 각도","압력으로 나타내지 않습니다.","회전속도가 아닙니다.","피스톤 위치가 아니라 크랭크 각도입니다."],"t":"밸브 선도 = 크랭크 각도"},"2024-2-기관1-4":{"w":"4행정 기관에서 흡기·배기밸브가 모두 닫히는 행정은 압축행정과 팽창(작동)행정입니다.","x":["흡입행정에는 흡기밸브가 열립니다.","흡입·배기행정에는 밸브가 열립니다.","배기행정에는 배기밸브가 열립니다.","정답. 압축과 팽창행정"],"t":"밸브 모두 닫힘 = 압축·팽창"},"2024-2-기관1-5":{"w":"라이너 위쪽 ①(헤드와 맞닿는 곳)에는 가스 누설을 막는 개스킷을, 아래쪽 ②에는 냉각수 누설을 막는 O링을 끼웁니다.","x":["정답. ① 개스킷, ② O링","위쪽은 개스킷입니다.","아래쪽은 O링입니다.","순서가 반대입니다."],"t":"라이너 위 개스킷, 아래 O링"},"2024-2-기관1-6":{"w":"직접분사식 연소실은 연소실 표면적이 작아 열손실이 적으므로 압축 온도가 높아 시동이 가장 쉽습니다. 부실식(예연소실·와류실·공기실)은 열손실이 커서 예열 플러그가 필요합니다.","x":["공기실식은 시동이 어렵습니다.","예연소실식은 예열 플러그가 필요합니다.","와류실식은 예열 플러그가 필요합니다.","정답. 직접분사식"],"t":"직접분사식 = 시동 쉬움, 열효율 좋음"},"2024-2-기관1-7":{"w":"트렁크형(4행정) 피스톤을 뺐을 때는 크라운의 균열, 카본 퇴적, 라이너 마멸 등을 점검합니다. 소기공은 2행정 기관에 있는 것으로 트렁크형 4행정 기관의 점검 사항이 아닙니다.","x":["크라운 균열은 점검합니다.","탄화물 퇴적은 점검합니다.","라이너 마멸은 점검합니다.","정답(옳지 않은 것). 소기공은 해당하지 않습니다."],"t":"소기공 = 2행정 기관"},"2024-2-기관1-8":{"w":"피스톤핀은 양 끝이 보스에 받쳐지고 가운데를 커넥팅로드가 누르므로 휨은 가운데에서 가장 큽니다.","x":["소형 고속기관은 알루미늄 피스톤을 많이 씁니다.","고과급일수록 피스톤이 뜨거워 냉각이 필요합니다.","정답(옳지 않은 것). 휨은 가운데에서 최대입니다.","크랭크핀 볼트는 사용 기간이 되면 교환합니다."],"t":"피스톤핀 휨 = 중앙 최대"},"2024-2-기관1-9":{"w":"피스톤링은 기밀 유지, 열 전달, 유막 형성을 합니다. 측압은 피스톤 스커트가 받습니다.","x":["정답(아닌 것). 측압은 피스톤 스커트가 받습니다.","기밀을 유지합니다.","열을 전달합니다.","유막을 만듭니다."],"t":"측압 = 피스톤 스커트"},"2024-2-기관1-10":{"w":"평균유효압력은 한 사이클의 일을 행정부피로 나눈 가상의 일정 압력입니다. 연료 분사량을 늘리면 일이 늘어 평균유효압력이 높아집니다. 지압 선도(강스프링 선도)의 면적으로 구합니다.","x":["정답. 분사량을 늘리면 높아집니다.","최고압력과 압축압력만으로는 구할 수 없습니다.","한 행정의 압력이 아닙니다.","약스프링 선도는 흡·배기 상태를 봅니다."],"t":"평균유효압력 ∝ 출력"},"2024-2-기관1-11":{"w":"그림의 ①은 캠의 움직임을 푸시로드로 받아 밸브스핀들을 눌러 여는 시소 모양의 로커암입니다.","x":["푸시로드는 캠과 로커암 사이의 막대입니다.","정답. ① = 로커암","밸브스핀들은 밸브의 축입니다.","롤러암은 캠에 닿는 부분입니다."],"t":"캠 → 푸시로드 → 로커암 → 밸브"},"2024-2-기관1-12":{"w":"수관 보일러는 관 속을 물이 흘러 고압에 견디고 증발이 빠릅니다. 대신 구조가 복잡해 청소·수리가 어렵고 제작비가 많이 들며 물 순환이 좋아야 합니다.","x":["정답. 고압에 견디고 증발이 빠름","연관 보일러의 장점입니다.","연관 보일러의 장점입니다.","수관은 물 순환이 중요합니다."],"t":"수관 보일러 = 고압·빠른 증발"},"2024-2-기관1-13":{"w":"과열도는 과열증기 온도에서 같은 압력의 포화온도를 뺀 값입니다.","x":["더하지 않습니다.","정답. 과열증기온도 − 포화증기온도","반대입니다.","대기온도와 관계없습니다."],"t":"과열도 = 과열온도 − 포화온도"},"2024-2-기관1-15":{"w":"날카로운 끝을 가진 핀(핀 날개)을 여러 개 배열해 좁은 틈을 만들고 증기를 교축시켜 누설을 막는 장치는 래버린스 패킹입니다.","x":["탄소패킹은 탄소 링을 씁니다.","기계식 패킹이 아닙니다.","정답. 래버린스 패킹","수봉패킹은 물을 씁니다."],"t":"래버린스 = 날카로운 핀 + 교축"},"2024-2-기관1-17":{"w":"선미관은 프로펠러축이 선체를 관통하는 곳에 있어 해수 침입을 막고 축을 받치는 베어링 역할을 합니다.","x":["중간축 베어링은 선내에 있습니다.","정답. 선미관","러더 핀틀 부시는 타의 베어링입니다.","추력 베어링은 추력을 전달합니다."],"t":"선미관 = 해수 차단 + 축 받침"},"2024-2-기관1-18":{"w":"탈아연 현상은 황동(구리+아연) 프로펠러에서 아연만 녹아 나가 표면이 거칠어지고 약해지는 부식입니다.","x":["피치가 바뀌지는 않습니다.","가장 적절한 설명이 아닙니다.","정답. 표면이 거칠어집니다.","색은 붉은 구리색으로 변합니다."],"t":"탈아연 = 황동에서 아연만 빠짐"},"2024-2-기관1-19":{"w":"선박의 저항이 커지면(선저 오손, 흘수 증가, 역풍 등) 배가 덜 나아가 슬립이 가장 크게 늘어납니다.","x":["정답. 저항 증가","피치가 작아지면 슬립은 줄어듭니다.","회전수가 줄면 슬립은 줄어듭니다.","속도가 늘면 슬립은 줄어듭니다."],"t":"저항↑ → 슬립↑"},"2024-2-기관1-20":{"w":"추진기 검사 때는 보스 경사부의 수밀 상태, 키홈의 해수 침입 흔적, 날개 끝의 굽음·손상 등을 특히 살핍니다. 캡과 키(타)의 거리는 분해 전 위치 확인용 계측이지 검사 관찰 사항이 아닙니다.","x":["보스 수밀 상태를 관찰합니다.","키홈 해수 침입을 관찰합니다.","날개 끝 굽음을 관찰합니다.","정답(아닌 것). 분해 전 계측 사항입니다."],"t":"추진기 검사 = 수밀·키홈·날개 손상"},"2024-2-기관1-21":{"w":"소비된 높이 0.8 − 0.4 = 0.4[m]. 부피 = 2 × 1 × 0.4 = 0.8[m³] = 800[ℓ]입니다.","x":["틀린 값입니다.","틀린 값입니다.","틀린 값입니다.","정답. 0.8[m³] = 800[ℓ]"],"t":"1[m³] = 1,000[ℓ]"},"2024-2-기관1-22":{"w":"연료유의 유황분은 연소해 황산화물이 되고, 물과 결합해 황산이 되어 저온부식을 일으킵니다.","x":["잔류탄소분은 카본 퇴적의 원인입니다.","정답. 유황분","회분은 마모의 원인입니다.","아스팔트분은 불완전 연소의 원인입니다."],"t":"저온부식 = 유황"},"2024-2-기관1-23":{"w":"온도 순서는 응고점 < 유동점 < 인화점 < 발화점 입니다. 발화점이 가장 높습니다.","x":["정답. 발화점","인화점은 발화점보다 낮습니다.","유동점은 낮습니다.","응고점이 가장 낮습니다."],"t":"응고점 < 유동점 < 인화점 < 발화점"},"2024-2-기관1-24":{"w":"탱크 안 기름의 양은 측심관에 측심자를 넣어 깊이를 재서 구합니다.","x":["정답. 측심관","주입관은 기름을 넣는 관입니다.","공기관은 탱크의 공기를 빼는 관입니다.","오버플로관은 넘치는 기름을 보내는 관입니다."],"t":"측심관 = 양 측정"},"2024-2-기관1-25":{"w":"점도지수는 온도가 변할 때 점도가 얼마나 변하는지를 나타내는 값입니다. 점도지수가 클수록 온도에 따른 점도 변화가 작습니다.","x":["애닐린지수는 착화성 관련 지수입니다.","정답. 점도지수","API지수는 비중을 나타냅니다.","점도계수가 아닙니다."],"t":"점도지수 = 온도에 따른 점도 변화"},"2024-2-기관2-1":{"w":"기관실 침수 때는 빌지 펌프, 잡용수(GS) 펌프, 밸러스트 펌프 등 해수·빌지 계통 펌프로 배수합니다. 청수 펌프는 청수 공급용이라 배수에 쓰지 않습니다.","x":["정답(아닌 것). 청수 펌프는 배수에 쓰지 않습니다.","잡용수 펌프는 배수에 씁니다.","밸러스트 펌프는 배수에 씁니다.","빌지 펌프는 배수에 씁니다."],"t":"침수 배수 = 빌지·잡용수·밸러스트 펌프"},"2024-2-기관2-2":{"w":"왕복펌프는 송출량은 적지만 높은 압력을 낼 수 있어, 적은 양을 높은 압력으로 보낼 때 씁니다.","x":["많은 양은 원심펌프가 적합합니다.","정답. 소유량 고압","대유량 저압은 축류펌프입니다.","적합하지 않습니다."],"t":"왕복펌프 = 소유량·고압"},"2024-2-기관2-3":{"w":"유공압 기호에서 원은 펌프·모터이고, 삼각형이 안쪽을 향하면 모터, 속이 빈 삼각형은 공기압입니다. 속이 빈 삼각형이 안쪽을 향한 ㉵가 공기압 모터입니다.","x":["공기압 모터 기호가 아닙니다.","공기압 모터 기호가 아닙니다.","공기압 모터 기호가 아닙니다.","정답. 빈 삼각형 + 안쪽 = 공기압 모터"],"t":"빈 삼각형 = 공기압, 안쪽 = 모터"},"2024-2-기관2-4":{"w":"유청정기는 운전 초기에 봉수를 넣어 회전통 바깥쪽에 물층을 만들어 줍니다. 봉수가 없으면 기름이 물 배출구로 빠져나갑니다.","x":["세척이 주목적이 아닙니다.","정답. 기름 유출 방지","세척이 주목적이 아닙니다.","회전통을 닫는 것은 작동수입니다."],"t":"봉수 = 기름 유출 방지"},"2024-2-기관2-5":{"w":"조타장치 4요소는 조종장치, 원동기, 추종장치, 타장치입니다.","x":["전달장치는 4요소가 아닙니다.","관제장치는 4요소가 아닙니다.","정답. 조종·원동기·추종·타장치","전동유압펌프는 원동기에 포함됩니다."],"t":"조타장치 4요소 = 조종·원동기·추종·타"},"2024-2-기관2-6":{"w":"윈치처럼 저속·고토크가 필요한 곳에는 반지름방향(레이디얼) 피스톤 모터를 많이 씁니다.","x":["기어 모터는 고속·저토크용입니다.","정답. 반지름방향 피스톤 모터","축방향 피스톤 모터는 고속용입니다.","서보 모터는 위치 제어용입니다."],"t":"윈치 = 레이디얼 피스톤 모터(저속 고토크)"},"2024-2-기관2-7":{"w":"불활성가스장치(IGS)는 보일러 배기가스를 세척기(스크러버)로 식히고 정화해 송풍기로 화물탱크에 보내며, 갑판 수봉장치(기밀상자)와 산소 농도 측정기를 갖춥니다. 수소 농도가 아니라 산소 농도를 측정합니다.","x":["세척기는 구성 요소입니다.","송풍기는 구성 요소입니다.","기밀상자(수봉장치)는 구성 요소입니다.","정답(아닌 것). 산소 농도를 측정합니다."],"t":"IGS = 산소 농도 8% 이하 유지"},"2024-2-기관2-8":{"w":"15[ppm] 기름여과장치는 운전 전에 내부를 해수(또는 청수)로 채웁니다.","x":["폐유를 채우지 않습니다.","정답. 해수","슬러지를 채우지 않습니다.","선저폐수를 채우지 않습니다."],"t":"기름여과장치 = 물로 채우고 시작"},"2024-2-기관2-9":{"w":"선저폐수(빌지)는 기름여과장치로 15[ppm] 이하로 처리한 뒤 해상으로 배출합니다.","x":["해당 명칭의 장치가 아닙니다.","정답. 기름여과장치","오수처리장치는 분뇨용입니다.","소각장치는 슬러지를 태웁니다."],"t":"빌지 처리 = 기름여과장치"},"2024-2-기관2-10":{"w":"소각장치의 배기덕트가 길면 배압이 높아져 연소가 나빠지므로 가능한 한 짧게 합니다.","x":["착화와 관계없습니다.","연료 절감이 주목적이 아닙니다.","통풍 능력이 주목적이 아닙니다.","정답. 배압 증가 방지"],"t":"배기덕트 짧게 = 배압↓"},"2024-2-기관2-11":{"w":"냉매는 수액기 출구 밸브를 닫고 보충합니다.","x":["충전관의 공기는 냉매 가스로 배제합니다.","정답(옳지 않은 것). 수액기 출구 밸브는 닫습니다.","응축기에 냉각수를 흘리며 합니다.","용기 무게로 보충량을 압니다."],"t":"냉매 보충 = 수액기 출구 밸브 닫기"},"2024-2-기관2-12":{"w":"응축기 냉각수의 출구와 입구 온도 차이는 약 5[℃]가 이상적입니다.","x":["정답. 약 5[℃]","너무 큽니다.","너무 큽니다.","너무 큽니다."],"t":"냉각수 온도차 약 5℃"},"2024-2-기관2-13":{"w":"유분리기는 압축기 토출 가스 속의 윤활유를 분리하므로 압축기와 응축기 사이에 설치합니다.","x":["정답. 압축기 – 응축기 사이","액관에 설치하지 않습니다.","액관에 설치하지 않습니다.","액관에 설치하지 않습니다."],"t":"유분리기 = 압축기 출구"},"2024-2-기관2-14":{"w":"공기조화장치는 온도, 습도, 기류(풍속), 청정도를 조절합니다. 압력 조절은 기능이 아닙니다.","x":["온도 조절은 기능입니다.","습도 조절은 기능입니다.","기류 조절은 기능입니다.","정답(아닌 것). 압력은 조절하지 않습니다."],"t":"공조 4요소 = 온도·습도·기류·청정도"},"2024-2-기관2-15":{"w":"건공기 1[kg]에 포함된 수증기 질량[kg]을 절대습도라 합니다.","x":["정답. 절대습도","상대습도는 수증기 분압의 비입니다.","비교습도는 포화 절대습도에 대한 비입니다.","포화도는 비교습도와 같습니다."],"t":"절대습도 = 수증기 kg / 건공기 kg"},"2024-2-기관2-16":{"w":"단조는 금속을 두드려 성형하므로 조직이 치밀해져 주물보다 기계적 성질이 좋습니다.","x":["자유단조와 형단조가 있습니다.","정답(옳지 않은 것). 단조품이 주물보다 성질이 좋습니다.","해머로 충격을 주어 가공합니다.","형단조의 설명이 맞습니다."],"t":"단조 = 조직 치밀, 강도 우수"},"2024-2-기관2-19":{"w":"선반은 원통 깎기, 나사 가공, 보링, 테이퍼 가공 등을 합니다. 기어 가공은 밀링이나 기어 전용 가공기로 합니다.","x":["정답. 기어 가공은 선반으로 어렵습니다.","수나사는 선반으로 가공합니다.","보링은 선반으로 합니다.","테이퍼는 선반으로 가공합니다."],"t":"기어 = 밀링·호빙"},"2024-2-기관2-20":{"w":"산소와 아세틸렌 용기는 모두 직사광선을 피해 40[℃] 이하의 서늘한 곳에 보관합니다.","x":["보호안경을 써야 합니다.","역화에 주의해야 합니다.","직사광선을 피합니다.","정답(옳지 않은 것). 산소 용기도 고온을 피합니다."],"t":"가스 용기 = 40℃ 이하 보관"},"2024-2-기관2-21":{"w":"선박의 저항과 추진력 계산에는 물에 잠긴 부분의 길이인 수선장(수선 길이)을 씁니다.","x":["전장은 배의 전체 길이입니다.","수선간장은 선박 규칙 등에 씁니다.","정답. 수선장","등록장은 등록용 길이입니다."],"t":"저항 계산 = 수선장"},"2024-2-기관2-23":{"w":"전진할 때 프로펠러 날개가 먼저 물을 가르는 쪽 모서리를 앞날(리딩 엣지)이라 합니다.","x":["뒷날은 반대쪽 모서리입니다.","정답. 앞날","틀린 용어입니다.","틀린 용어입니다."],"t":"앞날 = 먼저 물을 끊는 쪽"},"2024-2-기관2-25":{"w":"보이지 않는 부분(숨은선)은 파선으로 나타냅니다.","x":["정답. 파선 = 숨은선","일점 쇄선은 중심선입니다.","이점 쇄선은 가상선입니다.","실선은 외형선입니다."],"t":"숨은선 = 파선"},"2024-2-기관3-1":{"w":"임피던스는 전압을 전류로 나눈 값, Z = E / I [Ω]입니다.","x":["틀린 식입니다.","정답. Z = E / I","틀린 식입니다.","역수입니다."],"t":"Z = E / I"},"2024-2-기관3-2":{"w":"피상전력² = 유효전력² + 무효전력² 이므로 유효전력 = √(50² − 30²) = 40[W]. 역률 = 40 ÷ 50 = 0.8입니다.","x":["무효율(30/50)입니다.","틀린 값입니다.","정답. 40 ÷ 50 = 0.8","틀린 값입니다."],"t":"3:4:5 → 역률 0.8, 무효율 0.6"},"2024-2-기관3-3":{"w":"RLC 직렬 공진은 유도 리액턴스와 용량 리액턴스가 같을 때, 즉 2πfL = 1/(2πfC)일 때 일어납니다.","x":["틀린 식입니다.","유도성 회로입니다.","용량성 회로입니다.","정답. XL = XC"],"t":"공진 = XL = XC"},"2024-2-기관3-4":{"w":"전선의 저항 R = ρ × ℓ ÷ S 입니다. 길이에 비례하고 단면적에 반비례합니다.","x":["정답. R = ρℓ/S","틀린 식입니다.","틀린 식입니다.","틀린 식입니다."],"t":"R = ρℓ / S"},"2024-2-기관3-5":{"w":"XL = 2πfL = 2π × 60 × 0.005 = 0.6π[Ω]입니다.","x":["단위(mH)를 바꾸지 않은 값입니다.","틀린 값입니다.","틀린 값입니다.","정답. 2π × 60 × 0.005 = 0.6π"],"t":"XL = 2πfL (mH → H)"},"2024-2-기관3-6":{"w":"AC 100[V]처럼 표시된 사용전압은 실효값입니다.","x":["순시값이 아닙니다.","최대값이 아닙니다.","정답. 실효값","평균값이 아닙니다."],"t":"표시 전압 = 실효값"},"2024-2-기관3-7":{"w":"Z = √(R² + (XL − XC)²) = √(100² + 0²) = 100[Ω]입니다. XL과 XC가 같아 서로 상쇄되는 공진 상태입니다.","x":["정답. 공진 → Z = R = 100[Ω]","틀린 값입니다.","모두 더한 값입니다.","틀린 값입니다."],"t":"공진 시 Z = R"},"2024-2-기관3-8":{"w":"△결선에서는 선전류가 상전류의 √3배이고, 상전압과 선간전압은 같습니다.","x":["순서가 반대입니다.","정답. 선전류 = √3 상전류, 상전압 = 선간전압","Y결선의 관계입니다.","틀립니다."],"t":"△ = 전류 √3배"},"2024-2-기관3-9":{"w":"체적이 같은 채 길이가 3배가 되면 단면적은 1/3배가 됩니다. R ∝ 길이/단면적 이므로 3 ÷ (1/3) = 9배가 됩니다.","x":["단면적 변화를 빼먹었습니다.","틀립니다.","틀립니다.","정답. 3 × 3 = 9배"],"t":"늘여서 n배 길이 → 저항 n²배"},"2024-2-기관3-10":{"w":"변압기에서 E1/E2 = N1/N2 = I2/I1 입니다. 전압비는 권선비와 같고, 전류비는 반대입니다.","x":["정답. E1/E2 = N1/N2 = I2/I1","전류비가 반대입니다.","권선비가 반대입니다.","전압비가 반대입니다."],"t":"전압 ∝ 권수, 전류 ∝ 1/권수"},"2024-2-기관3-11":{"w":"기동 버튼 S1과 병렬로 연결된 MC a접점은 버튼을 떼어도 MC가 계속 동작하도록 하는 자기 유지 기능을 합니다.","x":["선행 동작 우선 회로가 아닙니다.","정답. 자기 유지","절환 기능이 아닙니다.","순차 동작이 아닙니다."],"t":"버튼과 병렬 a접점 = 자기 유지"},"2024-2-기관3-12":{"w":"Ns = 120f ÷ P = 120 × 60 ÷ 4 = 1,800[rpm]입니다.","x":["8극일 때입니다.","6극일 때입니다.","정답. 1,800[rpm]","2극일 때입니다."],"t":"60Hz: 2극 3,600 / 4극 1,800 / 6극 1,200"},"2024-2-기관3-13":{"w":"전압을 높이려면 직렬로 연결합니다. 24 ÷ 1.2 = 20개를 직렬로 연결합니다.","x":["정답. 20개 직렬","병렬은 전압이 그대로입니다.","12개 직렬은 14.4[V]입니다.","병렬은 전압이 그대로입니다."],"t":"전압↑ = 직렬, 용량↑ = 병렬"},"2024-2-기관3-14":{"w":"절연 종류별 허용 최고 온도: Y 90, A 105, E 120, B 130, F 155, H 180, C 180 초과[℃]입니다.","x":["O종은 없습니다.","B종은 130[℃]입니다.","정답. H종 180[℃]","C종은 180[℃] 초과입니다."],"t":"B 130, F 155, H 180"},"2024-2-기관3-15":{"w":"AVR(자동 전압 조정기)은 여자 전류를 자동으로 조절해 발전기 출력 전압을 일정하게 유지합니다.","x":["정답. AVR","RPR은 역전력 계전기입니다.","ACB는 기중 차단기입니다.","OCR은 과전류 계전기입니다."],"t":"AVR = 전압 일정"},"2024-2-기관3-16":{"w":"납축전지의 양극은 이산화납(PbO₂), 음극은 납(Pb)이고, 전해액은 묽은 황산(산성)입니다. 음극판이 양극판보다 1장 많고, 용량은 [Ah]로 표시합니다.","x":["음극판이 1장 더 많습니다.","용량은 [Ah]입니다.","정답. 음극 = 납(Pb)","전해액은 산성(황산)입니다."],"t":"납축전지 = 양극 PbO₂, 음극 Pb, 묽은 황산"},"2024-2-기관3-17":{"w":"권수비 = 440 ÷ 220 = 2. 전류는 전압과 반비례하므로 1차 전류 = 80 ÷ 2 = 40[A]입니다.","x":["틀린 값입니다.","틀린 값입니다.","틀린 값입니다.","정답. 80 ÷ 2 = 40[A]"],"t":"V1I1 = V2I2"},"2024-2-기관3-18":{"w":"전파 정류의 직류(평균) 전압은 교류 실효값의 약 0.9배입니다. 40 × 0.9 = 36[V]입니다.","x":["정답. 40 × 0.9 = 36[V]","실효값 그대로입니다.","최대값에 가깝습니다.","틀린 값입니다."],"t":"전파 정류 Vdc ≒ 0.9 V, 반파 ≒ 0.45 V"},"2024-2-기관3-19":{"w":"N형 반도체는 5가 원소인 도너를 첨가해 만듭니다.","x":["정답. 도너","억셉터는 P형용입니다.","캐리어는 전하 운반자입니다.","드리프트는 전하의 이동 현상입니다."],"t":"N형 = 도너"},"2024-2-기관3-20":{"w":"OR 기호(둥근 방패 모양) 끝에 동그라미(부정)가 붙은 것은 NOR입니다.","x":["AND는 D자 모양입니다.","정답. OR + 동그라미 = NOR","OR에는 동그라미가 없습니다.","NOT은 삼각형 + 동그라미입니다."],"t":"NOR = OR + 동그라미"},"2024-2-기관3-21":{"w":"RS 플립플롭은 R = S = 1 입력이 금지됩니다. JK 플립플롭은 이때 출력이 반전(토글)되도록 보완한 것입니다.","x":["RST는 클럭을 추가한 것입니다.","D 플립플롭은 입력을 하나로 줄인 것입니다.","T 플립플롭은 토글 전용입니다.","정답. JK 플립플롭"],"t":"JK = RS의 금지 입력 보완"},"2024-2-기관3-22":{"w":"제너 현상은 다이오드에 역방향 전압을 걸어 일정 값(제너 전압)에 이르면 갑자기 큰 전류가 흐르는 현상입니다.","x":["순방향이 아닙니다.","순방향이 아닙니다.","정답. 역방향 전압에서 큰 전류","전류가 0이 아닙니다."],"t":"제너 = 역방향 항복"},"2024-2-기관3-23":{"w":"포토 다이오드, 포토 트랜지스터, CdS는 빛을 검출하는 소자입니다. 트라이액은 교류 전력을 제어하는 양방향 스위칭 소자입니다.","x":["빛 검출 소자입니다.","빛 검출 소자입니다.","빛 검출 소자입니다.","정답(아닌 것). 트라이액은 전력 제어 소자입니다."],"t":"트라이액 = 교류 양방향 스위치"},"2024-2-기관3-24":{"w":"제너 다이오드 기호는 다이오드 막대(캐소드) 끝이 꺾인 모양입니다.","x":["다른 소자 기호입니다.","다른 소자 기호입니다.","정답. 꺾인 막대 = 제너","다른 소자 기호입니다."],"t":"제너 = 꺾인 막대"},"2024-2-기관3-25":{"w":"원 안에 이미터(E)가 비스듬히 붙고 위아래로 베이스1(B1), 베이스2(B2)가 있는 기호는 UJT(단접합 트랜지스터)입니다.","x":["정답. UJT","SCR은 다이오드 + 게이트입니다.","제너 다이오드가 아닙니다.","트라이액이 아닙니다."],"t":"UJT = E, B1, B2"},"2024-2-직무일반-2":{"w":"당직기관사는 선박·승무원 안전 확보, 효율적인 운전, 기기 상태 확인 등을 합니다. 전동기 슬립은 부하에 따라 정해지는 값(보통 수 %)이며 50[%]로 유지하는 것이 아닙니다.","x":["안전 확보는 맞습니다.","효율적 운전은 맞습니다.","정답(옳지 않은 것). 슬립 50[%]는 비정상입니다.","기기 상태 확인은 맞습니다."],"t":"유도전동기 슬립 = 보통 2~5%"},"2024-2-직무일반-5":{"w":"피스톤핀 같은 원통의 바깥지름을 정밀하게 잴 때는 외측 마이크로미터를 씁니다.","x":["디바이더는 금긋기·거리 옮기기용입니다.","틈새게이지는 틈을 잽니다.","정답. 외측 마이크로미터","버니어캘리퍼스는 정밀도가 낮습니다."],"t":"외경 정밀 측정 = 외측 마이크로미터"},"2024-2-직무일반-6":{"w":"배기가스의 유해 성분은 질소산화물(NO, NO₂), 황산화물(SO₂), 일산화탄소, 매연 등입니다. 질소(N₂)는 공기의 주성분으로 무해합니다.","x":["정답(아닌 것). 질소는 무해합니다.","일산화질소는 유해합니다.","이산화황은 유해합니다.","이산화질소는 유해합니다."],"t":"N₂ 무해, NOx·SOx 유해"},"2024-2-직무일반-7":{"w":"대량 유출 시에는 선체 경사를 조정해 유출을 줄이고, 손상 부위를 긴급 수리하며, 오일펜스를 설치합니다. 탱크 안에 유처리제를 뿌리는 것은 유출을 늦추지 못합니다.","x":["경사 조정은 맞는 조치입니다.","정답(옳지 않은 것). 탱크 내 유처리제 살포는 틀린 조치입니다.","긴급 수리는 맞습니다.","오일펜스 설치는 맞습니다."],"t":"유출 = 경사 조정·이송·수리·오일펜스"},"2024-2-직무일반-9":{"w":"오존층파괴물질기록부의 기록 코드 중 대기 배출에 관한 사항은 코드 C입니다. (A 충전, B 수리·정비, C 대기 배출 등으로 구분)","x":["틀린 코드입니다.","틀린 코드입니다.","정답. 코드 C = 대기 배출","틀린 코드입니다."],"t":"대기 배출 = 코드 C"},"2024-2-직무일반-10":{"w":"선박운항탄소집약도지수(CII)는 실제 운항 결과로 사후에 계산하는 연간 탄소집약도(에너지효율) 지표입니다. EEDI·EEXI는 설계 단계의 지수입니다.","x":["정답. 선박운항탄소집약도지수(CII)","설계 단계의 지수(EEDI)입니다.","현존선 지수(EEXI)입니다.","일반 용어입니다."],"t":"CII = 운항 실적(사후), EEDI·EEXI = 설계"},"2024-2-직무일반-11":{"w":"구강 대 구강 인공호흡을 할 때는 불어 넣은 공기가 새지 않도록 환자의 콧구멍을 막아야 합니다.","x":["눕히고 이물질을 제거합니다.","정답(옳지 않은 것). 콧구멍은 막습니다.","기도를 확보합니다.","가슴이 부풀 정도로 불어 넣습니다."],"t":"입 대 입 = 코를 막고"},"2024-2-직무일반-13":{"w":"일사병 환자는 그늘진 시원한 곳으로 옮기고 꽉 끼는 옷을 느슨하게 하며, 의식이 있으면 물이나 이온음료를 조금씩 줍니다. 염분을 그대로 먹이는 것은 적절하지 않고, 필요하면 옅은 소금물·이온음료로 보충합니다.","x":["시원한 곳으로 옮깁니다.","옷을 느슨하게 합니다.","의식이 없으면 음료를 주지 않습니다.","정답(적절하지 않은 것). 염분을 그대로 먹이지 않습니다."],"t":"일사병 = 그늘·옷 풀기·수분"},"2024-2-직무일반-16":{"w":"정전 직후 비상 조명은 비상 축전지가 즉시 전원을 공급합니다.","x":["인버터는 변환 장치입니다.","컨버터는 변환 장치입니다.","주발전기는 정전 상태입니다.","정답. 비상 축전지"],"t":"정전 직후 = 축전지"},"2024-2-직무일반-17":{"w":"조타장치 성능 기준: 최대 전진 속력에서 한쪽 35°부터 반대쪽 35°까지 돌릴 수 있어야 하고, 한쪽 35°에서 반대쪽 30°까지 28초 이내에 돌릴 수 있어야 합니다.","x":["틀립니다.","첫 번째 각도가 틀립니다.","시간이 틀립니다.","정답. 35°, 28초"],"t":"35° → 반대 30° = 28초 이내"},"2024-2-직무일반-18":{"w":"인화점이 낮은 기름일수록 낮은 온도에서도 불이 붙기 쉬워 화재가 잘 납니다.","x":["정답. 인화점","발열량과 관계없습니다.","세탄값과 관계없습니다.","임계점과 관계없습니다."],"t":"인화점 낮음 = 화재 위험"},"2024-2-직무일반-19":{"w":"D급 화재는 마그네슘 등 가연성 금속 화재로, 물을 뿌리면 폭발적으로 반응하므로 물을 쓰면 안 됩니다. 마른 모래·금속화재용 소화제를 씁니다.","x":["금속 화재입니다.","흡열 소화제를 씁니다.","정답(옳지 않은 것). 물은 매우 위험합니다.","냉각해 반응을 멈춥니다."],"t":"D급(금속) = 물 금지"},"2024-2-직무일반-20":{"w":"전기화재를 막으려면 절연저항을 규정치 이상으로 유지해야 합니다.","x":["연결부 고정은 예방법입니다.","과부하 금지는 예방법입니다.","정답(아닌 것). 절연저항은 높게 유지합니다.","단자 고정은 예방법입니다."],"t":"절연저항 = 높게"},"2024-2-직무일반-21":{"w":"기관실 화재 예방은 순찰, 청결 유지, 통풍, 누유 방지 등입니다. 비상 빌지 펌프 확인은 침수 대비책입니다.","x":["순찰은 예방법입니다.","청결 유지는 예방법입니다.","정답(옳지 않은 것). 침수 대비책입니다.","통풍은 예방법입니다."],"t":"빌지 펌프 = 침수 대비"},"2024-2-직무일반-22":{"w":"선박법은 선박의 국적, 톤수 측정·등록 등을 정해 해사 제도를 적정하게 운영하고 해상 질서를 유지하는 것이 목적입니다. 선내 질서 유지는 선원법의 목적입니다.","x":["정답(아닌 것). 선내 질서는 선원법입니다.","국적은 선박법 사항입니다.","톤수 측정은 선박법 사항입니다.","선박법의 목적입니다."],"t":"선내 질서 = 선원법"},"2024-2-직무일반-24":{"w":"해양오염방지설비를 선박에 처음 설치해 항해에 사용하려면 정기검사를 받습니다.","x":["정답. 최초 설치 = 정기검사","중간검사는 유효기간 중에 받습니다.","특별검사는 따로 정한 경우입니다.","임시검사는 개조·수리 때 받습니다."],"t":"최초 = 정기검사"},"2024-2-직무일반-25":{"w":"총톤수 100~400톤 미만 비유조선의 기관구역에는 선저폐수저장탱크 또는 기름여과장치, 배출관장치를 설치합니다. 유성찌꺼기탱크는 400톤 이상 선박에 의무입니다.","x":["설치 대상입니다.","정답(아닌 것). 유성찌꺼기탱크는 400톤 이상입니다.","설치 대상입니다.","설치 대상입니다."],"t":"유성찌꺼기탱크 = 400톤 이상"},"2024-2-영어-1":{"w":"\"공기탱크에 압축공기를 충전했다.\" charge = 충전하다.","x":["Took = 가졌다","Increased = 올렸다","Started = 시작했다","정답. Charged = 충전했다"],"t":"charge = 충전"},"2024-2-영어-2":{"w":"\"냉각수 출구 온도를 조정했다.\" adjust = 조정하다.","x":["정답. Adjusted = 조정했다","Exchanged = 교환했다","Refilled = 다시 채웠다","Charged = 충전했다"],"t":"adjust temperature"},"2024-2-영어-3":{"w":"M.D.O. = Marine Diesel Oil = 선박용 디젤유입니다.","x":["정답. M.D.O.","H.F.O. = 중유","L.O. = 윤활유","M.G.O. = 선박용 경유"],"t":"MDO 디젤유, HFO 중유, MGO 경유"},"2024-2-영어-4":{"w":"해양오염 방지를 위한 비치 서류는 기름기록부(Oil record book), 폐기물기록부(Garbage record book), 선박해양오염비상계획서(SOPEP) 등입니다. 연료유 공급서(BDN)는 연료 수급 증명 서류입니다.","x":["기름기록부는 비치 서류입니다.","정답(아닌 것). 연료 수급 영수증입니다.","폐기물기록부는 비치 서류입니다.","SOPEP는 비치 서류입니다."],"t":"SOPEP = 선박해양오염비상계획서"},"2024-2-영어-5":{"w":"아연판 = zinc plate, 4개 = 4 pieces. \"Renewed 4 pieces of zinc plates for aux. condenser.\"","x":["copper = 구리","bronze = 청동","iron = 철","정답. zinc plates = 아연판"],"t":"zinc = 아연"},"2024-2-영어-6":{"w":"태핏 간극 = tappet clearance 입니다.","x":["air gap = 공극","overlap clearance가 아닙니다.","top clearance = 톱 클리어런스","정답. tappet clearance"],"t":"tappet clearance = 밸브 간극"},"2024-2-영어-7":{"w":"Viscosity = 점도 입니다.","x":["밀도는 density입니다.","정답. 점도","비열은 specific heat입니다.","비중은 specific gravity입니다."],"t":"viscosity = 점도"},"2024-2-영어-10":{"w":"기관 이상과 처리, 입·출항 시간과 rpm, 연료유·윤활유 소비량 등을 기록하는 것은 기관일지(Engine room log book)입니다.","x":["기름기록부는 기름 처리 기록입니다.","벨북은 기관 명령 기록입니다.","정답. Engine room log book","적요일지는 항차 요약입니다."],"t":"engine log = 기관 운전 전반 기록"},"2024-2-영어-12":{"w":"\"전동기 기동기의 전자 접촉기 불량 접점을 사포(sand paper)로 다듬어라.\" 접점은 고운 사포로 살짝 다듬습니다.","x":["정답. sand paper = 사포","연삭기는 너무 거칩니다.","쇠톱은 자르는 공구입니다.","휴대용 연삭기는 너무 거칩니다."],"t":"접점 손질 = 고운 사포"},"2024-2-영어-13":{"w":"hair crack = 머리카락처럼 가는 미세한 균열입니다.","x":["부식이 아닙니다.","전식이 아닙니다.","정답. 미세한 균열","침식이 아닙니다."],"t":"hair crack = 미세 균열"},"2024-2-영어-14":{"w":"선미 = stern, 선수 = bow, 우현 = starboard, 좌현 = port 입니다.","x":["bow = 선수","starboard = 우현","port = 좌현","정답. stern = 선미"],"t":"bow 선수, stern 선미"},"2024-2-영어-15":{"w":"stores on hand = 현재 가지고 있는(재고) 선용품입니다.","x":["정답. 재고 선용품","소비된 것은 consumed입니다.","새것은 new입니다.","사용 중은 in use입니다."],"t":"on hand = 보유 중인"},"2024-2-영어-16":{"w":"건조기(drier)는 냉매를 충전할 때 들어올 수 있는 수분을 제거합니다.","x":["정답. drier = 건조기","purger = 불응축가스 배출기","evaporator = 증발기","solenoid valve = 전자밸브"],"t":"drier = 수분 제거"},"2024-2-영어-18":{"w":"염분계(salinity indicator)는 물속 염분의 비율(the proportion of salt)을 나타냅니다.","x":["PH = 산성도","vacuum = 진공","viscosity = 점도","정답. 염분의 비율"],"t":"salinity = 염분"},"2024-2-영어-20":{"w":"tail shaft = 프로펠러축(propeller shaft)입니다.","x":["stern shaft는 쓰이지만 정답 표현이 아닙니다.","정답. Propeller shaft","Cam shaft = 캠축","Thrust shaft = 추력축"],"t":"tail shaft = propeller shaft"},"2024-2-영어-23":{"w":"움직이는 부분과 고정된 부분 사이의 누설을 막는 장치는 stuffing box(패킹 상자)입니다.","x":["Rose box = 빌지 흡입구 여과상자","정답. Stuffing box","Mud box = 진흙 거르개","Bearing box = 베어링 상자"],"t":"stuffing box = 축 누설 방지"},"2024-2-영어-24":{"w":"흡입행정에서는 배기밸브가 닫히고(closed) 흡기밸브가 열립니다(opened).","x":["틀립니다.","반대입니다.","정답. 배기 closed, 흡기 opened","둘 다 닫히는 것은 압축·팽창행정입니다."],"t":"흡입행정 = 흡기 열림"},"2024-2-영어-25":{"w":"디젤 발전기는 디젤기관(a diesel engine)과 발전기(an electric generator)를 결합해 전기 에너지를 만듭니다.","x":["actuator = 작동기","가스기관·변환기가 아닙니다.","가솔린기관·압축기가 아닙니다.","정답. diesel engine + electric generator"],"t":"D/G = diesel + generator"},"2024-3-기관1-1":{"w":"밸브 겹침은 상사점 부근에서 흡기·배기밸브가 함께 열려 있는 구간입니다. 흡기밸브 열림(상사점 전 15°) + 배기밸브 닫힘(상사점 후 10°) = 25°입니다.","x":["틀린 값입니다.","배기만 두 번 더한 값입니다.","정답. 15° + 10° = 25°","흡기만 두 번 더한 값입니다."],"t":"오버랩 = 흡기 열림(BTDC) + 배기 닫힘(ATDC)"},"2024-3-기관1-2":{"w":"직접분사식은 연소실 표면적이 작아 열손실이 적고 압축 온도가 높아 시동이 가장 쉽습니다.","x":["예연소실식은 예열 플러그가 필요합니다.","와류실식은 예열 플러그가 필요합니다.","정답. 직접분사식","공기실식은 시동이 어렵습니다."],"t":"시동 쉬움 = 직접분사식"},"2024-3-기관1-3":{"w":"블로바이는 연소가스가 피스톤링을 지나 크랭크실로 새는 현상입니다. 링의 면압·장력을 높이고, 라이너와의 접촉을 좋게 하고, 링 수를 늘리면 줄어듭니다. 링 수를 줄이면 오히려 늘어납니다.","x":["면압 증가는 대책입니다.","장력 증가는 대책입니다.","접촉 개선은 대책입니다.","정답(아닌 것). 링 수를 줄이면 블로바이가 늘어납니다."],"t":"블로바이 = 가스가 크랭크실로 샘"},"2024-3-기관1-4":{"w":"라이너 위쪽 ①에는 개스킷(가스 밀봉), 아래쪽 ②에는 O링(냉각수 밀봉)이 들어갑니다.","x":["정답. ① 개스킷, ② O링","아래쪽은 O링입니다.","위쪽은 개스킷입니다.","틀립니다."],"t":"라이너 위 개스킷, 아래 O링"},"2024-3-기관1-5":{"w":"피스톤링의 절구(끊어진 틈)는 가스가 한 줄로 새지 않도록 링마다 서로 엇갈리게(보통 120°~180°) 배치해야 합니다.","x":["정답(옳지 않은 것). 절구는 서로 엇갈리게 합니다.","제일 밑의 링부터 끼웁니다.","상하 방향을 지킵니다(TOP 표시).","깨끗이 닦고 윤활유를 바릅니다."],"t":"링 절구 = 엇갈리게"},"2024-3-기관1-6":{"w":"크랭크축의 불균형 회전을 보정해 진동을 줄이는 것은 밸런스 웨이트(평형추)입니다.","x":["정답. 밸런스 웨이트","크랭크저널은 메인 베어링에 얹히는 부분입니다.","플라이 웨이트는 조속기의 추입니다.","크랭크암은 저널과 핀을 잇는 부분입니다."],"t":"밸런스 웨이트 = 진동 감소"},"2024-3-기관1-7":{"w":"4행정 기관은 크랭크축 2회전에 흡·배기밸브가 한 번씩 열리므로 캠축은 크랭크축의 1/2 속도로 돕니다. (2행정은 같은 속도)","x":["틀립니다.","정답. 크랭크축의 1/2","2행정 기관입니다.","틀립니다."],"t":"4행정 캠축 = 크랭크축 1/2"},"2024-3-기관1-8":{"w":"120°마다 착화하므로 240°는 두 칸입니다. 2번 다음은 4번, 그다음은 1번입니다(순서가 돌아옴).","x":["정답. 2 → 4 → 1","틀립니다.","한 칸(120°) 뒤입니다.","틀립니다."],"t":"착화순서는 순환합니다"},"2024-3-기관1-9":{"w":"배기온도가 오르는 원인은 분사시기 늦음(후연소), 배기밸브 누설, 과급기 회전수 저하(공기 부족) 등입니다. 연료유에 공기가 들어가면 연료 공급이 불안정해 출력이 떨어지며 배기온도 상승 원인은 아닙니다.","x":["후연소로 배기온도가 오릅니다.","배기밸브가 새면 오릅니다.","공기가 부족하면 오릅니다.","정답(옳지 않은 것). 공기 침입은 배기온도 상승 원인이 아닙니다."],"t":"배기온도↑ = 분사 늦음·밸브 누설·공기 부족"},"2024-3-기관1-10":{"w":"실린더 안에서 연소가스가 피스톤에 한 일로 발생하는 마력은 지시(도시)마력입니다.","x":["전달마력은 프로펠러에 전달되는 마력입니다.","추진마력은 해당하지 않습니다.","제동마력은 출력축에서 나오는 마력입니다.","정답. 지시마력"],"t":"실린더 안 = 지시마력(IHP)"},"2024-3-기관1-11":{"w":"스로틀 노즐은 니들 밸브 끝이 2단으로 되어 있어 처음에는 조금, 나중에는 많이 분사하므로 착화지연 동안 연료가 덜 쌓여 디젤 노크 방지에 효과적입니다.","x":["단공 노즐은 구멍이 하나입니다.","핀틀 노즐은 니들 끝이 돌출된 형식입니다.","다공 노즐은 구멍이 여러 개입니다.","정답. 스로틀 노즐"],"t":"스로틀 노즐 = 2단 분사, 노크 방지"},"2024-3-기관1-12":{"w":"캐스케이드 탱크(급수 여과 탱크)는 복수와 보충수를 모아 저장하고 기름 등 이물질을 걸러 보일러 급수로 보냅니다. 증기를 발생시키지는 않습니다.","x":["급수를 저장합니다.","이물질을 제거합니다.","급수를 보충합니다.","정답(옳지 않은 것). 증기 발생은 보일러의 역할입니다."],"t":"캐스케이드 탱크 = 급수 저장·여과"},"2024-3-기관1-13":{"w":"안전밸브의 방출능력은 증기 정지밸브를 닫고 최대 연소 상태로 운전해 압력이 일정 한도 이상 오르지 않는지 확인하는 축기시험으로 확인합니다.","x":["정답. 축기시험","압력시험이 아닙니다.","진공시험이 아닙니다.","수압시험은 강도·누설 시험입니다."],"t":"안전밸브 방출능력 = 축기시험"},"2024-3-기관1-15":{"w":"수트블로는 보일러를 정상 운전 중에 고압 증기나 압축공기로 전열면의 그을음을 불어내는 작업입니다. 물방울 없는 건조한 과열증기를 쓰는 것이 좋습니다.","x":["정상 운전 중에 합니다.","고압증기·압축공기를 씁니다.","드레인을 충분히 뺍니다.","정답(옳지 않은 것). 오히려 건조한 과열증기가 좋습니다."],"t":"수트블로 = 드레인 제거 후 건조 증기"},"2024-3-기관1-16":{"w":"선미관은 프로펠러축이 선체를 관통하는 곳에서 해수 침입을 막고 축을 받치는 베어링 역할을 합니다.","x":["중간축 베어링은 선내에 있습니다.","정답. 선미관","실린더와 관계없습니다.","스러스트 베어링은 추력을 전달합니다."],"t":"선미관 = 해수 차단 + 베어링"},"2024-3-기관1-18":{"w":"기름 윤활식 선미관의 선수측 실은 윤활유가 기관실 쪽으로 새는 것을 막습니다.","x":["해수 유입 방지는 선미측 실입니다.","공기 누출과 관계없습니다.","정답. 윤활유 누출 방지","빌지 유입과 관계없습니다."],"t":"선수측 실 = 윤활유 누출 방지"},"2024-3-기관1-19":{"w":"추진 출력은 유효마력과 추진효율, 애드미럴티 계수, 수조 모형 시험 등으로 구합니다. CFR 기관은 연료의 세탄가·옥탄가를 시험하는 표준 기관입니다.","x":["맞는 방법입니다.","맞는 방법입니다.","맞는 방법입니다.","정답(옳지 않은 것). CFR 기관은 연료 시험용입니다."],"t":"CFR 기관 = 연료 착화성 시험"},"2024-3-기관1-20":{"w":"슬립 s = (Vp − V) ÷ Vp 이므로 Vp = V ÷ (1 − s) = 12 ÷ 0.8 = 15노트입니다.","x":["틀린 값입니다.","배의 속도입니다.","틀린 값입니다.","정답. 12 ÷ 0.8 = 15노트"],"t":"Vp = V / (1 − s)"},"2024-3-기관1-21":{"w":"불꽃 없이 스스로 불이 붙는 최저 온도는 발화점(착화점)입니다.","x":["인화점은 불꽃을 대야 합니다.","유동점은 흐르는 최저 온도입니다.","정답. 발화점","임계점은 액체와 기체의 구분이 없어지는 점입니다."],"t":"스스로 = 발화점"},"2024-3-기관1-22":{"w":"디젤기관 배기 속 수증기는 응축되지 않으므로 저위발열량을 씁니다.","x":["중유 약 10,000[kcal/kgf]는 맞습니다.","정답(옳지 않은 것). 저위발열량을 씁니다.","고위발열량의 정의가 맞습니다.","저위발열량의 정의가 맞습니다."],"t":"기관 계산 = 저위발열량"},"2024-3-기관1-24":{"w":"유성은 윤활유가 금속면에 달라붙어 얇은 유막을 완전히 만들려는 성질입니다.","x":["점도와 다릅니다.","흐르려는 성질이 아닙니다.","완전 윤활과 다릅니다.","정답. 금속면에 얇은 유막을 만드는 성질"],"t":"유성 = 흡착·유막 형성"},"2024-3-기관2-2":{"w":"액체와 기체가 섞인 것을 다루는 진공펌프로는 수봉식(액봉식) 진공펌프인 내시(Nash) 펌프가 가장 적합합니다.","x":["기어 펌프는 기름용입니다.","원심 펌프는 기체가 섞이면 안 됩니다.","정답. 내시(수봉식 진공) 펌프","베인 펌프는 적합하지 않습니다."],"t":"기액 혼합 진공 = 내시 펌프"},"2024-3-기관2-3":{"w":"펌프 효율 = 수마력(유체가 얻은 동력) ÷ 축마력(펌프에 들어간 동력)입니다.","x":["반대입니다.","틀린 식입니다.","틀린 식입니다.","정답. 수마력 / 축마력"],"t":"효율 = 출력(수마력) / 입력(축마력)"},"2024-3-기관2-4":{"w":"선박의 압축공기는 공구 구동, 공기압 밸브 조작, 주기관 시동 등에 씁니다. 주기관 소기는 과급기나 소기 송풍기가 공급합니다.","x":["공구 구동에 씁니다.","조작밸브 작동에 씁니다.","주기관 시동에 씁니다.","정답(옳지 않은 것). 소기는 과급기가 합니다."],"t":"소기 = 과급기·송풍기"},"2024-3-기관2-7":{"w":"유면검출기가 기름층을 감지하면 배유 전자밸브를 열고, 타이머 신호로 닫습니다.","x":["콜레서는 기름을 뭉치게 합니다.","포집관은 기름을 모읍니다.","타이머는 밸브를 닫습니다.","정답. 유면검출기 신호로 열림"],"t":"열림 = 유면검출기, 닫힘 = 타이머"},"2024-3-기관2-9":{"w":"유수 혼합액의 온도를 높이면 기름의 점도가 낮아지고 물과의 비중 차가 커져 분리가 잘 됩니다.","x":["유속을 느리게 해야 합니다.","교반하면 섞입니다.","기름방울은 커야 잘 분리됩니다.","정답. 온도를 높입니다."],"t":"분리 향상 = 가온·저유속·큰 유적"},"2024-3-기관2-11":{"w":"증발기 출구 냉매가 과열된 채 압축되면 흡입 가스의 비체적이 커져 냉매순환량이 줄고, 압축기가 과열되며, 용적효율이 떨어집니다.","x":["압축기가 과열됩니다.","정답(옳지 않은 것). 냉매순환량은 감소합니다.","용적효율이 떨어집니다.","성적계수 설명은 출제 기준상 정답이 아닙니다."],"t":"과열압축 = 순환량↓, 압축기 과열","c":"성적계수도 일반적으로는 떨어지므로 ㉵도 옳지 않다고 볼 여지가 있으나, 공식 정답은 ㉯입니다."},"2024-3-기관2-12":{"w":"액분리기는 증발기 출구 냉매 가스 속의 냉매액을 분리해 압축기로 액이 들어가지 않게 하고 분리한 액을 증발기 쪽으로 되돌립니다.","x":["수액기는 액 냉매를 저장합니다.","유분리기는 윤활유를 분리합니다.","정답. 액분리기","팽창밸브는 냉매량을 조절합니다."],"t":"액분리기 = 액 냉매 분리"},"2024-3-기관2-13":{"w":"증발관에 서리가 끼면 전열이 나빠지므로 제상장치로 서리를 제거해 전열작용을 좋게 합니다.","x":["부하경감장치는 기동 부하를 줄입니다.","배기장치가 아닙니다.","정답. 제상장치","건조장치는 수분을 제거합니다."],"t":"제상 = 전열 회복"},"2024-3-기관2-14":{"w":"1냉동톤(RT)은 약 3,320[kcal/h]입니다.","x":["정답. 3,320[kcal/h]","틀린 값입니다.","틀린 값입니다.","틀린 값입니다."],"t":"1RT ≒ 3,320kcal/h"},"2024-3-기관2-17":{"w":"서피스 게이지는 정반 위에서 일감에 중심을 잡거나 평행선을 긋는 공구입니다.","x":["바이스는 일감을 무는 공구입니다(평면대는 정반).","금긋기 바늘 끝은 경화강입니다.","정답. 서피스 게이지","캘리퍼스는 필러게이지가 아닙니다."],"t":"서피스 게이지 = 금긋기·중심 잡기"},"2024-3-기관2-19":{"w":"움직이지 않는 두 면(플랜지 등) 사이의 누설은 개스킷으로 막습니다. 움직이는 축에는 패킹을 씁니다.","x":["정답. 개스킷 = 고정면 밀봉","펠트 링은 축 먼지 막이입니다.","글랜드 패킹은 움직이는 축에 씁니다.","래버린스 패킹은 회전축에 씁니다."],"t":"고정면 = 개스킷, 운동면 = 패킹"},"2024-3-기관2-20":{"w":"산소-아세틸렌 절단은 강을 산화시켜 태워 자르는 방법으로 연강이 가장 잘 절단됩니다. 스테인리스강·알루미늄·합금강은 산화물이 잘 녹지 않아 어렵습니다.","x":["합금강은 절단이 어렵습니다.","알루미늄은 절단이 어렵습니다.","정답. 연강","스테인리스강은 절단이 어렵습니다."],"t":"가스 절단 = 연강"},"2024-3-기관2-21":{"w":"갑판보를 위로 볼록하게 만들어 물이 잘 빠지게 하고 강도를 높인 것을 캠버(camber)라 합니다.","x":["건현은 수면에서 갑판까지의 높이입니다.","정답. 캠버","현호(sheer)는 선수미 방향으로 휜 것입니다.","용골은 배 밑 중심 부재입니다."],"t":"캠버 = 가로로 볼록, 현호 = 세로로 휨"},"2024-3-기관2-25":{"w":"최대허용치수와 최소허용치수의 차이를 치수 공차라 합니다.","x":["위 치수 허용차는 최대허용치수 − 기준치수입니다.","아래 치수 허용차는 최소허용치수 − 기준치수입니다.","정답. 치수 공차","기준 치수는 기준이 되는 치수입니다."],"t":"공차 = 최대 − 최소"},"2024-3-기관3-5":{"w":"지름이 2배면 단면적은 4배가 됩니다. 길이 4배 ÷ 단면적 4배 = 1배로 저항은 변하지 않습니다.","x":["정답. 4 ÷ 4 = 1배","틀립니다.","틀립니다.","단면적 변화를 빼먹은 값입니다."],"t":"단면적 ∝ 지름²"},"2024-3-기관3-6":{"w":"△결선에서는 선전류가 상전류의 √3배이고, 상전압과 선간전압이 같습니다.","x":["순서가 반대입니다.","정답. 선전류 = √3 상전류","Y결선의 관계입니다.","틀립니다."],"t":"△ = 전류 √3배"},"2024-3-기관3-7":{"w":"푸시 버튼(누름 버튼) 접점 기호는 접점 위에 T자 모양의 누름 손잡이가 있는 모양입니다.","x":["한시(타이머) 접점 기호입니다.","일반 스위치(나이프 스위치)입니다.","다른 접점 기호입니다.","정답. T자 손잡이 = 푸시 버튼"],"t":"푸시 버튼 = T자 누름대"},"2024-3-기관3-8":{"w":"절연저항은 메거(절연저항계)로 측정합니다.","x":["정답. 메거","멀티테스터는 저전압 측정용입니다.","옴 미터는 일반 저항용입니다.","접지 저항계는 접지저항용입니다."],"t":"절연저항 = 메거"},"2024-3-기관3-10":{"w":"납축전지를 충전하면 물이 분해되어 양극에서 산소, 음극에서 수소가 발생합니다.","x":["정답. 양극 산소, 음극 수소","반대입니다.","질소는 발생하지 않습니다.","질소는 발생하지 않습니다."],"t":"충전 가스 = 양극 O₂, 음극 H₂"},"2024-3-기관3-11":{"w":"전기기기에 표시된 교류 전압은 실효값입니다.","x":["평균값이 아닙니다.","정답. 실효값","최대값이 아닙니다.","최소값이 아닙니다."],"t":"표시 전압 = 실효값"},"2024-3-기관3-12":{"w":"선박 납축전지는 정전 시 비상전등, 통신장비, 항해계기 등의 비상전원으로 씁니다. 공기압축기처럼 큰 전력이 필요한 기기는 축전지로 운전하지 않습니다.","x":["비상전등에 씁니다.","통신장비에 씁니다.","항해계기에 씁니다.","정답(옳지 않은 것). 공기압축기는 발전기 전원으로 운전합니다."],"t":"축전지 = 비상 조명·통신·계기"},"2024-3-기관3-13":{"w":"유도전동기의 회전자는 항상 동기속도보다 조금 느리게 돕니다(슬립). 같아지면 토크가 0이 됩니다.","x":["정답. 동기속도가 더 빠릅니다.","회전자가 빠르면 발전기가 됩니다.","같으면 토크가 0입니다.","틀립니다."],"t":"유도전동기 = 동기속도보다 느림"},"2024-3-기관3-14":{"w":"P = 120f ÷ N = 120 × 60 ÷ 720 = 10극입니다.","x":["틀린 값입니다.","틀린 값입니다.","정답. 7,200 ÷ 720 = 10극","틀린 값입니다."],"t":"P = 120f / N"},"2024-3-기관3-15":{"w":"축전지 용량은 암페어시[Ah]로 나타냅니다.","x":["피상전력 단위입니다.","정답. [Ah]","무효전력 단위입니다.","전류 단위입니다."],"t":"축전지 = Ah"},"2024-3-기관3-16":{"w":"Ns = 120 × 60 ÷ 6 = 1,200[rpm]. N = Ns × (1 − s) = 1,200 × 0.96 = 1,152[rpm]입니다.","x":["틀린 값입니다.","8극일 때의 값입니다.","동기속도입니다.","정답. 1,200 × 0.96 = 1,152[rpm]"],"t":"N = Ns(1 − s)"},"2024-3-기관3-17":{"w":"납축전지는 충전하면 전해액(황산)의 비중과 전압이 모두 올라가고, 방전하면 둘 다 내려갑니다.","x":["충전 시 비중도 올라갑니다.","정답. 충전 시 비중·전압 모두 상승","방전 시 비중은 내려갑니다.","방전 시 전압은 내려갑니다."],"t":"비중으로 충전 상태 확인"},"2024-3-기관3-19":{"w":"A, B가 모두 1일 때만 X가 0이므로 NAND 게이트(㉯)입니다.","x":["AND입니다.","정답. NAND","OR입니다.","NOR입니다."],"t":"둘 다 1일 때만 0 = NAND"},"2024-3-기관3-20":{"w":"D자 모양(평평한 입력쪽, 둥근 출력쪽)이고 동그라미가 없으므로 AND 게이트입니다.","x":["NAND는 동그라미가 붙습니다.","NOR는 OR 모양 + 동그라미입니다.","OR는 방패 모양입니다.","정답. AND"],"t":"D자 = AND, 방패 = OR"},"2024-3-기관3-25":{"w":"스위치 A와 B가 병렬로 연결되어 둘 중 하나만 닫혀도 X가 동작하므로 OR 회로, X = A + B 입니다.","x":["직렬 연결(AND)입니다.","정답. 병렬 = OR = A + B","NAND입니다.","NOR입니다."],"t":"병렬 스위치 = OR, 직렬 = AND"},"2024-3-기관3-23":{"w":"서미스터는 온도에 따라 저항이 크게 변해 온도 검출에 씁니다.","x":["사이리스터는 전력 스위칭 소자입니다.","정답. 서미스터","배리스터는 전압에 따라 저항이 변합니다.","포토 트랜지스터는 빛을 검출합니다."],"t":"온도 = 서미스터"},"2024-3-기관3-24":{"w":"역방향 전압이 항복전압 이상이 되면 도통하는 다이오드는 제너 다이오드입니다.","x":["포토 다이오드는 빛을 검출합니다.","정답. 제너 다이오드","LED는 빛을 냅니다.","터널 다이오드는 부성저항 특성을 씁니다."],"t":"역방향 항복 = 제너"},"2024-3-직무일반-2":{"w":"적요일지(Abstract log)는 매 항차가 끝날 때 기관일지를 바탕으로 기관 상태, 유류 소모량 등을 요약한 서류입니다.","x":["기관장 일지가 아닙니다.","정오보고서는 매일 정오의 상태 보고입니다.","정답. 적요일지","입·출항 보고서가 아닙니다."],"t":"적요일지 = 항차 요약"},"2024-3-직무일반-3":{"w":"추운 곳에서는 기관실 온도가 너무 내려가지 않게 하고, 주기관을 데워 두며, 냉각수를 계속 순환시켜 동결을 막아야 합니다. 냉각수 사용을 줄이면 오히려 얼 수 있습니다.","x":["워밍 상태를 유지합니다.","기관실 온도에 주의합니다.","발전기 압력·온도에 주의합니다.","정답(아닌 것). 냉각수는 순환시켜야 얼지 않습니다."],"t":"동결 방지 = 순환 유지·보온"},"2024-3-직무일반-4":{"w":"스톱밸브(글로브·앵글밸브)는 작동이 확실하고 밀착이 좋아 기관실에 많이 쓰이지만, 유체가 S자로 꺾여 흐르므로 완전히 열어도 저항(에너지 손실)이 큽니다. 손실이 가장 적은 것은 게이트(슬루스)밸브입니다.","x":["기관실에 많이 씁니다.","작동이 확실합니다.","글러브·앵글밸브로 나뉩니다.","정답(옳지 않은 것). 스톱밸브는 손실이 큰 편입니다."],"t":"손실 최소 = 게이트밸브"},"2024-3-직무일반-5":{"w":"그림처럼 머리가 둥근 고리 모양인 볼트는 아이볼트로, 무거운 부품을 들어 올릴 때 씁니다.","x":["스터드볼트는 양쪽이 나사인 볼트입니다.","육각볼트는 머리가 육각입니다.","타이볼트는 긴 연결 볼트입니다.","정답. 아이볼트"],"t":"아이볼트 = 인양용 고리"},"2024-3-직무일반-7":{"w":"폐기물기록부는 총톤수 400톤 이상 선박(그리고 최대 승선인원 15명 이상 선박)이 비치해야 합니다.","x":["틀립니다.","틀립니다.","틀립니다.","정답. 400톤 이상"],"t":"폐기물기록부 = 400톤↑ 또는 15인↑"},"2024-3-직무일반-8":{"w":"유성찌꺼기는 소각, 저장, 육상 양륙으로 처리합니다. 청정기 비중판 교환은 처리 방법이 아닙니다.","x":["소각할 수 있습니다.","정답(옳지 않은 것). 비중판 교환은 처리 방법이 아닙니다.","저장할 수 있습니다.","양륙할 수 있습니다."],"t":"유성찌꺼기 = 소각·저장·양륙"},"2024-3-직무일반-9":{"w":"선박오염물질기록부는 기름기록부, 유해액체물질기록부, 폐기물기록부입니다. 오존층파괴물질기록부는 대기오염 관련 기록부로 따로 분류됩니다.","x":["선박오염물질기록부입니다.","정답(아닌 것). 오존층파괴물질기록부","선박오염물질기록부입니다.","선박오염물질기록부입니다."],"t":"오염물질기록부 = 기름·유해액체·폐기물"},"2024-3-직무일반-10":{"w":"마쇄·소독하지 않은 분뇨는 영해 기선에서 12해리를 넘는 곳에서 4노트 이상으로 항해하며 서서히 배출해야 합니다. (마쇄·소독한 것은 3해리 이상)","x":["3해리는 마쇄·소독한 분뇨의 기준입니다.","3해리는 마쇄·소독한 분뇨의 기준입니다.","속력이 부족합니다.","정답. 12해리, 4노트 이상"],"t":"미처리 분뇨 = 12해리·4노트"},"2024-3-직무일반-11":{"w":"찰과상은 피부나 점막이 마찰로 긁혀 손상된 상처입니다.","x":["자상(찔린 상처)입니다.","정답. 마찰로 긁힌 상처","절상(베인 상처)입니다.","열상(찢어진 상처)입니다."],"t":"찰과상 = 긁힘"},"2024-3-직무일반-13":{"w":"1도 동상은 피부가 창백하고 감각이 둔하며 찌르는 통증이 있고, 따뜻해지면 몹시 가렵고 붉어집니다. 2도는 물집, 3도는 조직 괴사입니다.","x":["정답. 1도 동상","2도는 물집이 생깁니다.","3도는 조직이 괴사합니다.","4도는 뼈까지 손상됩니다."],"t":"동상 1도 창백·가려움, 2도 물집, 3도 괴사"},"2024-3-직무일반-14":{"w":"주기관이 운전 불능이 되면 배의 조종에 직접 영향이 있으므로 가장 먼저 선교 당직사관에게 알려야 합니다.","x":["선장·선교가 판단합니다.","선교가 합니다.","정답. 선교에 즉시 연락","보고는 선교를 통해 합니다."],"t":"주기관 이상 = 선교에 먼저"},"2024-3-직무일반-17":{"w":"정전 후 예비 발전기가 투입되면 순차 기동 프로그램으로 추진에 필요한 선미관 윤활유 펌프 등이 자동 기동됩니다. 빌지·소화·슬러지 펌프는 수동 운전합니다.","x":["수동으로 운전합니다.","수동으로 운전합니다.","수동으로 운전합니다.","정답. 선미관 윤활유 펌프"],"t":"순차 기동 = 추진 필수 펌프"},"2024-3-직무일반-18":{"w":"보상식 화재탐지기는 정온식(일정 온도 도달)과 차동식(급격한 온도 상승)을 합친 것으로, 둘 중 하나만 만족해도 작동합니다.","x":["정온식은 일정 온도에서만 작동합니다.","광전자식은 연기를 감지합니다.","차동식은 온도 상승률로만 작동합니다.","정답. 보상식"],"t":"보상식 = 정온식 + 차동식"},"2024-3-직무일반-19":{"w":"연기탐지기 사이의 최대 거리는 11[m], 열탐지기는 9[m]입니다.","x":["틀립니다.","열탐지기 기준입니다.","정답. 11[m]","틀립니다."],"t":"연기 11m, 열 9m"},"2024-3-직무일반-22":{"w":"선박법은 국적·톤수 측정·등록을 정해 해상 질서 유지와 국민 경제 향상에 기여하는 법입니다. 감항성 유지는 선박안전법의 목적입니다.","x":["해상 질서 유지는 선박법 목적입니다.","정답(옳지 않은 것). 감항성은 선박안전법입니다.","국민 경제 향상은 선박법 목적입니다.","톤수 측정·등록은 선박법 내용입니다."],"t":"감항성 = 선박안전법"},"2024-3-직무일반-23":{"w":"선박을 등기한 뒤 지방해양수산청장에게 등록하면 선박국적증서를 발급받습니다.","x":["임시항해인가증이 아닙니다.","정답. 선박국적증서","재화중량톤수 증서가 아닙니다.","검사증서는 검사 후 받습니다."],"t":"등록 = 국적증서"},"2024-3-직무일반-24":{"w":"선박검사증서의 유효기간은 5년입니다.","x":["틀립니다.","틀립니다.","틀립니다.","정답. 5년"],"t":"선박검사증서 5년"},"2024-3-직무일반-25":{"w":"특별해역 밖에서 운항하는 400톤 이상 1만톤 미만 선박의 기관구역에는 배출관장치, 유성찌꺼기탱크, 기름여과장치(15ppm)를 설치합니다. 선저폐수농도경보장치는 1만톤 이상 선박 등에 필요합니다.","x":["설치합니다.","설치합니다.","설치합니다.","정답(아닌 것). 경보장치는 1만톤 이상입니다."],"t":"경보장치(15ppm 알람) = 1만톤 이상"},"2024-3-영어-1":{"w":"연료 수급 중 기름 유출 위험이 가장 큰 때는 탱크를 가득 채우는 마지막 단계(topped off)입니다.","x":["시작할 때가 아닙니다.","정답. topped off = 가득 채울 때","멈춘 뒤가 아닙니다.","시작 전이 아닙니다."],"t":"topping off = 가장 위험"},"2024-3-영어-2":{"w":"저온경보 = TAL(Temperature Alarm Low)입니다. H = High, P = Pressure.","x":["정답. TAL = 저온 경보","TAH = 고온 경보","PAL = 저압 경보","PAH = 고압 경보"],"t":"T온도·P압력, L저·H고"},"2024-3-영어-3":{"w":"\"검사를 위해 추력 베어링을 개방 점검하고, 추력 패드 간극을 확인·조정할 것.\"","x":["중간축이 아닙니다.","교환이 아니라 조정입니다.","정답. 추력 베어링 개방 점검","중간축이 아닙니다."],"t":"overhaul = 개방 정비"},"2024-3-영어-4":{"w":"그림은 사람들이 가운데로 모이는 표시로 비상 집합 장소(Muster station)입니다.","x":["연료 수급 장소가 아닙니다.","정답. Muster station = 집합 장소","소화 통제실이 아닙니다.","비상 탈출구가 아닙니다."],"t":"muster = 집합"},"2024-3-영어-5":{"w":"힘의 단위는 뉴턴(Newton)입니다.","x":["Joule은 일·에너지 단위입니다.","정답. Newton","Watt는 일률 단위입니다.","Horsepower는 마력입니다."],"t":"힘 N, 에너지 J, 일률 W"},"2024-3-영어-6":{"w":"비상탈출호흡구 = EEBD(Emergency Escape Breathing Device)입니다.","x":["EEDI = 에너지효율설계지수","틀립니다.","틀립니다.","정답. EEBD"],"t":"EEBD = 비상탈출호흡구"},"2024-3-영어-8":{"w":"저압(L.P.)·고압(H.P.) 피스톤 패킹링이 있는 기기는 2단 공기압축기(Air compressor)입니다.","x":["빌지펌프가 아닙니다.","발전기관이 아닙니다.","정답. Air compressor","조수기가 아닙니다."],"t":"L.P./H.P. 피스톤 = 2단 압축기"},"2024-3-영어-9":{"w":"automatic fire detecting system = 자동화재탐지장치 입니다.","x":["경보는 alarm입니다.","차단이 아닙니다.","정답. 자동화재탐지장치","소화는 extinguishing입니다."],"t":"detect = 탐지"},"2024-3-영어-11":{"w":"\"주기관 섬프 탱크 바닥의 기름을 퍼내고(bail) 내부를 청소했다.\"","x":["Examined = 검사했다","Started = 시작했다","Supplied = 공급했다","정답. Bailed = 퍼냈다"],"t":"bail out = 퍼내다"},"2024-3-영어-12":{"w":"\"검사관의 내부 검사를 위해 연료유 탱크를 가스 프리(gasfreed)하고 청소할 것.\"","x":["filled = 채운","changed = 바꾼","정답. gasfreed = 가스 제거","supplied = 공급한"],"t":"gas free = 가스 제거"},"2024-3-영어-13":{"w":"육전 = shore electricity(육상 전원)입니다.","x":["electronics는 전자기기입니다.","틀립니다.","정답. Shore electricity","선내 전원입니다."],"t":"shore power = 육전"},"2024-3-영어-14":{"w":"\"주기관 섬프 탱크에 시스템유 500리터를 보충했다.\" replenish = 보충하다.","x":["Started = 시작했다","정답. Replenished = 보충했다","Removed = 제거했다","Discharged = 배출했다"],"t":"replenish = 보충"},"2024-3-영어-16":{"w":"해수 밸브에는 개폐와 유량 조절이 확실한 글로브 밸브(Globe valve)가 가장 적합합니다.","x":["정답. Globe valve","전자밸브는 해수 밸브로 적합하지 않습니다.","볼 밸브는 정답이 아닙니다.","니들 밸브는 미세 유량용입니다."],"t":"해수 = 글로브 밸브"},"2024-3-영어-17":{"w":"갑판보기의 주 구동 방식은 공기압(pneumatic), 전기(electric), 유압(hydraulic)입니다.","x":["정답. pneumatic, electric","가스가 아닙니다.","가스가 아닙니다.","중력이 아닙니다."],"t":"갑판보기 = 공기압·전기·유압"},"2024-3-영어-19":{"w":"reservoirs = 저장 용기, 여기서는 공기탱크(시동 공기 저장조)입니다.","x":["압축기는 compressor입니다.","냉각기는 cooler입니다.","안전밸브는 safety valve입니다.","정답. 공기탱크"],"t":"air reservoir = 공기탱크"},"2024-3-영어-22":{"w":"기관실이 침수(flooded)되면 비상 빌지 배출 장치를 사용합니다.","x":["화재 시가 아닙니다.","정답. flooded = 침수","기름이 찬 경우가 아닙니다.","틀립니다."],"t":"flooded = 침수"},"2024-3-영어-23":{"w":"선박의 냉각기는 대부분 뜨거운 유체의 열(heat)을 해수나 청수로 옮깁니다.","x":["공기가 아닙니다.","물이 아닙니다.","정답. heat = 열","압력이 아닙니다."],"t":"cooler = heat transfer"},"2024-3-영어-24":{"w":"흡·배기밸브가 모두 닫히고 피스톤이 올라가며 공기를 압축해 온도가 높아지는 것은 압축행정입니다.","x":["배기행정은 배기밸브가 열립니다.","팽창행정은 피스톤이 내려갑니다.","흡입행정은 흡기밸브가 열립니다.","정답. Compression stroke"],"t":"밸브 닫힘 + 피스톤 상승 = 압축"},"2024-4-기관1-1":{"w":"디젤 연소 4단계는 제1과정 착화지연, 제2과정 급격(무제어) 연소, 제3과정 제어 연소, 제4과정 후연소입니다. 착화 후 급격히 연소하는 것은 제2과정입니다.","x":["제1과정은 착화지연 기간입니다.","정답. 제2과정 = 급격 연소","제3과정은 제어 연소입니다.","제4과정은 후연소입니다."],"t":"착화지연 → 급격연소 → 제어연소 → 후연소"},"2024-4-기관1-4":{"w":"압축비 = (행정용적 + 압축용적) ÷ 압축용적 = (200 + 20) ÷ 20 = 11입니다.","x":["행정용적 ÷ 압축용적만 한 값입니다.","정답. 220 ÷ 20 = 11","틀린 값입니다.","틀린 값입니다."],"t":"ε = (Vs + Vc) / Vc"},"2024-4-기관1-6":{"w":"크랭크암 개폐작용(디플렉션)은 메인 베어링의 불균일한 마멸, 기관 베드 변형, 크랭크축 중심 어긋남 등으로 생깁니다. 피스톤핀 베어링 틈새는 관계가 없습니다.","x":["메인 베어링 편마멸은 원인입니다.","베드 변형은 원인입니다.","정답(아닌 것). 피스톤핀 베어링은 관계없습니다.","중심 어긋남은 원인입니다."],"t":"디플렉션 = 메인 베어링·베드·축심"},"2024-4-기관1-8":{"w":"연접봉을 길게 하면 경사 각도가 작아져 측압과 라이너 마멸이 줄지만, 기관의 높이가 높아집니다.","x":["경사 각도는 작아집니다.","측압은 작아집니다.","정답. 기관 높이가 높아집니다.","마멸은 줄어듭니다."],"t":"연접봉 길게 = 측압↓, 높이↑"},"2024-4-기관1-9":{"w":"과급하면 더 많은 공기를 넣어 출력이 늘고, 마력당 무게가 줄며, 기계효율이 좋아지고, 연료 소비율은 줄어듭니다.","x":["출력이 늘어납니다.","마력당 중량이 줄어듭니다.","정답(아닌 것). 연료 소비율은 감소합니다.","기계효율이 늘어납니다."],"t":"과급 = 출력↑, 연료 소비율↓"},"2024-4-기관1-10":{"w":"지시마력은 강스프링으로 그린 PV 선도(압력-부피 선도)의 면적으로 평균유효압력을 구해 계산합니다.","x":["정답. PV 선도","수인 선도는 연소 상태를 봅니다.","최고압력 선도가 아닙니다.","약스프링 선도는 흡·배기 상태를 봅니다."],"t":"지시마력 = PV 선도 면적"},"2024-4-기관1-12":{"w":"수면계에 수위가 보이지 않으면 저수위일 수 있으므로 즉시 버너를 끄고 주증기 밸브를 닫습니다. 수저 방출을 하면 물이 더 줄어 위험합니다.","x":["급수 역지 밸브를 닫습니다(찬물 급수 금지).","버너를 끕니다.","주증기 밸브를 닫습니다.","정답(옳지 않은 것). 수저 방출은 하면 안 됩니다."],"t":"수위 불명 = 소화·증기 차단, 급수·방출 금지"},"2024-4-기관1-14":{"w":"재생터빈은 팽창 중간에 증기 일부를 뽑아(추기) 급수를 가열함으로써 복수기에서 버려지는 열을 줄여 열효율을 높입니다.","x":["정답. 재생터빈","추기터빈은 뽑은 증기를 다른 용도(가열 등)에 씁니다.","배압터빈은 배기를 대기압 이상으로 사용합니다.","복수터빈은 배기를 복수기로 보냅니다."],"t":"재생 = 추기로 급수 가열"},"2024-4-기관1-15":{"w":"공기 이젝터는 증기 분사로 복수기 속의 공기 등 불응축 가스를 계속 뽑아내 진공을 유지합니다.","x":["정답. 공기 이젝터","공기 분리기가 아닙니다.","해당하지 않습니다.","해당하지 않습니다."],"t":"복수기 진공 유지 = 공기 이젝터"},"2024-4-기관1-17":{"w":"선미관은 프로펠러축이 선체를 관통하는 곳에서 해수 침입을 막고 축의 베어링 역할을 합니다.","x":["정답. 선미관","중간축 베어링은 선내에 있습니다.","관계없습니다.","추력 베어링은 추력을 전달합니다."],"t":"선미관 = 해수 차단 + 베어링"},"2024-4-기관1-19":{"w":"가변 피치 프로펠러(CPP)는 기관을 일정 회전수로 돌리면서 날개 각도로 속력·전후진을 바꿉니다. 저속 항해가 쉽고 비틀림 진동이 작습니다. 날개 각도를 바꾸는 피치 제어장치(역전 제어장치)는 반드시 필요합니다.","x":["저속 항해가 쉽습니다.","일정 회전속도로 운전합니다.","정답(옳지 않은 것). 피치 제어장치가 필요합니다.","비틀림 진동이 작습니다."],"t":"CPP = 기관 일정 회전, 날개 각도로 조종"},"2024-4-기관1-21":{"w":"원심 청정은 기름을 가열해 점도를 낮추고, 유량을 적게 해 기름이 청정기 안에 오래 머물게 하면 분리 효과가 좋아집니다.","x":["점도가 높으면 분리가 나쁩니다.","유량이 많으면 분리가 나쁩니다.","정답. 점도 낮게, 유량 적게","둘 다 반대입니다."],"t":"청정 = 가열(저점도) + 저유량"},"2024-4-기관1-22":{"w":"연소하면 황산화물, 질소산화물, 매연(입자상 물질) 등이 직접 나옵니다. 오존은 대기 중에서 광화학 반응으로 생기는 2차 오염물질입니다.","x":["정답(아닌 것). 오존은 연소에서 직접 나오지 않습니다.","연소에서 직접 나옵니다.","연소에서 직접 나옵니다.","연소에서 직접 나옵니다."],"t":"오존 = 2차 생성물"},"2024-4-기관1-23":{"w":"파라핀계 원유는 점도지수가 크고 산화 안정성이 좋아 윤활유 원료로 적합합니다.","x":["정답. 파라핀계","나프텐계는 점도지수가 작습니다.","올레핀계는 불안정합니다.","혼합계는 가장 적당하지 않습니다."],"t":"윤활유 원료 = 파라핀계"},"2024-4-기관1-24":{"w":"윤활유가 산화·열화되면 산성 물질이 생겨 산값(전산가)이 올라가므로, 산값으로 열화 정도를 판단합니다.","x":["수분은 따로 측정합니다.","오탁도는 따로 봅니다.","점도는 따로 측정합니다.","정답. 산값 = 열화 정도"],"t":"산값↑ = 열화"},"2024-4-기관2-1":{"w":"캐비테이션이 생기면 블레이드(날개)가 침식되고, 송출압력과 효율이 떨어지며, 소음·진동이 생깁니다. 마우스링 부식과는 직접 관계가 없습니다.","x":["날개가 침식됩니다.","송출압력이 낮아집니다.","효율이 떨어집니다.","정답(옳지 않은 것). 마우스링 부식과 관계없습니다."],"t":"캐비테이션 = 침식·압력↓·효율↓·소음"},"2024-4-기관2-2":{"w":"속이 빈 삼각형(공기압)이 원 안쪽을 향하는(모터) 기호가 공기압 모터입니다.","x":["공기압 모터 기호가 아닙니다.","공기압 모터 기호가 아닙니다.","공기압 모터 기호가 아닙니다.","정답. 빈 삼각형 + 안쪽"],"t":"빈 삼각형 = 공기압, 안쪽 = 모터"},"2024-4-기관2-3":{"w":"기름을 가열하면 점도가 낮아져 고형분(불순물)이 잘 가라앉아 분리됩니다. 유황은 기름에 녹아 있어 청정기로 분리되지 않습니다.","x":["유황은 분리되지 않습니다.","정답. 점도↓ → 고형분 분리 용이","유화물 분리는 주된 효과가 아닙니다.","유황은 분리되지 않습니다."],"t":"청정기로 유황은 못 뺀다"},"2024-4-기관2-4":{"w":"갑판 유압기기는 유압펌프 1대로 여러 대의 유압모터(윈치 등)를 구동할 수 있습니다.","x":["개수 제한이 없습니다.","같을 필요가 없습니다.","정답. 펌프 1대로 여러 모터 구동","펌프 없이 모터만으로는 안 됩니다."],"t":"유압 = 펌프 1대 → 모터 여러 대"},"2024-4-기관2-7":{"w":"집 크레인, 카고 윈치, 데릭은 화물을 싣고 내리는 하역 설비입니다. 캡스턴은 계선줄을 감는 계선 설비입니다.","x":["정답(용도가 다른 것). 캡스턴 = 계선용","하역용입니다.","하역용입니다.","하역용입니다."],"t":"캡스턴 = 계선"},"2024-4-기관2-8":{"w":"기름을 잘 분리하려면 기름 입자를 크게 하고, 부상 거리를 짧게, 부상 속도를 빠르게, 경계면을 넓게 해야 합니다. 입자가 작으면 잘 떠오르지 않습니다.","x":["정답(옳지 않은 것). 입자는 크게 해야 합니다.","부상 거리가 짧으면 좋습니다.","부상 속도가 빠르면 좋습니다.","경계면이 넓으면 좋습니다."],"t":"기름 입자 = 클수록 잘 분리"},"2024-4-기관2-9":{"w":"선저폐수를 선외로 배출하려면 기름여과장치(15ppm)가 필요합니다.","x":["정답. 기름여과장치","유청정장치는 연료·윤활유용입니다.","오수처리장치는 분뇨용입니다.","폐유소각장치는 슬러지용입니다."],"t":"빌지 배출 = 기름여과장치"},"2024-4-기관2-10":{"w":"배기가스 이젝터는 배기를 빨아내 화로 안을 대기압보다 약간 낮은 부압으로 유지해 불꽃이 새지 않고 안정되게 연소하게 합니다.","x":["공기실이 아닙니다.","신축 커플링이 아닙니다.","교반기는 폐유를 섞습니다.","정답. 배기가스 이젝터"],"t":"화로 부압 = 배기가스 이젝터"},"2024-4-기관2-11":{"w":"방식 아연판은 해수가 흐르는 응축기 냉각수 측에 설치해 전식을 막습니다.","x":["정답. 응축기 냉각수측","증발기 외부가 아닙니다.","크랭크 케이스가 아닙니다.","냉매측이 아닙니다."],"t":"아연판 = 해수 쪽"},"2024-4-기관2-12":{"w":"압축비가 너무 높으면 토출가스 온도가 올라가고, 냉동능력과 성적계수가 떨어지며, 윤활유가 빨리 열화됩니다.","x":["냉동능력이 감소합니다.","정답(옳지 않은 것). 토출가스 온도는 높아집니다.","성적계수가 떨어집니다.","윤활유 열화가 빨라집니다."],"t":"압축비↑ = 토출온도↑, 능력↓"},"2024-4-기관2-14":{"w":"증발기에 끼는 서리는 냉장고(냉동실) 안 공기 속의 수분이 차가운 증발기 표면에 얼어붙은 것입니다.","x":["냉매 속 수분은 팽창밸브를 막히게 합니다.","정답. 냉장고 안 수분이 얼어붙은 것","냉매는 얼지 않습니다.","냉각수와 관계없습니다."],"t":"서리 = 고내 수분"},"2024-4-기관2-15":{"w":"2중 덕트 방식은 찬 공기와 따뜻한 공기를 두 개의 덕트로 보내 선실의 혼합상자에서 섞는 비율로 온도를 조절합니다.","x":["재열 방식은 말단에서 다시 가열합니다.","유인 방식은 1차 공기로 실내 공기를 유인합니다.","정답. 2중 덕트 방식","중앙 방식은 일반적인 용어입니다."],"t":"2중 덕트 = 냉·온풍 혼합"},"2024-4-기관2-17":{"w":"실린더 라이너 마멸량은 안지름을 재야 하므로 내경 마이크로미터(실린더 게이지)를 씁니다.","x":["한계 게이지는 합격 여부만 봅니다.","버니어 캘리퍼스는 정밀도가 부족합니다.","틈새 게이지는 틈을 잽니다.","정답. 내경 마이크로미터"],"t":"라이너 마멸 = 내경 마이크로미터"},"2024-4-기관2-18":{"w":"수나사는 다이스로, 암나사는 탭으로 가공합니다.","x":["탭은 암나사입니다.","정답. 다이스 = 수나사","줄은 다듬질용입니다.","밀링은 나사 가공에 일반적이지 않습니다."],"t":"다이스 = 수나사, 탭 = 암나사"},"2024-4-기관2-19":{"w":"바이트는 자루를 수평으로, 끝 높이를 일감 중심에 맞추고, 돌출 길이는 짧게 고정합니다. 받침 심은 되도록 적게(한두 장) 써야 흔들리지 않습니다.","x":["수평으로 고정합니다.","정답(옳지 않은 것). 심은 적게 받칩니다.","중심 높이를 맞춥니다.","짧게 고정합니다."],"t":"바이트 = 짧게·수평·중심 높이"},"2024-4-기관2-20":{"w":"가스가 새면 즉시 용기 밸브를 잠급니다. 불꽃으로 확인하면 안 되며, 산소 계통의 기름은 매우 위험합니다.","x":["정답. 즉시 용기 밸브 잠금","촛불은 폭발 위험이 있습니다.","산소와 기름은 폭발적으로 탑니다.","조정기를 시계방향으로 돌리면 오히려 열립니다."],"t":"누설 = 용기 밸브 즉시 잠금"},"2024-4-기관2-21":{"w":"피크 탱크(선수·선미 탱크)는 트림 조정, 선수 손상 시 침수 범위 한정, 선미 진동 완화 등에 쓰입니다. 모양이 좁고 복잡해 화물창으로 쓰지 않습니다.","x":["트림 조정에 씁니다.","침수 범위를 한정합니다.","정답(옳지 않은 것). 화물창으로 쓰지 않습니다.","진동을 완화합니다."],"t":"피크 탱크 = 밸러스트·트림용"},"2024-4-기관2-22":{"w":"수면 아래 선체 부피만큼의 해수 무게를 배수톤수라 합니다(선박의 실제 무게).","x":["순톤수는 적재 용적입니다.","정답. 배수톤수","총톤수는 전체 용적입니다.","운하톤수는 운하 통과용입니다."],"t":"배수톤수 = 배의 무게"},"2024-4-기관3-1":{"w":"저항만 있는 회로에서는 전압과 전류의 위상이 같습니다.","x":["정답. 저항성 회로","유도성은 전류가 늦습니다.","용량성은 전류가 빠릅니다.","RL은 전류가 늦습니다."],"t":"R = 위상 같음"},"2024-4-기관3-2":{"w":"용량 리액턴스 XC = 1/(2πfC)이므로 정전용량 C가 커지면 XC는 작아집니다.","x":["반대입니다.","정답. 작아집니다.","변합니다.","틀립니다."],"t":"XC ∝ 1/C"},"2024-4-기관3-4":{"w":"피상전력 = EI [VA]입니다.","x":["정답. EI","무효전력입니다.","해당 없음","유효전력입니다."],"t":"피상 EI"},"2024-4-기관3-7":{"w":"사인파의 최대값 Em = √2 × 실효값 E 입니다.","x":["실효값입니다.","틀립니다.","정답. √2 E","틀립니다."],"t":"Em = √2 E"},"2024-4-기관3-8":{"w":"△결선에서 선전류는 상전류의 √3배, 상전압과 선간전압은 같습니다.","x":["반대입니다.","정답. 선전류 = √3 상전류","Y결선입니다.","틀립니다."],"t":"△ = 전류 √3배"},"2024-4-기관3-9":{"w":"합성저항 10 × 3 = 30[Ω], I = 120 ÷ 30 = 4[A]입니다.","x":["틀린 값입니다.","틀린 값입니다.","정답. 120 ÷ 30 = 4[A]","틀린 값입니다."],"t":"직렬 = 저항 합"},"2024-4-기관3-10":{"w":"푸시 버튼 접점은 접점 위에 T자 누름대가 있는 기호입니다.","x":["한시 접점입니다.","일반 스위치입니다.","다른 접점입니다.","정답. T자 = 푸시 버튼"],"t":"푸시 버튼 = T자"},"2024-4-기관3-11":{"w":"OCR(Over Current Relay, 과전류 계전기)은 정해진 값 이상의 전류가 흐르면 동작합니다.","x":["PT는 계기용 변압기입니다.","CT는 계기용 변류기입니다.","정답. OCR","RPR은 역전력 계전기입니다."],"t":"OCR = 과전류"},"2024-4-기관3-13":{"w":"납축전지는 충전 중 물이 분해되어 가스로 나가고 증발도 하므로 물만 줄어듭니다. 그래서 황산이 아니라 증류수를 보충합니다.","x":["전해액은 묽은 황산입니다.","폭발 방지가 목적이 아닙니다.","열 억제가 목적이 아닙니다.","정답. 물만 손실되므로"],"t":"전해액 부족 = 증류수 보충"},"2024-4-기관3-14":{"w":"주파수가 낮아지면 동기속도가 줄어 회전속도가 감소하고, 전압이 같으면 자속이 늘어 여자전류가 커지므로 전류는 증가합니다.","x":["정답. 속도↓, 전류↑","반대입니다.","전류는 증가합니다.","속도는 감소합니다."],"t":"주파수↓ → 속도↓·전류↑"},"2024-4-기관3-15":{"w":"발전기 유도기전력 E ∝ 자속 × 회전속도 입니다.","x":["정답. 자속과 회전속도","전기자저항은 전압강하에 관계됩니다.","외부 온도는 관계없습니다.","직렬 저항은 관계없습니다."],"t":"E = kΦN"},"2024-4-기관3-16":{"w":"직입 기동하는 유도전동기의 기동전류는 전부하 전류의 약 5~8배입니다.","x":["너무 작습니다.","정답. 약 5~8배","너무 큽니다.","너무 큽니다."],"t":"직입 기동전류 ≒ 정격의 5~8배"},"2024-4-기관3-17":{"w":"Ns = 120 × 60 ÷ 6 = 1,200[rpm], N = 1,200 × (1 − 0.05) = 1,140[rpm]입니다.","x":["동기속도입니다.","정답. 1,140[rpm]","틀린 값입니다.","틀린 값입니다."],"t":"N = Ns(1 − s)"},"2024-4-기관3-18":{"w":"싱크로스코프(동기검정기)는 병렬운전 시 투입할 발전기가 빠른지(FAST) 느린지(SLOW) 보여 줍니다.","x":["ACB는 차단기입니다.","정답. 싱크로스코프","주파수계는 FAST/SLOW 표시가 없습니다.","거버너 스위치는 RAISE/LOWER입니다."],"t":"FAST/SLOW = 싱크로스코프"},"2024-4-기관3-19":{"w":"입력 A가 1이면 트랜지스터가 켜져 X가 접지(0)되고, A가 0이면 트랜지스터가 꺼져 X는 5V(1)가 됩니다. 입력을 반전하는 NOT 회로입니다.","x":["틀립니다.","정답. A = 1 → X = 0, A = 0 → X = 1 (NOT)","버퍼입니다.","틀립니다."],"t":"트랜지스터 스위치 = NOT"},"2024-4-기관3-23":{"w":"SCR은 애노드에 (+), 캐소드에 (−)를 걸고 게이트에 트리거 신호를 주면 도통됩니다. 한 번 도통하면 게이트 신호를 없애도 유지됩니다.","x":["정답. A(+), K(−) + 게이트 트리거 → 도통","도통 상태가 됩니다.","역방향이면 도통하지 않습니다.","틀립니다."],"t":"SCR = 순방향 + 게이트 → ON"},"2024-4-기관3-24":{"w":"온도가 오르면 저항이 작아지는(NTC) 서미스터를 온도 측정·보상에 씁니다.","x":["SCR은 스위칭 소자입니다.","정답. 서미스터","FET는 트랜지스터입니다.","배리스터는 전압용입니다."],"t":"서미스터 = 온도"},"2024-4-기관3-25":{"w":"이미터 화살표가 바깥쪽(E 쪽)을 향하면 NPN 트랜지스터입니다. 안쪽을 향하면 PNP입니다.","x":["UJT가 아닙니다.","PNP는 화살표가 안쪽입니다.","FET가 아닙니다.","정답. 화살표 밖 = NPN"],"t":"NPN = Not Pointing iN(화살표 밖)"},"2024-4-직무일반-1":{"w":"유인 당직 중 보조기기의 주요 사항은 당직기관사가 직접 기관일지에 기록해야 합니다.","x":["기관실을 벗어나지 않습니다.","선교 지시는 즉시 이행하고 기록합니다.","정답(옳지 않은 것). 당직기관사가 직접 기록합니다.","경보 시 즉시 내려갑니다."],"t":"기록 = 당직기관사 책임"},"2024-4-직무일반-2":{"w":"연료유 저장탱크를 청소할 때는 탱크 안의 유증기·유해가스 때문에 가스 중독 위험이 큽니다.","x":["추락 위험 작업입니다.","화상 위험 작업입니다.","정답. 연료유 탱크 소제","가스 중독 위험이 주가 아닙니다."],"t":"탱크 작업 = 가스 중독 주의"},"2024-4-직무일반-3":{"w":"그림은 양쪽 끝에 수나사가 있는 짧은 관인 니플입니다.","x":["티는 T자 모양입니다.","정답. 니플","소켓은 암나사 이음입니다.","엘보는 꺾인 모양입니다."],"t":"니플 = 양쪽 수나사"},"2024-4-직무일반-5":{"w":"운전 중인 전동기는 베어링 온도, 진동, 소음, 전류 등을 주기적으로 점검합니다. 회전 방향은 처음 운전할 때 확인합니다.","x":["정답(아닌 것). 회전 방향은 주기 점검 대상이 아닙니다.","점검합니다.","점검합니다.","점검합니다."],"t":"주기 점검 = 온도·진동·소음·전류"},"2024-4-직무일반-6":{"w":"총톤수 150톤 미만 유조선의 화물구역용 폐유저장용기는 최소 400[ℓ] 이상이어야 합니다.","x":["틀린 값입니다.","틀린 값입니다.","틀린 값입니다.","정답. 400[ℓ]"],"t":"150톤 미만 유조선 화물구역 = 400ℓ"},"2024-4-직무일반-7":{"w":"X류 물질은 해양에 배출되면 해양자원이나 인간의 건강에 심각한 위해를 끼치는 물질로 배출이 금지됩니다.","x":["Y류에 해당합니다.","정답. 심각한 위해 = X류","Z류에 해당합니다.","기타 물질입니다."],"t":"X 심각, Y 위해, Z 경미"},"2024-4-직무일반-12":{"w":"건강한 성인의 평상시 맥박은 1분에 약 60~80회입니다.","x":["너무 느립니다.","정답. 60~80회","빠릅니다.","너무 빠릅니다."],"t":"성인 맥박 60~80회/분"},"2024-4-직무일반-14":{"w":"선미관 윤활유 온도가 오르는 원인은 윤활유 열화, 순환량 부족, 냉각수 부족 등입니다. 후부 실링 균열은 해수 유입·기름 유출의 원인이지 온도 상승 원인이 아닙니다.","x":["열화는 원인입니다.","순환량 부족은 원인입니다.","정답(옳지 않은 것). 실링 균열은 누설 원인입니다.","냉각 부족은 원인입니다."],"t":"실링 불량 = 누설"},"2024-4-직무일반-16":{"w":"감통 운전(일부 실린더 연료 차단)을 하면 운전 중인 실린더의 부하가 불균형해 불완전 연소, 분무 불량, 열효율 저하가 생깁니다. 냉각수 온도 상승은 대표적인 문제점이 아닙니다.","x":["불완전 연소가 생깁니다.","분무가 나빠집니다.","정답(옳지 않은 것). 냉각수 온도 상승은 아닙니다.","열효율이 떨어집니다."],"t":"감통 운전 = 연소 불량·효율 저하"},"2024-4-직무일반-18":{"w":"연기탐지기 1개의 최대 담당 면적은 74[m²], 열탐지기는 37[m²]입니다.","x":["틀립니다.","열탐지기 기준입니다.","틀립니다.","정답. 74[m²]"],"t":"연기 74m², 열 37m²"},"2024-4-직무일반-19":{"w":"질식 소화는 산소 공급을 차단해 불을 끄는 방법입니다(CO₂, 포말, 덮개 등).","x":["정답. 산소 차단","냉각·점화원 제거입니다.","제거 소화입니다.","억제(부촉매) 소화입니다."],"t":"질식 = 산소 차단"},"2024-4-직무일반-23":{"w":"비상 신호(퇴선 제외)는 기적·사이렌으로 단음 7회 이상과 장음 1회로 합니다. 연속 3회 장음은 비상 신호가 아닙니다.","x":["여객선은 7일마다 합니다.","1/4 이상 교체 시 24시간 이내 실시합니다.","정답(옳지 않은 것). 비상 신호는 단음 7회 + 장음 1회입니다.","매월 1회 실시합니다."],"t":"비상신호 = 단음 7 + 장음 1"},"2024-4-직무일반-24":{"w":"폐기물기록부에는 폐기물의 해양 배출, 소각, 수용시설 배출 등을 기록합니다. 유성찌꺼기 처리는 기름기록부에 기록합니다.","x":["소각은 기록합니다.","해양 배출은 기록합니다.","수용시설 배출은 기록합니다.","정답(아닌 것). 기름기록부에 기록합니다."],"t":"유성찌꺼기 = 기름기록부"},"2024-4-직무일반-25":{"w":"선박해양오염비상계획서는 해양경찰청장의 검인을 받아 선박에 비치합니다.","x":["정답. 해양경찰청장","해양수산부장관이 아닙니다.","선급이 아닙니다.","지자체장이 아닙니다."],"t":"비상계획서 검인 = 해양경찰청장"},"2024-4-영어-2":{"w":"\"호스를 분리해도 됩니까?\" separate = 분리하다.","x":["정답. 분리해도 됩니까?","연결은 connect입니다.","상태를 묻는 문장이 아닙니다.","상태를 묻는 문장이 아닙니다."],"t":"separate = 분리, connect = 연결"},"2024-4-영어-3":{"w":"열교환기 = Heat exchanger 입니다.","x":["Economizer = 절탄기","Heat controller가 아닙니다.","Incinerator = 소각기","정답. Heat exchanger"],"t":"heat exchanger = 열교환기"},"2024-4-영어-4":{"w":"R.P.M. = Revolutions Per Minute(분당 회전수)입니다.","x":["정답. Revolutions Per Minute","틀립니다.","틀립니다.","틀립니다."],"t":"RPM = 분당 회전수"},"2024-4-영어-6":{"w":"Crankcase oil mist detector = 크랭크케이스 내 유증기(오일 미스트) 감지기입니다. 크랭크실 폭발을 막기 위해 설치합니다.","x":["압력 측정이 아닙니다.","회전속도 측정이 아닙니다.","정답. 유증기 감지기","소모량 감지가 아닙니다."],"t":"oil mist detector = 크랭크실 폭발 방지"},"2024-4-영어-7":{"w":"전류 = Electric current 입니다.","x":["Electrode = 전극","정답. Electric current","Electric charge = 전하","Electric resistance = 저항"],"t":"current = 전류"},"2024-4-영어-9":{"w":"muster = 소집하다. \"구명정 훈련을 위해 전 선원을 갑판에 소집했다.\"","x":["정답. 소집하였다","검사하였다가 아닙니다.","해산하였다가 아닙니다.","훈련하였다가 아닙니다."],"t":"muster = 소집"},"2024-4-영어-10":{"w":"transfer pump = 이송 펌프. Lubricating oil transfer pump = 윤활유 이송펌프.","x":["공급펌프는 supply pump입니다.","순환펌프는 circulating pump입니다.","청정펌프가 아닙니다.","정답. 윤활유 이송펌프"],"t":"transfer = 이송"},"2024-4-영어-11":{"w":"inspect(검사하다) ≒ check(점검하다).","x":["Adjusted = 조정했다","Regulated = 조절했다","정답. Checked = 점검했다","Found = 발견했다"],"t":"inspected ≒ checked"},"2024-4-영어-12":{"w":"R/up eng. = Rung up engine, 항해 속력으로 올려 정속(항해) 운전에 들어갔다는 뜻입니다.","x":["정답. 기관 정속 운전","감통 운전이 아닙니다.","운전 준비는 S/B입니다.","상태 양호가 아닙니다."],"t":"R/UP = 항해 정속, S/B = 준비, F.W.E. = 종료"},"2024-4-영어-13":{"w":"\"~할까요?\" = Shall we ~? \"Shall we start to transfer of H.F.O.?\"","x":["명령문입니다.","stop은 멈추다입니다.","check는 확인입니다.","정답. Shall we start ~?"],"t":"Shall we start ~?"},"2024-4-영어-15":{"w":"과급기는 배기가스(exhaust gas)로 돌아가는 가스터빈이 원심 송풍기를 돌리는 장치입니다.","x":["체인으로 구동하지 않습니다.","정답. exhaust gas","blower는 구동되는 쪽입니다.","압축공기로 구동하지 않습니다."],"t":"turbocharger = 배기가스 터빈"},"2024-4-영어-17":{"w":"배기밸브가 열리고 흡기밸브가 닫힌 채 피스톤이 올라가 연소가스를 밀어내는 것은 배기행정입니다.","x":["흡입행정은 흡기밸브가 열립니다.","정답. Exhaust stroke","작동행정은 피스톤이 내려갑니다.","압축행정은 밸브가 모두 닫힙니다."],"t":"배기밸브 열림 + 피스톤 상승 = 배기"},"2024-4-영어-18":{"w":"연관(smoke tubes), 노(furnace), 연돌 입구(uptake)를 청소하는 것은 보일러 정비입니다.","x":["정답. Boiler","주기관이 아닙니다.","소각기가 아닙니다.","발전기관이 아닙니다."],"t":"smoke tube·furnace = 보일러"},"2024-4-영어-19":{"w":"냉동기에서 온도와 압력이 모두 올라가는 곳은 압축기(compressor)입니다.","x":["정답. compressor","증발기는 저온·저압입니다.","응축기는 압력 유지, 온도 하강입니다.","팽창밸브는 압력이 내려갑니다."],"t":"compressor = 온도·압력 상승"},"2024-4-영어-20":{"w":"상사점(TDC)과 하사점(BDC) 사이의 거리는 행정(stroke)입니다.","x":["정답. stroke","clearance = 틈새","bore = 실린더 안지름","diameter = 지름"],"t":"stroke = TDC~BDC"},"2024-4-영어-21":{"w":"remote control system = 원격제어장치 입니다.","x":["원격자동장치가 아닙니다.","원격전자장치가 아닙니다.","외부조작장치가 아닙니다.","정답. 원격제어장치"],"t":"remote control = 원격제어"},"2024-4-영어-24":{"w":"lifeboat = 구명정 입니다. (구명벌은 liferaft)","x":["구명벌은 liferaft입니다.","구명환은 lifebuoy입니다.","구명줄은 lifeline입니다.","정답. 구명정"],"t":"lifeboat 구명정, liferaft 구명벌"},"2024-4-영어-25":{"w":"보일러 점검표에서 매일(daily) 점검 항목은 3개입니다. 점검표의 주기(daily, weekly, monthly 등) 칸을 확인해 세어 봅니다.","x":["틀립니다.","틀립니다.","정답. 3개","틀립니다."],"t":"daily = 매일"},"2025-1-기관1-1":{"w":"6실린더 4행정 기관은 720°÷6 = 120°마다 한 번씩 폭발합니다. 3번 실린더가 흡입행정을 시작할 때(상사점)는 3번이 폭발하기 360° 전입니다.\n착화순서 1→5→3→6→2→4에서 3번보다 세 칸(120°×3 = 360°) 앞에 폭발하는 실린더는 4번이므로, 이때 4번은 막 폭발하여 작동행정을 시작합니다.","x":["흡입행정 시작은 3번 자신의 상태입니다.","압축행정 시작은 3번보다 180° 뒤진 상태가 아닙니다.","정답. 3번보다 360° 앞선 4번은 작동행정 시작","배기행정 시작은 해당하지 않습니다."],"t":"흡입 시작인 실린더와 360° 차이 = 작동행정 시작인 실린더"},"2025-1-기관1-2":{"w":"소기공은 하사점을 중심으로 대칭으로 열리고 닫힙니다. 하사점 전 50°에 열리면 하사점 후 50°에 닫히므로 열려 있는 각도는 50° + 50° = 100°입니다.","x":["한쪽 각도만 계산한 값입니다.","정답. 50° + 50° = 100°","틀린 값입니다.","틀린 값입니다."],"t":"소기공 열림 각도 = 하사점 전 각도 × 2"},"2025-1-기관1-3":{"w":"저질 중유에는 황분이 많아 황산 부식(저온 부식)으로 라이너가 마멸됩니다. 저속 운전을 하면 실린더 온도가 낮아져 황산이 응결하기 쉬우므로 오히려 부식 마멸이 늘어납니다.","x":["정답(옳지 않은 것). 저속 운전은 저온 부식을 키웁니다.","냉각수 온도를 높게 유지하면 황산 응결(저온 부식)을 막습니다.","청정하면 불순물·회분이 줄어 마멸이 줄어듭니다.","알칼리성이 좋은 실린더유 등 적합한 윤활유 사용은 마멸 방지 대책입니다."],"t":"저질 중유 → 황산 부식 → 온도를 높게, 저속 운전은 피한다"},"2025-1-기관1-4":{"w":"켈밋(kelmet)은 구리(Cu)에 납(Pb)을 30~40% 섞은 베어링 합금입니다. 열전도가 좋고 고하중·고속에 강해 고속 디젤기관 베어링에 쓰입니다.","x":["연청동은 켈밋이 아닙니다.","정답. 켈밋 = 구리 + 납","인청동은 구리+주석+인입니다.","청동은 구리+주석입니다."],"t":"켈밋 = Cu + Pb"},"2025-1-기관1-5":{"w":"피스톤이 내려갈 때 링이 링 홈 안에서 위아래로 움직이면서 링 뒤쪽으로 윤활유를 퍼 올려 연소실로 보내는 현상을 링의 펌프작용이라 합니다. 윤활유 소비가 늘고 카본이 쌓이는 원인입니다.","x":["기밀작용은 가스 누설을 막는 작용입니다.","정답. 링이 윤활유를 연소실로 퍼 올리는 작용 = 펌프작용","냉각작용은 피스톤 열을 라이너로 전달하는 작용입니다.","플러터는 링이 링 홈 안에서 떨리는 현상입니다."],"t":"윤활유가 연소실로 올라감 = 링의 펌프작용"},"2025-1-기관1-6":{"w":"피스톤 헤드의 열이 피스톤핀 쪽으로 전달되는 것을 줄이기 위해 피스톤 내부에 방열판(열 차단판)을 둡니다. 핀과 핀 보스부가 과열되는 것을 막는 것이 주된 목적입니다.","x":["정답. 피스톤핀 과열 방지","무게를 줄이는 장치가 아닙니다.","라이너 열팽창 방지와는 관계없습니다.","가스 누설 방지는 피스톤링의 역할입니다."],"t":"피스톤 방열판 → 피스톤핀 과열 방지"},"2025-1-기관1-7":{"w":"리머 볼트는 볼트 몸통 일부를 리머로 정밀하게 다듬어 볼트 구멍에 꼭 맞게 끼우는 볼트입니다. 커넥팅로드와 베어링 캡의 위치가 어긋나지 않아 크랭크핀 베어링을 정확하게 조립할 수 있습니다.","x":["죄기 쉽게 하려는 목적이 아닙니다.","풀기 쉽게 하려는 목적이 아닙니다.","분해를 쉽게 하려는 목적이 아닙니다.","정답. 위치를 정확히 맞춰 조립하기 위해"],"t":"리머 볼트 = 정확한 위치 맞춤(맞춤 볼트)"},"2025-1-기관1-8":{"w":"4행정 기관의 배기행정 말기~흡기행정 초기(상사점 부근)에는 실린더 안 가스 압력이 거의 없는데, 피스톤과 커넥팅로드의 관성력이 피스톤을 위로 끌어올립니다. 이 관성력이 크랭크핀 볼트를 잡아당기므로 인장력이 가장 큽니다.","x":["이때는 관성력보다 압축 압력이 작용합니다.","압축 말기~작동 초기에는 가스 압력이 볼트를 누르는 방향(압축)으로 작용합니다.","이때는 관성력이 크지 않습니다.","정답. 가스 압력 없이 관성력만 작용 → 인장력 최대"],"t":"크랭크핀 볼트 인장 최대 = 배기 말~흡기 초(상사점)"},"2025-1-기관1-9":{"w":"시동 공기로 시동하는 기관에는 시동 공기 밸브를 여는 시동캠이 있습니다. 전동기(셀 모터)로 시동하는 기관은 시동 공기를 쓰지 않으므로 시동캠이 필요 없습니다.","x":["연료캠은 연료분사펌프를 움직이므로 필요합니다.","정답. 전동기 시동 기관에는 시동캠이 없습니다.","배기캠은 배기밸브를 여닫으므로 필요합니다.","흡기캠은 흡기밸브를 여닫으므로 필요합니다."],"t":"전동기 시동 → 시동캠 없음"},"2025-1-기관1-10":{"w":"디젤기관 진동의 원인은 폭발압력, 왕복 운동부의 관성력, 크랭크축의 회전(비틀림 진동) 등입니다. 플라이휠은 회전력의 변동을 줄여 회전을 고르게 하는 장치로, 진동의 원인이 아닙니다.","x":["정답(아닌 것). 플라이휠은 회전을 고르게 해 줍니다.","크랭크축 회전에 따른 비틀림 진동이 생깁니다.","폭발압력의 변동은 진동의 원인입니다.","왕복 운동부의 관성력은 진동의 원인입니다."],"t":"플라이휠 = 회전력 균일화(진동 원인 아님)"},"2025-1-기관1-11":{"w":"디젤 노킹은 착화지연 기간이 길어 그동안 쌓인 연료가 한꺼번에 폭발하면서 생깁니다. 노킹을 막으려면 착화지연 기간을 짧게 해야 합니다.","x":["세탄값이 크면 착화가 빨라 노킹이 줄어듭니다.","중질유는 착화성이 나빠 노킹이 심해집니다.","정답(옳지 않은 것). 착화지연 기간은 짧게 해야 합니다.","냉각수 온도를 높이면 압축 온도가 올라가 착화가 빨라집니다."],"t":"디젤 노킹 방지 = 착화지연 짧게, 세탄값 높게"},"2025-1-기관1-12":{"w":"보일러 수면에 떠 있는 기름이나 거품 같은 부유물은 수면 가까이에 설치한 수면 방출관(수면 분출관)으로 배출합니다.","x":["급수 내관은 급수를 드럼 안에 고르게 공급하는 관입니다.","정답. 수면 부유물 배출 = 수면 방출관","수저 방출관은 드럼 바닥의 침전물(슬러지)을 배출합니다.","드라이 파이프는 증기 속 수분을 분리합니다."],"t":"뜨는 것 = 수면 방출, 가라앉는 것 = 수저 방출"},"2025-1-기관1-13":{"w":"절탄기(이코노마이저)는 연도로 나가는 배기가스의 폐열로 보일러 급수를 미리 데우는 장치입니다. 보일러 연도(배기가스 통로)에 설치하며, 복수 계통에 설치하는 것이 아닙니다.","x":["정답(옳지 않은 것). 절탄기는 보일러 연도에 설치합니다.","효율은 오르지만 가스 통로가 좁아져 통풍 저항이 늘어납니다.","배기가스의 폐열을 이용합니다.","급수를 미리 데워 드럼의 열응력을 줄입니다."],"t":"절탄기 = 연도 폐열로 급수 예열"},"2025-1-기관1-14":{"w":"증기터빈의 축이 케이싱을 관통하는 곳에서 증기가 새는 것을 막기 위해 래버린스 패킹, 탄소 패킹, 수봉 패킹을 씁니다. 그리스 패킹은 증기터빈의 누설방지 장치가 아닙니다.","x":["래버린스 패킹은 대표적인 비접촉식 누설방지 장치입니다.","탄소 패킹은 탄소 링으로 축을 감싸 누설을 막습니다.","정답(아닌 것). 그리스 패킹은 쓰지 않습니다.","수봉 패킹은 물로 밀봉해 공기 유입·증기 누설을 막습니다."],"t":"터빈 패킹 = 래버린스, 탄소, 수봉"},"2025-1-기관1-15":{"w":"복수기로 배기를 진공(대기압보다 낮은 압력)으로 만들면 터빈 입구와 출구의 압력 차(열낙차)가 커져 증기가 더 많은 일을 하므로 터빈의 효율이 높아집니다.","x":["정답. 열낙차를 크게 해 효율을 높이기 위해","크기를 작게 하려는 목적이 아닙니다.","입구 증기 압력과는 관계없습니다.","입구 증기 속도와는 관계없습니다."],"t":"배기 진공 → 열낙차 증가 → 효율 증가"},"2025-1-기관1-16":{"w":"선미관은 프로펠러축이 선체를 관통하는 곳에 설치되어 해수 침입을 막고 축을 받쳐 주는 베어링 역할을 합니다. 추력을 선체에 전달하는 것은 추력(스러스트) 베어링입니다.","x":["선미관은 해수가 선내로 들어오는 것을 막습니다.","정답(옳지 않은 것). 추력 전달은 추력 베어링의 역할입니다.","선미관 베어링이 프로펠러축을 받칩니다.","프로펠러축이 선체를 관통하는 곳에 설치됩니다."],"t":"추력 전달 = 추력 베어링 (선미관 아님)"},"2025-1-기관1-17":{"w":"프로펠러축이 부러지는 원인은 재질 불량, 비틀림 진동, 부식에 의한 강도 저하, 축심 불일치 등입니다. 추력 베어링의 마멸은 축의 전후 위치에 영향을 주지만 프로펠러축 절손의 직접 원인은 아닙니다.","x":["재질 불량은 절손 원인입니다.","정답(아닌 것). 추력 베어링 마멸은 직접 원인이 아닙니다.","비틀림 진동은 피로 파괴의 원인입니다.","부식으로 강도가 떨어지면 부러지기 쉽습니다."],"t":"프로펠러축 절손 = 재질, 비틀림 진동, 부식"},"2025-1-기관1-18":{"w":"축계는 기관에서 프로펠러 방향(선수→선미)으로 스러스트축 → 중간축 → 추진기축(프로펠러축) 순서로 배치됩니다.","x":["정답. 스러스트축 → 중간축 → 추진기축","순서가 틀렸습니다.","순서가 틀렸습니다.","순서가 틀렸습니다."],"t":"기관 → 스러스트축 → 중간축 → 프로펠러축"},"2025-1-기관1-19":{"w":"슬립은 프로펠러가 이론상 나아가야 할 거리와 실제 배가 나아간 거리의 차이입니다. 배의 저항이 커지면(흘수 증가, 선저 오손, 역풍 등) 슬립이 늘어나고, 저항이 줄면 슬립도 줄어듭니다.","x":["흘수가 늘면 저항이 커져 슬립이 늘어납니다.","정답(아닌 것). 저항이 줄면 슬립은 줄어듭니다.","피치가 커지면 슬립이 늘어납니다.","회전수가 늘면 슬립이 늘어납니다."],"t":"저항 증가 → 슬립 증가"},"2025-1-기관1-20":{"w":"유효마력(EHP)은 배를 일정한 속도로 끌고 가는 데 필요한 마력으로, 예인마력이라고도 합니다. 선체를 직접 추진하는 데 쓰이는 동력입니다.","x":["제동마력은 기관 출력축에서 나오는 마력입니다.","전달마력은 프로펠러에 전달되는 마력입니다.","추력마력은 프로펠러가 내는 추력에 의한 마력입니다.","정답. 유효마력 = 예인마력"],"t":"유효마력 = 예인마력(EHP)"},"2025-1-기관1-21":{"w":"중유를 가열하면 점도가 낮아져 묽어집니다. 그래서 분사나 청정 전에 중유를 가열해 점도를 맞춥니다. 인화점·유동점은 기름 고유의 성질이고, 부피는 가열하면 늘어납니다.","x":["인화점은 가열해도 변하지 않는 고유 성질입니다.","유동점도 고유 성질입니다.","부피는 가열하면 늘어납니다.","정답. 가열하면 점도가 내려갑니다."],"t":"중유 가열 → 점도 저하"},"2025-1-기관1-22":{"w":"인화점은 불꽃을 가까이 댔을 때 불이 붙을 만큼 유증기가 발생하는 최저 온도입니다. 불꽃 없이 스스로 불이 붙는 온도는 착화점(발화점)입니다.","x":["착화점은 불꽃 없이 스스로 타기 시작하는 온도입니다.","연소점은 불이 붙은 뒤 계속 타는 온도로 인화점보다 높습니다.","정답. 불꽃을 대면 불이 붙는 최저 온도 = 인화점","발화점은 착화점과 같은 뜻입니다."],"t":"인화점(불꽃 대면) < 연소점 < 착화점(스스로)"},"2025-1-기관1-23":{"w":"윤활유가 고온의 실린더 벽이나 피스톤에 닿으면 열분해되어 탄화물(카본)이 생깁니다. 이 카본이 쌓이면 실린더 마멸과 피스톤링 고착의 원인이 됩니다.","x":["산소와 접촉하면 산화(슬러지)가 생깁니다.","새 윤활유 혼합은 탄화물의 원인이 아닙니다.","정답. 고온 → 열분해 → 탄화물","금속 가루·수분은 오염·유화의 원인입니다."],"t":"윤활유 탄화물 = 고온 열분해"},"2025-1-기관1-24":{"w":"유성(油性)은 윤활유가 금속 마찰면에 강하게 달라붙어 얇은 유막을 만드는 성질입니다. 유막이 끊기기 쉬운 경계 윤활 상태에서 특히 중요합니다.","x":["점도는 기름의 끈적한 정도(흐름에 대한 저항)입니다.","정답. 마찰면에 흡착해 유막을 만드는 성질 = 유성","항유화성은 물과 잘 섞이지 않고 분리되는 성질입니다.","산화 안정도는 산화에 견디는 성질입니다."],"t":"유성 = 흡착해서 유막 형성"},"2025-1-기관1-25":{"w":"윤활유는 감마(마찰 감소), 냉각, 밀봉(기밀), 청정, 방청, 응력 분산 작용을 합니다. 응집작용은 윤활유의 작용이 아닙니다.","x":["냉각작용은 윤활유의 작용입니다.","정답(아닌 것). 응집작용은 없습니다.","밀봉(기밀)작용은 윤활유의 작용입니다.","청정작용은 윤활유의 작용입니다."],"t":"윤활유 작용 = 감마·냉각·밀봉·청정·방청·응력분산"},"2025-1-기관2-1":{"w":"원심펌프가 송출을 못 하는 원인은 흡입양정이 너무 큼, 흡입관에 공기가 남아 있거나 새어 들어옴, 유체 온도가 너무 높아 증발(공동현상) 등입니다. 유체 온도가 낮은 것은 원인이 아닙니다.","x":["흡입양정이 크면 흡입이 안 됩니다.","흡입관 속 공기는 송출 불량의 원인입니다.","정답(옳지 않은 것). 온도가 높을 때가 문제입니다.","공기가 흡입되면 송출이 안 됩니다."],"t":"원심펌프 송출 불량 = 공기, 큰 흡입양정, 높은 유체 온도"},"2025-1-기관2-2":{"w":"이모(Imo) 펌프는 나사 모양의 로터(스크루) 3개가 맞물려 돌면서 액체를 축 방향으로 밀어내는 스크루 펌프입니다. 맥동이 적어 연료유·윤활유 펌프로 많이 씁니다.","x":["슬라이딩 베인은 베인 펌프 형식입니다.","축방향 플런저는 사판식 등 플런저 펌프 형식입니다.","방사식 플런저는 반경 방향 플런저 펌프입니다.","정답. 이모 펌프 = 스크루 펌프"],"t":"이모 펌프 = 3축 스크루 펌프"},"2025-1-기관2-3":{"w":"원심식 유청정기 안의 원뿔형 분리판은 기름을 얇은 층으로 나누어 원심력이 작용하는 거리를 짧게 해 줍니다. 그래서 물과 불순물이 빨리 분리됩니다.","x":["비중은 비중판(조정판)으로 조정합니다.","온도는 가열기로 높입니다.","봉수를 나누는 장치가 아닙니다.","정답. 기름을 얇은 층으로 나눕니다."],"t":"분리판 = 기름을 얇은 층으로 분할"},"2025-1-기관2-4":{"w":"큰 밸브 하나 대신 작은 밸브 여러 개를 쓰면 밸브 하나하나의 무게와 들림량이 작아져 밸브가 열리고 닫힐 때의 충격이 줄어듭니다.","x":["정답. 밸브 개폐 충격이 작아집니다.","제작비가 싸지는 것이 주목적이 아닙니다.","보수가 쉬워지는 것이 가장 큰 이점은 아닙니다.","밸브 박스를 줄이려는 목적이 아닙니다."],"t":"작은 밸브 여러 개 → 개폐 충격 감소"},"2025-1-기관2-5":{"w":"공기는 압축되므로 유압 조종장치 관 속에 공기가 있으면 조타륜을 돌려도 그 움직임이 바로 전달되지 않습니다. 운동의 전달이 정확하지 않게 됩니다.","x":["압력계 지시값이 높아지는 것은 아닙니다.","정답. 공기가 압축되어 움직임이 정확히 전달되지 않습니다.","조종장치 관 속 공기의 대표 현상이 아닙니다.","조종장치 관 속 공기의 대표 현상이 아닙니다."],"t":"유압 관 속 공기 → 전달이 부정확"},"2025-1-기관2-6":{"w":"유량제어밸브는 흐르는 기름의 양(속도)을 조절하는 밸브로, 교축밸브(스로틀밸브)가 대표적입니다. 감압·릴리프·시퀀스밸브는 압력제어밸브입니다.","x":["감압밸브는 압력제어밸브입니다.","정답. 교축밸브 = 유량제어밸브","릴리프밸브는 압력제어밸브입니다.","시퀀스밸브는 압력제어밸브입니다."],"t":"유량제어 = 교축밸브 / 압력제어 = 릴리프·감압·시퀀스"},"2025-1-기관2-7":{"w":"양묘기(윈드라스)는 닻과 닻줄을 감아올리는 장치로 체인 드럼(워핑드럼·체인 휠), 마찰 브레이크, 클러치, 조종 핸들 등으로 이루어집니다. 슬루잉 윈치는 크레인·데릭의 붐을 좌우로 돌리는 윈치입니다.","x":["조종 핸들은 양묘기의 구성품입니다.","체인 드럼은 양묘기의 구성품입니다.","정답(아닌 것). 슬루잉 윈치는 하역장치에 속합니다.","마찰 브레이크는 양묘기의 구성품입니다."],"t":"슬루잉 = 붐 좌우 회전(하역장치)"},"2025-1-기관2-8":{"w":"콜레서(coalescer)는 빌지 속의 아주 작은 기름방울을 섬유 필터에 흡착시켜 서로 뭉치게 해 큰 방울로 만듭니다. 커진 기름방울은 위로 잘 떠올라 분리됩니다.","x":["기름을 잘게 부수면 분리가 더 어려워집니다.","정답. 작은 기름 입자를 뭉쳐 큰 입자로 만듭니다.","물만 통과시키는 여과 필터와는 원리가 다릅니다.","기름만 통과시키는 장치가 아닙니다."],"t":"콜레서 = 작은 기름방울을 모아 큰 방울로"},"2025-1-기관2-9":{"w":"유면검출기는 분리기 위쪽에 모인 기름층의 두께를 감지해 기름을 배출시킵니다. 감도를 높이면 기름층이 조금만 쌓여도 감지하므로 기름층의 하한 레벨이 높아집니다(얇은 기름층에서도 동작).","x":["상한 레벨이 낮아진다는 설명은 맞지 않습니다.","정답. 감도를 높이면 기름층의 하한 레벨이 높아집니다.","물층의 상한 레벨과는 관계없는 설명입니다.","물층의 하한 레벨과는 관계없는 설명입니다."],"t":"유면검출기 감도↑ → 기름층 하한 레벨↑"},"2025-1-기관2-10":{"w":"폐유(슬러지)는 점도가 높고 이물질이 많아 원심펌프로는 옮기기 어렵습니다. 점도가 높은 액체를 일정하게 보낼 수 있는 기어 펌프가 가장 적당합니다.","x":["정답. 고점도 폐유 = 기어 펌프","원심펌프는 고점도 액체에 적합하지 않습니다.","왕복펌프는 맥동이 커 폐유 공급에 적합하지 않습니다.","축류펌프는 대유량·저양정용입니다."],"t":"고점도 기름 이송 = 기어 펌프"},"2025-1-기관2-11":{"w":"안전헤드는 실린더 상부에 강한 스프링으로 눌러 놓은 덮개입니다. 액 냉매나 이물질이 들어와 압력이 비정상적으로 높아지면 스프링을 밀고 들려 올라가 압축기를 보호합니다. 볼트로 고정하지 않습니다.","x":["정답(옳지 않은 것). 볼트가 아니라 스프링으로 눌러 둡니다.","이상 압력에서 들리는 일종의 안전밸브입니다.","송출밸브가 안전헤드에 설치됩니다.","피스톤 윗면과 함께 압축실을 이룹니다."],"t":"안전헤드 = 스프링으로 누른 덮개(액 압축 시 들림)"},"2025-1-기관2-12":{"w":"응축기 냉각관이 액 냉매에 많이 잠기면(냉매 과충전) 실제로 응축에 쓰이는 냉각 면적이 줄어 응축이 잘 안 되므로 압축(응축) 압력이 높아집니다.","x":["냉매가 부족하면 압력은 낮아집니다.","냉각수 온도가 낮으면 압력은 낮아집니다.","냉각수가 많으면 압력은 낮아집니다.","정답. 냉각관이 액에 잠기면 냉각 면적이 줄어 압력이 높아집니다."],"t":"압축압력 과대 = 냉각 불량, 냉매 과충전, 불응축 가스"},"2025-1-기관2-13":{"w":"냉매는 보통 수액기 출구 밸브를 닫고, 저압 측(흡입 측) 충전 밸브로 보충합니다. 출구 밸브를 닫아야 냉매가 수액기와 응축기에 모이며 충전됩니다.","x":["정답(옳지 않은 것). 수액기 출구 밸브는 닫고 보충합니다.","충전관 속 공기는 냉매 가스로 밀어내야 합니다.","응축기에 냉각수를 흘리며 보충합니다.","용기 무게 변화로 보충량을 알 수 있습니다."],"t":"냉매 보충 = 수액기 출구 밸브 닫고"},"2025-1-기관2-14":{"w":"가습은 물 분무, 증기 분무, 가습 팬(증발식) 등으로 합니다. 실리카겔은 수분을 빨아들이는 흡착제로 감습(제습)에 쓰입니다.","x":["물 분무는 가습 방법입니다.","증기 분무는 가습 방법입니다.","정답(아닌 것). 실리카겔은 제습제입니다.","가습 팬은 가습 방법입니다."],"t":"실리카겔 = 감습(제습)"},"2025-1-기관2-15":{"w":"실내에서 밖으로 열이 빠져나가는 겨울철 조건이므로 공급 공기를 가열해야 합니다. 가열하면 상대습도가 떨어지므로 가습도 함께 해야 합니다.","x":["냉각·감습은 여름철 조건입니다.","냉각은 맞지 않습니다.","가열은 맞지만 감습은 맞지 않습니다.","정답. 겨울철 = 가열 + 가습"],"t":"여름 = 냉각·감습, 겨울 = 가열·가습"},"2025-1-기관2-16":{"w":"핸드탭은 1번(황삭), 2번(중삭), 3번(다듬질) 탭 3개가 한 조입니다. 1번부터 차례로 사용해 암나사를 완성합니다.","x":["틀린 개수입니다.","정답. 3개가 한 조","틀린 개수입니다.","틀린 개수입니다."],"t":"핸드탭 = 3개 1조"},"2025-1-기관2-17":{"w":"스크레이퍼는 손으로 금속 표면을 조금씩 긁어내 평면이나 베어링 면을 정밀하게 다듬는 손다듬질 공구입니다.","x":["바이트는 선반에 끼워 쓰는 절삭 공구입니다.","정답. 스크레이퍼 = 손다듬질 공구","선반은 공작기계입니다.","실린더 게이지는 측정 공구입니다."],"t":"스크레이퍼 = 긁어서 다듬질"},"2025-1-기관2-18":{"w":"구멍 가공은 센터 드릴로 중심을 잡고 → 드릴로 뚫고 → 보링으로 구멍을 넓히고 → 리머로 정밀하게 다듬는 순서로 합니다.","x":["순서가 틀렸습니다.","정답. 센터 드릴 → 드릴 → 보링 → 리밍","순서가 틀렸습니다.","순서가 틀렸습니다."],"t":"센터 → 드릴 → 보링 → 리밍(마무리)"},"2025-1-기관2-19":{"w":"용접 전류가 부족하면 모재가 충분히 녹지 않아 용입 부족, 슬랙 혼입, 오버랩이 생깁니다. 언더컷은 전류가 너무 높을 때 생기는 결함입니다.","x":["용입 부족은 전류 부족 때 생깁니다.","슬랙 혼입은 전류 부족 때 생깁니다.","정답(아닌 것). 언더컷은 전류 과대 때 생깁니다.","오버랩은 전류 부족 때 생깁니다."],"t":"언더컷 = 전류 과대 / 오버랩 = 전류 부족"},"2025-1-기관2-20":{"w":"가스 용접 토치의 손잡이 쪽에는 산소와 아세틸렌의 양을 조절하는 밸브가 있습니다. 그림의 ⑤는 산소조정밸브입니다.","x":["팁은 불꽃이 나오는 토치의 끝부분입니다.","정답. ⑤ = 산소조정밸브","혼합실은 산소와 아세틸렌이 섞이는 곳입니다.","가스도관은 가스를 공급하는 호스입니다."],"t":"토치 = 팁, 혼합관, 산소밸브, 아세틸렌밸브"},"2025-1-기관2-21":{"w":"재화중량톤수(DWT)는 만재 배수량에서 경하 배수량(빈 배의 무게)을 뺀 값으로, 배가 실을 수 있는 화물·연료·물 등의 무게를 나타냅니다.","x":["정답. 만재 배수량 − 경하 배수량 = 재화중량톤수","순톤수는 여객·화물 적재 용적입니다.","배수톤수는 배가 밀어낸 물의 무게입니다.","총톤수는 선박 전체의 용적입니다."],"t":"재화중량톤수 = 실을 수 있는 무게(DWT)"},"2025-1-기관2-22":{"w":"수밀격벽은 선내를 여러 수밀 구획으로 나누어 침수·화재를 국부적으로 막습니다. 선수격벽(충돌격벽)이 가장 중요합니다. 소형선에서는 주로 수밀 횡격벽을 설치합니다.","x":["충돌에 대비한 선수격벽이 가장 중요합니다.","침수·화재를 국부적으로 제한합니다.","선박을 여러 수밀 구획으로 나눕니다.","정답(옳지 않은 것). 소형선은 주로 수밀 횡격벽을 씁니다."],"t":"수밀격벽 = 주로 횡격벽, 선수격벽이 가장 중요"},"2025-1-기관2-23":{"w":"선속과 필요한 동력은 3제곱 비례 관계에 있습니다. 따라서 시간당 연료소비량은 선속의 3제곱에 비례합니다. (항해 거리당 연료소비량은 선속의 제곱에 비례)","x":["반비례하지 않습니다.","제곱 비례는 같은 거리를 갈 때의 연료소비량입니다.","정답. 시간당 연료소비량 ∝ 선속³","4제곱이 아닙니다."],"t":"시간당 연료 ∝ 속력³, 거리당 연료 ∝ 속력²"},"2025-1-기관2-24":{"w":"한국산업표준(KS) 기계제도는 제3각법을 원칙으로 합니다. 정면도 위에 평면도, 오른쪽에 우측면도를 그립니다.","x":["반투상도법은 표준 투상법이 아닙니다.","제1각법은 일부 국가에서 쓰며 KS 원칙이 아닙니다.","제2각법은 쓰지 않습니다.","정답. KS = 제3각법"],"t":"KS 제도 = 제3각법"},"2025-1-기관2-25":{"w":"도면을 그릴 때는 가장 먼저 중심선을 그려 기준을 잡고, 그다음 외형선, 치수선 순서로 그립니다.","x":["치수선은 외형을 그린 뒤에 그립니다.","정답. 중심선을 가장 먼저","해칭선은 단면을 나타낼 때 나중에 그립니다.","외형선은 중심선 다음에 그립니다."],"t":"제도 순서 = 중심선 → 외형선 → 치수선"},"2025-1-기관3-1":{"w":"가운데 4[Ω] 두 개는 병렬이므로 4÷2 = 2[Ω]입니다. 여기에 양쪽 3[Ω]이 직렬로 붙으므로 3 + 2 + 3 = 8[Ω]입니다.","x":["병렬 부분만 계산한 값입니다.","틀린 값입니다.","정답. 3 + (4∥4 = 2) + 3 = 8[Ω]","병렬을 계산하지 않은 값에 가깝습니다."],"t":"같은 저항 2개 병렬 = 절반"},"2025-1-기관3-2":{"w":"우리가 흔히 말하는 교류 220[V], 440[V]는 모두 실효값입니다. 같은 일을 하는 직류 전압으로 바꾼 값으로, 최대값의 1/√2(약 0.707배)입니다.","x":["최대값은 실효값의 √2배(약 311[V])입니다.","순시값은 매 순간 바뀌는 값입니다.","정답. 일반적인 교류 전압 표시 = 실효값","평균값은 최대값의 약 0.637배입니다."],"t":"전압계·명판 표시 = 실효값"},"2025-1-기관3-3":{"w":"같은 크기의 저항 n개를 병렬로 연결하면 합성 저항은 1/n배가 됩니다. 10개이므로 1/10배로 작아집니다.","x":["병렬 연결하면 작아집니다.","5개일 때의 값입니다.","직렬 10개일 때의 값입니다.","정답. 같은 저항 10개 병렬 = 1/10배"],"t":"같은 저항 n개: 직렬 n배, 병렬 1/n배"},"2025-1-기관3-4":{"w":"교류 전력의 단위는 유효전력 [W], 무효전력 [Var], 피상전력 [VA]입니다.","x":["[VA]는 피상전력의 단위입니다.","정답. 무효전력 = [Var]","[W]는 유효전력의 단위입니다.","[Wb]는 자속의 단위입니다."],"t":"W(유효), Var(무효), VA(피상)"},"2025-1-기관3-5":{"w":"권수비 a = V1/V2 이므로 V2 = V1 ÷ a = 600 ÷ 6 = 100[V]입니다.","x":["틀린 값입니다.","정답. 600 ÷ 6 = 100[V]","틀린 값입니다.","곱해서 계산한 값입니다."],"t":"권수비 a = V1/V2 = N1/N2"},"2025-1-기관3-6":{"w":"RL 직렬회로의 임피던스 Z = √(R² + XL²) = √(30² + 40²) = √2500 = 50[Ω]입니다.","x":["뺀 값입니다.","정답. √(30² + 40²) = 50[Ω]","단순히 더한 값입니다.","틀린 값입니다."],"t":"Z = √(R² + X²) (3:4:5 직각삼각형)"},"2025-1-기관3-7":{"w":"키르히호프의 제1법칙(전류 법칙)은 회로의 한 점으로 들어오는 전류의 합과 나가는 전류의 합이 같다는 법칙입니다. 즉 전류의 대수합은 0입니다.","x":["앙페르의 법칙은 전류와 자기장의 방향에 관한 법칙입니다.","정답. 키르히호프 제1법칙(전류 법칙)","쿨롱의 법칙은 전하 사이의 힘에 관한 법칙입니다.","패러데이의 법칙은 전자유도에 관한 법칙입니다."],"t":"키르히호프 1법칙 = 전류, 2법칙 = 전압"},"2025-1-기관3-8":{"w":"역률 = 유효전력 ÷ 피상전력 = P ÷ (V × I) = 30 ÷ (100 × 0.6) = 30 ÷ 60 = 0.5입니다.","x":["정답. 30 ÷ 60 = 0.5","전류값을 그대로 쓴 값입니다.","틀린 값입니다.","틀린 값입니다."],"t":"역률 cosθ = P / VI"},"2025-1-기관3-9":{"w":"전류 I = 전하량 Q ÷ 시간 t = 0.3 ÷ 0.5 = 0.6[A]입니다.","x":["틀린 값입니다.","틀린 값입니다.","정답. 0.3[C] ÷ 0.5[s] = 0.6[A]","틀린 값입니다."],"t":"I = Q / t"},"2025-1-기관3-10":{"w":"그림은 세 축전지의 (+)끼리, (−)끼리 연결한 병렬 연결입니다. 병렬 연결하면 전압은 그대로 12[V]이고 용량은 더해져 80 × 3 = 240[Ah]가 됩니다.","x":["축전지 1개의 값입니다.","정답. 병렬 = 전압 그대로, 용량 합산","직렬 연결일 때의 값입니다.","전압과 용량을 모두 더한 잘못된 값입니다."],"t":"축전지 직렬 = 전압 합, 병렬 = 용량 합"},"2025-1-기관3-11":{"w":"그림의 기호는 다이오드(정류기) 모양입니다. 계측기에 이 기호가 있으면 교류를 정류해 가동코일형 계기로 재는 정류형 계기입니다.","x":["정답. 다이오드 기호 = 정류형","열선형은 열선이 늘어나는 것을 이용하는 계기입니다.","유도형은 원판에 유도되는 전류를 이용합니다.","정전형은 전극 사이의 정전력을 이용합니다."],"t":"계기 기호 다이오드 = 정류형"},"2025-1-기관3-12":{"w":"3상 전력 P = √3 × 선간전압 × 선전류 × 역률 입니다. 따라서 E는 선간전압, I는 선전류, cosθ는 역률입니다.","x":["cosθ는 주파수가 아니라 역률입니다.","정답. √3 × 선간전압 × 선전류 × 역률","상전압·상전류로 쓰면 3 × E상 × I상 × cosθ가 됩니다.","cosθ는 주파수가 아닙니다."],"t":"P = √3 VL IL cosθ = 3 Vp Ip cosθ"},"2025-1-기관3-13":{"w":"발전기의 주파수는 원동기(디젤기관)의 회전수로 정해집니다. 배전반의 조속기 모터 스위치(거버너 스위치)로 원동기의 회전수를 바꿔 주파수를 조정합니다.","x":["동기검정기는 병렬운전 시 위상을 확인하는 계기입니다.","정답. 주파수 조정 = 조속기(거버너) 모터 스위치","여자전류 조정기는 전압을 조정합니다.","역전류 차단기는 역전력을 막는 보호장치입니다."],"t":"주파수 = 거버너, 전압 = 여자전류(AVR)"},"2025-1-기관3-14":{"w":"직류 전동기 속도 N ∝ (V − IaRa) / Φ 입니다. 전기자 저항 Ra가 커지면 전압강하가 커져 속도가 떨어집니다.","x":["속도가 빨라지면 역기전력이 커집니다.","속도는 자속에 반비례합니다.","공급전압이 높아지면 속도가 올라갑니다.","정답(옳지 않은 것). 전기자 저항이 크면 속도는 떨어집니다."],"t":"N ∝ (V − IaRa) / Φ"},"2025-1-기관3-15":{"w":"직류기 브러시는 정류가 잘 되고 정류자를 덜 닳게 하는 카본(탄소) 브러시를 가장 많이 씁니다.","x":["동 브러시는 저전압 대전류용으로 일부만 씁니다.","정답. 카본 브러시","주철 브러시는 쓰지 않습니다.","전기동 브러시는 일반적이지 않습니다."],"t":"브러시 = 카본(탄소)"},"2025-1-기관3-16":{"w":"유도전동기 기동법은 전전압(직입) 기동, Y-△ 기동, 기동보상기(단권변압기) 기동, 리액터 기동 등이 있습니다. 극수 변환법은 속도 제어 방법입니다.","x":["Y-△ 기동법은 기동 방법입니다.","기동보상기법은 기동 방법입니다.","정답(아닌 것). 극수 변환은 속도 제어법입니다.","전전압 기동법은 소형 전동기 기동 방법입니다."],"t":"극수 변환 = 속도 제어"},"2025-1-기관3-17":{"w":"동기속도 Ns = 120f/P = 120 × 60 ÷ 8 = 900[rpm].\n슬립 s = (Ns − N) ÷ Ns × 100 = (900 − 864) ÷ 900 × 100 = 4[%]입니다.","x":["틀린 값입니다.","정답. (900 − 864) ÷ 900 = 4[%]","틀린 값입니다.","틀린 값입니다."],"t":"Ns = 120f / P, s = (Ns − N) / Ns"},"2025-1-기관3-18":{"w":"선박의 3상 동기발전기 전기자 권선은 보통 Y결선으로 하고, 유도전동기 고정자 권선은 정상 운전 시 △결선으로 합니다(Y-△ 기동 후 △로 운전).","x":["전동기는 정상 운전 시 △결선입니다.","정답. 발전기 Y, 전동기 △","반대입니다.","발전기는 Y결선입니다."],"t":"발전기 Y, 전동기(운전 중) △"},"2025-1-기관3-19":{"w":"진리표를 보면 A와 B가 모두 1일 때만 X가 0이고, 나머지는 1입니다. AND의 반대인 NAND 게이트입니다. NAND 기호는 AND 기호 끝에 작은 동그라미(부정)가 붙은 모양입니다.","x":["AND 게이트는 둘 다 1일 때만 1입니다.","정답. 둘 다 1일 때만 0 = NAND","OR 게이트는 하나라도 1이면 1입니다.","NOR 게이트는 둘 다 0일 때만 1입니다."],"t":"NAND = AND + 동그라미, 둘 다 1일 때만 0"},"2025-1-기관3-20":{"w":"반도체의 공유결합에서 전자가 빠져나간 빈자리를 정공(hole)이라 합니다. 정공은 (+) 전하처럼 움직입니다.","x":["정답. 전자가 빠진 빈자리 = 정공","도핑은 불순물을 넣는 것입니다.","억셉터는 정공을 만드는 3가 불순물입니다.","캐리어는 전하를 나르는 전자·정공을 통틀어 말합니다."],"t":"정공 = 전자의 빈자리 (+)"},"2025-1-기관3-21":{"w":"실리콘 트랜지스터는 베이스-이미터 사이에 약 0.6~0.7[V] 이상의 순방향 전압을 걸어야 베이스 전류가 흐르고 컬렉터 전류가 흐릅니다.","x":["정답. 실리콘 = 약 0.7[V]","틀린 값입니다.","게르마늄은 약 0.3[V]입니다.","틀린 값입니다."],"t":"Si 0.7V, Ge 0.3V"},"2025-1-기관3-22":{"w":"서미스터는 온도에 따라 저항값이 크게 변하는 소자로, 온도 측정·온도 보상에 씁니다.","x":["빛에 의해 변하는 소자는 CdS(광도전 소자)입니다.","정답. 서미스터 = 온도 → 저항 변화","전류에 의해 변하는 소자가 아닙니다.","전압에 의해 변하는 소자는 배리스터입니다."],"t":"서미스터 = 온도(thermal), 배리스터 = 전압"},"2025-1-기관3-23":{"w":"제너 다이오드는 역방향 전압이 일정 값(제너 전압)에 이르면 전압이 그 값으로 일정하게 유지되는 성질이 있어 정전압 회로에 씁니다.","x":["정답. 정전압 = 제너 다이오드","터널 다이오드는 고속 스위칭·발진용입니다.","배리스터는 과전압 보호용입니다.","서미스터는 온도 감지용입니다."],"t":"제너 다이오드 = 정전압"},"2025-1-기관3-24":{"w":"다이오드 기호에서 바깥쪽으로 나가는 화살표 두 개가 있는 것은 빛을 내는 발광 다이오드(LED)입니다.","x":["트랜지스터는 3개의 단자를 가진 기호입니다.","제너 다이오드는 막대가 꺾인 모양입니다.","연산증폭기는 삼각형 기호입니다.","정답. 화살표가 밖으로 = 발광 다이오드(LED)"],"t":"화살표 밖으로 = LED, 안으로 = 포토다이오드"},"2025-1-기관3-25":{"w":"다이오드는 한 방향으로만 전류를 흘려 교류를 직류로 바꾸는 정류작용을 합니다.","x":["변조는 다이오드의 주된 작용이 아닙니다.","발진은 주로 트랜지스터 회로의 작용입니다.","증폭은 트랜지스터의 작용입니다.","정답. 다이오드 = 정류"],"t":"다이오드 = 정류, 트랜지스터 = 증폭·스위칭"},"2025-1-직무일반-1":{"w":"일반적으로 2등 기관사는 연료유의 수급·관리, 연료유 청정기, 발전기 등을 맡습니다. 윤활유의 수급 및 관리는 주로 3등 기관사의 업무입니다.","x":["발전기 운전·관리는 2등 기관사 업무입니다.","정답(아닌 것). 윤활유 관리는 주로 3등 기관사 업무입니다.","연료유 수급·관리는 2등 기관사 업무입니다.","연료유 청정기는 2등 기관사 업무입니다."],"t":"2기사 = 연료유·발전기 / 3기사 = 윤활유"},"2025-1-직무일반-2":{"w":"기름 탱크 안은 유증기가 있어 작은 불꽃에도 폭발할 수 있습니다. 징이 박힌 신발은 철판과 부딪혀 불꽃을 일으킬 수 있으므로 신으면 안 됩니다.","x":["방폭형 공구·작업등을 사용해야 합니다.","전선 스파크에 주의해야 합니다.","미리 충분히 환기해야 합니다.","정답(옳지 않은 것). 징 박힌 신발은 불꽃을 일으킵니다."],"t":"기름 탱크 = 불꽃 금지(징 신발 금지)"},"2025-1-직무일반-3":{"w":"그림은 한쪽으로만 흐르게 하고 역류를 막는 체크밸브입니다. 유체가 반대로 흐르면 밸브가 닫힙니다.","x":["슬루스밸브는 문처럼 위아래로 여닫는 밸브입니다.","글러브밸브는 둥근 몸통의 유량 조절용 밸브입니다.","정답. 역류 방지 = 체크밸브","나비밸브는 원판을 돌려 여닫는 밸브입니다."],"t":"체크밸브 = 역류 방지"},"2025-1-직무일반-4":{"w":"연료유를 수급할 때 탱크를 바꾸려면 다음 탱크의 밸브를 먼저 연 뒤에 가득 찬 탱크의 밸브를 닫아야 합니다. 먼저 닫으면 관 속 압력이 급상승해 호스·관이 터지거나 기름이 넘칠 수 있습니다.","x":["스커퍼를 막아 기름이 바다로 흘러가는 것을 막아야 합니다.","측심을 자주 해 넘치지 않게 해야 합니다.","경사·트림에 주의해야 합니다.","정답(아닌 것). 다음 탱크 밸브를 먼저 열고 앞 탱크를 닫습니다."],"t":"탱크 전환 = 다음 탱크 열고 → 앞 탱크 닫기"},"2025-1-직무일반-5":{"w":"실린더 헤드 균열은 표면에 염료(침투액)를 발라 균열에 스며들게 한 뒤 현상액을 뿌려 찾는 침투탐상법(컬러 체크)으로 가장 많이 검사합니다. 재질에 상관없이 간편하게 쓸 수 있습니다.","x":["정답. 침투탐상(컬러 체크)","자분탐상은 자성체에만 쓸 수 있습니다.","와류탐상은 도체 표면 검사용으로 장비가 필요합니다.","초음파탐상은 내부 결함 검사용입니다."],"t":"표면 균열 = 침투탐상(컬러 체크)"},"2025-1-직무일반-6":{"w":"해양오염비상계획서는 총톤수 150톤 이상 유조선, 총톤수 400톤 이상 선박(유조선 외)이 갖추어야 합니다. 단, 군함과 경찰용 선박은 제외됩니다. 따라서 총톤수 600톤 어선이 대상입니다.","x":["군함은 제외됩니다.","정답. 400톤 이상 선박인 600톤 어선","유조선은 150톤 이상부터 대상입니다.","경찰용 선박은 제외됩니다."],"t":"비상계획서 = 유조선 150톤↑, 그 외 400톤↑ (군함·경찰선 제외)"},"2025-1-직무일반-7":{"w":"기름기록부는 작업한 날짜와 작업 부호·번호를 기록하고, 각 작업마다 담당 사관이 서명하며, 기재가 끝난 각 페이지에는 선장이 서명합니다. 최종 기재일부터 3년간 보존합니다.","x":["3년간 보존해야 합니다.","정답(아닌 것). 페이지마다 서명하는 사람은 선장입니다.","피예인선을 제외하고 선내에 보관합니다.","일자와 부호·번호를 기록합니다."],"t":"기름기록부 = 작업마다 담당 사관 서명, 페이지마다 선장 서명, 3년 보존"},"2025-1-직무일반-8":{"w":"폐기물을 육상 수용시설에 배출할 때는 배출 일시, 수용시설 이름, 폐기물 종류별 배출량, 책임자 서명 등을 기재합니다. 폐기물 발생원인은 기재하지 않습니다.","x":["배출 일시는 기재합니다.","책임자 서명은 기재합니다.","정답(아닌 것). 발생원인은 기재 사항이 아닙니다.","종류별 배출량은 기재합니다."],"t":"폐기물 배출 기록 = 일시·장소·종류별 양·서명"},"2025-1-직무일반-9":{"w":"선박 평형수(ballast water)에는 적재한 해역의 수중 생물이 들어 있어, 다른 해역에서 배출하면 외래종이 퍼져 생태계를 교란합니다. 그래서 평형수 처리장치 설치가 의무화되었습니다.","x":["슬러지는 기름 찌꺼기입니다.","정답. 선박 평형수 → 외래 생물 이동","배기가스는 대기오염 원인입니다.","유성 혼합물은 기름오염 원인입니다."],"t":"평형수 = 외래 생물 이동 문제"},"2025-1-직무일반-10":{"w":"기관구역 기름 배출 기준은 항해 중일 것, 기름오염방지설비가 작동 중일 것, 배출액의 기름 성분이 15[ppm] 이하일 것 등입니다. '1해리당 30리터 이하'는 유조선 화물구역 기준이며, 50리터 이상은 기준이 아닙니다.","x":["항해 중일 것은 배출 기준입니다.","설비 작동 중일 것은 배출 기준입니다.","15[ppm] 이하는 배출 기준입니다.","정답(아닌 것). 순간 배출률 50리터 이상은 기준이 아닙니다."],"t":"기관구역 배출 = 항해 중 + 설비 작동 + 15ppm 이하"},"2025-1-직무일반-11":{"w":"탈구는 강한 외력으로 관절을 이루는 뼈 끝이 관절에서 빠져나온 상태입니다.","x":["자상은 찔린 상처입니다.","골절은 뼈가 부러진 상태입니다.","정답. 관절에서 뼈가 빠짐 = 탈구","절상은 베인 상처입니다."],"t":"탈구 = 관절이 빠짐"},"2025-1-직무일반-12":{"w":"옷에 불이 붙으면 바닥에 누워 구르면서 불을 끕니다(Stop, Drop, Roll). 뛰면 공기가 공급되어 불이 더 커집니다.","x":["정답. 누워서 구른다","벽에 비비면 불을 끄기 어렵고 번질 수 있습니다.","달리면 불이 더 커집니다.","가만히 서 있으면 얼굴 쪽으로 불이 번집니다."],"t":"옷에 불 = 멈추고, 눕고, 구르기"},"2025-1-직무일반-13":{"w":"일사병 환자는 의식이 있으면 시원한 곳에서 물이나 이온 음료를 조금씩 줍니다. 흉부·복부 손상자나 의식이 없는 환자에게는 음료를 주면 안 됩니다.","x":["정답. 일사병 환자는 수분 보충","흉부 손상자는 음료를 주지 않습니다.","복부 손상자는 음료를 주지 않습니다.","무의식 환자는 질식 위험이 있어 주지 않습니다."],"t":"음료 금지 = 무의식·흉부·복부 손상"},"2025-1-직무일반-14":{"w":"방수(침수 방지)용 기자재에는 시멘트, 캔버스, 방수매트, 쐐기, 나무판 등이 있습니다. 톱밥은 기름 흡착 등에 쓰일 뿐 방수 기자재가 아닙니다.","x":["정답(아닌 것). 톱밥은 방수 기자재가 아닙니다.","시멘트 박스로 파공을 막습니다.","캔버스로 파공을 막습니다.","방수매트로 파공을 막습니다."],"t":"방수 기자재 = 시멘트·캔버스·매트·쐐기"},"2025-1-직무일반-15":{"w":"한 실린더만 배기온도가 높은 원인은 연료분사시기 늦음(후연소), 배기밸브 누설, 연료분사밸브 누설(불량 분무) 등 그 실린더의 문제입니다. 냉각수 압력 상승은 배기온도를 높이는 원인이 아닙니다.","x":["분사시기가 늦으면 후연소로 배기온도가 오릅니다.","정답(아닌 것). 냉각수 압력 상승은 원인이 아닙니다.","배기밸브가 새면 고온가스가 새어 배기온도가 오릅니다.","분사밸브가 새면 연소가 나빠져 배기온도가 오릅니다."],"t":"한 실린더 배기온도↑ = 분사시기 늦음, 밸브 누설"},"2025-1-직무일반-16":{"w":"Crash astern은 전속 전진 중 충돌 위험 등 비상시 주기관을 긴급히 후진시키는 기능입니다.","x":["위험회전수 회피 기능과 다릅니다.","정답. 전진 중 긴급 후진","부하 변동 시 정지 기능이 아닙니다.","윤활유 압력 저하 시에는 정지(셧다운)만 합니다."],"t":"Crash astern = 긴급 후진"},"2025-1-직무일반-17":{"w":"정전이 나면 비상발전기가 기동해 전원을 공급하기까지 시간이 걸리므로, 그동안 비상배터리(축전지)가 비상 조명에 즉시 전원을 공급합니다.","x":["인버터는 직류를 교류로 바꾸는 장치입니다.","컨버터는 교류를 직류로 바꾸는 장치입니다.","주발전기는 정전된 상태입니다.","정답. 즉시 공급 = 비상배터리(축전지)"],"t":"정전 직후 즉시 = 축전지"},"2025-1-직무일반-18":{"w":"선박소방설비기준상 열탐지기 1개가 담당하는 최대 바닥 면적은 37[m²], 연기탐지기는 74[m²]입니다. 탐지기 사이 거리는 열탐지기 9[m], 연기탐지기 11[m] 이내입니다.","x":["정답. 열탐지기 = 37[m²]","틀린 값입니다.","연기탐지기의 담당 면적입니다.","틀린 값입니다."],"t":"열탐지기 37m², 연기탐지기 74m²"},"2025-1-직무일반-19":{"w":"기름을 다룰 때 정전기는 유속이 빠를 때, 와류가 생길 때, 높은 곳에서 떨어질 때(낙차), 불순물(비전도성)이 섞였을 때 많이 생깁니다. 전도성 부유물이 많으면 전하가 잘 빠져나가 정전기가 덜 쌓입니다.","x":["유속이 빠르면 정전기가 많이 생깁니다.","정답(아닌 것). 전도성이 있으면 전하가 잘 빠집니다.","와류가 생기면 정전기가 많이 생깁니다.","낙차가 크면 정전기가 많이 생깁니다."],"t":"정전기 증가 = 빠른 유속·와류·낙차"},"2025-1-직무일반-20":{"w":"전기화재를 막으려면 절연저항을 규정치 이상으로 높게 유지해야 합니다. 절연저항이 낮으면 누전·단락으로 화재가 날 수 있습니다.","x":["연결부 고정은 예방법입니다.","과부하 운전 금지는 예방법입니다.","정답(옳지 않은 것). 절연저항은 규정치 이상으로 유지합니다.","접속단자 고정은 예방법입니다."],"t":"절연저항 = 높을수록 좋다"},"2025-1-직무일반-21":{"w":"밀폐된 장소의 화재는 전원·통풍을 차단하고 주변을 냉각해 확산을 막은 뒤 고정식 소화설비 등으로 끕니다. 휴대용 포말 소화기를 들고 들어가는 것은 매우 위험합니다.","x":["전원 차단은 올바른 조치입니다.","통풍 차단은 산소 공급을 막는 올바른 조치입니다.","인접 격실 냉각은 확산 방지 조치입니다.","정답(옳지 않은 것). 휴대 소화기로 진입하는 것은 위험합니다."],"t":"밀폐 구역 화재 = 차단·냉각·고정식 소화"},"2025-1-직무일반-22":{"w":"유해액체물질은 해양에 미치는 위해 정도에 따라 X류(가장 심각, 배출 금지), Y류, Z류, 기타 물질로 나눕니다.","x":["정답. X류 = 배출 금지(가장 위험)","Y류는 위해를 끼치지만 제한적 배출이 가능합니다.","Z류는 위해가 비교적 적은 물질입니다.","잠정평가물질은 아직 평가 중인 물질입니다."],"t":"X류 > Y류 > Z류 (X류 배출 금지)"},"2025-1-직무일반-23":{"w":"기관구역 기름오염방지설비는 기름여과장치, 유성찌꺼기(슬러지)탱크, 선저폐수 저장탱크, 선저폐수 농도경보장치(15ppm 경보장치) 등입니다. 혼합물탱크(슬롭탱크)는 유조선 화물구역의 설비입니다.","x":["정답(아닌 것). 혼합물탱크는 화물구역 설비입니다.","유성찌꺼기탱크는 기관구역 설비입니다.","기름여과장치는 기관구역 설비입니다.","선저폐수농도경보장치는 기관구역 설비입니다."],"t":"기관구역 = 여과장치·찌꺼기탱크·15ppm 경보장치"},"2025-1-직무일반-24":{"w":"해양오염방지검사증서의 유효기간은 5년입니다. 그 사이에 중간검사, 연차검사를 받습니다.","x":["틀린 기간입니다.","틀린 기간입니다.","틀린 기간입니다.","정답. 5년"],"t":"해양오염방지검사증서 = 5년"},"2025-1-직무일반-25":{"w":"분뇨마쇄소독장치 기술기준에는 악취 방지, 순환수장치·보조탱크 합계 150[ℓ] 이상, 육상 수용시설로 배출할 충분한 용량의 배출펌프 등이 있습니다. 발생가스 고압경보장치는 기준에 없습니다.","x":["정답(옳지 않은 것). 고압경보장치는 기준에 없습니다.","악취 발산 방지는 기준입니다.","합계 150[ℓ] 이상은 기준입니다.","배출펌프 용량 기준은 맞습니다."],"t":"분뇨마쇄소독장치 = 150ℓ 이상"},"2025-1-영어-1":{"w":"발전기 기관 = dynamo engine(또는 generator engine), 사용시간 = working hours 입니다.","x":["정답. Working hours of dynamo engine","wear는 '마모'라는 뜻입니다.","altering engine은 없는 표현입니다.","wear, altering 모두 틀립니다."],"t":"사용시간 = working hours"},"2025-1-영어-2":{"w":"청소하다 = clean(과거형 cleaned), 빌지웰 = bilge well 입니다.","x":["scale은 '물때를 제거하다'라는 뜻입니다.","정답. Cleaned bilge well.","scale, wall 모두 틀립니다.","bilge water wall은 없는 표현입니다."],"t":"청소하였다 = Cleaned"},"2025-1-영어-3":{"w":"음식을 차갑게 보관하는 장치는 냉장고(refrigerator)입니다.","x":["Compressor = 압축기","Heater = 가열기","Condenser = 응축기","정답. Refrigerator = 냉장고(냉동기)"],"t":"Refrigerator = 냉장고"},"2025-1-영어-4":{"w":"프로펠러 피치(1회전에 이론상 나아가는 거리)와 배가 실제 나아간 거리의 차이를 슬립(slip)이라 합니다.","x":["rpm = 분당 회전수","sailing mile = 항해 거리","정답. slip = 슬립","engine mile = 기관 거리(프로펠러 기준 거리)"],"t":"피치 − 실제 전진 거리 = slip"},"2025-1-영어-5":{"w":"변압기 = transformer 입니다.","x":["Transmitter = 송신기","Transducer = 변환기(센서)","Transistor = 트랜지스터","정답. Transformer = 변압기"],"t":"Transformer = 변압기"},"2025-1-영어-6":{"w":"피스톤 톱 클리어런스는 납(lead) 조각을 넣고 눌러 그 두께로 잽니다. 납 = lead 입니다.","x":["zinc = 아연","정답. lead = 납","silver = 은","copper = 구리"],"t":"톱 클리어런스 = lead(납)로 측정"},"2025-1-영어-7":{"w":"reduction gear = 감속기어 입니다. 문장은 \"감속기어 케이싱에서 기름을 모두 빼냈다\"는 뜻입니다.","x":["안전기어가 아닙니다.","역전기어는 reversing gear입니다.","정답. reduction gear = 감속기어","충전기어는 없는 용어입니다."],"t":"reduction gear = 감속기어"},"2025-1-영어-8":{"w":"소화 펌프는 모든 소화 호스 연결구에 해수(sea water)를 공급하는 원심펌프입니다.","x":["정답. sea water = 해수","bilge = 선저 폐수","fresh water = 청수","distilled water = 증류수"],"t":"Fire pump → sea water"},"2025-1-영어-9":{"w":"pneumatic = 공기압의 입니다. Pneumatic control = 공기압 제어.","x":["정답. 공기압 제어","공연비 제어가 아닙니다.","자동 제어는 automatic control입니다.","유압 제어는 hydraulic control입니다."],"t":"pneumatic = 공기압, hydraulic = 유압"},"2025-1-영어-10":{"w":"Be sure to ~ = 반드시 ~하시오, tighten = 조이다. \"호스 연결부를 확실히 조이시오.\"","x":["점검하다는 check입니다.","분리하다는 disconnect입니다.","정답. 확실히 조이시오","확인하다는 confirm입니다."],"t":"tighten = 조이다, loosen = 풀다"},"2025-1-영어-11":{"w":"adjust(조정하다)와 바꿔 쓸 수 있는 말은 regulate(조절하다)입니다.","x":["정답. Regulated = 조절했다","Ascertained = 확인했다","Inspected = 점검했다","Took = 가졌다"],"t":"adjust ≒ regulate"},"2025-1-영어-12":{"w":"worn out = 닳은(마멸된), how much = 얼마나. \"실린더 라이너가 얼마나 마멸되었습니까?\"","x":["균열은 crack입니다.","몇 개는 how many입니다.","정답. 얼마나 마멸되었습니까?","사용량을 묻는 문장이 아닙니다."],"t":"worn out = 마멸된"},"2025-1-영어-13":{"w":"\"손상된 스트레이너를 즉시 교체했다.\" 손상된 것은 교체(replace)합니다.","x":["Measured = 측정했다","Discharged = 배출했다","Adjusted = 조정했다","정답. Replaced = 교체했다"],"t":"damaged → replaced"},"2025-1-영어-14":{"w":"\"윤활유 탱크 레벨을 점검하고 필요하면 보충하시오.\" 레벨은 점검(check)합니다.","x":["Fill = 채우다","정답. Check = 점검하다","Replace = 교체하다","Overhaul = 분해 정비하다"],"t":"check level and refill"},"2025-1-영어-15":{"w":"4행정 기관의 흡입행정은 상사점(TDC)에서 시작해 하사점(BDC)에서 끝납니다.","x":["정답. TDC에서 시작, BDC에서 끝","순서가 반대입니다.","틀립니다.","틀립니다."],"t":"흡입 TDC → BDC, 압축 BDC → TDC"},"2025-1-영어-16":{"w":"vapor compression type = 증기 압축식 입니다. \"대부분의 기계식 냉동장치는 증기 압축식이다.\"","x":["정답. 증기 압축식","흡수식은 absorption type입니다.","증기 분사식은 steam jet type입니다.","냉매 분사식이 아닙니다."],"t":"vapor compression = 증기 압축식"},"2025-1-영어-17":{"w":"보일러의 강제통풍(forced draft)에는 송풍기(fan)를 씁니다.","x":["furnace = 노(연소실)","정답. fan = 송풍기","fire bricks = 내화벽돌","alarm = 경보기"],"t":"forced draft fan = 강제통풍 송풍기"},"2025-1-영어-18":{"w":"2행정 사이클은 피스톤 2행정, 즉 크랭크축 1회전(one revolution)에 한 사이클을 마칩니다.","x":["motion = 움직임","정답. revolution = 회전","blowing = 불기","arrangement = 배치"],"t":"2행정 = 1 revolution, 4행정 = 2 revolutions"},"2025-1-영어-19":{"w":"액체에 에너지를 주어 압력을 높이고 이동시키는 장치는 펌프(pump)입니다.","x":["cooler = 냉각기","정답. pump = 펌프","heater = 가열기","condenser = 응축기"],"t":"pump = 액체에 에너지를 주는 장치"},"2025-1-영어-20":{"w":"선교와 기관실 사이에 기관 명령을 주고받는 장치는 기관 텔레그래프(engine telegraph)입니다.","x":["telescope = 망원경","정답. telegraph = 기관 텔레그래프","diaphragm = 격막","tachometer = 회전계"],"t":"engine telegraph = 선교↔기관실 명령 전달"},"2025-1-영어-21":{"w":"주기관은 배 뒤쪽(stern)의 프로펠러(propeller)를 돌립니다.","x":["rudder = 타","정답. propeller = 프로펠러","stern tube = 선미관","generator = 발전기"],"t":"stern = 선미, bow = 선수"},"2025-1-영어-22":{"w":"양묘기(windlass)는 닻(anchor)을 감아올리고 내리는 갑판 기계입니다.","x":["rudder = 타(조타기가 담당)","accommodation ladder = 현문 사다리","cargo = 화물(하역 윈치·크레인이 담당)","정답. anchor = 닻"],"t":"windlass = anchor handling"},"2025-1-영어-23":{"w":"실린더 안에서 발생하는 동력은 도시마력(indicated horse power, IHP)입니다.","x":["brake horse power = 제동마력(출력축 동력)","정답. indicated horse power = 도시마력","shaft horse power = 축마력","friction horse power = 마찰마력"],"t":"IHP(실린더 안) − FHP = BHP"},"2025-1-영어-24":{"w":"단위 부피당 질량은 밀도(density)입니다.","x":["Load = 하중","Specific weight = 비중량(단위 부피당 무게)","정답. Density = 밀도","Specific volume = 비체적(단위 질량당 부피)"],"t":"density = mass / volume"},"2025-1-영어-25":{"w":"피스톤과 실린더 라이너 사이의 틈을 가스가 새지 않게 막는 것은 피스톤링(piston ring)입니다.","x":["propeller = 프로펠러","정답. piston ring = 피스톤링","piston skirt = 피스톤 스커트(측압을 받는 부분)","scavenge port = 소기공"],"t":"piston ring = gas tight sealing"},"2025-2-기관1-1":{"w":"2행정 기관은 크랭크축 1회전마다 폭발하므로 회전력 변화가 작고, 흡·배기밸브가 없어 헤드 구조가 간단하며, 출력당 무게가 가볍습니다. 그러나 소기가 불완전해 용적효율이 낮고, 폭발 횟수가 많아 열응력이 큽니다.","x":["회전력 변화가 작은 것은 장점입니다.","헤드 구조가 간단한 것은 장점입니다.","정답(옳지 않은 것). 2행정은 용적효율이 낮고 열응력이 큽니다.","출력당 중량이 작은 것은 장점입니다."],"t":"2행정 단점 = 용적효율 낮음, 열응력 큼"},"2025-2-기관1-2":{"w":"용적효율은 실제 흡입된 공기량의 비율입니다. 흡입공기 온도가 높으면 공기가 팽창해 밀도가 낮아지므로 실린더에 들어오는 공기량(질량)이 줄어 용적효율이 떨어집니다.","x":["과급기는 용적효율을 높입니다.","흡입 압력이 높으면 공기가 더 많이 들어옵니다.","정답. 흡입공기 온도가 높으면 용적효율이 떨어집니다.","흡입밸브가 크면 흡입이 잘 됩니다."],"t":"흡기 온도↑ → 공기 밀도↓ → 용적효율↓"},"2025-2-기관1-3":{"w":"압축비 = (압축용적 + 행정용적) ÷ 압축용적 = 1 + 행정용적/압축용적 입니다. 11 = 1 + Vs/Vc 이므로 Vs/Vc = 10, 즉 압축용적은 행정용적의 1/10 = 10[%]입니다.","x":["틀린 값입니다.","정답. Vc = Vs ÷ (ε − 1) = 1/10","압축비를 그대로 쓴 잘못된 값입니다.","틀린 값입니다."],"t":"압축비 ε = 1 + Vs/Vc"},"2025-2-기관1-4":{"w":"실린더 라이너 위쪽 ①(헤드·블록과 맞닿는 곳)에는 개스킷(보통 구리)을 넣어 가스가 새지 않게 하고, 아래쪽 ②에는 고무 오링을 끼워 냉각수가 새지 않게 합니다. 오링은 라이너의 열팽창을 허용합니다.","x":["정답. ① 개스킷, ② 오링","아래쪽은 냉각수 밀봉용 오링입니다.","위쪽은 개스킷입니다.","순서가 틀렸습니다."],"t":"라이너 위 = 개스킷(가스), 아래 = 오링(냉각수)"},"2025-2-기관1-6":{"w":"피스톤링은 가스의 기밀 유지, 피스톤 열을 라이너로 전달하는 냉각, 라이너 벽에 윤활유를 고르게 퍼뜨리는 윤활(오일링) 역할을 합니다. 피스톤의 부식 방지는 링의 역할이 아닙니다.","x":["열을 라이너로 전달해 냉각합니다.","오일링이 라이너의 윤활을 돕습니다.","정답(아닌 것). 부식 방지는 링의 역할이 아닙니다.","기밀 유지가 가장 중요한 역할입니다."],"t":"피스톤링 = 기밀·냉각(열전달)·윤활유 분배"},"2025-2-기관1-7":{"w":"2행정 기관에서 피스톤이 상사점 부근에 오면 압축이 끝나 연료가 분사됩니다. 배기·소기는 하사점 부근에서 열립니다.","x":["배기는 하사점 부근에서 열립니다.","소기는 하사점 부근에서 열립니다.","안전밸브는 이상 압력일 때만 열립니다.","정답. 상사점 부근 = 연료 분사"],"t":"상사점 부근 = 연료 분사, 하사점 부근 = 소기·배기"},"2025-2-기관1-8":{"w":"피스톤 재료는 가볍고, 고온 강도가 크고, 마멸이 적고, 열전도가 좋아야 합니다. 열팽창 계수는 작아야 라이너와의 틈이 크게 변하지 않아 고착을 막을 수 있습니다.","x":["마멸이 작아야 합니다.","관성력을 줄이려면 가벼워야 합니다.","고온에서 강도가 있어야 합니다.","정답(아닌 것). 열팽창 계수는 작아야 합니다."],"t":"피스톤 재료 = 열전도 크고, 열팽창 작고"},"2025-2-기관1-9":{"w":"플라이휠의 바깥 둘레를 림(rim)이라 하며, 여기에 각 실린더의 상사점·하사점, 분사시기 등이 표시되어 있어 기관 조정 때 씁니다.","x":["정답. 림 = 외주, 눈금 표시","암은 림과 보스를 잇는 부분입니다.","보스는 축에 끼워지는 중심부입니다.","원판은 해당하지 않습니다."],"t":"플라이휠 = 림(바깥) + 암 + 보스(중심)"},"2025-2-기관1-10":{"w":"실린더를 너무 냉각하면 불완전 연소, 열효율 저하, 황산 응결로 인한 저온 부식과 라이너 마멸이 생깁니다. 저온 부식의 원인은 질소산화물이 아니라 황산화물(황산)입니다.","x":["과냉하면 불완전 연소가 생깁니다.","과냉하면 열 손실로 열효율이 떨어집니다.","과냉하면 라이너 마멸이 빨라집니다.","정답(아닌 것). 저온 부식은 황 성분(황산) 때문입니다."],"t":"저온 부식 = 황산, 과냉이 원인"},"2025-2-기관1-11":{"w":"디젤 노킹은 착화지연이 길 때 생깁니다. 분사시기가 너무 빠르거나, 냉각수 온도가 낮거나, 노즐에서 연료가 새면 노킹이 생깁니다. 분사압력이 높으면 분무가 좋아져 오히려 노킹이 줄어듭니다.","x":["분사가 너무 빠르면 착화지연 중 연료가 쌓입니다.","온도가 낮으면 착화가 늦어집니다.","정답(아닌 것). 분사압력이 높으면 분무가 좋아집니다.","노즐 누설은 불량 분무로 노킹을 일으킵니다."],"t":"노킹 원인 = 분사 빠름, 저온, 불량 분무"},"2025-2-기관1-12":{"w":"급수 내관은 드럼 안으로 들어온 차가운 급수를 드럼 전체에 고르게 퍼지게 합니다. 한곳에 찬물이 들어가 생기는 온도차로 인한 부동팽창(열응력)을 막기 위해서입니다.","x":["청관제는 약품 주입 장치로 넣습니다.","산소 제거는 탈기기가 합니다.","물이 증기와 함께 나가는 것은 기수분리기가 막습니다.","정답. 온도차로 인한 부동팽창 방지"],"t":"급수 내관 = 급수를 고르게 분배(부동팽창 방지)"},"2025-2-기관1-13":{"w":"수관 보일러는 관 안의 물이 가열되므로 보유 수량이 적어 짧은 시간에 증기를 만들 수 있고, 고압·대용량에 적합합니다. 대신 급수 순도가 높아야 하고 부하 변동에 따른 압력 변화가 크며 청소가 어렵습니다.","x":["순도 높은 급수가 필요한 것은 단점입니다.","압력 변화가 큰 것은 단점입니다.","구조가 복잡해 청소·보수가 어렵습니다.","정답. 증기 발생이 빠릅니다."],"t":"수관 보일러 = 빠른 증기 발생, 고압용"},"2025-2-기관1-14":{"w":"같은 압력에서 포화증기를 더 가열해 포화온도보다 높아진 증기가 과열증기입니다. 따라서 온도가 가장 높습니다.","x":["정답. 과열증기가 가장 높습니다.","습포화증기는 포화온도입니다.","건포화증기도 포화온도입니다.","포화증기는 포화온도입니다."],"t":"과열증기 > 포화증기(습·건 모두 포화온도)"},"2025-2-기관1-15":{"w":"복수펌프는 복수기에 모인 복수를 빨아 가압한 뒤 급수가열기를 거쳐 급수펌프(또는 탈기기)로 보냅니다.","x":["정답. 복수펌프","순환수펌프는 복수기에 냉각 해수를 보냅니다.","공기이젝터는 복수기 속 공기를 뽑아냅니다.","공기분리기는 공기를 분리하는 장치입니다."],"t":"복수펌프 = 복수를 급수 계통으로"},"2025-2-기관1-16":{"w":"초음파 탐상법은 탐촉자(진동자)로 초음파를 보내 결함에서 반사되어 오는 신호를 화면으로 보고 내부 결함을 찾는 방법입니다.","x":["방사선 탐상은 X선·γ선 필름으로 봅니다.","정답. 초음파 펄스 반사 = 초음파 탐상","침투 탐상은 염료로 표면 균열을 찾습니다.","전자기 탐상은 자분·와류를 이용합니다."],"t":"초음파 = 내부 결함, 침투 = 표면 균열"},"2025-2-기관1-17":{"w":"입거 때 프로펠러는 너트 풀림, 캐비테이션 침식, 날개·보스의 균열과 부식, 날개 변형 등을 점검합니다. 보스비는 설계 값으로 입거 때 계측할 점검 사항이 아닙니다.","x":["너트 풀림을 점검합니다.","캐비테이션 침식을 점검합니다.","균열과 부식을 점검합니다.","정답(옳지 않은 것). 보스비 계측은 점검 사항이 아닙니다."],"t":"입거 시 프로펠러 = 너트·침식·균열·부식"},"2025-2-기관1-18":{"w":"프로펠러를 뺄 때는 다시 조립할 때 제자리에 오도록 프로펠러와 선미관(보스) 사이 거리, 프로펠러 캡과 타 사이 거리, 축 커플링과 격벽 사이 거리 등을 미리 재 둡니다. 날개 사이 거리는 분해와 관계없습니다.","x":["조립 위치 확인을 위해 잽니다.","조립 위치 확인을 위해 잽니다.","정답(아닌 것). 날개 사이 거리는 잴 필요가 없습니다.","축의 전후 위치 확인을 위해 잽니다."],"t":"분해 전 계측 = 축 방향 위치(선미관·타·격벽 거리)"},"2025-2-기관1-19":{"w":"캐비테이션은 날개 뒷면의 압력이 낮아져 기포가 생겼다가 터지는 현상으로 소음·진동, 날개면 침식, 추력·효율 저하를 일으킵니다. 반류(배 뒤를 따라오는 물의 흐름) 증가와는 관계없습니다.","x":["기포가 터지며 소음이 납니다.","진동이 생깁니다.","정답(옳지 않은 것). 반류 증가는 캐비테이션의 영향이 아닙니다.","날개면이 침식됩니다."],"t":"캐비테이션 = 소음·진동·침식·효율 저하"},"2025-2-기관1-20":{"w":"프로펠러가 1회전할 때 날개 위의 한 점이 축 방향으로 이론상 나아가는 거리를 피치라 합니다.","x":["슬립은 피치와 실제 전진 거리의 차이입니다.","스큐백은 날개가 회전 반대 방향으로 휜 정도입니다.","경사(레이크)는 날개가 뒤로 기운 정도입니다.","정답. 1회전 전진 거리 = 피치"],"t":"피치 = 1회전 이론 전진 거리"},"2025-2-기관1-21":{"w":"유동점은 기름이 흐를 수 있는 가장 낮은 온도입니다. 유동점이 높으면 추울 때 기름이 굳어 잘 흐르지 않습니다.","x":["온도가 오르면 점도는 낮아집니다.","세탄가가 낮으면 착화성이 나빠집니다.","정답. 유동점이 높으면 한랭 시 잘 흐르지 않습니다.","인화점이 낮으면 화재 위험이 높아집니다."],"t":"유동점 높음 = 추울 때 문제"},"2025-2-기관1-22":{"w":"점도는 기름의 끈적한 정도, 즉 흐름에 대한 저항입니다. 점도가 높을수록 잘 흐르지 않으므로 유동성과 가장 관련이 깊습니다.","x":["비중은 무게 비율입니다.","정답. 유동성 = 점도","발화점은 스스로 불이 붙는 온도입니다.","발열량은 태울 때 나오는 열량입니다."],"t":"점도 = 흐름에 대한 저항"},"2025-2-기관1-23":{"w":"디젤기관 연소가스 속 수증기는 응축되지 않고 그대로 배출되므로, 수증기 증발열을 뺀 저위발열량을 씁니다.","x":["정답(옳지 않은 것). 디젤기관은 저위발열량을 씁니다.","중유 발열량은 약 10,000[kcal/kgf]입니다.","발열량의 정의로 맞습니다.","저위발열량의 정의로 맞습니다."],"t":"기관 계산 = 저위발열량"},"2025-2-기관1-24":{"w":"윤활유는 윤활(감마), 냉각, 기밀, 청정, 방청 작용을 합니다. 분리 작용은 윤활유의 작용이 아닙니다.","x":["윤활·기밀 작용은 맞습니다.","냉각·청정 작용은 맞습니다.","정답(아닌 것). 분리 작용은 없습니다.","기밀·냉각 작용은 맞습니다."],"t":"윤활유 = 윤활·냉각·기밀·청정·방청"},"2025-2-기관2-1":{"w":"원심펌프는 송출밸브를 조여 유량을 조절할 수 있습니다. 흡입밸브를 조이면 공동현상(캐비테이션)이 생기므로 흡입밸브는 조이면 안 됩니다.","x":["정격 운전을 해야 합니다.","베어링 온도에 주의해야 합니다.","흡입밸브를 조이면 캐비테이션이 생깁니다.","정답(옳지 않은 것). 송출밸브는 조여서 유량을 조절할 수 있습니다."],"t":"원심펌프 유량 조절 = 송출밸브 (흡입밸브 조임 금지)"},"2025-2-기관2-2":{"w":"마우스링(웨어링)은 임펠러 입구와 케이싱 사이에 끼워 고압 쪽 물이 저압 쪽으로 새는 것을 막습니다. 닳으면 교체합니다.","x":["랜턴링은 글랜드 패킹 사이에 봉수를 공급합니다.","밸런스 디스크는 축방향 추력을 줄입니다.","정답. 임펠러-케이싱 누설 방지 = 마우스링","기계식 실은 축 관통부 누설을 막습니다."],"t":"마우스링 = 임펠러와 케이싱 사이"},"2025-2-기관2-3":{"w":"유공압 기호에서 원은 펌프·모터를 나타냅니다. 삼각형이 원 안쪽을 향하면 모터(에너지를 받음), 바깥을 향하면 펌프입니다. 삼각형이 속이 빈 흰색이면 공기압, 검은색이면 유압입니다. 속이 빈 삼각형이 안쪽을 향한 ㉵가 공기압 모터입니다.","x":["검은(채운) 삼각형이 안쪽을 향한 유압 모터 기호입니다.","비스듬한 화살표가 있는 가변 용량형 기호입니다.","요동형 액추에이터 기호입니다.","정답. 흰 삼각형 + 안쪽 = 공기압 모터"],"t":"삼각형 흰색 = 공기압, 검은색 = 유압 / 안쪽 = 모터"},"2025-2-기관2-4":{"w":"표준대기압은 수은주 760[mm], 수주로는 약 10.33[m]입니다. 약 10[m]입니다.","x":["수은주 높이 0.76[m]입니다.","틀린 값입니다.","틀린 값입니다.","정답. 약 10[m]"],"t":"1기압 = 760mmHg = 10.33mH₂O"},"2025-2-기관2-5":{"w":"조타장치는 조종장치(조타륜), 원동기(전동기·유압펌프), 추종장치(타가 원하는 각도에 서게 함), 타장치(타와 타두재)의 4가지로 이루어집니다.","x":["전달장치는 4대 요소가 아닙니다.","관제장치는 4대 요소가 아닙니다.","정답. 조종·원동기·추종·타장치","전동유압펌프는 원동기에 포함됩니다."],"t":"조타장치 4요소 = 조종·원동기·추종·타"},"2025-2-기관2-6":{"w":"자동장력계선장치는 계선줄의 장력을 일정 범위로 유지합니다. 줄이 끊어지지 않게 하려면 장력의 최대값을 일정값 이하로 설정해 그 이상이 되면 줄을 풀어 주게 합니다.","x":["정답. 최대 장력을 일정값 이하로","최소값 설정은 줄 끊어짐 방지와 관계없습니다.","최대값을 높게 하면 줄이 끊어질 수 있습니다.","평균값 설정 방법이 아닙니다."],"t":"줄 끊어짐 방지 = 최대 장력 제한"},"2025-2-기관2-7":{"w":"하역용 윈치는 역전장치와 제동장치가 있고, 정격하중을 정격속도로 감아올릴 수 있어야 하며, 하중에 따라 속도를 조절할 수 있어야 합니다. 정격속도로만 운전된다면 안전하게 하역할 수 없습니다.","x":["역전장치가 필요합니다.","제동장치가 필요합니다.","정답(아닌 것). 속도 조절이 가능해야 합니다.","정격하중을 정격속도로 감을 수 있어야 합니다."],"t":"하역 윈치 = 역전·제동·속도 조절"},"2025-2-기관2-10":{"w":"생물화학적 오수처리장치의 폭기탱크에는 산기기(디퓨저)를 두어 송풍기에서 온 공기를 작은 기포로 흩어 호기성 미생물에 산소를 공급합니다.","x":["정답. 공기를 기포로 분산 = 산기기","송풍기는 공기를 보내는 장치입니다.","스키머는 표면 부유물을 걷어내는 장치입니다.","용해기는 해당하지 않습니다."],"t":"폭기탱크 = 산기기로 공기 공급"},"2025-2-기관2-11":{"w":"응축기는 냉각 방식에 따라 수냉식, 공랭식, 증발식(물과 공기를 함께 사용)으로 나눕니다. 유냉식은 없습니다.","x":["정답(아닌 것). 유냉식 응축기는 없습니다.","수냉식은 선박에서 가장 많이 씁니다.","공랭식은 소형 냉동기에 씁니다.","증발식은 물의 증발열을 이용합니다."],"t":"응축기 = 수냉·공랭·증발식"},"2025-2-기관2-12":{"w":"언로더 장치는 기동 시 흡입밸브를 들어 올려 압축을 하지 않게 해 기동 부하를 줄입니다. 기동 후 윤활유 펌프 압력이 오르면 그 압력으로 언로더 피스톤이 움직여 정상 압축을 시작합니다.","x":["정답. 윤활유 압력으로 작동","흡입가스 압력으로 작동하지 않습니다.","바이패스 밸브로 작동하지 않습니다.","솔레노이드 밸브로 작동하지 않습니다."],"t":"언로더 = 윤활유 압력으로 작동"},"2025-2-기관2-13":{"w":"냉매는 증발잠열이 크고, 응축압력이 낮고, 비체적이 작고, 임계온도가 높아야 합니다. 임계온도가 낮으면 상온에서 응축(액화)시키기 어렵습니다.","x":["증발잠열이 커야 냉동효과가 큽니다.","응축압력이 낮아야 장치가 가벼워집니다.","비체적이 작아야 압축기가 작아집니다.","정답(옳지 않은 것). 임계온도는 높아야 합니다."],"t":"냉매 = 증발잠열↑, 임계온도↑, 응축압력↓"},"2025-2-기관2-14":{"w":"1냉동톤은 0[℃] 물 1톤을 24시간 동안 0[℃] 얼음으로 만드는 능력이며, 79.68 × 1000 ÷ 24 ≒ 3,320[kcal/h]입니다.","x":["틀립니다.","시간이 틀립니다.","열량이 틀립니다.","정답. 24시간, 3,320[kcal/h]"],"t":"1RT = 3,320kcal/h (24시간)"},"2025-2-기관2-15":{"w":"밖에서 안으로 열이 들어오는 여름철 조건이므로 공급 공기를 냉각하고, 습도도 높으므로 감습(제습)합니다.","x":["정답. 여름철 = 냉각 + 감습","가습은 필요하지 않습니다.","가열은 겨울철 조건입니다.","겨울철 조건입니다."],"t":"여름 = 냉각·감습, 겨울 = 가열·가습"},"2025-2-기관2-16":{"w":"탭이 부러지는 원인은 핸들에 과도한 힘을 줄 때, 구멍 바닥에 탭이 부딪칠 때, 탭과 구멍의 중심이 맞지 않을 때, 구멍이 너무 작을 때 등입니다. 탭이 소재보다 단단한 것은 정상입니다.","x":["정답(아닌 것). 탭은 원래 소재보다 단단해야 합니다.","무리한 힘은 부러짐의 원인입니다.","바닥에 부딪치면 부러집니다.","중심이 어긋나면 부러집니다."],"t":"탭 부러짐 = 과한 힘·바닥 충돌·중심 불일치"},"2025-2-기관2-17":{"w":"연삭숫돌은 숫돌 입자, 입도, 결합도, 조직, 결합제의 5가지로 표기합니다. 거칠기는 표기 항목이 아닙니다.","x":["입도(입자 크기)는 표기합니다.","조직(입자 밀도)은 표기합니다.","결합도(단단한 정도)는 표기합니다.","정답(아닌 것). 거칠기는 표기하지 않습니다."],"t":"숫돌 표기 = 입자·입도·결합도·조직·결합제"},"2025-2-기관2-18":{"w":"쇠톱 작업에서 관이 거의 다 잘렸을 때는 힘을 약하게 하고 천천히 잘라야 합니다. 세게 밀면 톱날이 부러지거나 다칠 수 있습니다.","x":["바른 자세는 맞습니다.","톱날 전체를 쓰는 것이 맞습니다.","밀 때 잘리도록 끼우는 것이 맞습니다.","정답(옳지 않은 것). 끝날 때는 힘을 줄입니다."],"t":"쇠톱 = 밀 때 절삭, 끝날 때 힘 빼기"},"2025-2-기관2-19":{"w":"실린더 라이너는 회전하는 틀에 쇳물을 부어 원심력으로 치밀하게 만드는 원심 주조법으로 만듭니다. 크랭크축은 단조, 실린더 헤드는 주조로 만듭니다.","x":["크랭크축은 단조로 만듭니다.","정답. 실린더 라이너 = 원심 주조","실린더 헤드는 주조로 만듭니다.","배기밸브는 단조로 만듭니다."],"t":"라이너 = 원심 주조, 크랭크축 = 단조"},"2025-2-기관2-20":{"w":"가스 용기 색은 산소 = 녹색, 아세틸렌 = 황색(노란색), 이산화탄소 = 청색입니다.","x":["청색은 이산화탄소 용기입니다.","틀립니다.","반대입니다.","정답. 산소 녹색, 아세틸렌 노란색"],"t":"산소 녹색, 아세틸렌 노랑"},"2025-2-기관2-21":{"w":"트림 = 선수 흘수 − 선미 흘수 = 580 − 570 = 10[cm]입니다. 선수 쪽이 더 깊으므로 선수 트림 10[cm]입니다.","x":["값이 틀립니다.","방향과 값이 틀립니다.","정답. 선수가 10[cm] 더 깊음 = 선수 트림 10[cm]","방향이 틀립니다."],"t":"더 깊은 쪽 트림"},"2025-2-기관2-22":{"w":"저속에서는 파도가 거의 생기지 않으므로 선체 표면과 물 사이의 마찰저항이 가장 큽니다. 고속일수록 조파저항이 커집니다.","x":["정답. 저속 = 마찰저항 최대","조파저항은 고속에서 커집니다.","와류저항은 상대적으로 작습니다.","공기저항은 작습니다."],"t":"저속 = 마찰저항, 고속 = 조파저항"},"2025-2-기관2-24":{"w":"중심선은 가는 1점 쇄선으로 그립니다. 2점 쇄선은 가상선, 파선은 숨은선, 굵은 실선은 외형선입니다.","x":["파선은 숨은선입니다.","실선은 외형선·치수선입니다.","정답. 중심선 = 1점 쇄선","2점 쇄선은 가상선입니다."],"t":"중심선 1점 쇄선, 가상선 2점 쇄선, 숨은선 파선"},"2025-2-기관2-25":{"w":"제3각법은 정면도를 중심으로 위에 평면도, 오른쪽에 우측면도를 배치합니다.","x":["정답. 정면도·평면도·우측면도","정면도가 빠졌습니다.","좌측면도는 주로 배치하지 않습니다.","평면도가 빠졌습니다."],"t":"제3각법 = 정면도 + 위 평면도 + 오른쪽 우측면도"},"2025-2-기관3-1":{"w":"평형 3상 교류는 세 상의 기전력 크기, 주파수, 파형이 같고 위상만 120°씩 차이 납니다.","x":["크기가 같습니다.","주파수가 같습니다.","정답(옳지 않은 것). 위상은 120°씩 다릅니다.","파형이 같습니다."],"t":"평형 3상 = 위상차 120°"},"2025-2-기관3-3":{"w":"사인파 교류의 최대값 = 실효값 × √2 입니다. 3상 교류도 각 상은 사인파이므로 최대값은 실효값의 √2배입니다.","x":["틀립니다.","실효값이 최대값의 1/√2배입니다.","정답. 최대값 = √2 × 실효값","틀립니다."],"t":"Vm = √2 V"},"2025-2-기관3-5":{"w":"옴의 법칙 I = V ÷ R = 440 ÷ 125 = 3.52 ≒ 3.5[A]입니다.","x":["틀린 값입니다.","정답. 440 ÷ 125 ≒ 3.5[A]","틀린 값입니다.","틀린 값입니다."],"t":"I = V / R"},"2025-2-기관3-6":{"w":"P = EIcosθ에서 P는 유효전력으로 단위는 [W] 또는 [kW]입니다. [kVA]는 피상전력(EI)의 단위입니다. θ는 전압과 전류의 위상차, E와 I는 실효값입니다.","x":["정답(옳지 않은 것). P의 단위는 [W]입니다.","θ는 전압과 전류의 위상차가 맞습니다.","E는 전압의 실효값이 맞습니다.","I는 전류의 실효값이 맞습니다."],"t":"EIcosθ = 유효전력 [W]"},"2025-2-기관3-7":{"w":"병렬 회로는 각 저항에 같은 전압이 걸립니다. 21÷2 + 21÷2 + 21÷3 = 10.5 + 10.5 + 7 = 28[A]입니다.","x":["틀린 값입니다.","정답. 10.5 + 10.5 + 7 = 28[A]","틀린 값입니다.","틀린 값입니다."],"t":"병렬 전체 전류 = 각 가지 전류의 합"},"2025-2-기관3-8":{"w":"콘덴서의 정전용량 단위는 패럿[F]입니다. 보통 [μF], [pF] 단위로 씁니다.","x":["헨리는 인덕턴스 단위입니다.","정답. 패럿[F]","쿨롱은 전하량 단위입니다.","볼트는 전압 단위입니다."],"t":"C[F], L[H], Q[C]"},"2025-2-기관3-9":{"w":"저항 R = ρ × 길이 ÷ 단면적 입니다. 길이 3배, 단면적 1/2배이면 저항은 3 ÷ (1/2) = 6배가 됩니다.","x":["틀린 값입니다.","틀린 값입니다.","정답. 3 × 2 = 6배","틀린 값입니다."],"t":"R ∝ 길이 / 단면적"},"2025-2-기관3-10":{"w":"콘덴서만 있는 회로에서는 전류가 전압보다 90° 앞섭니다(빠릅니다). 코일만 있는 회로에서는 전류가 90° 늦습니다.","x":["60°가 아닙니다.","코일(L) 회로의 경우입니다.","60°가 아닙니다.","정답. C 회로 = 전류가 90° 빠름"],"t":"C = 전류 앞섬, L = 전류 늦음 (90°)"},"2025-2-기관3-11":{"w":"충전된 콘덴서는 전원을 떼어도 전하가 그대로 남아 있습니다(방전 경로가 있어야 방전). 그래서 콘덴서를 만지기 전에는 반드시 방전시켜야 합니다.","x":["(+)극판에는 (+)전하, (−)극판에는 (−)전하가 모입니다.","반대 전하끼리 끌어당깁니다.","정답(옳지 않은 것). 전원을 떼어도 전하는 남아 있습니다.","면적이 넓고 간격이 좁을수록 용량이 커집니다."],"t":"충전된 콘덴서 = 전하 유지(감전 주의)"},"2025-2-기관3-12":{"w":"△결선에서는 선전류가 상전류의 √3배이고, 상전압과 선간전압은 서로 같습니다. (Y결선은 반대로 선간전압 = √3 × 상전압, 선전류 = 상전류)","x":["선전류와 상전류의 순서가 반대입니다.","정답. 선전류 = √3 × 상전류, 상전압 = 선간전압","Y결선의 관계입니다.","틀린 관계입니다."],"t":"△ = 전류 √3배, Y = 전압 √3배"},"2025-2-기관3-13":{"w":"옴의 법칙(V = IR)은 전압, 전류, 저항의 관계를 나타냅니다.","x":["줄의 법칙은 전류에 의한 발열량 법칙입니다.","패러데이의 법칙은 전자유도 법칙입니다.","정답. 옴의 법칙 V = IR","앙페르의 법칙은 전류와 자기장의 방향 법칙입니다."],"t":"옴의 법칙 V = I × R"},"2025-2-기관3-14":{"w":"접점 기호 중 가운데에 ×(가위표)가 있는 것은 열동계전기(과부하 계전기)처럼 동작 후 손으로 눌러야 복귀하는 수동복귀 접점입니다.","x":["누름버튼 스위치 접점입니다.","한시(타이머) 접점 기호입니다.","정답. × 표시 = 수동복귀 접점","한시 접점 기호입니다."],"t":"× 표시 접점 = 수동복귀(열동계전기)"},"2025-2-기관3-15":{"w":"누름버튼을 누르면 계전기 X가 동작하고, X의 a접점(X-a)이 누름버튼과 병렬로 닫혀 버튼에서 손을 떼도 X가 계속 동작합니다. 이를 자기유지회로라 합니다.","x":["인터록은 두 회로가 동시에 동작하지 않게 하는 회로입니다.","선행동작 우선회로가 아닙니다.","정답. 자기 접점으로 동작 유지 = 자기유지회로","신입신호 우선회로가 아닙니다."],"t":"버튼과 병렬 a접점 = 자기유지"},"2025-2-기관3-16":{"w":"3상 유도전동기의 3단자 중 2단자를 바꾸면 회전자기장 방향이 반대로 되어 강한 제동이 걸립니다. 이를 역상제동(플러깅)이라 합니다.","x":["정답. 두 선 교체 = 역상제동(플러깅)","발전제동은 직류를 흘리거나 저항에 전력을 소비시킵니다.","단상제동은 해당하지 않습니다.","회생제동은 전력을 전원으로 되돌립니다."],"t":"두 선 바꾸기 = 역상제동(= 역회전)"},"2025-2-기관3-17":{"w":"440[V] 회로의 절연저항은 500[V] 메거로 측정합니다. 측정 회로 전압보다 높은 정격의 메거를 씁니다.","x":["전압이 너무 낮습니다.","전압이 너무 낮습니다.","일반적으로 쓰는 정격이 아닙니다.","정답. 440[V]급 = 500[V] 메거"],"t":"440V 계통 = 500V 메거"},"2025-2-기관3-18":{"w":"동기속도 Ns = 120f ÷ P [rpm]입니다.","x":["정답. Ns = 120f / P","틀린 식입니다.","틀린 식입니다.","틀린 식입니다."],"t":"Ns = 120f / P"},"2025-2-기관3-19":{"w":"그림은 중간 탭 변압기와 다이오드 2개를 쓴 전파 정류회로입니다. 출력은 음(−)의 반파도 뒤집혀 나와 반파가 연속으로 이어진 파형이 됩니다.","x":["반파 정류의 출력(한 주기에 한 번)입니다.","평활회로를 거친 맥동 직류입니다.","정답. 전파 정류 = 반원이 연속","완전한 직류입니다."],"t":"다이오드 2개 + 중간탭 = 전파 정류"},"2025-2-기관3-20":{"w":"단상 브리지 전파 정류회로는 다이오드 4개를 다리(브리지) 모양으로 연결합니다.","x":["중간 탭 전파 정류에 쓰는 개수입니다.","정답. 브리지 = 4개","3상 브리지 정류에 쓰는 개수입니다.","틀린 개수입니다."],"t":"단상 브리지 4개, 3상 브리지 6개"},"2025-2-기관3-21":{"w":"두 다이오드가 A, B에서 X 쪽으로 향하고 X가 저항으로 접지된 다이오드 OR 회로입니다. A나 B 중 하나라도 1이면 X가 1이 되므로 ②, ③, ④입니다.","x":["둘 다 0이면 X는 0입니다.","④만이 아닙니다.","④도 X = 1입니다.","정답. 하나라도 1이면 1 (OR)"],"t":"다이오드 → 출력, 저항 접지 = OR"},"2025-2-기관3-22":{"w":"진리표에서 A, B가 모두 1일 때만 X가 0이므로 NAND 게이트입니다. AND 기호 끝에 동그라미가 붙은 ㉯입니다.","x":["AND 게이트입니다.","정답. NAND 게이트","OR 게이트입니다.","NOR 게이트입니다."],"t":"둘 다 1일 때만 0 = NAND"},"2025-2-기관3-23":{"w":"트랜지스터는 신호를 증폭하고, 스위칭 작용을 합니다. 단자는 베이스, 컬렉터, 이미터입니다. 애노드·캐소드·게이트는 SCR(사이리스터)의 단자입니다.","x":["정답. ①, ②","③은 틀립니다.","③은 틀립니다.","③은 틀립니다."],"t":"TR 단자 = B·C·E, SCR = A·K·G"},"2025-2-기관3-24":{"w":"정류된 맥동 전압을 평탄하게 하는 평활회로에는 전하를 모았다 내보내는 콘덴서(와 코일)를 씁니다.","x":["서미스터는 온도 감지 소자입니다.","정답. 평활 = 콘덴서","다이오드는 정류 소자입니다.","트랜지스터는 능동소자입니다."],"t":"평활회로 = 콘덴서"},"2025-2-기관3-25":{"w":"N형 반도체는 실리콘에 5가 원소(인, 비소 등)를 넣어 만들며, 이 불순물을 도너(donor)라 합니다. P형은 3가 원소인 억셉터를 넣습니다.","x":["도핑은 불순물을 넣는 과정입니다.","억셉터는 P형을 만드는 불순물입니다.","정공은 P형의 캐리어입니다.","정답. N형 = 도너(5가)"],"t":"N형 = 도너(5가), P형 = 억셉터(3가)"},"2025-2-기관2-8":{"w":"폐유(슬러지)는 점도가 높고 이물질이 많아 원심펌프로는 옮기기 어렵습니다. 점도가 높은 액체를 일정하게 보낼 수 있는 기어 펌프가 가장 적절합니다.","x":["정답. 고점도 폐유 = 기어 펌프","원심펌프는 고점도 액체에 적합하지 않습니다.","왕복펌프는 맥동이 커 폐유 공급에 적합하지 않습니다.","축류펌프는 대유량·저양정용입니다."],"t":"고점도 기름 이송 = 기어 펌프"},"2025-2-직무일반-1":{"w":"부식으로 얇아진 외판 두께는 한쪽 면에서 초음파를 보내 반사 시간으로 두께를 재는 초음파 두께 측정법으로 잽니다.","x":["정답. 두께 측정 = 초음파","자기탐상은 표면 균열 검사용입니다.","다이체크는 표면 균열 검사용입니다.","침투탐상은 표면 균열 검사용입니다."],"t":"두께 측정 = 초음파"},"2025-2-직무일반-2":{"w":"연료유 탱크 안은 폭발 위험이 있으므로 가스를 배제하고, 방폭등을 쓰며, 구명줄로 작업자와 보조원을 연결합니다. 탱크 주위에 일반 비상등을 켜 두는 것은 불꽃의 원인이 될 수 있어 적절하지 않습니다.","x":["가스를 미리 배제해야 합니다.","방폭등을 써야 합니다.","정답(옳지 않은 것). 일반 전등은 폭발 위험이 있습니다.","구명줄은 필요합니다."],"t":"탱크 작업 = 가스 배제·방폭등·구명줄"},"2025-2-직무일반-3":{"w":"그림은 관을 세 방향으로 나누는 T자 모양 부속품인 티(tee)입니다.","x":["정답. T자 모양 = 티","니플은 짧은 양쪽 수나사 관입니다.","엘보는 방향을 90°·45°로 꺾는 부속품입니다.","플러그는 관 끝을 막는 마개입니다."],"t":"티 = 분기, 엘보 = 방향 전환"},"2025-2-직무일반-4":{"w":"수급 전에는 스커퍼 폐쇄, 신호기(B기)·등화 확인, 오염방제자재와 소화기 비치 등을 준비합니다. 기름기록부는 수급이 끝난 뒤에 작성합니다.","x":["정답(아닌 것). 기름기록부는 수급 후 작성합니다.","스커퍼 폐쇄는 수급 전 확인 사항입니다.","신호기·등화는 수급 전 확인 사항입니다.","방제자재·소화기 비치는 수급 전 준비 사항입니다."],"t":"기름기록부 = 작업 후 기록"},"2025-2-직무일반-5":{"w":"운전 중인 전동기는 베어링 온도, 전류(과부하 여부), 이상 진동·소음 등을 주기적으로 점검합니다. 회전 방향은 설치·정비 후 처음 운전할 때 확인하는 사항입니다.","x":["정답(아닌 것). 회전 방향은 주기적 점검 대상이 아닙니다.","베어링 온도는 점검합니다.","전류는 점검합니다.","진동·소음은 점검합니다."],"t":"운전 중 점검 = 온도·전류·진동·소음"},"2025-2-직무일반-6":{"w":"유성찌꺼기(슬러지)는 청정기 폐유, 기름여과장치에서 분리된 폐유, 탱크 드레인 기름 등 더 이상 쓸 수 없는 기름입니다. 저장탱크에 보관 중인 윤활유는 아직 쓸 수 있는 기름입니다.","x":["여과장치에서 분리된 폐유는 유성찌꺼기입니다.","정답(아닌 것). 보관 중인 윤활유는 사용할 기름입니다.","탱크 드레인 기름은 유성찌꺼기입니다.","청정 폐유는 유성찌꺼기입니다."],"t":"유성찌꺼기 = 청정·여과·드레인 폐유"},"2025-2-직무일반-7":{"w":"유성찌꺼기는 바다에 버릴 수 없고, 육상 수용시설에 넘기거나 승인된 소각설비로 소각합니다.","x":["유성찌꺼기는 해양 배출이 금지됩니다.","선저폐수는 여과 후 배출하거나 육상에 넘깁니다.","혼합물과 함께 배출할 수 없습니다.","정답. 승인된 소각설비로 유성찌꺼기 소각"],"t":"유성찌꺼기 = 소각 또는 육상 처리"},"2025-2-직무일반-8":{"w":"오염물질 배출 신고 사항은 배출 일시·장소·원인, 사고선박의 명칭·종류·규모, 배출 추정량과 확산 상황, 응급조치 상황 등입니다. 본선의 훈련 주기는 신고 사항이 아닙니다.","x":["선박의 명칭·종류·규모는 신고합니다.","일시·장소·원인은 신고합니다.","정답(옳지 않은 것). 훈련 주기는 신고 사항이 아닙니다.","추정량·확산·응급조치는 신고합니다."],"t":"배출 신고 = 언제·어디서·왜·얼마나·조치"},"2025-2-직무일반-9":{"w":"선박 소각설비에는 연소실 온도측정장치, 폐유·연료 분무압력계, 배기가스 중 일산화탄소·이산화탄소·산소 농도 연속측정장치 등을 갖춥니다. 열량계는 해당하지 않습니다.","x":["정답(아닌 것). 열량계는 필요 없습니다.","온도측정장치는 필요합니다.","분무압력계는 필요합니다.","가스 농도 측정장치는 필요합니다."],"t":"소각설비 = 온도·분무압력·가스농도 측정"},"2025-2-직무일반-10":{"w":"선박에너지효율 관련 보고 사항은 연료유 종류와 사용량, 운항거리, 운항시간 등입니다. 윤활유는 보고 대상이 아닙니다.","x":["운항거리는 보고합니다.","운항시간은 보고합니다.","정답(아닌 것). 윤활유 사용량은 보고하지 않습니다.","연료유 종류와 사용량은 보고합니다."],"t":"에너지효율 보고 = 연료유·거리·시간"},"2025-2-직무일반-11":{"w":"쇼크가 오면 혈압과 체온이 떨어지고, 맥박은 빠르고 약하며, 호흡이 얕고 불규칙하고, 식은땀이 나고 피부가 창백해집니다.","x":["정답(아닌 것). 혈압과 체온은 떨어집니다.","호흡이 약하고 불규칙합니다.","맥박이 빠르고 약합니다.","식은땀과 창백한 피부가 나타납니다."],"t":"쇼크 = 혈압↓·체온↓·맥박 빠르고 약함"},"2025-2-직무일반-13":{"w":"화재 연기를 피하려면 젖은 수건으로 입과 코를 막고 자세를 낮춰 대피합니다. 젖은 수건이 연기 입자와 뜨거운 공기를 걸러 줍니다.","x":["손으로는 걸러지지 않습니다.","마른 수건보다 젖은 수건이 효과적입니다.","정답. 젖은 수건","화장지는 효과가 적습니다."],"t":"연기 = 젖은 수건 + 낮은 자세"},"2025-2-직무일반-14":{"w":"외판에 작은 구멍이 나면 나무 쐐기, 방수 매트, 시멘트 등으로 막아 방수합니다.","x":["작은 파공으로 바로 퇴선하지 않습니다.","정답. 쐐기 등으로 방수","걸레와 테이프로는 수압을 견디지 못합니다.","전원 차단은 응급 방수 조치가 아닙니다."],"t":"작은 파공 = 쐐기로 막기"},"2025-2-직무일반-15":{"w":"보일러 본체에는 부식, 점식(피팅), 균열, 과열로 인한 변형 등의 손상이 생깁니다. 노킹은 기관의 이상 연소 현상입니다.","x":["피팅(점식)은 보일러 손상입니다.","부식은 보일러 손상입니다.","정답(아닌 것). 노킹은 기관에서 생기는 현상입니다.","균열은 보일러 손상입니다."],"t":"보일러 손상 = 부식·피팅·균열·과열"},"2025-2-직무일반-16":{"w":"수면 아래에서 기름이 새면 새는 탱크를 찾고, 그 탱크의 기름을 다른 탱크로 옮기고, 오일펜스로 확산을 막습니다. 탱크 안에 유처리제를 뿌리는 것은 누출을 늦추지 못하며 잘못된 조치입니다.","x":["누출 탱크를 찾아야 합니다.","기름을 다른 탱크로 옮겨 수위를 낮춥니다.","오일펜스로 확산을 막습니다.","정답(적절하지 않은 것). 탱크에 유처리제를 뿌리지 않습니다."],"t":"누유 = 찾고·옮기고·오일펜스"},"2025-2-직무일반-17":{"w":"기관실 화재 시 비상정지 스위치로 연료유 밸브(급속차단밸브)를 닫고, 연료유 펌프와 통풍 팬을 멈춰 연료와 산소 공급을 끊습니다. 청수펌프는 해당하지 않습니다.","x":["유류밸브를 차단합니다.","통풍 팬을 정지합니다.","유류펌프를 정지합니다.","정답(아닌 것). 청수펌프는 정지 대상이 아닙니다."],"t":"비상정지 = 연료 차단 + 통풍 정지"},"2025-2-직무일반-18":{"w":"수소, 아세틸렌, 프로판은 불이 붙거나 폭발하는 가연성 가스입니다. 프레온은 불연성 냉매 가스입니다.","x":["수소는 폭발성 가스입니다.","아세틸렌은 폭발성 가스입니다.","프로판은 폭발성 가스입니다.","정답(아닌 것). 프레온은 불연성입니다."],"t":"프레온 = 불연성 냉매"},"2025-2-직무일반-19":{"w":"가벼운 기름일수록 인화점이 낮습니다. 경유(약 50~70[℃])가 중유나 윤활유보다 인화점이 낮습니다.","x":["정답. 경유가 가장 낮습니다.","윤활유는 인화점이 높습니다(약 200[℃] 이상).","A 중유는 경유보다 높습니다.","C 중유는 더 높습니다."],"t":"가벼운 기름일수록 인화점 낮음"},"2025-2-직무일반-20":{"w":"아세틸렌 실린더는 안의 아세톤이 흘러나오지 않도록 반드시 세워서 사용합니다.","x":["기름·먼지를 미리 치워야 합니다.","통풍이 잘 되게 해야 합니다.","가연물은 제거해야 합니다.","정답(옳지 않은 것). 아세틸렌 실린더는 세워서 사용합니다."],"t":"아세틸렌 용기 = 세워서"},"2025-2-직무일반-21":{"w":"기관구역 고정식 CO₂ 소화설비는 2분 이내에 CO₂ 총량의 85[%] 이상을 방출해야 합니다.","x":["비율이 틀렸습니다.","정답. 2분 이내 85[%]","시간과 비율이 틀렸습니다.","시간이 틀렸습니다."],"t":"기관실 CO₂ = 2분 이내 85%"},"2025-2-직무일반-22":{"w":"임시검사는 용도 변경, 무선설비 새로 설치, 선박 시설의 개조·수리 등을 할 때 받습니다. 검사증서 유효기간이 끝나면 정기검사를 받아야 합니다.","x":["용도 변경은 임시검사 대상입니다.","정답(아닌 것). 유효기간 만료는 정기검사 대상입니다.","무선설비 신설은 임시검사 대상입니다.","강도·수밀성·방화성에 관한 개조는 임시검사 대상입니다."],"t":"유효기간 만료 = 정기검사"},"2025-2-직무일반-23":{"w":"해양안전심판원이 해기사에게 내리는 징계는 면허의 취소, 업무정지(1개월~1년), 견책의 3가지입니다.","x":["견책은 징계입니다.","면허 취소는 징계입니다.","정답(아닌 것). 권고는 징계가 아닙니다.","업무정지는 징계입니다."],"t":"징계 = 취소·업무정지·견책"},"2025-2-직무일반-24":{"w":"유조선이 아닌 선박의 기관구역용 폐유저장용기는 총톤수 5~10톤 미만 20[ℓ], 10~30톤 미만 60[ℓ], 30~50톤 미만 100[ℓ], 50~100톤 미만 200[ℓ]입니다.","x":["5톤 이상 10톤 미만 기준입니다.","10톤 이상 30톤 미만 기준입니다.","30톤 이상 50톤 미만 기준입니다.","정답. 50톤 이상 100톤 미만 = 200[ℓ]"],"t":"폐유저장용기 20 → 60 → 100 → 200ℓ"},"2025-2-직무일반-25":{"w":"해양환경관리법상 기름은 원유, 석유제품(중유·경유·윤활유 등), 이들을 함유한 액체 혼합물, 폐유를 말합니다. 석유가스는 제외됩니다.","x":["원유는 기름입니다.","중유는 기름입니다.","윤활유는 기름입니다.","정답(아닌 것). 석유가스는 제외됩니다."],"t":"기름에서 석유가스 제외"},"2025-2-영어-1":{"w":"S/B = Stand by(기관 준비) 입니다. \"군산 출항을 위해 기관을 스탠바이했다.\"","x":["정답. S/B = Stand by","틀린 표현입니다.","틀린 표현입니다.","틀린 표현입니다."],"t":"S/B = Stand by, F.W.E. = Finished With Engine"},"2025-2-영어-2":{"w":"\"모든 흡기밸브를 ( )할 것\" — lapped(래핑), examined(검사), renewed(교체)는 밸브 작업으로 알맞지만 charged(충전)는 맞지 않습니다.","x":["lapped = 갈아 맞춤(래핑)","examined = 검사","정답(적절하지 않은 것). charged = 충전","renewed = 교체"],"t":"lap = 밸브 맞춤 연마"},"2025-2-영어-3":{"w":"Relief valve(릴리프 밸브)는 압력이 설정값 이상으로 오르면 열려 과도한 압력 상승을 막습니다.","x":["압력 저하 방지가 아닙니다.","온도 상승 방지가 아닙니다.","정답. 과도한 압력 상승 방지","온도 저하 방지가 아닙니다."],"t":"Relief valve = 과압 방지"},"2025-2-영어-4":{"w":"Thermocouple(열전대)은 온도를 재는 센서입니다. Manometer(액주 압력계), Barometer(기압계), Bourdon tube(부르동관 압력계)는 모두 압력 측정용입니다.","x":["Manometer = 압력계","Barometer = 기압계","정답(관계없는 것). Thermocouple = 열전대(온도)","Bourdon tube = 부르동관 압력계"],"t":"Thermocouple = 온도 측정"},"2025-2-영어-6":{"w":"배 밑바닥 옆의 해수 흡입 상자를 sea chest(씨 체스트)라 합니다.","x":["rose box = 빌지 흡입구의 여과상자","mud box = 빌지관의 진흙 거르개","정답. sea chest = 해수 흡입함","suction strainer = 흡입 여과기"],"t":"sea chest = 해수 흡입구"},"2025-2-영어-7":{"w":"\"새는 관을 수리했다.\" correct(바로잡다) ≒ repair(수리하다).","x":["Received = 받았다","정답. Repaired = 수리했다","Adjusted = 조정했다","Cleaned = 청소했다"],"t":"corrected ≒ repaired"},"2025-2-영어-8":{"w":"fire bricks = 내화벽돌. \"보일러 노 안의 깨진 내화벽돌을 교체했다.\"","x":["정답. 내화벽돌","방화벽은 fire wall입니다.","방음벽돌이 아닙니다.","화로는 furnace입니다."],"t":"fire brick = 내화벽돌"},"2025-2-영어-9":{"w":"구멍에 암나사를 내는 공구는 탭(tap)입니다.","x":["file = 줄","정답. tap = 탭(암나사 가공)","bite = 선반 바이트","reamer = 리머(구멍 다듬질)"],"t":"tap = 암나사, die = 수나사"},"2025-2-영어-10":{"w":"중간축 = intermediate shaft, \"~할 것\" = to be ~ed. 따라서 \"Intermediate shaft bearing to be overhauled and surveyed.\"","x":["tail shaft는 프로펠러축이고, 과거형입니다.","tail shaft는 프로펠러축입니다.","과거형(~했다)입니다.","정답. 중간축 + to be ~ed(~할 것)"],"t":"intermediate shaft = 중간축, to be ~ed = ~할 것"},"2025-2-영어-11":{"w":"기관 회전수는 tachometer(회전계)로 잽니다.","x":["thermometer = 온도계","manometer = 압력계","정답. tachometer = 회전계","dynamometer = 동력계"],"t":"tachometer = 회전계"},"2025-2-영어-12":{"w":"port = 좌현, starboard = 우현. \"연료유를 좌현 5번 탱크에서 우현 2번 탱크로 이송했다.\"","x":["좌우가 반대입니다.","방향이 반대입니다.","정답. 좌현 5번 → 우현 2번","틀립니다."],"t":"port = 좌현, starboard = 우현"},"2025-2-영어-13":{"w":"hydrostatic test = 수압 시험 = water pressure test 입니다.","x":["humidity test = 습도 시험","정답. water pressure test = 수압 시험","tension test = 인장 시험","deformation test = 변형 시험"],"t":"hydrostatic test = 수압 시험"},"2025-2-영어-14":{"w":"보일러 점검표에서 F.O. cut off condition(연료유 차단 상태, 안전장치 작동 시험)은 3개월마다 점검하는 항목입니다. 수위 경보·화염 감지기 등은 더 자주 점검합니다.","x":["원격 수면계는 더 자주 점검합니다.","버너 화염 감지기는 더 자주 점검합니다.","정답. F.O. cut off condition = 3개월","수위 경보는 더 자주 점검합니다."],"t":"F.O. cut off = 연료 차단 시험"},"2025-2-영어-15":{"w":"발전기 병렬 운전(동기화)은 전압, 주파수, 위상을 맞추는 것입니다. 전류는 맞출 조건이 아닙니다.","x":["전압을 맞춥니다.","위상을 맞춥니다.","정답(적절하지 않은 것). 전류는 동기화 조건이 아닙니다.","주파수를 맞춥니다."],"t":"병렬운전 조건 = 전압·주파수·위상"},"2025-2-영어-16":{"w":"높은 온도를 재는 온도계는 pyrometer(고온계)입니다.","x":["정답. Pyrometer = 고온계","Viscometer = 점도계","Hygrometer = 습도계","Hydrometer = 비중계"],"t":"pyro = 불, 고온"},"2025-2-영어-17":{"w":"123,000 = one hundred twenty three thousand, [m³] = cubic meters 입니다.","x":["billion은 10억입니다.","billion, square 모두 틀립니다.","정답. 123,000 cubic meters","square meters는 [m²]입니다."],"t":"m³ = cubic meter, m² = square meter"},"2025-2-영어-18":{"w":"내연기관의 이론 사이클은 오토(정적) 사이클, 디젤(정압) 사이클, 사바테(복합) 사이클입니다.","x":["정답. Sabathe cycle = 복합 사이클","Rankine cycle = 증기 사이클","Reheat cycle = 재열 사이클(증기)","Refrigeration cycle = 냉동 사이클"],"t":"내연기관 = 오토·디젤·사바테"},"2025-2-영어-19":{"w":"피스톤과 실린더 벽 사이의 압력 기밀을 유지하는 것은 piston ring(압축링)입니다.","x":["oil ring은 윤활유를 긁어내는 링입니다.","정답. piston ring","seal ring은 일반적인 밀봉 링입니다.","rubber ring은 고무 링입니다."],"t":"piston ring = pressure tight seal"},"2025-2-영어-20":{"w":"IHP = Indicated Horse Power = 지시마력(도시마력)입니다. 기계효율 = BHP ÷ IHP.","x":["제동마력은 BHP입니다.","전달마력은 DHP입니다.","유효마력은 EHP입니다.","정답. IHP = 지시(도시)마력"],"t":"기계효율 = BHP / IHP"},"2025-2-영어-21":{"w":"공기를 압축하면 온도가 올라갑니다. 디젤기관은 이 압축열로 연료를 착화합니다.","x":["부피는 줄어듭니다.","정답. 압축하면 temperature(온도) 상승","viscosity = 점도","area = 면적"],"t":"압축 → 온도 상승(디젤 착화 원리)"},"2025-2-영어-22":{"w":"두 격벽 사이의 빈 공간으로 인접 구획을 분리하는 것은 cofferdam(코퍼댐)입니다.","x":["정답. cofferdam = 격리 공간","sky light = 천창","watertight door = 수밀문","double bottom tank = 이중저 탱크"],"t":"cofferdam = 격벽 사이 빈 공간"},"2025-2-영어-23":{"w":"액체를 낮은 곳에서 높은 곳으로 올리는 기계는 pump입니다.","x":["generator = 발전기","heater = 가열기","transformer = 변압기","정답. pump = 펌프"],"t":"pump = raise liquids"},"2025-2-영어-24":{"w":"수관 보일러는 관 속으로 물(급수, feed water)이 지나가고, 관 밖을 연소가스가 가열합니다. (연관 보일러는 반대)","x":["해수는 보일러수로 쓰지 않습니다.","연관 보일러에서 관 속으로 지나가는 것입니다.","정답. 수관 보일러 = 관 속에 물","과열증기는 과열기에서 만들어집니다."],"t":"수관 = 관 속 물, 연관 = 관 속 가스"},"2025-2-영어-25":{"w":"움직이는 부품 사이에 유막을 만드는 것은 윤활유 계통(lubricating oil system)의 주된 기능입니다.","x":["fuel oil system = 연료유 계통","control oil system = 제어유 계통","hydraulic oil system = 유압 계통","정답. lubricating oil system = 윤활유 계통"],"t":"oil film = lubricating oil"},"2025-3-기관1-1":{"w":"지시열효율은 실린더 안에서 연료의 열이 얼마나 일(지시일)로 바뀌는지를 나타냅니다. 연소 개선, 냉각손실 감소, 유효행정 증가 등으로 높아집니다. 기계효율은 지시마력 중 마찰 손실을 뺀 비율로, 지시열효율과는 별개입니다.","x":["유효행정이 늘면 팽창일이 늘어납니다.","연소가 좋아지면 지시열효율이 높아집니다.","정답(옳지 않은 것). 기계효율은 지시열효율과 관계없습니다.","냉각손실이 줄면 지시열효율이 높아집니다."],"t":"제동열효율 = 지시열효율 × 기계효율"},"2025-3-기관1-2":{"w":"압축비 = (행정부피 + 압축부피) ÷ 압축부피 = (1,900 + 100) ÷ 100 = 20입니다. 회전수는 계산에 필요 없습니다.","x":["틀린 값입니다.","틀린 값입니다.","행정부피 ÷ 압축부피만 한 값입니다.","정답. 2,000 ÷ 100 = 20"],"t":"압축비 = (Vs + Vc) / Vc"},"2025-3-기관1-3":{"w":"메인 베어링은 과부하, 윤활유 부족, 크랭크축 중심선 어긋남, 베어링 틈새 부적당 등으로 발열합니다. 점도지수가 큰 윤활유는 온도가 변해도 점도 변화가 작은 좋은 윤활유입니다.","x":["과부하는 발열 원인입니다.","윤활유 부족은 발열 원인입니다.","중심선 어긋남은 편하중으로 발열 원인입니다.","정답(아닌 것). 점도지수가 큰 윤활유는 좋은 윤활유입니다."],"t":"점도지수 큼 = 온도에 따른 점도 변화 작음(좋음)"},"2025-3-기관1-4":{"w":"2행정 기관에서 피스톤이 상사점 부근에 오면 압축이 끝나 연료가 분사됩니다. 소기공과 배기밸브는 하사점 부근에서 열립니다.","x":["정답. 상사점 부근 = 연료 분사","소기공은 하사점 부근에서 열립니다.","배기밸브는 하사점 전에 열립니다.","안전밸브는 이상 압력 때만 열립니다."],"t":"상사점 = 분사, 하사점 = 소기·배기"},"2025-3-기관1-6":{"w":"피스톤 재료는 마멸에 강하고, 고온 강도가 크고, 열전도가 좋으며 열팽창이 작아야 합니다. 열팽창이 크면 피스톤이 라이너에 고착될 수 있습니다.","x":["마멸에 강해야 합니다.","실린더와 비슷한 열전도 특성이 좋습니다.","고온·고압 강도가 필요합니다.","정답(옳지 않은 것). 열팽창은 작아야 합니다."],"t":"피스톤 = 열팽창 작게"},"2025-3-기관1-7":{"w":"피스톤링은 기밀 유지, 열 전달(냉각), 유막 형성(윤활유 분배)을 합니다. 측압(피스톤을 라이너 쪽으로 미는 힘)은 피스톤 스커트(트렁크 피스톤)나 크로스헤드가 받습니다.","x":["피스톤의 열을 라이너로 전달합니다.","윤활유 유막을 만듭니다.","정답(아닌 것). 측압은 스커트·크로스헤드가 받습니다.","기밀 유지를 합니다."],"t":"측압 = 피스톤 스커트(크로스헤드)"},"2025-3-기관1-8":{"w":"6실린더 4행정 기관은 120°마다 폭발합니다. 착화순서 1→5→3→6→2→4에서 1번 다음 2번은 네 칸 뒤이므로 120° × 4 = 480° 회전해야 합니다.","x":["바로 다음 실린더(5번)까지의 각도입니다.","틀린 값입니다.","세 칸(6번) 뒤의 각도입니다.","정답. 네 칸 × 120° = 480°"],"t":"6실린더 4행정 = 120° 간격, 칸 수 × 120°"},"2025-3-기관1-9":{"w":"밸런스 웨이트(평형추)는 크랭크의 회전 질량과 반대쪽에 달아 불균형한 원심력을 없애 진동을 줄이고 회전을 고르게 합니다.","x":["개폐작용 방지가 목적이 아닙니다.","충격력 흡수가 목적이 아닙니다.","중심선 수정용이 아닙니다.","정답. 진동 감소와 원활한 회전"],"t":"밸런스 웨이트 = 불균형 원심력 제거"},"2025-3-기관1-10":{"w":"압축비가 낮으면 압축 온도가 낮아 착화지연이 길어지고, 후연소가 생기며, 연료소비량이 늘어납니다. 평균유효압력은 오히려 낮아집니다.","x":["후연소가 길어집니다.","착화지연이 길어집니다.","연료소비량이 늘어납니다.","정답(옳지 않은 것). 평균유효압력은 낮아집니다."],"t":"압축비↓ → 착화 늦음, 출력↓"},"2025-3-기관1-11":{"w":"보슈식 연료분사펌프는 실린더마다 1대씩 있고, 캠이 플런저를 밀며, 토출밸브가 있습니다. 분사량은 플런저를 돌려 나선형 홈(리드)의 위치를 바꿔 분사 종료 시기를 조정해 바꿉니다.","x":["토출밸브가 있습니다.","캠으로 플런저를 움직입니다.","정답(옳지 않은 것). 분사량은 분사 종료 시기(유효행정)로 조정합니다.","실린더마다 1대씩 설치됩니다."],"t":"보슈식 = 플런저 회전(래크)으로 분사량 조정"},"2025-3-기관1-12":{"w":"역화는 점화할 때 노 안에 남아 있던 유증기·가스가 한꺼번에 폭발해 불꽃이 밖으로 튀어나오는 현상입니다. 점화 전에 송풍기로 노 안을 충분히 환기(프리퍼지)해야 합니다.","x":["스케일 제거는 전열 효율과 관계있습니다.","수위 확인은 보일러 안전 사항이지만 역화 방지와는 다릅니다.","증기밸브 확인은 역화 방지와 관계없습니다.","정답. 점화 전 노 내 가스 배제(프리퍼지)"],"t":"역화 방지 = 점화 전 프리퍼지"},"2025-3-기관1-14":{"w":"포밍은 보일러수 속 불순물(기름, 부유물 등) 때문에 기포가 터지지 않고 수면에 거품층을 이루어 증기와 함께 넘어가는 현상입니다.","x":["정답. 거품이 쌓여 넘어감 = 포밍","기수분리는 증기에서 물방울을 분리하는 것입니다.","프라이밍은 물방울이 증기와 함께 튀어 나가는 현상입니다.","스플래시는 해당하지 않습니다."],"t":"포밍 = 거품, 프라이밍 = 물방울 비산"},"2025-3-기관1-17":{"w":"겉보기 슬립 = (프로펠러 속도 − 배의 속도) ÷ 프로펠러 속도 = (V_P − V) / V_P 입니다.","x":["정답. (V_P − V) / V_P","부호와 분모가 틀렸습니다.","틀린 식입니다.","틀린 식입니다."],"t":"슬립 = (이론 속도 − 실제 속도) / 이론 속도"},"2025-3-기관1-18":{"w":"프로펠러 속도[m/h] = 피치 × 분당 회전수 × 60 입니다. 1해리 = 1,852[m]이므로 노트 = (P × N × 60) ÷ 1,852 입니다.","x":["초당 속도[m/s]입니다.","60을 곱하지 않았습니다.","틀린 식입니다.","정답. (P × N × 60) / 1,852"],"t":"1노트 = 1,852m/h"},"2025-3-기관1-19":{"w":"프로펠러를 분해하기 전에는 재조립 위치를 확인하기 위해 프로펠러와 선미관 거리, 축 커플링과 격벽 거리, 프로펠러 캡과 타 사이 거리 등을 잽니다. 감속기어와의 거리는 재지 않습니다.","x":["재야 하는 곳입니다.","정답(아닌 것). 감속기어와의 거리는 재지 않습니다.","재야 하는 곳입니다.","재야 하는 곳입니다."],"t":"분해 전 계측 = 선미관·격벽·타와의 거리"},"2025-3-기관1-20":{"w":"축계 접지장치는 슬립링과 브러시로 축과 선체를 전기적으로 연결해 전위차를 낮추고 전식(전기 부식)을 막습니다. 브러시 수는 전류용량이 아니라 축지름 등 설치 조건에 따라 정합니다.","x":["정답(옳지 않은 것). 브러시 수는 전류용량으로 결정하지 않습니다.","접촉저항이 작아야 합니다.","전위차를 낮춰 부식을 막습니다.","브러시와 슬립링이 접촉합니다."],"t":"축 접지장치 = 슬립링 + 브러시, 전식 방지"},"2025-3-기관1-21":{"w":"왕복 거리 48해리 ÷ 12노트 = 4시간. 연료 4시간 × 10[ℓ] = 40[ℓ]. 예비 20[%] 8[ℓ]를 더하면 48[ℓ]입니다.","x":["정답. 40 + 8 = 48[ℓ]","틀린 값입니다.","틀린 값입니다.","틀린 값입니다."],"t":"필요 연료 = 시간 × 시간당 소비량 × 1.2"},"2025-3-기관1-22":{"w":"연료의 주성분 중 단위 무게당 발열량이 가장 큰 것은 수소(약 34,000[kcal/kg])이고, 탄소는 약 8,100[kcal/kg]입니다.","x":["탄소는 수소보다 발열량이 작습니다.","유황은 발열량이 작고 부식의 원인입니다.","정답. 수소","질소는 타지 않습니다."],"t":"발열량 수소 > 탄소"},"2025-3-기관1-24":{"w":"윤활유는 점도지수가 크고, 응고점이 낮고, 항유화성이 크며, 탄화되기 어려워야 합니다.","x":["점도지수는 커야 합니다.","정답. 응고점이 낮아야 합니다.","항유화성은 커야 합니다.","탄화가 어려워야 합니다."],"t":"윤활유 = 점도지수↑, 응고점↓, 항유화성↑"},"2025-3-기관1-25":{"w":"두 마찰면 사이에 두꺼운 유막이 있어 완전히 떨어진 상태를 완전윤활(유체윤활)이라 합니다.","x":["경계윤활은 유막이 아주 얇은 상태입니다.","극압윤활은 고하중에서 극압 첨가제로 윤활하는 상태입니다.","정답. 완전 분리 = 완전(유체)윤활","불완전윤활은 부분적으로 접촉하는 상태입니다."],"t":"완전윤활 > 불완전윤활 > 경계윤활"},"2025-3-기관2-1":{"w":"기름(유류) 이송에는 점도가 높은 액체를 잘 보내는 기어펌프, 나사펌프, 베인펌프 등을 씁니다. 기포펌프(에어리프트)는 공기를 불어넣어 물을 끌어올리는 펌프로 기름용이 아닙니다.","x":["정답(아닌 것). 기포펌프는 유류용이 아닙니다.","기어펌프는 유류용입니다.","나사펌프는 유류용입니다.","베인펌프는 유류용입니다."],"t":"유류 펌프 = 기어·나사·베인"},"2025-3-기관2-2":{"w":"공기는 열전달이 나쁘므로 냉각관 바깥에 핀을 붙여 공기와 닿는 표면적을 늘려 냉각 효과를 높입니다.","x":["파손 방지가 목적이 아닙니다.","미관이 목적이 아닙니다.","정답. 표면적 증대","공기 흐름을 좋게 하려는 목적이 아닙니다."],"t":"핀(fin) = 표면적 증대"},"2025-3-기관2-3":{"w":"왕복펌프는 피스톤 왕복 운동 때문에 송출량이 맥동합니다. 송출 쪽에 공기실을 달아 공기의 압축·팽창으로 맥동을 줄입니다.","x":["제트펌프는 공기실이 필요 없습니다.","기어펌프는 맥동이 작습니다.","원심펌프는 맥동이 거의 없습니다.","정답. 왕복펌프 = 공기실"],"t":"공기실 = 왕복펌프 맥동 방지"},"2025-3-기관2-4":{"w":"사이드 스러스터는 선박을 옆으로 움직이는 추진장치로, 선수나 선미 부근의 수면 아래에 옆으로 뚫린 터널 안에 설치합니다.","x":["갑판에 설치하지 않습니다.","기관실 안쪽이 아닙니다.","크랭크축 끝이 아닙니다.","정답. 선수·선미 부근 수면 아래"],"t":"사이드(바우) 스러스터 = 수면 아래 터널"},"2025-3-기관2-5":{"w":"하역용 윈치는 역전·제동 장치가 있어야 하고, 하중에 따라 속도를 넓은 범위로 조절할 수 있어야 합니다.","x":["역전 장치가 필요합니다.","제동 장치가 필요합니다.","정답(옳지 않은 것). 속도 조절 범위는 넓어야 합니다.","원하는 속도로 감아올릴 수 있어야 합니다."],"t":"하역 윈치 = 속도 조절 범위 넓게"},"2025-3-기관2-9":{"w":"기름여과장치는 유면검출기가 기름층을 감지하면 배유 전자밸브를 열고, 일정 시간이 지나면 타이머 신호로 밸브를 닫습니다.","x":["콜레서는 기름을 뭉치게 하는 필터입니다.","포집관은 기름을 모으는 관입니다.","정답. 타이머 신호로 닫힘","전동기는 펌프를 돌립니다."],"t":"배유밸브 = 유면검출기로 열림, 타이머로 닫힘"},"2025-3-기관2-10":{"w":"생물화학적 오수처리장치는 폭기탱크(미생물 분해) → 침전탱크 → 멸균탱크(소독)로 구성됩니다. 팽창탱크는 냉각수 계통의 탱크입니다.","x":["멸균탱크는 구성 탱크입니다.","침전탱크는 구성 탱크입니다.","폭기탱크는 구성 탱크입니다.","정답(아닌 것). 팽창탱크는 냉각수 계통입니다."],"t":"오수처리 = 폭기 → 침전 → 멸균"},"2025-3-기관2-11":{"w":"액분리기(어큐뮬레이터)는 증발기와 압축기 사이에 설치해 액 냉매를 분리하고 가스만 압축기로 보내 액 해머(액 압축)를 막습니다.","x":["유분리기는 냉매 가스 속 윤활유를 분리합니다.","수액기는 액 냉매를 저장합니다.","건조기는 수분을 제거합니다.","정답. 액 해머 방지 = 액분리기"],"t":"액분리기 = 압축기 보호(액 해머 방지)"},"2025-3-기관2-12":{"w":"증발기 제상은 물을 뿌리거나(살수), 전열기로 가열하거나, 압축기의 고온·고압 가스를 보내는(핫가스) 방법 등으로 합니다. 약품 살포는 쓰지 않습니다.","x":["살수 제상은 제상 방법입니다.","전열 제상은 제상 방법입니다.","정답(아닌 것). 약품 살포는 쓰지 않습니다.","핫가스 제상은 제상 방법입니다."],"t":"제상 = 살수·전열·핫가스"},"2025-3-기관2-13":{"w":"서리는 열을 잘 전달하지 못하므로, 증발기 코일에 서리가 많이 붙으면 열교환이 나빠져 냉동효율(냉동능력)이 떨어집니다.","x":["정답. 냉동효율 감소","냉매 통과량이 직접 줄지 않습니다.","부하가 작아지는 것은 아닙니다.","응축기 압력이 높아지는 것은 아닙니다."],"t":"서리 = 단열재 역할 → 냉동효율↓"},"2025-3-기관2-14":{"w":"암모니아는 구리와 구리합금을 부식시키므로 암모니아 냉동장치에는 강관·주철관 등을 쓰고 동관은 쓰지 않습니다. (프레온은 동관 사용)","x":["철은 사용할 수 있습니다.","주철은 사용할 수 있습니다.","정답. 암모니아는 동을 부식시킵니다.","강은 사용할 수 있습니다."],"t":"암모니아 = 동 사용 금지"},"2025-3-기관2-17":{"w":"하이트 게이지는 정반 위에서 물체의 높이를 재거나 금긋기를 하는 게이지입니다.","x":["필러 게이지는 틈새를 잽니다.","다이얼 게이지는 작은 변위(흔들림)를 잽니다.","정답. 높이 = 하이트 게이지","스트레인 게이지는 변형률을 잽니다."],"t":"하이트 = 높이, 필러 = 틈새"},"2025-3-기관2-18":{"w":"리머는 드릴로 뚫은 구멍을 치수에 맞게 매끈하고 정밀하게 다듬는 공구입니다. 끝부분이 약간 테이퍼져 있고 손(핸드 리머)이나 기계로 씁니다.","x":["끝에 테이퍼 부분이 있습니다.","절삭날은 곧은 날 또는 약한 나선형입니다.","선반 전용이 아닙니다.","정답. 구멍의 정밀 다듬질"],"t":"리머 = 구멍 다듬질"},"2025-3-기관2-19":{"w":"가스가 새면 즉시 용기 밸브를 잠가 공급을 끊습니다. 누설 확인은 비눗물로 하고, 불꽃은 절대 쓰지 않습니다. 산소는 기름과 닿으면 폭발적으로 연소할 수 있습니다.","x":["정답. 즉시 용기 밸브를 잠급니다.","촛불로 확인하면 폭발합니다.","화기 근처로 옮기면 안 됩니다.","산소 계통의 기름은 매우 위험합니다."],"t":"가스 누설 = 즉시 밸브 잠금, 비눗물 확인"},"2025-3-기관2-20":{"w":"용접 이음은 구조가 간단하고, 기밀·수밀성이 좋고, 재료와 공수를 줄여 경제적입니다. 그러나 열 때문에 잔류응력과 응력 집중이 생기는 것은 단점입니다.","x":["구조가 간단한 것은 장점입니다.","기밀·수밀성은 장점입니다.","경제적인 것은 장점입니다.","정답(아닌 것). 응력 집중은 단점입니다."],"t":"용접 단점 = 잔류응력·응력 집중·변형"},"2025-3-기관2-22":{"w":"이중저는 선저를 이중으로 만든 구조로 연료유·밸러스트수·청수를 저장하고, 좌초 시 침수를 막으며, 종강도를 보강합니다. 화물은 이중저에 싣지 않습니다.","x":["정답(옳지 않은 것). 이중저에는 화물을 싣지 않습니다.","연료유를 저장합니다.","좌초 시 방수 역할을 합니다.","종강도를 보강합니다."],"t":"이중저 = 연료·밸러스트·청수 탱크"},"2025-3-기관2-23":{"w":"용골은 배 밑바닥 중심선을 따라 선수재에서 선미재까지 이어진 가장 중요한 종강력재로, 사람의 척추에 해당합니다.","x":["늑골은 갈비뼈처럼 횡으로 선 부재입니다.","정답. 용골","격벽은 선내를 나누는 벽입니다.","빌지킬은 횡요(롤링)를 줄이는 부재입니다."],"t":"용골 = 배의 척추"},"2025-3-기관2-25":{"w":"도면에서 반지름은 수치 앞에 R을 붙입니다. 지름은 Ø, 두께는 t, 45° 모따기는 C를 붙입니다.","x":["지름 기호 Ø입니다.","정답. 반지름 = R","t는 두께입니다.","C는 45° 모따기입니다."],"t":"R 반지름, Ø 지름, t 두께, C 모따기"},"2025-3-기관3-1":{"w":"RL 직렬회로의 임피던스 Z = √(R² + XL²) = √(8² + 6²) = √100 = 10[Ω]입니다.","x":["R 값만 쓴 값입니다.","정답. √(64 + 36) = 10[Ω]","틀린 값입니다.","단순히 더한 값입니다."],"t":"Z = √(R² + X²) (6:8:10)"},"2025-3-기관3-2":{"w":"전류의 3대 작용은 발열작용(전열기), 자기작용(전동기), 화학작용(전기분해·축전지)입니다. 증폭작용은 트랜지스터의 작용입니다.","x":["화학작용은 3대 작용입니다.","발열작용은 3대 작용입니다.","정답(아닌 것). 증폭작용은 전류의 작용이 아닙니다.","자기작용은 3대 작용입니다."],"t":"전류 3대 작용 = 발열·자기·화학"},"2025-3-기관3-3":{"w":"6, 12, 4[Ω] 병렬: 1 ÷ (1/6 + 1/12 + 1/4) = 1 ÷ (6/12) = 2[Ω]. 여기에 3[Ω]이 직렬이므로 합성저항은 2 + 3 = 5[Ω]입니다.","x":["틀린 값입니다.","정답. 2 + 3 = 5[Ω]","틀린 값입니다.","모두 더한 값입니다."],"t":"병렬은 역수의 합의 역수"},"2025-3-기관3-5":{"w":"직렬회로는 모든 저항에 같은 전류가 흐릅니다. 전체 저항 5 + 3 + 2 = 10[Ω], 전류 2[A]이므로 E = 10 × 2 = 20[V]입니다.","x":["R만 곱한 값입니다.","틀린 값입니다.","정답. 10[Ω] × 2[A] = 20[V]","틀린 값입니다."],"t":"직렬 = 전류 같음, V = IR"},"2025-3-기관3-6":{"w":"3상 전력 P = √3 × 선간전압 × 선전류 × 역률 입니다. 역률이 1이면 P = √3 × V × I 이므로 √3배입니다.","x":["틀립니다.","정답. √3배","틀립니다.","상전압·상전류로 계산할 때의 3배입니다."],"t":"P = √3 VI cosθ"},"2025-3-기관3-7":{"w":"전류 I = Q ÷ t = 10 ÷ 2 = 5[A]입니다.","x":["틀린 값입니다.","정답. 10 ÷ 2 = 5[A]","틀린 값입니다.","곱한 값입니다."],"t":"I = Q / t"},"2025-3-기관3-9":{"w":"피상전력 = 전압 × 전류 = EI [VA]입니다. 유효전력은 EIcosθ, 무효전력은 EIsinθ입니다.","x":["정답. 피상전력 = EI","무효전력입니다.","해당하지 않습니다.","유효전력입니다."],"t":"피상 EI, 유효 EIcosθ, 무효 EIsinθ"},"2025-3-기관3-10":{"w":"그림은 콘덴서 C1, C2가 병렬로 연결된 회로입니다. 콘덴서는 병렬로 연결하면 용량이 더해지므로 C1 + C2 입니다. (저항과 반대)","x":["정답. 병렬 = C1 + C2","틀린 식입니다.","틀린 식입니다.","직렬 연결일 때의 식입니다."],"t":"콘덴서 병렬 = 더하기, 직렬 = 곱/합"},"2025-3-기관3-11":{"w":"접점 가운데에 ×가 있는 것은 열동계전기처럼 동작 후 손으로 복귀시켜야 하는 수동복귀 접점입니다.","x":["일반 a접점입니다.","정답. × 표시 = 수동복귀 접점","누름버튼 스위치 접점입니다.","b접점 등 다른 접점입니다."],"t":"× 표시 = 수동복귀"},"2025-3-기관3-12":{"w":"단권변압기(기동보상기)로 전동기에 낮은 전압을 걸어 기동하면 큰 기동 전류를 줄일 수 있습니다. 가속된 뒤 전전압으로 바꿉니다.","x":["전압을 낮추기 위해 씁니다.","속도 감소가 목적이 아닙니다.","기동 토크는 오히려 줄어듭니다.","정답. 기동 전류 감소"],"t":"기동보상기 = 감전압 기동 → 기동전류↓"},"2025-3-기관3-13":{"w":"퓨즈는 정해진 전류 이상이 흐르면 녹아 끊어지므로 용량을 전류 단위 [A]로 나타냅니다.","x":["정답. 퓨즈 용량 = [A]","[V]는 전압 단위입니다.","[W]는 전력 단위입니다.","[Ω]은 저항 단위입니다."],"t":"퓨즈 = 전류[A]"},"2025-3-기관3-14":{"w":"직류발전기는 계자, 전기자, 정류자, 브러시로 이루어집니다. 슬립링은 교류발전기·권선형 유도전동기에 쓰입니다.","x":["계자는 구성 요소입니다.","브러시는 구성 요소입니다.","전기자는 구성 요소입니다.","정답(아닌 것). 슬립링은 교류기에 씁니다."],"t":"직류기 = 정류자, 교류기 = 슬립링"},"2025-3-기관3-15":{"w":"회전자 속도가 동기속도와 같아지면 회전자가 회전자기장을 끊지 않으므로 회전자에 유도전류가 흐르지 않아 토크가 0이 됩니다. 그래서 유도전동기는 항상 동기속도보다 조금 느립니다(슬립).","x":["고정자가 아니라 회전자입니다.","정답. 회전자, 유도전류","여자전류가 아닙니다.","틀립니다."],"t":"동기속도 = 유도전류 0 = 토크 0"},"2025-3-기관3-16":{"w":"지시 계기의 3대 요소는 구동장치(바늘을 움직이는 힘), 제어장치(스프링으로 되돌리는 힘), 제동장치(바늘의 흔들림 억제)입니다.","x":["구동장치는 3대 요소입니다.","제어장치는 3대 요소입니다.","정답(아닌 것). 보호장치는 3대 요소가 아닙니다.","제동장치는 3대 요소입니다."],"t":"계기 3요소 = 구동·제어·제동"},"2025-3-기관3-17":{"w":"Ns = 120f ÷ P 이므로 P = 120f ÷ Ns = 120 × 60 ÷ 1,200 = 6극입니다.","x":["틀린 값입니다.","틀린 값입니다.","정답. 7,200 ÷ 1,200 = 6극","틀린 값입니다."],"t":"P = 120f / N"},"2025-3-기관3-18":{"w":"2차 전압 = 400 ÷ 2 = 200[V]. 2차 전류 = 3,000[W] ÷ 200[V] = 15[A]입니다.","x":["틀린 값입니다.","1차 전류입니다.","틀린 값입니다.","정답. 3,000 ÷ 200 = 15[A]"],"t":"2차 전압 = 1차 전압 / 권수비"},"2025-3-기관3-20":{"w":"A, B가 모두 1일 때만 X가 0이므로 NAND 게이트입니다. AND 기호에 동그라미가 붙은 ㉯입니다.","x":["AND 게이트입니다.","정답. NAND","OR 게이트입니다.","NOR 게이트입니다."],"t":"둘 다 1일 때만 0 = NAND"},"2025-3-기관3-21":{"w":"전류증폭도(β)는 입력전류(베이스 전류)에 대한 출력전류(컬렉터 전류)의 비입니다.","x":["틀린 정의입니다.","틀린 정의입니다.","정답. 출력전류 ÷ 입력전류","전압증폭도입니다."],"t":"전류증폭도 = Ic / Ib"},"2025-3-기관3-23":{"w":"다이오드는 한 방향으로만 전류를 흘려 교류를 직류로 바꾸는 정류 작용을 합니다.","x":["정답. 정류 작용","증폭은 트랜지스터입니다.","연산은 연산증폭기입니다.","발진은 발진회로입니다."],"t":"다이오드 = 정류"},"2025-3-기관3-24":{"w":"LED(발광 다이오드)는 순방향 전류가 흐르면 빛을 냅니다.","x":["CdS는 빛에 따라 저항이 변하는 소자입니다.","포토 다이오드는 빛을 받아 전류를 만듭니다.","정답. LED","포토 트랜지스터는 빛을 받아 동작합니다."],"t":"LED = 빛을 냄, 포토 = 빛을 받음"},"2025-3-직무일반-1":{"w":"무인화 선박에서 정전되면 먼저 S/B 예비발전기가 자동 기동해 약 45초 이내에 전력을 공급합니다. 예비발전기가 규정 시간 안에 전력을 공급하지 못하면 비상발전기가 전력을 공급합니다.","x":["정전과 동시에 예비발전기가 기동합니다.","S/B 순서대로 기동합니다.","정답(옳지 않은 것). 예비발전기가 먼저 기동합니다.","예비발전기가 실패하면 비상발전기가 공급합니다."],"t":"정전 → 예비발전기 먼저 → 실패 시 비상발전기"},"2025-3-직무일반-2":{"w":"당직 인수 전에는 기관장의 당직지침과 특별 지시, 진행 중인 작업과 잠재적 위험, 기관일지 작성 상태, 기계 상태 등을 확인합니다. 내부통신시스템 사용 방법은 당직 인수 때 확인하는 사항이 아닙니다.","x":["기관일지 상태를 확인합니다.","정답(아닌 것). 통신시스템 사용법은 평소 숙지 사항입니다.","기관장 지침을 확인합니다.","진행 중인 작업과 위험을 확인합니다."],"t":"당직 인수 = 지시사항·진행 작업·기계 상태"},"2025-3-직무일반-3":{"w":"유출된 기름이 퍼지는 것을 막기 위해 선박 주위에 오일펜스를 둘러칩니다. 그 뒤 유회수기로 거두고 흡착재로 닦아 냅니다.","x":["유회수기는 기름을 거두어들이는 장비입니다.","흡착재는 기름을 빨아들이는 재료입니다.","정답. 확산 방지 = 오일펜스","유겔화제는 기름을 굳히는 약제입니다."],"t":"확산 방지 = 오일펜스"},"2025-3-직무일반-4":{"w":"관로가 길어지면 마찰 손실이 커져 압력손실이 커집니다.","x":["수격작용에 주의해야 합니다.","정답(옳지 않은 것). 관로가 길면 압력손실이 커집니다.","색으로 유체를 구분합니다.","온도 변화에 대비한 신축이음이 필요합니다."],"t":"관로 길이↑ → 압력손실↑"},"2025-3-직무일반-6":{"w":"시체스트(sea chest)는 선체 바닥 옆에 있는 해수 흡입함입니다. 조개·해초 등이 막으면 증기(또는 공기)를 불어 넣어 청소할 수 있도록 증기관을 설치하기도 합니다.","x":["냉각기가 아닙니다.","항해 중 수시로 개방하지 않습니다.","수면 가까이가 아니라 선저 가까이에 설치합니다.","정답. 청소용 증기배관을 설치합니다."],"t":"시체스트 = 선저 해수 흡입함(증기 청소)"},"2025-3-직무일반-7":{"w":"빌지관 계통에는 바닷물이 역류해 들어오지 않도록 역지밸브(스톱 체크밸브)를 반드시 사용합니다.","x":["빌지가 고이는 곳이 빌지웰입니다.","정박 중에는 배출하지 않습니다.","정답(옳지 않은 것). 빌지관에는 역지밸브를 사용합니다.","15[ppm] 기름여과장치를 거쳐 배출합니다."],"t":"빌지관 = 역지밸브 필수"},"2025-3-직무일반-8":{"w":"선박해양오염비상계획서에는 방제조직, 선원이 취할 방제조치, 선장의 보고 절차, 연안국에 통보할 기관과 연락처 등이 들어갑니다. 통보 대상은 기국이 아니라 연안국(사고 해역 국가)입니다.","x":["방제조직이 포함됩니다.","방제조치가 포함됩니다.","보고 절차가 포함됩니다.","정답(아닌 것). 기국이 아니라 연안국 연락처입니다."],"t":"비상계획서 = 연안국 연락처"},"2025-3-직무일반-9":{"w":"선박평형수관리기록부는 마지막으로 기록한 날로부터 5년간 선박에 보존해야 합니다.","x":["틀린 기간입니다.","기름기록부 보존 기간(3년)입니다.","정답. 5년","틀린 기간입니다."],"t":"평형수기록부 5년, 기름기록부 3년"},"2025-3-직무일반-10":{"w":"선박에너지효율은 선박의 화물운송과 관련해 사용한 에너지량을 이산화탄소 발생 비율로 나타낸 것입니다.","x":["틀린 정의입니다.","틀린 정의입니다.","틀린 정의입니다.","정답. 에너지량 대비 CO₂ 발생 비율"],"t":"에너지효율 = CO₂ 발생 비율"},"2025-3-직무일반-11":{"w":"들것은 보통 환자의 발 쪽이 앞으로 가게 운반합니다(계단을 오를 때는 머리가 앞). 뒤쪽 운반자가 환자의 얼굴을 보며 상태를 살필 수 있습니다.","x":["4인 운반이 안전합니다.","부상에 맞는 체위로 운반합니다.","흔들리지 않게 합니다.","정답(옳지 않은 것). 보통 발 쪽이 앞으로 갑니다."],"t":"들것 = 발 먼저(오르막은 머리 먼저)"},"2025-3-직무일반-12":{"w":"출혈이 심하면 출혈 부위를 심장보다 높게 들어 올려 피가 덜 나오게 합니다.","x":["거즈로 압박하는 것은 맞습니다.","정답(옳지 않은 것). 출혈부는 심장보다 높게 합니다.","원격 의료 조언을 받습니다.","심한 출혈은 동맥 압박·지혈대를 씁니다."],"t":"출혈 = 압박 + 심장보다 높게"},"2025-3-직무일반-13":{"w":"사람이 내쉬는 숨에도 약 16[%]의 산소가 남아 있어, 구강 대 구강 인공호흡으로 환자에게 산소를 공급할 수 있습니다.","x":["기도 개방은 준비 과정입니다.","심장 압박은 흉부압박입니다.","위를 부풀리면 구토 위험이 있습니다.","정답. 날숨에도 산소가 있습니다."],"t":"날숨 산소 약 16%"},"2025-3-직무일반-15":{"w":"주기관 진동이 심하면 노킹, 위험회전수 운전, 베드 볼트 이완·절손, 각 실린더 출력 불균형 등을 점검합니다. 연료유 여과기 막힘은 출력 저하·정지의 원인이지 진동 점검 사항이 아닙니다.","x":["정답(옳지 않은 것). 여과기 막힘은 진동 점검 사항이 아닙니다.","노킹을 확인합니다.","위험회전수를 확인합니다.","베드 볼트를 확인합니다."],"t":"진동 점검 = 노킹·위험회전수·베드 볼트"},"2025-3-직무일반-16":{"w":"우선 차단(선택 차단)은 발전기 과부하 시 중요하지 않은 부하부터 차단해 발전기를 보호하는 기능입니다. 병렬운전 중 발전기가 전동기처럼 도는 것을 막는 것은 역전력 계전기(역전력 차단)의 기능입니다.","x":["트립 코일이 있습니다.","덜 중요한 부하부터 차단합니다.","과부하 시 선택 부하를 차단합니다.","정답(옳지 않은 것). 역전력 차단에 대한 설명입니다."],"t":"우선 차단 = 과부하 시 비중요 부하 차단"},"2025-3-직무일반-17":{"w":"정전 후 예비발전기가 기동되면 순차기동으로 주요 보기가 운전됩니다. 선미관 윤활유 펌프(S/T L.O. pump) 같은 추진에 필요한 펌프가 자동 운전됩니다. 이송 펌프나 조수기 펌프는 수동 운전입니다.","x":["연료유 이송 펌프는 수동 운전합니다.","조수기 이젝터 펌프는 순차기동 대상이 아닙니다.","정답. 선미관 윤활유 펌프","윤활유 이송 펌프는 수동 운전합니다."],"t":"순차기동 = 추진에 필요한 펌프"},"2025-3-직무일반-19":{"w":"가연성 액체의 인화점은 비중·점도·압력이 낮을수록, 주위온도가 높을수록 낮아져 위험해집니다.","x":["틀립니다.","A가 틀립니다.","정답. A 낮을수록, B 높을수록","B가 틀립니다."],"t":"가벼운 기름, 높은 온도 = 인화 쉬움"},"2025-3-직무일반-21":{"w":"A급 구획은 강 또는 동등한 재료로 만들고 60분 동안 연기·화염을 막아야 합니다. B급은 불연재, C급은 불연재로 구조 기준이 낮습니다.","x":["정답. A급 = 강재","B급은 불연재입니다.","C급은 불연재입니다.","D급은 없습니다."],"t":"A급 = 강재, 60분 차단"},"2025-3-직무일반-22":{"w":"선박법은 선박의 국적, 톤수 측정, 등기·등록, 선적항과 선명 표시 등을 규정합니다. 선박시설과 감항성은 선박안전법에서 규정합니다.","x":["톤수 측정은 선박법 사항입니다.","국적·등록은 선박법 사항입니다.","선명·선적항 표시는 선박법 사항입니다.","정답(아닌 것). 선박안전법 사항입니다."],"t":"선박법 = 국적·톤수·등록 / 선박안전법 = 시설·감항성"},"2025-3-직무일반-23":{"w":"선박국적증서는 선박이 어느 나라에 속하는지(국적)를 증명하는 문서입니다.","x":["건조국 증명이 아닙니다.","정답. 선박이 소속된 국가 증명","회사 국적이 아닙니다.","항해 국가가 아닙니다."],"t":"국적증서 = 선박의 국적"},"2025-3-직무일반-24":{"w":"해양 배출 금지 오염물질은 기름(원유·폐유 등), 유해액체물질, 포장유해물질, 폐기물 등입니다. 불활성기체는 오염물질이 아닙니다.","x":["원유는 금지 물질입니다.","유해액체물질은 금지 물질입니다.","폐유는 금지 물질입니다.","정답(아닌 것). 불활성기체는 오염물질이 아닙니다."],"t":"불활성기체 = 오염물질 아님"},"2025-3-직무일반-25":{"w":"기관구역 기름기록부에는 선저폐수 처리, 유성찌꺼기 처리, 연료유·산적 윤활유 수급 등을 기록합니다. 혼합물탱크(슬롭탱크)의 혼합물 배출은 화물구역 기름기록부(유조선)에 기록합니다.","x":["선저폐수 처리를 기록합니다.","연료유·윤활유 수급을 기록합니다.","정답(아닌 것). 화물구역 기록 사항입니다.","유성찌꺼기 처리를 기록합니다."],"t":"혼합물탱크 = 화물구역 기록부"},"2025-3-영어-1":{"w":"\"노(furnace)의 변형을 검사할 것.\" furnace가 있는 기기는 보일러입니다.","x":["정답. Boiler(보일러 노)","Cooler = 냉각기","Heater = 가열기","Purifier = 청정기"],"t":"furnace = 보일러 노"},"2025-3-영어-2":{"w":"아연판(zinc plate)은 해수가 흐르는 냉각기의 전식 방지용으로 붙입니다. \"주기관 윤활유 냉각기의 아연판 4개를 교체했다.\"","x":["크랭크케이스에는 아연판을 붙이지 않습니다.","정답. M/E L.O. cooler(해수 냉각)","공기탱크에는 아연판이 없습니다.","연료유 가열기에는 아연판이 없습니다."],"t":"zinc plate = 해수 냉각기 부식 방지"},"2025-3-영어-3":{"w":"ISM Code = International Safety Management Code(국제안전관리규약)입니다.","x":["Mode가 아닙니다.","Security가 아닙니다.","Security는 ISPS Code입니다.","정답. International Safety Management Code"],"t":"ISM = Safety Management, ISPS = Security"},"2025-3-영어-4":{"w":"정해진 항로와 일정으로 운항하는 정기선은 Liner입니다.","x":["정답. Liner = 정기선","Tanker = 유조선","Tramper = 부정기선","Fishing vessel = 어선"],"t":"Liner 정기선, Tramper 부정기선"},"2025-3-영어-5":{"w":"낮추다 = reduce(과거형 reduced). \"Reduced M/E rpm to 90 by bridge's order.\"","x":["Induced = 유도했다","Increased = 올렸다","Operated = 운전했다","정답. Reduced = 낮췄다"],"t":"reduce = 낮추다, increase = 올리다"},"2025-3-영어-6":{"w":"Frequency(주파수)의 단위는 [Hz]입니다.","x":["[kVA]는 피상전력","정답. [Hz] = 주파수","[kW]는 유효전력","[Ah]는 축전지 용량"],"t":"frequency = Hz"},"2025-3-영어-7":{"w":"행정 = stroke 입니다.","x":["Stripe = 줄무늬","Cycle = 사이클","Strike = 치다","정답. Stroke = 행정"],"t":"stroke = 행정"},"2025-3-영어-8":{"w":"보일러 점화 전에 노 안을 송풍기로 환기하는 것은 Pre-purge(프리퍼지)입니다. 소화 후 환기는 Post-purge입니다.","x":["Post-purge = 소화 후 환기","Surface blow down = 수면 분출","정답. Pre-purge = 점화 전 환기","Bottom blow down = 수저 분출"],"t":"pre = 전, post = 후"},"2025-3-영어-9":{"w":"hydrostatic test = 수압시험 입니다.","x":["수두시험이 아닙니다.","정답. 수압시험","누수시험은 leak test입니다.","수류시험이 아닙니다."],"t":"hydrostatic test = 수압시험"},"2025-3-영어-10":{"w":"Intermediate shaft = 중간축 입니다. \"중간축을 검사를 위해 뽑아낼 것.\"","x":["정답. 중간축","선수축이 아닙니다.","크랭크축은 crankshaft입니다.","중심축이 아닙니다."],"t":"intermediate shaft = 중간축"},"2025-3-영어-11":{"w":"S/B = Stand by(기관 준비) 입니다.","x":["정답. Stand by","틀린 표현입니다.","틀린 표현입니다.","틀린 표현입니다."],"t":"S/B = Stand by"},"2025-3-영어-12":{"w":"\"연료유 200톤을 이중저 탱크에 받았다(적재했다).\" loaded ≒ received.","x":["Shifted = 옮겼다","정답. Received = 받았다","Gauged = 측정했다","Raised = 올렸다"],"t":"loaded ≒ received (수급)"},"2025-3-영어-13":{"w":"Governor(조속기)는 부하가 변해도 기관 회전수를 일정하게 조절(control)합니다.","x":["회전수를 세는 것은 tachometer입니다.","정답. RPM control","유량을 세지 않습니다.","온도 제어가 아닙니다."],"t":"governor = 회전수 제어"},"2025-3-영어-14":{"w":"\"윈치 고장으로 하역 작업을 중지했다.\" owing to = ~때문에, trouble = 고장.","x":["viscosity = 점도","injection = 분사","정답. trouble = 고장","treatment = 처리"],"t":"owing to trouble = 고장 때문에"},"2025-3-영어-17":{"w":"보일러의 과도한 압력을 조절(방출)하는 밸브는 safety valve(안전밸브)입니다.","x":["air valve = 공기밸브","suction valve = 흡입밸브","정답. safety valve = 안전밸브","exhaust valve = 배기밸브"],"t":"safety valve = 과압 방출"},"2025-3-영어-18":{"w":"ETA = Estimated Time of Arrival = 도착 예정 시각입니다. 출항 예정 시각은 ETD입니다.","x":["ETD입니다.","정답. 도착 예정 시각","틀립니다.","틀립니다."],"t":"ETA 도착, ETD 출항"},"2025-3-영어-19":{"w":"Expansion stroke(팽창행정) = Working stroke(작동행정, 폭발행정)입니다.","x":["Suction stroke = 흡입행정","정답. Working stroke = 작동행정","Exhaust stroke = 배기행정","Compression stroke = 압축행정"],"t":"expansion = working = power stroke"},"2025-3-영어-20":{"w":"F/H = Full Ahead = 전속 전진입니다.","x":["F/S는 해당하지 않습니다.","H/H = Half Ahead(반속 전진)","D/H = Dead Slow Ahead(극미속 전진)","정답. F/H = Full Ahead"],"t":"F/H 전속, H/H 반속, S/H 미속, D/H 극미속"},"2025-3-영어-21":{"w":"\"기관부를 책임지는 사람은?\" 기관장(Chief engineer)입니다.","x":["정답. Chief engineer = 기관장","Chief officer = 1등 항해사","No.1 oiler = 조기장","Captain = 선장"],"t":"기관부 책임 = Chief engineer"},"2025-3-영어-22":{"w":"MARPOL은 선박에 의한 해양오염 방지 협약입니다.","x":["MLC = 해사노동협약","ISPS = 선박·항만시설 보안","STCW = 선원 훈련·자격증명·당직 기준","정답. MARPOL = 해양오염 방지"],"t":"MARPOL = 해양오염"},"2025-3-영어-23":{"w":"닻을 다루는 일반적인 장치는 windlass(양묘기)입니다.","x":["winch = 하역·계선 윈치","정답. windlass = 양묘기","bow thruster = 선수 추진기","steering gear = 조타기"],"t":"windlass = anchor handling"},"2025-3-기관2-16":{"w":"쇠톱 작업에서 관이 거의 다 잘렸을 때는 힘을 약하게 하고 천천히 잘라야 합니다. 세게 밀면 톱날이 부러지거나 다칠 수 있습니다.","x":["바른 자세는 맞습니다.","톱날 전체를 쓰는 것이 맞습니다.","밀 때 잘리도록 끼우는 것이 맞습니다.","정답(옳지 않은 것). 끝날 때는 힘을 줄입니다."],"t":"쇠톱 = 밀 때 절삭, 끝날 때 힘 빼기"},"2025-4-기관1-1":{"w":"내연기관의 이론 열사이클은 오토(정적), 디젤(정압), 사바테(복합) 사이클입니다. 랭킨 사이클은 증기터빈 같은 외연기관(증기원동소)의 사이클입니다.","x":["오토 사이클은 가솔린기관의 사이클입니다.","디젤 사이클은 저속 디젤기관의 사이클입니다.","사바테 사이클은 고속 디젤기관의 사이클입니다.","정답(아닌 것). 랭킨 사이클은 증기 사이클입니다."],"t":"랭킨 = 증기(외연기관)"},"2025-4-기관1-2":{"w":"실린더 헤드는 라이너·피스톤과 함께 연소실을 이루고, 온도 차이로 균열이 생기기 쉬워 너트는 대각선 순서로 고르게 조입니다. 중·소형기관의 헤드는 주로 주철로 만듭니다(대형은 주강).","x":["연소실을 구성합니다.","부동팽창·균열이 생기기 쉽습니다.","정답(옳지 않은 것). 중·소형은 주철을 주로 씁니다.","대각선으로 나누어 조입니다."],"t":"헤드 너트 = 대각선 순서로 조임"},"2025-4-기관1-3":{"w":"피스톤링용 주철 속의 흑연은 스스로 윤활 작용을 하고 윤활유를 머금어 유막을 유지하게 합니다.","x":["철은 기본 성분입니다.","정답. 흑연 = 자기 윤활","니켈은 강도·내식성을 높입니다.","크롬은 내마모성을 높입니다."],"t":"주철 속 흑연 = 윤활 보조"},"2025-4-기관1-4":{"w":"크랭크암 개폐량(디플렉션) 허용한도는 행정(stroke)을 기준으로 정합니다. 보통 행정의 약 1/10,000(한계 약 3/10,000)입니다.","x":["정답. 행정 기준","저널 지름 기준이 아닙니다.","실린더 지름 기준이 아닙니다.","회전수 기준이 아닙니다."],"t":"디플렉션 한도 = 행정 × 1/10,000"},"2025-4-기관1-5":{"w":"풋라이너는 연접봉 아래(대단부)와 베어링 사이에 넣는 판입니다. 두께를 늘리면 연접봉이 길어진 효과가 나서 피스톤이 더 높이 올라가 압축부피가 작아지므로 압축비가 커집니다.","x":["정답. 압축부피 감소 → 압축비 증가","두께를 줄이면 작아집니다.","변합니다.","한 방향으로만 변합니다."],"t":"풋라이너 두께↑ = 압축비↑, 헤드 개스킷 두께↑ = 압축비↓"},"2025-4-기관1-6":{"w":"배기가 검은색이 되는 원인은 공기 부족(소기압력 저하), 불완전 연소, 과부하 등입니다. 연료유에 물이 섞이면 흰색 배기가 나옵니다.","x":["소기압력이 낮으면 공기가 부족해 흑색 배기가 됩니다.","불완전 연소는 흑색 배기의 원인입니다.","과부하는 흑색 배기의 원인입니다.","정답(아닌 것). 물이 섞이면 흰색 배기가 됩니다."],"t":"흑색 = 공기 부족·과부하, 백색 = 물 혼입"},"2025-4-기관1-7":{"w":"기관을 시동한 직후에는 가장 먼저 윤활유 압력을 확인해야 합니다. 윤활유 압력이 오르지 않으면 베어링이 소손되므로 즉시 정지합니다.","x":["정답. 윤활유 압력계","연료유 압력은 그다음 확인합니다.","배기 온도는 운전 중 확인합니다.","시동공기는 시동 전에 확인합니다."],"t":"시동 직후 = 윤활유 압력 먼저"},"2025-4-기관1-8":{"w":"유압식 조속기의 보상용 니들 밸브를 너무 적게 열면 보상 작용이 느려져 기관 속도 변화가 신속하지 못합니다. 너무 많이 열면 난조(헌팅, 맥동 운전)가 생깁니다.","x":["너무 많이 열었을 때의 현상입니다.","연료 제한 기능과 관계없습니다.","속도가 급상승하지 않습니다.","정답. 적게 열면 응답이 느립니다."],"t":"니들밸브 많이 열림 = 헌팅, 적게 열림 = 둔함"},"2025-4-기관1-9":{"w":"밸브 오버랩은 상사점 부근에서 흡기밸브와 배기밸브가 함께 열려 있는 구간입니다. 흡기밸브 열림 상사점 전 50° + 배기밸브 닫힘 상사점 후 50° = 100°입니다.","x":["틀린 값입니다.","틀린 값입니다.","정답. 50° + 50° = 100°","틀린 값입니다."],"t":"오버랩 = 흡기 열림(BTDC) + 배기 닫힘(ATDC)"},"2025-4-기관1-10":{"w":"라이너가 마멸되는 직접 원인은 불완전 연소(카본), 피스톤링 기밀 불량(블로바이), 크랭크실 윤활유 오손(트렁크형은 크랭크실 윤활유가 라이너를 윤활) 등입니다. 과급기 운전 자체는 마멸의 원인이 아닙니다.","x":["정답(아닌 것). 과급기 운전은 직접 원인이 아닙니다.","불완전 연소는 원인입니다.","링 기밀 불량은 원인입니다.","윤활유 오손은 원인입니다."],"t":"트렁크형 = 크랭크실 윤활유가 라이너도 윤활"},"2025-4-기관1-11":{"w":"크랭크축이 부러지는 주된 원인은 축 중심의 어긋남(메인 베어링 편마멸 등)으로 반복 굽힘 응력이 생기는 것입니다. 비틀림 진동, 재질 결함 등도 원인입니다.","x":["불완전 연소는 직접 원인이 아닙니다.","링 마멸은 직접 원인이 아닙니다.","정답. 축 중심의 어긋남","분사압력은 직접 원인이 아닙니다."],"t":"크랭크축 절손 = 중심선 불일치"},"2025-4-기관1-12":{"w":"청관제는 스케일 부착 방지, 부식 방지, 캐리오버(포밍) 방지, pH 조정 등을 합니다. 급수 속 공기(산소)는 탈기기로 제거합니다.","x":["캐리오버 방지 효과가 있습니다.","정답(옳지 않은 것). 공기 제거는 탈기기의 역할입니다.","부식 방지 효과가 있습니다.","스케일 방지 효과가 있습니다."],"t":"청관제 = 스케일·부식·캐리오버 방지"},"2025-4-기관1-13":{"w":"단요소식 급수제어는 드럼 수위 하나만 검출해 급수량을 조절합니다. (2요소식: 수위 + 증기유량, 3요소식: 수위 + 증기유량 + 급수유량)","x":["정답. 단요소 = 수위","3요소식에서 쓰는 신호입니다.","2요소식 이상에서 쓰는 신호입니다.","증기온도는 쓰지 않습니다."],"t":"1요소 수위, 2요소 +증기량, 3요소 +급수량"},"2025-4-기관1-15":{"w":"Superheater(과열기)는 포화증기를 더 가열해 과열증기로 만듭니다.","x":["정답. Superheater = 과열기","Economizer = 절탄기(급수 예열)","Desuperheater = 과열 저감기","Regenerator = 재생기"],"t":"superheater = 과열기"},"2025-4-기관1-16":{"w":"프로펠러 피치는 반지름 위치마다 다를 수 있어, 보통 0.7R 위치의 피치를 평균 피치(대표 피치)로 씁니다.","x":["틀립니다.","정답. 0.7R","틀립니다.","틀립니다."],"t":"평균 피치 = 0.7R"},"2025-4-기관1-17":{"w":"말굽형 추력 베어링은 구조가 오래된 형식으로 소형선·저추력에 쓰였고, 추력이 큰 중·대형선에는 미첼형(세그먼트형)을 가장 많이 씁니다.","x":["정답(옳지 않은 것). 말굽형은 추력이 큰 선박에 적합하지 않습니다.","미첼형이 가장 많이 쓰입니다.","상자형은 소형선에 씁니다.","추력이 크면 여러 단으로 만듭니다."],"t":"추력 베어링 = 미첼형(중·대형)"},"2025-4-기관1-18":{"w":"침투액을 뿌리고 닦아낸 뒤 현상액을 뿌려 균열을 찾는 방법은 컬러 체크(침투 탐상법)입니다.","x":["자분 탐상은 자분을 뿌려 자기장으로 봅니다.","정답. 컬러 체크","방사선 탐상은 X선을 씁니다.","초음파 탐상은 초음파를 씁니다."],"t":"컬러 체크 = 침투액 + 현상액"},"2025-4-기관1-19":{"w":"슬립은 프로펠러에 의한 이론 속도와 배의 실제 속도의 차이입니다.","x":["정답. 프로펠러 속도 − 배의 속도","틀린 정의입니다.","틀린 정의입니다.","틀린 정의입니다."],"t":"슬립 = 이론 속도 − 실제 속도"},"2025-4-기관1-20":{"w":"공기저항은 수면 위 선체와 공기의 마찰, 공기 와류로 생기며 전체 저항의 약 1~3[%]입니다. 속도가 빨라질수록 커집니다.","x":["전 저항의 1~3[%]입니다.","정답(옳지 않은 것). 고속일수록 커집니다.","공기 마찰로 생깁니다.","공기 와류로 생깁니다."],"t":"공기저항 ∝ 속도²"},"2025-4-기관1-21":{"w":"입자의 침강속도(스토크스 법칙)는 입자 지름의 제곱에 비례하므로 입자 크기의 영향이 가장 큽니다. 밀도 차에는 비례, 점도에는 반비례합니다.","x":["영향은 있지만 가장 크지는 않습니다.","영향은 있지만 가장 크지는 않습니다.","반비례하지만 가장 큰 요인은 아닙니다.","정답. 입자 지름의 제곱에 비례"],"t":"침강속도 ∝ (입자 지름)²"},"2025-4-기관1-22":{"w":"경유의 비중은 약 0.84~0.89입니다. 휘발유는 약 0.69~0.77, 등유는 약 0.78~0.84, 중유는 약 0.91~0.99입니다.","x":["휘발유의 비중입니다.","등유의 비중입니다.","정답. 경유 약 0.84~0.89","중유의 비중입니다."],"t":"휘발유 < 등유 < 경유 < 중유"},"2025-4-기관1-23":{"w":"탄소가 공기 부족으로 불완전 연소하면 일산화탄소(CO)가 생깁니다. 완전 연소하면 이산화탄소(CO₂)가 됩니다.","x":["완전 연소의 생성물입니다.","정답. 불완전 연소 = CO","수소가 연소한 것입니다.","황이 연소한 것입니다."],"t":"C 불완전 연소 = CO"},"2025-4-기관1-24":{"w":"유성은 윤활유가 마찰면에 강하게 달라붙어 유막을 만드는 성질입니다.","x":["정답. 유성","점도지수는 온도에 따른 점도 변화 정도입니다.","유동점은 흐를 수 있는 최저 온도입니다.","항유화성은 물과 분리되는 성질입니다."],"t":"유성 = 흡착해 유막 형성"},"2025-4-기관2-1":{"w":"송출압력이 오르지 않는 원인은 공기 흡입, 임펠러 손상, 마우스링 마멸(내부 누설), 회전수 부족 등입니다. 전동기 슬립이 작으면 오히려 회전수가 정상에 가까우므로 원인이 아닙니다.","x":["공기가 흡입되면 압력이 오르지 않습니다.","임펠러가 손상되면 압력이 오르지 않습니다.","마우스링이 닳으면 내부 누설로 압력이 떨어집니다.","정답(옳지 않은 것). 슬립이 작은 것은 정상 상태입니다."],"t":"송출압력 불량 = 공기·임펠러 손상·마우스링 마멸"},"2025-4-기관2-2":{"w":"임펠러를 여러 단 직렬로 배치한 다단식을 쓰면 단마다 압력이 더해져 높은 양정을 얻습니다. 양흡입식은 유량을 늘리는 방식입니다.","x":["단단식은 양정이 낮습니다.","단흡입식은 양정과 관계없습니다.","정답. 다단식 = 고양정","양흡입식은 유량 증가용입니다."],"t":"다단식 = 양정↑, 양흡입 = 유량↑"},"2025-4-기관2-3":{"w":"마우스링은 케이싱과 임펠러 입구 사이에 끼워 송출측 물이 흡입측으로 역류(누설)하는 것을 막습니다.","x":["랜턴 링은 패킹에 봉수를 공급합니다.","와실은 속도에너지를 압력으로 바꿉니다.","정답. 마우스 링","기계식 실은 축 관통부를 밀봉합니다."],"t":"마우스링 = 내부 역류 방지"},"2025-4-기관2-5":{"w":"갑판보기(윈치, 양묘기 등)는 바닷물과 비바람에 노출되므로 잘 씻겨 나가지 않는 그리스를 윤활제로 많이 씁니다.","x":["냉동유는 냉동기 압축기용입니다.","정답. 그리스","터빈유는 터빈·유압용입니다.","절연유는 변압기용입니다."],"t":"갑판보기 = 그리스"},"2025-4-기관2-6":{"w":"추종장치는 타가 조타 신호(명령 타각)만큼 돌아가면 유압펌프 송출을 멈춰 타를 그 위치에 고정시킵니다.","x":["다를 때는 타를 움직여야 합니다.","원래 위치로 되돌리지 않습니다.","정답. 명령 타각에 도달하면 고정","원래 위치로 되돌리지 않습니다."],"t":"추종장치 = 명령 타각에서 정지"},"2025-4-기관2-7":{"w":"자동배유장치는 유면검출기가 기름층을 감지하면 전자밸브를 열어 기름을 배출하고, 타이머로 일정 시간 뒤 밸브를 닫습니다. 구성 요소는 타이머, 전자밸브, 유면검출기입니다.","x":["콜레서·포집관은 분리 장치입니다.","포집관·검유밸브는 해당하지 않습니다.","정답. 타이머·전자밸브·유면검출기","해당하지 않습니다."],"t":"자동배유 = 유면검출기 + 전자밸브 + 타이머"},"2025-4-기관2-8":{"w":"침전탱크에 가라앉은 활성슬러지는 공기 상승관(에어리프트)으로 폭기탱크에 되돌려 보내 미생물을 다시 활용합니다.","x":["스키머는 표면 부유물을 걷습니다.","멸균탱크로 보내지 않습니다.","멸균탱크로 보내지 않습니다.","정답. 공기 상승관으로 폭기탱크로 반송"],"t":"활성슬러지 = 폭기탱크로 반송"},"2025-4-기관2-9":{"w":"15[ppm] 기름여과장치는 선저폐수(빌지)처럼 물에 기름이 조금 섞인 것을 처리합니다. 청정기 슬러지는 기름 찌꺼기이므로 슬러지 탱크에 모아 소각하거나 육상에 넘깁니다.","x":["선저폐수는 처리할 수 있습니다.","탱크 소제 폐수는 처리할 수 있습니다.","바닥 소제수는 처리할 수 있습니다.","정답(처리 못 함). 슬러지는 여과장치로 처리하지 않습니다."],"t":"슬러지 = 소각 또는 육상 처리"},"2025-4-기관2-10":{"w":"콜레서는 작은 기름 입자를 흡착시켜 뭉치게 해 큰 입자로 만들어 떠오르게 합니다.","x":["잘게 부수지 않습니다.","정답. 큰 입자로 흡착·합체","물만 통과시키는 필터가 아닙니다.","기름만 통과시키는 필터가 아닙니다."],"t":"콜레서 = 기름 입자 합체"},"2025-4-기관2-11":{"w":"서리는 열을 잘 전달하지 못하는 단열층이 되어 증발코일의 전열을 방해합니다. 제상해야 전열이 좋아져 냉동능력이 회복됩니다.","x":["응축기와 관계없습니다.","부식 방지가 주목적이 아닙니다.","정답. 전열을 좋게 하기 위해","무게로 인한 파손이 주목적이 아닙니다."],"t":"제상 = 전열 회복"},"2025-4-기관2-12":{"w":"유분리기는 압축기에서 나온 냉매 가스 속의 윤활유를 분리해 다시 압축기(크랭크케이스)로 되돌려 보냅니다.","x":["팽창밸브로 보내지 않습니다.","응축기로 보내지 않습니다.","드레인탱크로 보내지 않습니다.","정답. 압축기로 되돌려 보냅니다."],"t":"유분리기 → 압축기로 반송"},"2025-4-기관2-13":{"w":"공기조화장치의 공기냉각기는 냉매가 증발하며 공기의 열을 빼앗으므로 냉동장치의 증발기 역할을 합니다.","x":["압축기가 아닙니다.","응축기는 열을 버리는 곳입니다.","정답. 공기냉각기 = 증발기","팽창밸브가 아닙니다."],"t":"공기냉각기 = 증발기"},"2025-4-기관2-15":{"w":"습공기의 절대습도와 같은 온도에서 포화공기의 절대습도의 비를 [%]로 나타낸 것을 포화도(비교습도)라 합니다. 상대습도는 수증기 분압의 비입니다.","x":["건조도는 습증기 속 건증기의 비율입니다.","정답. 절대습도의 비 = 포화도","과열도는 과열증기와 포화온도의 차이입니다.","상대습도는 수증기 분압의 비입니다."],"t":"포화도 = 절대습도 비, 상대습도 = 분압 비"},"2025-4-기관2-16":{"w":"스크레이핑은 스크레이퍼로 평면이나 곡면(베어링 면 등)을 조금씩 긁어 정밀하게 다듬는 작업입니다.","x":["구멍 가공은 리밍·보링입니다.","연삭은 숫돌로 합니다.","정답. 평면·곡면의 정밀 다듬질","숫돌 다듬질은 연삭입니다."],"t":"스크레이핑 = 긁어서 정밀 다듬질"},"2025-4-기관2-17":{"w":"태핏(밸브) 간극처럼 좁은 틈새는 얇은 강판을 두께별로 모은 필러게이지(틈새게이지)로 잽니다.","x":["버니어 캘리퍼스는 길이·지름을 잽니다.","정답. 필러게이지","마이크로미터는 정밀 외경을 잽니다.","한계게이지는 합격 여부만 봅니다."],"t":"틈새 = 필러게이지"},"2025-4-기관2-19":{"w":"널링은 공구 손잡이 등에 미끄럼 방지용 요철 무늬를 내는 작업으로, 선반에 널링 공구를 대고 가공합니다.","x":["정답. 널링 = 선반 가공","밀링은 평면·홈 가공입니다.","셰이퍼는 평면 가공입니다.","플레이너는 큰 평면 가공입니다."],"t":"널링 = 선반"},"2025-4-기관2-20":{"w":"피복제는 아크를 안정시키고, 용융속도를 조절하며, 슬랙으로 용착금속을 보호해 강도를 유지하게 합니다. 전류를 억제하는 역할은 없습니다.","x":["아크를 안정시킵니다.","용융속도를 조절합니다.","용착금속을 보호합니다.","정답(아닌 것). 전류 억제는 피복제 역할이 아닙니다."],"t":"피복제 = 아크 안정·보호·용융 조절"},"2025-4-기관2-22":{"w":"종강력재는 배의 길이 방향으로 이어져 세로 방향 힘을 견디는 부재로 용골, 킬슨, 거더, 종통재 등이 있습니다. 늑골(프레임)은 횡강력재입니다.","x":["용골은 종강력재입니다.","정답(아닌 것). 늑골은 횡강력재입니다.","거더는 종강력재입니다.","킬슨은 종강력재입니다."],"t":"늑골 = 횡강력재"},"2025-4-기관2-24":{"w":"축척은 실물보다 작게, 배척은 실물보다 크게, 현척(실척)은 실물과 같은 크기로 그리는 것입니다.","x":["척도는 표제란에 기입합니다.","배척은 확대입니다.","정답(옳지 않은 것). 실물 크기는 현척입니다.","치수는 항상 실물 크기로 기입합니다."],"t":"축척 < 현척 = 실물 < 배척"},"2025-4-기관2-25":{"w":"정면도는 물체의 모양과 특징을 가장 잘 나타내는 방향에서 그린 도면으로, 치수를 집중적으로 기입합니다.","x":["평면도는 위에서 본 도면입니다.","정답. 정면도","배면도는 뒤에서 본 도면입니다.","우측면도는 오른쪽에서 본 도면입니다."],"t":"정면도 = 가장 중요한 도면"},"2025-4-기관3-1":{"w":"인덕턴스(코일)만 있는 회로에서는 전류가 전압보다 90° 늦습니다. 전압 V를 기준(오른쪽)으로 하면 전류 I는 아래쪽(90° 뒤)을 향하는 ㉯입니다.","x":["위상이 같은 저항(R) 회로입니다.","정답. 전류가 90° 늦음","전류가 90° 앞선 콘덴서(C) 회로입니다.","약간 늦은 RL 회로입니다."],"t":"L = 전류 90° 늦음, C = 전류 90° 빠름"},"2025-4-기관3-2":{"w":"교류 전압계·전류계는 실효값을 가리킵니다.","x":["최대값이 아닙니다.","평균값이 아닙니다.","정답. 실효값","순시값이 아닙니다."],"t":"교류 계기 = 실효값"},"2025-4-기관3-3":{"w":"직렬 합성저항 20 + 30 + 50 = 100[Ω]. 전류 I = 100 ÷ 100 = 1[A]입니다.","x":["정답. 100[V] ÷ 100[Ω] = 1[A]","틀린 값입니다.","틀린 값입니다.","틀린 값입니다."],"t":"직렬 = 저항을 더한다"},"2025-4-기관3-4":{"w":"유도성 리액턴스 XL = 2πfL [Ω]입니다. 용량성 리액턴스는 XC = 1/(2πfC) [Ω]입니다.","x":["틀린 식입니다.","정답. XL = 2πfL","용량성 리액턴스 XC입니다.","틀린 식입니다."],"t":"XL = 2πfL, XC = 1/2πfC"},"2025-4-기관3-5":{"w":"직류 전력 P = VI = I²R = V²/R 입니다. I²÷R은 틀린 식입니다.","x":["맞는 식입니다.","맞는 식입니다.","맞는 식입니다.","정답(옳지 않은 것). I² ÷ R은 틀립니다."],"t":"P = VI = I²R = V²/R"},"2025-4-기관3-6":{"w":"피상전력은 전압 × 전류(VA)이므로 전압계와 전류계만 있으면 구할 수 있습니다.","x":["정답. 전압계 + 전류계","역률계는 필요 없습니다.","역률계는 필요 없습니다.","주파수계는 필요 없습니다."],"t":"피상전력 = V × I"},"2025-4-기관3-7":{"w":"전류는 전압에 비례하고 저항에 반비례한다는 것이 옴의 법칙(I = V/R)입니다.","x":["정답. 옴의 법칙","쿨롱의 법칙은 전하 사이의 힘입니다.","앙페르의 법칙은 전류와 자기장입니다.","줄의 법칙은 전류의 발열량입니다."],"t":"I = V / R"},"2025-4-기관3-9":{"w":"P = V² ÷ R = 220² ÷ 220 = 220[W]입니다. (전류 1[A] × 220[V])","x":["틀린 값입니다.","틀린 값입니다.","정답. 220²/220 = 220[W]","틀린 값입니다."],"t":"P = V² / R"},"2025-4-기관3-10":{"w":"납축전지는 충전할 때 물이 전기분해되어 수소가스가 발생합니다. 수소는 폭발성이 있어 축전지실은 통풍이 잘 되어야 합니다.","x":["정답. 수소가스 발생","질소가 아닙니다.","아황산가스가 아닙니다.","이산화탄소가 아닙니다."],"t":"축전지실 = 수소 → 통풍·화기 엄금"},"2025-4-기관3-11":{"w":"역기전력은 회전자가 자속을 끊으며 회전할 때 생기므로 회전 속도에 비례합니다. 회전자가 정지해 있으면 역기전력은 0입니다. (그래서 기동 전류가 큽니다)","x":["정답. 정지 시 역기전력 0","정격속도에서는 역기전력이 있습니다.","동기속도에서도 역기전력이 있습니다.","빠를수록 역기전력은 커집니다."],"t":"역기전력 ∝ 속도, 정지 시 0"},"2025-4-기관3-12":{"w":"싱크로스코프 바늘은 병렬로 넣으려는 발전기(No.2)가 모선(No.1)보다 빠르면 시계방향(FAST), 느리면 반시계방향으로 돕니다. 시계방향이면 No.2가 빠르고 No.1이 느린 상태입니다.","x":["반대입니다.","정답. 시계방향 = 투입 발전기가 빠름 = No.1이 느림","역률과 관계없습니다.","역률과 관계없습니다."],"t":"싱크로스코프 시계방향 = 투입기 FAST"},"2025-4-기관3-13":{"w":"동기 전동기는 기동 토크가 없어 스스로 기동하지 못하므로 기동권선이나 외부 장치로 동기속도 가까이 돌려 줘야 합니다.","x":["유도 전동기는 스스로 기동합니다.","직권 전동기는 기동 토크가 큽니다.","정답. 동기 전동기 = 자기 기동 불가","분권 전동기는 스스로 기동합니다."],"t":"동기 전동기 = 기동 토크 없음"},"2025-4-기관3-14":{"w":"변압기 철심을 얇은 강판으로 겹쳐(성층) 만드는 것은 와류(맴돌이 전류) 손실을 줄이기 위해서입니다. 성층하지 않으면 와류손이 크게 늘어납니다.","x":["동손은 권선 저항 손실입니다.","정답. 와류손 증가","유전체 손실과 관계없습니다.","히스테리시스손은 규소강판으로 줄입니다."],"t":"성층 = 와류손↓, 규소강 = 히스테리시스손↓"},"2025-4-기관3-15":{"w":"전동기 명판의 440[V]는 실효값입니다. (최대값은 약 622[V])","x":["틀린 값입니다.","정답. 명판 전압 = 실효값","최대값입니다.","틀린 값입니다."],"t":"정격 전압 = 실효값"},"2025-4-기관3-16":{"w":"3상 유도전동기 고정자에 3상 전류가 흐르면 일정한 속도로 도는 회전자계가 생기고, 이 자계가 회전자를 끌고 돕니다.","x":["정답. 회전자계","교번자계는 단상에서 생깁니다.","해당하지 않습니다.","해당하지 않습니다."],"t":"3상 = 회전자계, 단상 = 교번자계"},"2025-4-기관3-17":{"w":"계기용 변압기(PT)는 고전압을 낮춰 전압계로 재는 장치로, 1차측을 피측정 회로에 병렬로 연결합니다. 계기용 변류기(CT)는 직렬로 연결합니다.","x":["직렬은 변류기(CT) 연결입니다.","정답. PT 1차측 = 병렬","2차측에는 계기를 연결합니다.","2차측에는 계기를 연결합니다."],"t":"PT 병렬, CT 직렬"},"2025-4-기관3-18":{"w":"부동 충전법은 충전기가 평소 부하에 전류를 공급하면서 축전지의 자기방전을 보충하고, 정전 시에는 축전지가 자동으로 부하에 전류를 공급하는 방식입니다.","x":["정전류 충전은 일정 전류로 충전하는 방법입니다.","정답. 부동 충전법","급속 충전은 짧은 시간에 큰 전류로 충전합니다.","균등 충전은 셀 사이 전압을 맞추는 충전입니다."],"t":"부동 충전 = 충전기 + 축전지 병렬 상시 연결"},"2025-4-기관3-19":{"w":"정류된 맥동 전압을 평탄하게 하는 회로는 평활회로이고, 여기에는 전하를 저장·방전하는 콘덴서를 주로 씁니다.","x":["정류회로가 아닙니다.","정류회로·가변저항이 아닙니다.","정답. 평활회로, 콘덴서","가변저항이 아닙니다."],"t":"평활회로 = 콘덴서"},"2025-4-기관3-20":{"w":"SCR(실리콘 제어 정류기)은 다이오드 기호의 캐소드 쪽에 게이트(G) 단자가 붙은 모양입니다.","x":["양방향 다이오드(DIAC) 모양입니다.","양방향 소자(TRIAC) 모양입니다.","정답. 다이오드 + 게이트 = SCR","트랜지스터(UJT 등) 기호입니다."],"t":"SCR = 다이오드 + 게이트"},"2025-4-기관3-21":{"w":"중간 탭 변압기와 다이오드 2개를 쓴 전파 정류회로이므로 입력의 음(−) 반주기도 뒤집혀 출력되어 반원이 연속으로 이어진 파형이 됩니다.","x":["입력 교류 그대로입니다.","음의 반파만 나온 파형입니다.","정답. 전파 정류 파형","반파 정류 파형입니다."],"t":"다이오드 2개 + 중간탭 = 전파 정류"},"2025-4-기관3-22":{"w":"입력이 베이스에, 출력이 컬렉터에서 나오고 이미터가 입력·출력 공통(접지 쪽)이므로 이미터 접지 방식입니다. 가장 많이 쓰는 증폭 방식입니다.","x":["베이스 접지는 입력이 이미터입니다.","정답. 이미터 공통 = 이미터 접지","컬렉터 접지는 출력이 이미터입니다.","트랜지스터에는 애노드가 없습니다."],"t":"입력 B, 출력 C = 이미터 접지"},"2025-4-기관3-23":{"w":"제너 다이오드 기호는 다이오드 기호의 막대(캐소드) 끝이 꺾인 모양(Z자 형태)입니다.","x":["다른 소자 기호입니다.","가변용량(버랙터) 다이오드 기호입니다.","정답. 막대 끝이 꺾인 모양 = 제너","일반 다이오드입니다."],"t":"제너 = 꺾인 막대"},"2025-4-기관3-24":{"w":"보일러 화염검출기(flame eye)에는 빛을 받으면 저항이 줄어드는 CdS(황화카드뮴) 셀을 널리 씁니다.","x":["정답. CdS","광전지는 전압을 만드는 소자입니다.","SSS는 해당하지 않습니다.","MOSFET는 전력 스위칭 소자입니다."],"t":"화염검출 = CdS"},"2025-4-기관3-25":{"w":"NPN 트랜지스터는 N(이미터)-P(베이스)-N(컬렉터) 구조입니다. 베이스는 P형 반도체입니다.","x":["NPN의 다수 반송자는 전자입니다.","정답(옳지 않은 것). 베이스는 P형입니다.","C-B 사이는 역방향입니다.","E-B 사이는 순방향입니다."],"t":"NPN = 베이스 P형"},"2025-4-직무일반-2":{"w":"쓸 수 없는 소모품도 바다에 버리면 안 되고 육상 수용시설에 처리해야 합니다.","x":["변질되지 않게 보관합니다.","무거운 것은 고정합니다.","사용량과 잔량을 관리합니다.","정답(옳지 않은 것). 바다에 버리면 안 됩니다."],"t":"폐기물 = 해양 투기 금지"},"2025-4-직무일반-3":{"w":"수급 전에는 선내 교육, 탱크 잔량 확인, 신호기·등화 확인 등을 합니다. 기름기록부는 수급이 끝난 뒤 실제 수급량을 기록합니다.","x":["정답(아닌 것). 기름기록부는 수급 후 기록합니다.","선내 교육을 합니다.","잔량을 확인합니다.","신호기·등화를 확인합니다."],"t":"기름기록부 = 실적을 사후 기록"},"2025-4-직무일반-4":{"w":"그림은 둥근 눈금판과 바늘로 작은 변위를 읽는 다이얼게이지입니다. 축의 흔들림(휨)·크랭크암 개폐량 등을 잽니다.","x":["틈새게이지는 얇은 판 묶음입니다.","온도게이지가 아닙니다.","정답. 다이얼게이지","한계게이지는 통과·정지 게이지입니다."],"t":"다이얼게이지 = 작은 변위 측정"},"2025-4-직무일반-5":{"w":"입거 전에는 도면·특수공구 준비, 냉각수 연결 위치 확인 등을 합니다. 소모품은 수리 중에도 필요하므로 재고를 소진하면 안 됩니다.","x":["정답(적절하지 않은 것). 소모품은 충분히 확보해야 합니다.","도면을 준비합니다.","냉각수 연결 위치를 확인합니다.","특수공구를 준비합니다."],"t":"입거 준비 = 도면·공구·연결 위치"},"2025-4-직무일반-6":{"w":"유출 기름은 오일펜스로 확산을 막고 흡착재·겔화제로 수거합니다. 유처리제는 기름을 잘게 분산시키는 약제이며, 기름을 가라앉히는(침강) 처리는 해저 오염을 일으켜 허용되지 않습니다.","x":["흡착재로 수거합니다.","정답(아닌 것). 침강 처리는 하지 않습니다.","겔화제로 굳혀 수거합니다.","오일펜스로 확산을 막습니다."],"t":"기름 침강 처리 금지"},"2025-4-직무일반-7":{"w":"배출통제해역(ECA)에서는 연료유 황 함유량 기준(0.1[%] 이하)이 엄격하므로, 들어가기 전에 저유황유로 바꿔 황산화물(SOx) 배출을 줄입니다.","x":["정답. 황산화물 배출 감소","늘리기 위해서가 아닙니다.","질소산화물은 기관 조정·SCR 등으로 줄입니다.","늘리기 위해서가 아닙니다."],"t":"ECA 연료 교환 = SOx 감소"},"2025-4-직무일반-8":{"w":"수급 시 갑판 배수구(스커퍼)는 막아 두고, 방제 자재를 가까이 두고, 탱크를 자주 측심해 넘치지 않게 합니다. 맨홀을 열어 두면 안 됩니다.","x":["①은 틀립니다(배수구는 막아야 함).","①은 틀립니다.","정답. ②, ③","④는 틀립니다."],"t":"수급 = 스커퍼 막기·방제자재·자주 측심"},"2025-4-직무일반-9":{"w":"평형판식 기름여과장치는 운전 전에 장치 안을 물(청수 또는 해수)로 채워 둡니다. 기름을 채워 두면 분리가 되지 않습니다.","x":["정답(옳지 않은 것). 운전 전에는 물로 채웁니다.","가열하면 분리 효과가 좋아집니다.","유량이 많으면 난류로 분리가 나빠집니다.","가열 코일로 고점도 혼합액도 처리할 수 있습니다."],"t":"기름여과장치 = 운전 전 물 채움"},"2025-4-직무일반-10":{"w":"유성찌꺼기는 소각기로 소각하거나, 찌꺼기 탱크에 저장한 뒤 육상 폐유처리시설로 넘깁니다. 청정기로 다시 청정할 수 있는 것이 아닙니다.","x":["소각할 수 있습니다.","저장할 수 있습니다.","정답(옳지 않은 것). 비중판 교환은 처리 방법이 아닙니다.","육상에 양륙할 수 있습니다."],"t":"유성찌꺼기 = 소각·저장·육상 처리"},"2025-4-직무일반-11":{"w":"손가락 절단 시에는 거즈로 직접 압박하고 높이 들어 지혈합니다. 절단된 부분은 거즈로 싸서 비닐에 넣고 차갑게 보관합니다. 손가락에 지혈대를 쓰면 조직이 손상될 수 있어 쓰지 않습니다.","x":["직접 압박 지혈은 맞습니다.","정답(옳지 않은 것). 지혈대는 조직을 손상시킵니다.","절단 부위 보관 방법이 맞습니다.","거즈 압박과 거상은 맞습니다."],"t":"손가락 절단 = 직접 압박 + 거상"},"2025-4-직무일반-12":{"w":"익수자는 물을 토하게 하려고 시간을 쓰지 말고 즉시 인공호흡(심폐소생술)을 시작해야 합니다.","x":["정답(옳지 않은 것). 물 토하게 하기보다 즉시 인공호흡","보이는 이물질은 꺼냅니다.","원인 제거 후 산소·인공호흡을 합니다.","등을 두드려 이물질을 뺍니다."],"t":"익수 = 즉시 인공호흡"},"2025-4-직무일반-13":{"w":"감전자는 전원을 끊고 통풍이 잘 되는 곳으로 옮겨 필요하면 인공호흡·심장마사지를 합니다. 화상 부위는 깨끗이 하고 필요하면 화상 연고로 처치합니다. 1주일 동안 연고를 바르지 말라는 것은 틀린 처치입니다.","x":["필요하면 심장 마사지를 합니다.","통풍이 잘 되는 곳으로 옮깁니다.","필요하면 인공호흡을 합니다.","정답(옳지 않은 것). 화상 처치를 해야 합니다."],"t":"감전 = 전원 차단 → 인공호흡·심폐소생"},"2025-4-직무일반-14":{"w":"비상빌지흡입밸브는 기관실 침수 시 주 해수펌프로 빌지를 빼내는 밸브로, 평소에는 닫아 두어야 합니다. 열어 두면 해수가 역류할 수 있습니다.","x":["정답(옳지 않은 것). 평소에는 닫아 둡니다.","킹스톤 밸브 개폐를 확실히 합니다.","방수 기자재 사용법을 알아둡니다.","교육·훈련을 합니다."],"t":"비상빌지흡입밸브 = 평소 닫힘"},"2025-4-직무일반-15":{"w":"침수 시에는 침수 부위를 확인하고, 작은 구멍은 쐐기로 막고, 배수 펌프를 가동합니다. 발전기를 멈추면 배수 펌프도 멈추므로 발전기는 가능한 한 운전을 유지해야 합니다.","x":["침수 부위를 확인합니다.","작은 파공은 쐐기로 막습니다.","침몰 위험 시 주요 서류를 반출합니다.","정답(옳지 않은 것). 발전기를 멈추면 배수할 수 없습니다."],"t":"침수 = 배수를 위해 발전기 유지"},"2025-4-직무일반-16":{"w":"발전기가 급정지하면 휴지 중인 발전기를 시동해 전원을 복구하고, 고장 원인을 조사합니다. 예비발전기로 복구할 수 있으므로 즉시 비상발전기를 시동하는 것은 일반적인 조치가 아닙니다. (비상발전기는 자동 기동합니다)","x":["원인을 조사합니다.","전원을 복구합니다.","예비 발전기를 시동합니다.","정답(적절하지 않은 것). 예비발전기로 먼저 복구합니다."],"t":"발전기 급정지 = 예비발전기 기동 → 송전"},"2025-4-직무일반-17":{"w":"발전기 전압은 여자(계자)전류로 정해지므로 AVR 고장, 여자장치 불안정, 여자기 다이오드 소손 등이 전압 변동의 원인입니다. 원동기 냉각 불량은 전압 변동의 직접 원인이 아닙니다.","x":["AVR 고장은 원인입니다.","여자장치 불안정은 원인입니다.","정답(아닌 것). 냉각 불량은 직접 원인이 아닙니다.","다이오드 소손은 원인입니다."],"t":"전압 = 여자 계통(AVR)"},"2025-4-직무일반-18":{"w":"과전류가 흐르면 전선·기기가 과열되어 전기화재의 위험이 가장 큽니다.","x":["정답. 과전류","절연저항이 높으면 안전합니다.","부하용량이 큰 것 자체는 위험이 아닙니다.","정격 이내라면 오래 사용해도 위험하지 않습니다."],"t":"전기화재 1순위 = 과전류"},"2025-4-직무일반-19":{"w":"메탄, 수소, 프로판은 가연성 가스로 폭발 위험이 있습니다. 질소는 불연성 가스입니다.","x":["메탄은 폭발성입니다.","정답. 질소는 불연성","수소는 폭발성입니다.","프로판은 폭발성입니다."],"t":"질소 = 불연성(불활성)"},"2025-4-직무일반-20":{"w":"CO₂ 소화기는 레버·호스·안전핀을 점검하고, 무게가 규정의 2/3 이하로 줄면 재충전하며, 직사광선을 피해 40[℃] 이하에서 보관합니다. 추운 곳에서 보온할 필요는 없습니다.","x":["주기적으로 점검합니다.","2/3 이하면 재충전합니다.","정답(옳지 않은 것). 보온 보관은 필요 없습니다.","40[℃] 이하에서 보관합니다."],"t":"CO₂ 소화기 = 무게로 점검, 고온 주의"},"2025-4-직무일반-21":{"w":"화재제어도에는 방화 구획, 소화 설비, 화재탐지·경보 장치, 통풍장치와 차단 장치, 탈출 통로 등을 표시합니다. 시동 공기탱크는 표시 대상이 아닙니다.","x":["통풍장치는 표시합니다.","정답(아닌 것). 시동공기탱크는 표시하지 않습니다.","구획은 표시합니다.","소화 설비는 표시합니다."],"t":"화재제어도 = 구획·소화설비·통풍·탈출로"},"2025-4-직무일반-22":{"w":"선박법상 대한민국 선박은 국유·공유선, 대한민국 국민이 소유한 선박, 대한민국 법인이 소유한 선박 등입니다. 외국 정부로부터 용선한 선박은 소유자가 외국이므로 대한민국 선박이 아닙니다.","x":["정답(아닌 것). 외국 정부 소유 선박입니다.","한국인 소유 선박은 대한민국 선박입니다.","국유선은 대한민국 선박입니다.","한국 법인 소유 선박은 대한민국 선박입니다."],"t":"국적 = 소유자 기준"},"2025-4-직무일반-23":{"w":"분뇨저장탱크는 충분한 배출펌프, 적정 저장용량, 저장량 표시장치(액면계·측심관), 가스 방출 장치 등을 갖춥니다. 고압 대비 안전밸브는 기준에 없습니다.","x":["배출펌프는 기준입니다.","정답(옳지 않은 것). 안전밸브는 기준이 아닙니다.","저장용량은 기준입니다.","저장량 표시장치는 기준입니다."],"t":"분뇨저장탱크 = 배출펌프·용량·표시장치"},"2025-4-직무일반-24":{"w":"해양오염방지설비를 개조하거나 수리할 때는 임시검사를 받아야 합니다.","x":["정기검사는 증서 발급·갱신 때 받습니다.","중간검사는 정기검사 사이에 받습니다.","정답. 개조·수리 = 임시검사","임시항해검사는 증서 없이 임시로 항해할 때 받습니다."],"t":"개조·수리 = 임시검사"},"2025-4-직무일반-25":{"w":"IMO 형식승인 소각기로는 PVC(폴리염화비닐)를 소각할 수 있습니다. PCB, 중금속 폐기물, 할로겐 화합물을 함유한 정제석유제품 등은 소각이 금지됩니다.","x":["정답. PVC는 승인 소각기에서 소각 가능","PCB는 소각 금지","중금속 폐기물은 소각 금지","할로겐 함유 석유제품은 소각 금지"],"t":"승인 소각기 = PVC 소각 가능"},"2025-4-영어-1":{"w":"\"냉각 청수탱크를 청수로 다시 채웠다.\" refill = 다시 채우다.","x":["Gauged = 측정했다","Examined = 검사했다","정답. Refilled = 다시 채웠다","Discharged = 배출했다"],"t":"refill = 보충하다"},"2025-4-영어-2":{"w":"wear down = 마멸량. \"실린더 라이너의 마멸량을 측정했다.\"","x":["누설량은 leakage입니다.","정답. 마멸량","부식은 corrosion입니다.","비중량은 specific weight입니다."],"t":"wear = 마멸"},"2025-4-영어-3":{"w":"입항하다 = arrive at. \"S/B Eng' for arriving at Busan.\" (출항은 leaving)","x":["at이 빠졌습니다.","leaving은 출항입니다.","정답. arriving at Busan","leaving은 출항입니다."],"t":"arrive at 입항, leave 출항"},"2025-4-영어-4":{"w":"발전기·전동기의 절연저항은 megger(메거)로 측정합니다.","x":["clamp meter = 후크형 전류계","ammeter = 전류계","voltage meter = 전압계","정답. megger = 절연저항계"],"t":"megger = 절연저항 측정"},"2025-4-영어-5":{"w":"\"윤활유 펌프를 개방 정비했다.\" lubricating oil pump = 윤활유 펌프.","x":["정답. lubricating oil pump","grinding = 연삭","indicating = 지시","welding = 용접"],"t":"L.O. = lubricating oil"},"2025-4-영어-6":{"w":"시동공기밸브 = starting air valve 입니다.","x":["시동이 빠졌습니다.","정답. starting air valves","시동공기 감압밸브입니다.","시동공기 분배밸브입니다."],"t":"starting air valve = 시동공기밸브"},"2025-4-영어-7":{"w":"크랭크축은 저널(Journal), 핀(Pin), 암(Arm)으로 이루어집니다. 림(Rim)은 플라이휠의 바깥 둘레입니다.","x":["Journal = 크랭크 저널","Pin = 크랭크핀","Arm = 크랭크암","정답(아닌 것). Rim = 플라이휠 테두리"],"t":"크랭크축 = journal + pin + arm"},"2025-4-영어-8":{"w":"\"터닝기어를 연결(engage)하고 주기관을 20분간 돌렸다(turn).\"","x":["정답. Engaged, turned","순서가 바뀌었습니다.","틀립니다.","틀립니다."],"t":"engage = 연결, disengage = 분리"},"2025-4-영어-9":{"w":"\"지방표준시(L.S.T.)에 맞추려고 시계를 1시간 앞당겼다.\" advance = 앞당기다.","x":["Received = 받았다","Slowed = 늦췄다(시계에는 retard를 씀)","정답. Advanced = 앞당겼다","Completed = 끝냈다"],"t":"advance 앞당김, retard 늦춤"},"2025-4-영어-10":{"w":"주기관 재킷 냉각 청수펌프(원심펌프)의 부품으로 impeller, mouth ring, mechanical seal은 맞지만, relief valve(릴리프 밸브)는 원심펌프 부품이 아닙니다.","x":["impeller = 임펠러","정답(적당하지 않은 것). relief valve는 원심펌프에 없습니다.","mouth ring = 마우스링","mechanical seal = 기계식 실"],"t":"원심펌프 = impeller, mouth ring, seal"},"2025-4-영어-11":{"w":"\"시간당 몇 톤으로 펌핑하십니까?\" (수급할 때 송유 속도를 묻는 표현)","x":["펌프 대수를 묻지 않습니다.","총량을 묻지 않습니다.","펌프 용량을 묻는 것이 아닙니다.","정답. 시간당 몇 톤으로 펌핑"],"t":"per hour = 시간당"},"2025-4-영어-12":{"w":"\"디젤기관 내부에는 버너가 없다.\" 디젤기관은 압축열로 착화하며, 버너는 보일러에 있습니다.","x":["피스톤은 있습니다.","정답. burner는 보일러 장치","실린더는 있습니다.","크랭크축은 있습니다."],"t":"burner = 보일러"},"2025-4-영어-13":{"w":"화장실·소변기 배수, 의료실 배수, 살아 있는 동물이 있는 공간의 배수는 MARPOL 부속서 Ⅳ의 오수(Sewage) 정의입니다.","x":["정답. Sewage = 오수","동물 사체입니다.","생활 폐기물입니다.","운항 폐기물입니다."],"t":"sewage = 화장실·의료실·동물 공간 배수"},"2025-4-영어-15":{"w":"뜨겁고 차가운 정도(온도)를 재는 도구는 thermometer(온도계)입니다.","x":["Barometer = 기압계","정답. Thermometer = 온도계","Calorimeter = 열량계","Salinometer = 염분계"],"t":"thermometer = 온도계"},"2025-4-영어-16":{"w":"10,000[kW]급 대형 주기관은 압축공기(Compressed air)로 시동합니다.","x":["가열 연료로 시동하지 않습니다.","정답. Compressed air = 압축공기","소형 기관의 시동 방법입니다.","틀립니다."],"t":"대형 주기관 = 압축공기 시동"},"2025-4-영어-17":{"w":"프로펠러 추력을 선체에 전달하는 베어링은 thrust bearing(추력 베어링)입니다.","x":["main bearing = 메인 베어링","정답. thrust bearing = 추력 베어링","crosshead bearing = 크로스헤드 베어링","crank pin bearing = 크랭크핀 베어링"],"t":"thrust bearing = 추력 전달"},"2025-4-영어-18":{"w":"닻을 다루는 일반적인 장치는 windlass(양묘기)입니다.","x":["정답. windlass = 양묘기","mooring winch = 계선 윈치","jib crane = 지브 크레인","capstan = 캡스턴"],"t":"windlass = anchor handling"},"2025-4-영어-19":{"w":"우회전 프로펠러(right-handed propeller)는 배 뒤에서 보았을 때 전진 시 시계방향(clockwise)으로 돕니다.","x":["정답. clockwise = 시계방향","outward = 바깥쪽","anticlockwise = 반시계방향","inward = 안쪽"],"t":"right-handed = clockwise"},"2025-4-영어-22":{"w":"갑판기계의 주 구동 방식으로 가장 흔한 것은 유압(hydraulic)입니다.","x":["steam = 증기(옛 방식)","pneumatic = 공기압","정답. hydraulic = 유압","electronic = 전자식"],"t":"갑판기계 = hydraulic"},"2025-4-영어-23":{"w":"F.W.E.(Finished With Engine, 기관 사용 종료) 후에는 테스트 콕을 열고, 보조 송풍기를 멈추고, 에어 러닝을 하고, 터닝기어를 연결(engage)해 주기관을 돌립니다. 터닝기어를 분리(disengage)하는 것은 시동 준비 때 하는 일입니다.","x":["테스트 콕을 엽니다.","보조 송풍기를 멈춥니다.","에어 러닝을 합니다.","정답(아닌 것). F.W.E. 후에는 터닝기어를 연결합니다."],"t":"F.W.E. 후 = engage turning gear"},"2025-4-영어-24":{"w":"원심펌프에서 모터의 에너지를 받아 유체를 바깥으로 가속시키는 회전 부품은 impeller(임펠러)입니다.","x":["정답. Impeller = 임펠러","Bearing = 베어링","Packing gland = 패킹 글랜드","Mechanical seal = 기계식 실"],"t":"impeller = 회전차"},"2025-4-영어-25":{"w":"선박의 열교환기는 대부분 뜨거운 액체를 해수나 청수로 식히는 냉각기(cooler)입니다.","x":["공기나 증기가 아닙니다.","기기 이름입니다.","냉각되는 쪽의 액체입니다.","정답. sea water or fresh water"],"t":"cooler = 해수·청수로 냉각"},"2021-1-기관1-3":{"w":"메인 베어링은 과부하, 윤활유 부족, 크랭크축 중심선 어긋남, 베어링 틈새 부적당 등으로 발열합니다. 점도지수가 큰 윤활유는 온도가 변해도 점도 변화가 작은 좋은 윤활유입니다.","x":["과부하는 발열 원인입니다.","중심선 어긋남은 편하중으로 발열 원인입니다.","윤활유 부족은 발열 원인입니다.","정답(아닌 것). 점도지수가 큰 윤활유는 좋은 윤활유입니다."],"t":"점도지수 큼 = 온도에 따른 점도 변화 작음(좋음)"},"2021-1-기관1-6":{"w":"연접봉을 길게 하면 경사 각도가 작아져 측압과 라이너 마멸이 줄지만, 기관의 높이가 높아집니다.","x":["경사 각도는 작아집니다.","측압은 작아집니다.","정답. 기관 높이가 높아집니다.","마멸은 줄어듭니다."],"t":"연접봉 길게 = 측압↓, 높이↑"},"2021-1-기관1-8":{"w":"플라이휠은 같은 무게라면 두께보다 지름을 크게 하는 것이 관성모멘트가 커서 회전을 고르게 하는 데 효과적입니다.","x":["정답(옳지 않은 것). 지름을 크게 하는 것이 효과적입니다.","저속 회전을 가능하게 합니다.","실린더 수가 적으면 더 커야 합니다.","고속기관은 작아도 됩니다."],"t":"플라이휠 = 지름이 효과적(관성모멘트)"},"2021-1-기관1-16":{"w":"추진 축계는 프로펠러축, 추력축, 중간축으로 이루어집니다. 캠축은 기관 내부 부품입니다.","x":["구성 요소입니다.","구성 요소입니다.","구성 요소입니다.","정답(아닌 것). 캠축"],"t":"캠축 = 기관 부품"},"2021-1-기관1-18":{"w":"슬립은 프로펠러에 의한 이론 속도와 배의 실제 속도의 차이입니다.","x":["정답. 프로펠러 속도 − 배의 속도","틀린 정의입니다.","틀린 정의입니다.","틀린 정의입니다."],"t":"슬립 = 이론 속도 − 실제 속도"},"2021-1-기관1-21":{"w":"원심 청정은 기름을 가열해 점도를 낮추고, 유량을 적게 해 기름이 청정기 안에 오래 머물게 하면 분리 효과가 좋아집니다.","x":["점도가 높으면 분리가 나쁩니다.","유량이 많으면 분리가 나쁩니다.","정답. 점도 낮게, 유량 적게","둘 다 반대입니다."],"t":"청정 = 가열(저점도) + 저유량"},"2021-1-기관1-24":{"w":"유성(油性)은 윤활유가 금속 마찰면에 강하게 달라붙어 얇은 유막을 만드는 성질입니다. 유막이 끊기기 쉬운 경계 윤활 상태에서 특히 중요합니다.","x":["점도는 기름의 끈적한 정도(흐름에 대한 저항)입니다.","정답. 마찰면에 흡착해 유막을 만드는 성질 = 유성","항유화성은 물과 잘 섞이지 않고 분리되는 성질입니다.","산화 안정도는 산화에 견디는 성질입니다."],"t":"유성 = 흡착해서 유막 형성"},"2021-1-기관2-4":{"w":"콜레서 분리법은 콜레서 필터로 작은 기름방울을 서로 응집시켜 큰 방울로 만들어 분리합니다.","x":["평행판 분리법은 판 사이 흐름으로 분리합니다.","중력 분리법은 비중 차로 분리합니다.","원심 분리법은 원심력으로 분리합니다.","정답. 응집 = 콜레서"],"t":"응집(합체) = 콜레서"},"2021-1-기관2-5":{"w":"갑판보기(윈치, 양묘기 등)는 바닷물과 비바람에 노출되므로 잘 씻겨 나가지 않는 그리스를 윤활제로 많이 씁니다.","x":["냉동유는 냉동기 압축기용입니다.","정답. 그리스","터빈유는 터빈·유압용입니다.","절연유는 변압기용입니다."],"t":"갑판보기 = 그리스"},"2021-1-기관2-6":{"w":"유압 조타기의 유압관에 공기가 섞이면 공기가 압축·팽창하며 소리(소음)가 나고 동작이 불안정해집니다.","x":["기름이 새면 압력이 떨어집니다.","정답. 공기 혼입","유온 상승은 주 원인이 아닙니다.","펌프 소손은 해당하지 않습니다."],"t":"유압관 소음 = 공기 혼입"},"2021-1-기관2-7":{"w":"불활성가스장치(IGS)는 보일러 배기가스를 세척기(스크러버)로 식히고 정화해 송풍기로 화물탱크에 보내며, 갑판 수봉장치(기밀상자)와 산소 농도 측정기를 갖춥니다. 수소 농도가 아니라 산소 농도를 측정합니다.","x":["세척기는 구성 요소입니다.","송풍기는 구성 요소입니다.","기밀상자(수봉장치)는 구성 요소입니다.","정답(아닌 것). 산소 농도를 측정합니다."],"t":"IGS = 산소 농도 8% 이하 유지"},"2021-1-기관2-9":{"w":"폐유소각장치에서 보조 연료 없이 스스로 연소할 수 있는 폐유의 수분 함량은 약 40~50[%]까지입니다. 그 이상이면 보조 버너가 필요합니다.","x":["이보다 많아도 연소 가능합니다.","정답. 약 40∼50[%]","너무 많습니다.","너무 많습니다."],"t":"폐유 자체 연소 = 수분 약 50% 이하"},"2021-1-기관2-13":{"w":"응축기 출구(액관)에는 건조기 → 전자밸브 → 자동팽창밸브 → (증발기) → 증발압력 조절밸브 순서로 설치합니다.","x":["순서가 틀렸습니다.","순서가 틀렸습니다.","순서가 틀렸습니다.","정답. 건조기 → 전자밸브 → 팽창밸브 → 증발압력 조절밸브"],"t":"건조기 → 전자밸브 → 팽창밸브"},"2021-1-기관2-16":{"w":"베어링 간극처럼 좁은 틈새는 필러 게이지(틈새게이지)로 잽니다.","x":["정답. 필러 게이지","센터 게이지는 나사 바이트 각도를 봅니다.","피치 게이지는 나사 피치를 잽니다.","곡률 게이지는 반지름을 잽니다."],"t":"틈새 = 필러 게이지"},"2021-1-기관2-17":{"w":"리머는 드릴로 뚫은 구멍의 내면을 정밀하게 다듬질하는 공구입니다.","x":["축 표면이 아닙니다.","정답. 구멍 내면 다듬질","나사산이 아닙니다.","모서리가 아닙니다."],"t":"리머 = 구멍 다듬질"},"2021-1-기관2-18":{"w":"선반으로 절삭, 보링, 널링, 나사 가공 등을 할 수 있습니다. 단조는 두드려 성형하는 작업으로 선반 작업이 아닙니다.","x":["선반 작업입니다.","정답(아닌 것). 단조","선반 작업입니다.","선반 작업입니다."],"t":"단조 = 해머·프레스"},"2021-1-기관2-20":{"w":"산소-아세틸렌 절단은 강을 산화시켜 태워 자르는 방법으로 연강이 가장 잘 절단됩니다. 스테인리스강·알루미늄·합금강은 산화물이 잘 녹지 않아 어렵습니다.","x":["합금강은 절단이 어렵습니다.","알루미늄은 절단이 어렵습니다.","정답. 연강","스테인리스강은 절단이 어렵습니다."],"t":"가스 절단 = 연강"},"2021-1-기관2-25":{"w":"치수공차 = 최대허용치수 − 최소허용치수 입니다.","x":["위 치수 허용차입니다.","아래 치수 허용차입니다.","정답. 최대 − 최소","틀립니다."],"t":"공차 = 최대 − 최소"},"2021-1-기관3-1":{"w":"10[Ω] 두 개가 병렬이므로 5[Ω]입니다. 여기에 4[Ω], 3[Ω]이 직렬로 붙어 4 + 3 + 5 = 12[Ω]입니다.","x":["직렬 부분만 더한 값입니다.","정답. 4 + 3 + (10∥10 = 5) = 12[Ω]","병렬 부분을 10으로 계산한 값입니다.","모두 더한 값입니다."],"t":"같은 저항 2개 병렬 = 절반"},"2021-1-기관3-3":{"w":"소비전력 P = V × I × 역률 = 200 × 2 × 0.9 = 360[W]입니다.","x":["틀립니다.","틀립니다.","정답. 360[W]","피상전력입니다."],"t":"P = VI cosθ"},"2021-1-기관3-4":{"w":"전류 I = 전하량 Q ÷ 시간 t = 0.3 ÷ 0.5 = 0.6[A]입니다.","x":["틀린 값입니다.","틀린 값입니다.","정답. 0.3[C] ÷ 0.5[s] = 0.6[A]","틀린 값입니다."],"t":"I = Q / t"},"2021-1-기관3-7":{"w":"UPS는 ①정류기로 교류를 직류로 바꿔 ③축전지를 충전하고, ②인버터로 다시 교류를 만들어 부하에 공급합니다. 정전되면 축전지가 인버터에 전력을 공급합니다. 따라서 ③은 축전지입니다.","x":["정류기는 ①입니다.","정답. ③ = 축전지","인버터는 ②입니다.","다이오드는 해당하지 않습니다."],"t":"UPS = 정류기 → 축전지 → 인버터"},"2021-1-기관3-11":{"w":"농형 유도전동기는 회전자가 도체 막대로 단락되어 있어 브러시가 필요 없습니다.","x":["직류기는 브러시가 있습니다.","직류기는 브러시가 있습니다.","정답. 농형 유도전동기","권선형은 슬립링·브러시가 있습니다."],"t":"농형 = 브러시 없음"},"2021-1-기관3-17":{"w":"권수비 = 440 ÷ 220 = 2. 전류는 전압과 반비례하므로 1차 전류 = 80 ÷ 2 = 40[A]입니다.","x":["틀린 값입니다.","틀린 값입니다.","틀린 값입니다.","정답. 80 ÷ 2 = 40[A]"],"t":"V1I1 = V2I2"},"2021-1-기관3-19":{"w":"RS 플립플롭은 R = S = 1 입력이 금지됩니다. JK 플립플롭은 이때 출력이 반전(토글)되도록 보완한 것입니다.","x":["RST는 클럭을 추가한 것입니다.","D 플립플롭은 입력을 하나로 줄인 것입니다.","T 플립플롭은 토글 전용입니다.","정답. JK 플립플롭"],"t":"JK = RS의 금지 입력 보완"},"2021-1-기관3-22":{"w":"전압 이득[dB] = 20 log(증폭률) = 20 × log100 = 20 × 2 = 40[dB]입니다.","x":["10배일 때입니다.","정답. 40[dB]","1,000배일 때입니다.","틀립니다."],"t":"dB = 20 log A"},"2021-1-기관3-25":{"w":"입력이 베이스에, 출력이 컬렉터에서 나오고 이미터가 입력·출력 공통(접지 쪽)이므로 이미터 접지 방식입니다. 가장 많이 쓰는 증폭 방식입니다.","x":["베이스 접지는 입력이 이미터입니다.","정답. 이미터 공통 = 이미터 접지","컬렉터 접지는 출력이 이미터입니다.","트랜지스터에는 애노드가 없습니다."],"t":"입력 B, 출력 C = 이미터 접지"},"2021-1-직무일반-1":{"w":"출거 전에는 물에 잠기는 곳(시체스트·선저밸브, 프로펠러·선미관, 선외밸브)의 조립 상태를 반드시 확인해야 합니다. 청정기 조립 상태는 출거 후에도 확인할 수 있습니다.","x":["정답(아닌 것). 청정기는 출거 전 필수 확인 사항이 아닙니다.","선저밸브는 반드시 확인합니다.","프로펠러·선미관은 반드시 확인합니다.","선외밸브는 반드시 확인합니다."],"t":"출거 전 = 수선 아래 장치 확인"},"2021-1-직무일반-5":{"w":"한국선급 검사는 연차, 중간, 정기, 입거검사 등입니다. 특별검사는 선급 검사 종류가 아닙니다.","x":["선급 검사입니다.","선급 검사입니다.","선급 검사입니다.","정답(아닌 것). 특별검사"],"t":"선급 = 정기·중간·연차·입거"},"2021-1-직무일반-10":{"w":"기름이 배출되면 즉시 신고하고, 확산을 막고, 흡착재 등으로 제거해야 합니다. 양을 확인할 때까지 기다리며 현장 보전만 하면 오염이 퍼집니다.","x":["즉시 제거합니다.","확산을 막습니다.","정답(옳지 않은 것). 즉시 방제해야 합니다.","신속히 신고합니다."],"t":"유출 = 신고·확산 방지·제거"},"2021-1-직무일반-18":{"w":"보상식 화재탐지기는 정온식(일정 온도 도달)과 차동식(급격한 온도 상승)을 합친 것으로, 둘 중 하나만 만족해도 작동합니다.","x":["정온식은 일정 온도에서만 작동합니다.","광전자식은 연기를 감지합니다.","차동식은 온도 상승률로만 작동합니다.","정답. 보상식"],"t":"보상식 = 정온식 + 차동식"},"2021-1-직무일반-20":{"w":"기름을 다룰 때 정전기는 유속이 빠를 때, 와류가 생길 때, 높은 곳에서 떨어질 때(낙차), 불순물(비전도성)이 섞였을 때 많이 생깁니다. 전도성 부유물이 많으면 전하가 잘 빠져나가 정전기가 덜 쌓입니다.","x":["유속이 빠르면 정전기가 많이 생깁니다.","정답(아닌 것). 전도성이 있으면 전하가 잘 빠집니다.","와류가 생기면 정전기가 많이 생깁니다.","낙차가 크면 정전기가 많이 생깁니다."],"t":"정전기 증가 = 빠른 유속·와류·낙차"},"2021-1-직무일반-22":{"w":"선박안전법상 항해구역은 평수구역, 연해구역, 근해구역, 원양구역입니다. '연안구역'은 해당하지 않습니다.","x":["항해구역입니다.","정답(아닌 것). 연해구역이 맞습니다.","항해구역입니다.","항해구역입니다."],"t":"평수·연해·근해·원양"},"2021-1-직무일반-23":{"w":"선박법은 선박의 국적, 톤수 측정·등록 등을 정해 해사 제도를 적정하게 운영하고 해상 질서를 유지하는 것이 목적입니다. 선내 질서 유지는 선원법의 목적입니다.","x":["정답(아닌 것). 선내 질서는 선원법입니다.","국적은 선박법 사항입니다.","톤수 측정은 선박법 사항입니다.","선박법의 목적입니다."],"t":"선내 질서 = 선원법"},"2021-1-영어-3":{"w":"\"주 섬프 탱크 바닥의 기름을 퍼내고 내부를 청소했다.\" bail = 퍼내다.","x":["검사했다","교환했다","공급했다","정답. Bailed"],"t":"bail out = 퍼내다"},"2021-1-영어-6":{"w":"그림은 사람들이 가운데로 모이는 표시로 비상 집합 장소(Muster station)입니다.","x":["연료 수급 장소가 아닙니다.","정답. Muster station = 집합 장소","소화 통제실이 아닙니다.","비상 탈출구가 아닙니다."],"t":"muster = 집합"},"2021-1-영어-8":{"w":"\"전동기 기동기의 전자 접촉기 불량 접점을 사포(sand paper)로 다듬어라.\" 접점은 고운 사포로 살짝 다듬습니다.","x":["정답. sand paper = 사포","연삭기는 너무 거칩니다.","쇠톱은 자르는 공구입니다.","휴대용 연삭기는 너무 거칩니다."],"t":"접점 손질 = 고운 사포"},"2021-1-영어-12":{"w":"보일러의 강제통풍(forced draft)에는 송풍기(fan)를 씁니다.","x":["furnace = 노(연소실)","정답. fan = 송풍기","fire bricks = 내화벽돌","alarm = 경보기"],"t":"forced draft fan = 강제통풍 송풍기"},"2021-1-영어-13":{"w":"윤활유는 마찰·마모 감소, 냉각, 밀봉 등을 합니다. 속도를 제한하는 것은 윤활유의 목적이 아닙니다.","x":["정답(옳지 않은 것). 속도 제한","냉각은 목적입니다.","마찰 감소는 목적입니다.","밀봉은 목적입니다."],"t":"윤활유 ≠ 속도 제한"},"2021-1-영어-14":{"w":"vapor compression type = 증기 압축식 입니다. \"대부분의 기계식 냉동장치는 증기 압축식이다.\"","x":["정답. 증기 압축식","흡수식은 absorption type입니다.","증기 분사식은 steam jet type입니다.","냉매 분사식이 아닙니다."],"t":"vapor compression = 증기 압축식"},"2021-1-영어-15":{"w":"축전지 전해액의 비중은 hydrometer(비중계)로 잽니다.","x":["고온계","점도계","정답. hydrometer","습도계"],"t":"hydrometer = 비중계"},"2021-1-영어-18":{"w":"닻을 다루는 일반적인 장치는 windlass(양묘기)입니다.","x":["정답. windlass = 양묘기","mooring winch = 계선 윈치","jib crane = 지브 크레인","capstan = 캡스턴"],"t":"windlass = anchor handling"},"2021-1-영어-22":{"w":"디젤 발전기는 디젤기관(a diesel engine)과 발전기(an electric generator)를 결합해 전기 에너지를 만듭니다.","x":["actuator = 작동기","가스기관·변환기가 아닙니다.","가솔린기관·압축기가 아닙니다.","정답. diesel engine + electric generator"],"t":"D/G = diesel + generator"},"2021-1-영어-23":{"w":"F.W.E.(Finished With Engine, 기관 사용 종료) 후에는 테스트 콕을 열고, 보조 송풍기를 멈추고, 에어 러닝을 하고, 터닝기어를 연결(engage)해 주기관을 돌립니다. 터닝기어를 분리(disengage)하는 것은 시동 준비 때 하는 일입니다.","x":["테스트 콕을 엽니다.","보조 송풍기를 멈춥니다.","에어 러닝을 합니다.","정답(아닌 것). F.W.E. 후에는 터닝기어를 연결합니다."],"t":"F.W.E. 후 = engage turning gear"},"2021-2-기관1-1":{"w":"1[PS] ≒ 0.736[kW]이므로 1[kW] ≒ 1 ÷ 0.736 ≒ 1.36[PS]입니다.","x":["틀립니다.","1[PS]의 [kW] 값입니다.","1[PS]의 [kgf·m/s] 값입니다.","정답. 1.36[PS]"],"t":"1PS = 0.736kW, 1kW = 1.36PS"},"2021-2-기관1-2":{"w":"메인 베어링은 과부하, 윤활유 부족, 크랭크축 중심선 어긋남, 베어링 틈새 부적당 등으로 발열합니다. 점도지수가 큰 윤활유는 온도가 변해도 점도 변화가 작은 좋은 윤활유입니다.","x":["과부하는 발열 원인입니다.","중심선 어긋남은 편하중으로 발열 원인입니다.","윤활유 부족은 발열 원인입니다.","정답(아닌 것). 점도지수가 큰 윤활유는 좋은 윤활유입니다."],"t":"점도지수 큼 = 온도에 따른 점도 변화 작음(좋음)"},"2021-2-기관1-5":{"w":"플라이휠의 바깥 둘레를 림(rim)이라 하며, 여기에 각 실린더의 상사점·하사점, 분사시기 등이 표시되어 있어 기관 조정 때 씁니다.","x":["정답. 림 = 외주, 눈금 표시","암은 림과 보스를 잇는 부분입니다.","보스는 축에 끼워지는 중심부입니다.","원판은 해당하지 않습니다."],"t":"플라이휠 = 림(바깥) + 암 + 보스(중심)"},"2021-2-기관1-7":{"w":"배기가 검은색이 되는 원인은 불완전 연소, 과부하, 연소 공기량 부족(소기 압력 저하) 등입니다. 소기 압력이 높으면 공기가 충분해 오히려 연소가 좋아집니다.","x":["정답(옳지 않은 것). 소기 압력이 높으면 연소가 좋습니다.","원인입니다.","원인입니다.","원인입니다."],"t":"흑색 배기 = 공기 부족·과부하"},"2021-2-기관1-8":{"w":"배압(배기 저항)이 높아지는 원인은 배기 계통의 카본 퇴적, 배기온도 상승(가스 팽창), 후연소 등입니다. 실린더 윤활 불량은 배압과 직접 관계가 없습니다.","x":["카본이 쌓이면 통로가 좁아집니다.","온도가 높으면 가스 부피가 커집니다.","후연소는 배기온도를 높입니다.","정답(옳지 않은 것). 실린더 윤활은 배압과 관계없습니다."],"t":"배압 상승 = 카본·고온 배기"},"2021-2-기관1-9":{"w":"배기밸브는 더 뜨거워 많이 늘어나므로 태핏 간극을 흡기밸브와 같거나 더 크게 합니다. 간극은 그 실린더가 압축행정 상사점(밸브가 완전히 닫힌 상태)에 있을 때 조정합니다.","x":["정답. ①, ② 모두 옳다","②도 옳습니다.","둘 다 옳습니다.","①도 옳습니다."],"t":"태핏 간극 = 압축 TDC에서, 배기 ≥ 흡기"},"2021-2-기관1-10":{"w":"보슈형 펌프는 래크로 플런저를 회전시켜 경사홈의 위치를 바꿔 유효행정(토출량)을 조절합니다.","x":["토출밸브를 돌리지 않습니다.","정답. 플런저를 회전","스필밸브는 다른 형식입니다.","흡입밸브로 조절하지 않습니다."],"t":"보슈형 = 플런저 회전"},"2021-2-기관1-13":{"w":"캐리오버는 발생 증기와 함께 보일러 물(물방울, 불순물)이 밖으로 딸려 나가는 현상입니다. 포밍, 프라이밍이 원인입니다.","x":["정상적인 증기 공급입니다.","정답. 보일러수가 증기와 함께 반출","응축 현상입니다.","수면계 착오입니다."],"t":"캐리오버 = 증기에 물이 섞여 나감"},"2021-2-기관1-14":{"w":"같은 압력에서 포화증기를 더 가열해 포화온도보다 높아진 증기가 과열증기입니다. 따라서 온도가 가장 높습니다.","x":["정답. 과열증기가 가장 높습니다.","습포화증기는 포화온도입니다.","건포화증기도 포화온도입니다.","포화증기는 포화온도입니다."],"t":"과열증기 > 포화증기(습·건 모두 포화온도)"},"2021-2-기관1-17":{"w":"기관 회전 방향은 그대로 두고 날개 각도를 바꿔 전진·후진하는 추진기는 가변 피치 프로펠러(CPP)입니다.","x":["분사추진기(워터제트)가 아닙니다.","외차추진기가 아닙니다.","고정 피치는 날개 각도가 고정됩니다.","정답. 가변 피치 프로펠러"],"t":"CPP = 날개 각도로 전후진"},"2021-2-기관1-19":{"w":"프로펠러 날개가 손상되면 진동이 생기고 추진력과 추진효율이 떨어집니다. 반류 증가는 날개 손상의 영향이 아닙니다.","x":["진동이 생깁니다.","추진력이 줄어듭니다.","정답(옳지 않은 것). 반류와 관계없습니다.","추진효율이 떨어집니다."],"t":"날개 손상 = 진동·추진력↓"},"2021-2-기관1-20":{"w":"추진 출력은 유효마력과 추진효율, 애드미럴티 계수, 수조 모형 시험 등으로 구합니다. CFR 기관은 연료의 세탄가·옥탄가를 시험하는 표준 기관입니다.","x":["맞는 방법입니다.","맞는 방법입니다.","맞는 방법입니다.","정답(옳지 않은 것). CFR 기관은 연료 시험용입니다."],"t":"CFR 기관 = 연료 착화성 시험"},"2021-2-기관1-21":{"w":"연료유의 주성분은 탄소(C)와 수소(H)입니다(탄화수소).","x":["질소는 주성분이 아닙니다.","정답. C와 H","산소는 주성분이 아닙니다.","질소는 주성분이 아닙니다."],"t":"연료유 = 탄화수소(C, H)"},"2021-2-기관1-23":{"w":"윤활유는 윤활(감마), 냉각, 기밀, 청정, 방청 작용을 합니다. 분리 작용은 윤활유의 작용이 아닙니다.","x":["윤활·기밀 작용은 맞습니다.","냉각·청정 작용은 맞습니다.","정답(아닌 것). 분리 작용은 없습니다.","기밀·냉각 작용은 맞습니다."],"t":"윤활유 = 윤활·냉각·기밀·청정·방청"},"2021-2-기관1-25":{"w":"윤활유는 항유화성이 크고, 유성이 좋고, 점도가 적당하며, 응고점이 낮아야 합니다.","x":["맞습니다.","정답(옳지 않은 것). 응고점은 낮아야 합니다.","맞습니다.","맞습니다."],"t":"윤활유 = 응고점 낮게"},"2021-2-기관2-2":{"w":"왕복펌프는 흡입 성능이 좋고, 운전 조건이 변해도 효율 변화가 적지만, 송출이 불균일합니다. 소용량 고압용이며 대용량 저압용은 원심·축류펌프입니다.","x":["특징입니다.","정답(아닌 것). 왕복펌프는 소용량 고압용입니다.","특징입니다.","특징입니다."],"t":"왕복펌프 = 소용량·고압"},"2021-2-기관2-4":{"w":"사이드 스러스터는 배가 거의 멈춰 있을 때(선속 0) 옆으로 미는 힘이 가장 큽니다. 속력이 나면 효과가 급격히 줄어듭니다.","x":["전속에서는 효과가 거의 없습니다.","틀립니다.","정답. 선속 0일 때","틀립니다."],"t":"사이드 스러스터 = 저속·정지 시 효과"},"2021-2-기관2-5":{"w":"헬리컬 기어는 축방향 추력이 생기므로, 방향이 반대인 헬리컬을 합친 이중 헬리컬(헤링본) 기어를 써서 추력을 상쇄합니다.","x":["축마력 증가가 목적이 아닙니다.","송출 방향과 관계없습니다.","송출량 증가가 주목적이 아닙니다.","정답. 축방향 추력 상쇄"],"t":"이중 헬리컬 = 추력 상쇄"},"2021-2-기관2-6":{"w":"유압 양묘장치는 유압펌프에서 보낸 기름으로 유압모터를 돌려 체인 드럼축을 직접 구동합니다.","x":["정답. 유압모터","웜기어는 전동식에 씁니다.","스퍼기어는 감속용입니다.","클러치는 동력을 연결·차단합니다."],"t":"유압 양묘기 = 유압모터 구동"},"2021-2-기관2-10":{"w":"산기기로 공기를 불어 넣어 호기성 박테리아가 오물을 분해하는 탱크는 폭기탱크입니다.","x":["멸균탱크는 소독합니다.","침전탱크는 슬러지를 가라앉힙니다.","정답. 폭기탱크","해당하지 않습니다."],"t":"폭기탱크 = 공기 + 박테리아"},"2021-2-기관2-11":{"w":"압축비가 너무 높으면 토출가스 온도가 올라가고, 냉동능력과 성적계수가 떨어지며, 윤활유가 빨리 열화됩니다.","x":["냉동능력이 감소합니다.","정답(옳지 않은 것). 토출가스 온도는 높아집니다.","성적계수가 떨어집니다.","윤활유 열화가 빨라집니다."],"t":"압축비↑ = 토출온도↑, 능력↓"},"2021-2-기관2-12":{"w":"암모니아는 증발잠열이 크지만, 수분이 있으면 구리합금을 부식시키고 독성·자극성 냄새가 있으며, 물에 잘 녹아 새면 식품을 상하게 할 수 있습니다.","x":["맞습니다.","맞습니다.","맞습니다.","정답(옳지 않은 것). 암모니아는 물에 잘 흡수됩니다."],"t":"암모니아 = 물에 잘 녹음, 동 부식"},"2021-2-기관2-13":{"w":"냉동장치는 증발기에서 냉매가 증발할 때 주위의 열(증발열, 잠열)을 흡수합니다.","x":["정답. 증발열","승화열이 아닙니다.","응고열이 아닙니다.","현열이 아닙니다."],"t":"냉동 = 증발잠열"},"2021-2-기관2-14":{"w":"공기조화장치는 온도, 습도, 기류(풍속), 청정도를 조절합니다. 압력 조절은 기능이 아닙니다.","x":["온도 조절은 기능입니다.","습도 조절은 기능입니다.","기류 조절은 기능입니다.","정답(아닌 것). 압력은 조절하지 않습니다."],"t":"공조 4요소 = 온도·습도·기류·청정도"},"2021-2-기관2-15":{"w":"건공기 1[kg]에 포함된 수증기 질량[kg]을 절대습도라 합니다.","x":["정답. 절대습도","상대습도는 수증기 분압의 비입니다.","비교습도는 포화 절대습도에 대한 비입니다.","포화도는 비교습도와 같습니다."],"t":"절대습도 = 수증기 kg / 건공기 kg"},"2021-2-기관2-16":{"w":"스크레이핑은 스크레이퍼로 평면이나 곡면(베어링 면 등)을 조금씩 긁어 정밀하게 다듬는 작업입니다.","x":["구멍 가공은 리밍·보링입니다.","연삭은 숫돌로 합니다.","정답. 평면·곡면의 정밀 다듬질","숫돌 다듬질은 연삭입니다."],"t":"스크레이핑 = 긁어서 정밀 다듬질"},"2021-2-기관2-17":{"w":"버니어 캘리퍼스, 마이크로미터, 다이얼 게이지는 측정 공구이고, 바이스는 일감을 고정하는 공구입니다.","x":["측정 공구입니다.","측정 공구입니다.","측정 공구입니다.","정답(아닌 것). 바이스는 고정 공구입니다."],"t":"바이스 = 고정"},"2021-2-기관2-18":{"w":"실린더 라이너는 회전하는 틀에 쇳물을 부어 원심력으로 치밀하게 만드는 원심 주조법으로 만듭니다. 크랭크축은 단조, 실린더 헤드는 주조로 만듭니다.","x":["실린더 헤드는 주조로 만듭니다.","정답. 실린더 라이너 = 원심 주조","배기밸브는 단조로 만듭니다.","크랭크축은 단조로 만듭니다."],"t":"라이너 = 원심 주조, 크랭크축 = 단조"},"2021-2-기관2-19":{"w":"핸드실드의 차광유리(필터 렌즈) 앞에 보호유리를 대는 것은 튀는 스패터로부터 비싼 필터 렌즈를 보호하기 위해서입니다.","x":["눈 보호는 차광유리의 역할입니다.","목적이 아닙니다.","정답. 필터 렌즈 보호","감전과 관계없습니다."],"t":"보호유리 = 필터 렌즈 보호"},"2021-2-기관2-20":{"w":"용접 이음은 리벳·볼트 이음보다 재료와 공수가 절약되고 이음 효율(강도)이 높습니다. 잔류 응력과 경화는 오히려 단점입니다.","x":["가장 큰 장점이 아닙니다.","잔류 응력은 단점입니다.","정답. 재료·공수 절감, 이음효율 높음","경화는 균열 원인이 되는 단점입니다."],"t":"용접 = 이음효율↑"},"2021-2-기관2-22":{"w":"용골은 배 밑바닥 중심선을 따라 선수재에서 선미재까지 이어진 가장 중요한 종강력재로, 사람의 척추에 해당합니다.","x":["늑골은 갈비뼈처럼 횡으로 선 부재입니다.","정답. 용골","빌지킬은 횡요(롤링)를 줄이는 부재입니다.","격벽은 선내를 나누는 벽입니다."],"t":"용골 = 배의 척추"},"2021-2-기관2-25":{"w":"기계의 설치 위치를 나타내는 도면은 배치도입니다.","x":["설치도가 아닙니다.","배선도는 전선 연결도입니다.","배관도는 관 연결도입니다.","정답. 배치도"],"t":"배치도 = 위치"},"2021-2-기관3-1":{"w":"같은 1,000[W]를 쓰려면 ①(1,000V)은 1[A], ②(100V)는 10[A]가 흐릅니다. 선로 손실 I²R은 ①이 1[W], ②가 100[W]로 ②가 더 큽니다.","x":["전류가 달라 전압강하도 다릅니다.","②의 전류가 더 큽니다.","정답. ②의 선로 손실이 더 큼","열량은 ②가 더 큽니다."],"t":"고전압 송전 = 손실↓"},"2021-2-기관3-2":{"w":"거주실 전원 220[V]는 실효값(실효치)입니다.","x":["최대치가 아닙니다.","순시치가 아닙니다.","정답. 실효치","평균치가 아닙니다."],"t":"전원 = 실효값"},"2021-2-기관3-3":{"w":"역기전력도 전압이므로 단위는 [V]입니다.","x":["정전용량 단위입니다.","정답. [V]","저항 단위입니다.","전력 단위입니다."],"t":"기전력 = V"},"2021-2-기관3-6":{"w":"역률 = 유효전력 ÷ 피상전력 = P ÷ (V × I) = 30 ÷ (100 × 0.6) = 30 ÷ 60 = 0.5입니다.","x":["틀린 값입니다.","틀린 값입니다.","전류값을 그대로 쓴 값입니다.","정답. 30 ÷ 60 = 0.5"],"t":"역률 cosθ = P / VI"},"2021-2-기관3-7":{"w":"XL = 2πfL = 2π × 60 × 0.005 = 0.6π[Ω]입니다.","x":["단위(mH)를 바꾸지 않은 값입니다.","틀린 값입니다.","틀린 값입니다.","정답. 2π × 60 × 0.005 = 0.6π"],"t":"XL = 2πfL (mH → H)"},"2021-2-기관3-8":{"w":"정전용량은 전극 간격이 좁을수록 커집니다.","x":["맞습니다.","맞습니다.","맞습니다.","정답(옳지 않은 것). 간격이 좁을수록 커집니다."],"t":"C ∝ 1/간격"},"2021-2-기관3-10":{"w":"XL = XC 이면 서로 상쇄되어 Z = R = 100[Ω]입니다(직렬 공진).","x":["0이 아닙니다.","정답. 100[Ω]","틀립니다.","모두 더한 값입니다."],"t":"공진 시 Z = R"},"2021-2-기관3-11":{"w":"전위차 V = 일 W ÷ 전하량 Q 입니다. 1[C]의 전하가 1[J]의 일을 하면 1[V]입니다.","x":["정답. V = W / Q","틀린 식입니다.","틀린 식입니다.","틀린 식입니다."],"t":"V = W / Q (W = QV)"},"2021-2-기관3-13":{"w":"전구가 콘덴서와 병렬로 연결되어 있어, 스위치를 닫는 순간 빈 콘덴서가 전류를 받아들여 전구 양단 전압이 0입니다. 콘덴서가 충전되며 전압이 올라가 전구가 서서히 밝아집니다.","x":["틀립니다.","정답. 꺼진 상태에서 서서히 밝아짐","전구가 콘덴서와 직렬일 때입니다.","결국 켜집니다."],"t":"C와 병렬 전구 = 서서히 밝아짐"},"2021-2-기관3-16":{"w":"전동기의 회전 방향(힘의 방향)은 플레밍의 왼손 법칙으로 알 수 있습니다. 발전기의 기전력 방향은 오른손 법칙입니다.","x":["정답. 플레밍의 왼손 법칙","전류가 만드는 자기장 세기 법칙입니다.","발전기에 씁니다.","전자유도 법칙입니다."],"t":"전동기 왼손, 발전기 오른손"},"2021-2-기관3-18":{"w":"철심을 얇게 성층하면 맴돌이 전류(와류) 손실을 줄일 수 있습니다.","x":["정답. 와류손 방지","히스테리시스손은 규소강으로 줄입니다.","마찰손과 관계없습니다.","표유부하손과 관계없습니다."],"t":"성층 = 와류손↓"},"2021-2-기관3-19":{"w":"전압 이득[dB] = 20 log(증폭률) = 20 × log100 = 20 × 2 = 40[dB]입니다.","x":["10배일 때입니다.","정답. 40[dB]","1,000배일 때입니다.","틀립니다."],"t":"dB = 20 log A"},"2021-2-직무일반-3":{"w":"수급 전에는 스커퍼 폐쇄, 신호기(B기)·등화 확인, 오염방제자재와 소화기 비치 등을 준비합니다. 기름기록부는 수급이 끝난 뒤에 작성합니다.","x":["정답(아닌 것). 기름기록부는 수급 후 작성합니다.","스커퍼 폐쇄는 수급 전 확인 사항입니다.","신호기·등화는 수급 전 확인 사항입니다.","방제자재·소화기 비치는 수급 전 준비 사항입니다."],"t":"기름기록부 = 작업 후 기록"},"2021-2-직무일반-4":{"w":"한국선급의 선급유지 검사는 정기, 중간, 연차, 입거, 보일러, 계속검사 등입니다. 임시항해검사는 선박안전법의 검사입니다.","x":["선급 검사입니다.","선급 검사입니다.","선급 검사입니다.","정답(아닌 것). 임시항해검사"],"t":"임시항해검사 = 선박안전법"},"2021-2-직무일반-5":{"w":"그림처럼 머리가 둥근 고리 모양인 볼트는 아이볼트로, 무거운 부품을 들어 올릴 때 씁니다.","x":["스터드볼트는 양쪽이 나사인 볼트입니다.","육각볼트는 머리가 육각입니다.","타이볼트는 긴 연결 볼트입니다.","정답. 아이볼트"],"t":"아이볼트 = 인양용 고리"},"2021-2-직무일반-6":{"w":"호기성 박테리아로 유기물을 분해하는 오수처리 방식은 미생물(생물학적) 분해식입니다.","x":["저장 분쇄식이 아닙니다.","정답. 미생물 분해식","염소 순환식은 화학식입니다.","틀립니다."],"t":"오수처리 = 호기성 미생물"},"2021-2-직무일반-8":{"w":"유출된 기름이 퍼지는 것을 막기 위해 선박 주위에 오일펜스를 둘러칩니다. 그 뒤 유회수기로 거두고 흡착재로 닦아 냅니다.","x":["유회수기는 기름을 거두어들이는 장비입니다.","흡착재는 기름을 빨아들이는 재료입니다.","정답. 확산 방지 = 오일펜스","유겔화제는 기름을 굳히는 약제입니다."],"t":"확산 방지 = 오일펜스"},"2021-2-직무일반-9":{"w":"수급 시 갑판 배수구(스커퍼)는 막아 두고, 방제 자재를 가까이 두고, 탱크를 자주 측심해 넘치지 않게 합니다. 맨홀을 열어 두면 안 됩니다.","x":["①은 틀립니다(배수구는 막아야 함).","①은 틀립니다(배수구는 막아야 함).","①은 틀립니다(배수구는 막아야 함).","①은 틀립니다(배수구는 막아야 함)."],"t":"수급 = 스커퍼 막기·방제자재·자주 측심"},"2021-2-직무일반-10":{"w":"기관구역 기름기록부의 슬러지는 청정기 슬러지, 자동 여과기 드레인, 세틀링 탱크 드레인 등 기름 찌꺼기입니다. 보일러 급수탱크 드레인은 물이므로 슬러지가 아닙니다.","x":["정답(아닌 것). 급수탱크 드레인은 물입니다.","슬러지입니다.","슬러지입니다.","슬러지입니다."],"t":"슬러지 = 기름 찌꺼기"},"2021-2-직무일반-14":{"w":"침몰 우려가 있으면 가장 먼저 선내 침수 상황을 전 승무원에게 알려 모두 대비하게 해야 합니다.","x":["귀중품 정리는 우선 조치가 아닙니다.","조난통신은 선교(선장)가 합니다.","정답. 전 승무원에게 알린다","그다음 조치입니다."],"t":"비상 시 1순위 = 전원에게 알림"},"2021-2-직무일반-17":{"w":"조타장치는 최대 전진 속력에서 한쪽 35°부터 반대쪽 35°까지 돌릴 수 있어야 하고, 35°에서 반대쪽 30°까지 28초 이내에 돌려야 합니다.","x":["틀립니다.","틀립니다.","틀립니다.","정답. 35°, 28초"],"t":"35° → 반대 30° = 28초"},"2021-2-직무일반-20":{"w":"기관구역 고정식 CO₂ 소화설비는 2분 이내에 CO₂ 총량의 85[%] 이상을 방출해야 합니다.","x":["비율이 틀렸습니다.","정답. 2분 이내 85[%]","시간과 비율이 틀렸습니다.","시간이 틀렸습니다."],"t":"기관실 CO₂ = 2분 이내 85%"},"2021-2-직무일반-21":{"w":"소화전에는 소화 호스, 노즐, 스패너(연결용)를 비치합니다. 안전등은 비치하지 않습니다.","x":["비치합니다.","비치합니다.","비치합니다.","정답(아닌 것). 안전등"],"t":"소화전 = 호스·노즐·스패너"},"2021-2-직무일반-22":{"w":"선박안전법상 항해구역은 평수구역, 연해구역, 근해구역, 원양구역입니다. '연안구역'은 해당하지 않습니다.","x":["항해구역입니다.","정답(아닌 것). 연해구역이 맞습니다.","항해구역입니다.","항해구역입니다."],"t":"평수·연해·근해·원양"},"2021-2-직무일반-24":{"w":"선원법상 선원에게 임의의 24시간 동안 10시간 이상의 휴식시간을 주어야 합니다.","x":["틀립니다.","정답. 10시간","틀립니다.","틀립니다."],"t":"휴식 = 24시간 중 10시간 이상"},"2021-2-직무일반-25":{"w":"IMO 형식승인 소각기로는 PVC(폴리염화비닐)를 소각할 수 있습니다. PCB, 중금속 폐기물, 할로겐 화합물을 함유한 정제석유제품 등은 소각이 금지됩니다.","x":["정답. PVC는 승인 소각기에서 소각 가능","PCB는 소각 금지","중금속 폐기물은 소각 금지","할로겐 함유 석유제품은 소각 금지"],"t":"승인 소각기 = PVC 소각 가능"},"2021-2-영어-3":{"w":"프로펠러 피치(1회전에 이론상 나아가는 거리)와 배가 실제 나아간 거리의 차이를 슬립(slip)이라 합니다.","x":["rpm = 분당 회전수","sailing mile = 항해 거리","정답. slip = 슬립","engine mile = 기관 거리(프로펠러 기준 거리)"],"t":"피치 − 실제 전진 거리 = slip"},"2021-2-영어-4":{"w":"F.O.T. = Fuel Oil Tank(연료유 탱크)입니다.","x":["맞습니다.","맞습니다.","정답(옳지 않은 것). F.O.T. = Fuel Oil Tank","맞습니다."],"t":"FOT = 연료유 탱크"},"2021-2-영어-5":{"w":"\"주기관 시동 실패로 ( )을(를) 점검했다\" — 공기탱크 압력, 시동공기밸브, 시동공기 분배기는 점검 대상이지만 시동공기의 습도는 시동 실패 점검 항목이 아닙니다.","x":["정답(적절하지 않은 것). 습도","점검합니다.","점검합니다.","점검합니다."],"t":"시동 실패 = 공기압·시동밸브·분배기"},"2021-2-영어-6":{"w":"muster = 소집하다. \"구명정 훈련을 위해 전 선원을 갑판에 소집했다.\"","x":["정답. 소집하였다","검사하였다가 아닙니다.","해산하였다가 아닙니다.","훈련하였다가 아닙니다."],"t":"muster = 소집"},"2021-2-영어-7":{"w":"하루는 자정부터 4시간씩 6개의 당직 시간으로 나눕니다.","x":["정답. four","틀립니다.","틀립니다.","틀립니다."],"t":"당직 = 4시간씩"},"2021-2-영어-8":{"w":"\"기관부를 책임지는 사람은?\" 기관장(Chief engineer)입니다.","x":["정답. Chief engineer = 기관장","Chief officer = 1등 항해사","No.1 oiler = 조기장","Captain = 선장"],"t":"기관부 책임 = Chief engineer"},"2021-2-영어-9":{"w":"\"주기관 섬프 탱크의 양을 확인했다.\" amount = 양.","x":["정답. amount","인화점","점도","연소점"],"t":"ascertain amount = 양 확인"},"2021-2-영어-10":{"w":"inspect(검사하다) ≒ check(점검하다).","x":["Adjusted = 조정했다","Regulated = 조절했다","정답. Checked = 점검했다","Found = 발견했다"],"t":"inspected ≒ checked"},"2021-2-영어-12":{"w":"at once = 즉시 = instantly.","x":["때때로","자주","자주","정답. instantly"],"t":"at once = instantly"},"2021-2-영어-15":{"w":"조수장치에서 증기로 해수를 가열해 증발시키는 열교환기는 Evaporator(증발기)입니다.","x":["정답. Evaporator","진공 차단기","절탄기","응축기"],"t":"evaporator = 조수기 증발기"},"2021-2-영어-16":{"w":"배를 조종하는 장치는 rudder(타)입니다.","x":["윈치","조속기","정답. rudder","발전기"],"t":"rudder = 타"},"2021-2-영어-17":{"w":"화재의 3요소는 연료(fuel), 열(heat), 산소(oxygen)입니다. power는 관계없습니다.","x":["3요소입니다.","3요소입니다.","3요소입니다.","정답(관계없는 것). power"],"t":"fire triangle = fuel·heat·oxygen"},"2021-2-영어-20":{"w":"벌류트 펌프를 기동하기 위해 물을 붓는 것을 Priming(마중물 넣기)이라 합니다.","x":["Sounding = 측심","정답. Priming","Warming = 난기","Turning = 터닝"],"t":"priming = 마중물"},"2021-2-영어-21":{"w":"실린더 안에서 발생하는 동력은 도시마력(indicated horse power, IHP)입니다.","x":["brake horse power = 제동마력(출력축 동력)","정답. indicated horse power = 도시마력","shaft horse power = 축마력","friction horse power = 마찰마력"],"t":"IHP(실린더 안) − FHP = BHP"},"2021-2-영어-22":{"w":"F.W.E.(Finished With Engine, 기관 사용 종료) 후에는 테스트 콕을 열고, 보조 송풍기를 멈추고, 에어 러닝을 하고, 터닝기어를 연결(engage)해 주기관을 돌립니다. 터닝기어를 분리(disengage)하는 것은 시동 준비 때 하는 일입니다.","x":["테스트 콕을 엽니다.","보조 송풍기를 멈춥니다.","에어 러닝을 합니다.","정답(아닌 것). F.W.E. 후에는 터닝기어를 연결합니다."],"t":"F.W.E. 후 = engage turning gear"},"2021-2-영어-23":{"w":"발전기 병렬 운전(동기화)은 전압, 주파수, 위상을 맞추는 것입니다. 전류는 맞출 조건이 아닙니다.","x":["전압을 맞춥니다.","위상을 맞춥니다.","정답(적절하지 않은 것). 전류는 동기화 조건이 아닙니다.","주파수를 맞춥니다."],"t":"병렬운전 조건 = 전압·주파수·위상"},"2021-2-영어-24":{"w":"유조선 탱크를 대기와 완전히 격리해 보호하는 방법은 불활성 가스(inert gas)입니다.","x":["오일 미스트가 아닙니다.","원유가 아닙니다.","정답. inert gas","독성가스가 아닙니다."],"t":"IGS = 탱크 보호"},"2021-2-영어-25":{"w":"오일 미스트 검출기는 크랭크실 안 유증기의 농도(concentration)가 발화 전 위험 수준에 이르면 경보를 울리고 감속시킵니다.","x":["연소가 아닙니다.","정답. concentration = 농도","증발이 아닙니다.","응축이 아닙니다."],"t":"mist concentration = 유증기 농도"},"2021-3-기관1-1":{"w":"4행정 기관에서 배기행정 종말(상사점 부근)에는 가스 압력 없이 관성력이 크랭크축을 끌어올려 메인 베어링 캡에 최대 하중이 걸립니다.","x":["틀립니다.","정답. 배기행정 종말","틀립니다.","압축 종말에는 하중이 아래쪽에 걸립니다."],"t":"캡 최대 하중 = 배기 말"},"2021-3-기관1-4":{"w":"메인 베어링은 과부하, 윤활유 부족, 크랭크축 중심선 어긋남, 베어링 틈새 부적당 등으로 발열합니다. 점도지수가 큰 윤활유는 온도가 변해도 점도 변화가 작은 좋은 윤활유입니다.","x":["과부하는 발열 원인입니다.","중심선 어긋남은 편하중으로 발열 원인입니다.","윤활유 부족은 발열 원인입니다.","정답(아닌 것). 점도지수가 큰 윤활유는 좋은 윤활유입니다."],"t":"점도지수 큼 = 온도에 따른 점도 변화 작음(좋음)"},"2021-3-기관1-7":{"w":"피스톤 평균속도 = 2 × 행정 × 매분 회전수 ÷ 60 [m/s]입니다(1회전에 2행정).","x":["2를 곱하지 않았습니다.","정답. 2LN / 60","틀립니다.","틀립니다."],"t":"Vm = 2LN / 60"},"2021-3-기관1-9":{"w":"크랭크암 개폐량(디플렉션)으로 위험 개폐량 도달, 메인 베어링 마멸, 축 중심선 불일치를 판단합니다. 위험 회전수는 비틀림 진동 계산으로 정하는 것으로 개폐량으로는 알 수 없습니다.","x":["판단할 수 있습니다.","판단할 수 있습니다.","정답(판단할 수 없는 것). 위험 회전수","판단할 수 있습니다."],"t":"디플렉션 = 베어링 마멸·축심"},"2021-3-기관1-11":{"w":"그림의 ①은 캠의 움직임을 푸시로드로 받아 밸브스핀들을 눌러 여는 시소 모양의 로커암입니다.","x":["푸시로드는 캠과 로커암 사이의 막대입니다.","정답. ① = 로커암","밸브스핀들은 밸브의 축입니다.","롤러암은 캠에 닿는 부분입니다."],"t":"캠 → 푸시로드 → 로커암 → 밸브"},"2021-3-기관1-14":{"w":"복수장치(복수기)는 배기압력을 진공으로 낮춰 열효율을 높이고, 증기를 물로 되돌려 급수로 회수합니다.","x":["조속장치는 속도 조절용입니다.","정답. 복수장치","증발장치가 아닙니다.","팽창장치가 아닙니다."],"t":"복수기 = 진공 + 급수 회수"},"2021-3-기관1-16":{"w":"대형 선박에는 미첼형(세그먼트형) 추력 베어링을 주로 씁니다.","x":["말굽형은 옛 형식입니다.","상자형은 소형선용입니다.","정답. 미첼형","해당하지 않습니다."],"t":"추력 베어링 = 미첼형"},"2021-3-기관1-18":{"w":"추진 축계는 프로펠러축, 추력축, 중간축으로 이루어집니다. 캠축은 기관 내부 부품입니다.","x":["구성 요소입니다.","구성 요소입니다.","구성 요소입니다.","정답(아닌 것). 캠축"],"t":"캠축 = 기관 부품"},"2021-3-기관1-20":{"w":"출력 = 저항 × 속도 입니다. 저항은 속도의 제곱에 비례하므로 출력은 속도의 세제곱에 비례합니다.","x":["저항은 속도에 비례해 커집니다.","정답. 출력 = 저항 × 속도","속도는 회전수에 비례합니다.","출력은 회전수의 세제곱에 비례합니다."],"t":"P = R × V"},"2021-3-기관1-21":{"w":"경유의 비중은 약 0.84~0.89입니다. 휘발유는 약 0.69~0.77, 등유는 약 0.78~0.84, 중유는 약 0.91~0.99입니다.","x":["휘발유의 비중입니다.","등유의 비중입니다.","정답. 경유 약 0.84~0.89","중유의 비중입니다."],"t":"휘발유 < 등유 < 경유 < 중유"},"2021-3-기관1-22":{"w":"윤활유가 밖에서 오염되어 열화되는 원인은 냉각수, 연료유, 먼지 혼입 등입니다. 새 윤활유 보충은 열화 원인이 아닙니다.","x":["원인입니다.","원인입니다.","원인입니다.","정답(아닌 것). 새 윤활유 보충"],"t":"열화 = 외부 오염"},"2021-3-기관1-23":{"w":"윤활유는 점도지수가 크고, 응고점이 낮고, 항유화성이 크며, 탄화되기 어려워야 합니다.","x":["점도지수는 커야 합니다.","정답. 응고점이 낮아야 합니다.","항유화성은 커야 합니다.","탄화가 어려워야 합니다."],"t":"윤활유 = 점도지수↑, 응고점↓, 항유화성↑"},"2021-3-기관2-1":{"w":"원심펌프는 회전차(임펠러)의 원심력으로 물을 보냅니다.","x":["정답. 원심력","양력은 축류펌프의 원리입니다.","축류펌프입니다.","마찰력이 아닙니다."],"t":"원심펌프 = 원심력"},"2021-3-기관2-2":{"w":"왕복펌프는 송출량은 적지만 높은 압력을 낼 수 있어, 적은 양을 높은 압력으로 보낼 때 씁니다.","x":["많은 양은 원심펌프가 적합합니다.","정답. 소유량 고압","대유량 저압은 축류펌프입니다.","적합하지 않습니다."],"t":"왕복펌프 = 소유량·고압"},"2021-3-기관2-5":{"w":"양묘기(윈드라스)는 닻과 닻줄을 감아올리는 장치로 체인 드럼(워핑드럼·체인 휠), 마찰 브레이크, 클러치, 조종 핸들 등으로 이루어집니다. 슬루잉 윈치는 크레인·데릭의 붐을 좌우로 돌리는 윈치입니다.","x":["조종 핸들은 양묘기의 구성품입니다.","체인 드럼은 양묘기의 구성품입니다.","정답(아닌 것). 슬루잉 윈치는 하역장치에 속합니다.","마찰 브레이크는 양묘기의 구성품입니다."],"t":"슬루잉 = 붐 좌우 회전(하역장치)"},"2021-3-기관2-7":{"w":"유량제어밸브는 흐르는 기름의 양(속도)을 조절하는 밸브로, 교축밸브(스로틀밸브)가 대표적입니다. 감압·릴리프·시퀀스밸브는 압력제어밸브입니다.","x":["감압밸브는 압력제어밸브입니다.","정답. 교축밸브 = 유량제어밸브","릴리프밸브는 압력제어밸브입니다.","시퀀스밸브는 압력제어밸브입니다."],"t":"유량제어 = 교축밸브 / 압력제어 = 릴리프·감압·시퀀스"},"2021-3-기관2-8":{"w":"기름여과장치는 유면검출기가 기름층을 감지하면 배유 전자밸브를 열고, 일정 시간이 지나면 타이머 신호로 밸브를 닫습니다.","x":["콜레서는 기름을 뭉치게 하는 필터입니다.","포집관은 기름을 모으는 관입니다.","정답. 타이머 신호로 닫힘","전동기는 펌프를 돌립니다."],"t":"배유밸브 = 유면검출기로 열림, 타이머로 닫힘"},"2021-3-기관2-9":{"w":"유면검출기는 분리기 위쪽에 모인 기름층의 두께를 감지해 기름을 배출시킵니다. 감도를 높이면 기름층이 조금만 쌓여도 감지하므로 기름층의 하한 레벨이 높아집니다(얇은 기름층에서도 동작).","x":["상한 레벨이 낮아진다는 설명은 맞지 않습니다.","정답. 감도를 높이면 기름층의 하한 레벨이 높아집니다.","물층의 상한 레벨과는 관계없는 설명입니다.","물층의 하한 레벨과는 관계없는 설명입니다."],"t":"유면검출기 감도↑ → 기름층 하한 레벨↑"},"2021-3-기관2-10":{"w":"기름의 부상속도는 기름 입자가 클수록, 물과 기름의 밀도 차가 클수록 빨라집니다. 밀도 차를 작게 하면 느려집니다.","x":["경계면을 크게 하면 좋습니다.","응집제는 입자를 키웁니다.","부피가 크면 빨라집니다.","정답(옳지 않은 것). 밀도 차는 커야 합니다."],"t":"부상속도 ∝ 밀도차 × 지름²"},"2021-3-기관2-11":{"w":"냉동장치는 증발기에서 냉매가 증발할 때 주위의 열(증발열, 잠열)을 흡수합니다.","x":["정답. 증발열","승화열이 아닙니다.","응고열이 아닙니다.","현열이 아닙니다."],"t":"냉동 = 증발잠열"},"2021-3-기관2-12":{"w":"물질이 가진 전체 에너지(내부 에너지 + 압력×부피)를 엔탈피라 합니다.","x":["정답. 엔탈피","엔트로피는 무질서도입니다.","성적계수는 냉동기 효율입니다.","비엔트로피는 단위 질량당 엔트로피입니다."],"t":"엔탈피 = 전체 열에너지"},"2021-3-기관2-13":{"w":"증발관에 서리가 끼면 전열이 나빠지므로 제상장치로 서리를 제거해 전열작용을 좋게 합니다.","x":["부하경감장치는 기동 부하를 줄입니다.","배기장치가 아닙니다.","정답. 제상장치","건조장치는 수분을 제거합니다."],"t":"제상 = 전열 회복"},"2021-3-기관2-14":{"w":"공기조화 방식에는 유인 유닛 방식, 팬코일 유닛 방식, 단일·2중 덕트 방식 등이 있습니다. 랩슨 슬라이드는 조타장치의 형식입니다.","x":["유인 유닛은 공조 방식입니다.","팬코일 유닛은 공조 방식입니다.","2중 덕트는 공조 방식입니다.","정답(아닌 것). 랩슨 슬라이드는 조타장치입니다."],"t":"랩슨 슬라이드 = 조타장치"},"2021-3-기관2-15":{"w":"공기조화는 온도, 습도, 기류(유속), 청정도를 조절합니다. 압력은 조절하지 않습니다.","x":["기능입니다.","기능입니다.","기능입니다.","정답(아닌 것). 압력"],"t":"공조 = 온도·습도·기류·청정도"},"2021-3-기관2-16":{"w":"높이를 재는 게이지는 하이트 게이지입니다.","x":["다이얼 게이지는 변위를 잽니다.","정답. 하이트 게이지","블록 게이지는 기준 치수 블록입니다.","스트레인 게이지는 변형률을 잽니다."],"t":"하이트 = 높이"},"2021-3-기관3-1":{"w":"단권변압기(기동보상기)로 전동기에 낮은 전압을 걸어 기동하면 큰 기동 전류를 줄일 수 있습니다. 가속된 뒤 전전압으로 바꿉니다.","x":["기동 토크는 오히려 줄어듭니다.","전압을 낮추기 위해 씁니다.","정답. 기동 전류 감소","속도 감소가 목적이 아닙니다."],"t":"기동보상기 = 감전압 기동 → 기동전류↓"},"2021-3-기관3-2":{"w":"키르히호프의 제1법칙(전류 법칙)은 한 점으로 들어오고 나가는 전류의 대수합이 0이라는 법칙입니다.","x":["앙페르의 법칙은 전류와 자기장의 방향입니다.","쿨롱의 법칙은 전하 사이의 힘입니다.","정답. 키르히호프의 법칙","패러데이의 법칙은 전자유도입니다."],"t":"키르히호프 1법칙 = 전류, 2법칙 = 전압"},"2021-3-기관3-3":{"w":"XL = 2πfL = 2π × 60 × 0.005 = 0.6π[Ω]입니다.","x":["단위(mH)를 바꾸지 않은 값입니다.","틀린 값입니다.","틀린 값입니다.","정답. 2π × 60 × 0.005 = 0.6π"],"t":"XL = 2πfL (mH → H)"},"2021-3-기관3-5":{"w":"전류 I = Q ÷ t = 10 ÷ 2 = 5[A]입니다.","x":["틀린 값입니다.","정답. 10 ÷ 2 = 5[A]","틀린 값입니다.","곱한 값입니다."],"t":"I = Q / t"},"2021-3-기관3-6":{"w":"정전용량은 전극 간격이 좁을수록 커집니다.","x":["맞습니다.","맞습니다.","맞습니다.","정답(옳지 않은 것). 간격이 좁을수록 커집니다."],"t":"C ∝ 1/간격"},"2021-3-기관3-11":{"w":"P = V × I × 역률 = 100 × 1 × 0.8 = 80[W]입니다.","x":["틀립니다.","정답. 80[W]","피상전력입니다.","틀립니다."],"t":"P = VI cosθ"},"2021-3-기관3-13":{"w":"농형 회전자는 회전자 철심, 도체 막대, 단락환, 통풍 날개로 이루어집니다. 슬립링은 권선형 회전자에 있습니다.","x":["정답(아닌 것). 슬립링은 권선형","구성 요소입니다.","구성 요소입니다.","구성 요소입니다."],"t":"농형 = 슬립링 없음"},"2021-3-기관3-14":{"w":"철심을 얇은 철판으로 성층하면 맴돌이 전류 손실이 줄어듭니다.","x":["히스테리시스 손실은 규소강으로 줄입니다.","정답. 맴돌이 전류 손실 감소","주목적이 아닙니다.","주목적이 아닙니다."],"t":"성층 = 와류손↓"},"2021-3-기관3-16":{"w":"병렬 운전 중 두 발전기의 기전력 크기가 다르면 두 발전기 사이에 무효 순환전류가 흘러 권선이 과열됩니다.","x":["정답. 무효 순환전류","위상 차이 때의 현상입니다.","유효전력은 거버너가 정합니다.","위상과 관계없습니다."],"t":"전압 차 = 무효 순환전류"},"2021-3-기관3-18":{"w":"싱크로스코프(동기검정기)는 병렬운전 시 투입할 발전기가 빠른지(FAST) 느린지(SLOW) 보여 줍니다.","x":["ACB는 차단기입니다.","정답. 싱크로스코프","주파수계는 FAST/SLOW 표시가 없습니다.","거버너 스위치는 RAISE/LOWER입니다."],"t":"FAST/SLOW = 싱크로스코프"},"2021-3-기관3-20":{"w":"두 다이오드가 A, B에서 X 쪽으로 향하고 X가 저항으로 접지된 다이오드 OR 회로입니다. A나 B 중 하나라도 1이면 X가 1이 되므로 ②, ③, ④입니다.","x":["둘 다 0이면 X는 0입니다.","둘 다 0이면 X는 0입니다.","둘 다 0이면 X는 0입니다.","둘 다 0이면 X는 0입니다."],"t":"다이오드 → 출력, 저항 접지 = OR"},"2021-3-기관3-21":{"w":"전압 이득[dB] = 20 log(증폭률) = 20 × log100 = 20 × 2 = 40[dB]입니다.","x":["10배일 때입니다.","정답. 40[dB]","1,000배일 때입니다.","틀립니다."],"t":"dB = 20 log A"},"2021-3-기관3-22":{"w":"맥동 직류를 평탄하게 만드는 회로는 콘덴서를 쓴 평활회로(R-C 평활회로 등)입니다.","x":["정류회로입니다.","저항만으로는 평활이 안 됩니다.","정류회로입니다.","정답. R-C 평활회로"],"t":"평활 = C 사용"},"2021-3-기관3-24":{"w":"역방향 항복 현상으로 전압을 일정하게 유지하는 소자는 제너 다이오드입니다.","x":["틀립니다.","정답. 제너 다이오드","가변용량은 전압에 따라 용량이 변합니다.","터널은 부성저항을 씁니다."],"t":"제너 = 정전압"},"2021-3-기관3-25":{"w":"교류 전력 제어용 양방향 3단자 스위칭 소자는 TRIAC입니다.","x":["FET가 아닙니다.","정답. TRIAC","UJT가 아닙니다.","SSS는 2단자 소자입니다."],"t":"TRIAC = 양방향 3단자"},"2021-3-직무일반-1":{"w":"황천 때는 출입문을 잠그고, 이동물을 고정하며, 부하 변동에 주의합니다. 과급공기 압력을 임의로 낮추면 연소가 나빠지므로 옳지 않습니다.","x":["맞습니다.","맞습니다.","정답(옳지 않은 것). 과급압력을 낮추지 않습니다.","맞습니다."],"t":"황천 = 고정·밀폐·부하 주의"},"2021-3-직무일반-2":{"w":"밀폐 공간의 산소 결핍은 철판이 녹슬면서 산소를 소비하는 것(부식)과 통풍 불량이 주된 원인입니다.","x":["습도는 주된 원인이 아닙니다.","습도는 주된 원인이 아닙니다.","습도는 주된 원인이 아닙니다.","습도는 주된 원인이 아닙니다."],"t":"산소 결핍 = 부식 + 통풍 불량"},"2021-3-직무일반-3":{"w":"수급 전에는 스커퍼 폐쇄, 신호기(B기)·등화 확인, 오염방제자재와 소화기 비치 등을 준비합니다. 기름기록부는 수급이 끝난 뒤에 작성합니다.","x":["정답(아닌 것). 기름기록부는 수급 후 작성합니다.","스커퍼 폐쇄는 수급 전 확인 사항입니다.","신호기·등화는 수급 전 확인 사항입니다.","방제자재·소화기 비치는 수급 전 준비 사항입니다."],"t":"기름기록부 = 작업 후 기록"},"2021-3-직무일반-4":{"w":"한국선급의 선급유지 검사는 정기, 중간, 연차, 입거, 보일러, 계속검사 등입니다. 임시항해검사는 선박안전법의 검사입니다.","x":["선급 검사입니다.","선급 검사입니다.","선급 검사입니다.","정답(아닌 것). 임시항해검사"],"t":"임시항해검사 = 선박안전법"},"2021-3-직무일반-5":{"w":"부식으로 얇아진 외판 두께는 한쪽 면에서 초음파를 보내 반사 시간으로 두께를 재는 초음파 두께 측정법으로 잽니다.","x":["정답. 두께 측정 = 초음파","자기탐상은 표면 균열 검사용입니다.","다이체크는 표면 균열 검사용입니다.","침투탐상은 표면 균열 검사용입니다."],"t":"두께 측정 = 초음파"},"2021-3-직무일반-7":{"w":"기름이 배출되면 즉시 신고하고, 확산을 막고, 흡착재 등으로 제거해야 합니다. 양을 확인할 때까지 기다리며 현장 보전만 하면 오염이 퍼집니다.","x":["즉시 제거합니다.","확산을 막습니다.","정답(옳지 않은 것). 즉시 방제해야 합니다.","신속히 신고합니다."],"t":"유출 = 신고·확산 방지·제거"},"2021-3-직무일반-9":{"w":"기관구역 기름기록부의 슬러지는 청정기 슬러지, 자동 여과기 드레인, 세틀링 탱크 드레인 등 기름 찌꺼기입니다. 보일러 급수탱크 드레인은 물이므로 슬러지가 아닙니다.","x":["정답(아닌 것). 급수탱크 드레인은 물입니다.","슬러지입니다.","슬러지입니다.","슬러지입니다."],"t":"슬러지 = 기름 찌꺼기"},"2021-3-직무일반-10":{"w":"연료가 연소하면 질소산화물(NOx), 황산화물(SOx) 등이 생깁니다. 염화불화탄소(CFC)는 냉매 등에서 나옵니다.","x":["냉매에서 나옵니다.","정답. 질소산화물","냉매 등에서 나옵니다.","오염물질이 아닙니다."],"t":"연소 = NOx·SOx"},"2021-3-직무일반-11":{"w":"혈액에서 산소를 운반하는 것은 적혈구(헤모글로빈)입니다.","x":["백혈구는 면역을 담당합니다.","정답. 적혈구","혈소판은 혈액 응고를 담당합니다.","감마 글로불린은 항체입니다."],"t":"적혈구 = 산소 운반"},"2021-3-직무일반-12":{"w":"검역 감염병에는 콜레라, 페스트, 황열 등이 있습니다. 장티푸스는 검역 감염병이 아닙니다.","x":["검역 감염병입니다.","정답(아닌 것). 장티푸스","검역 감염병입니다.","검역 감염병입니다."],"t":"검역 = 콜레라·페스트·황열"},"2021-3-직무일반-13":{"w":"응급처치는 생명을 구하고, 악화를 막고, 고통을 줄이는 것이 목적입니다. 의약품으로 치료 기간을 줄이는 것은 치료의 목적입니다.","x":["목적입니다.","목적입니다.","목적입니다.","정답(아닌 것). 치료가 목적이 아닙니다."],"t":"응급처치 = 생명 구조·악화 방지"},"2021-3-직무일반-15":{"w":"정전 후 예비발전기가 투입되면 Sequential start program(순차 기동 프로그램)이 주요 전동기를 차례로 자동 기동합니다.","x":["정답. 순차 기동","역전력 보호입니다.","우선 차단입니다.","수동 기동입니다."],"t":"sequential start = 순차 자동 기동"},"2021-3-직무일반-19":{"w":"물은 증발열이 커서 냉각 효과가 가장 뛰어난 소화제입니다.","x":["정답. 물","포말은 질식 효과가 큽니다.","분말은 억제 효과가 큽니다.","드라이파우더는 금속 화재용입니다."],"t":"냉각 = 물"},"2021-3-직무일반-22":{"w":"임시검사는 용도 변경, 길이 변경 등 개조, 무선설비 신설 때 받습니다. 검사증서 유효기간이 끝나면 정기검사를 받습니다.","x":["임시검사 대상입니다.","정답(아닌 것). 정기검사 대상입니다.","임시검사 대상입니다.","임시검사 대상입니다."],"t":"유효기간 만료 = 정기검사"},"2021-3-영어-1":{"w":"\"주 섬프 탱크 바닥의 기름을 퍼내고 내부를 청소했다.\" bail = 퍼내다.","x":["검사했다","교환했다","공급했다","정답. Bailed"],"t":"bail out = 퍼내다"},"2021-3-영어-3":{"w":"병렬 운전에서 분리하다 = release from parallel running. \"Released No.2 generator in parallel running and stopped No.2 G/E.\"","x":["engage는 연결입니다.","engage는 연결입니다.","정답. Released, parallel running","병렬이 빠졌습니다."],"t":"release = 분리"},"2021-3-영어-5":{"w":"\"주기관 시동 실패로 ( )을(를) 점검했다\" — 공기탱크 압력, 시동공기밸브, 시동공기 분배기는 점검 대상이지만 시동공기의 습도는 시동 실패 점검 항목이 아닙니다.","x":["정답(적절하지 않은 것). 습도","점검합니다.","점검합니다.","점검합니다."],"t":"시동 실패 = 공기압·시동밸브·분배기"},"2021-3-영어-7":{"w":"EEDI = Energy Efficiency Design Index = 에너지효율설계지수입니다.","x":["정답. 에너지효율설계지수","운항지수는 EEOI입니다.","틀립니다.","틀립니다."],"t":"EEDI = 설계지수"},"2021-3-영어-9":{"w":"축방향 간극(axial clearance)을 조정하는 것은 추력 베어링(thrust bearing)입니다.","x":["볼 베어링이 아닙니다.","중간 베어링이 아닙니다.","롤러 베어링이 아닙니다.","정답. thrust bearing"],"t":"axial clearance = 추력 베어링"},"2021-3-영어-10":{"w":"\"검사관의 내부 검사를 위해 연료유 탱크를 가스 프리(gasfreed)하고 청소할 것.\"","x":["filled = 채운","changed = 바꾼","정답. gasfreed = 가스 제거","supplied = 공급한"],"t":"gas free = 가스 제거"},"2021-3-영어-12":{"w":"\"분사 압력(injection pressure)을 30[MPa]로 조정했다.\"","x":["온도","정답. pressure","유량","점도"],"t":"injection pressure = 분사 압력"},"2021-3-영어-13":{"w":"기관 회전수는 tachometer(회전계)로 잽니다.","x":["온도계","압력계","정답. tachometer","동력계"],"t":"tachometer = 회전계"},"2021-3-영어-14":{"w":"hydrostatic test = 수압 시험 = water pressure test 입니다.","x":["정답. water pressure test = 수압 시험","humidity test = 습도 시험","tension test = 인장 시험","deformation test = 변형 시험"],"t":"hydrostatic test = 수압 시험"},"2021-3-영어-15":{"w":"\"2번 실린더 커버를 열고(opened) 피스톤을 꺼냈다(took out).\"","x":["정답. Opened, took out","조립하고 꺼낼 수 없습니다.","피스톤을 닫을 수 없습니다.","틀립니다."],"t":"take out = 꺼내다"},"2021-3-영어-17":{"w":"선박의 열교환기는 대부분 뜨거운 액체를 해수와 청수로 식히는 냉각기입니다.","x":["틀립니다.","틀립니다.","정답. sea water and fresh water","틀립니다."],"t":"cooler = 해수·청수"},"2021-3-영어-19":{"w":"IHP = Indicated Horse Power = 지시마력(도시마력)입니다. 기계효율 = BHP ÷ IHP.","x":["제동마력은 BHP입니다.","전달마력은 DHP입니다.","유효마력은 EHP입니다.","정답. IHP = 지시(도시)마력"],"t":"기계효율 = BHP / IHP"},"2021-3-영어-22":{"w":"절연체(insulator)는 전류 흐름에 높은 저항을 주는 물질입니다.","x":["정답. 높은 저항","도체입니다.","틀립니다.","틀립니다."],"t":"insulator = 높은 저항"},"2021-3-영어-23":{"w":"압력이 너무 높을 때 증기를 방출해 폭발을 막는 것은 safety valve(안전밸브)입니다.","x":["drain valve = 드레인 밸브","정답. safety valve","by pass valve = 바이패스 밸브","non return valve = 역지밸브"],"t":"safety valve = 과압 방출"},"2021-3-영어-24":{"w":"갑판기계의 주 구동 방식으로 가장 흔한 것은 유압(hydraulic)입니다.","x":["steam = 증기(옛 방식)","pneumatic = 공기압","정답. hydraulic = 유압","electronic = 전자식"],"t":"갑판기계 = hydraulic"},"2021-3-영어-25":{"w":"용액의 염분을 재는 기구는 Salinometer(염분계)입니다.","x":["회전계","습도계","점도계","정답. Salinometer"],"t":"salinometer = 염분계"},"2021-4-기관1-1":{"w":"소기효율은 소기가 끝난 뒤 실린더 안에 남은 새 공기(급기)의 무게를 실린더 안 전체 가스 무게로 나눈 값입니다. 잔류 배기가스가 적을수록 높습니다.","x":["정답. 소기효율","급기효율은 공급 공기량 기준입니다.","충전효율은 표준 상태 공기량 기준입니다.","용적효율은 흡입 부피의 비율입니다."],"t":"소기효율 = 새 공기 / 전체 가스"},"2021-4-기관1-4":{"w":"피스톤링 플러터는 링이 링 홈 안에서 떨리는 현상으로, 피스톤 속도가 빠를 때(고속 회전) 관성력 때문에 잘 생깁니다. 링이 가볍고 장력이 크면 줄어듭니다.","x":["속도가 느리면 잘 생기지 않습니다.","가벼우면 줄어듭니다.","정답. 피스톤 속도가 빠를 때","장력이 크면 줄어듭니다."],"t":"플러터 = 고속에서 발생"},"2021-4-기관1-6":{"w":"트렁크형 기관의 피스톤핀은 피스톤이 받은 힘을 커넥팅로드에 전달합니다.","x":["크로스헤드형 기관의 설명입니다.","측압은 피스톤 스커트가 받습니다.","정답. 힘을 커넥팅로드에 전달","회전운동으로 바꾸는 것은 크랭크축입니다."],"t":"피스톤핀 = 힘 전달"},"2021-4-기관1-8":{"w":"디젤 연소 과정 중 후연소 기간이 일반적으로 가장 깁니다.","x":["착화지연은 짧습니다.","무제어연소는 짧습니다.","정답. 후연소 기간","제어연소보다 후연소가 깁니다."],"t":"가장 긴 기간 = 후연소"},"2021-4-기관1-10":{"w":"과급된 공기는 압축되며 온도가 올라가 밀도가 낮아집니다. 공기 냉각기로 식히면 밀도가 높아져 더 많은 공기를 실린더에 넣을 수 있습니다.","x":["주목적이 아닙니다.","주목적이 아닙니다.","정답. 공기 밀도를 높이기 위해","오히려 착화지연은 길어질 수 있습니다."],"t":"공기 냉각기 = 밀도 증가"},"2021-4-기관1-11":{"w":"그림의 ①은 캠의 움직임을 푸시로드로 받아 밸브스핀들을 눌러 여는 시소 모양의 로커암입니다.","x":["푸시로드는 캠과 로커암 사이의 막대입니다.","정답. ① = 로커암","밸브스핀들은 밸브의 축입니다.","롤러암은 캠에 닿는 부분입니다."],"t":"캠 → 푸시로드 → 로커암 → 밸브"},"2021-4-기관1-12":{"w":"안전밸브의 방출능력은 증기 정지밸브를 닫고 최대 연소 상태로 운전해 압력이 일정 한도 이상 오르지 않는지 확인하는 축기시험으로 확인합니다.","x":["정답. 축기시험","압력시험이 아닙니다.","진공시험이 아닙니다.","수압시험은 강도·누설 시험입니다."],"t":"안전밸브 방출능력 = 축기시험"},"2021-4-기관1-14":{"w":"같은 압력에서 포화증기를 더 가열해 포화온도보다 높아진 증기가 과열증기입니다. 따라서 온도가 가장 높습니다.","x":["정답. 과열증기가 가장 높습니다.","습포화증기는 포화온도입니다.","건포화증기도 포화온도입니다.","포화증기는 포화온도입니다."],"t":"과열증기 > 포화증기(습·건 모두 포화온도)"},"2021-4-기관1-18":{"w":"기름 윤활식 선미관은 베어링 길이를 짧게 할 수 있고, 마멸이 작으며, 해수 침입이 적습니다. 대신 윤활유 압력을 유지하기 위한 중력유 탱크가 필요합니다.","x":["장점입니다.","장점입니다.","장점입니다.","정답(옳지 않은 것). 중력유 탱크가 필요합니다."],"t":"유윤활 선미관 = 중력 탱크 필요"},"2021-4-기관1-20":{"w":"유효마력(EHP)은 배를 일정한 속도로 끌고 가는 데 필요한 마력으로, 예인마력이라고도 합니다. 선체를 직접 추진하는 데 쓰이는 동력입니다.","x":["제동마력은 기관 출력축에서 나오는 마력입니다.","전달마력은 프로펠러에 전달되는 마력입니다.","추력마력은 프로펠러가 내는 추력에 의한 마력입니다.","정답. 유효마력 = 예인마력"],"t":"유효마력 = 예인마력(EHP)"},"2021-4-기관1-21":{"w":"15/4[℃] 비중은 같은 부피의 15[℃] 기름 무게와 4[℃] 물 무게의 비입니다.","x":["점도가 아닙니다.","점도가 아닙니다.","정답. 15[℃] 기름 / 4[℃] 물","반대입니다."],"t":"비중 15/4℃ = 기름(15℃) / 물(4℃)"},"2021-4-기관1-22":{"w":"유동점은 기름이 흐를 수 있는 가장 낮은 온도입니다. 유동점이 높으면 추울 때 기름이 굳어 잘 흐르지 않습니다.","x":["온도가 오르면 점도는 낮아집니다.","세탄가가 낮으면 착화성이 나빠집니다.","정답. 유동점이 높으면 한랭 시 잘 흐르지 않습니다.","인화점이 낮으면 화재 위험이 높아집니다."],"t":"유동점 높음 = 추울 때 문제"},"2021-4-기관1-24":{"w":"윤활유는 항유화성이 크고, 유성이 좋고, 점도가 적당하며, 응고점이 낮아야 합니다.","x":["맞습니다.","정답(옳지 않은 것). 응고점은 낮아야 합니다.","맞습니다.","맞습니다."],"t":"윤활유 = 응고점 낮게"},"2021-4-기관2-3":{"w":"원심펌프는 송출밸브를 조여 유량을 조절할 수 있습니다. 흡입밸브를 조이면 공동현상(캐비테이션)이 생기므로 흡입밸브는 조이면 안 됩니다.","x":["정격 운전을 해야 합니다.","베어링 온도에 주의해야 합니다.","흡입밸브를 조이면 캐비테이션이 생깁니다.","정답(옳지 않은 것). 송출밸브는 조여서 유량을 조절할 수 있습니다."],"t":"원심펌프 유량 조절 = 송출밸브 (흡입밸브 조임 금지)"},"2021-4-기관2-4":{"w":"회전속도를 바꿔 유량을 조절하면 밸브로 조이는 것처럼 저항 손실이 없어 효율이 가장 좋고 동력도 절약됩니다(인버터 제어).","x":["밸브 조임은 손실이 생깁니다.","흡입밸브를 조이면 캐비테이션이 생깁니다.","손실이 큽니다.","정답. 회전속도 조절"],"t":"가장 효율적 = 회전수 제어"},"2021-4-기관2-7":{"w":"추종장치는 타가 명령한 각도까지 움직이면 원동기 송출을 멈춰 그 위치에 타를 고정시킵니다.","x":["조종장치는 조타륜 등 명령 장치입니다.","정답. 추종장치","고정장치는 4대 요소가 아닙니다.","타장치는 타와 타두재입니다."],"t":"추종장치 = 명령 각도에서 정지"},"2021-4-기관2-10":{"w":"자동배유장치는 유면검출기와 전자밸브(그리고 타이머)로 구성됩니다.","x":["교반기는 없습니다.","빌지펌프는 배유장치가 아닙니다.","정답. 유면검출기, 전자밸브","틀립니다."],"t":"자동배유 = 유면검출기 + 전자밸브"},"2021-4-기관2-13":{"w":"습공기의 수증기 분압과 같은 온도의 포화 수증기 분압의 비[%]를 상대습도라 합니다.","x":["절대습도는 수증기 kg/건공기 kg입니다.","정답. 상대습도","비교습도는 절대습도의 비입니다.","포화도는 비교습도와 같습니다."],"t":"상대습도 = 분압 비"},"2021-4-기관2-14":{"w":"감습(제습) 방법은 냉각식, 흡착식(실리카겔), 흡수식(염화리튬) 등입니다. 증기 분사는 가습 방법입니다.","x":["냉각식은 감습입니다.","정답(아닌 것). 증기 분사는 가습입니다.","흡착식은 감습입니다.","흡수식은 감습입니다."],"t":"증기 분사 = 가습"},"2021-4-기관2-16":{"w":"베어링 간극처럼 좁은 틈새는 필러 게이지(틈새게이지)로 잽니다.","x":["정답. 필러 게이지","센터 게이지는 나사 바이트 각도를 봅니다.","피치 게이지는 나사 피치를 잽니다.","곡률 게이지는 반지름을 잽니다."],"t":"틈새 = 필러 게이지"},"2021-4-기관2-21":{"w":"재화중량톤수(DWT)는 만재 배수량에서 경하 배수량(빈 배의 무게)을 뺀 값으로, 배가 실을 수 있는 화물·연료·물 등의 무게를 나타냅니다.","x":["정답. 만재 배수량 − 경하 배수량 = 재화중량톤수","순톤수는 여객·화물 적재 용적입니다.","배수톤수는 배가 밀어낸 물의 무게입니다.","총톤수는 선박 전체의 용적입니다."],"t":"재화중량톤수 = 실을 수 있는 무게(DWT)"},"2021-4-기관3-2":{"w":"전류 I = 전하량 Q ÷ 시간 t = 0.3 ÷ 0.5 = 0.6[A]입니다.","x":["틀린 값입니다.","틀린 값입니다.","정답. 0.3[C] ÷ 0.5[s] = 0.6[A]","틀린 값입니다."],"t":"I = Q / t"},"2021-4-기관3-3":{"w":"주파수 f = 1 ÷ 주기 = 1 ÷ 0.2 = 5[Hz]입니다.","x":["틀립니다.","정답. 1 ÷ 0.2 = 5[Hz]","틀립니다.","틀립니다."],"t":"f = 1 / T"},"2021-4-기관3-5":{"w":"Z = √(8² + 6²) = 10[Ω], I = 100 ÷ 10 = 10[A]입니다.","x":["틀립니다.","틀립니다.","틀립니다.","정답. 10[A]"],"t":"6-8-10 삼각형"},"2021-4-기관3-6":{"w":"전류의 3대 작용은 발열작용(전열기), 자기작용(전동기), 화학작용(전기분해·축전지)입니다. 증폭작용은 트랜지스터의 작용입니다.","x":["화학작용은 3대 작용입니다.","발열작용은 3대 작용입니다.","정답(아닌 것). 증폭작용은 전류의 작용이 아닙니다.","자기작용은 3대 작용입니다."],"t":"전류 3대 작용 = 발열·자기·화학"},"2021-4-기관3-11":{"w":"교류는 시간에 따라 크기와 방향이 계속 바뀌고, 직류는 방향이 일정합니다.","x":["직류는 방향이 바뀌지 않습니다.","정답. 교류는 크기·방향이 변함","틀립니다.","틀립니다."],"t":"교류 = 크기·방향 변화"},"2021-4-기관3-12":{"w":"축전지는 충전할 때 수소가스를 발생시키므로 폭발을 막기 위해 통풍이 잘 되어야 합니다.","x":["정답. 수소가스","질소가 아닙니다.","아황산가스가 아닙니다.","산소도 나오지만 위험은 수소입니다."],"t":"축전지실 = 수소"},"2021-4-기관3-18":{"w":"절연저항은 온도와 관계없이 항상 클수록 좋습니다.","x":["작으면 누전됩니다.","틀립니다.","틀립니다.","정답. 모두 큰 것이 좋다"],"t":"절연저항 = 클수록 좋음"},"2021-4-기관3-21":{"w":"적분회로에 구형파를 넣으면 출력은 일정하게 증가·감소를 반복하는 삼각파가 됩니다.","x":["사인파가 아닙니다.","구형파가 아닙니다.","정답. 삼각파","펄스파는 미분회로의 출력입니다."],"t":"적분 → 삼각파, 미분 → 펄스"},"2021-4-기관3-22":{"w":"두 다이오드가 A, B에서 X 쪽으로 향하고 X가 저항으로 접지된 다이오드 OR 회로입니다. A나 B 중 하나라도 1이면 X가 1이 되므로 ②, ③, ④입니다.","x":["둘 다 0이면 X는 0입니다.","둘 다 0이면 X는 0입니다.","둘 다 0이면 X는 0입니다.","둘 다 0이면 X는 0입니다."],"t":"다이오드 → 출력, 저항 접지 = OR"},"2021-4-직무일반-1":{"w":"그림은 양쪽 끝에 수나사가 있는 짧은 관인 니플입니다.","x":["티는 T자 모양입니다.","정답. 니플","소켓은 암나사 이음입니다.","엘보는 꺾인 모양입니다."],"t":"니플 = 양쪽 수나사"},"2021-4-직무일반-2":{"w":"스톱밸브(글로브·앵글밸브)는 작동이 확실하고 밀착이 좋아 기관실에 많이 쓰이지만, 유체가 S자로 꺾여 흐르므로 완전히 열어도 저항(에너지 손실)이 큽니다. 손실이 가장 적은 것은 게이트(슬루스)밸브입니다.","x":["기관실에 많이 씁니다.","작동이 확실합니다.","글러브·앵글밸브로 나뉩니다.","정답(옳지 않은 것). 스톱밸브는 손실이 큰 편입니다."],"t":"손실 최소 = 게이트밸브"},"2021-4-직무일반-5":{"w":"피스톤 개방에는 피스톤링 확장기, 마이크로미터, 아이볼트(들어 올리기) 등이 필요합니다. 브리지게이지는 메인 베어링 마멸(처짐) 측정용입니다.","x":["정답(아닌 것). 브리지게이지는 베어링 측정용입니다.","필요합니다.","필요합니다.","필요합니다."],"t":"브리지게이지 = 메인 베어링"},"2021-4-직무일반-11":{"w":"검역 감염병에는 콜레라, 페스트, 황열 등이 있습니다. 장티푸스는 검역 감염병이 아닙니다.","x":["검역 감염병입니다.","정답(아닌 것). 장티푸스","검역 감염병입니다.","검역 감염병입니다."],"t":"검역 = 콜레라·페스트·황열"},"2021-4-직무일반-13":{"w":"응급처치는 생명을 구하고, 악화를 막고, 고통을 줄이는 것이 목적입니다. 의약품으로 치료 기간을 줄이는 것은 치료의 목적입니다.","x":["목적입니다.","목적입니다.","목적입니다.","정답(아닌 것). 치료가 목적이 아닙니다."],"t":"응급처치 = 생명 구조·악화 방지"},"2021-4-직무일반-17":{"w":"정전 후 예비발전기가 투입되면 Sequential start program(순차 기동 프로그램)이 주요 전동기를 차례로 자동 기동합니다.","x":["정답. 순차 기동","역전력 보호입니다.","우선 차단입니다.","수동 기동입니다."],"t":"sequential start = 순차 자동 기동"},"2021-4-직무일반-18":{"w":"기관구역 소화호스는 지름 40[mm], 최대 길이 15[m]입니다(갑판은 20[m]).","x":["길이가 틀립니다.","정답. 40[mm], 15[m]","틀립니다.","틀립니다."],"t":"기관실 소화호스 = 40mm·15m"},"2021-4-직무일반-20":{"w":"열작업 때는 반대편 격실에도 감시원을 두고, 가스 용기를 세우고, 혼자 작업하지 않습니다. 작업 구역은 통풍이 되어야 하므로 개폐구를 모두 닫아 두는 것은 옳지 않습니다.","x":["맞습니다.","맞습니다.","맞습니다.","정답(옳지 않은 것). 통풍을 유지합니다."],"t":"열작업 = 통풍·감시원"},"2021-4-영어-2":{"w":"\"주 섬프 탱크 바닥의 기름을 퍼내고 내부를 청소했다.\" bail = 퍼내다.","x":["검사했다","교환했다","공급했다","정답. Bailed"],"t":"bail out = 퍼내다"},"2021-4-영어-3":{"w":"유도전동기(Induction motor)는 여자전류 때문에 지상(뒤진) 역률을 만듭니다.","x":["정답. Induction motor","직류기는 역률이 없습니다.","직류기입니다.","직류기입니다."],"t":"유도전동기 = 지상 역률"},"2021-4-영어-6":{"w":"프로펠러 피치(1회전에 이론상 나아가는 거리)와 배가 실제 나아간 거리의 차이를 슬립(slip)이라 합니다.","x":["rpm = 분당 회전수","sailing mile = 항해 거리","정답. slip = 슬립","engine mile = 기관 거리(프로펠러 기준 거리)"],"t":"피치 − 실제 전진 거리 = slip"},"2021-4-영어-8":{"w":"하루는 자정부터 4시간씩 6개의 당직 시간으로 나눕니다.","x":["정답. four","틀립니다.","틀립니다.","틀립니다."],"t":"당직 = 4시간씩"},"2021-4-영어-13":{"w":"Be sure to ~ = 반드시 ~하시오, tighten = 조이다. \"호스 연결부를 확실히 조이시오.\"","x":["점검하다는 check입니다.","정답. 확실히 조이시오","분리하다는 disconnect입니다.","확인하다는 confirm입니다."],"t":"tighten = 조이다, loosen = 풀다"},"2021-4-영어-15":{"w":"피스톤과 실린더 라이너 사이의 틈을 가스가 새지 않게 막는 것은 피스톤링(piston ring)입니다.","x":["propeller = 프로펠러","정답. piston ring = 피스톤링","piston skirt = 피스톤 스커트(측압을 받는 부분)","scavenge port = 소기공"],"t":"piston ring = gas tight sealing"},"2021-4-영어-16":{"w":"\"기관 내부의 먼지와 카본을 청소한다\"는 윤활유의 청정 작용입니다.","x":["냉각수가 아닙니다.","시동공기가 아닙니다.","역전공기가 아닙니다.","정답. Lubricating oil"],"t":"윤활유 = 청정 작용"},"2021-4-영어-17":{"w":"\"윤활유 탱크 레벨을 점검하고 필요하면 보충하시오.\" 레벨은 점검(check)합니다.","x":["Fill = 채우다","정답. Check = 점검하다","Replace = 교체하다","Overhaul = 분해 정비하다"],"t":"check level and refill"},"2021-4-영어-21":{"w":"보일러의 과도한 압력을 조절(방출)하는 밸브는 safety valve(안전밸브)입니다.","x":["suction valve = 흡입밸브","정답. safety valve = 안전밸브","exhaust valve = 배기밸브","air valve = 공기밸브"],"t":"safety valve = 과압 방출"},"2021-4-영어-22":{"w":"\"연료유는 청정된 뒤 서비스(service) 탱크에 저장된다.\"","x":["슬러지 탱크","정답. service tank","저장 탱크는 청정 전입니다.","넘침 탱크"],"t":"청정 후 = service tank"},"2022-1-기관1-2":{"w":"소기효율은 소기가 끝난 뒤 실린더 안에 남은 새 공기(급기)의 무게를 실린더 안 전체 가스 무게로 나눈 값입니다. 잔류 배기가스가 적을수록 높습니다.","x":["정답. 소기효율","급기효율은 공급 공기량 기준입니다.","충전효율은 표준 상태 공기량 기준입니다.","용적효율은 흡입 부피의 비율입니다."],"t":"소기효율 = 새 공기 / 전체 가스"},"2022-1-기관1-6":{"w":"2행정 기관에서 피스톤이 상사점 부근에 오면 압축이 끝나 연료가 분사됩니다. 소기공과 배기밸브는 하사점 부근에서 열립니다.","x":["배기밸브는 하사점 전에 열립니다.","소기공은 하사점 부근에서 열립니다.","안전밸브는 이상 압력 때만 열립니다.","정답. 상사점 부근 = 연료 분사"],"t":"상사점 = 분사, 하사점 = 소기·배기"},"2022-1-기관1-7":{"w":"피스톤링은 기밀 유지, 열 전달, 유막 형성을 합니다. 측압은 피스톤 스커트가 받습니다.","x":["기밀을 유지합니다.","정답(아닌 것). 측압은 피스톤 스커트가 받습니다.","열을 전달합니다.","유막을 만듭니다."],"t":"측압 = 피스톤 스커트"},"2022-1-기관1-12":{"w":"수관 보일러는 관 안의 물이 가열되므로 보유 수량이 적어 짧은 시간에 증기를 만들 수 있고, 고압·대용량에 적합합니다. 대신 급수 순도가 높아야 하고 부하 변동에 따른 압력 변화가 크며 청소가 어렵습니다.","x":["순도 높은 급수가 필요한 것은 단점입니다.","압력 변화가 큰 것은 단점입니다.","구조가 복잡해 청소·보수가 어렵습니다.","정답. 증기 발생이 빠릅니다."],"t":"수관 보일러 = 빠른 증기 발생, 고압용"},"2022-1-기관1-15":{"w":"복수기로 배기를 진공(대기압보다 낮은 압력)으로 만들면 터빈 입구와 출구의 압력 차(열낙차)가 커져 증기가 더 많은 일을 하므로 터빈의 효율이 높아집니다.","x":["정답. 열낙차를 크게 해 효율을 높이기 위해","크기를 작게 하려는 목적이 아닙니다.","입구 증기 압력과는 관계없습니다.","입구 증기 속도와는 관계없습니다."],"t":"배기 진공 → 열낙차 증가 → 효율 증가"},"2022-1-기관1-24":{"w":"윤활유가 고온의 실린더 벽이나 피스톤에 닿으면 열분해되어 탄화물(카본)이 생깁니다. 이 카본이 쌓이면 실린더 마멸과 피스톤링 고착의 원인이 됩니다.","x":["산소와 접촉하면 산화(슬러지)가 생깁니다.","정답. 고온 → 열분해 → 탄화물","금속 가루·수분은 오염·유화의 원인입니다.","새 윤활유 혼합은 탄화물의 원인이 아닙니다."],"t":"윤활유 탄화물 = 고온 열분해"},"2022-1-기관2-2":{"w":"회전속도를 바꿔 유량을 조절하면 밸브로 조이는 것처럼 저항 손실이 없어 효율이 가장 좋고 동력도 절약됩니다(인버터 제어).","x":["밸브 조임은 손실이 생깁니다.","흡입밸브를 조이면 캐비테이션이 생깁니다.","손실이 큽니다.","정답. 회전속도 조절"],"t":"가장 효율적 = 회전수 제어"},"2022-1-기관2-4":{"w":"펌프 효율 = 수마력(유체가 얻은 동력) ÷ 축마력(펌프에 들어간 동력)입니다.","x":["반대입니다.","틀린 식입니다.","틀린 식입니다.","정답. 수마력 / 축마력"],"t":"효율 = 출력(수마력) / 입력(축마력)"},"2022-1-기관2-7":{"w":"윈치처럼 저속·고토크가 필요한 곳에는 반지름방향(레이디얼) 피스톤 모터를 많이 씁니다.","x":["기어 모터는 고속·저토크용입니다.","정답. 반지름방향 피스톤 모터","축방향 피스톤 모터는 고속용입니다.","서보 모터는 위치 제어용입니다."],"t":"윈치 = 레이디얼 피스톤 모터(저속 고토크)"},"2022-1-기관2-10":{"w":"기름여과장치는 유면검출기가 기름층을 감지하면 배유 전자밸브를 열고, 일정 시간이 지나면 타이머 신호로 밸브를 닫습니다.","x":["콜레서는 기름을 뭉치게 하는 필터입니다.","포집관은 기름을 모으는 관입니다.","정답. 타이머 신호로 닫힘","전동기는 펌프를 돌립니다."],"t":"배유밸브 = 유면검출기로 열림, 타이머로 닫힘"},"2022-1-기관2-11":{"w":"냉동톤 = 332,000 ÷ 3,320 = 100 RT. 동력 = 100 × 0.8 = 80[kW]입니다.","x":["틀린 값입니다.","틀린 값입니다.","정답. 100RT × 0.8 = 80[kW]","틀린 값입니다."],"t":"1RT = 3,320kcal/h"},"2022-1-기관2-12":{"w":"응축기 출구(액관)에는 건조기 → 전자밸브 → 자동팽창밸브 → (증발기) → 증발압력 조절밸브 순서로 설치합니다.","x":["순서가 틀렸습니다.","순서가 틀렸습니다.","순서가 틀렸습니다.","정답. 건조기 → 전자밸브 → 팽창밸브 → 증발압력 조절밸브"],"t":"건조기 → 전자밸브 → 팽창밸브"},"2022-1-기관2-15":{"w":"증발기에 끼는 서리는 냉장고(냉동실) 안 공기 속의 수분이 차가운 증발기 표면에 얼어붙은 것입니다.","x":["냉매 속 수분은 팽창밸브를 막히게 합니다.","정답. 냉장고 안 수분이 얼어붙은 것","냉매는 얼지 않습니다.","냉각수와 관계없습니다."],"t":"서리 = 고내 수분"},"2022-1-기관2-19":{"w":"선반으로 절삭, 보링, 널링, 나사 가공 등을 할 수 있습니다. 단조는 두드려 성형하는 작업으로 선반 작업이 아닙니다.","x":["선반 작업입니다.","정답(아닌 것). 단조","선반 작업입니다.","선반 작업입니다."],"t":"단조 = 해머·프레스"},"2022-1-기관3-2":{"w":"주파수 f = 1 ÷ 주기 = 1 ÷ 0.2 = 5[Hz]입니다.","x":["틀립니다.","정답. 1 ÷ 0.2 = 5[Hz]","틀립니다.","틀립니다."],"t":"f = 1 / T"},"2022-1-기관3-3":{"w":"전류의 3대 작용은 발열작용(전열기), 자기작용(전동기), 화학작용(전기분해·축전지)입니다. 증폭작용은 트랜지스터의 작용입니다.","x":["화학작용은 3대 작용입니다.","발열작용은 3대 작용입니다.","정답(아닌 것). 증폭작용은 전류의 작용이 아닙니다.","자기작용은 3대 작용입니다."],"t":"전류 3대 작용 = 발열·자기·화학"},"2022-1-기관3-5":{"w":"직류 전력 P = EI = I²R = E²/R 입니다.","x":["정답. P = E²/R","틀린 식입니다.","틀린 식입니다.","틀린 식입니다."],"t":"P = E² / R"},"2022-1-기관3-6":{"w":"전류 I = Q ÷ t = 10 ÷ 2 = 5[A]입니다.","x":["틀린 값입니다.","정답. 10 ÷ 2 = 5[A]","틀린 값입니다.","곱한 값입니다."],"t":"I = Q / t"},"2022-1-기관3-9":{"w":"피상전력 = EI [VA]입니다.","x":["유효전력입니다.","무효전력입니다.","정답. EI","해당 없음"],"t":"피상 EI"},"2022-1-기관3-24":{"w":"적분회로에 구형파를 넣으면 출력은 일정하게 증가·감소를 반복하는 삼각파가 됩니다.","x":["사인파가 아닙니다.","구형파가 아닙니다.","정답. 삼각파","펄스파는 미분회로의 출력입니다."],"t":"적분 → 삼각파, 미분 → 펄스"},"2022-1-직무일반-4":{"w":"그림처럼 머리가 둥근 고리 모양인 볼트는 아이볼트로, 무거운 부품을 들어 올릴 때 씁니다.","x":["스터드볼트는 양쪽이 나사인 볼트입니다.","육각볼트는 머리가 육각입니다.","타이볼트는 긴 연결 볼트입니다.","정답. 아이볼트"],"t":"아이볼트 = 인양용 고리"},"2022-1-직무일반-5":{"w":"한국선급의 선급유지 검사는 정기, 중간, 연차, 입거, 보일러, 계속검사 등입니다. 임시항해검사는 선박안전법의 검사입니다.","x":["선급 검사입니다.","선급 검사입니다.","선급 검사입니다.","정답(아닌 것). 임시항해검사"],"t":"임시항해검사 = 선박안전법"},"2022-1-직무일반-14":{"w":"침수 시에는 장소 확인, 방수 작업, 배수펌프 가동을 먼저 합니다. 모든 발전기를 멈추면 배수할 수 없습니다.","x":["배수합니다.","조사합니다.","방수합니다.","정답(옳지 않은 것). 발전기를 정지하면 안 됩니다."],"t":"침수 = 발전기 유지하며 배수"},"2022-1-직무일반-15":{"w":"정전 직후 기관실 비상전등은 축전지(비상배터리)에서 즉시 전원을 받아 켜집니다.","x":["주발전기는 정전된 상태입니다.","정답. 축전지","예비발전기는 기동에 시간이 걸립니다.","인버터는 변환 장치입니다."],"t":"정전 직후 = 축전지"},"2022-1-직무일반-21":{"w":"모든 선박은 다른 설비와 관계없이 수(물) 소화장치를 기본으로 갖춰야 합니다.","x":["선택 설비입니다.","정답. 수 소화장치","선택 설비입니다.","선택 설비입니다."],"t":"기본 = 물 소화"},"2022-1-직무일반-22":{"w":"선박법은 국적·톤수 측정·등록을 정해 해상 질서 유지와 국민 경제 향상에 기여하는 법입니다. 감항성 유지는 선박안전법의 목적입니다.","x":["해상 질서 유지는 선박법 목적입니다.","정답(옳지 않은 것). 감항성은 선박안전법입니다.","국민 경제 향상은 선박법 목적입니다.","톤수 측정·등록은 선박법 내용입니다."],"t":"감항성 = 선박안전법"},"2022-1-직무일반-24":{"w":"유조선이 아닌 선박의 기관구역용 폐유저장용기는 총톤수 5~10톤 미만 20[ℓ], 10~30톤 미만 60[ℓ], 30~50톤 미만 100[ℓ], 50~100톤 미만 200[ℓ]입니다.","x":["5톤 이상 10톤 미만 기준입니다.","10톤 이상 30톤 미만 기준입니다.","30톤 이상 50톤 미만 기준입니다.","정답. 50톤 이상 100톤 미만 = 200[ℓ]"],"t":"폐유저장용기 20 → 60 → 100 → 200ℓ"},"2022-1-직무일반-25":{"w":"해양오염방지설비를 선박에 처음 설치해 항해에 사용하려면 정기검사를 받습니다.","x":["정답. 최초 설치 = 정기검사","중간검사는 유효기간 중에 받습니다.","특별검사는 따로 정한 경우입니다.","임시검사는 개조·수리 때 받습니다."],"t":"최초 = 정기검사"},"2022-1-영어-3":{"w":"태핏 간극 = tappet clearance 입니다.","x":["air gap = 공극","overlap clearance가 아닙니다.","top clearance = 톱 클리어런스","정답. tappet clearance"],"t":"tappet clearance = 밸브 간극"},"2022-1-영어-6":{"w":"hair crack = 머리카락처럼 가는 미세한 균열입니다.","x":["부식이 아닙니다.","전식이 아닙니다.","정답. 미세한 균열","침식이 아닙니다."],"t":"hair crack = 미세 균열"},"2022-1-영어-7":{"w":"\"지방표준시(L.S.T.)에 맞추려고 시계를 1시간 앞당겼다.\" advance = 앞당기다.","x":["Received = 받았다","Slowed = 늦췄다(시계에는 retard를 씀)","정답. Advanced = 앞당겼다","Completed = 끝냈다"],"t":"advance 앞당김, retard 늦춤"},"2022-1-영어-10":{"w":"Scavenging port(소기공)는 2행정 기관(2 stroke engine)의 실린더 아래쪽에 있는 공기 흡입구입니다.","x":["정답. 2 stroke engine","4행정 기관은 흡기밸브를 씁니다.","가스터빈에는 없습니다.","증기터빈에는 없습니다."],"t":"scavenging port = 2행정"},"2022-1-영어-13":{"w":"\"주 섬프 탱크 바닥의 기름을 퍼내고 내부를 청소했다.\" bail = 퍼내다.","x":["검사했다","교환했다","공급했다","정답. Bailed"],"t":"bail out = 퍼내다"},"2022-1-영어-15":{"w":"폐유, 슬러지, 고형 폐기물을 태우는 노는 incinerator(소각기)입니다.","x":["온수기","정답. incinerator","기름 보일러","배기가스 보일러"],"t":"incinerator = 소각기"},"2022-1-영어-16":{"w":"흡·배기밸브가 모두 닫히고 피스톤이 올라가며 공기를 압축하는 것은 압축행정입니다.","x":["흡입행정이 아닙니다.","배기행정이 아닙니다.","작동행정이 아닙니다.","정답. Compression stroke"],"t":"압축행정"},"2022-1-영어-21":{"w":"시간당 해리(nautical miles per hour)로 나타낸 속도는 knot(노트)입니다.","x":["배럴","와트","동력","정답. knot"],"t":"knot = 해리/시"},"2022-1-영어-24":{"w":"양묘기(windlass)는 닻(anchor)을 감아올리고 내리는 갑판 기계입니다.","x":["accommodation ladder = 현문 사다리","rudder = 타(조타기가 담당)","cargo = 화물(하역 윈치·크레인이 담당)","정답. anchor = 닻"],"t":"windlass = anchor handling"},"2022-1-영어-25":{"w":"갑판기계의 주 구동 방식으로 가장 흔한 것은 유압(hydraulic)입니다.","x":["steam = 증기(옛 방식)","pneumatic = 공기압","정답. hydraulic = 유압","electronic = 전자식"],"t":"갑판기계 = hydraulic"},"2022-2-기관1-4":{"w":"메인 베어링은 과부하, 윤활유 부족, 크랭크축 중심선 어긋남, 베어링 틈새 부적당 등으로 발열합니다. 점도지수가 큰 윤활유는 온도가 변해도 점도 변화가 작은 좋은 윤활유입니다.","x":["과부하는 발열 원인입니다.","중심선 어긋남은 편하중으로 발열 원인입니다.","윤활유 부족은 발열 원인입니다.","정답(아닌 것). 점도지수가 큰 윤활유는 좋은 윤활유입니다."],"t":"점도지수 큼 = 온도에 따른 점도 변화 작음(좋음)"},"2022-2-기관1-5":{"w":"피스톤핀은 트렁크형 기관에서 피스톤과 커넥팅로드를 연결하고 힘을 전달하며, 표면 경화강으로 만듭니다. 크로스헤드형 기관에는 피스톤핀이 없고 크로스헤드핀이 있습니다.","x":["트렁크형에서 피스톤과 커넥팅로드를 연결합니다.","힘을 전달합니다.","표면 경화강을 씁니다.","정답(옳지 않은 것). 크로스헤드형에는 피스톤핀이 없습니다."],"t":"피스톤핀 = 트렁크형 기관"},"2022-2-기관1-8":{"w":"배기가 검은색이 되는 원인은 공기 부족(소기압력 저하), 불완전 연소, 과부하 등입니다. 연료유에 물이 섞이면 흰색 배기가 나옵니다.","x":["불완전 연소는 흑색 배기의 원인입니다.","정답(아닌 것). 물이 섞이면 흰색 배기가 됩니다.","과부하는 흑색 배기의 원인입니다.","소기압력이 낮으면 공기가 부족해 흑색 배기가 됩니다."],"t":"흑색 = 공기 부족·과부하, 백색 = 물 혼입"},"2022-2-기관1-11":{"w":"보슈식 연료분사펌프는 배럴, 플런저, 토출밸브, 래크·피니언 등으로 구성됩니다. 스필밸브는 스필(밸브)식 펌프의 부품입니다.","x":["구성 요소입니다.","정답(아닌 것). 스필밸브는 없습니다.","구성 요소입니다.","구성 요소입니다."],"t":"보슈식 = 배럴·플런저·토출밸브"},"2022-2-기관1-15":{"w":"보일러 안전밸브 스프링은 상온에서 밀착될 때까지 압축해 10분 두었을 때 영구 변형이 자유 높이의 1[%]를 넘으면 안 됩니다.","x":["정답. 1[%]","틀립니다.","틀립니다.","틀립니다."],"t":"안전밸브 스프링 영구변형 ≤ 1%"},"2022-2-기관1-16":{"w":"미첼형 추력 베어링은 칼라와 기울어진 패드 사이에 기름이 쐐기 모양으로 들어가 높은 유압으로 추력을 받습니다.","x":["보통형이 아닙니다.","정답. 미첼형","말굽형은 칼라 여러 개를 쓰는 옛 형식입니다.","해당하지 않습니다."],"t":"미첼형 = 경사 패드 쐐기 유막"},"2022-2-기관1-24":{"w":"온도에 따른 점도 변화 정도를 나타내는 것은 점도지수입니다.","x":["아닐린점은 착화성 관련입니다.","정답. 점도지수","API는 비중입니다.","해당하지 않습니다."],"t":"점도지수"},"2022-2-기관1-25":{"w":"마찰은 고체마찰, 경계마찰, 유체마찰(과 그 중간 상태)로 나눕니다. 기체마찰은 분류에 없습니다.","x":["고체마찰은 마찰 종류입니다.","정답(아닌 것). 기체마찰","경계마찰은 마찰 종류입니다.","유체마찰은 마찰 종류입니다."],"t":"마찰 = 고체·경계·유체"},"2022-2-기관2-8":{"w":"기름여과장치는 유면검출기가 기름층을 감지하면 배유 전자밸브를 열고, 일정 시간이 지나면 타이머 신호로 밸브를 닫습니다.","x":["콜레서는 기름을 뭉치게 하는 필터입니다.","포집관은 기름을 모으는 관입니다.","정답. 타이머 신호로 닫힘","전동기는 펌프를 돌립니다."],"t":"배유밸브 = 유면검출기로 열림, 타이머로 닫힘"},"2022-2-기관2-9":{"w":"점도가 높은 폐유를 일정하게 보내는 데는 기어 펌프를 많이 씁니다.","x":["제트 펌프가 아닙니다.","정답. 기어 펌프","터빈 펌프가 아닙니다.","피스톤 펌프가 아닙니다."],"t":"폐유 = 기어 펌프"},"2022-2-기관2-10":{"w":"원심펌프가 송출을 못 하는 원인은 흡입양정이 너무 큼, 흡입관에 공기가 남아 있거나 새어 들어옴, 유체 온도가 너무 높아 증발(공동현상) 등입니다. 유체 온도가 낮은 것은 원인이 아닙니다.","x":["흡입양정이 크면 흡입이 안 됩니다.","흡입관 속 공기는 송출 불량의 원인입니다.","정답(옳지 않은 것). 온도가 높을 때가 문제입니다.","공기가 흡입되면 송출이 안 됩니다."],"t":"원심펌프 송출 불량 = 공기, 큰 흡입양정, 높은 유체 온도"},"2022-2-기관2-11":{"w":"불응축 가스(공기)가 들어가면 응축기에서 응축되지 않아 응축(압축) 압력이 높아지고, 동력이 늘며 냉동능력이 떨어집니다.","x":["흡입 압력과 관계없습니다.","응축 압력은 높아집니다.","냉동능력은 나빠집니다.","정답. 압축 압력 상승"],"t":"불응축 가스 = 고압 상승"},"2022-2-기관2-13":{"w":"암모니아는 구리와 구리합금을 부식시키므로 암모니아 냉동장치에는 강관·주철관 등을 쓰고 동관은 쓰지 않습니다. (프레온은 동관 사용)","x":["철은 사용할 수 있습니다.","주철은 사용할 수 있습니다.","정답. 암모니아는 동을 부식시킵니다.","강은 사용할 수 있습니다."],"t":"암모니아 = 동 사용 금지"},"2022-2-기관2-16":{"w":"버니어 캘리퍼스, 마이크로미터, 다이얼 게이지는 측정 공구이고, 바이스는 일감을 고정하는 공구입니다.","x":["측정 공구입니다.","측정 공구입니다.","측정 공구입니다.","정답(아닌 것). 바이스는 고정 공구입니다."],"t":"바이스 = 고정"},"2022-2-기관2-18":{"w":"선반은 원통 깎기, 나사 가공, 보링, 테이퍼 가공 등을 합니다. 기어 가공은 밀링이나 기어 전용 가공기로 합니다.","x":["정답. 기어 가공은 선반으로 어렵습니다.","수나사는 선반으로 가공합니다.","보링은 선반으로 합니다.","테이퍼는 선반으로 가공합니다."],"t":"기어 = 밀링·호빙"},"2022-2-기관2-23":{"w":"선체 저항은 마찰 저항, 조파 저항, 조와(와류) 저항, 공기 저항입니다.","x":["경계·충격·잉여 저항은 분류가 아닙니다.","정답. 마찰·조파·조와·공기","틀립니다.","틀립니다."],"t":"선체 저항 = 마찰·조파·조와·공기"},"2022-2-기관3-2":{"w":"주파수 f = 1 ÷ 주기 = 1 ÷ 0.2 = 5[Hz]입니다.","x":["틀립니다.","정답. 1 ÷ 0.2 = 5[Hz]","틀립니다.","틀립니다."],"t":"f = 1 / T"},"2022-2-기관3-3":{"w":"피상전력² = 유효전력² + 무효전력² 이므로 유효전력 = √(50² − 30²) = 40[W]. 역률 = 40 ÷ 50 = 0.8입니다.","x":["무효율(30/50)입니다.","틀린 값입니다.","정답. 40 ÷ 50 = 0.8","틀린 값입니다."],"t":"3:4:5 → 역률 0.8, 무효율 0.6"},"2022-2-기관3-4":{"w":"저항만 있는 회로에서는 전압과 전류의 위상이 같습니다.","x":["정답. 저항성 회로","유도성은 전류가 늦습니다.","용량성은 전류가 빠릅니다.","RL은 전류가 늦습니다."],"t":"R = 위상 같음"},"2022-2-기관3-6":{"w":"전류 I = Q ÷ t = 10 ÷ 2 = 5[A]입니다.","x":["틀린 값입니다.","정답. 10 ÷ 2 = 5[A]","틀린 값입니다.","곱한 값입니다."],"t":"I = Q / t"},"2022-2-기관3-12":{"w":"납축전지는 충전 중 물이 분해되어 가스로 나가고 증발도 하므로 물만 줄어듭니다. 그래서 황산이 아니라 증류수를 보충합니다.","x":["전해액은 묽은 황산입니다.","폭발 방지가 목적이 아닙니다.","열 억제가 목적이 아닙니다.","정답. 물만 손실되므로"],"t":"전해액 부족 = 증류수 보충"},"2022-2-기관3-14":{"w":"선박의 3상 동기발전기 전기자 권선은 보통 Y결선으로 하고, 유도전동기 고정자 권선은 정상 운전 시 △결선으로 합니다(Y-△ 기동 후 △로 운전).","x":["전동기는 정상 운전 시 △결선입니다.","정답. 발전기 Y, 전동기 △","반대입니다.","발전기는 Y결선입니다."],"t":"발전기 Y, 전동기(운전 중) △"},"2022-2-기관3-15":{"w":"병렬운전 시 주파수와 위상이 맞는지 확인하는 계기는 동기검정기(싱크로스코프)입니다.","x":["주파수만 봅니다.","AVR은 전압 조정기입니다.","정답. 동기검정기","역률계는 역률을 봅니다."],"t":"동기검정기 = 주파수·위상 확인"},"2022-2-기관3-21":{"w":"PLC 디지털 입력 회로는 외부 신호와 내부 회로를 전기적으로 절연하기 위해 포토커플러(Photo-coupler)를 가장 많이 씁니다.","x":["OP Amp가 아닙니다.","FET가 아닙니다.","정답. 포토커플러","UJT가 아닙니다."],"t":"PLC 입력 = 포토커플러(절연)"},"2022-2-직무일반-1":{"w":"Abstract log(적요일지)는 한 항차가 끝난 뒤 그 항차의 주요 내용(항해시간, 연료 소비 등)을 요약한 기록입니다.","x":["Bell book은 기관 명령 기록부입니다.","정답. Abstract log = 항차 요약","Condition report는 상태 보고서입니다.","Engine room log book은 매일 쓰는 기관일지입니다."],"t":"Abstract log = 항차 요약"},"2022-2-직무일반-4":{"w":"스톱밸브(글로브·앵글밸브)는 작동이 확실하고 밀착이 좋아 기관실에 많이 쓰이지만, 유체가 S자로 꺾여 흐르므로 완전히 열어도 저항(에너지 손실)이 큽니다. 손실이 가장 적은 것은 게이트(슬루스)밸브입니다.","x":["기관실에 많이 씁니다.","작동이 확실합니다.","글러브·앵글밸브로 나뉩니다.","정답(옳지 않은 것). 스톱밸브는 손실이 큰 편입니다."],"t":"손실 최소 = 게이트밸브"},"2022-2-직무일반-10":{"w":"선저의 유성 혼합물은 기름여과장치로 처리해 배출하거나, 저장탱크에 모아 두었다가 육상으로 양륙합니다. 청정기로 처리하지 않습니다.","x":["여과 후 배출합니다.","정답(옳지 않은 것). 청정기로 처리하지 않습니다.","저장합니다.","양륙합니다."],"t":"빌지 = 여과장치·저장·양륙"},"2022-2-직무일반-14":{"w":"침몰 우려가 있으면 가장 먼저 선내 침수 상황을 전 승무원에게 알려 모두 대비하게 해야 합니다.","x":["귀중품 정리는 우선 조치가 아닙니다.","조난통신은 선교(선장)가 합니다.","정답. 전 승무원에게 알린다","그다음 조치입니다."],"t":"비상 시 1순위 = 전원에게 알림"},"2022-2-직무일반-15":{"w":"보일러 본체에는 부식, 점식(피팅), 균열, 과열로 인한 변형 등의 손상이 생깁니다. 노킹은 기관의 이상 연소 현상입니다.","x":["피팅(점식)은 보일러 손상입니다.","부식은 보일러 손상입니다.","정답(아닌 것). 노킹은 기관에서 생기는 현상입니다.","균열은 보일러 손상입니다."],"t":"보일러 손상 = 부식·피팅·균열·과열"},"2022-2-직무일반-16":{"w":"정전 직후 기관실 비상전등은 축전지(비상배터리)에서 즉시 전원을 받아 켜집니다.","x":["주발전기는 정전된 상태입니다.","정답. 축전지","예비발전기는 기동에 시간이 걸립니다.","인버터는 변환 장치입니다."],"t":"정전 직후 = 축전지"},"2022-2-직무일반-17":{"w":"디젤발전기의 경보·정지 조건은 과속도, 윤활유 압력 저하, 냉각수 온도 상승 등입니다. 소기 압력 저하는 발전기 정지 조건이 아닙니다.","x":["조건입니다.","조건입니다.","정답(아닌 것). 소기 압력 저하","조건입니다."],"t":"D/G 정지 = 과속·LO 압력↓·냉각수 온도↑"},"2022-2-직무일반-19":{"w":"연기식 탐지기는 광전자식, 이온화식, 안개실식 등입니다. 차동식은 온도 상승률로 작동하는 열식 탐지기입니다.","x":["정답(아닌 것). 차동식은 열식","연기식입니다.","연기식입니다.","연기식입니다."],"t":"차동식 = 열식"},"2022-2-직무일반-21":{"w":"과전류가 흐르면 전선·기기가 과열되어 전기화재의 위험이 가장 큽니다.","x":["정답. 과전류","절연저항이 높으면 안전합니다.","부하용량이 큰 것 자체는 위험이 아닙니다.","정격 이내라면 오래 사용해도 위험하지 않습니다."],"t":"전기화재 1순위 = 과전류"},"2022-2-직무일반-22":{"w":"선박안전법상 검사는 건조·정기·중간(1종·2종)·임시·임시항해·국제협약검사 등입니다. 프로펠러축검사는 선급 검사 항목입니다.","x":["해당합니다.","해당합니다.","정답(아닌 것). 프로펠러축검사","해당합니다."],"t":"선박안전법 검사 = 정기·중간·임시·임시항해"},"2022-2-영어-2":{"w":"연료 수급 중 기름 유출 위험이 가장 큰 때는 탱크를 가득 채우는 마지막 단계(topped off)입니다.","x":["시작할 때가 아닙니다.","정답. topped off = 가득 채울 때","멈춘 뒤가 아닙니다.","시작 전이 아닙니다."],"t":"topping off = 가장 위험"},"2022-2-영어-6":{"w":"비상탈출호흡구 = EEBD(Emergency Escape Breathing Device)입니다.","x":["EEDI = 에너지효율설계지수","틀립니다.","틀립니다.","정답. EEBD"],"t":"EEBD = 비상탈출호흡구"},"2022-2-영어-10":{"w":"응축기 덮개의 아연판(zinc plates)은 해수 부식을 막는 방식(anti-corrosion)용입니다.","x":["정답. anti-corrosion","노킹 방지가 아닙니다.","안정기가 아닙니다.","침식 방지가 아닙니다."],"t":"zinc = 부식 방지"},"2022-2-영어-11":{"w":"stores on hand = 현재 가지고 있는(재고) 선용품입니다.","x":["정답. 재고 선용품","소비된 것은 consumed입니다.","새것은 new입니다.","사용 중은 in use입니다."],"t":"on hand = 보유 중인"},"2022-2-영어-12":{"w":"주배전반에서 수리할 대상으로 MCCB(배선용 차단기)가 알맞습니다.","x":["ACC는 자동연소제어입니다.","DPT는 차압 발신기입니다.","FWC는 해당하지 않습니다.","정답. MCCB"],"t":"배전반 = MCCB·ACB"},"2022-2-영어-13":{"w":"기관 회전수는 tachometer(회전계)로 잽니다.","x":["온도계","압력계","정답. tachometer","동력계"],"t":"tachometer = 회전계"},"2022-2-영어-15":{"w":"기계의 속도를 일정하게 유지하는 장치는 Governor(조속기)입니다.","x":["정답. Governor","증발기","안정기","지시기"],"t":"governor = 조속기"},"2022-2-영어-16":{"w":"선교와 기관실 사이에 기관 명령을 주고받는 장치는 기관 텔레그래프(engine telegraph)입니다.","x":["telescope = 망원경","정답. telegraph = 기관 텔레그래프","diaphragm = 격막","tachometer = 회전계"],"t":"engine telegraph = 선교↔기관실 명령 전달"},"2022-2-영어-19":{"w":"원심펌프에서 모터의 에너지를 받아 유체를 바깥으로 가속시키는 회전 부품은 impeller(임펠러)입니다.","x":["Packing gland = 패킹 글랜드","정답. Impeller = 임펠러","Bearing = 베어링","Mechanical seal = 기계식 실"],"t":"impeller = 회전차"},"2022-2-영어-20":{"w":"선박의 열교환기는 대부분 뜨거운 액체를 해수나 청수로 식히는 냉각기(cooler)입니다.","x":["냉각되는 쪽의 액체입니다.","공기나 증기가 아닙니다.","정답. sea water or fresh water","기기 이름입니다."],"t":"cooler = 해수·청수로 냉각"},"2022-2-영어-21":{"w":"IHP = Indicated Horse Power = 지시마력(도시마력)입니다. 기계효율 = BHP ÷ IHP.","x":["제동마력은 BHP입니다.","전달마력은 DHP입니다.","유효마력은 EHP입니다.","정답. IHP = 지시(도시)마력"],"t":"기계효율 = BHP / IHP"},"2022-2-영어-25":{"w":"우회전 프로펠러(right-handed propeller)는 배 뒤에서 보았을 때 전진 시 시계방향(clockwise)으로 돕니다.","x":["정답. clockwise = 시계방향","outward = 바깥쪽","anticlockwise = 반시계방향","inward = 안쪽"],"t":"right-handed = clockwise"},"2022-3-기관1-1":{"w":"무기 분사식(고압 연료를 직접 분사하는 방식) 디젤기관은 정적·정압 연소가 섞인 복합(사바테) 사이클을 기본으로 합니다.","x":["정답. 복합 사이클","가솔린기관입니다.","공기 분사식 저속 디젤의 사이클입니다.","증기 사이클입니다."],"t":"무기 분사식 = 복합(사바테) 사이클"},"2022-3-기관1-2":{"w":"피스톤링용 주철 속의 흑연은 스스로 윤활 작용을 하고 윤활유를 머금어 유막을 유지하게 합니다.","x":["철은 기본 성분입니다.","정답. 흑연 = 자기 윤활","니켈은 강도·내식성을 높입니다.","크롬은 내마모성을 높입니다."],"t":"주철 속 흑연 = 윤활 보조"},"2022-3-기관1-3":{"w":"고정 피치 프로펠러를 구동하는 주기관의 출력은 회전수의 세제곱에 비례해 증가합니다(프로펠러 법칙).","x":["틀립니다.","토크는 제곱에 비례합니다.","정답. 세제곱 비례 증가","감소하지 않습니다."],"t":"출력 ∝ N³, 토크 ∝ N²"},"2022-3-기관1-4":{"w":"메인 베어링은 과부하, 윤활유 부족, 크랭크축 중심선 어긋남, 베어링 틈새 부적당 등으로 발열합니다. 점도지수가 큰 윤활유는 온도가 변해도 점도 변화가 작은 좋은 윤활유입니다.","x":["과부하는 발열 원인입니다.","중심선 어긋남은 편하중으로 발열 원인입니다.","윤활유 부족은 발열 원인입니다.","정답(아닌 것). 점도지수가 큰 윤활유는 좋은 윤활유입니다."],"t":"점도지수 큼 = 온도에 따른 점도 변화 작음(좋음)"},"2022-3-기관1-6":{"w":"배기밸브는 더 뜨거워 많이 늘어나므로 태핏 간극을 흡기밸브와 같거나 더 크게 합니다. 간극은 그 실린더가 압축행정 상사점(밸브가 완전히 닫힌 상태)에 있을 때 조정합니다.","x":["정답. ①, ② 모두 옳다","②도 옳습니다.","둘 다 옳습니다.","①도 옳습니다."],"t":"태핏 간극 = 압축 TDC에서, 배기 ≥ 흡기"},"2022-3-기관1-7":{"w":"보슈형 펌프는 래크로 플런저를 회전시켜 경사홈의 위치를 바꿔 유효행정(토출량)을 조절합니다.","x":["토출밸브를 돌리지 않습니다.","정답. 플런저를 회전","스필밸브는 다른 형식입니다.","흡입밸브로 조절하지 않습니다."],"t":"보슈형 = 플런저 회전"},"2022-3-기관1-8":{"w":"밸브 겹침은 상사점 부근에서 흡기·배기밸브가 함께 열려 있는 구간입니다. 흡기밸브 열림(상사점 전 15°) + 배기밸브 닫힘(상사점 후 10°) = 25°입니다.","x":["틀린 값입니다.","배기만 두 번 더한 값입니다.","정답. 15° + 10° = 25°","흡기만 두 번 더한 값입니다."],"t":"오버랩 = 흡기 열림(BTDC) + 배기 닫힘(ATDC)"},"2022-3-기관1-10":{"w":"성능곡선(시운전 곡선)에는 회전수·출력에 따른 연료소비율, 기계효율, 최고압력, 배기온도 등이 나옵니다. 연료분사압력은 나오지 않습니다.","x":["알 수 있습니다.","알 수 있습니다.","알 수 있습니다.","정답(알 수 없는 것). 연료분사압력"],"t":"성능곡선 ≠ 분사압력"},"2022-3-기관1-11":{"w":"과급된 공기는 압축되며 온도가 올라가 밀도가 낮아집니다. 공기 냉각기로 식히면 밀도가 높아져 더 많은 공기를 실린더에 넣을 수 있습니다.","x":["주목적이 아닙니다.","주목적이 아닙니다.","정답. 공기 밀도를 높이기 위해","오히려 착화지연은 길어질 수 있습니다."],"t":"공기 냉각기 = 밀도 증가"},"2022-3-기관1-12":{"w":"팽창 중인 증기 일부를 뽑아 급수를 가열하는 사이클은 재생 사이클입니다. 다시 가열해 터빈에 넣는 것은 재열 사이클입니다.","x":["이론 사이클입니다.","기본 증기 사이클입니다.","정답. 재생 사이클","재열 사이클은 증기를 다시 가열합니다."],"t":"재생 = 추기로 급수 가열, 재열 = 증기 재가열"},"2022-3-기관1-13":{"w":"캐리오버는 발생 증기와 함께 보일러 물(물방울, 불순물)이 밖으로 딸려 나가는 현상입니다. 포밍, 프라이밍이 원인입니다.","x":["정상적인 증기 공급입니다.","정답. 보일러수가 증기와 함께 반출","응축 현상입니다.","수면계 착오입니다."],"t":"캐리오버 = 증기에 물이 섞여 나감"},"2022-3-기관1-14":{"w":"같은 압력에서 포화증기를 더 가열해 포화온도보다 높아진 증기가 과열증기입니다. 따라서 온도가 가장 높습니다.","x":["정답. 과열증기가 가장 높습니다.","습포화증기는 포화온도입니다.","건포화증기도 포화온도입니다.","포화증기는 포화온도입니다."],"t":"과열증기 > 포화증기(습·건 모두 포화온도)"},"2022-3-기관1-15":{"w":"보일러 안전밸브 스프링은 상온에서 밀착될 때까지 압축해 10분 두었을 때 영구 변형이 자유 높이의 1[%]를 넘으면 안 됩니다.","x":["정답. 1[%]","틀립니다.","틀립니다.","틀립니다."],"t":"안전밸브 스프링 영구변형 ≤ 1%"},"2022-3-기관1-16":{"w":"기관 회전 방향은 그대로 두고 날개 각도를 바꿔 전진·후진하는 추진기는 가변 피치 프로펠러(CPP)입니다.","x":["분사추진기(워터제트)가 아닙니다.","외차추진기가 아닙니다.","고정 피치는 날개 각도가 고정됩니다.","정답. 가변 피치 프로펠러"],"t":"CPP = 날개 각도로 전후진"},"2022-3-기관1-17":{"w":"물·공기 저항을 이기며 선체를 예인하는 데 필요한 마력은 유효마력입니다.","x":["도시마력은 실린더 안 마력입니다.","전달마력이 아닙니다.","제동마력이 아닙니다.","정답. 유효마력"],"t":"예인 = 유효마력"},"2022-3-기관1-18":{"w":"프로펠러 날개가 손상되면 진동이 생기고 추진력과 추진효율이 떨어집니다. 반류 증가는 날개 손상의 영향이 아닙니다.","x":["진동이 생깁니다.","추진력이 줄어듭니다.","정답(옳지 않은 것). 반류와 관계없습니다.","추진효율이 떨어집니다."],"t":"날개 손상 = 진동·추진력↓"},"2022-3-기관1-19":{"w":"컬러 체크는 침투액과 현상액을 쓰는 침투 탐상법입니다.","x":["자분 탐상법입니다.","초음파 탐상법입니다.","고주파 탐상법입니다.","정답. 침투 탐상법"],"t":"컬러 체크 = 침투 탐상"},"2022-3-기관1-21":{"w":"수증기의 증발잠열을 뺀 발열량은 저위 발열량입니다.","x":["정답. 저위 발열량","고위 발열량은 증발잠열을 포함합니다.","틀립니다.","틀립니다."],"t":"저위 = 증발잠열 제외"},"2022-3-기관1-24":{"w":"탄소가 공기 부족으로 불완전 연소하면 일산화탄소(CO)가 생깁니다. 완전 연소하면 이산화탄소(CO₂)가 됩니다.","x":["완전 연소의 생성물입니다.","정답. 불완전 연소 = CO","수소가 연소한 것입니다.","황이 연소한 것입니다."],"t":"C 불완전 연소 = CO"},"2022-3-기관2-2":{"w":"불활성가스장치의 공급주관 가스 속 산소 농도는 5[%] 이하, 화물탱크 안은 8[%] 이하로 유지해야 합니다.","x":["틀립니다.","정답. 5[%] 이하","탱크 내 기준입니다.","틀립니다."],"t":"IGS 공급 5%↓, 탱크 8%↓"},"2022-3-기관2-3":{"w":"유면검출기가 기름층을 감지하면 배유 전자밸브를 열고, 타이머 신호로 닫습니다.","x":["콜레서는 기름을 뭉치게 합니다.","포집관은 기름을 모읍니다.","타이머는 밸브를 닫습니다.","정답. 유면검출기 신호로 열림"],"t":"열림 = 유면검출기, 닫힘 = 타이머"},"2022-3-기관2-6":{"w":"사이드 스러스터는 배가 거의 멈춰 있을 때(선속 0) 옆으로 미는 힘이 가장 큽니다. 속력이 나면 효과가 급격히 줄어듭니다.","x":["전속에서는 효과가 거의 없습니다.","틀립니다.","정답. 선속 0일 때","틀립니다."],"t":"사이드 스러스터 = 저속·정지 시 효과"},"2022-3-기관2-10":{"w":"오염된 물(오수)을 물리적·화학적·생물화학적으로 처리하는 장치는 오수처리장치입니다.","x":["공조장치가 아닙니다.","정답. 오수처리장치","기름을 분리하는 장치입니다.","폐유를 태우는 장치입니다."],"t":"오수처리장치 = 분뇨·오수 처리"},"2022-3-기관2-11":{"w":"불응축 가스(공기)가 들어가면 응축기에서 응축되지 않아 응축(압축) 압력이 높아지고, 동력이 늘며 냉동능력이 떨어집니다.","x":["흡입 압력과 관계없습니다.","응축 압력은 높아집니다.","냉동능력은 나빠집니다.","정답. 압축 압력 상승"],"t":"불응축 가스 = 고압 상승"},"2022-3-기관2-12":{"w":"냉동장치는 증발기에서 냉매가 증발할 때 주위의 열(증발열, 잠열)을 흡수합니다.","x":["정답. 증발열","승화열이 아닙니다.","응고열이 아닙니다.","현열이 아닙니다."],"t":"냉동 = 증발잠열"},"2022-3-기관2-13":{"w":"공기조화장치는 온도, 습도, 기류(풍속), 청정도를 조절합니다. 압력 조절은 기능이 아닙니다.","x":["온도 조절은 기능입니다.","습도 조절은 기능입니다.","기류 조절은 기능입니다.","정답(아닌 것). 압력은 조절하지 않습니다."],"t":"공조 4요소 = 온도·습도·기류·청정도"},"2022-3-기관2-15":{"w":"실내에서 밖으로 열이 빠져나가는 겨울철 조건이므로 공급 공기를 가열해야 합니다. 가열하면 상대습도가 떨어지므로 가습도 함께 해야 합니다.","x":["냉각·감습은 여름철 조건입니다.","냉각은 맞지 않습니다.","가열은 맞지만 감습은 맞지 않습니다.","정답. 겨울철 = 가열 + 가습"],"t":"여름 = 냉각·감습, 겨울 = 가열·가습"},"2022-3-기관2-18":{"w":"플랜지 접합면처럼 움직이지 않는 면 사이에 넣어 누설을 막는 것은 개스킷입니다.","x":["정답. 개스킷","스크레이퍼링은 기름 긁기 링입니다.","기계식 실은 회전축용입니다.","글랜드 패킹은 축용입니다."],"t":"플랜지 = 개스킷"},"2022-3-기관2-19":{"w":"버니어 캘리퍼스, 마이크로미터, 다이얼 게이지는 측정 공구이고, 바이스는 일감을 고정하는 공구입니다.","x":["측정 공구입니다.","측정 공구입니다.","측정 공구입니다.","정답(아닌 것). 바이스는 고정 공구입니다."],"t":"바이스 = 고정"},"2022-3-기관2-22":{"w":"용골은 배 밑바닥 중심선을 따라 선수재에서 선미재까지 이어진 가장 중요한 종강력재로, 사람의 척추에 해당합니다.","x":["늑골은 갈비뼈처럼 횡으로 선 부재입니다.","정답. 용골","빌지킬은 횡요(롤링)를 줄이는 부재입니다.","격벽은 선내를 나누는 벽입니다."],"t":"용골 = 배의 척추"},"2022-3-기관2-24":{"w":"기능상 지장이 없는 범위에서 미리 정한 치수의 허용량을 공차라 합니다.","x":["정답. 공차","해칭은 단면 표시입니다.","스머징은 단면 칠하기입니다.","거칠기는 표면 상태입니다."],"t":"공차 = 허용 범위"},"2022-3-기관3-1":{"w":"거주실 전원 220[V]는 실효값입니다.","x":["최대값이 아닙니다.","순시값이 아닙니다.","정답. 실효값","평균값이 아닙니다."],"t":"전원 표시 = 실효값"},"2022-3-기관3-2":{"w":"병렬 회로는 각 저항에 같은 전압이 걸립니다. 21÷2 + 21÷2 + 21÷3 = 10.5 + 10.5 + 7 = 28[A]입니다.","x":["틀린 값입니다.","정답. 10.5 + 10.5 + 7 = 28[A]","틀린 값입니다.","틀린 값입니다."],"t":"병렬 전체 전류 = 각 가지 전류의 합"},"2022-3-기관3-3":{"w":"전류 I = Q ÷ t = 10 ÷ 2 = 5[A]입니다.","x":["틀린 값입니다.","정답. 10 ÷ 2 = 5[A]","틀린 값입니다.","곱한 값입니다."],"t":"I = Q / t"},"2022-3-기관3-4":{"w":"주파수 f = 1 ÷ 주기 = 1 ÷ 0.2 = 5[Hz]입니다.","x":["틀립니다.","정답. 1 ÷ 0.2 = 5[Hz]","틀립니다.","틀립니다."],"t":"f = 1 / T"},"2022-3-기관3-6":{"w":"여자기는 교류발전기의 계자 권선에 직류 전류를 공급해 자속을 만듭니다.","x":["주파수는 회전수로 정해집니다.","부하 분담은 거버너가 합니다.","정답. 계자에 직류 공급","속도는 거버너가 조절합니다."],"t":"여자기 = 계자 직류 공급"},"2022-3-기관3-9":{"w":"XL = 2πfL = 2π × 60 × 0.005 = 0.6π[Ω]입니다.","x":["단위(mH)를 바꾸지 않은 값입니다.","틀린 값입니다.","틀린 값입니다.","정답. 2π × 60 × 0.005 = 0.6π"],"t":"XL = 2πfL (mH → H)"},"2022-3-기관3-11":{"w":"철심을 얇게 성층하면 맴돌이 전류(와류) 손실을 줄일 수 있습니다.","x":["정답. 와류손 방지","히스테리시스손은 규소강으로 줄입니다.","마찰손과 관계없습니다.","표유부하손과 관계없습니다."],"t":"성층 = 와류손↓"},"2022-3-기관3-18":{"w":"3상 유도전동기 속도 제어법은 주파수 변환, 극수 변환, 2차 저항 가감(권선형), 전압 제어 등입니다. 전류 변환법은 없습니다.","x":["정답(아닌 것). 전류 변환법","속도 제어법입니다.","속도 제어법입니다.","속도 제어법입니다."],"t":"속도 제어 = 주파수·극수·2차 저항"},"2022-3-기관3-19":{"w":"정류 출력을 평활하게 하려면 출력단에 콘덴서를 병렬로 연결합니다(코일은 직렬).","x":["콘덴서는 병렬입니다.","정답. 콘덴서 병렬","부하저항을 작게 하면 맥동이 커집니다.","코일은 직렬로 넣습니다."],"t":"평활 = C 병렬, L 직렬"},"2022-3-기관3-20":{"w":"적분회로에 구형파를 넣으면 출력은 일정하게 증가·감소를 반복하는 삼각파가 됩니다.","x":["사인파가 아닙니다.","구형파가 아닙니다.","정답. 삼각파","펄스파는 미분회로의 출력입니다."],"t":"적분 → 삼각파, 미분 → 펄스"},"2022-3-기관3-25":{"w":"다이오드 기호에 게이트 단자가 붙은 것은 SCR(실리콘 제어 정류기)입니다.","x":["정답. SCR","UJT는 이미터 화살표가 있는 기호입니다.","TR은 베이스·컬렉터·이미터 기호입니다.","다이오드에는 게이트가 없습니다."],"t":"SCR = 다이오드 + 게이트"},"2022-3-직무일반-1":{"w":"부식으로 얇아진 외판 두께는 한쪽 면에서 초음파를 보내 반사 시간으로 두께를 재는 초음파 두께 측정법으로 잽니다.","x":["정답. 두께 측정 = 초음파","자기탐상은 표면 균열 검사용입니다.","다이체크는 표면 균열 검사용입니다.","침투탐상은 표면 균열 검사용입니다."],"t":"두께 측정 = 초음파"},"2022-3-직무일반-2":{"w":"한국선급의 선급유지 검사는 정기, 중간, 연차, 입거, 보일러, 계속검사 등입니다. 임시항해검사는 선박안전법의 검사입니다.","x":["선급 검사입니다.","선급 검사입니다.","선급 검사입니다.","정답(아닌 것). 임시항해검사"],"t":"임시항해검사 = 선박안전법"},"2022-3-직무일반-3":{"w":"그림처럼 머리가 둥근 고리 모양인 볼트는 아이볼트로, 무거운 부품을 들어 올릴 때 씁니다.","x":["스터드볼트는 양쪽이 나사인 볼트입니다.","육각볼트는 머리가 육각입니다.","타이볼트는 긴 연결 볼트입니다.","정답. 아이볼트"],"t":"아이볼트 = 인양용 고리"},"2022-3-직무일반-4":{"w":"그림은 둥근 눈금판과 바늘로 작은 변위를 읽는 다이얼게이지입니다. 축의 흔들림(휨)·크랭크암 개폐량 등을 잽니다.","x":["틈새게이지는 얇은 판 묶음입니다.","온도게이지가 아닙니다.","정답. 다이얼게이지","한계게이지는 통과·정지 게이지입니다."],"t":"다이얼게이지 = 작은 변위 측정"},"2022-3-직무일반-6":{"w":"선박에서 나오는 대기오염물질은 황산화물, 질소산화물, 오존층 파괴물질, 휘발성 유기화합물 등입니다. 유기주석 화합물은 선체 도료(방오도료)의 유해물질로 해양오염물질입니다.","x":["황산화물은 대기오염물질입니다.","오존층 파괴물질은 대기오염물질입니다.","질소산화물은 대기오염물질입니다.","정답(아닌 것). 유기주석은 방오도료 물질입니다."],"t":"유기주석(TBT) = 방오도료"},"2022-3-직무일반-7":{"w":"수급 시 갑판 배수구(스커퍼)는 막아 두고, 방제 자재를 가까이 두고, 탱크를 자주 측심해 넘치지 않게 합니다. 맨홀을 열어 두면 안 됩니다.","x":["①은 틀립니다(배수구는 막아야 함).","①은 틀립니다(배수구는 막아야 함).","①은 틀립니다(배수구는 막아야 함).","①은 틀립니다(배수구는 막아야 함)."],"t":"수급 = 스커퍼 막기·방제자재·자주 측심"},"2022-3-직무일반-8":{"w":"기관구역 기름기록부의 슬러지는 청정기 슬러지, 자동 여과기 드레인, 세틀링 탱크 드레인 등 기름 찌꺼기입니다. 보일러 급수탱크 드레인은 물이므로 슬러지가 아닙니다.","x":["정답(아닌 것). 급수탱크 드레인은 물입니다.","슬러지입니다.","슬러지입니다.","슬러지입니다."],"t":"슬러지 = 기름 찌꺼기"},"2022-3-직무일반-10":{"w":"유성찌꺼기는 바다에 버릴 수 없고, 육상 수용시설에 넘기거나 승인된 소각설비로 소각합니다.","x":["유성찌꺼기는 해양 배출이 금지됩니다.","선저폐수는 여과 후 배출하거나 육상에 넘깁니다.","혼합물과 함께 배출할 수 없습니다.","정답. 승인된 소각설비로 유성찌꺼기 소각"],"t":"유성찌꺼기 = 소각 또는 육상 처리"},"2022-3-직무일반-11":{"w":"혈액에서 산소를 운반하는 것은 적혈구(헤모글로빈)입니다.","x":["백혈구는 면역을 담당합니다.","정답. 적혈구","혈소판은 혈액 응고를 담당합니다.","감마 글로불린은 항체입니다."],"t":"적혈구 = 산소 운반"},"2022-3-직무일반-12":{"w":"관절의 뼈가 제자리에서 빠져나온 상태를 탈구라 합니다.","x":["염좌는 인대가 늘어난 것입니다.","타박상은 부딪힌 상처입니다.","정답. 탈구","골절은 뼈가 부러진 것입니다."],"t":"탈구 = 관절이 빠짐"},"2022-3-직무일반-13":{"w":"2도 화상은 진피까지 손상되어 물집이 생기고 통증이 심합니다.","x":["1도는 붉어지기만 합니다.","정답. 2도 화상","3도는 피부 전층이 손상됩니다.","해당하지 않습니다."],"t":"2도 = 물집"},"2022-3-직무일반-16":{"w":"침몰 우려가 있으면 가장 먼저 선내 침수 상황을 전 승무원에게 알려 모두 대비하게 해야 합니다.","x":["귀중품 정리는 우선 조치가 아닙니다.","조난통신은 선교(선장)가 합니다.","정답. 전 승무원에게 알린다","그다음 조치입니다."],"t":"비상 시 1순위 = 전원에게 알림"},"2022-3-직무일반-19":{"w":"소화전에는 소화 호스, 노즐, 스패너(연결용)를 비치합니다. 안전등은 비치하지 않습니다.","x":["비치합니다.","비치합니다.","비치합니다.","정답(아닌 것). 안전등"],"t":"소화전 = 호스·노즐·스패너"},"2022-3-직무일반-20":{"w":"화재의 3요소는 가연물질, 열(점화원), 산소입니다.","x":["정답. 가연물·열·산소","압력이 아닙니다.","질소는 불연성입니다.","질소는 불연성입니다."],"t":"화재 3요소 = 가연물·열·산소"},"2022-3-직무일반-21":{"w":"과전류가 흐르면 전선·기기가 과열되어 전기화재의 위험이 가장 큽니다.","x":["정답. 과전류","절연저항이 높으면 안전합니다.","부하용량이 큰 것 자체는 위험이 아닙니다.","정격 이내라면 오래 사용해도 위험하지 않습니다."],"t":"전기화재 1순위 = 과전류"},"2022-3-직무일반-22":{"w":"해양오염방지관리인은 선박의 오염방지설비 정비·점검, 방제 자재 관리, 기름·폐기물기록부 기록·보관 등을 합니다. 해양시설 오염물질기록부는 해양시설(육상)의 업무입니다.","x":["업무입니다.","정답(아닌 것). 해양시설 기록부","업무입니다.","업무입니다."],"t":"오염방지관리인 = 선박 기록부·설비"},"2022-3-영어-1":{"w":"아연판(zinc plate)은 해수가 흐르는 냉각기의 전식 방지용으로 붙입니다. \"주기관 윤활유 냉각기의 아연판 4개를 교체했다.\"","x":["크랭크케이스에는 아연판을 붙이지 않습니다.","정답. M/E L.O. cooler(해수 냉각)","공기탱크에는 아연판이 없습니다.","연료유 가열기에는 아연판이 없습니다."],"t":"zinc plate = 해수 냉각기 부식 방지"},"2022-3-영어-5":{"w":"선박의 열교환기는 대부분 뜨거운 액체를 해수나 청수로 식히는 냉각기(cooler)입니다.","x":["냉각되는 쪽의 액체입니다.","공기나 증기가 아닙니다.","정답. sea water or fresh water","기기 이름입니다."],"t":"cooler = 해수·청수로 냉각"},"2022-3-영어-9":{"w":"프로펠러 피치(1회전에 이론상 나아가는 거리)와 배가 실제 나아간 거리의 차이를 슬립(slip)이라 합니다.","x":["rpm = 분당 회전수","sailing mile = 항해 거리","정답. slip = 슬립","engine mile = 기관 거리(프로펠러 기준 거리)"],"t":"피치 − 실제 전진 거리 = slip"},"2022-3-영어-10":{"w":"F.O.T. = Fuel Oil Tank(연료유 탱크)입니다.","x":["맞습니다.","맞습니다.","정답(옳지 않은 것). F.O.T. = Fuel Oil Tank","맞습니다."],"t":"FOT = 연료유 탱크"},"2022-3-영어-13":{"w":"F.W.E.(Finished With Engine, 기관 사용 종료) 후에는 테스트 콕을 열고, 보조 송풍기를 멈추고, 에어 러닝을 하고, 터닝기어를 연결(engage)해 주기관을 돌립니다. 터닝기어를 분리(disengage)하는 것은 시동 준비 때 하는 일입니다.","x":["테스트 콕을 엽니다.","보조 송풍기를 멈춥니다.","에어 러닝을 합니다.","정답(아닌 것). F.W.E. 후에는 터닝기어를 연결합니다."],"t":"F.W.E. 후 = engage turning gear"},"2022-3-영어-14":{"w":"벌류트 펌프를 기동하기 위해 물을 붓는 것을 Priming(마중물 넣기)이라 합니다.","x":["Sounding = 측심","정답. Priming","Warming = 난기","Turning = 터닝"],"t":"priming = 마중물"},"2022-3-영어-15":{"w":"발전기 병렬 운전(동기화)은 전압, 주파수, 위상을 맞추는 것입니다. 전류는 맞출 조건이 아닙니다.","x":["전압을 맞춥니다.","위상을 맞춥니다.","정답(적절하지 않은 것). 전류는 동기화 조건이 아닙니다.","주파수를 맞춥니다."],"t":"병렬운전 조건 = 전압·주파수·위상"},"2022-3-영어-21":{"w":"힘의 단위는 뉴턴(Newton)입니다.","x":["Joule은 일·에너지 단위입니다.","정답. Newton","Watt는 일률 단위입니다.","Horsepower는 마력입니다."],"t":"힘 N, 에너지 J, 일률 W"},"2022-3-영어-22":{"w":"원심펌프에서 모터의 에너지를 받아 유체를 바깥으로 가속시키는 회전 부품은 impeller(임펠러)입니다.","x":["Packing gland = 패킹 글랜드","정답. Impeller = 임펠러","Bearing = 베어링","Mechanical seal = 기계식 실"],"t":"impeller = 회전차"},"2022-3-영어-24":{"w":"흡·배기밸브가 닫힌 채 연소로 압력이 올라 피스톤을 밀어 내리는 것은 작동(폭발) 행정입니다.","x":["흡입행정이 아닙니다.","배기행정이 아닙니다.","정답. Working stroke","압축행정이 아닙니다."],"t":"연소 → 피스톤 하강 = 작동행정"},"2022-3-영어-25":{"w":"프로펠러 추력을 선체에 전달하는 베어링은 thrust bearing(추력 베어링)입니다.","x":["main bearing = 메인 베어링","정답. thrust bearing = 추력 베어링","crosshead bearing = 크로스헤드 베어링","crank pin bearing = 크랭크핀 베어링"],"t":"thrust bearing = 추력 전달"},"2022-4-기관1-1":{"w":"압축비 = (행정부피 + 압축부피) ÷ 압축부피 = (1,900 + 100) ÷ 100 = 20입니다. 회전수는 계산에 필요 없습니다.","x":["틀린 값입니다.","틀린 값입니다.","행정부피 ÷ 압축부피만 한 값입니다.","정답. 2,000 ÷ 100 = 20"],"t":"압축비 = (Vs + Vc) / Vc"},"2022-4-기관1-2":{"w":"플라이휠은 같은 무게라면 두께보다 지름을 크게 하는 것이 관성모멘트가 커서 회전을 고르게 하는 데 효과적입니다.","x":["정답(옳지 않은 것). 지름을 크게 하는 것이 효과적입니다.","저속 회전을 가능하게 합니다.","실린더 수가 적으면 더 커야 합니다.","고속기관은 작아도 됩니다."],"t":"플라이휠 = 지름이 효과적(관성모멘트)"},"2022-4-기관1-6":{"w":"4행정 기관에서 배기행정 종말(상사점 부근)에는 가스 압력 없이 관성력이 크랭크축을 끌어올려 메인 베어링 캡에 최대 하중이 걸립니다.","x":["틀립니다.","정답. 배기행정 종말","틀립니다.","압축 종말에는 하중이 아래쪽에 걸립니다."],"t":"캡 최대 하중 = 배기 말"},"2022-4-기관1-7":{"w":"메인 베어링은 과부하, 윤활유 부족, 크랭크축 중심선 어긋남, 베어링 틈새 부적당 등으로 발열합니다. 점도지수가 큰 윤활유는 온도가 변해도 점도 변화가 작은 좋은 윤활유입니다.","x":["과부하는 발열 원인입니다.","중심선 어긋남은 편하중으로 발열 원인입니다.","윤활유 부족은 발열 원인입니다.","정답(아닌 것). 점도지수가 큰 윤활유는 좋은 윤활유입니다."],"t":"점도지수 큼 = 온도에 따른 점도 변화 작음(좋음)"},"2022-4-기관1-9":{"w":"배기밸브 고착은 스핀들과 가이드의 열전도 불량, 스핀들의 큰 열팽창, 간격이 너무 작을 때, 카본 퇴적 등으로 생깁니다. 밸브 박스를 충분히 냉각하는 것은 오히려 고착을 막습니다.","x":["열전도가 나쁘면 과열로 고착됩니다.","열팽창이 크면 틈이 없어져 고착됩니다.","정답(아닌 것). 냉각은 고착 방지 대책입니다.","간격이 작으면 고착됩니다."],"t":"밸브 고착 = 과열·틈새 부족·카본"},"2022-4-기관1-11":{"w":"그림의 ①은 캠의 움직임을 푸시로드로 받아 밸브스핀들을 눌러 여는 시소 모양의 로커암입니다.","x":["푸시로드는 캠과 로커암 사이의 막대입니다.","정답. ① = 로커암","밸브스핀들은 밸브의 축입니다.","롤러암은 캠에 닿는 부분입니다."],"t":"캠 → 푸시로드 → 로커암 → 밸브"},"2022-4-기관1-12":{"w":"안전밸브의 방출능력은 증기 정지밸브를 닫고 최대 연소 상태로 운전해 압력이 일정 한도 이상 오르지 않는지 확인하는 축기시험으로 확인합니다.","x":["정답. 축기시험","압력시험이 아닙니다.","진공시험이 아닙니다.","수압시험은 강도·누설 시험입니다."],"t":"안전밸브 방출능력 = 축기시험"},"2022-4-기관1-17":{"w":"프로펠러에 의한 축계 진동은 피치 불균일, 캐비테이션, 정적·동적 불평형 등으로 생깁니다. 날개 전개면적이 작은 것은 직접 원인이 아닙니다.","x":["원인입니다.","정답(아닌 것). 전개면적","원인입니다.","원인입니다."],"t":"프로펠러 진동 = 피치·캐비테이션·불평형"},"2022-4-기관1-20":{"w":"겉보기 슬립 = (Vp − V) ÷ Vp 입니다.","x":["정답. (Vp − V) / Vp","틀린 식입니다.","틀린 식입니다.","틀린 식입니다."],"t":"슬립 = (이론 − 실제) / 이론"},"2022-4-기관1-22":{"w":"디젤기관 윤활유는 온도 변화에도 점도가 잘 변하지 않는 점도지수가 큰 윤활유가 적절합니다.","x":["점도가 크기만 하면 마찰 손실이 큽니다.","정답. 점도지수가 큰 윤활유","항유화성은 커야 합니다.","산화안정도는 커야 합니다."],"t":"좋은 윤활유 = 점도지수↑"},"2022-4-기관1-25":{"w":"불꽃 없이 온도를 높여 저절로 불이 붙기 시작하는 최저 온도는 발화점(착화점)입니다.","x":["유동점은 흐를 수 있는 최저 온도입니다.","정답. 발화점","인화점은 불꽃을 대면 불이 붙는 온도입니다.","응고점은 굳는 온도입니다."],"t":"발화점 = 스스로, 인화점 = 불꽃 대면"},"2022-4-기관2-2":{"w":"회전식 펌프는 기어, 나사, 베인 펌프 등입니다. 제트펌프는 고속 유체의 흐름으로 빨아올리는 특수 펌프입니다.","x":["정답(아닌 것). 제트펌프","회전식입니다.","회전식입니다.","회전식입니다."],"t":"제트펌프 = 이젝터 원리"},"2022-4-기관2-3":{"w":"사이드 스러스터는 선박을 옆으로 움직이는 추진장치로, 선수나 선미 부근의 수면 아래에 옆으로 뚫린 터널 안에 설치합니다.","x":["갑판에 설치하지 않습니다.","정답. 선수·선미 부근 수면 아래","크랭크축 끝이 아닙니다.","기관실 안쪽이 아닙니다."],"t":"사이드(바우) 스러스터 = 수면 아래 터널"},"2022-4-기관2-4":{"w":"불활성가스장치의 공급주관 가스 속 산소 농도는 5[%] 이하, 화물탱크 안은 8[%] 이하로 유지해야 합니다.","x":["틀립니다.","정답. 5[%] 이하","탱크 내 기준입니다.","틀립니다."],"t":"IGS 공급 5%↓, 탱크 8%↓"},"2022-4-기관2-5":{"w":"왕복펌프는 송출량은 적지만 높은 압력을 낼 수 있어, 적은 양을 높은 압력으로 보낼 때 씁니다.","x":["많은 양은 원심펌프가 적합합니다.","정답. 소유량 고압","대유량 저압은 축류펌프입니다.","적합하지 않습니다."],"t":"왕복펌프 = 소유량·고압"},"2022-4-기관2-6":{"w":"전동 유압식 조타장치의 전동기는 항해 중 계속 회전하고, 조타할 때만 가변 용량 펌프의 송출 방향·양이 바뀌어 타를 움직입니다.","x":["틀립니다.","정답. 항상 회전","틀립니다.","틀립니다."],"t":"조타 전동기 = 상시 회전"},"2022-4-기관2-7":{"w":"기름여과장치는 유면검출기가 기름층을 감지하면 배유 전자밸브를 열고, 일정 시간이 지나면 타이머 신호로 밸브를 닫습니다.","x":["콜레서는 기름을 뭉치게 하는 필터입니다.","포집관은 기름을 모으는 관입니다.","정답. 타이머 신호로 닫힘","전동기는 펌프를 돌립니다."],"t":"배유밸브 = 유면검출기로 열림, 타이머로 닫힘"},"2022-4-기관2-10":{"w":"유압식 계선 윈치는 조종 밸브로 유압모터에 가는 기름의 방향과 양을 바꿔 드럼의 회전 방향과 속도를 조절합니다.","x":["베벨 기어가 아닙니다.","펌프는 기름을 보낼 뿐입니다.","모터는 구동 장치입니다.","정답. 조종 밸브"],"t":"방향·속도 = 조종 밸브"},"2022-4-기관2-11":{"w":"액분리기는 증발기 출구 냉매 가스 속의 냉매액을 분리해 압축기로 액이 들어가지 않게 하고 분리한 액을 증발기 쪽으로 되돌립니다.","x":["정답. 액분리기","유분리기는 윤활유를 분리합니다.","수액기는 액 냉매를 저장합니다.","팽창밸브는 냉매량을 조절합니다."],"t":"액분리기 = 액 냉매 분리"},"2022-4-기관2-12":{"w":"냉동장치는 증발기에서 냉매가 증발할 때 주위의 열(증발열, 잠열)을 흡수합니다.","x":["정답. 증발열","승화열이 아닙니다.","응고열이 아닙니다.","현열이 아닙니다."],"t":"냉동 = 증발잠열"},"2022-4-기관2-14":{"w":"증발관에 서리가 끼면 전열이 나빠지므로 제상장치로 서리를 제거해 전열작용을 좋게 합니다.","x":["부하경감장치는 기동 부하를 줄입니다.","배기장치가 아닙니다.","정답. 제상장치","건조장치는 수분을 제거합니다."],"t":"제상 = 전열 회복"},"2022-4-기관2-16":{"w":"연삭숫돌은 숫돌 입자, 입도, 결합도, 조직, 결합제의 5가지로 표기합니다. 거칠기는 표기 항목이 아닙니다.","x":["입도(입자 크기)는 표기합니다.","조직(입자 밀도)은 표기합니다.","결합도(단단한 정도)는 표기합니다.","정답(아닌 것). 거칠기는 표기하지 않습니다."],"t":"숫돌 표기 = 입자·입도·결합도·조직·결합제"},"2022-4-기관2-17":{"w":"외력에 대항해 재료 내부에 생기는 단위 면적당 저항력을 응력이라 합니다.","x":["정답. 응력","변형률은 늘어난 비율입니다.","하중은 외력입니다.","경도는 단단한 정도입니다."],"t":"응력 = 힘 / 면적"},"2022-4-기관2-20":{"w":"철판 두께는 외경 마이크로미터로 정밀하게 잴 수 있습니다.","x":["다이얼 게이지는 변위를 잽니다.","정답. 외경 마이크로미터","틈새 게이지는 틈을 잽니다.","서피스 게이지는 금긋기용입니다."],"t":"두께 = 외경 마이크로미터"},"2022-4-기관2-21":{"w":"조파저항은 배가 만드는 파도에 의한 저항으로, 속력이 빨라질수록 급격히 커집니다.","x":["정답. 증가","감소하지 않습니다.","일정하지 않습니다.","계속 증가합니다."],"t":"조파저항 = 고속에서 커짐"},"2022-4-기관2-24":{"w":"기능상 지장이 없는 범위에서 미리 정한 치수의 허용량을 공차라 합니다.","x":["정답. 공차","해칭은 단면 표시입니다.","스머징은 단면 칠하기입니다.","거칠기는 표면 상태입니다."],"t":"공차 = 허용 범위"},"2022-4-기관3-2":{"w":"6, 12, 4[Ω] 병렬: 1 ÷ (1/6 + 1/12 + 1/4) = 1 ÷ (6/12) = 2[Ω]. 여기에 3[Ω]이 직렬이므로 합성저항은 2 + 3 = 5[Ω]입니다.","x":["틀린 값입니다.","정답. 2 + 3 = 5[Ω]","틀린 값입니다.","모두 더한 값입니다."],"t":"병렬은 역수의 합의 역수"},"2022-4-기관3-4":{"w":"그림은 세 축전지의 (+)끼리, (−)끼리 연결한 병렬 연결입니다. 병렬 연결하면 전압은 그대로 12[V]이고 용량은 더해져 80 × 3 = 240[Ah]가 됩니다.","x":["축전지 1개의 값입니다.","정답. 병렬 = 전압 그대로, 용량 합산","직렬 연결일 때의 값입니다.","전압과 용량을 모두 더한 잘못된 값입니다."],"t":"축전지 직렬 = 전압 합, 병렬 = 용량 합"},"2022-4-기관3-6":{"w":"전기드릴의 접지선을 선체에 연결하면 누전 시 전류가 선체로 흘러 사람이 감전되지 않습니다.","x":["단락 방지가 아닙니다.","정답. 감전 예방","모터 보호가 아닙니다.","발전기 트립과 관계없습니다."],"t":"접지 = 감전 방지"},"2022-4-기관3-7":{"w":"XL = 2πfL = 2π × 60 × 0.005 = 0.6π[Ω]입니다.","x":["단위(mH)를 바꾸지 않은 값입니다.","틀린 값입니다.","틀린 값입니다.","정답. 2π × 60 × 0.005 = 0.6π"],"t":"XL = 2πfL (mH → H)"},"2022-4-기관3-12":{"w":"병렬 운전 중 두 발전기의 기전력 크기가 다르면 두 발전기 사이에 무효 순환전류가 흘러 권선이 과열됩니다.","x":["정답. 무효 순환전류","위상 차이 때의 현상입니다.","유효전력은 거버너가 정합니다.","위상과 관계없습니다."],"t":"전압 차 = 무효 순환전류"},"2022-4-기관3-13":{"w":"전압이 2배면 전류도 2배(I = V/R), 전력은 P = V²/R 이므로 4배가 됩니다.","x":["전력이 틀립니다.","정답. 전류 2배, 전력 4배","틀립니다.","틀립니다."],"t":"P ∝ V²"},"2022-4-기관3-14":{"w":"전기자 전류가 만드는 자속이 주 자극(계자)의 자속에 영향을 주는 현상을 전기자 반작용이라 합니다.","x":["유도 기전력이 아닙니다.","전자력이 아닙니다.","정답. 전기자 반작용","정류 작용이 아닙니다."],"t":"전기자 반작용 = 전기자 자속의 영향"},"2022-4-기관3-18":{"w":"부동 충전법은 충전기가 평소 부하에 전류를 공급하면서 축전지의 자기방전을 보충하고, 정전 시에는 축전지가 자동으로 부하에 전류를 공급하는 방식입니다.","x":["정전류 충전은 일정 전류로 충전하는 방법입니다.","정답. 부동 충전법","급속 충전은 짧은 시간에 큰 전류로 충전합니다.","균등 충전은 셀 사이 전압을 맞추는 충전입니다."],"t":"부동 충전 = 충전기 + 축전지 병렬 상시 연결"},"2022-4-기관3-19":{"w":"N형 반도체는 실리콘에 5가 원소(인, 비소 등)를 넣어 만들며, 이 불순물을 도너(donor)라 합니다. P형은 3가 원소인 억셉터를 넣습니다.","x":["도핑은 불순물을 넣는 과정입니다.","억셉터는 P형을 만드는 불순물입니다.","정공은 P형의 캐리어입니다.","정답. N형 = 도너(5가)"],"t":"N형 = 도너(5가), P형 = 억셉터(3가)"},"2022-4-기관3-20":{"w":"일정한 기준전압을 얻는 데는 제너 다이오드를 씁니다.","x":["해당하지 않습니다.","UJT가 아닙니다.","정답. 제너 다이오드","FET가 아닙니다."],"t":"기준전압 = 제너"},"2022-4-기관3-21":{"w":"두 다이오드가 A, B에서 X 쪽으로 향하고 X가 저항으로 접지된 다이오드 OR 회로입니다. A나 B 중 하나라도 1이면 X가 1이 되므로 ②, ③, ④입니다.","x":["둘 다 0이면 X는 0입니다.","둘 다 0이면 X는 0입니다.","둘 다 0이면 X는 0입니다.","둘 다 0이면 X는 0입니다."],"t":"다이오드 → 출력, 저항 접지 = OR"},"2022-4-기관3-23":{"w":"교류 전력 제어용 양방향 3단자 스위칭 소자는 TRIAC입니다.","x":["FET가 아닙니다.","정답. TRIAC","UJT가 아닙니다.","SSS는 2단자 소자입니다."],"t":"TRIAC = 양방향 3단자"},"2022-4-기관3-24":{"w":"정류된 맥동 전압을 평탄하게 하는 회로는 평활회로이고, 여기에는 전하를 저장·방전하는 콘덴서를 주로 씁니다.","x":["정류회로가 아닙니다.","정류회로·가변저항이 아닙니다.","정답. 평활회로, 콘덴서","가변저항이 아닙니다."],"t":"평활회로 = 콘덴서"},"2022-4-직무일반-1":{"w":"그림은 관을 세 방향으로 나누는 T자 모양 부속품인 티(tee)입니다.","x":["정답. T자 모양 = 티","니플은 짧은 양쪽 수나사 관입니다.","엘보는 방향을 90°·45°로 꺾는 부속품입니다.","플러그는 관 끝을 막는 마개입니다."],"t":"티 = 분기, 엘보 = 방향 전환"},"2022-4-직무일반-2":{"w":"수급 전에는 스커퍼 폐쇄, 신호기(B기)·등화 확인, 오염방제자재와 소화기 비치 등을 준비합니다. 기름기록부는 수급이 끝난 뒤에 작성합니다.","x":["정답(아닌 것). 기름기록부는 수급 후 작성합니다.","스커퍼 폐쇄는 수급 전 확인 사항입니다.","신호기·등화는 수급 전 확인 사항입니다.","방제자재·소화기 비치는 수급 전 준비 사항입니다."],"t":"기름기록부 = 작업 후 기록"},"2022-4-직무일반-4":{"w":"부식으로 얇아진 외판 두께는 한쪽 면에서 초음파를 보내 반사 시간으로 두께를 재는 초음파 두께 측정법으로 잽니다.","x":["정답. 두께 측정 = 초음파","자기탐상은 표면 균열 검사용입니다.","다이체크는 표면 균열 검사용입니다.","침투탐상은 표면 균열 검사용입니다."],"t":"두께 측정 = 초음파"},"2022-4-직무일반-10":{"w":"선박 평형수(ballast water)에는 적재한 해역의 수중 생물이 들어 있어, 다른 해역에서 배출하면 외래종이 퍼져 생태계를 교란합니다. 그래서 평형수 처리장치 설치가 의무화되었습니다.","x":["슬러지는 기름 찌꺼기입니다.","배기가스는 대기오염 원인입니다.","정답. 선박 평형수 → 외래 생물 이동","유성 혼합물은 기름오염 원인입니다."],"t":"평형수 = 외래 생물 이동 문제"},"2022-4-직무일반-11":{"w":"혈액에서 산소를 운반하는 것은 적혈구(헤모글로빈)입니다.","x":["백혈구는 면역을 담당합니다.","정답. 적혈구","혈소판은 혈액 응고를 담당합니다.","감마 글로불린은 항체입니다."],"t":"적혈구 = 산소 운반"},"2022-4-직무일반-12":{"w":"응급처치는 생명을 구하고, 악화를 막고, 고통을 줄이는 것이 목적입니다. 의약품으로 치료 기간을 줄이는 것은 치료의 목적입니다.","x":["목적입니다.","목적입니다.","목적입니다.","정답(아닌 것). 치료가 목적이 아닙니다."],"t":"응급처치 = 생명 구조·악화 방지"},"2022-4-직무일반-16":{"w":"정전 후 예비발전기가 투입되면 Sequential start program(순차 기동 프로그램)이 주요 전동기를 차례로 자동 기동합니다.","x":["정답. 순차 기동","역전력 보호입니다.","우선 차단입니다.","수동 기동입니다."],"t":"sequential start = 순차 자동 기동"},"2022-4-직무일반-17":{"w":"보일러 본체에는 부식, 점식(피팅), 균열, 과열로 인한 변형 등의 손상이 생깁니다. 노킹은 기관의 이상 연소 현상입니다.","x":["피팅(점식)은 보일러 손상입니다.","부식은 보일러 손상입니다.","정답(아닌 것). 노킹은 기관에서 생기는 현상입니다.","균열은 보일러 손상입니다."],"t":"보일러 손상 = 부식·피팅·균열·과열"},"2022-4-직무일반-18":{"w":"열작업 때는 반대편 격실에도 감시원을 두고, 가스 용기를 세우고, 혼자 작업하지 않습니다. 작업 구역은 통풍이 되어야 하므로 개폐구를 모두 닫아 두는 것은 옳지 않습니다.","x":["맞습니다.","맞습니다.","맞습니다.","정답(옳지 않은 것). 통풍을 유지합니다."],"t":"열작업 = 통풍·감시원"},"2022-4-직무일반-21":{"w":"과전류가 흐르면 전선·기기가 과열되어 전기화재의 위험이 가장 큽니다.","x":["정답. 과전류","절연저항이 높으면 안전합니다.","부하용량이 큰 것 자체는 위험이 아닙니다.","정격 이내라면 오래 사용해도 위험하지 않습니다."],"t":"전기화재 1순위 = 과전류"},"2022-4-직무일반-23":{"w":"유조선이 아닌 선박의 기관구역용 폐유저장용기는 총톤수 5~10톤 미만 20[ℓ], 10~30톤 미만 60[ℓ], 30~50톤 미만 100[ℓ], 50~100톤 미만 200[ℓ]입니다.","x":["5톤 이상 10톤 미만 기준입니다.","10톤 이상 30톤 미만 기준입니다.","30톤 이상 50톤 미만 기준입니다.","정답. 50톤 이상 100톤 미만 = 200[ℓ]"],"t":"폐유저장용기 20 → 60 → 100 → 200ℓ"},"2022-4-직무일반-24":{"w":"임시검사는 용도 변경, 길이 변경 등 개조, 무선설비 신설 때 받습니다. 검사증서 유효기간이 끝나면 정기검사를 받습니다.","x":["임시검사 대상입니다.","정답(아닌 것). 정기검사 대상입니다.","임시검사 대상입니다.","임시검사 대상입니다."],"t":"유효기간 만료 = 정기검사"},"2022-4-영어-1":{"w":"\"모든 공기 ( )에 압축공기를 충전했다.\" vessels, tanks, reservoirs는 공기탱크지만 coolers(냉각기)는 알맞지 않습니다.","x":["공기 용기입니다.","정답(적합하지 않은 것). coolers","공기 탱크입니다.","공기 저장조입니다."],"t":"air reservoir = 공기탱크"},"2022-4-영어-2":{"w":"수관(water tubes), 노(furnace), 연소실 청소는 보일러 정비입니다.","x":["정답. Boiler","소각기가 아닙니다.","냉각기가 아닙니다.","응축기가 아닙니다."],"t":"water tube·furnace = 보일러"},"2022-4-영어-4":{"w":"보일러 점화 전에 노 안을 송풍기로 환기하는 것은 Pre-purge(프리퍼지)입니다. 소화 후 환기는 Post-purge입니다.","x":["Post-purge = 소화 후 환기","정답. Pre-purge = 점화 전 환기","Surface blow down = 수면 분출","Bottom blow down = 수저 분출"],"t":"pre = 전, post = 후"},"2022-4-영어-5":{"w":"at once = 즉시 = instantly.","x":["때때로","자주","자주","정답. instantly"],"t":"at once = instantly"},"2022-4-영어-7":{"w":"hydrostatic test = 수압 시험 = water pressure test 입니다.","x":["정답. water pressure test = 수압 시험","humidity test = 습도 시험","tension test = 인장 시험","deformation test = 변형 시험"],"t":"hydrostatic test = 수압 시험"},"2022-4-영어-8":{"w":"응축기 덮개의 아연판(zinc plates)은 해수 부식을 막는 방식(anti-corrosion)용입니다.","x":["정답. anti-corrosion","노킹 방지가 아닙니다.","안정기가 아닙니다.","침식 방지가 아닙니다."],"t":"zinc = 부식 방지"},"2022-4-영어-10":{"w":"\"주 섬프 탱크 바닥의 기름을 퍼내고 내부를 청소했다.\" bail = 퍼내다.","x":["검사했다","교환했다","공급했다","정답. Bailed"],"t":"bail out = 퍼내다"},"2022-4-영어-12":{"w":"\"주기관 시동 실패로 ( )을(를) 점검했다\" — 공기탱크 압력, 시동공기밸브, 시동공기 분배기는 점검 대상이지만 시동공기의 습도는 시동 실패 점검 항목이 아닙니다.","x":["정답(적절하지 않은 것). 습도","점검합니다.","점검합니다.","점검합니다."],"t":"시동 실패 = 공기압·시동밸브·분배기"},"2022-4-영어-14":{"w":"선박의 열교환기는 대부분 뜨거운 액체를 해수나 청수로 식히는 냉각기(cooler)입니다.","x":["냉각되는 쪽의 액체입니다.","공기나 증기가 아닙니다.","정답. sea water or fresh water","기기 이름입니다."],"t":"cooler = 해수·청수로 냉각"},"2022-4-영어-17":{"w":"용액의 염분을 재는 기구는 Salinometer(염분계)입니다.","x":["회전계","습도계","점도계","정답. Salinometer"],"t":"salinometer = 염분계"},"2022-4-영어-18":{"w":"\"호스를 분리해도 됩니까?\" separate = 분리하다.","x":["정답. 분리해도 됩니까?","연결은 connect입니다.","상태를 묻는 문장이 아닙니다.","상태를 묻는 문장이 아닙니다."],"t":"separate = 분리, connect = 연결"},"2022-4-영어-20":{"w":"F.O.T. = Fuel Oil Tank(연료유 탱크)입니다.","x":["맞습니다.","맞습니다.","정답(옳지 않은 것). F.O.T. = Fuel Oil Tank","맞습니다."],"t":"FOT = 연료유 탱크"},"2022-4-영어-24":{"w":"mechanical efficiency = 기계효율입니다.","x":["정답. 기계효율","추진효율","전달효율","지시열효율"],"t":"mechanical efficiency = BHP/IHP"},"2022-4-영어-25":{"w":"선박에서 기름과 오염물질을 분리하는 주 목적의 장치는 기름여과장치(oil filtering equipment)입니다.","x":["청정기는 연료·윤활유 정제용입니다.","소각기가 아닙니다.","빌지펌프가 아닙니다.","정답. oil filtering equipment"],"t":"해양 보호 = 기름여과장치"},"2023-1-기관1-6":{"w":"2행정 기관에서 피스톤이 상사점 부근에 오면 압축이 끝나 연료가 분사됩니다. 배기·소기는 하사점 부근에서 열립니다.","x":["배기는 하사점 부근에서 열립니다.","소기는 하사점 부근에서 열립니다.","안전밸브는 이상 압력일 때만 열립니다.","정답. 상사점 부근 = 연료 분사"],"t":"상사점 부근 = 연료 분사, 하사점 부근 = 소기·배기"},"2023-1-기관1-12":{"w":"안전밸브의 방출능력은 증기 정지밸브를 닫고 최대 연소 상태로 운전해 압력이 일정 한도 이상 오르지 않는지 확인하는 축기시험으로 확인합니다.","x":["정답. 축기시험","압력시험이 아닙니다.","진공시험이 아닙니다.","수압시험은 강도·누설 시험입니다."],"t":"안전밸브 방출능력 = 축기시험"},"2023-1-기관1-15":{"w":"복수기로 배기를 진공(대기압보다 낮은 압력)으로 만들면 터빈 입구와 출구의 압력 차(열낙차)가 커져 증기가 더 많은 일을 하므로 터빈의 효율이 높아집니다.","x":["정답. 열낙차를 크게 해 효율을 높이기 위해","크기를 작게 하려는 목적이 아닙니다.","입구 증기 압력과는 관계없습니다.","입구 증기 속도와는 관계없습니다."],"t":"배기 진공 → 열낙차 증가 → 효율 증가"},"2023-1-기관1-16":{"w":"기름 윤활식 선미관의 선미측 실은 해수 유입과 윤활유 유출을 막고, 선수측(기관실 쪽) 실은 윤활유가 기관실로 새지 않게 막습니다.","x":["해수 유입 방지는 선미측 실의 역할입니다.","공기 누출과 관계없습니다.","정답. 윤활유 누출 방지","오수 유입과 관계없습니다."],"t":"선수측 실 = 윤활유 누출 방지"},"2023-1-기관1-20":{"w":"캐비테이션은 날개 뒷면의 압력이 낮아져 기포가 생겼다가 터지는 현상으로 소음·진동, 날개면 침식, 추력·효율 저하를 일으킵니다. 반류(배 뒤를 따라오는 물의 흐름) 증가와는 관계없습니다.","x":["정답(옳지 않은 것). 반류 증가는 캐비테이션의 영향이 아닙니다.","날개면이 침식됩니다.","기포가 터지며 소음이 납니다.","진동이 생깁니다."],"t":"캐비테이션 = 소음·진동·침식·효율 저하"},"2023-1-기관1-22":{"w":"원심 청정은 기름을 가열해 점도를 낮추고, 유량을 적게 해 기름이 청정기 안에 오래 머물게 하면 분리 효과가 좋아집니다.","x":["점도가 높으면 분리가 나쁩니다.","유량이 많으면 분리가 나쁩니다.","정답. 점도 낮게, 유량 적게","둘 다 반대입니다."],"t":"청정 = 가열(저점도) + 저유량"},"2023-1-기관2-1":{"w":"왕복펌프는 피스톤 왕복 운동 때문에 송출량이 맥동합니다. 송출 쪽에 공기실을 달아 공기의 압축·팽창으로 맥동을 줄입니다.","x":["제트펌프는 공기실이 필요 없습니다.","기어펌프는 맥동이 작습니다.","원심펌프는 맥동이 거의 없습니다.","정답. 왕복펌프 = 공기실"],"t":"공기실 = 왕복펌프 맥동 방지"},"2023-1-기관2-5":{"w":"윈치처럼 저속·고토크가 필요한 곳에는 반지름방향(레이디얼) 피스톤 모터를 많이 씁니다.","x":["기어 모터는 고속·저토크용입니다.","정답. 반지름방향 피스톤 모터","축방향 피스톤 모터는 고속용입니다.","서보 모터는 위치 제어용입니다."],"t":"윈치 = 레이디얼 피스톤 모터(저속 고토크)"},"2023-1-기관2-6":{"w":"유량제어밸브는 흐르는 기름의 양(속도)을 조절하는 밸브로, 교축밸브(스로틀밸브)가 대표적입니다. 감압·릴리프·시퀀스밸브는 압력제어밸브입니다.","x":["감압밸브는 압력제어밸브입니다.","정답. 교축밸브 = 유량제어밸브","릴리프밸브는 압력제어밸브입니다.","시퀀스밸브는 압력제어밸브입니다."],"t":"유량제어 = 교축밸브 / 압력제어 = 릴리프·감압·시퀀스"},"2023-1-기관2-10":{"w":"자동배유장치는 유면검출기가 기름층을 감지하면 전자밸브를 열어 기름을 배출하고, 타이머로 일정 시간 뒤 밸브를 닫습니다. 구성 요소는 타이머, 전자밸브, 유면검출기입니다.","x":["콜레서·포집관은 분리 장치입니다.","콜레서·포집관은 분리 장치입니다.","콜레서·포집관은 분리 장치입니다.","콜레서·포집관은 분리 장치입니다."],"t":"자동배유 = 유면검출기 + 전자밸브 + 타이머"},"2023-1-기관2-20":{"w":"산소-아세틸렌 절단은 강을 산화시켜 태워 자르는 방법으로 연강이 가장 잘 절단됩니다. 스테인리스강·알루미늄·합금강은 산화물이 잘 녹지 않아 어렵습니다.","x":["합금강은 절단이 어렵습니다.","알루미늄은 절단이 어렵습니다.","정답. 연강","스테인리스강은 절단이 어렵습니다."],"t":"가스 절단 = 연강"},"2023-1-기관2-22":{"w":"용골은 배 밑바닥 중심선을 따라 선수재에서 선미재까지 이어진 가장 중요한 종강력재로, 사람의 척추에 해당합니다.","x":["늑골은 갈비뼈처럼 횡으로 선 부재입니다.","정답. 용골","빌지킬은 횡요(롤링)를 줄이는 부재입니다.","격벽은 선내를 나누는 벽입니다."],"t":"용골 = 배의 척추"},"2023-1-기관2-23":{"w":"기속거리(프로펠러 거리)는 피치 × 회전수로 계산하므로 피치를 알아야 합니다.","x":["항주거리는 실제 측정 거리입니다.","연료소비율과 관계없습니다.","축마력과 관계없습니다.","정답. 기속거리 = 피치 × 회전수"],"t":"기속거리 = P × N"},"2023-1-기관2-24":{"w":"한국산업표준(KS) 기계제도는 제3각법을 원칙으로 합니다. 정면도 위에 평면도, 오른쪽에 우측면도를 그립니다.","x":["반투상도법은 표준 투상법이 아닙니다.","제1각법은 일부 국가에서 쓰며 KS 원칙이 아닙니다.","제2각법은 쓰지 않습니다.","정답. KS = 제3각법"],"t":"KS 제도 = 제3각법"},"2023-1-기관2-25":{"w":"도면을 그릴 때는 가장 먼저 중심선을 그려 기준을 잡고, 그다음 외형선, 치수선 순서로 그립니다.","x":["치수선은 외형을 그린 뒤에 그립니다.","정답. 중심선을 가장 먼저","해칭선은 단면을 나타낼 때 나중에 그립니다.","외형선은 중심선 다음에 그립니다."],"t":"제도 순서 = 중심선 → 외형선 → 치수선"},"2023-1-기관3-5":{"w":"RL 직렬회로의 임피던스 Z = √(R² + XL²) = √(30² + 40²) = √2500 = 50[Ω]입니다.","x":["뺀 값입니다.","정답. √(30² + 40²) = 50[Ω]","단순히 더한 값입니다.","틀린 값입니다."],"t":"Z = √(R² + X²) (3:4:5 직각삼각형)"},"2023-1-기관3-7":{"w":"정격전압 100[V]는 실효값이므로 최대값 = 100 × √2 ≒ 141[V]입니다.","x":["평균값에 해당하는 값입니다.","실효값입니다.","정답. 100 × 1.414 ≒ 141[V]","틀린 값입니다."],"t":"최대값 = 실효값 × √2"},"2023-1-기관3-9":{"w":"전류 I = 전하량 Q ÷ 시간 t = 0.3 ÷ 0.5 = 0.6[A]입니다.","x":["틀린 값입니다.","틀린 값입니다.","정답. 0.3[C] ÷ 0.5[s] = 0.6[A]","틀린 값입니다."],"t":"I = Q / t"},"2023-1-기관3-10":{"w":"그림은 세 축전지의 (+)끼리, (−)끼리 연결한 병렬 연결입니다. 병렬 연결하면 전압은 그대로 12[V]이고 용량은 더해져 80 × 3 = 240[Ah]가 됩니다.","x":["축전지 1개의 값입니다.","정답. 병렬 = 전압 그대로, 용량 합산","직렬 연결일 때의 값입니다.","전압과 용량을 모두 더한 잘못된 값입니다."],"t":"축전지 직렬 = 전압 합, 병렬 = 용량 합"},"2023-1-기관3-21":{"w":"정류된 맥동 전압을 평탄하게 하는 회로는 평활회로이고, 여기에는 전하를 저장·방전하는 콘덴서를 주로 씁니다.","x":["정류회로가 아닙니다.","정류회로·가변저항이 아닙니다.","정답. 평활회로, 콘덴서","가변저항이 아닙니다."],"t":"평활회로 = 콘덴서"},"2023-1-기관3-25":{"w":"제너 다이오드는 역방향 전압이 일정 값(제너 전압)에 이르면 전압이 그 값으로 일정하게 유지되는 성질이 있어 정전압 회로에 씁니다.","x":["정답. 정전압 = 제너 다이오드","터널 다이오드는 고속 스위칭·발진용입니다.","배리스터는 과전압 보호용입니다.","서미스터는 온도 감지용입니다."],"t":"제너 다이오드 = 정전압"},"2023-1-직무일반-3":{"w":"부식으로 얇아진 외판 두께는 한쪽 면에서 초음파를 보내 반사 시간으로 두께를 재는 초음파 두께 측정법으로 잽니다.","x":["정답. 두께 측정 = 초음파","자기탐상은 표면 균열 검사용입니다.","다이체크는 표면 균열 검사용입니다.","침투탐상은 표면 균열 검사용입니다."],"t":"두께 측정 = 초음파"},"2023-1-직무일반-7":{"w":"수급 시 갑판 배수구(스커퍼)는 막아 두고, 방제 자재를 가까이 두고, 탱크를 자주 측심해 넘치지 않게 합니다. 맨홀을 열어 두면 안 됩니다.","x":["①은 틀립니다(배수구는 막아야 함).","①은 틀립니다(배수구는 막아야 함).","①은 틀립니다(배수구는 막아야 함).","①은 틀립니다(배수구는 막아야 함)."],"t":"수급 = 스커퍼 막기·방제자재·자주 측심"},"2023-1-직무일반-11":{"w":"의식이 없는 사람에게 음료를 주면 기도로 넘어가 질식할 수 있으므로 절대 주면 안 됩니다.","x":["열사병 환자는 의식이 있으면 수분을 줍니다.","일사병 환자는 수분을 줍니다.","정답. 의식불명자","중독자는 상황에 따라 다릅니다."],"t":"의식 없으면 음료 금지"},"2023-1-직무일반-17":{"w":"보일러 본체에는 부식, 점식(피팅), 균열, 과열로 인한 변형 등의 손상이 생깁니다. 노킹은 기관의 이상 연소 현상입니다.","x":["피팅(점식)은 보일러 손상입니다.","부식은 보일러 손상입니다.","정답(아닌 것). 노킹은 기관에서 생기는 현상입니다.","균열은 보일러 손상입니다."],"t":"보일러 손상 = 부식·피팅·균열·과열"},"2023-1-직무일반-19":{"w":"과전류가 흐르면 전선·기기가 과열되어 전기화재의 위험이 가장 큽니다.","x":["정답. 과전류","절연저항이 높으면 안전합니다.","부하용량이 큰 것 자체는 위험이 아닙니다.","정격 이내라면 오래 사용해도 위험하지 않습니다."],"t":"전기화재 1순위 = 과전류"},"2023-1-직무일반-22":{"w":"선박법은 선박의 국적, 톤수 측정·등록 등을 정해 해사 제도를 적정하게 운영하고 해상 질서를 유지하는 것이 목적입니다. 선내 질서 유지는 선원법의 목적입니다.","x":["정답(아닌 것). 선내 질서는 선원법입니다.","국적은 선박법 사항입니다.","톤수 측정은 선박법 사항입니다.","선박법의 목적입니다."],"t":"선내 질서 = 선원법"},"2023-1-영어-5":{"w":"프로펠러 피치(1회전에 이론상 나아가는 거리)와 배가 실제 나아간 거리의 차이를 슬립(slip)이라 합니다.","x":["rpm = 분당 회전수","sailing mile = 항해 거리","정답. slip = 슬립","engine mile = 기관 거리(프로펠러 기준 거리)"],"t":"피치 − 실제 전진 거리 = slip"},"2023-1-영어-6":{"w":"\"전동기 기동기의 전자 접촉기 불량 접점을 사포(sand paper)로 다듬어라.\" 접점은 고운 사포로 살짝 다듬습니다.","x":["정답. sand paper = 사포","연삭기는 너무 거칩니다.","쇠톱은 자르는 공구입니다.","휴대용 연삭기는 너무 거칩니다."],"t":"접점 손질 = 고운 사포"},"2023-1-영어-9":{"w":"육전 = shore electricity(육상 전원)입니다.","x":["electronics는 전자기기입니다.","틀립니다.","정답. Shore electricity","선내 전원입니다."],"t":"shore power = 육전"},"2023-1-영어-11":{"w":"청정기 그림에서 E는 전동기와 수평축 사이에서 동력을 서서히 전달하는 마찰 클러치(Friction clutch)입니다. 청정기는 기동할 때 마찰 클러치가 미끄러지며 서서히 회전을 올립니다.","x":["스파이럴 기어가 아닙니다.","수직축이 아닙니다.","수평축이 아닙니다.","정답. Friction clutch"],"t":"청정기 기동 = 마찰 클러치로 서서히"},"2023-1-영어-13":{"w":"건조기(drier)는 냉매를 충전할 때 들어올 수 있는 수분을 제거합니다.","x":["정답. drier = 건조기","purger = 불응축가스 배출기","evaporator = 증발기","solenoid valve = 전자밸브"],"t":"drier = 수분 제거"},"2023-1-영어-18":{"w":"reservoirs = 저장 용기, 여기서는 공기탱크(시동 공기 저장조)입니다.","x":["압축기는 compressor입니다.","냉각기는 cooler입니다.","안전밸브는 safety valve입니다.","정답. 공기탱크"],"t":"air reservoir = 공기탱크"},"2023-1-영어-20":{"w":"2행정 사이클은 피스톤 2행정, 즉 크랭크축 1회전(one revolution)에 한 사이클을 마칩니다.","x":["motion = 움직임","정답. revolution = 회전","arrangement = 배치","blowing = 불기"],"t":"2행정 = 1 revolution, 4행정 = 2 revolutions"},"2023-1-영어-22":{"w":"액체에 에너지를 주어 압력을 높이고 이동시키는 장치는 펌프(pump)입니다.","x":["cooler = 냉각기","정답. pump = 펌프","heater = 가열기","condenser = 응축기"],"t":"pump = 액체에 에너지를 주는 장치"},"2023-1-영어-23":{"w":"선교와 기관실 사이에 기관 명령을 주고받는 장치는 기관 텔레그래프(engine telegraph)입니다.","x":["telescope = 망원경","정답. telegraph = 기관 텔레그래프","diaphragm = 격막","tachometer = 회전계"],"t":"engine telegraph = 선교↔기관실 명령 전달"},"2023-2-기관1-7":{"w":"실린더를 너무 냉각하면 불완전 연소, 열효율 저하, 황산 응결로 인한 저온 부식과 라이너 마멸이 생깁니다. 저온 부식의 원인은 질소산화물이 아니라 황산화물(황산)입니다.","x":["과냉하면 불완전 연소가 생깁니다.","과냉하면 열 손실로 열효율이 떨어집니다.","과냉하면 라이너 마멸이 빨라집니다.","정답(아닌 것). 저온 부식은 황 성분(황산) 때문입니다."],"t":"저온 부식 = 황산, 과냉이 원인"},"2023-2-기관1-17":{"w":"축계 진동이 심하면 중간축 베어링 마멸, 프로펠러 날개 손상, 피치 불균일 등을 점검합니다. 날개의 강도 변화는 눈으로 점검할 수 있는 사항이 아닙니다.","x":["점검합니다.","정답(아닌 것). 강도 변화는 점검 사항이 아닙니다.","점검합니다.","점검합니다."],"t":"축계 진동 = 베어링·날개 손상·피치"},"2023-2-기관1-19":{"w":"캐비테이션은 날개 뒷면의 압력이 낮아져 기포가 생겼다가 터지는 현상으로 소음·진동, 날개면 침식, 추력·효율 저하를 일으킵니다. 반류(배 뒤를 따라오는 물의 흐름) 증가와는 관계없습니다.","x":["정답(옳지 않은 것). 반류 증가는 캐비테이션의 영향이 아닙니다.","날개면이 침식됩니다.","기포가 터지며 소음이 납니다.","진동이 생깁니다."],"t":"캐비테이션 = 소음·진동·침식·효율 저하"},"2023-2-기관1-20":{"w":"프로펠러가 1회전할 때 날개 위의 한 점이 축 방향으로 이론상 나아가는 거리를 피치라 합니다.","x":["슬립은 피치와 실제 전진 거리의 차이입니다.","스큐백은 날개가 회전 반대 방향으로 휜 정도입니다.","경사(레이크)는 날개가 뒤로 기운 정도입니다.","정답. 1회전 전진 거리 = 피치"],"t":"피치 = 1회전 이론 전진 거리"},"2023-2-기관1-22":{"w":"유동점은 기름이 흐를 수 있는 가장 낮은 온도입니다. 유동점이 높으면 추울 때 기름이 굳어 잘 흐르지 않습니다.","x":["온도가 오르면 점도는 낮아집니다.","세탄가가 낮으면 착화성이 나빠집니다.","정답. 유동점이 높으면 한랭 시 잘 흐르지 않습니다.","인화점이 낮으면 화재 위험이 높아집니다."],"t":"유동점 높음 = 추울 때 문제"},"2023-2-기관1-23":{"w":"원심 청정은 기름을 가열해 점도를 낮추고, 유량을 적게 해 기름이 청정기 안에 오래 머물게 하면 분리 효과가 좋아집니다.","x":["점도가 높으면 분리가 나쁩니다.","유량이 많으면 분리가 나쁩니다.","정답. 점도 낮게, 유량 적게","둘 다 반대입니다."],"t":"청정 = 가열(저점도) + 저유량"},"2023-2-기관2-1":{"w":"회전속도를 바꿔 유량을 조절하면 밸브로 조이는 것처럼 저항 손실이 없어 효율이 가장 좋고 동력도 절약됩니다(인버터 제어).","x":["밸브 조임은 손실이 생깁니다.","흡입밸브를 조이면 캐비테이션이 생깁니다.","손실이 큽니다.","정답. 회전속도 조절"],"t":"가장 효율적 = 회전수 제어"},"2023-2-기관2-9":{"w":"유면검출기는 분리기 위쪽에 모인 기름층의 두께를 감지해 기름을 배출시킵니다. 감도를 높이면 기름층이 조금만 쌓여도 감지하므로 기름층의 하한 레벨이 높아집니다(얇은 기름층에서도 동작).","x":["상한 레벨이 낮아진다는 설명은 맞지 않습니다.","정답. 감도를 높이면 기름층의 하한 레벨이 높아집니다.","물층의 상한 레벨과는 관계없는 설명입니다.","물층의 하한 레벨과는 관계없는 설명입니다."],"t":"유면검출기 감도↑ → 기름층 하한 레벨↑"},"2023-2-기관2-10":{"w":"침전탱크에 가라앉은 활성슬러지는 공기 상승관(에어리프트)으로 폭기탱크에 되돌려 보내 미생물을 다시 활용합니다.","x":["스키머는 표면 부유물을 걷습니다.","멸균탱크로 보내지 않습니다.","멸균탱크로 보내지 않습니다.","정답. 공기 상승관으로 폭기탱크로 반송"],"t":"활성슬러지 = 폭기탱크로 반송"},"2023-2-기관2-11":{"w":"증발기 제상은 물을 뿌리거나(살수), 전열기로 가열하거나, 압축기의 고온·고압 가스를 보내는(핫가스) 방법 등으로 합니다. 약품 살포는 쓰지 않습니다.","x":["핫가스 제상은 제상 방법입니다.","살수 제상은 제상 방법입니다.","정답(아닌 것). 약품 살포는 쓰지 않습니다.","전열 제상은 제상 방법입니다."],"t":"제상 = 살수·전열·핫가스"},"2023-2-기관2-15":{"w":"실내에서 밖으로 열이 빠져나가는 겨울철 조건이므로 공급 공기를 가열해야 합니다. 가열하면 상대습도가 떨어지므로 가습도 함께 해야 합니다.","x":["냉각·감습은 여름철 조건입니다.","냉각은 맞지 않습니다.","가열은 맞지만 감습은 맞지 않습니다.","정답. 겨울철 = 가열 + 가습"],"t":"여름 = 냉각·감습, 겨울 = 가열·가습"},"2023-2-기관2-16":{"w":"베어링 간극처럼 좁은 틈새는 필러 게이지(틈새게이지)로 잽니다.","x":["정답. 필러 게이지","센터 게이지는 나사 바이트 각도를 봅니다.","피치 게이지는 나사 피치를 잽니다.","곡률 게이지는 반지름을 잽니다."],"t":"틈새 = 필러 게이지"},"2023-2-기관2-20":{"w":"용접부 잔류응력은 풀림(어닐링) 열처리로 제거합니다.","x":["담금질은 경화 처리입니다.","뜨임은 담금질 후 인성을 주는 처리입니다.","불림은 조직을 균일하게 하는 처리입니다.","정답. 풀림 = 잔류응력 제거"],"t":"풀림 = 응력 제거·연화"},"2023-2-기관2-21":{"w":"트림 = 선수 흘수 − 선미 흘수 = 580 − 570 = 10[cm]입니다. 선수 쪽이 더 깊으므로 선수 트림 10[cm]입니다.","x":["값이 틀립니다.","방향과 값이 틀립니다.","정답. 선수가 10[cm] 더 깊음 = 선수 트림 10[cm]","방향이 틀립니다."],"t":"더 깊은 쪽 트림"},"2023-2-기관2-22":{"w":"용골은 배 밑바닥 중심선을 따라 선수재에서 선미재까지 이어진 가장 중요한 종강력재로, 사람의 척추에 해당합니다.","x":["늑골은 갈비뼈처럼 횡으로 선 부재입니다.","정답. 용골","빌지킬은 횡요(롤링)를 줄이는 부재입니다.","격벽은 선내를 나누는 벽입니다."],"t":"용골 = 배의 척추"},"2023-2-기관2-25":{"w":"한국산업표준(KS) 기계제도는 제3각법을 원칙으로 합니다. 정면도 위에 평면도, 오른쪽에 우측면도를 그립니다.","x":["반투상도법은 표준 투상법이 아닙니다.","제1각법은 일부 국가에서 쓰며 KS 원칙이 아닙니다.","제2각법은 쓰지 않습니다.","정답. KS = 제3각법"],"t":"KS 제도 = 제3각법"},"2023-2-기관3-1":{"w":"정격전압 100[V]는 실효값이므로 최대값 = 100 × √2 ≒ 141[V]입니다.","x":["평균값에 해당하는 값입니다.","실효값입니다.","정답. 100 × 1.414 ≒ 141[V]","틀린 값입니다."],"t":"최대값 = 실효값 × √2"},"2023-2-기관3-5":{"w":"전류 I = Q ÷ t = 10 ÷ 2 = 5[A]입니다.","x":["틀린 값입니다.","정답. 10 ÷ 2 = 5[A]","틀린 값입니다.","곱한 값입니다."],"t":"I = Q / t"},"2023-2-기관3-7":{"w":"e = Em sinωt 에서 e는 순시값, Em은 최대값, ω는 각속도(2πf), t는 시간[초]입니다.","x":["e는 순시값입니다.","t의 단위는 [초]입니다.","Em은 최대값입니다.","정답. ω = 각속도"],"t":"e 순시값, Em 최대값, ω = 2πf"},"2023-2-기관3-10":{"w":"전압을 높이려면 직렬로 연결합니다. 24 ÷ 1.2 = 20개를 직렬로 연결합니다.","x":["정답. 20개 직렬","병렬은 전압이 그대로입니다.","12개 직렬은 14.4[V]입니다.","병렬은 전압이 그대로입니다."],"t":"전압↑ = 직렬, 용량↑ = 병렬"},"2023-2-기관3-23":{"w":"제너 현상은 다이오드에 역방향 전압을 걸어 일정 값(제너 전압)에 이르면 갑자기 큰 전류가 흐르는 현상입니다.","x":["순방향이 아닙니다.","순방향이 아닙니다.","정답. 역방향 전압에서 큰 전류","전류가 0이 아닙니다."],"t":"제너 = 역방향 항복"},"2023-2-기관3-24":{"w":"포토 다이오드, 포토 트랜지스터, CdS는 빛을 검출하는 소자입니다. 트라이액은 교류 전력을 제어하는 양방향 스위칭 소자입니다.","x":["빛 검출 소자입니다.","빛 검출 소자입니다.","빛 검출 소자입니다.","정답(아닌 것). 트라이액은 전력 제어 소자입니다."],"t":"트라이액 = 교류 양방향 스위치"},"2023-2-직무일반-8":{"w":"선저의 유성 혼합물은 기름여과장치로 처리해 배출하거나, 저장탱크에 모아 두었다가 육상으로 양륙합니다. 청정기로 처리하지 않습니다.","x":["여과 후 배출합니다.","정답(옳지 않은 것). 청정기로 처리하지 않습니다.","저장합니다.","양륙합니다."],"t":"빌지 = 여과장치·저장·양륙"},"2023-2-직무일반-13":{"w":"들것은 보통 환자의 발 쪽이 앞으로 가게 운반합니다(계단 오를 때는 머리 먼저). 뒤쪽 운반자가 환자 얼굴을 보며 상태를 살필 수 있습니다.","x":["4인 운반이 안전합니다.","부상에 맞는 체위로 운반합니다.","흔들리지 않게 합니다.","정답(옳지 않은 것). 보통 발 쪽이 앞입니다."],"t":"들것 = 발 먼저"},"2023-2-직무일반-15":{"w":"라이너 균열로 피스톤을 둔 채 감통 운전할 때는 연료유, 냉각수, 시동공기를 차단합니다. 피스톤이 계속 움직이므로 실린더유는 계속 공급해 라이너와 링이 긁히지 않게 합니다.","x":["연료유를 차단합니다.","균열로 새므로 냉각수를 차단합니다.","시동공기를 차단합니다.","정답(옳지 않은 것). 실린더유는 공급합니다."],"t":"피스톤 둔 감통 = 실린더유 계속 공급"},"2023-2-직무일반-16":{"w":"정전 후 예비발전기가 투입되면 Sequential start program(순차 기동 프로그램)이 주요 전동기를 차례로 자동 기동합니다.","x":["정답. 순차 기동","역전력 보호입니다.","우선 차단입니다.","수동 기동입니다."],"t":"sequential start = 순차 자동 기동"},"2023-2-직무일반-17":{"w":"기관실 화재 시 비상정지 스위치로 연료유 밸브(급속차단밸브)를 닫고, 연료유 펌프와 통풍 팬을 멈춰 연료와 산소 공급을 끊습니다. 청수펌프는 해당하지 않습니다.","x":["유류밸브를 차단합니다.","통풍 팬을 정지합니다.","유류펌프를 정지합니다.","정답(아닌 것). 청수펌프는 정지 대상이 아닙니다."],"t":"비상정지 = 연료 차단 + 통풍 정지"},"2023-2-직무일반-18":{"w":"선박소방설비기준상 열탐지기 1개가 담당하는 최대 바닥 면적은 37[m²], 연기탐지기는 74[m²]입니다. 탐지기 사이 거리는 열탐지기 9[m], 연기탐지기 11[m] 이내입니다.","x":["정답. 열탐지기 = 37[m²]","틀린 값입니다.","연기탐지기의 담당 면적입니다.","틀린 값입니다."],"t":"열탐지기 37m², 연기탐지기 74m²"},"2023-2-직무일반-20":{"w":"가벼운 기름일수록 인화점이 낮습니다. 경유(약 50~70[℃])가 중유나 윤활유보다 인화점이 낮습니다.","x":["정답. 경유가 가장 낮습니다.","윤활유는 인화점이 높습니다(약 200[℃] 이상).","A 중유는 경유보다 높습니다.","C 중유는 더 높습니다."],"t":"가벼운 기름일수록 인화점 낮음"},"2023-2-직무일반-23":{"w":"유조선이 아닌 선박의 기관구역용 폐유저장용기는 총톤수 5~10톤 미만 20[ℓ], 10~30톤 미만 60[ℓ], 30~50톤 미만 100[ℓ], 50~100톤 미만 200[ℓ]입니다.","x":["5톤 이상 10톤 미만 기준입니다.","10톤 이상 30톤 미만 기준입니다.","30톤 이상 50톤 미만 기준입니다.","정답. 50톤 이상 100톤 미만 = 200[ℓ]"],"t":"폐유저장용기 20 → 60 → 100 → 200ℓ"},"2023-2-직무일반-24":{"w":"4급 기관사는 연근해·평수구역에서 일정 추진력 이하 선박의 기관장이 될 수 있습니다. 무제한수역을 항행하는 추진력 1,500[kW] 이상, 총톤수 500톤 이상 어선의 기관장은 상위 면허가 필요합니다.","x":["승선 가능합니다.","승선 가능합니다.","승선 가능합니다.","정답(승선 불가). 무제한수역 대형 어선"],"t":"4급 기관장 = 제한된 수역·추진력"},"2023-2-영어-1":{"w":"\"시간당 몇 톤으로 펌핑하십니까?\" (수급할 때 송유 속도를 묻는 표현)","x":["펌프 대수를 묻지 않습니다.","총량을 묻지 않습니다.","펌프 용량을 묻는 것이 아닙니다.","정답. 시간당 몇 톤으로 펌핑"],"t":"per hour = 시간당"},"2023-2-영어-15":{"w":"원심펌프에서 모터의 에너지를 받아 유체를 바깥으로 가속시키는 회전 부품은 impeller(임펠러)입니다.","x":["Packing gland = 패킹 글랜드","정답. Impeller = 임펠러","Bearing = 베어링","Mechanical seal = 기계식 실"],"t":"impeller = 회전차"},"2023-2-영어-25":{"w":"보일러 점검표에서 F.O. cut off condition(연료유 차단 상태, 안전장치 작동 시험)은 3개월마다 점검하는 항목입니다. 수위 경보·화염 감지기 등은 더 자주 점검합니다.","x":["원격 수면계는 더 자주 점검합니다.","버너 화염 감지기는 더 자주 점검합니다.","정답. F.O. cut off condition = 3개월","수위 경보는 더 자주 점검합니다."],"t":"F.O. cut off = 연료 차단 시험"},"2023-3-기관1-3":{"w":"직접분사식은 연소실 표면적이 작아 열손실이 적고 압축 온도가 높아 시동이 가장 쉽습니다.","x":["예연소실식은 예열 플러그가 필요합니다.","와류실식은 예열 플러그가 필요합니다.","정답. 직접분사식","공기실식은 시동이 어렵습니다."],"t":"시동 쉬움 = 직접분사식"},"2023-3-기관1-9":{"w":"보슈식 펌프에서 플런저의 경사홈이 배럴의 흡입구멍과 일치하면 고압 연료가 흡입구로 빠져나가 분사가 끝납니다.","x":["정답. 경사홈 일치 = 분사끝","상사점과 관계없습니다.","하사점과 관계없습니다.","분사시작은 플런저 윗면이 구멍을 막을 때입니다."],"t":"경사홈 = 분사끝(분사량 조정)"},"2023-3-기관1-10":{"w":"유압조속기의 보상 니들밸브를 너무 많이 열면 보상이 너무 빨라져 회전속도가 오르내리는 헌팅(난조)이 생깁니다.","x":["정답. 헌팅","과속이 유지되지 않습니다.","반대로 불안정해집니다.","정지하지 않습니다."],"t":"니들밸브 과다 개방 = 헌팅"},"2023-3-기관1-12":{"w":"Superheater(과열기)는 포화증기를 더 가열해 과열증기로 만듭니다.","x":["정답. Superheater = 과열기","Economizer = 절탄기(급수 예열)","Desuperheater = 과열 저감기","Regenerator = 재생기"],"t":"superheater = 과열기"},"2023-3-기관1-17":{"w":"선미관은 프로펠러축이 선체를 관통하는 곳에 있어 해수 침입을 막고 축을 받치는 베어링 역할을 합니다.","x":["중간축 베어링은 선내에 있습니다.","정답. 선미관","러더 핀틀 부시는 타의 베어링입니다.","추력 베어링은 추력을 전달합니다."],"t":"선미관 = 해수 차단 + 축 받침"},"2023-3-기관1-23":{"w":"윤활유가 고온의 실린더 벽이나 피스톤에 닿으면 열분해되어 탄화물(카본)이 생깁니다. 이 카본이 쌓이면 실린더 마멸과 피스톤링 고착의 원인이 됩니다.","x":["산소와 접촉하면 산화(슬러지)가 생깁니다.","새 윤활유 혼합은 탄화물의 원인이 아닙니다.","정답. 고온 → 열분해 → 탄화물","금속 가루·수분은 오염·유화의 원인입니다."],"t":"윤활유 탄화물 = 고온 열분해"},"2023-3-기관1-25":{"w":"점도지수는 온도가 변할 때 점도가 얼마나 변하는지를 나타내는 값입니다. 점도지수가 클수록 온도에 따른 점도 변화가 작습니다.","x":["애닐린지수는 착화성 관련 지수입니다.","정답. 점도지수","API지수는 비중을 나타냅니다.","점도계수가 아닙니다."],"t":"점도지수 = 온도에 따른 점도 변화"},"2023-3-기관2-3":{"w":"왕복펌프는 흡입 성능이 좋고 고압을 낼 수 있지만, 같은 유량이면 원심펌프보다 크고, 왕복 운동 때문에 고속 운전이 어렵습니다.","x":["정답(옳지 않은 것). 고속 운전이 어렵습니다.","흡입 성능이 좋습니다.","공기실로 맥동을 줄입니다.","크기가 큽니다."],"t":"왕복펌프 = 저속·고압·흡입 양호"},"2023-3-기관2-5":{"w":"콜레서 분리법은 콜레서 필터로 작은 기름방울을 서로 응집시켜 큰 방울로 만들어 분리합니다.","x":["평행판 분리법은 판 사이 흐름으로 분리합니다.","중력 분리법은 비중 차로 분리합니다.","원심 분리법은 원심력으로 분리합니다.","정답. 응집 = 콜레서"],"t":"응집(합체) = 콜레서"},"2023-3-기관2-7":{"w":"점도가 높은 폐유를 일정하게 보내는 데는 기어 펌프를 많이 씁니다.","x":["제트 펌프가 아닙니다.","정답. 기어 펌프","터빈 펌프가 아닙니다.","피스톤 펌프가 아닙니다."],"t":"폐유 = 기어 펌프"},"2023-3-기관2-8":{"w":"생물화학적 오수처리장치는 폭기탱크(미생물 분해) → 침전탱크 → 멸균탱크(소독)로 구성됩니다. 팽창탱크는 냉각수 계통의 탱크입니다.","x":["멸균탱크는 구성 탱크입니다.","침전탱크는 구성 탱크입니다.","폭기탱크는 구성 탱크입니다.","정답(아닌 것). 팽창탱크는 냉각수 계통입니다."],"t":"오수처리 = 폭기 → 침전 → 멸균"},"2023-3-기관2-9":{"w":"유면검출기는 분리기 위쪽에 모인 기름층의 두께를 감지해 기름을 배출시킵니다. 감도를 높이면 기름층이 조금만 쌓여도 감지하므로 기름층의 하한 레벨이 높아집니다(얇은 기름층에서도 동작).","x":["상한 레벨이 낮아진다는 설명은 맞지 않습니다.","정답. 감도를 높이면 기름층의 하한 레벨이 높아집니다.","물층의 상한 레벨과는 관계없는 설명입니다.","물층의 하한 레벨과는 관계없는 설명입니다."],"t":"유면검출기 감도↑ → 기름층 하한 레벨↑"},"2023-3-기관2-12":{"w":"프레온 누설은 비눗물, 핼라이드 토치(불꽃 색 변화), 할로겐 누설검지기로 찾습니다. 유황을 태워 흰 연기로 찾는 방법은 암모니아 누설 검지법입니다.","x":["정답(옳지 않은 것). 유황 초는 암모니아용입니다.","핼라이드 토치는 프레온용입니다.","비눗물은 공통으로 씁니다.","할로겐 검지기는 프레온용입니다."],"t":"프레온 = 핼라이드 토치, 암모니아 = 유황"},"2023-3-기관2-15":{"w":"감습(제습) 방법은 냉각식, 흡착식(실리카겔), 흡수식(염화리튬) 등입니다. 증기 분사는 가습 방법입니다.","x":["냉각식은 감습입니다.","정답(아닌 것). 증기 분사는 가습입니다.","흡착식은 감습입니다.","흡수식은 감습입니다."],"t":"증기 분사 = 가습"},"2023-3-기관2-22":{"w":"이중저는 선저를 이중으로 만든 구조로 연료유·밸러스트수·청수를 저장하고, 좌초 시 침수를 막으며, 종강도를 보강합니다. 화물은 이중저에 싣지 않습니다.","x":["연료유를 저장합니다.","정답(옳지 않은 것). 이중저에는 화물을 싣지 않습니다.","좌초 시 방수 역할을 합니다.","종강도를 보강합니다."],"t":"이중저 = 연료·밸러스트·청수 탱크"},"2023-3-기관3-3":{"w":"저항만 있는 회로에서는 전압과 전류의 위상이 같습니다.","x":["정답. 저항성 회로","유도성은 전류가 늦습니다.","용량성은 전류가 빠릅니다.","RL은 전류가 늦습니다."],"t":"R = 위상 같음"},"2023-3-기관3-4":{"w":"키르히호프의 제1법칙(전류 법칙)은 한 점으로 들어오고 나가는 전류의 대수합이 0이라는 법칙입니다.","x":["앙페르의 법칙은 전류와 자기장의 방향입니다.","쿨롱의 법칙은 전하 사이의 힘입니다.","정답. 키르히호프의 법칙","패러데이의 법칙은 전자유도입니다."],"t":"키르히호프 1법칙 = 전류, 2법칙 = 전압"},"2023-3-기관3-5":{"w":"전류 I = Q ÷ t = 10 ÷ 2 = 5[A]입니다.","x":["틀린 값입니다.","정답. 10 ÷ 2 = 5[A]","틀린 값입니다.","곱한 값입니다."],"t":"I = Q / t"},"2023-3-기관3-7":{"w":"AC 100[V]처럼 표시된 사용전압은 실효값입니다.","x":["순시값이 아닙니다.","최대값이 아닙니다.","정답. 실효값","평균값이 아닙니다."],"t":"표시 전압 = 실효값"},"2023-3-기관3-15":{"w":"P = 120f ÷ N = 120 × 60 ÷ 720 = 10극입니다.","x":["틀린 값입니다.","틀린 값입니다.","정답. 7,200 ÷ 720 = 10극","틀린 값입니다."],"t":"P = 120f / N"},"2023-3-기관3-18":{"w":"e = Em sinωt 에서 e는 순시값, Em은 최대값, ω는 각속도(2πf), t는 시간[초]입니다.","x":["e는 순시값입니다.","t의 단위는 [초]입니다.","Em은 최대값입니다.","정답. ω = 각속도"],"t":"e 순시값, Em 최대값, ω = 2πf"},"2023-3-기관3-21":{"w":"보일러 화염검출기(flame eye)에는 빛을 받으면 저항이 줄어드는 CdS(황화카드뮴) 셀을 널리 씁니다.","x":["정답. CdS","광전지는 전압을 만드는 소자입니다.","SSS는 해당하지 않습니다.","MOSFET는 전력 스위칭 소자입니다."],"t":"화염검출 = CdS"},"2023-3-기관3-23":{"w":"서미스터는 온도에 따라 저항이 크게 변해 온도 검출에 씁니다.","x":["사이리스터는 전력 스위칭 소자입니다.","정답. 서미스터","배리스터는 전압에 따라 저항이 변합니다.","포토 트랜지스터는 빛을 검출합니다."],"t":"온도 = 서미스터"},"2023-3-기관3-25":{"w":"다이오드 기호에 게이트 단자가 붙은 것은 SCR(실리콘 제어 정류기)입니다.","x":["정답. SCR","UJT는 이미터 화살표가 있는 기호입니다.","TR은 베이스·컬렉터·이미터 기호입니다.","다이오드에는 게이트가 없습니다."],"t":"SCR = 다이오드 + 게이트"},"2023-3-직무일반-5":{"w":"연료유를 수급할 때 탱크를 바꾸려면 다음 탱크의 밸브를 먼저 연 뒤에 가득 찬 탱크의 밸브를 닫아야 합니다. 먼저 닫으면 관 속 압력이 급상승해 호스·관이 터지거나 기름이 넘칠 수 있습니다.","x":["스커퍼를 막아 기름이 바다로 흘러가는 것을 막아야 합니다.","측심을 자주 해 넘치지 않게 해야 합니다.","경사·트림에 주의해야 합니다.","정답(아닌 것). 다음 탱크 밸브를 먼저 열고 앞 탱크를 닫습니다."],"t":"탱크 전환 = 다음 탱크 열고 → 앞 탱크 닫기"},"2023-3-직무일반-6":{"w":"선박에서 나오는 대기오염물질은 황산화물, 질소산화물, 오존층 파괴물질, 휘발성 유기화합물 등입니다. 유기주석 화합물은 선체 도료(방오도료)의 유해물질로 해양오염물질입니다.","x":["황산화물은 대기오염물질입니다.","오존층 파괴물질은 대기오염물질입니다.","질소산화물은 대기오염물질입니다.","정답(아닌 것). 유기주석은 방오도료 물질입니다."],"t":"유기주석(TBT) = 방오도료"},"2023-3-직무일반-11":{"w":"탈구는 강한 외력으로 관절을 이루는 뼈 끝이 관절에서 빠져나온 상태입니다.","x":["자상은 찔린 상처입니다.","골절은 뼈가 부러진 상태입니다.","정답. 관절에서 뼈가 빠짐 = 탈구","절상은 베인 상처입니다."],"t":"탈구 = 관절이 빠짐"},"2023-3-직무일반-15":{"w":"정전 후 예비발전기가 투입되면 Sequential start program(순차 기동 프로그램)이 주요 전동기를 차례로 자동 기동합니다.","x":["정답. 순차 기동","역전력 보호입니다.","우선 차단입니다.","수동 기동입니다."],"t":"sequential start = 순차 자동 기동"},"2023-3-직무일반-19":{"w":"과전류가 흐르면 전선·기기가 과열되어 전기화재의 위험이 가장 큽니다.","x":["정답. 과전류","절연저항이 높으면 안전합니다.","부하용량이 큰 것 자체는 위험이 아닙니다.","정격 이내라면 오래 사용해도 위험하지 않습니다."],"t":"전기화재 1순위 = 과전류"},"2023-3-직무일반-25":{"w":"유조선이 아닌 선박의 기관구역용 폐유저장용기는 총톤수 5~10톤 미만 20[ℓ], 10~30톤 미만 60[ℓ], 30~50톤 미만 100[ℓ], 50~100톤 미만 200[ℓ]입니다.","x":["5톤 이상 10톤 미만 기준입니다.","10톤 이상 30톤 미만 기준입니다.","30톤 이상 50톤 미만 기준입니다.","정답. 50톤 이상 100톤 미만 = 200[ℓ]"],"t":"폐유저장용기 20 → 60 → 100 → 200ℓ"},"2023-3-영어-4":{"w":"\"모든 흡기밸브를 ( )할 것\" — lapped(래핑), examined(검사), renewed(교체)는 밸브 작업으로 알맞지만 charged(충전)는 맞지 않습니다.","x":["lapped = 갈아 맞춤(래핑)","examined = 검사","정답(적절하지 않은 것). charged = 충전","renewed = 교체"],"t":"lap = 밸브 맞춤 연마"},"2023-3-영어-10":{"w":"\"피스톤링, 링 홈, 실린더 톱 클리어런스를 측정할 것.\" measure = 측정하다.","x":["충전","교체","정답. measured","다시 채움"],"t":"to be measured = 측정할 것"},"2023-3-영어-17":{"w":"\"디젤기관 내부에는 버너가 없다.\" 디젤기관은 압축열로 착화하며, 버너는 보일러에 있습니다.","x":["피스톤은 있습니다.","정답. burner는 보일러 장치","실린더는 있습니다.","크랭크축은 있습니다."],"t":"burner = 보일러"},"2023-3-영어-18":{"w":"공기를 압축하면 온도가 올라갑니다. 디젤기관은 이 압축열로 연료를 착화합니다.","x":["부피는 줄어듭니다.","정답. 압축하면 temperature(온도) 상승","viscosity = 점도","area = 면적"],"t":"압축 → 온도 상승(디젤 착화 원리)"},"2023-3-영어-19":{"w":"증기를 만드는 큰 강철 용기는 boiler입니다.","x":["steam turbine = 증기터빈","air vessel = 공기탱크","정답. boiler = 보일러","calorifier = 온수기"],"t":"boiler = 증기 발생"},"2023-3-영어-20":{"w":"닻을 다루는 일반적인 장치는 windlass(양묘기)입니다.","x":["정답. windlass = 양묘기","mooring winch = 계선 윈치","jib crane = 지브 크레인","capstan = 캡스턴"],"t":"windlass = anchor handling"},"2023-3-영어-23":{"w":"\"연료유는 청정된 뒤 서비스(service) 탱크에 저장된다.\"","x":["슬러지 탱크","정답. service tank","저장 탱크는 청정 전입니다.","넘침 탱크"],"t":"청정 후 = service tank"},"2023-3-영어-24":{"w":"피스톤과 실린더 라이너 사이의 틈을 가스가 새지 않게 막는 것은 피스톤링(piston ring)입니다.","x":["propeller = 프로펠러","정답. piston ring = 피스톤링","piston skirt = 피스톤 스커트(측압을 받는 부분)","scavenge port = 소기공"],"t":"piston ring = gas tight sealing"},"2023-3-영어-25":{"w":"\"선박의 대부분의 냉각기(coolers)는 뜨거운 유체의 열을 해수나 청수로 옮긴다.\"","x":["정답. coolers","보일러가 아닙니다.","연료 탱크가 아닙니다.","가열기가 아닙니다."],"t":"cooler = 냉각기"},"2023-4-기관1-3":{"w":"압축비 = (행정부피 + 압축부피) ÷ 압축부피 = (1,900 + 100) ÷ 100 = 20입니다. 회전수는 계산에 필요 없습니다.","x":["틀린 값입니다.","틀린 값입니다.","행정부피 ÷ 압축부피만 한 값입니다.","정답. 2,000 ÷ 100 = 20"],"t":"압축비 = (Vs + Vc) / Vc"},"2023-4-기관1-4":{"w":"메인 베어링은 과부하, 윤활유 부족, 크랭크축 중심선 어긋남, 베어링 틈새 부적당 등으로 발열합니다. 점도지수가 큰 윤활유는 온도가 변해도 점도 변화가 작은 좋은 윤활유입니다.","x":["과부하는 발열 원인입니다.","중심선 어긋남은 편하중으로 발열 원인입니다.","윤활유 부족은 발열 원인입니다.","정답(아닌 것). 점도지수가 큰 윤활유는 좋은 윤활유입니다."],"t":"점도지수 큼 = 온도에 따른 점도 변화 작음(좋음)"},"2023-4-기관1-8":{"w":"피스톤링용 주철 속의 흑연은 스스로 윤활 작용을 하고 윤활유를 머금어 유막을 유지하게 합니다.","x":["철은 기본 성분입니다.","정답. 흑연 = 자기 윤활","니켈은 강도·내식성을 높입니다.","크롬은 내마모성을 높입니다."],"t":"주철 속 흑연 = 윤활 보조"},"2023-4-기관1-12":{"w":"캐리오버는 발생 증기와 함께 보일러 물(물방울, 불순물)이 밖으로 딸려 나가는 현상입니다. 포밍, 프라이밍이 원인입니다.","x":["정상적인 증기 공급입니다.","정답. 보일러수가 증기와 함께 반출","응축 현상입니다.","수면계 착오입니다."],"t":"캐리오버 = 증기에 물이 섞여 나감"},"2023-4-기관1-23":{"w":"탄소가 공기 부족으로 불완전 연소하면 일산화탄소(CO)가 생깁니다. 완전 연소하면 이산화탄소(CO₂)가 됩니다.","x":["완전 연소의 생성물입니다.","정답. 불완전 연소 = CO","수소가 연소한 것입니다.","황이 연소한 것입니다."],"t":"C 불완전 연소 = CO"},"2023-4-기관1-25":{"w":"윤활유 압력이 떨어지는 원인은 여과기 막힘(펌프 흡입측), 베어링 간극 과대, 펌프 공기 흡입, 온도 상승으로 인한 점도 저하 등입니다. 온도가 낮아 점도가 올라가면 압력은 오히려 올라갑니다.","x":["원인입니다.","원인입니다.","원인입니다.","정답(아닌 것). 점도가 오르면 압력은 올라갑니다."],"t":"윤활유 압력↓ = 간극↑·공기·점도↓"},"2023-4-기관2-3":{"w":"왕복펌프는 송출량은 적지만 높은 압력을 낼 수 있어, 적은 양을 높은 압력으로 보낼 때 씁니다.","x":["많은 양은 원심펌프가 적합합니다.","정답. 소유량 고압","대유량 저압은 축류펌프입니다.","적합하지 않습니다."],"t":"왕복펌프 = 소유량·고압"},"2023-4-기관2-11":{"w":"증발기 제상은 물을 뿌리거나(살수), 전열기로 가열하거나, 압축기의 고온·고압 가스를 보내는(핫가스) 방법 등으로 합니다. 약품 살포는 쓰지 않습니다.","x":["핫가스 제상은 제상 방법입니다.","살수 제상은 제상 방법입니다.","정답(아닌 것). 약품 살포는 쓰지 않습니다.","전열 제상은 제상 방법입니다."],"t":"제상 = 살수·전열·핫가스"},"2023-4-기관2-13":{"w":"냉동장치는 증발기에서 냉매가 증발할 때 주위의 열(증발열, 잠열)을 흡수합니다.","x":["정답. 증발열","승화열이 아닙니다.","응고열이 아닙니다.","현열이 아닙니다."],"t":"냉동 = 증발잠열"},"2023-4-기관2-14":{"w":"액분리기는 증발기 출구 냉매 가스 속의 냉매액을 분리해 압축기로 액이 들어가지 않게 하고 분리한 액을 증발기 쪽으로 되돌립니다.","x":["수액기는 액 냉매를 저장합니다.","유분리기는 윤활유를 분리합니다.","정답. 액분리기","팽창밸브는 냉매량을 조절합니다."],"t":"액분리기 = 액 냉매 분리"},"2023-4-기관2-15":{"w":"실내에서 밖으로 열이 빠져나가는 겨울철 조건이므로 공급 공기를 가열해야 합니다. 가열하면 상대습도가 떨어지므로 가습도 함께 해야 합니다.","x":["냉각·감습은 여름철 조건입니다.","냉각은 맞지 않습니다.","가열은 맞지만 감습은 맞지 않습니다.","정답. 겨울철 = 가열 + 가습"],"t":"여름 = 냉각·감습, 겨울 = 가열·가습"},"2023-4-기관2-18":{"w":"외력에 대항해 재료 내부에 생기는 단위 면적당 저항력을 응력이라 합니다.","x":["정답. 응력","변형률은 늘어난 비율입니다.","하중은 외력입니다.","경도는 단단한 정도입니다."],"t":"응력 = 힘 / 면적"},"2023-4-기관2-19":{"w":"피복제는 아크를 안정시키고, 용융속도를 조절하며, 슬랙으로 용착금속을 보호해 강도를 유지하게 합니다. 전류를 억제하는 역할은 없습니다.","x":["아크를 안정시킵니다.","용융속도를 조절합니다.","용착금속을 보호합니다.","정답(아닌 것). 전류 억제는 피복제 역할이 아닙니다."],"t":"피복제 = 아크 안정·보호·용융 조절"},"2023-4-기관2-20":{"w":"움직이지 않는 두 면(플랜지 등) 사이의 누설은 개스킷으로 막습니다. 움직이는 축에는 패킹을 씁니다.","x":["글랜드 패킹은 움직이는 축에 씁니다.","펠트 링은 축 먼지 막이입니다.","정답. 개스킷 = 고정면 밀봉","래버린스 패킹은 회전축에 씁니다."],"t":"고정면 = 개스킷, 운동면 = 패킹"},"2023-4-기관2-21":{"w":"수밀격벽은 침수 범위를 한정하고 방화벽 역할을 하며, 기관실 앞·뒤는 수밀격벽으로 합니다. 주로 수직 횡격벽으로 설치해 횡강도를 형성합니다.","x":["침수를 한정합니다.","방화벽 역할도 합니다.","기관실 전후는 수밀격벽입니다.","정답(옳지 않은 것). 주로 수직 횡격벽입니다."],"t":"수밀격벽 = 수직 횡격벽"},"2023-4-기관2-22":{"w":"용골은 배 밑바닥 중심선을 따라 선수재에서 선미재까지 이어진 가장 중요한 종강력재로, 사람의 척추에 해당합니다.","x":["늑골은 갈비뼈처럼 횡으로 선 부재입니다.","정답. 용골","빌지킬은 횡요(롤링)를 줄이는 부재입니다.","격벽은 선내를 나누는 벽입니다."],"t":"용골 = 배의 척추"},"2023-4-기관2-23":{"w":"전진할 때 프로펠러 날개가 먼저 물을 가르는 쪽 모서리를 앞날(리딩 엣지)이라 합니다.","x":["뒷날은 반대쪽 모서리입니다.","정답. 앞날","틀린 용어입니다.","틀린 용어입니다."],"t":"앞날 = 먼저 물을 끊는 쪽"},"2023-4-기관3-3":{"w":"주파수 f = 1 ÷ 주기 = 1 ÷ 0.2 = 5[Hz]입니다.","x":["틀립니다.","정답. 1 ÷ 0.2 = 5[Hz]","틀립니다.","틀립니다."],"t":"f = 1 / T"},"2023-4-기관3-8":{"w":"콘덴서의 정전용량 단위는 패럿[F]입니다. 보통 [μF], [pF] 단위로 씁니다.","x":["헨리는 인덕턴스 단위입니다.","정답. 패럿[F]","쿨롱은 전하량 단위입니다.","볼트는 전압 단위입니다."],"t":"C[F], L[H], Q[C]"},"2023-4-기관3-19":{"w":"정류 출력을 평활하게 하려면 출력단에 콘덴서를 병렬로 연결합니다(코일은 직렬).","x":["콘덴서는 병렬입니다.","정답. 콘덴서 병렬","부하저항을 작게 하면 맥동이 커집니다.","코일은 직렬로 넣습니다."],"t":"평활 = C 병렬, L 직렬"},"2023-4-기관3-20":{"w":"두 다이오드가 A, B에서 X 쪽으로 향하고 X가 저항으로 접지된 다이오드 OR 회로입니다. A나 B 중 하나라도 1이면 X가 1이 되므로 ②, ③, ④입니다.","x":["둘 다 0이면 X는 0입니다.","둘 다 0이면 X는 0입니다.","둘 다 0이면 X는 0입니다.","둘 다 0이면 X는 0입니다."],"t":"다이오드 → 출력, 저항 접지 = OR"},"2023-4-기관3-22":{"w":"N형 반도체는 실리콘에 5가 원소(인, 비소 등)를 넣어 만들며, 이 불순물을 도너(donor)라 합니다. P형은 3가 원소인 억셉터를 넣습니다.","x":["도핑은 불순물을 넣는 과정입니다.","억셉터는 P형을 만드는 불순물입니다.","정공은 P형의 캐리어입니다.","정답. N형 = 도너(5가)"],"t":"N형 = 도너(5가), P형 = 억셉터(3가)"},"2023-4-기관3-25":{"w":"다이오드 기호에 게이트 단자가 붙은 것은 SCR(실리콘 제어 정류기)입니다.","x":["정답. SCR","UJT는 이미터 화살표가 있는 기호입니다.","TR은 베이스·컬렉터·이미터 기호입니다.","다이오드에는 게이트가 없습니다."],"t":"SCR = 다이오드 + 게이트"},"2023-4-직무일반-2":{"w":"부식으로 얇아진 외판 두께는 한쪽 면에서 초음파를 보내 반사 시간으로 두께를 재는 초음파 두께 측정법으로 잽니다.","x":["정답. 두께 측정 = 초음파","자기탐상은 표면 균열 검사용입니다.","다이체크는 표면 균열 검사용입니다.","침투탐상은 표면 균열 검사용입니다."],"t":"두께 측정 = 초음파"},"2023-4-직무일반-3":{"w":"위험 방지를 위해 발전기 시동 시 터닝 바 위치, 밀폐 탱크 환기, 전기작업 시 차단기 차단을 확인합니다. 보일러 작업 시 안전밸브 조정 압력 확인은 위험 방지 수칙이 아닙니다.","x":["확인합니다.","정답(옳지 않은 것). 위험 방지 수칙이 아닙니다.","확인합니다.","확인합니다."],"t":"위험작업 = 터닝바·환기·전원 차단"},"2023-4-직무일반-5":{"w":"그림은 둥근 눈금판과 바늘로 작은 변위를 읽는 다이얼게이지입니다. 축의 흔들림(휨)·크랭크암 개폐량 등을 잽니다.","x":["틈새게이지는 얇은 판 묶음입니다.","온도게이지가 아닙니다.","정답. 다이얼게이지","한계게이지는 통과·정지 게이지입니다."],"t":"다이얼게이지 = 작은 변위 측정"},"2023-4-직무일반-7":{"w":"선박에서 나오는 대기오염물질은 황산화물, 질소산화물, 오존층 파괴물질, 휘발성 유기화합물 등입니다. 유기주석 화합물은 선체 도료(방오도료)의 유해물질로 해양오염물질입니다.","x":["황산화물은 대기오염물질입니다.","오존층 파괴물질은 대기오염물질입니다.","질소산화물은 대기오염물질입니다.","정답(아닌 것). 유기주석은 방오도료 물질입니다."],"t":"유기주석(TBT) = 방오도료"},"2023-4-직무일반-9":{"w":"기관구역 기름기록부의 슬러지는 청정기 슬러지, 자동 여과기 드레인, 세틀링 탱크 드레인 등 기름 찌꺼기입니다. 보일러 급수탱크 드레인은 물이므로 슬러지가 아닙니다.","x":["정답(아닌 것). 급수탱크 드레인은 물입니다.","슬러지입니다.","슬러지입니다.","슬러지입니다."],"t":"슬러지 = 기름 찌꺼기"},"2023-4-직무일반-10":{"w":"연료 수급 전에는 갑판 배수구를 막아야 기름이 바다로 흐르지 않습니다.","x":["통신 수단을 점검합니다.","자주 측심합니다.","정답(옳지 않은 것). 배수구는 막습니다.","방제 자재를 비치합니다."],"t":"수급 = 스커퍼 폐쇄"},"2023-4-직무일반-15":{"w":"보일러 본체에는 부식, 점식(피팅), 균열, 과열로 인한 변형 등의 손상이 생깁니다. 노킹은 기관의 이상 연소 현상입니다.","x":["피팅(점식)은 보일러 손상입니다.","부식은 보일러 손상입니다.","정답(아닌 것). 노킹은 기관에서 생기는 현상입니다.","균열은 보일러 손상입니다."],"t":"보일러 손상 = 부식·피팅·균열·과열"},"2023-4-직무일반-18":{"w":"연기식 탐지기는 광전자식, 이온화식, 안개실식 등입니다. 차동식은 온도 상승률로 작동하는 열식 탐지기입니다.","x":["정답(아닌 것). 차동식은 열식","연기식입니다.","연기식입니다.","연기식입니다."],"t":"차동식 = 열식"},"2023-4-직무일반-19":{"w":"과전류가 흐르면 전선·기기가 과열되어 전기화재의 위험이 가장 큽니다.","x":["정답. 과전류","절연저항이 높으면 안전합니다.","부하용량이 큰 것 자체는 위험이 아닙니다.","정격 이내라면 오래 사용해도 위험하지 않습니다."],"t":"전기화재 1순위 = 과전류"},"2023-4-직무일반-24":{"w":"4급 기관사는 연근해·평수구역에서 일정 추진력 이하 선박의 기관장이 될 수 있습니다. 무제한수역을 항행하는 추진력 1,500[kW] 이상, 총톤수 500톤 이상 어선의 기관장은 상위 면허가 필요합니다.","x":["승선 가능합니다.","승선 가능합니다.","승선 가능합니다.","정답(승선 불가). 무제한수역 대형 어선"],"t":"4급 기관장 = 제한된 수역·추진력"},"2023-4-영어-1":{"w":"아연판(zinc plate)은 해수가 흐르는 냉각기의 전식 방지용으로 붙입니다. \"주기관 윤활유 냉각기의 아연판 4개를 교체했다.\"","x":["크랭크케이스에는 아연판을 붙이지 않습니다.","정답. M/E L.O. cooler(해수 냉각)","공기탱크에는 아연판이 없습니다.","연료유 가열기에는 아연판이 없습니다."],"t":"zinc plate = 해수 냉각기 부식 방지"},"2023-4-영어-7":{"w":"보일러 점화 전에 노 안을 송풍기로 환기하는 것은 Pre-purge(프리퍼지)입니다. 소화 후 환기는 Post-purge입니다.","x":["Post-purge = 소화 후 환기","Surface blow down = 수면 분출","정답. Pre-purge = 점화 전 환기","Bottom blow down = 수저 분출"],"t":"pre = 전, post = 후"},"2023-4-영어-8":{"w":"\"호스를 분리해도 됩니까?\" separate = 분리하다.","x":["정답. 분리해도 됩니까?","연결은 connect입니다.","상태를 묻는 문장이 아닙니다.","상태를 묻는 문장이 아닙니다."],"t":"separate = 분리, connect = 연결"},"2023-4-영어-9":{"w":"transfer pump = 이송 펌프. Lubricating oil transfer pump = 윤활유 이송펌프.","x":["공급펌프는 supply pump입니다.","순환펌프는 circulating pump입니다.","청정펌프가 아닙니다.","정답. 윤활유 이송펌프"],"t":"transfer = 이송"},"2023-4-영어-10":{"w":"ETA = Estimated Time of Arrival = 도착 예정 시각입니다. 출항 예정 시각은 ETD입니다.","x":["ETD입니다.","정답. 도착 예정 시각","틀립니다.","틀립니다."],"t":"ETA 도착, ETD 출항"},"2023-4-영어-14":{"w":"프로펠러 피치(1회전에 이론상 나아가는 거리)와 배가 실제 나아간 거리의 차이를 슬립(slip)이라 합니다.","x":["rpm = 분당 회전수","sailing mile = 항해 거리","정답. slip = 슬립","engine mile = 기관 거리(프로펠러 기준 거리)"],"t":"피치 − 실제 전진 거리 = slip"},"2023-4-영어-17":{"w":"닻을 다루는 일반적인 장치는 windlass(양묘기)입니다.","x":["정답. windlass = 양묘기","mooring winch = 계선 윈치","jib crane = 지브 크레인","capstan = 캡스턴"],"t":"windlass = anchor handling"},"2023-4-영어-21":{"w":"\"선박의 대부분의 냉각기(coolers)는 뜨거운 유체의 열을 해수나 청수로 옮긴다.\"","x":["정답. coolers","보일러가 아닙니다.","연료 탱크가 아닙니다.","가열기가 아닙니다."],"t":"cooler = 냉각기"},"2024-1-기관1-6":{"w":"4행정 기관의 배기행정 말기~흡기행정 초기(상사점 부근)에는 실린더 안 가스 압력이 거의 없는데, 피스톤과 커넥팅로드의 관성력이 피스톤을 위로 끌어올립니다. 이 관성력이 크랭크핀 볼트를 잡아당기므로 인장력이 가장 큽니다.","x":["이때는 관성력보다 압축 압력이 작용합니다.","압축 말기~작동 초기에는 가스 압력이 볼트를 누르는 방향(압축)으로 작용합니다.","이때는 관성력이 크지 않습니다.","정답. 가스 압력 없이 관성력만 작용 → 인장력 최대"],"t":"크랭크핀 볼트 인장 최대 = 배기 말~흡기 초(상사점)"},"2024-1-기관1-11":{"w":"유압식 조속기의 보상용 니들 밸브를 너무 적게 열면 보상 작용이 느려져 기관 속도 변화가 신속하지 못합니다. 너무 많이 열면 난조(헌팅, 맥동 운전)가 생깁니다.","x":["너무 많이 열었을 때의 현상입니다.","연료 제한 기능과 관계없습니다.","속도가 급상승하지 않습니다.","정답. 적게 열면 응답이 느립니다."],"t":"니들밸브 많이 열림 = 헌팅, 적게 열림 = 둔함"},"2024-1-기관1-15":{"w":"복수기로 배기를 진공(대기압보다 낮은 압력)으로 만들면 터빈 입구와 출구의 압력 차(열낙차)가 커져 증기가 더 많은 일을 하므로 터빈의 효율이 높아집니다.","x":["정답. 열낙차를 크게 해 효율을 높이기 위해","크기를 작게 하려는 목적이 아닙니다.","입구 증기 압력과는 관계없습니다.","입구 증기 속도와는 관계없습니다."],"t":"배기 진공 → 열낙차 증가 → 효율 증가"},"2024-1-기관1-20":{"w":"프로펠러가 1회전할 때 날개 위의 한 점이 축 방향으로 이론상 나아가는 거리를 피치라 합니다.","x":["슬립은 피치와 실제 전진 거리의 차이입니다.","스큐백은 날개가 회전 반대 방향으로 휜 정도입니다.","경사(레이크)는 날개가 뒤로 기운 정도입니다.","정답. 1회전 전진 거리 = 피치"],"t":"피치 = 1회전 이론 전진 거리"},"2024-1-기관1-21":{"w":"유동점은 기름이 흐를 수 있는 가장 낮은 온도입니다. 유동점이 높으면 추울 때 기름이 굳어 잘 흐르지 않습니다.","x":["온도가 오르면 점도는 낮아집니다.","세탄가가 낮으면 착화성이 나빠집니다.","정답. 유동점이 높으면 한랭 시 잘 흐르지 않습니다.","인화점이 낮으면 화재 위험이 높아집니다."],"t":"유동점 높음 = 추울 때 문제"},"2024-1-기관1-22":{"w":"경유의 비중은 약 0.84~0.89입니다. 휘발유는 약 0.69~0.77, 등유는 약 0.78~0.84, 중유는 약 0.91~0.99입니다.","x":["휘발유의 비중입니다.","등유의 비중입니다.","정답. 경유 약 0.84~0.89","중유의 비중입니다."],"t":"휘발유 < 등유 < 경유 < 중유"},"2024-1-기관2-3":{"w":"이모(Imo) 펌프는 나사 모양의 로터(스크루) 3개가 맞물려 돌면서 액체를 축 방향으로 밀어내는 스크루 펌프입니다. 맥동이 적어 연료유·윤활유 펌프로 많이 씁니다.","x":["슬라이딩 베인은 베인 펌프 형식입니다.","축방향 플런저는 사판식 등 플런저 펌프 형식입니다.","방사식 플런저는 반경 방향 플런저 펌프입니다.","정답. 이모 펌프 = 스크루 펌프"],"t":"이모 펌프 = 3축 스크루 펌프"},"2024-1-기관2-10":{"w":"유면검출기는 분리기 위쪽에 모인 기름층의 두께를 감지해 기름을 배출시킵니다. 감도를 높이면 기름층이 조금만 쌓여도 감지하므로 기름층의 하한 레벨이 높아집니다(얇은 기름층에서도 동작).","x":["상한 레벨이 낮아진다는 설명은 맞지 않습니다.","정답. 감도를 높이면 기름층의 하한 레벨이 높아집니다.","물층의 상한 레벨과는 관계없는 설명입니다.","물층의 하한 레벨과는 관계없는 설명입니다."],"t":"유면검출기 감도↑ → 기름층 하한 레벨↑"},"2024-1-기관2-15":{"w":"공기조화장치의 공기냉각기는 냉매가 증발하며 공기의 열을 빼앗으므로 냉동장치의 증발기 역할을 합니다.","x":["압축기가 아닙니다.","응축기는 열을 버리는 곳입니다.","정답. 공기냉각기 = 증발기","팽창밸브가 아닙니다."],"t":"공기냉각기 = 증발기"},"2024-1-기관2-18":{"w":"실린더 라이너는 회전하는 틀에 쇳물을 부어 원심력으로 치밀하게 만드는 원심 주조법으로 만듭니다. 크랭크축은 단조, 실린더 헤드는 주조로 만듭니다.","x":["실린더 헤드는 주조로 만듭니다.","정답. 실린더 라이너 = 원심 주조","배기밸브는 단조로 만듭니다.","크랭크축은 단조로 만듭니다."],"t":"라이너 = 원심 주조, 크랭크축 = 단조"},"2024-1-기관2-19":{"w":"용접 전류가 부족하면 모재가 충분히 녹지 않아 용입 부족, 슬랙 혼입, 오버랩이 생깁니다. 언더컷은 전류가 너무 높을 때 생기는 결함입니다.","x":["용입 부족은 전류 부족 때 생깁니다.","슬랙 혼입은 전류 부족 때 생깁니다.","정답(아닌 것). 언더컷은 전류 과대 때 생깁니다.","오버랩은 전류 부족 때 생깁니다."],"t":"언더컷 = 전류 과대 / 오버랩 = 전류 부족"},"2024-1-기관2-21":{"w":"용골은 배 밑바닥 중심선을 따라 선수재에서 선미재까지 이어진 가장 중요한 종강력재로, 사람의 척추에 해당합니다.","x":["늑골은 갈비뼈처럼 횡으로 선 부재입니다.","정답. 용골","빌지킬은 횡요(롤링)를 줄이는 부재입니다.","격벽은 선내를 나누는 벽입니다."],"t":"용골 = 배의 척추"},"2024-1-기관2-25":{"w":"제3각법은 정면도를 중심으로 위에 평면도, 오른쪽에 우측면도를 배치합니다.","x":["정답. 정면도·평면도·우측면도","정면도가 빠졌습니다.","좌측면도는 주로 배치하지 않습니다.","평면도가 빠졌습니다."],"t":"제3각법 = 정면도 + 위 평면도 + 오른쪽 우측면도"},"2024-1-기관3-10":{"w":"그림은 세 축전지의 (+)끼리, (−)끼리 연결한 병렬 연결입니다. 병렬 연결하면 전압은 그대로 12[V]이고 용량은 더해져 80 × 3 = 240[Ah]가 됩니다.","x":["축전지 1개의 값입니다.","정답. 병렬 = 전압 그대로, 용량 합산","직렬 연결일 때의 값입니다.","전압과 용량을 모두 더한 잘못된 값입니다."],"t":"축전지 직렬 = 전압 합, 병렬 = 용량 합"},"2024-1-기관3-13":{"w":"단권변압기(기동보상기)로 전동기에 낮은 전압을 걸어 기동하면 큰 기동 전류를 줄일 수 있습니다. 가속된 뒤 전전압으로 바꿉니다.","x":["기동 토크는 오히려 줄어듭니다.","전압을 낮추기 위해 씁니다.","정답. 기동 전류 감소","속도 감소가 목적이 아닙니다."],"t":"기동보상기 = 감전압 기동 → 기동전류↓"},"2024-1-기관3-16":{"w":"RL 직렬회로의 임피던스 Z = √(R² + XL²) = √(30² + 40²) = √2500 = 50[Ω]입니다.","x":["뺀 값입니다.","정답. √(30² + 40²) = 50[Ω]","단순히 더한 값입니다.","틀린 값입니다."],"t":"Z = √(R² + X²) (3:4:5 직각삼각형)"},"2024-1-기관3-20":{"w":"정류된 맥동 전압을 평탄하게 하는 회로는 평활회로이고, 여기에는 전하를 저장·방전하는 콘덴서를 주로 씁니다.","x":["정류회로가 아닙니다.","정류회로·가변저항이 아닙니다.","정답. 평활회로, 콘덴서","가변저항이 아닙니다."],"t":"평활회로 = 콘덴서"},"2024-1-직무일반-10":{"w":"빌지관 계통에는 바닷물이 역류해 들어오지 않도록 역지밸브(스톱 체크밸브)를 반드시 사용합니다.","x":["정박 중에는 배출하지 않습니다.","빌지가 고이는 곳이 빌지웰입니다.","정답(옳지 않은 것). 빌지관에는 역지밸브를 사용합니다.","15[ppm] 기름여과장치를 거쳐 배출합니다."],"t":"빌지관 = 역지밸브 필수"},"2024-1-직무일반-18":{"w":"선박소방설비기준상 열탐지기 1개가 담당하는 최대 바닥 면적은 37[m²], 연기탐지기는 74[m²]입니다. 탐지기 사이 거리는 열탐지기 9[m], 연기탐지기 11[m] 이내입니다.","x":["정답. 열탐지기 = 37[m²]","틀린 값입니다.","연기탐지기의 담당 면적입니다.","틀린 값입니다."],"t":"열탐지기 37m², 연기탐지기 74m²"},"2024-1-영어-2":{"w":"worn out = 닳은(마멸된), how much = 얼마나. \"실린더 라이너가 얼마나 마멸되었습니까?\"","x":["균열은 crack입니다.","몇 개는 how many입니다.","정답. 얼마나 마멸되었습니까?","사용량을 묻는 문장이 아닙니다."],"t":"worn out = 마멸된"},"2024-1-영어-12":{"w":"IHP = Indicated Horse Power = 지시마력(도시마력)입니다. 기계효율 = BHP ÷ IHP.","x":["제동마력은 BHP입니다.","전달마력은 DHP입니다.","유효마력은 EHP입니다.","정답. IHP = 지시(도시)마력"],"t":"기계효율 = BHP / IHP"},"2024-1-영어-13":{"w":"피스톤과 실린더 벽 사이의 압력 기밀을 유지하는 것은 piston ring(압축링)입니다.","x":["oil ring은 윤활유를 긁어내는 링입니다.","정답. piston ring","seal ring은 일반적인 밀봉 링입니다.","rubber ring은 고무 링입니다."],"t":"piston ring = pressure tight seal"},"2024-1-영어-17":{"w":"발전기 병렬 운전(동기화)은 전압, 주파수, 위상을 맞추는 것입니다. 전류는 맞출 조건이 아닙니다.","x":["전압을 맞춥니다.","위상을 맞춥니다.","정답(적절하지 않은 것). 전류는 동기화 조건이 아닙니다.","주파수를 맞춥니다."],"t":"병렬운전 조건 = 전압·주파수·위상"},"2024-1-영어-19":{"w":"vapor compression type = 증기 압축식 입니다. \"대부분의 기계식 냉동장치는 증기 압축식이다.\"","x":["정답. 증기 압축식","흡수식은 absorption type입니다.","증기 분사식은 steam jet type입니다.","냉매 분사식이 아닙니다."],"t":"vapor compression = 증기 압축식"},"2024-1-영어-21":{"w":"액체에 에너지를 주어 압력을 높이고 이동시키는 장치는 펌프(pump)입니다.","x":["cooler = 냉각기","정답. pump = 펌프","heater = 가열기","condenser = 응축기"],"t":"pump = 액체에 에너지를 주는 장치"},"2024-2-기관1-2":{"w":"지시열효율은 실린더 안에서 연료의 열이 얼마나 일(지시일)로 바뀌는지를 나타냅니다. 연소 개선, 냉각손실 감소, 유효행정 증가 등으로 높아집니다. 기계효율은 지시마력 중 마찰 손실을 뺀 비율로, 지시열효율과는 별개입니다.","x":["유효행정이 늘면 팽창일이 늘어납니다.","연소가 좋아지면 지시열효율이 높아집니다.","정답(옳지 않은 것). 기계효율은 지시열효율과 관계없습니다.","냉각손실이 줄면 지시열효율이 높아집니다."],"t":"제동열효율 = 지시열효율 × 기계효율"},"2024-2-기관1-14":{"w":"복수펌프는 복수기에 모인 복수를 빨아 가압한 뒤 급수가열기를 거쳐 급수펌프(또는 탈기기)로 보냅니다.","x":["정답. 복수펌프","순환수펌프는 복수기에 냉각 해수를 보냅니다.","공기이젝터는 복수기 속 공기를 뽑아냅니다.","공기분리기는 공기를 분리하는 장치입니다."],"t":"복수펌프 = 복수를 급수 계통으로"},"2024-2-기관2-17":{"w":"태핏(밸브) 간극처럼 좁은 틈새는 얇은 강판을 두께별로 모은 필러게이지(틈새게이지)로 잽니다.","x":["버니어 캘리퍼스는 길이·지름을 잽니다.","정답. 필러게이지","마이크로미터는 정밀 외경을 잽니다.","한계게이지는 합격 여부만 봅니다."],"t":"틈새 = 필러게이지"},"2024-2-기관2-18":{"w":"스크레이핑은 스크레이퍼로 평면이나 곡면(베어링 면 등)을 조금씩 긁어 정밀하게 다듬는 작업입니다.","x":["구멍 가공은 리밍·보링입니다.","연삭은 숫돌로 합니다.","정답. 평면·곡면의 정밀 다듬질","숫돌 다듬질은 연삭입니다."],"t":"스크레이핑 = 긁어서 정밀 다듬질"},"2024-2-기관2-22":{"w":"용골은 배 밑바닥 중심선을 따라 선수재에서 선미재까지 이어진 가장 중요한 종강력재로, 사람의 척추에 해당합니다.","x":["늑골은 갈비뼈처럼 횡으로 선 부재입니다.","정답. 용골","빌지킬은 횡요(롤링)를 줄이는 부재입니다.","격벽은 선내를 나누는 벽입니다."],"t":"용골 = 배의 척추"},"2024-2-기관2-24":{"w":"도면의 오른쪽 아래에는 도면 번호·명칭·척도·작성자 등을 적는 표제란을 반드시 둡니다.","x":["중심선은 위치가 정해져 있지 않습니다.","중심 마크는 도면 가장자리 중앙에 둡니다.","정답. 표제란","구역 기호는 테두리에 둡니다."],"t":"오른쪽 아래 = 표제란"},"2024-2-직무일반-1":{"w":"Abstract log(적요일지)는 한 항차가 끝난 뒤 그 항차의 주요 내용(항해시간, 연료 소비 등)을 요약한 기록입니다.","x":["Bell book은 기관 명령 기록부입니다.","정답. Abstract log = 항차 요약","Condition report는 상태 보고서입니다.","Engine room log book은 매일 쓰는 기관일지입니다."],"t":"Abstract log = 항차 요약"},"2024-2-직무일반-3":{"w":"그림은 관을 세 방향으로 나누는 T자 모양 부속품인 티(tee)입니다.","x":["정답. T자 모양 = 티","니플은 짧은 양쪽 수나사 관입니다.","엘보는 방향을 90°·45°로 꺾는 부속품입니다.","플러그는 관 끝을 막는 마개입니다."],"t":"티 = 분기, 엘보 = 방향 전환"},"2024-2-직무일반-4":{"w":"시체스트(sea chest)는 선체 바닥 옆에 있는 해수 흡입함입니다. 조개·해초 등이 막으면 증기(또는 공기)를 불어 넣어 청소할 수 있도록 증기관을 설치하기도 합니다.","x":["냉각기가 아닙니다.","수면 가까이가 아니라 선저 가까이에 설치합니다.","항해 중 수시로 개방하지 않습니다.","정답. 청소용 증기배관을 설치합니다."],"t":"시체스트 = 선저 해수 흡입함(증기 청소)"},"2024-2-직무일반-8":{"w":"수급 시 갑판 배수구(스커퍼)는 막아 두고, 방제 자재를 가까이 두고, 탱크를 자주 측심해 넘치지 않게 합니다. 맨홀을 열어 두면 안 됩니다.","x":["①은 틀립니다(배수구는 막아야 함).","①은 틀립니다(배수구는 막아야 함).","①은 틀립니다(배수구는 막아야 함).","①은 틀립니다(배수구는 막아야 함)."],"t":"수급 = 스커퍼 막기·방제자재·자주 측심"},"2024-2-직무일반-12":{"w":"의식이 없는 사람에게 음료를 주면 기도로 넘어가 질식할 수 있으므로 절대 주면 안 됩니다.","x":["열사병 환자는 의식이 있으면 수분을 줍니다.","일사병 환자는 수분을 줍니다.","정답. 의식불명자","중독자는 상황에 따라 다릅니다."],"t":"의식 없으면 음료 금지"},"2024-2-직무일반-14":{"w":"방수(침수 방지)용 기자재에는 시멘트, 캔버스, 방수매트, 쐐기, 나무판 등이 있습니다. 톱밥은 기름 흡착 등에 쓰일 뿐 방수 기자재가 아닙니다.","x":["시멘트 박스로 파공을 막습니다.","캔버스로 파공을 막습니다.","방수매트로 파공을 막습니다.","정답(아닌 것). 톱밥은 방수 기자재가 아닙니다."],"t":"방수 기자재 = 시멘트·캔버스·매트·쐐기"},"2024-2-직무일반-15":{"w":"침몰 우려가 있으면 가장 먼저 선내 침수 상황을 전 승무원에게 알려 모두 대비하게 해야 합니다.","x":["귀중품 정리는 우선 조치가 아닙니다.","조난통신은 선교(선장)가 합니다.","정답. 전 승무원에게 알린다","그다음 조치입니다."],"t":"비상 시 1순위 = 전원에게 알림"},"2024-2-직무일반-23":{"w":"해양안전심판원이 해기사에게 내리는 징계는 면허의 취소, 업무정지(1개월~1년), 견책의 3가지입니다.","x":["견책은 징계입니다.","정답(아닌 것). 권고는 징계가 아닙니다.","면허 취소는 징계입니다.","업무정지는 징계입니다."],"t":"징계 = 취소·업무정지·견책"},"2024-2-영어-8":{"w":"낮추다 = reduce(과거형 reduced). \"Reduced M/E rpm to 90 by bridge's order.\"","x":["Increased = 올렸다","정답. Reduced = 낮췄다","Induced = 유도했다","Operated = 운전했다"],"t":"reduce = 낮추다, increase = 올리다"},"2024-2-영어-9":{"w":"보일러 점화 전에 노 안을 송풍기로 환기하는 것은 Pre-purge(프리퍼지)입니다. 소화 후 환기는 Post-purge입니다.","x":["Post-purge = 소화 후 환기","Surface blow down = 수면 분출","정답. Pre-purge = 점화 전 환기","Bottom blow down = 수저 분출"],"t":"pre = 전, post = 후"},"2024-2-영어-11":{"w":"프로펠러 피치(1회전에 이론상 나아가는 거리)와 배가 실제 나아간 거리의 차이를 슬립(slip)이라 합니다.","x":["rpm = 분당 회전수","sailing mile = 항해 거리","정답. slip = 슬립","engine mile = 기관 거리(프로펠러 기준 거리)"],"t":"피치 − 실제 전진 거리 = slip"},"2024-2-영어-17":{"w":"수트 블로잉은 증기 압력 확인(③) → 수트 블로어 주증기밸브 열기(②) → 수트 블로잉 실시(④) → 주증기밸브 닫기(①) 순서입니다.","x":["순서가 틀렸습니다.","순서가 틀렸습니다.","순서가 틀렸습니다.","순서가 틀렸습니다."],"t":"확인 → 열기 → 실시 → 닫기"},"2024-2-영어-19":{"w":"공기를 압축하면 온도가 올라갑니다. 디젤기관은 이 압축열로 연료를 착화합니다.","x":["부피는 줄어듭니다.","정답. 압축하면 temperature(온도) 상승","viscosity = 점도","area = 면적"],"t":"압축 → 온도 상승(디젤 착화 원리)"},"2024-2-영어-21":{"w":"닻을 다루는 일반적인 장치는 windlass(양묘기)입니다.","x":["정답. windlass = 양묘기","mooring winch = 계선 윈치","jib crane = 지브 크레인","capstan = 캡스턴"],"t":"windlass = anchor handling"},"2024-2-영어-22":{"w":"우회전 프로펠러(right-handed propeller)는 배 뒤에서 보았을 때 전진 시 시계방향(clockwise)으로 돕니다.","x":["정답. clockwise = 시계방향","outward = 바깥쪽","anticlockwise = 반시계방향","inward = 안쪽"],"t":"right-handed = clockwise"},"2024-3-기관1-14":{"w":"Superheater(과열기)는 포화증기를 더 가열해 과열증기로 만듭니다.","x":["정답. Superheater = 과열기","Economizer = 절탄기(급수 예열)","Desuperheater = 과열 저감기","Regenerator = 재생기"],"t":"superheater = 과열기"},"2024-3-기관1-17":{"w":"프로펠러축이 부러지는 원인은 재질 불량, 비틀림 진동, 부식에 의한 강도 저하, 축심 불일치 등입니다. 추력 베어링의 마멸은 축의 전후 위치에 영향을 주지만 프로펠러축 절손의 직접 원인은 아닙니다.","x":["재질 불량은 절손 원인입니다.","정답(아닌 것). 추력 베어링 마멸은 직접 원인이 아닙니다.","비틀림 진동은 피로 파괴의 원인입니다.","부식으로 강도가 떨어지면 부러지기 쉽습니다."],"t":"프로펠러축 절손 = 재질, 비틀림 진동, 부식"},"2024-3-기관1-23":{"w":"윤활유가 고온의 실린더 벽이나 피스톤에 닿으면 열분해되어 탄화물(카본)이 생깁니다. 이 카본이 쌓이면 실린더 마멸과 피스톤링 고착의 원인이 됩니다.","x":["산소와 접촉하면 산화(슬러지)가 생깁니다.","새 윤활유 혼합은 탄화물의 원인이 아닙니다.","정답. 고온 → 열분해 → 탄화물","금속 가루·수분은 오염·유화의 원인입니다."],"t":"윤활유 탄화물 = 고온 열분해"},"2024-3-기관1-25":{"w":"윤활유는 점도지수가 크고, 응고점이 낮고, 항유화성이 크며, 탄화되기 어려워야 합니다.","x":["점도지수는 커야 합니다.","정답. 응고점이 낮아야 합니다.","항유화성은 커야 합니다.","탄화가 어려워야 합니다."],"t":"윤활유 = 점도지수↑, 응고점↓, 항유화성↑"},"2024-3-기관2-1":{"w":"원심펌프는 송출밸브를 조여 유량을 조절할 수 있습니다. 흡입밸브를 조이면 공동현상(캐비테이션)이 생기므로 흡입밸브는 조이면 안 됩니다.","x":["정격 운전을 해야 합니다.","베어링 온도에 주의해야 합니다.","흡입밸브를 조이면 캐비테이션이 생깁니다.","정답(옳지 않은 것). 송출밸브는 조여서 유량을 조절할 수 있습니다."],"t":"원심펌프 유량 조절 = 송출밸브 (흡입밸브 조임 금지)"},"2024-3-기관2-5":{"w":"하역용 윈치는 역전장치와 제동장치가 있고, 정격하중을 정격속도로 감아올릴 수 있어야 하며, 하중에 따라 속도를 조절할 수 있어야 합니다. 정격속도로만 운전된다면 안전하게 하역할 수 없습니다.","x":["정격하중을 정격속도로 감을 수 있어야 합니다.","역전장치가 필요합니다.","정답(아닌 것). 속도 조절이 가능해야 합니다.","제동장치가 필요합니다."],"t":"하역 윈치 = 역전·제동·속도 조절"},"2024-3-기관2-6":{"w":"사이드 스러스터는 선박을 옆으로 움직이는 추진장치로, 선수나 선미 부근의 수면 아래에 옆으로 뚫린 터널 안에 설치합니다.","x":["갑판에 설치하지 않습니다.","정답. 선수·선미 부근 수면 아래","크랭크축 끝이 아닙니다.","기관실 안쪽이 아닙니다."],"t":"사이드(바우) 스러스터 = 수면 아래 터널"},"2024-3-기관2-8":{"w":"폐유(슬러지)는 점도가 높고 이물질이 많아 원심펌프로는 옮기기 어렵습니다. 점도가 높은 액체를 일정하게 보낼 수 있는 기어 펌프가 가장 적당합니다.","x":["정답. 고점도 폐유 = 기어 펌프","원심펌프는 고점도 액체에 적합하지 않습니다.","왕복펌프는 맥동이 커 폐유 공급에 적합하지 않습니다.","축류펌프는 대유량·저양정용입니다."],"t":"고점도 기름 이송 = 기어 펌프"},"2024-3-기관2-10":{"w":"침전탱크에 가라앉은 활성슬러지는 공기 상승관(에어리프트)으로 폭기탱크에 되돌려 보내 미생물을 다시 활용합니다.","x":["스키머는 표면 부유물을 걷습니다.","멸균탱크로 보내지 않습니다.","멸균탱크로 보내지 않습니다.","정답. 공기 상승관으로 폭기탱크로 반송"],"t":"활성슬러지 = 폭기탱크로 반송"},"2024-3-기관2-15":{"w":"공기조화장치는 온도, 습도, 기류(풍속), 청정도를 조절합니다. 압력 조절은 기능이 아닙니다.","x":["온도 조절은 기능입니다.","습도 조절은 기능입니다.","기류 조절은 기능입니다.","정답(아닌 것). 압력은 조절하지 않습니다."],"t":"공조 4요소 = 온도·습도·기류·청정도"},"2024-3-기관2-16":{"w":"태핏(밸브) 간극처럼 좁은 틈새는 얇은 강판을 두께별로 모은 필러게이지(틈새게이지)로 잽니다.","x":["버니어 캘리퍼스는 길이·지름을 잽니다.","정답. 필러게이지","마이크로미터는 정밀 외경을 잽니다.","한계게이지는 합격 여부만 봅니다."],"t":"틈새 = 필러게이지"},"2024-3-기관2-18":{"w":"실린더 라이너는 회전하는 틀에 쇳물을 부어 원심력으로 치밀하게 만드는 원심 주조법으로 만듭니다. 크랭크축은 단조, 실린더 헤드는 주조로 만듭니다.","x":["실린더 헤드는 주조로 만듭니다.","정답. 실린더 라이너 = 원심 주조","배기밸브는 단조로 만듭니다.","크랭크축은 단조로 만듭니다."],"t":"라이너 = 원심 주조, 크랭크축 = 단조"},"2024-3-기관2-22":{"w":"전진할 때 프로펠러 날개가 먼저 물을 가르는 쪽 모서리를 앞날(리딩 엣지)이라 합니다.","x":["뒷날은 반대쪽 모서리입니다.","정답. 앞날","틀린 용어입니다.","틀린 용어입니다."],"t":"앞날 = 먼저 물을 끊는 쪽"},"2024-3-기관2-23":{"w":"선속과 필요한 동력은 3제곱 비례 관계에 있습니다. 따라서 시간당 연료소비량은 선속의 3제곱에 비례합니다. (항해 거리당 연료소비량은 선속의 제곱에 비례)","x":["반비례하지 않습니다.","제곱 비례는 같은 거리를 갈 때의 연료소비량입니다.","정답. 시간당 연료소비량 ∝ 선속³","4제곱이 아닙니다."],"t":"시간당 연료 ∝ 속력³, 거리당 연료 ∝ 속력²"},"2024-3-기관2-24":{"w":"제3각법은 정면도를 중심으로 위에 평면도, 오른쪽에 우측면도를 배치합니다.","x":["정답. 정면도·평면도·우측면도","정면도가 빠졌습니다.","좌측면도는 주로 배치하지 않습니다.","평면도가 빠졌습니다."],"t":"제3각법 = 정면도 + 위 평면도 + 오른쪽 우측면도"},"2024-3-기관3-1":{"w":"키르히호프의 제1법칙(전류 법칙)은 한 점으로 들어오고 나가는 전류의 대수합이 0이라는 법칙입니다.","x":["앙페르의 법칙은 전류와 자기장의 방향입니다.","정답. 키르히호프의 법칙","쿨롱의 법칙은 전하 사이의 힘입니다.","패러데이의 법칙은 전자유도입니다."],"t":"키르히호프 1법칙 = 전류, 2법칙 = 전압"},"2024-3-기관3-2":{"w":"전류는 전압에 비례하고 저항에 반비례한다는 것이 옴의 법칙(I = V/R)입니다.","x":["정답. 옴의 법칙","쿨롱의 법칙은 전하 사이의 힘입니다.","앙페르의 법칙은 전류와 자기장입니다.","줄의 법칙은 전류의 발열량입니다."],"t":"I = V / R"},"2024-3-기관3-3":{"w":"병렬 회로는 각 저항에 같은 전압이 걸립니다. 21÷2 + 21÷2 + 21÷3 = 10.5 + 10.5 + 7 = 28[A]입니다.","x":["틀린 값입니다.","정답. 10.5 + 10.5 + 7 = 28[A]","틀린 값입니다.","틀린 값입니다."],"t":"병렬 전체 전류 = 각 가지 전류의 합"},"2024-3-기관3-4":{"w":"전류 I = 전하량 Q ÷ 시간 t = 0.3 ÷ 0.5 = 0.6[A]입니다.","x":["틀린 값입니다.","틀린 값입니다.","정답. 0.3[C] ÷ 0.5[s] = 0.6[A]","틀린 값입니다."],"t":"I = Q / t"},"2024-3-기관3-9":{"w":"3상 유도전동기의 3단자 중 2단자를 바꾸면 회전자기장 방향이 반대로 되어 강한 제동이 걸립니다. 이를 역상제동(플러깅)이라 합니다.","x":["정답. 두 선 교체 = 역상제동(플러깅)","발전제동은 직류를 흘리거나 저항에 전력을 소비시킵니다.","단상제동은 해당하지 않습니다.","회생제동은 전력을 전원으로 되돌립니다."],"t":"두 선 바꾸기 = 역상제동(= 역회전)"},"2024-3-기관3-18":{"w":"부동 충전법은 충전기가 평소 부하에 전류를 공급하면서 축전지의 자기방전을 보충하고, 정전 시에는 축전지가 자동으로 부하에 전류를 공급하는 방식입니다.","x":["정전류 충전은 일정 전류로 충전하는 방법입니다.","정답. 부동 충전법","급속 충전은 짧은 시간에 큰 전류로 충전합니다.","균등 충전은 셀 사이 전압을 맞추는 충전입니다."],"t":"부동 충전 = 충전기 + 축전지 병렬 상시 연결"},"2024-3-기관3-21":{"w":"정류된 맥동 전압을 평탄하게 하는 회로는 평활회로이고, 여기에는 전하를 저장·방전하는 콘덴서를 주로 씁니다.","x":["정류회로가 아닙니다.","정류회로·가변저항이 아닙니다.","정답. 평활회로, 콘덴서","가변저항이 아닙니다."],"t":"평활회로 = 콘덴서"},"2024-3-기관3-22":{"w":"LED(발광 다이오드)는 순방향 전류가 흐르면 빛을 냅니다.","x":["CdS는 빛에 따라 저항이 변하는 소자입니다.","포토 다이오드는 빛을 받아 전류를 만듭니다.","정답. LED","포토 트랜지스터는 빛을 받아 동작합니다."],"t":"LED = 빛을 냄, 포토 = 빛을 받음"},"2024-3-직무일반-6":{"w":"선박해양오염비상계획서에는 방제조직, 선원이 취할 방제조치, 선장의 보고 절차, 연안국에 통보할 기관과 연락처 등이 들어갑니다. 통보 대상은 기국이 아니라 연안국(사고 해역 국가)입니다.","x":["방제조직이 포함됩니다.","보고 절차가 포함됩니다.","방제조치가 포함됩니다.","정답(아닌 것). 기국이 아니라 연안국 연락처입니다."],"t":"비상계획서 = 연안국 연락처"},"2024-3-직무일반-12":{"w":"들것은 보통 환자의 발 쪽이 앞으로 가게 운반합니다(계단 오를 때는 머리 먼저). 뒤쪽 운반자가 환자 얼굴을 보며 상태를 살필 수 있습니다.","x":["4인 운반이 안전합니다.","부상에 맞는 체위로 운반합니다.","흔들리지 않게 합니다.","정답(옳지 않은 것). 보통 발 쪽이 앞입니다."],"t":"들것 = 발 먼저"},"2024-3-직무일반-15":{"w":"Crash astern은 전속 전진 중 충돌 위험 등 비상시 주기관을 긴급히 후진시키는 기능입니다.","x":["위험회전수 회피 기능과 다릅니다.","정답. 전진 중 긴급 후진","부하 변동 시 정지 기능이 아닙니다.","윤활유 압력 저하 시에는 정지(셧다운)만 합니다."],"t":"Crash astern = 긴급 후진"},"2024-3-직무일반-16":{"w":"우선 차단(선택 차단)은 발전기 과부하 시 중요하지 않은 부하부터 차단해 발전기를 보호하는 기능입니다. 병렬운전 중 발전기가 전동기처럼 도는 것을 막는 것은 역전력 계전기(역전력 차단)의 기능입니다.","x":["트립 코일이 있습니다.","덜 중요한 부하부터 차단합니다.","과부하 시 선택 부하를 차단합니다.","정답(옳지 않은 것). 역전력 차단에 대한 설명입니다."],"t":"우선 차단 = 과부하 시 비중요 부하 차단"},"2024-3-직무일반-20":{"w":"과전류가 흐르면 전선·기기가 과열되어 전기화재의 위험이 가장 큽니다.","x":["정답. 과전류","절연저항이 높으면 안전합니다.","부하용량이 큰 것 자체는 위험이 아닙니다.","정격 이내라면 오래 사용해도 위험하지 않습니다."],"t":"전기화재 1순위 = 과전류"},"2024-3-직무일반-21":{"w":"밀폐된 장소의 화재는 전원·통풍을 차단하고 주변을 냉각해 확산을 막은 뒤 고정식 소화설비 등으로 끕니다. 휴대용 포말 소화기를 들고 들어가는 것은 매우 위험합니다.","x":["전원 차단은 올바른 조치입니다.","통풍 차단은 산소 공급을 막는 올바른 조치입니다.","인접 격실 냉각은 확산 방지 조치입니다.","정답(옳지 않은 것). 휴대 소화기로 진입하는 것은 위험합니다."],"t":"밀폐 구역 화재 = 차단·냉각·고정식 소화"},"2024-3-영어-7":{"w":"프로펠러 피치(1회전에 이론상 나아가는 거리)와 배가 실제 나아간 거리의 차이를 슬립(slip)이라 합니다.","x":["rpm = 분당 회전수","sailing mile = 항해 거리","정답. slip = 슬립","engine mile = 기관 거리(프로펠러 기준 거리)"],"t":"피치 − 실제 전진 거리 = slip"},"2024-3-영어-10":{"w":"Expansion stroke(팽창행정) = Working stroke(작동행정, 폭발행정)입니다.","x":["Suction stroke = 흡입행정","정답. Working stroke = 작동행정","Exhaust stroke = 배기행정","Compression stroke = 압축행정"],"t":"expansion = working = power stroke"},"2024-3-영어-15":{"w":"F.W.E.(Finished With Engine, 기관 사용 종료) 후에는 테스트 콕을 열고, 보조 송풍기를 멈추고, 에어 러닝을 하고, 터닝기어를 연결(engage)해 주기관을 돌립니다. 터닝기어를 분리(disengage)하는 것은 시동 준비 때 하는 일입니다.","x":["테스트 콕을 엽니다.","보조 송풍기를 멈춥니다.","에어 러닝을 합니다.","정답(아닌 것). F.W.E. 후에는 터닝기어를 연결합니다."],"t":"F.W.E. 후 = engage turning gear"},"2024-3-영어-18":{"w":"증기를 만드는 큰 강철 용기는 boiler입니다.","x":["steam turbine = 증기터빈","air vessel = 공기탱크","정답. boiler = 보일러","calorifier = 온수기"],"t":"boiler = 증기 발생"},"2024-3-영어-20":{"w":"소화 펌프는 모든 소화 호스 연결구에 해수(sea water)를 공급하는 원심펌프입니다.","x":["정답. sea water = 해수","bilge = 선저 폐수","fresh water = 청수","distilled water = 증류수"],"t":"Fire pump → sea water"},"2024-3-영어-21":{"w":"닻을 다루는 일반적인 장치는 windlass(양묘기)입니다.","x":["정답. windlass = 양묘기","mooring winch = 계선 윈치","jib crane = 지브 크레인","capstan = 캡스턴"],"t":"windlass = anchor handling"},"2024-3-영어-25":{"w":"빌지를 배출할 때 기름이 선외로 나가지 않게 하려면 15[ppm] 기름여과장치가 필요합니다.","x":["빌지펌프만으로는 기름을 거를 수 없습니다.","정답. 15[ppm] oil filtering equipment","소각기는 슬러지 처리용입니다.","오수처리장치는 분뇨 처리용입니다."],"t":"빌지 배출 = 15ppm 기름여과장치"},"2024-4-기관1-2":{"w":"소기공은 하사점을 중심으로 대칭으로 열리고 닫힙니다. 하사점 전 50°에 열리면 하사점 후 50°에 닫히므로 열려 있는 각도는 50° + 50° = 100°입니다.","x":["한쪽 각도만 계산한 값입니다.","정답. 50° + 50° = 100°","틀린 값입니다.","틀린 값입니다."],"t":"소기공 열림 각도 = 하사점 전 각도 × 2"},"2024-4-기관1-3":{"w":"밸브 개폐시기 선도는 흡·배기밸브가 열리고 닫히는 시기를 상사점·하사점 전후의 크랭크 각도로 나타낸 그림입니다.","x":["정답. 크랭크 각도","압력으로 나타내지 않습니다.","회전속도가 아닙니다.","피스톤 위치가 아니라 크랭크 각도입니다."],"t":"밸브 선도 = 크랭크 각도"},"2024-4-기관1-5":{"w":"피스톤 재료는 마멸에 강하고, 고온 강도가 크고, 열전도가 좋으며 열팽창이 작아야 합니다. 열팽창이 크면 피스톤이 라이너에 고착될 수 있습니다.","x":["마멸에 강해야 합니다.","실린더와 비슷한 열전도 특성이 좋습니다.","고온·고압 강도가 필요합니다.","정답(옳지 않은 것). 열팽창은 작아야 합니다."],"t":"피스톤 = 열팽창 작게"},"2024-4-기관1-7":{"w":"4행정 기관의 배기행정 말기~흡기행정 초기(상사점 부근)에는 실린더 안 가스 압력이 거의 없는데, 피스톤과 커넥팅로드의 관성력이 피스톤을 위로 끌어올립니다. 이 관성력이 크랭크핀 볼트를 잡아당기므로 인장력이 가장 큽니다.","x":["이때는 관성력보다 압축 압력이 작용합니다.","압축 말기~작동 초기에는 가스 압력이 볼트를 누르는 방향(압축)으로 작용합니다.","이때는 관성력이 크지 않습니다.","정답. 가스 압력 없이 관성력만 작용 → 인장력 최대"],"t":"크랭크핀 볼트 인장 최대 = 배기 말~흡기 초(상사점)"},"2024-4-기관1-11":{"w":"배압(배기 저항)이 높아지는 원인은 배기 계통의 카본 퇴적, 배기온도 상승(가스 팽창), 후연소 등입니다. 실린더 윤활 불량은 배압과 직접 관계가 없습니다.","x":["카본이 쌓이면 통로가 좁아집니다.","온도가 높으면 가스 부피가 커집니다.","후연소는 배기온도를 높입니다.","정답(옳지 않은 것). 실린더 윤활은 배압과 관계없습니다."],"t":"배압 상승 = 카본·고온 배기"},"2024-4-기관1-13":{"w":"복수기로 배기를 진공(대기압보다 낮은 압력)으로 만들면 터빈 입구와 출구의 압력 차(열낙차)가 커져 증기가 더 많은 일을 하므로 터빈의 효율이 높아집니다.","x":["정답. 열낙차를 크게 해 효율을 높이기 위해","크기를 작게 하려는 목적이 아닙니다.","입구 증기 압력과는 관계없습니다.","입구 증기 속도와는 관계없습니다."],"t":"배기 진공 → 열낙차 증가 → 효율 증가"},"2024-4-기관1-16":{"w":"축계는 기관에서 프로펠러 방향(선수→선미)으로 스러스트축 → 중간축 → 추진기축(프로펠러축) 순서로 배치됩니다.","x":["정답. 스러스트축 → 중간축 → 추진기축","순서가 틀렸습니다.","순서가 틀렸습니다.","순서가 틀렸습니다."],"t":"기관 → 스러스트축 → 중간축 → 프로펠러축"},"2024-4-기관1-18":{"w":"겉보기 슬립 = (프로펠러 속도 − 배의 속도) ÷ 프로펠러 속도 = (V_P − V) / V_P 입니다.","x":["정답. (V_P − V) / V_P","부호와 분모가 틀렸습니다.","틀린 식입니다.","틀린 식입니다."],"t":"슬립 = (이론 속도 − 실제 속도) / 이론 속도"},"2024-4-기관1-20":{"w":"프로펠러가 1회전할 때 날개 위의 한 점이 축 방향으로 이론상 나아가는 거리를 피치라 합니다.","x":["슬립은 피치와 실제 전진 거리의 차이입니다.","스큐백은 날개가 회전 반대 방향으로 휜 정도입니다.","경사(레이크)는 날개가 뒤로 기운 정도입니다.","정답. 1회전 전진 거리 = 피치"],"t":"피치 = 1회전 이론 전진 거리"},"2024-4-기관1-25":{"w":"윤활유가 고온의 실린더 벽이나 피스톤에 닿으면 열분해되어 탄화물(카본)이 생깁니다. 이 카본이 쌓이면 실린더 마멸과 피스톤링 고착의 원인이 됩니다.","x":["산소와 접촉하면 산화(슬러지)가 생깁니다.","새 윤활유 혼합은 탄화물의 원인이 아닙니다.","정답. 고온 → 열분해 → 탄화물","금속 가루·수분은 오염·유화의 원인입니다."],"t":"윤활유 탄화물 = 고온 열분해"},"2024-4-기관2-5":{"w":"윈치처럼 저속·고토크가 필요한 곳에는 반지름방향(레이디얼) 피스톤 모터를 많이 씁니다.","x":["기어 모터는 고속·저토크용입니다.","정답. 반지름방향 피스톤 모터","축방향 피스톤 모터는 고속용입니다.","서보 모터는 위치 제어용입니다."],"t":"윈치 = 레이디얼 피스톤 모터(저속 고토크)"},"2024-4-기관2-6":{"w":"추종장치는 타가 명령한 각도까지 움직이면 원동기 송출을 멈춰 그 위치에 타를 고정시킵니다.","x":["타장치는 타와 타두재입니다.","조종장치는 조타륜 등 명령 장치입니다.","정답. 추종장치","고정장치는 4대 요소가 아닙니다."],"t":"추종장치 = 명령 각도에서 정지"},"2024-4-기관2-13":{"w":"냉매는 수액기 출구 밸브를 닫고 보충합니다.","x":["충전관의 공기는 냉매 가스로 배제합니다.","정답(옳지 않은 것). 수액기 출구 밸브는 닫습니다.","응축기에 냉각수를 흘리며 합니다.","용기 무게로 보충량을 압니다."],"t":"냉매 보충 = 수액기 출구 밸브 닫기"},"2024-4-기관2-16":{"w":"스크레이핑은 스크레이퍼로 평면이나 곡면(베어링 면 등)을 조금씩 긁어 정밀하게 다듬는 작업입니다.","x":["구멍 가공은 리밍·보링입니다.","연삭은 숫돌로 합니다.","정답. 평면·곡면의 정밀 다듬질","숫돌 다듬질은 연삭입니다."],"t":"스크레이핑 = 긁어서 정밀 다듬질"},"2024-4-기관2-23":{"w":"전진할 때 프로펠러 날개가 먼저 물을 가르는 쪽 모서리를 앞날(리딩 엣지)이라 합니다.","x":["뒷날은 반대쪽 모서리입니다.","정답. 앞날","틀린 용어입니다.","틀린 용어입니다."],"t":"앞날 = 먼저 물을 끊는 쪽"},"2024-4-기관2-24":{"w":"제3각법은 정면도를 중심으로 위에 평면도, 오른쪽에 우측면도를 배치합니다.","x":["정답. 정면도·평면도·우측면도","정면도가 빠졌습니다.","좌측면도는 주로 배치하지 않습니다.","평면도가 빠졌습니다."],"t":"제3각법 = 정면도 + 위 평면도 + 오른쪽 우측면도"},"2024-4-기관2-25":{"w":"도면의 오른쪽 아래에는 도면 번호·명칭·척도·작성자 등을 적는 표제란을 반드시 둡니다.","x":["중심선은 위치가 정해져 있지 않습니다.","중심 마크는 도면 가장자리 중앙에 둡니다.","정답. 표제란","구역 기호는 테두리에 둡니다."],"t":"오른쪽 아래 = 표제란"},"2024-4-기관3-3":{"w":"역률 = 유효전력 ÷ 피상전력 = P ÷ (V × I) = 30 ÷ (100 × 0.6) = 30 ÷ 60 = 0.5입니다.","x":["정답. 30 ÷ 60 = 0.5","전류값을 그대로 쓴 값입니다.","틀린 값입니다.","틀린 값입니다."],"t":"역률 cosθ = P / VI"},"2024-4-기관3-5":{"w":"병렬 회로는 각 저항에 같은 전압이 걸립니다. 21÷2 + 21÷2 + 21÷3 = 10.5 + 10.5 + 7 = 28[A]입니다.","x":["틀린 값입니다.","정답. 10.5 + 10.5 + 7 = 28[A]","틀린 값입니다.","틀린 값입니다."],"t":"병렬 전체 전류 = 각 가지 전류의 합"},"2024-4-기관3-6":{"w":"전류 I = Q ÷ t = 10 ÷ 2 = 5[A]입니다.","x":["틀린 값입니다.","정답. 10 ÷ 2 = 5[A]","틀린 값입니다.","곱한 값입니다."],"t":"I = Q / t"},"2024-4-기관3-12":{"w":"전압을 높이려면 직렬로 연결합니다. 24 ÷ 1.2 = 20개를 직렬로 연결합니다.","x":["정답. 20개 직렬","병렬은 전압이 그대로입니다.","12개 직렬은 14.4[V]입니다.","병렬은 전압이 그대로입니다."],"t":"전압↑ = 직렬, 용량↑ = 병렬"},"2024-4-기관3-20":{"w":"중간 탭 변압기와 다이오드 D1, D2를 쓴 단상 전파 정류 회로입니다. 반주기마다 다이오드가 번갈아 도통합니다.","x":["반파 정류는 다이오드 1개입니다.","정답. 단상 전파 정류","3상이 아닙니다.","3상이 아닙니다."],"t":"중간탭 + 다이오드 2개 = 단상 전파"},"2024-4-기관3-21":{"w":"정류된 맥동 전압을 평탄하게 하는 회로는 평활회로이고, 여기에는 전하를 저장·방전하는 콘덴서를 주로 씁니다.","x":["정류회로가 아닙니다.","정류회로·가변저항이 아닙니다.","정답. 평활회로, 콘덴서","가변저항이 아닙니다."],"t":"평활회로 = 콘덴서"},"2024-4-기관3-22":{"w":"보일러 화염검출기(flame eye)에는 빛을 받으면 저항이 줄어드는 CdS(황화카드뮴) 셀을 널리 씁니다.","x":["정답. CdS","광전지는 전압을 만드는 소자입니다.","SSS는 해당하지 않습니다.","MOSFET는 전력 스위칭 소자입니다."],"t":"화염검출 = CdS"},"2024-4-직무일반-8":{"w":"마쇄·소독하지 않은 분뇨는 영해 기선에서 12해리를 넘는 곳에서 4노트 이상으로 항해하며 서서히 배출해야 합니다. (마쇄·소독한 것은 3해리 이상)","x":["3해리는 마쇄·소독한 분뇨의 기준입니다.","3해리는 마쇄·소독한 분뇨의 기준입니다.","속력이 부족합니다.","정답. 12해리, 4노트 이상"],"t":"미처리 분뇨 = 12해리·4노트"},"2024-4-직무일반-9":{"w":"폐기물을 육상 수용시설에 배출할 때는 배출 일시, 수용시설 이름, 폐기물 종류별 배출량, 책임자 서명 등을 기재합니다. 폐기물 발생원인은 기재하지 않습니다.","x":["배출 일시는 기재합니다.","책임자 서명은 기재합니다.","정답(아닌 것). 발생원인은 기재 사항이 아닙니다.","종류별 배출량은 기재합니다."],"t":"폐기물 배출 기록 = 일시·장소·종류별 양·서명"},"2024-4-직무일반-10":{"w":"선박에너지효율은 선박의 화물운송과 관련해 사용한 에너지량을 이산화탄소 발생 비율로 나타낸 것입니다.","x":["틀린 정의입니다.","틀린 정의입니다.","틀린 정의입니다.","정답. 에너지량 대비 CO₂ 발생 비율"],"t":"에너지효율 = CO₂ 발생 비율"},"2024-4-직무일반-11":{"w":"두드러기는 주로 음식(생선·조개 등)이나 약물에 대한 알레르기 반응으로 생깁니다.","x":["신경 긴장은 주된 원인이 아닙니다.","비타민 결핍은 주된 원인이 아닙니다.","바이러스는 주된 원인이 아닙니다.","정답. 음식·약물 부작용(알레르기)"],"t":"두드러기 = 알레르기"},"2024-4-직무일반-13":{"w":"일사병 환자는 의식이 있으면 시원한 곳에서 물이나 이온 음료를 조금씩 줍니다. 흉부·복부 손상자나 의식이 없는 환자에게는 음료를 주면 안 됩니다.","x":["정답. 일사병 환자는 수분 보충","흉부 손상자는 음료를 주지 않습니다.","복부 손상자는 음료를 주지 않습니다.","무의식 환자는 질식 위험이 있어 주지 않습니다."],"t":"음료 금지 = 무의식·흉부·복부 손상"},"2024-4-직무일반-15":{"w":"보일러 본체에는 부식, 점식(피팅), 균열, 과열로 인한 변형 등의 손상이 생깁니다. 노킹은 기관의 이상 연소 현상입니다.","x":["피팅(점식)은 보일러 손상입니다.","부식은 보일러 손상입니다.","정답(아닌 것). 노킹은 기관에서 생기는 현상입니다.","균열은 보일러 손상입니다."],"t":"보일러 손상 = 부식·피팅·균열·과열"},"2024-4-직무일반-17":{"w":"조타장치 성능 기준: 최대 전진 속력에서 한쪽 35°부터 반대쪽 35°까지 돌릴 수 있어야 하고, 한쪽 35°에서 반대쪽 30°까지 28초 이내에 돌릴 수 있어야 합니다.","x":["틀립니다.","첫 번째 각도가 틀립니다.","시간이 틀립니다.","정답. 35°, 28초"],"t":"35° → 반대 30° = 28초 이내"},"2024-4-직무일반-21":{"w":"밀폐된 장소의 화재는 전원·통풍을 차단하고 주변을 냉각해 확산을 막은 뒤 고정식 소화설비 등으로 끕니다. 휴대용 포말 소화기를 들고 들어가는 것은 매우 위험합니다.","x":["전원 차단은 올바른 조치입니다.","통풍 차단은 산소 공급을 막는 올바른 조치입니다.","인접 격실 냉각은 확산 방지 조치입니다.","정답(옳지 않은 것). 휴대 소화기로 진입하는 것은 위험합니다."],"t":"밀폐 구역 화재 = 차단·냉각·고정식 소화"},"2024-4-직무일반-22":{"w":"선박검사증서의 유효기간은 5년입니다.","x":["틀립니다.","틀립니다.","틀립니다.","정답. 5년"],"t":"선박검사증서 5년"},"2024-4-영어-1":{"w":"출항 직후에는 R/UP ENG(항해 속력 전환), 연료 전환(A → C 중유), 오수처리장치 가동 등을 기록합니다. 터닝기어 연결은 입항 후(F.W.E. 이후) 작업입니다.","x":["Rung up eng.은 출항 후 기록합니다.","정답(아닌 것). 터닝기어 연결은 입항 후 작업입니다.","연료 전환은 출항 후 기록합니다.","오수처리장치 가동은 출항 후 기록합니다."],"t":"engage turning gear = 정박 후"},"2024-4-영어-5":{"w":"보일러 점화 전에 노 안을 송풍기로 환기하는 것은 Pre-purge(프리퍼지)입니다. 소화 후 환기는 Post-purge입니다.","x":["Post-purge = 소화 후 환기","Surface blow down = 수면 분출","정답. Pre-purge = 점화 전 환기","Bottom blow down = 수저 분출"],"t":"pre = 전, post = 후"},"2024-4-영어-8":{"w":"프로펠러 피치(1회전에 이론상 나아가는 거리)와 배가 실제 나아간 거리의 차이를 슬립(slip)이라 합니다.","x":["rpm = 분당 회전수","sailing mile = 항해 거리","정답. slip = 슬립","engine mile = 기관 거리(프로펠러 기준 거리)"],"t":"피치 − 실제 전진 거리 = slip"},"2024-4-영어-14":{"w":"\"시간당 몇 톤으로 펌핑하십니까?\" (수급할 때 송유 속도를 묻는 표현)","x":["펌프 대수를 묻지 않습니다.","총량을 묻지 않습니다.","펌프 용량을 묻는 것이 아닙니다.","정답. 시간당 몇 톤으로 펌핑"],"t":"per hour = 시간당"},"2024-4-영어-16":{"w":"수트 블로잉은 증기 압력 확인(③) → 수트 블로어 주증기밸브 열기(②) → 수트 블로잉 실시(④) → 주증기밸브 닫기(①) 순서입니다.","x":["순서가 틀렸습니다.","순서가 틀렸습니다.","순서가 틀렸습니다.","순서가 틀렸습니다."],"t":"확인 → 열기 → 실시 → 닫기"},"2024-4-영어-22":{"w":"닻을 다루는 일반적인 장치는 windlass(양묘기)입니다.","x":["정답. windlass = 양묘기","mooring winch = 계선 윈치","jib crane = 지브 크레인","capstan = 캡스턴"],"t":"windlass = anchor handling"},"2024-4-영어-23":{"w":"실린더 라이너의 유막과 직접 닿는 면을 가진 것은 piston ring입니다.","x":["slip ring = 슬립링(전기)","정답. piston ring","O ring = 오링","mouth ring = 마우스링(펌프)"],"t":"piston ring face ↔ liner oil film"},"2025-2-기관1-5":{"w":"저질 중유에는 황분이 많아 황산 부식(저온 부식)으로 라이너가 마멸됩니다. 저속 운전을 하면 실린더 온도가 낮아져 황산이 응결하기 쉬우므로 오히려 부식 마멸이 늘어납니다.","x":["정답(옳지 않은 것). 저속 운전은 저온 부식을 키웁니다.","냉각수 온도를 높게 유지하면 황산 응결(저온 부식)을 막습니다.","청정하면 불순물·회분이 줄어 마멸이 줄어듭니다.","알칼리성이 좋은 실린더유 등 적합한 윤활유 사용은 마멸 방지 대책입니다."],"t":"저질 중유 → 황산 부식 → 온도를 높게, 저속 운전은 피한다"},"2025-2-기관1-25":{"w":"윤활유가 고온의 실린더 벽이나 피스톤에 닿으면 열분해되어 탄화물(카본)이 생깁니다. 이 카본이 쌓이면 실린더 마멸과 피스톤링 고착의 원인이 됩니다.","x":["산소와 접촉하면 산화(슬러지)가 생깁니다.","새 윤활유 혼합은 탄화물의 원인이 아닙니다.","정답. 고온 → 열분해 → 탄화물","금속 가루·수분은 오염·유화의 원인입니다."],"t":"윤활유 탄화물 = 고온 열분해"},"2025-2-기관2-9":{"w":"유면검출기는 분리기 위쪽에 모인 기름층의 두께를 감지해 기름을 배출시킵니다. 감도를 높이면 기름층이 조금만 쌓여도 감지하므로 기름층의 하한 레벨이 높아집니다(얇은 기름층에서도 동작).","x":["상한 레벨이 낮아진다는 설명은 맞지 않습니다.","정답. 감도를 높이면 기름층의 하한 레벨이 높아집니다.","물층의 상한 레벨과는 관계없는 설명입니다.","물층의 하한 레벨과는 관계없는 설명입니다."],"t":"유면검출기 감도↑ → 기름층 하한 레벨↑"},"2025-2-기관2-23":{"w":"선속과 필요한 동력은 3제곱 비례 관계에 있습니다. 따라서 시간당 연료소비량은 선속의 3제곱에 비례합니다. (항해 거리당 연료소비량은 선속의 제곱에 비례)","x":["반비례하지 않습니다.","제곱 비례는 같은 거리를 갈 때의 연료소비량입니다.","정답. 시간당 연료소비량 ∝ 선속³","4제곱이 아닙니다."],"t":"시간당 연료 ∝ 속력³, 거리당 연료 ∝ 속력²"},"2025-2-기관3-2":{"w":"전류 I = 전하량 Q ÷ 시간 t = 0.3 ÷ 0.5 = 0.6[A]입니다.","x":["틀린 값입니다.","틀린 값입니다.","정답. 0.3[C] ÷ 0.5[s] = 0.6[A]","틀린 값입니다."],"t":"I = Q / t"},"2025-2-기관3-4":{"w":"키르히호프의 제1법칙(전류 법칙)은 한 점으로 들어오고 나가는 전류의 대수합이 0이라는 법칙입니다.","x":["앙페르의 법칙은 전류와 자기장의 방향입니다.","정답. 키르히호프의 법칙","쿨롱의 법칙은 전하 사이의 힘입니다.","패러데이의 법칙은 전자유도입니다."],"t":"키르히호프 1법칙 = 전류, 2법칙 = 전압"},"2025-2-직무일반-12":{"w":"탈구는 강한 외력으로 관절을 이루는 뼈 끝이 관절에서 빠져나온 상태입니다.","x":["자상은 찔린 상처입니다.","골절은 뼈가 부러진 상태입니다.","정답. 관절에서 뼈가 빠짐 = 탈구","절상은 베인 상처입니다."],"t":"탈구 = 관절이 빠짐"},"2025-2-영어-5":{"w":"프로펠러 피치(1회전에 이론상 나아가는 거리)와 배가 실제 나아간 거리의 차이를 슬립(slip)이라 합니다.","x":["rpm = 분당 회전수","sailing mile = 항해 거리","정답. slip = 슬립","engine mile = 기관 거리(프로펠러 기준 거리)"],"t":"피치 − 실제 전진 거리 = slip"},"2025-3-기관1-5":{"w":"피스톤 헤드의 열이 피스톤핀 쪽으로 전달되는 것을 줄이기 위해 피스톤 내부에 방열판(열 차단판)을 둡니다. 핀과 핀 보스부가 과열되는 것을 막는 것이 주된 목적입니다.","x":["가스 누설 방지는 피스톤링의 역할입니다.","무게를 줄이는 장치가 아닙니다.","정답. 피스톤핀 과열 방지","라이너 열팽창 방지와는 관계없습니다."],"t":"피스톤 방열판 → 피스톤핀 과열 방지"},"2025-3-기관1-13":{"w":"같은 압력에서 포화증기를 더 가열해 포화온도보다 높아진 증기가 과열증기입니다. 따라서 온도가 가장 높습니다.","x":["정답. 과열증기가 가장 높습니다.","습포화증기는 포화온도입니다.","포화증기는 포화온도입니다.","건포화증기도 포화온도입니다."],"t":"과열증기 > 포화증기(습·건 모두 포화온도)"},"2025-3-기관1-15":{"w":"복수기로 배기를 진공(대기압보다 낮은 압력)으로 만들면 터빈 입구와 출구의 압력 차(열낙차)가 커져 증기가 더 많은 일을 하므로 터빈의 효율이 높아집니다.","x":["정답. 열낙차를 크게 해 효율을 높이기 위해","크기를 작게 하려는 목적이 아닙니다.","입구 증기 압력과는 관계없습니다.","입구 증기 속도와는 관계없습니다."],"t":"배기 진공 → 열낙차 증가 → 효율 증가"},"2025-3-기관1-16":{"w":"축계는 기관에서 프로펠러 방향(선수→선미)으로 스러스트축 → 중간축 → 추진기축(프로펠러축) 순서로 배치됩니다.","x":["정답. 스러스트축 → 중간축 → 추진기축","순서가 틀렸습니다.","순서가 틀렸습니다.","순서가 틀렸습니다."],"t":"기관 → 스러스트축 → 중간축 → 프로펠러축"},"2025-3-기관1-23":{"w":"윤활유가 고온의 실린더 벽이나 피스톤에 닿으면 열분해되어 탄화물(카본)이 생깁니다. 이 카본이 쌓이면 실린더 마멸과 피스톤링 고착의 원인이 됩니다.","x":["산소와 접촉하면 산화(슬러지)가 생깁니다.","새 윤활유 혼합은 탄화물의 원인이 아닙니다.","정답. 고온 → 열분해 → 탄화물","금속 가루·수분은 오염·유화의 원인입니다."],"t":"윤활유 탄화물 = 고온 열분해"},"2025-3-기관2-6":{"w":"원심펌프가 송출을 못 하는 원인은 흡입양정이 너무 큼, 흡입관에 공기가 남아 있거나 새어 들어옴, 유체 온도가 너무 높아 증발(공동현상) 등입니다. 유체 온도가 낮은 것은 원인이 아닙니다.","x":["흡입양정이 크면 흡입이 안 됩니다.","정답(옳지 않은 것). 온도가 높을 때가 문제입니다.","공기가 흡입되면 송출이 안 됩니다.","흡입관 속 공기는 송출 불량의 원인입니다."],"t":"원심펌프 송출 불량 = 공기, 큰 흡입양정, 높은 유체 온도"},"2025-3-기관2-7":{"w":"콜레서(coalescer)는 빌지 속의 아주 작은 기름방울을 섬유 필터에 흡착시켜 서로 뭉치게 해 큰 방울로 만듭니다. 커진 기름방울은 위로 잘 떠올라 분리됩니다.","x":["기름을 잘게 부수면 분리가 더 어려워집니다.","정답. 작은 기름 입자를 뭉쳐 큰 입자로 만듭니다.","물만 통과시키는 여과 필터와는 원리가 다릅니다.","기름만 통과시키는 장치가 아닙니다."],"t":"콜레서 = 작은 기름방울을 모아 큰 방울로"},"2025-3-기관2-8":{"w":"유면검출기는 분리기 위쪽에 모인 기름층의 두께를 감지해 기름을 배출시킵니다. 감도를 높이면 기름층이 조금만 쌓여도 감지하므로 기름층의 하한 레벨이 높아집니다(얇은 기름층에서도 동작).","x":["상한 레벨이 낮아진다는 설명은 맞지 않습니다.","정답. 감도를 높이면 기름층의 하한 레벨이 높아집니다.","물층의 상한 레벨과는 관계없는 설명입니다.","물층의 하한 레벨과는 관계없는 설명입니다."],"t":"유면검출기 감도↑ → 기름층 하한 레벨↑"},"2025-3-기관2-15":{"w":"실내에서 밖으로 열이 빠져나가는 겨울철 조건이므로 공급 공기를 가열해야 합니다. 가열하면 상대습도가 떨어지므로 가습도 함께 해야 합니다.","x":["냉각·감습은 여름철 조건입니다.","냉각은 맞지 않습니다.","가열은 맞지만 감습은 맞지 않습니다.","정답. 겨울철 = 가열 + 가습"],"t":"여름 = 냉각·감습, 겨울 = 가열·가습"},"2025-3-기관2-21":{"w":"트림 = 선수 흘수 − 선미 흘수 = 580 − 570 = 10[cm]입니다. 선수 쪽이 더 깊으므로 선수 트림 10[cm]입니다.","x":["값이 틀립니다.","방향과 값이 틀립니다.","정답. 선수가 10[cm] 더 깊음 = 선수 트림 10[cm]","방향이 틀립니다."],"t":"더 깊은 쪽 트림"},"2025-3-기관2-24":{"w":"한국산업표준(KS) 기계제도는 제3각법을 원칙으로 합니다. 정면도 위에 평면도, 오른쪽에 우측면도를 그립니다.","x":["반투상도법은 표준 투상법이 아닙니다.","제1각법은 일부 국가에서 쓰며 KS 원칙이 아닙니다.","제2각법은 쓰지 않습니다.","정답. KS = 제3각법"],"t":"KS 제도 = 제3각법"},"2025-3-기관3-4":{"w":"키르히호프의 제1법칙(전류 법칙)은 한 점으로 들어오고 나가는 전류의 대수합이 0이라는 법칙입니다.","x":["앙페르의 법칙은 전류와 자기장의 방향입니다.","정답. 키르히호프의 법칙","쿨롱의 법칙은 전하 사이의 힘입니다.","패러데이의 법칙은 전자유도입니다."],"t":"키르히호프 1법칙 = 전류, 2법칙 = 전압"},"2025-3-기관3-8":{"w":"콘덴서만 있는 회로에서는 전류가 전압보다 90° 앞섭니다(빠릅니다). 코일만 있는 회로에서는 전류가 90° 늦습니다.","x":["60°가 아닙니다.","코일(L) 회로의 경우입니다.","60°가 아닙니다.","정답. C 회로 = 전류가 90° 빠름"],"t":"C = 전류 앞섬, L = 전류 늦음 (90°)"},"2025-3-기관3-19":{"w":"두 다이오드가 A, B에서 X 쪽으로 향하고 X가 저항으로 접지된 다이오드 OR 회로입니다. A나 B 중 하나라도 1이면 X가 1이 되므로 ②, ③, ④입니다.","x":["둘 다 0이면 X는 0입니다.","둘 다 0이면 X는 0입니다.","둘 다 0이면 X는 0입니다.","둘 다 0이면 X는 0입니다."],"t":"다이오드 → 출력, 저항 접지 = OR"},"2025-3-기관3-22":{"w":"제너 다이오드는 역방향 전압이 일정 값(제너 전압)에 이르면 전압이 그 값으로 일정하게 유지되는 성질이 있어 정전압 회로에 씁니다.","x":["정답. 정전압 = 제너 다이오드","터널 다이오드는 고속 스위칭·발진용입니다.","배리스터는 과전압 보호용입니다.","서미스터는 온도 감지용입니다."],"t":"제너 다이오드 = 정전압"},"2025-3-기관3-25":{"w":"N형 반도체는 실리콘에 5가 원소(인, 비소 등)를 넣어 만들며, 이 불순물을 도너(donor)라 합니다. P형은 3가 원소인 억셉터를 넣습니다.","x":["도핑은 불순물을 넣는 과정입니다.","억셉터는 P형을 만드는 불순물입니다.","정공은 P형의 캐리어입니다.","정답. N형 = 도너(5가)"],"t":"N형 = 도너(5가), P형 = 억셉터(3가)"},"2025-3-직무일반-5":{"w":"그림은 한쪽으로만 흐르게 하고 역류를 막는 체크밸브입니다. 유체가 반대로 흐르면 밸브가 닫힙니다.","x":["나비밸브는 원판을 돌려 여닫는 밸브입니다.","슬루스밸브는 문처럼 위아래로 여닫는 밸브입니다.","정답. 역류 방지 = 체크밸브","글러브밸브는 둥근 몸통의 유량 조절용 밸브입니다."],"t":"체크밸브 = 역류 방지"},"2025-3-직무일반-14":{"w":"방수(침수 방지)용 기자재에는 시멘트, 캔버스, 방수매트, 쐐기, 나무판 등이 있습니다. 톱밥은 기름 흡착 등에 쓰일 뿐 방수 기자재가 아닙니다.","x":["정답(아닌 것). 톱밥은 방수 기자재가 아닙니다.","시멘트 박스로 파공을 막습니다.","캔버스로 파공을 막습니다.","방수매트로 파공을 막습니다."],"t":"방수 기자재 = 시멘트·캔버스·매트·쐐기"},"2025-3-직무일반-18":{"w":"선박소방설비기준상 열탐지기 1개가 담당하는 최대 바닥 면적은 37[m²], 연기탐지기는 74[m²]입니다. 탐지기 사이 거리는 열탐지기 9[m], 연기탐지기 11[m] 이내입니다.","x":["정답. 열탐지기 = 37[m²]","틀린 값입니다.","연기탐지기의 담당 면적입니다.","틀린 값입니다."],"t":"열탐지기 37m², 연기탐지기 74m²"},"2025-3-직무일반-20":{"w":"전기화재를 막으려면 절연저항을 규정치 이상으로 높게 유지해야 합니다. 절연저항이 낮으면 누전·단락으로 화재가 날 수 있습니다.","x":["연결부 고정은 예방법입니다.","과부하 운전 금지는 예방법입니다.","정답(옳지 않은 것). 절연저항은 규정치 이상으로 유지합니다.","접속단자 고정은 예방법입니다."],"t":"절연저항 = 높을수록 좋다"},"2025-3-영어-15":{"w":"액체에 에너지를 주어 압력을 높이고 이동시키는 장치는 펌프(pump)입니다.","x":["cooler = 냉각기","정답. pump = 펌프","heater = 가열기","condenser = 응축기"],"t":"pump = 액체에 에너지를 주는 장치"},"2025-3-영어-16":{"w":"선교와 기관실 사이에 기관 명령을 주고받는 장치는 기관 텔레그래프(engine telegraph)입니다.","x":["telescope = 망원경","정답. telegraph = 기관 텔레그래프","diaphragm = 격막","tachometer = 회전계"],"t":"engine telegraph = 선교↔기관실 명령 전달"},"2025-3-영어-24":{"w":"보일러의 강제통풍(forced draft)에는 송풍기(fan)를 씁니다.","x":["furnace = 노(연소실)","정답. fan = 송풍기","fire bricks = 내화벽돌","alarm = 경보기"],"t":"forced draft fan = 강제통풍 송풍기"},"2025-3-영어-25":{"w":"피스톤과 실린더 벽 사이의 압력 기밀을 유지하는 것은 piston ring(압축링)입니다.","x":["oil ring은 윤활유를 긁어내는 링입니다.","정답. piston ring","seal ring은 일반적인 밀봉 링입니다.","rubber ring은 고무 링입니다."],"t":"piston ring = pressure tight seal"},"2025-4-기관1-14":{"w":"포밍은 보일러수 속 불순물(기름, 부유물 등) 때문에 기포가 터지지 않고 수면에 거품층을 이루어 증기와 함께 넘어가는 현상입니다.","x":["정답. 거품이 쌓여 넘어감 = 포밍","기수분리는 증기에서 물방울을 분리하는 것입니다.","프라이밍은 물방울이 증기와 함께 튀어 나가는 현상입니다.","스플래시는 해당하지 않습니다."],"t":"포밍 = 거품, 프라이밍 = 물방울 비산"},"2025-4-기관1-25":{"w":"윤활유가 고온의 실린더 벽이나 피스톤에 닿으면 열분해되어 탄화물(카본)이 생깁니다. 이 카본이 쌓이면 실린더 마멸과 피스톤링 고착의 원인이 됩니다.","x":["산소와 접촉하면 산화(슬러지)가 생깁니다.","새 윤활유 혼합은 탄화물의 원인이 아닙니다.","정답. 고온 → 열분해 → 탄화물","금속 가루·수분은 오염·유화의 원인입니다."],"t":"윤활유 탄화물 = 고온 열분해"},"2025-4-기관2-4":{"w":"사이드 스러스터는 선박을 옆으로 움직이는 추진장치로, 선수나 선미 부근의 수면 아래에 옆으로 뚫린 터널 안에 설치합니다.","x":["갑판에 설치하지 않습니다.","기관실 안쪽이 아닙니다.","크랭크축 끝이 아닙니다.","정답. 선수·선미 부근 수면 아래"],"t":"사이드(바우) 스러스터 = 수면 아래 터널"},"2025-4-기관2-14":{"w":"실내에서 밖으로 열이 빠져나가는 겨울철 조건이므로 공급 공기를 가열해야 합니다. 가열하면 상대습도가 떨어지므로 가습도 함께 해야 합니다.","x":["냉각·감습은 여름철 조건입니다.","냉각은 맞지 않습니다.","가열은 맞지만 감습은 맞지 않습니다.","정답. 겨울철 = 가열 + 가습"],"t":"여름 = 냉각·감습, 겨울 = 가열·가습"},"2025-4-기관2-18":{"w":"리머는 드릴로 뚫은 구멍을 치수에 맞게 매끈하고 정밀하게 다듬는 공구입니다. 끝부분이 약간 테이퍼져 있고 손(핸드 리머)이나 기계로 씁니다.","x":["끝에 테이퍼 부분이 있습니다.","절삭날은 곧은 날 또는 약한 나선형입니다.","선반 전용이 아닙니다.","정답. 구멍의 정밀 다듬질"],"t":"리머 = 구멍 다듬질"},"2025-4-기관2-21":{"w":"재화중량톤수(DWT)는 만재 배수량에서 경하 배수량(빈 배의 무게)을 뺀 값으로, 배가 실을 수 있는 화물·연료·물 등의 무게를 나타냅니다.","x":["순톤수는 여객·화물 적재 용적입니다.","총톤수는 선박 전체의 용적입니다.","배수톤수는 배가 밀어낸 물의 무게입니다.","정답. 만재 배수량 − 경하 배수량 = 재화중량톤수"],"t":"재화중량톤수 = 실을 수 있는 무게(DWT)"},"2025-4-기관2-23":{"w":"이중저는 선저를 이중으로 만든 구조로 연료유·밸러스트수·청수를 저장하고, 좌초 시 침수를 막으며, 종강도를 보강합니다. 화물은 이중저에 싣지 않습니다.","x":["정답(옳지 않은 것). 이중저에는 화물을 싣지 않습니다.","연료유를 저장합니다.","좌초 시 방수 역할을 합니다.","종강도를 보강합니다."],"t":"이중저 = 연료·밸러스트·청수 탱크"},"2025-4-기관3-8":{"w":"누름버튼을 누르면 계전기 X가 동작하고, X의 a접점(X-a)이 누름버튼과 병렬로 닫혀 버튼에서 손을 떼도 X가 계속 동작합니다. 이를 자기유지회로라 합니다.","x":["인터록은 두 회로가 동시에 동작하지 않게 하는 회로입니다.","정답. 자기 접점으로 동작 유지 = 자기유지회로","선행동작 우선회로가 아닙니다.","신입신호 우선회로가 아닙니다."],"t":"버튼과 병렬 a접점 = 자기유지"},"2025-4-직무일반-1":{"w":"그림은 한쪽으로만 흐르게 하고 역류를 막는 체크밸브입니다. 유체가 반대로 흐르면 밸브가 닫힙니다.","x":["나비밸브는 원판을 돌려 여닫는 밸브입니다.","슬루스밸브는 문처럼 위아래로 여닫는 밸브입니다.","정답. 역류 방지 = 체크밸브","글러브밸브는 둥근 몸통의 유량 조절용 밸브입니다."],"t":"체크밸브 = 역류 방지"},"2025-4-영어-14":{"w":"피스톤과 실린더 벽 사이의 압력 기밀을 유지하는 것은 piston ring(압축링)입니다.","x":["oil ring은 윤활유를 긁어내는 링입니다.","정답. piston ring","seal ring은 일반적인 밀봉 링입니다.","rubber ring은 고무 링입니다."],"t":"piston ring = pressure tight seal"},"2025-4-영어-20":{"w":"선교와 기관실 사이에 기관 명령을 주고받는 장치는 기관 텔레그래프(engine telegraph)입니다.","x":["telescope = 망원경","정답. telegraph = 기관 텔레그래프","diaphragm = 격막","tachometer = 회전계"],"t":"engine telegraph = 선교↔기관실 명령 전달"},"2025-4-영어-21":{"w":"움직이는 부품 사이에 유막을 만드는 것은 윤활유 계통(lubricating oil system)의 주된 기능입니다.","x":["fuel oil system = 연료유 계통","control oil system = 제어유 계통","hydraulic oil system = 유압 계통","정답. lubricating oil system = 윤활유 계통"],"t":"oil film = lubricating oil"},"2020-2-기관1-3":{"w":"4행정 기관에서 배기행정 종말(상사점 부근)에는 가스 압력 없이 관성력이 크랭크축을 끌어올려 메인 베어링 캡에 최대 하중이 걸립니다.","x":["틀립니다.","정답. 배기행정 종말","틀립니다.","압축 종말에는 하중이 아래쪽에 걸립니다."],"t":"캡 최대 하중 = 배기 말"},"2020-2-기관1-4":{"w":"중·대형 2행정 디젤기관은 배기밸브로 위로 배기하고 소기공으로 아래에서 소기하는 유니플로 소기식을 많이 씁니다. 소기 효율이 가장 좋습니다.","x":["정답. 유니플로 소기식","루프 소기식은 중소형에 씁니다.","횡단 소기식은 소형에 씁니다.","와류 소기식이 아닙니다."],"t":"대형 2행정 = 유니플로 소기"},"2020-2-기관1-5":{"w":"피스톤링용 주철 속의 흑연은 스스로 윤활 작용을 하고 윤활유를 머금어 유막을 유지하게 합니다.","x":["철은 기본 성분입니다.","정답. 흑연 = 자기 윤활","니켈은 강도·내식성을 높입니다.","크롬은 내마모성을 높입니다."],"t":"주철 속 흑연 = 윤활 보조"},"2020-2-기관1-6":{"w":"트렁크형 피스톤 윗면을 오목하게 만들면 공기의 와류가 생기고 연료와 잘 섞여 연소가 좋아집니다.","x":["정답. 연소 개선","강도가 목적이 아닙니다.","압축비는 오히려 작아집니다.","변형 감소가 목적이 아닙니다."],"t":"오목한 피스톤 윗면 = 와류·연소 개선"},"2020-2-기관1-7":{"w":"크랭크축의 불균형 회전을 보정해 진동을 줄이는 것은 밸런스 웨이트(평형추)입니다.","x":["정답. 밸런스 웨이트","크랭크저널은 메인 베어링에 얹히는 부분입니다.","플라이 웨이트는 조속기의 추입니다.","크랭크암은 저널과 핀을 잇는 부분입니다."],"t":"밸런스 웨이트 = 진동 감소"},"2020-2-기관1-8":{"w":"크랭크암 개폐량(디플렉션)으로 위험 개폐량 도달, 메인 베어링 마멸, 축 중심선 불일치를 판단합니다. 위험 회전수는 비틀림 진동 계산으로 정하는 것으로 개폐량으로는 알 수 없습니다.","x":["판단할 수 있습니다.","판단할 수 있습니다.","정답(판단할 수 없는 것). 위험 회전수","판단할 수 있습니다."],"t":"디플렉션 = 베어링 마멸·축심"},"2020-2-기관1-10":{"w":"고정 피치 프로펠러를 구동하는 주기관의 출력은 회전수의 세제곱에 비례해 증가합니다(프로펠러 법칙).","x":["틀립니다.","토크는 제곱에 비례합니다.","정답. 세제곱 비례 증가","감소하지 않습니다."],"t":"출력 ∝ N³, 토크 ∝ N²"},"2020-2-기관1-12":{"w":"회전식(로터리) 버너는 고속 회전하는 컵의 원심력으로 기름을 무화하므로 연료 압력이 가장 낮아도 됩니다.","x":["정답. 회전식 버너","압력 분무식은 고압이 필요합니다.","증기로 무화합니다.","공기로 무화합니다."],"t":"회전식 버너 = 저압 연료"},"2020-2-기관1-13":{"w":"버너의 진동 연소는 연료유 압력 변동, 수분 혼입, 가열 온도 과다(기포 발생) 등으로 생깁니다. 보일러 부하 변화는 진동 연소의 원인이 아닙니다.","x":["원인입니다.","정답(아닌 것). 부하 변화는 원인이 아닙니다.","원인입니다.","원인입니다."],"t":"진동 연소 = 연료 압력·수분·과열"},"2020-2-기관1-14":{"w":"팽창 중인 증기 일부를 뽑아 급수를 가열하는 사이클은 재생 사이클입니다. 다시 가열해 터빈에 넣는 것은 재열 사이클입니다.","x":["이론 사이클입니다.","기본 증기 사이클입니다.","정답. 재생 사이클","재열 사이클은 증기를 다시 가열합니다."],"t":"재생 = 추기로 급수 가열, 재열 = 증기 재가열"},"2020-2-기관1-15":{"w":"복수기로 배기를 진공(대기압보다 낮은 압력)으로 만들면 터빈 입구와 출구의 압력 차(열낙차)가 커져 증기가 더 많은 일을 하므로 터빈의 효율이 높아집니다.","x":["정답. 열낙차를 크게 해 효율을 높이기 위해","크기를 작게 하려는 목적이 아닙니다.","입구 증기 압력과는 관계없습니다.","입구 증기 속도와는 관계없습니다."],"t":"배기 진공 → 열낙차 증가 → 효율 증가"},"2020-2-기관1-16":{"w":"역전장치에는 직접 역전(캠축 이동식 등)과 간접 역전(역전기어, 가변 피치 프로펠러)이 있습니다. 대형 선박은 주로 기관 자체를 역회전시키는 직접 역전방식을 씁니다.","x":["맞습니다.","맞습니다.","정답(옳지 않은 것). 대형선은 직접 역전입니다.","맞습니다."],"t":"대형 저속기관 = 직접 역전"},"2020-2-기관1-17":{"w":"스러스트 베어링이 많이 닳으면 크랭크축이 축 방향으로 밀려 메인 베어링 측면 발열, 크랭크암 개폐량 증대, 라이너 편마멸이 생깁니다. 배기밸브 누설과는 관계없습니다.","x":["나타납니다.","나타납니다.","나타납니다.","정답(아닌 것). 배기밸브 누설과 관계없습니다."],"t":"스러스트 마멸 = 축방향 이동"},"2020-2-기관1-18":{"w":"물·공기 저항을 이기며 선체를 예인하는 데 필요한 마력은 유효마력입니다.","x":["도시마력은 실린더 안 마력입니다.","전달마력이 아닙니다.","제동마력이 아닙니다.","정답. 유효마력"],"t":"예인 = 유효마력"},"2020-2-기관1-22":{"w":"수증기의 증발잠열을 뺀 발열량은 저위 발열량입니다.","x":["정답. 저위 발열량","고위 발열량은 증발잠열을 포함합니다.","틀립니다.","틀립니다."],"t":"저위 = 증발잠열 제외"},"2020-2-기관2-1":{"w":"추종장치는 타가 조타 신호(명령 타각)만큼 돌아가면 유압펌프 송출을 멈춰 타를 그 위치에 고정시킵니다.","x":["다를 때는 타를 움직여야 합니다.","원래 위치로 되돌리지 않습니다.","정답. 명령 타각에 도달하면 고정","원래 위치로 되돌리지 않습니다."],"t":"추종장치 = 명령 타각에서 정지"},"2020-2-기관2-4":{"w":"셀프젝터 청정기는 정상 청정 중에는 저압수(작동수)를 공급해 회전통을 닫아 두고, 슬러지를 배출할 때는 고압수를 공급해 회전통을 엽니다.","x":["정답. 청정 중 = 저압수 공급, 고압수 차단","반대입니다.","배출 시에는 고압수를 공급합니다.","배출 시에는 고압수를 공급합니다."],"t":"저압수 = 닫힘, 고압수 = 열림(배출)"},"2020-2-기관2-6":{"w":"유압 양묘장치는 유압펌프에서 보낸 기름으로 유압모터를 돌려 체인 드럼축을 직접 구동합니다.","x":["정답. 유압모터","웜기어는 전동식에 씁니다.","스퍼기어는 감속용입니다.","클러치는 동력을 연결·차단합니다."],"t":"유압 양묘기 = 유압모터 구동"},"2020-2-기관2-7":{"w":"불활성가스장치의 공급주관 가스 속 산소 농도는 5[%] 이하, 화물탱크 안은 8[%] 이하로 유지해야 합니다.","x":["틀립니다.","정답. 5[%] 이하","탱크 내 기준입니다.","틀립니다."],"t":"IGS 공급 5%↓, 탱크 8%↓"},"2020-2-기관2-9":{"w":"유면검출기가 기름층을 감지하면 배유 전자밸브를 열고, 타이머 신호로 닫습니다.","x":["콜레서는 기름을 뭉치게 합니다.","포집관은 기름을 모읍니다.","타이머는 밸브를 닫습니다.","정답. 유면검출기 신호로 열림"],"t":"열림 = 유면검출기, 닫힘 = 타이머"},"2020-2-기관2-10":{"w":"폐유(슬러지)는 점도가 높고 이물질이 많아 원심펌프로는 옮기기 어렵습니다. 점도가 높은 액체를 일정하게 보낼 수 있는 기어 펌프가 가장 적당합니다.","x":["정답. 고점도 폐유 = 기어 펌프","원심펌프는 고점도 액체에 적합하지 않습니다.","왕복펌프는 맥동이 커 폐유 공급에 적합하지 않습니다.","축류펌프는 대유량·저양정용입니다."],"t":"고점도 기름 이송 = 기어 펌프"},"2020-2-기관2-11":{"w":"불응축 가스(공기)가 들어가면 응축기에서 응축되지 않아 응축(압축) 압력이 높아지고, 동력이 늘며 냉동능력이 떨어집니다.","x":["흡입 압력과 관계없습니다.","응축 압력은 높아집니다.","냉동능력은 나빠집니다.","정답. 압축 압력 상승"],"t":"불응축 가스 = 고압 상승"},"2020-2-기관2-13":{"w":"압축비가 너무 높으면 토출가스 온도가 올라가고, 냉동능력과 성적계수가 떨어지며, 윤활유가 빨리 열화됩니다.","x":["냉동능력이 감소합니다.","정답(옳지 않은 것). 토출가스 온도는 높아집니다.","성적계수가 떨어집니다.","윤활유 열화가 빨라집니다."],"t":"압축비↑ = 토출온도↑, 능력↓"},"2020-2-기관2-14":{"w":"냉동톤 = 332,000 ÷ 3,320 = 100 RT. 동력 = 100 × 0.8 = 80[kW]입니다.","x":["틀린 값입니다.","틀린 값입니다.","정답. 100RT × 0.8 = 80[kW]","틀린 값입니다."],"t":"1RT = 3,320kcal/h"},"2020-2-기관2-16":{"w":"어미자 눈금 1[mm]를 아들자 20등분으로 읽는 버니어 캘리퍼스의 최소 측정값은 1 ÷ 20 = 0.05[mm]입니다.","x":["틀립니다.","아들자 한 눈금의 실제 길이(19/20)입니다.","틀립니다.","정답. 0.05[mm]"],"t":"20등분 버니어 = 0.05mm"},"2020-2-기관2-17":{"w":"가열 후 노 안에서 천천히 식혀 재료를 무르게 하고 내부 응력을 없애는 열처리는 풀림입니다.","x":["뜨임은 담금질 후 인성을 주는 처리입니다.","담금질은 급랭 경화입니다.","불림은 공기 중 냉각입니다.","정답. 풀림(노냉)"],"t":"풀림 = 노 안에서 서냉"},"2020-2-기관2-18":{"w":"선박에서 나사는 주로 선반으로 깎아 만듭니다(나사 절삭). 손으로는 탭·다이스를 씁니다.","x":["정답. 선반 가공","밀링은 주로 평면·홈 가공입니다.","드릴링은 구멍 가공입니다.","호닝은 구멍 내면 다듬질입니다."],"t":"나사 가공 = 선반(탭·다이스)"},"2020-2-기관2-19":{"w":"플랜지 접합면처럼 움직이지 않는 면 사이에 넣어 누설을 막는 것은 개스킷입니다.","x":["정답. 개스킷","스크레이퍼링은 기름 긁기 링입니다.","기계식 실은 회전축용입니다.","글랜드 패킹은 축용입니다."],"t":"플랜지 = 개스킷"},"2020-2-기관2-20":{"w":"유체를 한 방향으로만 흐르게 해 역류를 막는 밸브는 체크 밸브입니다.","x":["릴리프 밸브는 압력 제한용입니다.","정답. 체크 밸브","안전 밸브는 과압 방출용입니다.","니들 밸브는 미세 유량 조절용입니다."],"t":"체크 밸브 = 역류 방지"},"2020-2-기관2-21":{"w":"전진할 때 프로펠러 날개가 먼저 물을 가르는 쪽 모서리를 앞날(리딩 엣지)이라 합니다.","x":["뒷날은 반대쪽 모서리입니다.","정답. 앞날","틀린 용어입니다.","틀린 용어입니다."],"t":"앞날 = 먼저 물을 끊는 쪽"},"2020-2-기관2-22":{"w":"계약 단계의 기본 설계 도면은 일반 배치도, 중앙 횡단면도, 외판 전개도 등입니다. 선저 구조도는 상세 설계 단계 도면입니다.","x":["기본 설계 도면입니다.","기본 설계 도면입니다.","정답(아닌 것). 상세 설계 도면입니다.","기본 설계 도면입니다."],"t":"기본 설계 = 일반배치도·중앙횡단면도"},"2020-2-기관2-24":{"w":"기능상 지장이 없는 범위에서 미리 정한 치수의 허용량을 공차라 합니다.","x":["정답. 공차","해칭은 단면 표시입니다.","스머징은 단면 칠하기입니다.","거칠기는 표면 상태입니다."],"t":"공차 = 허용 범위"},"2020-2-기관3-1":{"w":"거주실 전원 220[V]는 실효값(실효치)입니다.","x":["최대치가 아닙니다.","순시치가 아닙니다.","정답. 실효치","평균치가 아닙니다."],"t":"전원 = 실효값"},"2020-2-기관3-2":{"w":"역기전력도 전압이므로 단위는 [V]입니다.","x":["정전용량 단위입니다.","정답. [V]","저항 단위입니다.","전력 단위입니다."],"t":"기전력 = V"},"2020-2-기관3-4":{"w":"병렬 회로는 각 저항에 같은 전압이 걸립니다. 21÷2 + 21÷2 + 21÷3 = 10.5 + 10.5 + 7 = 28[A]입니다.","x":["틀린 값입니다.","정답. 10.5 + 10.5 + 7 = 28[A]","틀린 값입니다.","틀린 값입니다."],"t":"병렬 전체 전류 = 각 가지 전류의 합"},"2020-2-기관3-6":{"w":"전류 I = Q ÷ t = 10 ÷ 2 = 5[A]입니다.","x":["틀린 값입니다.","정답. 10 ÷ 2 = 5[A]","틀린 값입니다.","곱한 값입니다."],"t":"I = Q / t"},"2020-2-기관3-9":{"w":"주파수 f = 1 ÷ 주기 = 1 ÷ 0.2 = 5[Hz]입니다.","x":["틀립니다.","정답. 1 ÷ 0.2 = 5[Hz]","틀립니다.","틀립니다."],"t":"f = 1 / T"},"2020-2-기관3-11":{"w":"P = V² ÷ R = 220² ÷ 220 = 220[W]입니다. (전류 1[A] × 220[V])","x":["틀린 값입니다.","틀린 값입니다.","정답. 220²/220 = 220[W]","틀린 값입니다."],"t":"P = V² / R"},"2020-2-기관3-15":{"w":"여자기는 교류발전기의 계자 권선에 직류 전류를 공급해 자속을 만듭니다.","x":["주파수는 회전수로 정해집니다.","부하 분담은 거버너가 합니다.","정답. 계자에 직류 공급","속도는 거버너가 조절합니다."],"t":"여자기 = 계자 직류 공급"},"2020-2-기관3-19":{"w":"정류 출력을 평활하게 하려면 출력단에 콘덴서를 병렬로 연결합니다(코일은 직렬).","x":["콘덴서는 병렬입니다.","정답. 콘덴서 병렬","부하저항을 작게 하면 맥동이 커집니다.","코일은 직렬로 넣습니다."],"t":"평활 = C 병렬, L 직렬"},"2020-2-기관3-21":{"w":"적분회로에 구형파를 넣으면 출력은 일정하게 증가·감소를 반복하는 삼각파가 됩니다.","x":["사인파가 아닙니다.","구형파가 아닙니다.","정답. 삼각파","펄스파는 미분회로의 출력입니다."],"t":"적분 → 삼각파, 미분 → 펄스"},"2020-2-기관3-25":{"w":"N형 반도체는 실리콘에 5가 원소(인, 비소 등)를 넣어 만들며, 이 불순물을 도너(donor)라 합니다. P형은 3가 원소인 억셉터를 넣습니다.","x":["도핑은 불순물을 넣는 과정입니다.","억셉터는 P형을 만드는 불순물입니다.","정공은 P형의 캐리어입니다.","정답. N형 = 도너(5가)"],"t":"N형 = 도너(5가), P형 = 억셉터(3가)"},"2020-2-직무일반-2":{"w":"일반적으로 2등 기관사는 연료유의 수급·관리, 연료유 청정기, 발전기 등을 맡습니다. 윤활유의 수급 및 관리는 주로 3등 기관사의 업무입니다.","x":["발전기 운전·관리는 2등 기관사 업무입니다.","정답(아닌 것). 윤활유 관리는 주로 3등 기관사 업무입니다.","연료유 수급·관리는 2등 기관사 업무입니다.","연료유 청정기는 2등 기관사 업무입니다."],"t":"2기사 = 연료유·발전기 / 3기사 = 윤활유"},"2020-2-직무일반-3":{"w":"기관 비품(예비품)은 피스톤, 실린더 라이너, 안전밸브 스프링처럼 교체용 부품입니다. 실린더 오일은 소모품입니다.","x":["정답(아닌 것). 실린더 오일은 소모품입니다.","비품(예비품)입니다.","비품입니다.","비품입니다."],"t":"오일 = 소모품, 부품 = 비품"},"2020-2-직무일반-4":{"w":"쓸 수 없는 소모품도 바다에 버리면 안 되고 육상 수용시설에 처리해야 합니다.","x":["변질되지 않게 보관합니다.","무거운 것은 고정합니다.","사용량과 잔량을 관리합니다.","정답(옳지 않은 것). 바다에 버리면 안 됩니다."],"t":"폐기물 = 해양 투기 금지"},"2020-2-직무일반-5":{"w":"부식으로 얇아진 외판 두께는 한쪽 면에서 초음파를 보내 반사 시간으로 두께를 재는 초음파 두께 측정법으로 잽니다.","x":["정답. 두께 측정 = 초음파","자기탐상은 표면 균열 검사용입니다.","다이체크는 표면 균열 검사용입니다.","침투탐상은 표면 균열 검사용입니다."],"t":"두께 측정 = 초음파"},"2020-2-직무일반-6":{"w":"유출된 기름이 퍼지는 것을 막기 위해 선박 주위에 오일펜스를 둘러칩니다. 그 뒤 유회수기로 거두고 흡착재로 닦아 냅니다.","x":["유회수기는 기름을 거두어들이는 장비입니다.","흡착재는 기름을 빨아들이는 재료입니다.","정답. 확산 방지 = 오일펜스","유겔화제는 기름을 굳히는 약제입니다."],"t":"확산 방지 = 오일펜스"},"2020-2-직무일반-7":{"w":"선박에서 나오는 대기오염물질은 황산화물, 질소산화물, 오존층 파괴물질, 휘발성 유기화합물 등입니다. 유기주석 화합물은 선체 도료(방오도료)의 유해물질로 해양오염물질입니다.","x":["황산화물은 대기오염물질입니다.","오존층 파괴물질은 대기오염물질입니다.","질소산화물은 대기오염물질입니다.","정답(아닌 것). 유기주석은 방오도료 물질입니다."],"t":"유기주석(TBT) = 방오도료"},"2020-2-직무일반-10":{"w":"연료유 수급 후 기관일지에는 수급량, 수급 시간, 비중·점도 등 사양을 기록합니다. 선장과 책임사관의 성명은 기록 항목이 아닙니다.","x":["기록합니다.","기록합니다.","정답(아닌 것). 성명은 기록하지 않습니다.","기록합니다."],"t":"수급 기록 = 양·시간·사양"},"2020-2-직무일반-11":{"w":"혈액에서 산소를 운반하는 것은 적혈구(헤모글로빈)입니다.","x":["백혈구는 면역을 담당합니다.","정답. 적혈구","혈소판은 혈액 응고를 담당합니다.","감마 글로불린은 항체입니다."],"t":"적혈구 = 산소 운반"},"2020-2-직무일반-12":{"w":"검역 감염병에는 콜레라, 페스트, 황열 등이 있습니다. 장티푸스는 검역 감염병이 아닙니다.","x":["검역 감염병입니다.","정답(아닌 것). 장티푸스","검역 감염병입니다.","검역 감염병입니다."],"t":"검역 = 콜레라·페스트·황열"},"2020-2-직무일반-13":{"w":"관절의 뼈가 제자리에서 빠져나온 상태를 탈구라 합니다.","x":["염좌는 인대가 늘어난 것입니다.","타박상은 부딪힌 상처입니다.","정답. 탈구","골절은 뼈가 부러진 것입니다."],"t":"탈구 = 관절이 빠짐"},"2020-2-직무일반-14":{"w":"한 실린더만 배기온도가 높은 원인은 연료분사시기 늦음(후연소), 배기밸브 누설, 연료분사밸브 누설(불량 분무) 등 그 실린더의 문제입니다. 냉각수 압력 상승은 배기온도를 높이는 원인이 아닙니다.","x":["분사밸브가 새면 연소가 나빠져 배기온도가 오릅니다.","정답(아닌 것). 냉각수 압력 상승은 원인이 아닙니다.","배기밸브가 새면 고온가스가 새어 배기온도가 오릅니다.","분사시기가 늦으면 후연소로 배기온도가 오릅니다."],"t":"한 실린더 배기온도↑ = 분사시기 늦음, 밸브 누설"},"2020-2-직무일반-17":{"w":"디젤발전기의 경보·정지 조건은 과속도, 윤활유 압력 저하, 냉각수 온도 상승 등입니다. 소기 압력 저하는 발전기 정지 조건이 아닙니다.","x":["조건입니다.","조건입니다.","정답(아닌 것). 소기 압력 저하","조건입니다."],"t":"D/G 정지 = 과속·LO 압력↓·냉각수 온도↑"},"2020-2-직무일반-20":{"w":"정전기를 막으려면 접지하고, 마찰을 줄이고, 합성섬유 옷을 피하며, 전도성 물질을 씁니다. 비전도성 물질은 정전기를 쌓이게 합니다.","x":["대책입니다.","정답(옳지 않은 것). 비전도성 물질은 정전기를 쌓습니다.","대책입니다.","대책입니다."],"t":"정전기 = 접지·전도성"},"2020-2-직무일반-23":{"w":"선원법의 근로시간·휴식시간 기준은 원양어선 등 일부 어선에는 적용되지 않습니다(어선 특례).","x":["적용됩니다.","적용됩니다.","정답(적용 제외). 원양어선","적용됩니다."],"t":"원양어선 = 근로시간 기준 적용 제외"},"2020-2-직무일반-24":{"w":"선박법상 기관과 돛을 함께 쓰면서 주로 기관으로 추진하는 선박은 기선입니다. 주로 돛을 쓰면 범선입니다.","x":["정답. 주로 기관 = 기선","주로 돛 = 범선","부선은 추진장치가 없는 배입니다.","기범선은 선박법상 분류가 아닙니다."],"t":"주로 기관 = 기선"},"2020-2-직무일반-25":{"w":"해양오염방지관리인은 선박의 오염방지설비 정비·점검, 방제 자재 관리, 기름·폐기물기록부 기록·보관 등을 합니다. 해양시설 오염물질기록부는 해양시설(육상)의 업무입니다.","x":["업무입니다.","정답(아닌 것). 해양시설 기록부","업무입니다.","업무입니다."],"t":"오염방지관리인 = 선박 기록부·설비"},"2020-2-영어-1":{"w":"아연판(zinc plate)은 해수가 흐르는 냉각기의 전식 방지용으로 붙입니다. \"주기관 윤활유 냉각기의 아연판 4개를 교체했다.\"","x":["크랭크케이스에는 아연판을 붙이지 않습니다.","정답. M/E L.O. cooler(해수 냉각)","공기탱크에는 아연판이 없습니다.","연료유 가열기에는 아연판이 없습니다."],"t":"zinc plate = 해수 냉각기 부식 방지"},"2020-2-영어-3":{"w":"\"시간당 몇 톤으로 펌핑하십니까?\" 시간당 공급량을 묻습니다.","x":["정답. 시간당 공급량","틀립니다.","틀립니다.","틀립니다."],"t":"per hour = 시간당"},"2020-2-영어-4":{"w":"발전기관은 선박에 전력(electric power)과 조명(lighting)을 공급합니다.","x":["틀립니다.","틀립니다.","정답. electric power, lighting","틀립니다."],"t":"generator = power & lighting"},"2020-2-영어-6":{"w":"2행정 기관은 크랭크축 1회전(one revolution)에 1사이클을 마칩니다.","x":["틀립니다.","정답. One revolution","4행정입니다.","틀립니다."],"t":"2행정 = 1회전, 4행정 = 2회전"},"2020-2-영어-7":{"w":"at once = 즉시 = instantly.","x":["때때로","자주","자주","정답. instantly"],"t":"at once = instantly"},"2020-2-영어-8":{"w":"\"대리점을 통해(through) 연료유 500톤을 주문했지요?\"","x":["정답. through = ~을 통해","during = ~동안","before = ~전에","after = ~후에"],"t":"through agent = 대리점을 통해"},"2020-2-영어-10":{"w":"indicator card(지압도)는 압력-부피 선도(P-V diagram)입니다.","x":["분사시기 선도가 아닙니다.","틀립니다.","정답. Pressure - volume diagram","틀립니다."],"t":"indicator card = P-V 선도"},"2020-2-영어-13":{"w":"흡입행정은 TDC에서 시작해 BDC에서 끝납니다.","x":["정답. TDC, BDC","반대입니다.","틀립니다.","틀립니다."],"t":"흡입 = TDC → BDC"},"2020-2-영어-14":{"w":"선박의 열교환기는 대부분 뜨거운 액체를 해수와 청수로 식히는 냉각기입니다.","x":["틀립니다.","틀립니다.","정답. sea water and fresh water","틀립니다."],"t":"cooler = 해수·청수"},"2020-2-영어-15":{"w":"실린더 안 가스 온도는 연소가 일어나는 작동(working) 행정에서 가장 높습니다.","x":["흡입이 아닙니다.","압축이 아닙니다.","정답. working","배기가 아닙니다."],"t":"최고 온도 = 작동행정"},"2020-2-영어-16":{"w":"오일 미스트 검출기는 크랭크실 안 유증기의 농도(concentration)가 발화 전 위험 수준에 이르면 경보를 울리고 감속시킵니다.","x":["연소가 아닙니다.","정답. concentration = 농도","증발이 아닙니다.","응축이 아닙니다."],"t":"mist concentration = 유증기 농도"},"2020-2-영어-17":{"w":"기계효율 = BHP ÷ IHP 입니다.","x":["반대입니다.","틀립니다.","틀립니다.","정답. BHP/IHP"],"t":"기계효율 = BHP / IHP"},"2020-2-영어-18":{"w":"기밀 유지, 열 전달, 라이너 윤활은 피스톤링(piston ring)의 역할입니다.","x":["정답. The purpose of piston ring","피스톤이 아닙니다.","배기밸브가 아닙니다.","라이너가 아닙니다."],"t":"piston ring = 기밀·열전달·윤활"},"2020-2-영어-19":{"w":"tail shaft = 프로펠러축(propeller shaft)입니다.","x":["stern shaft는 쓰이지만 정답 표현이 아닙니다.","정답. Propeller shaft","Cam shaft = 캠축","Thrust shaft = 추력축"],"t":"tail shaft = propeller shaft"},"2020-2-영어-21":{"w":"기계의 속도를 일정하게 유지하는 장치는 Governor(조속기)입니다.","x":["정답. Governor","증발기","안정기","지시기"],"t":"governor = 조속기"},"2020-2-영어-22":{"w":"절연체(insulator)는 전류 흐름에 높은 저항을 주는 물질입니다.","x":["정답. 높은 저항","도체입니다.","틀립니다.","틀립니다."],"t":"insulator = 높은 저항"},"2020-2-영어-23":{"w":"과급기는 배기가스(exhaust gas)로 돌아가는 가스터빈이 원심 송풍기를 돌리는 장치입니다.","x":["체인으로 구동하지 않습니다.","정답. exhaust gas","blower는 구동되는 쪽입니다.","압축공기로 구동하지 않습니다."],"t":"turbocharger = 배기가스 터빈"},"2020-3-기관1-2":{"w":"2행정 기관에서 피스톤이 상사점 부근에 오면 압축이 끝나 연료가 분사됩니다. 소기공과 배기밸브는 하사점 부근에서 열립니다.","x":["배기밸브는 하사점 전에 열립니다.","소기공은 하사점 부근에서 열립니다.","안전밸브는 이상 압력 때만 열립니다.","정답. 상사점 부근 = 연료 분사"],"t":"상사점 = 분사, 하사점 = 소기·배기"},"2020-3-기관1-6":{"w":"고정 피치 프로펠러를 구동하는 주기관의 출력은 회전수의 세제곱에 비례해 증가합니다(프로펠러 법칙).","x":["틀립니다.","토크는 제곱에 비례합니다.","정답. 세제곱 비례 증가","감소하지 않습니다."],"t":"출력 ∝ N³, 토크 ∝ N²"},"2020-3-기관1-10":{"w":"보슈형 펌프는 래크로 플런저를 회전시켜 경사홈의 위치를 바꿔 유효행정(토출량)을 조절합니다.","x":["토출밸브를 돌리지 않습니다.","정답. 플런저를 회전","스필밸브는 다른 형식입니다.","흡입밸브로 조절하지 않습니다."],"t":"보슈형 = 플런저 회전"},"2020-3-기관1-11":{"w":"유압식 조속기의 보상용 니들 밸브를 너무 적게 열면 보상 작용이 느려져 기관 속도 변화가 신속하지 못합니다. 너무 많이 열면 난조(헌팅, 맥동 운전)가 생깁니다.","x":["너무 많이 열었을 때의 현상입니다.","연료 제한 기능과 관계없습니다.","속도가 급상승하지 않습니다.","정답. 적게 열면 응답이 느립니다."],"t":"니들밸브 많이 열림 = 헌팅, 적게 열림 = 둔함"},"2020-3-기관1-12":{"w":"같은 압력에서 포화증기를 더 가열해 포화온도보다 높아진 증기가 과열증기입니다. 따라서 온도가 가장 높습니다.","x":["정답. 과열증기가 가장 높습니다.","습포화증기는 포화온도입니다.","건포화증기도 포화온도입니다.","포화증기는 포화온도입니다."],"t":"과열증기 > 포화증기(습·건 모두 포화온도)"},"2020-3-기관1-18":{"w":"30°에서 20[cm]를 나아가면 한 바퀴(360°)에는 20 × (360 ÷ 30) = 240[cm]를 나아갑니다.","x":["틀립니다.","틀립니다.","틀립니다.","정답. 20 × 12 = 240[cm]"],"t":"피치 = 부분 피치 × 360 / 각도"},"2020-3-기관1-22":{"w":"선내에서 연료유 점도를 간단히 재는 기구는 비스코미터(점도계)입니다.","x":["정답. 비스코미터","스폿 테스트는 윤활유 오염도를 봅니다.","플로미터는 유량계입니다.","타코미터는 회전계입니다."],"t":"viscometer = 점도계"},"2020-3-기관1-23":{"w":"유압 작동유는 유동점이 낮고, 점도지수가 크며, 중성이고, 인화점이 높아야 화재 위험이 적습니다.","x":["유동점이 낮아야 합니다.","점도지수가 커야 합니다.","중성이어야 합니다.","정답(옳지 않은 것). 인화점은 높아야 합니다."],"t":"작동유 = 인화점 높게"},"2020-3-기관2-1":{"w":"플래시식 조수장치에서 가열용 증기 압력이 높으면 오리피스로 감압합니다.","x":["이젝터는 진공을 만듭니다.","증발기가 아닙니다.","정답. 오리피스","기수분리기는 물방울을 분리합니다."],"t":"오리피스 = 감압"},"2020-3-기관2-2":{"w":"한쪽으로만 물을 빨아들이는 편흡입 임펠러는 앞뒤 압력 차가 커서 축 추력이 생기기 쉽습니다. 양흡입, 평형공, 스러스트 베어링은 추력 대책입니다.","x":["추력이 상쇄됩니다.","추력 대책입니다.","추력 대책입니다.","정답. 편흡입 임펠러"],"t":"편흡입 = 축 추력 발생"},"2020-3-기관2-4":{"w":"왕복펌프는 피스톤·플런저·버킷이 왕복하며 액체를 보내는 펌프입니다. 트로코이드 펌프는 내접 기어 형태의 회전펌프입니다.","x":["피스톤 펌프는 왕복펌프입니다.","정답(아닌 것). 트로코이드 펌프는 회전펌프입니다.","플런저 펌프는 왕복펌프입니다.","버킷 펌프는 왕복펌프입니다."],"t":"트로코이드 = 회전펌프"},"2020-3-기관2-6":{"w":"유량제어밸브는 흐르는 기름의 양(속도)을 조절하는 밸브로, 교축밸브(스로틀밸브)가 대표적입니다. 감압·릴리프·시퀀스밸브는 압력제어밸브입니다.","x":["감압밸브는 압력제어밸브입니다.","정답. 교축밸브 = 유량제어밸브","릴리프밸브는 압력제어밸브입니다.","시퀀스밸브는 압력제어밸브입니다."],"t":"유량제어 = 교축밸브 / 압력제어 = 릴리프·감압·시퀀스"},"2020-3-기관2-8":{"w":"양묘기(윈드라스)는 닻과 닻줄을 감아올리는 장치로 체인 드럼(워핑드럼·체인 휠), 마찰 브레이크, 클러치, 조종 핸들 등으로 이루어집니다. 슬루잉 윈치는 크레인·데릭의 붐을 좌우로 돌리는 윈치입니다.","x":["조종 핸들은 양묘기의 구성품입니다.","체인 드럼은 양묘기의 구성품입니다.","정답(아닌 것). 슬루잉 윈치는 하역장치에 속합니다.","마찰 브레이크는 양묘기의 구성품입니다."],"t":"슬루잉 = 붐 좌우 회전(하역장치)"},"2020-3-기관2-10":{"w":"선저폐수를 선외로 배출하려면 기름여과장치(15ppm)가 필요합니다.","x":["정답. 기름여과장치","유청정장치는 연료·윤활유용입니다.","오수처리장치는 분뇨용입니다.","폐유소각장치는 슬러지용입니다."],"t":"빌지 배출 = 기름여과장치"},"2020-3-기관2-11":{"w":"불응축 가스(공기)가 들어가면 응축기에서 응축되지 않아 응축(압축) 압력이 높아지고, 동력이 늘며 냉동능력이 떨어집니다.","x":["흡입 압력과 관계없습니다.","응축 압력은 높아집니다.","냉동능력은 나빠집니다.","정답. 압축 압력 상승"],"t":"불응축 가스 = 고압 상승"},"2020-3-기관2-14":{"w":"증발관에 서리가 끼면 전열이 나빠지므로 제상장치로 서리를 제거해 전열작용을 좋게 합니다.","x":["부하경감장치는 기동 부하를 줄입니다.","배기장치가 아닙니다.","정답. 제상장치","건조장치는 수분을 제거합니다."],"t":"제상 = 전열 회복"},"2020-3-기관2-15":{"w":"실내에서 밖으로 열이 빠져나가는 겨울철 조건이므로 공급 공기를 가열해야 합니다. 가열하면 상대습도가 떨어지므로 가습도 함께 해야 합니다.","x":["냉각·감습은 여름철 조건입니다.","냉각은 맞지 않습니다.","가열은 맞지만 감습은 맞지 않습니다.","정답. 겨울철 = 가열 + 가습"],"t":"여름 = 냉각·감습, 겨울 = 가열·가습"},"2020-3-기관2-18":{"w":"선반으로 절삭, 보링, 널링, 나사 가공 등을 할 수 있습니다. 단조는 두드려 성형하는 작업으로 선반 작업이 아닙니다.","x":["선반 작업입니다.","정답(아닌 것). 단조","선반 작업입니다.","선반 작업입니다."],"t":"단조 = 해머·프레스"},"2020-3-기관2-19":{"w":"용접 끝부분의 용융지가 식으며 오목하게 들어가 생기는 결함은 크레이터이며, 균열·슬래그 섞임이 생기기 쉽습니다.","x":["정답. 크레이터","스패터는 튀는 금속 알갱이입니다.","언더컷은 모재가 파인 결함입니다.","오버랩은 용착금속이 넘친 결함입니다."],"t":"크레이터 = 용접 끝의 오목부"},"2020-3-기관2-20":{"w":"유체를 한 방향으로만 흐르게 해 역류를 막는 밸브는 체크 밸브입니다.","x":["릴리프 밸브는 압력 제한용입니다.","정답. 체크 밸브","안전 밸브는 과압 방출용입니다.","니들 밸브는 미세 유량 조절용입니다."],"t":"체크 밸브 = 역류 방지"},"2020-3-기관3-1":{"w":"금속(구리, 알루미늄, 철)은 온도가 오르면 저항이 커지고, 탄소·반도체는 온도가 오르면 저항이 작아집니다.","x":["금속은 저항이 커집니다.","금속은 저항이 커집니다.","정답. 탄소","금속은 저항이 커집니다."],"t":"탄소·반도체 = 부(−)의 온도계수"},"2020-3-기관3-4":{"w":"I = V ÷ R = 440 ÷ 125 = 3.52[A]입니다.","x":["틀린 값입니다.","정답. 440 ÷ 125 = 3.52[A]","틀린 값입니다.","틀린 값입니다."],"t":"I = V / R"},"2020-3-기관3-6":{"w":"전압이 2배면 전류도 2배(I = V/R), 전력은 P = V²/R 이므로 4배가 됩니다.","x":["전력이 틀립니다.","정답. 전류 2배, 전력 4배","틀립니다.","틀립니다."],"t":"P ∝ V²"},"2020-3-기관3-9":{"w":"그림은 세 축전지의 (+)끼리, (−)끼리 연결한 병렬 연결입니다. 병렬 연결하면 전압은 그대로 12[V]이고 용량은 더해져 80 × 3 = 240[Ah]가 됩니다.","x":["축전지 1개의 값입니다.","정답. 병렬 = 전압 그대로, 용량 합산","직렬 연결일 때의 값입니다.","전압과 용량을 모두 더한 잘못된 값입니다."],"t":"축전지 직렬 = 전압 합, 병렬 = 용량 합"},"2020-3-기관3-12":{"w":"Ns = 120f ÷ P = 120 × 60 ÷ 4 = 1,800[rpm]입니다.","x":["8극일 때입니다.","6극일 때입니다.","정답. 1,800[rpm]","2극일 때입니다."],"t":"60Hz: 2극 3,600 / 4극 1,800 / 6극 1,200"},"2020-3-기관3-13":{"w":"전압을 높이려면 직렬로 연결합니다. 24 ÷ 1.2 = 20개를 직렬로 연결합니다.","x":["정답. 20개 직렬","병렬은 전압이 그대로입니다.","12개 직렬은 14.4[V]입니다.","병렬은 전압이 그대로입니다."],"t":"전압↑ = 직렬, 용량↑ = 병렬"},"2020-3-기관3-15":{"w":"철심을 얇게 성층하면 맴돌이 전류(와류) 손실을 줄일 수 있습니다.","x":["정답. 와류손 방지","히스테리시스손은 규소강으로 줄입니다.","마찰손과 관계없습니다.","표유부하손과 관계없습니다."],"t":"성층 = 와류손↓"},"2020-3-기관3-16":{"w":"MCCB = 배선용 차단기(Molded Case Circuit Breaker), PB = 푸시 버튼 스위치입니다.","x":["열동 계전기는 THR입니다.","정답. 배선용 차단기, 푸시 버튼","틀립니다.","기중 차단기는 ACB입니다."],"t":"MCCB = 배선용 차단기"},"2020-3-직무일반-3":{"w":"당직 인수 전에는 기관장의 당직지침과 특별 지시, 진행 중인 작업과 잠재적 위험, 기관일지 작성 상태, 기계 상태 등을 확인합니다. 내부통신시스템 사용 방법은 당직 인수 때 확인하는 사항이 아닙니다.","x":["기관일지 상태를 확인합니다.","정답(아닌 것). 통신시스템 사용법은 평소 숙지 사항입니다.","기관장 지침을 확인합니다.","진행 중인 작업과 위험을 확인합니다."],"t":"당직 인수 = 지시사항·진행 작업·기계 상태"},"2020-3-직무일반-5":{"w":"PSC(항만국 통제)의 기준 미달선은 감항성이 확보되지 않았거나 승선자가 위험한 경우, 정비 불량으로 장비 성능이 크게 떨어진 경우입니다.","x":["틀립니다.","틀립니다.","틀립니다.","틀립니다."],"t":"기준 미달선 = 감항성·장비 불량"},"2020-3-직무일반-6":{"w":"슬러지는 소각하거나, 육상으로 양륙하거나, 저장 후 수용시설로 보냅니다. 15[ppm] 기름여과장치로 처리하는 것은 빌지입니다.","x":["정답(옳지 않은 것). 여과장치는 빌지용입니다.","소각합니다.","양륙합니다.","저장 후 이송합니다."],"t":"슬러지 ≠ 여과장치"},"2020-3-직무일반-8":{"w":"일산화탄소(CO)는 헤모글로빈과 산소보다 훨씬 강하게 결합해 적은 양으로도 산소 운반을 막습니다.","x":["정답. 일산화탄소","이산화탄소가 아닙니다.","미연탄화수소가 아닙니다.","이산화질소가 아닙니다."],"t":"CO = 헤모글로빈 결합"},"2020-3-직무일반-9":{"w":"연료유 수급 후 기관일지에는 수급량, 수급 시간, 비중·점도 등 사양을 기록합니다. 선장과 책임사관의 성명은 기록 항목이 아닙니다.","x":["기록합니다.","기록합니다.","정답(아닌 것). 성명은 기록하지 않습니다.","기록합니다."],"t":"수급 기록 = 양·시간·사양"},"2020-3-직무일반-11":{"w":"혈액에서 산소를 운반하는 것은 적혈구(헤모글로빈)입니다.","x":["백혈구는 면역을 담당합니다.","정답. 적혈구","혈소판은 혈액 응고를 담당합니다.","감마 글로불린은 항체입니다."],"t":"적혈구 = 산소 운반"},"2020-3-직무일반-16":{"w":"정전 후 예비발전기가 투입되면 Sequential start program(순차 기동 프로그램)이 주요 전동기를 차례로 자동 기동합니다.","x":["정답. 순차 기동","역전력 보호입니다.","우선 차단입니다.","수동 기동입니다."],"t":"sequential start = 순차 자동 기동"},"2020-3-직무일반-21":{"w":"고정식 CO₂ 소화장치는 조작이 쉽고, 설명서를 게시하고, 승인된 기기를 써야 합니다. 사람이 있을 수 있으므로 자동 방출이 아니라 경보 후 수동으로 방출합니다.","x":["조건입니다.","조건입니다.","조건입니다.","정답(옳지 않은 것). CO₂는 자동 방출하지 않습니다."],"t":"CO₂ = 경보 후 수동 방출"},"2020-3-영어-3":{"w":"힘의 단위는 뉴턴(Newton)입니다.","x":["Joule은 일·에너지 단위입니다.","정답. Newton","Watt는 일률 단위입니다.","Horsepower는 마력입니다."],"t":"힘 N, 에너지 J, 일률 W"},"2020-3-영어-5":{"w":"Salinometer = 염분 농도계 입니다.","x":["산소 농도계가 아닙니다.","정답. 염분 농도계","틀립니다.","틀립니다."],"t":"saline = 염분"},"2020-3-영어-8":{"w":"hair crack = 머리카락처럼 가는 미세한 균열입니다.","x":["부식이 아닙니다.","전식이 아닙니다.","정답. 미세한 균열","침식이 아닙니다."],"t":"hair crack = 미세 균열"},"2020-3-영어-12":{"w":"portable fire extinguisher = 휴대식 소화기 입니다.","x":["고정식은 fixed입니다.","정답. 휴대식 소화기","경보기가 아닙니다.","자동이 아닙니다."],"t":"portable = 휴대식"},"2020-3-영어-14":{"w":"디젤 발전기는 디젤기관(a diesel engine)과 발전기(an electric generator)를 결합해 전기 에너지를 만듭니다.","x":["actuator = 작동기","가스기관·변환기가 아닙니다.","가솔린기관·압축기가 아닙니다.","정답. diesel engine + electric generator"],"t":"D/G = diesel + generator"},"2020-3-영어-16":{"w":"오일 미스트 검출기는 크랭크실 안 유증기의 농도(concentration)가 발화 전 위험 수준에 이르면 경보를 울리고 감속시킵니다.","x":["연소가 아닙니다.","정답. concentration = 농도","증발이 아닙니다.","응축이 아닙니다."],"t":"mist concentration = 유증기 농도"},"2020-3-영어-17":{"w":"vapor compression type = 증기 압축식 입니다. \"대부분의 기계식 냉동장치는 증기 압축식이다.\"","x":["정답. 증기 압축식","흡수식은 absorption type입니다.","증기 분사식은 steam jet type입니다.","냉매 분사식이 아닙니다."],"t":"vapor compression = 증기 압축식"},"2020-3-영어-18":{"w":"fuel injection occurs too early = 연료분사가 너무 빠르면.","x":["연소가 아니라 분사입니다.","틀립니다.","늦으면이 아닙니다.","정답. 연료분사가 너무 빠르면"],"t":"too early = 너무 빠른"},"2020-3-영어-21":{"w":"\"과열기(superheater)는 주로 증기 속의 수분을 없애는 데 쓴다.\" 포화증기를 더 가열해 건조한 과열증기로 만듭니다.","x":["연료 가열이 아닙니다.","급수 가열은 절탄기입니다.","압력은 높이지 않습니다.","정답. remove moisture from steam"],"t":"superheater = 수분 제거·과열"},"2020-3-영어-22":{"w":"뜨겁고 찬 정도를 재는 도구는 Thermometer(온도계)입니다.","x":["습도계","정답. Thermometer","열량계","염분계"],"t":"thermometer = 온도계"},"2020-4-기관1-1":{"w":"압축비 = (행정부피 + 압축부피) ÷ 압축부피 = (1,900 + 100) ÷ 100 = 20입니다. 회전수는 계산에 필요 없습니다.","x":["틀린 값입니다.","틀린 값입니다.","행정부피 ÷ 압축부피만 한 값입니다.","정답. 2,000 ÷ 100 = 20"],"t":"압축비 = (Vs + Vc) / Vc"},"2020-4-기관1-2":{"w":"중·대형 2행정 디젤기관은 배기밸브로 위로 배기하고 소기공으로 아래에서 소기하는 유니플로 소기식을 많이 씁니다. 소기 효율이 가장 좋습니다.","x":["정답. 유니플로 소기식","루프 소기식은 중소형에 씁니다.","횡단 소기식은 소형에 씁니다.","와류 소기식이 아닙니다."],"t":"대형 2행정 = 유니플로 소기"},"2020-4-기관1-3":{"w":"피스톤핀 보스부는 열팽창으로 핀이 끼이지 않도록 핀과 직각 방향의 열팽창이 작아야(또는 여유가 있게 설계) 합니다. 열팽창이 커야 한다는 것은 틀립니다.","x":["맞습니다.","맞습니다.","정답(옳지 않은 것). 보스부 열팽창은 작아야 합니다.","맞습니다."],"t":"피스톤 = 열팽창 작게"},"2020-4-기관1-4":{"w":"오일 스크레이퍼링(오일링)은 라이너 벽의 윤활유를 긁어내려 연소실로 올라가는 것을 막고 라이너 내벽에 고르게 분포시킵니다. 압축링은 가스 기밀과 피스톤 열을 라이너로 전달합니다.","x":["열은 피스톤에서 실린더(라이너) 쪽으로 방출합니다.","압축링은 연소가스의 누설을 막습니다.","연소실로 들어가는 것을 막습니다.","정답. 윤활유를 고르게 분포"],"t":"오일링 = 윤활유 분포·긁어내림"},"2020-4-기관1-5":{"w":"플라이휠은 같은 무게라면 두께보다 지름을 크게 하는 것이 관성모멘트가 커서 회전을 고르게 하는 데 효과적입니다.","x":["정답(옳지 않은 것). 지름을 크게 하는 것이 효과적입니다.","저속 회전을 가능하게 합니다.","실린더 수가 적으면 더 커야 합니다.","고속기관은 작아도 됩니다."],"t":"플라이휠 = 지름이 효과적(관성모멘트)"},"2020-4-기관1-6":{"w":"4행정 기관의 배기행정 말기~흡기행정 초기(상사점 부근)에는 실린더 안 가스 압력이 거의 없는데, 피스톤과 커넥팅로드의 관성력이 피스톤을 위로 끌어올립니다. 이 관성력이 크랭크핀 볼트를 잡아당기므로 인장력이 가장 큽니다.","x":["이때는 관성력보다 압축 압력이 작용합니다.","압축 말기~작동 초기에는 가스 압력이 볼트를 누르는 방향(압축)으로 작용합니다.","이때는 관성력이 크지 않습니다.","정답. 가스 압력 없이 관성력만 작용 → 인장력 최대"],"t":"크랭크핀 볼트 인장 최대 = 배기 말~흡기 초(상사점)"},"2020-4-기관1-7":{"w":"지시마력은 강스프링으로 그린 PV 선도(압력-부피 선도)의 면적으로 평균유효압력을 구해 계산합니다.","x":["정답. PV 선도","수인 선도는 연소 상태를 봅니다.","최고압력 선도가 아닙니다.","약스프링 선도는 흡·배기 상태를 봅니다."],"t":"지시마력 = PV 선도 면적"},"2020-4-기관1-8":{"w":"2행정: Pi = P·A·L·N·Z ÷ 4,500 = 7.5 × 400 × 0.2 × 300 × 6 ÷ 4,500 = 240[PS] ≒ 176[kW]입니다.","x":["4행정으로 잘못 계산한 값입니다.","정답. 176[kW]","틀립니다.","틀립니다."],"t":"2행정 N 그대로, 4행정 N/2"},"2020-4-기관1-9":{"w":"후연소가 길어지면 연소가 늦게까지 이어져 배기온도가 오르고, 연료소비율이 늘며, 기관이 과열되고 배기색이 나빠집니다.","x":["배기온도는 올라갑니다.","연료소비율은 늘어납니다.","배기색은 검어집니다.","정답. 기관이 과열됩니다."],"t":"후연소↑ = 과열·배기온도↑"},"2020-4-기관1-10":{"w":"과급하면 같은 기관에서 출력이 늘고, 마력당 무게가 줄며, 평균유효압력이 높아집니다.","x":["가벼워집니다.","저질유 사용과 관계없습니다.","정답. 출력 증대","높아집니다."],"t":"과급 = 출력↑"},"2020-4-기관1-12":{"w":"안전밸브의 방출능력은 증기 정지밸브를 닫고 최대 연소 상태로 운전해 압력이 일정 한도 이상 오르지 않는지 확인하는 축기시험으로 확인합니다.","x":["정답. 축기시험","압력시험이 아닙니다.","진공시험이 아닙니다.","수압시험은 강도·누설 시험입니다."],"t":"안전밸브 방출능력 = 축기시험"},"2020-4-기관1-13":{"w":"보일러 효율은 증기 발생에 실제로 쓰인 열량을 연료의 총 발열량으로 나눈 비율입니다.","x":["전열면적은 면적입니다.","증발량은 증기 양입니다.","보일러 마력은 능력 단위입니다.","정답. 보일러 효율"],"t":"보일러 효율 = 유효열 / 공급열"},"2020-4-기관1-15":{"w":"증기터빈의 노즐은 증기를 팽창시켜 열에너지를 속도에너지로 바꿉니다.","x":["로터는 회전체입니다.","블레이드는 속도에너지를 회전력으로 바꿉니다.","정답. 노즐","더미 피스톤은 추력 평형 장치입니다."],"t":"노즐 = 열 → 속도"},"2020-4-기관1-16":{"w":"역전장치에는 직접 역전(캠축 이동식 등)과 간접 역전(역전기어, 가변 피치 프로펠러)이 있습니다. 대형 선박은 주로 기관 자체를 역회전시키는 직접 역전방식을 씁니다.","x":["맞습니다.","맞습니다.","정답(옳지 않은 것). 대형선은 직접 역전입니다.","맞습니다."],"t":"대형 저속기관 = 직접 역전"},"2020-4-기관1-17":{"w":"추진 축계는 프로펠러축, 추력축, 중간축으로 이루어집니다. 캠축은 기관 내부 부품입니다.","x":["구성 요소입니다.","구성 요소입니다.","구성 요소입니다.","정답(아닌 것). 캠축"],"t":"캠축 = 기관 부품"},"2020-4-기관1-18":{"w":"프로펠러는 알루미늄 청동, 고력 황동, 스테인리스강, 주강 등으로 만듭니다. 주철은 약하고 잘 깨져 쓰지 않습니다.","x":["재료입니다.","재료입니다.","재료입니다.","정답(아닌 것). 고급 주철"],"t":"프로펠러 = 동합금·스테인리스"},"2020-4-기관1-19":{"w":"프로펠러에 의한 축계 진동은 피치 불균일, 캐비테이션, 정적·동적 불평형 등으로 생깁니다. 날개 전개면적이 작은 것은 직접 원인이 아닙니다.","x":["원인입니다.","정답(아닌 것). 전개면적","원인입니다.","원인입니다."],"t":"프로펠러 진동 = 피치·캐비테이션·불평형"},"2020-4-기관1-21":{"w":"디젤 연료의 착화성은 세탄가로 나타냅니다. 옥탄가는 가솔린의 노킹 저항성입니다.","x":["옥탄가는 가솔린용입니다.","헵탄가는 없습니다.","정답. 세탄가","전산가는 산성도입니다."],"t":"디젤 = 세탄가, 가솔린 = 옥탄가"},"2020-4-기관1-23":{"w":"연료유를 저장·운반할 때 화재 위험의 기준이 되는 성질은 인화점입니다.","x":["착화점이 아닙니다.","발화점이 아닙니다.","정답. 인화점","유동점이 아닙니다."],"t":"화재 위험 = 인화점"},"2020-4-기관1-25":{"w":"디젤기관 윤활유는 온도 변화에도 점도가 잘 변하지 않는 점도지수가 큰 윤활유가 적절합니다.","x":["점도가 크기만 하면 마찰 손실이 큽니다.","정답. 점도지수가 큰 윤활유","항유화성은 커야 합니다.","산화안정도는 커야 합니다."],"t":"좋은 윤활유 = 점도지수↑"},"2020-4-기관2-2":{"w":"한쪽으로만 물을 빨아들이는 편흡입 임펠러는 앞뒤 압력 차가 커서 축 추력이 생기기 쉽습니다. 양흡입, 평형공, 스러스트 베어링은 추력 대책입니다.","x":["추력이 상쇄됩니다.","추력 대책입니다.","추력 대책입니다.","정답. 편흡입 임펠러"],"t":"편흡입 = 축 추력 발생"},"2020-4-기관2-3":{"w":"회전식 펌프는 기어, 나사, 베인 펌프 등입니다. 제트펌프는 고속 유체의 흐름으로 빨아올리는 특수 펌프입니다.","x":["정답(아닌 것). 제트펌프","회전식입니다.","회전식입니다.","회전식입니다."],"t":"제트펌프 = 이젝터 원리"},"2020-4-기관2-5":{"w":"사이드 스러스터는 선박을 옆으로 움직이는 추진장치로, 선수나 선미 부근의 수면 아래에 옆으로 뚫린 터널 안에 설치합니다.","x":["갑판에 설치하지 않습니다.","정답. 선수·선미 부근 수면 아래","크랭크축 끝이 아닙니다.","기관실 안쪽이 아닙니다."],"t":"사이드(바우) 스러스터 = 수면 아래 터널"},"2020-4-기관2-6":{"w":"불활성가스장치의 공급주관 가스 속 산소 농도는 5[%] 이하, 화물탱크 안은 8[%] 이하로 유지해야 합니다.","x":["틀립니다.","정답. 5[%] 이하","탱크 내 기준입니다.","틀립니다."],"t":"IGS 공급 5%↓, 탱크 8%↓"},"2020-4-기관2-7":{"w":"타를 움직이는 힘을 내는 것은 원동기(전동기+유압펌프)입니다.","x":["조종장치는 명령을 보냅니다.","정답. 원동기","추종장치는 타를 명령 각도에 멈춥니다.","타장치는 타와 타두재입니다."],"t":"원동기 = 동력"},"2020-4-기관2-8":{"w":"유면검출기는 분리기 위쪽에 모인 기름층의 두께를 감지해 기름을 배출시킵니다. 감도를 높이면 기름층이 조금만 쌓여도 감지하므로 기름층의 하한 레벨이 높아집니다(얇은 기름층에서도 동작).","x":["상한 레벨이 낮아진다는 설명은 맞지 않습니다.","정답. 감도를 높이면 기름층의 하한 레벨이 높아집니다.","물층의 상한 레벨과는 관계없는 설명입니다.","물층의 하한 레벨과는 관계없는 설명입니다."],"t":"유면검출기 감도↑ → 기름층 하한 레벨↑"},"2020-4-기관2-9":{"w":"선저폐수(빌지)는 기름여과장치로 15[ppm] 이하로 처리한 뒤 해상으로 배출합니다.","x":["해당 명칭의 장치가 아닙니다.","정답. 기름여과장치","오수처리장치는 분뇨용입니다.","소각장치는 슬러지를 태웁니다."],"t":"빌지 처리 = 기름여과장치"},"2020-4-기관2-10":{"w":"폐유(슬러지)는 점도가 높고 이물질이 많아 원심펌프로는 옮기기 어렵습니다. 점도가 높은 액체를 일정하게 보낼 수 있는 기어 펌프가 가장 적당합니다.","x":["정답. 고점도 폐유 = 기어 펌프","원심펌프는 고점도 액체에 적합하지 않습니다.","왕복펌프는 맥동이 커 폐유 공급에 적합하지 않습니다.","축류펌프는 대유량·저양정용입니다."],"t":"고점도 기름 이송 = 기어 펌프"},"2020-4-기관2-11":{"w":"액분리기는 증발기 출구 냉매 가스 속의 냉매액을 분리해 압축기로 액이 들어가지 않게 하고 분리한 액을 증발기 쪽으로 되돌립니다.","x":["정답. 액분리기","유분리기는 윤활유를 분리합니다.","수액기는 액 냉매를 저장합니다.","팽창밸브는 냉매량을 조절합니다."],"t":"액분리기 = 액 냉매 분리"},"2020-4-기관2-12":{"w":"응축기 출구(액관)에는 건조기 → 전자밸브 → 자동팽창밸브 → (증발기) → 증발압력 조절밸브 순서로 설치합니다.","x":["순서가 틀렸습니다.","순서가 틀렸습니다.","순서가 틀렸습니다.","정답. 건조기 → 전자밸브 → 팽창밸브 → 증발압력 조절밸브"],"t":"건조기 → 전자밸브 → 팽창밸브"},"2020-4-기관2-14":{"w":"건공기 1[kg]에 포함된 수증기 질량[kg]을 절대습도라 합니다.","x":["정답. 절대습도","상대습도는 수증기 분압의 비입니다.","비교습도는 포화 절대습도에 대한 비입니다.","포화도는 비교습도와 같습니다."],"t":"절대습도 = 수증기 kg / 건공기 kg"},"2020-4-기관2-15":{"w":"밖에서 안으로 열이 들어오는 여름철 조건이므로 공급 공기를 냉각하고, 습도도 높으므로 감습(제습)합니다.","x":["정답. 여름철 = 냉각 + 감습","가습은 필요하지 않습니다.","가열은 겨울철 조건입니다.","겨울철 조건입니다."],"t":"여름 = 냉각·감습, 겨울 = 가열·가습"},"2020-4-기관2-16":{"w":"연삭숫돌은 숫돌 입자, 입도, 결합도, 조직, 결합제의 5가지로 표기합니다. 거칠기는 표기 항목이 아닙니다.","x":["입도(입자 크기)는 표기합니다.","조직(입자 밀도)은 표기합니다.","결합도(단단한 정도)는 표기합니다.","정답(아닌 것). 거칠기는 표기하지 않습니다."],"t":"숫돌 표기 = 입자·입도·결합도·조직·결합제"},"2020-4-기관2-17":{"w":"스크레이핑은 스크레이퍼로 평면이나 곡면(베어링 면 등)을 조금씩 긁어 정밀하게 다듬는 작업입니다.","x":["구멍 가공은 리밍·보링입니다.","연삭은 숫돌로 합니다.","정답. 평면·곡면의 정밀 다듬질","숫돌 다듬질은 연삭입니다."],"t":"스크레이핑 = 긁어서 정밀 다듬질"},"2020-4-기관2-19":{"w":"외력에 대항해 재료 내부에 생기는 단위 면적당 저항력을 응력이라 합니다.","x":["정답. 응력","변형률은 늘어난 비율입니다.","하중은 외력입니다.","경도는 단단한 정도입니다."],"t":"응력 = 힘 / 면적"},"2020-4-기관2-20":{"w":"기계적 시험은 인장시험, 충격시험, 경도시험, 굽힘시험 등입니다. 이음성능시험은 기계적 시험의 종류가 아닙니다.","x":["기계적 시험입니다.","기계적 시험입니다.","정답(아닌 것). 이음성능시험","기계적 시험입니다."],"t":"기계적 시험 = 인장·충격·경도·굽힘"},"2020-4-기관2-21":{"w":"선박의 저항과 추진력 계산에는 물에 잠긴 부분의 길이인 수선장(수선 길이)을 씁니다.","x":["전장은 배의 전체 길이입니다.","수선간장은 선박 규칙 등에 씁니다.","정답. 수선장","등록장은 등록용 길이입니다."],"t":"저항 계산 = 수선장"},"2020-4-기관2-23":{"w":"조파저항은 배가 만드는 파도에 의한 저항으로, 속력이 빨라질수록 급격히 커집니다.","x":["정답. 증가","감소하지 않습니다.","일정하지 않습니다.","계속 증가합니다."],"t":"조파저항 = 고속에서 커짐"},"2020-4-기관2-24":{"w":"기능상 지장이 없는 범위에서 미리 정한 치수의 허용량을 공차라 합니다.","x":["정답. 공차","해칭은 단면 표시입니다.","스머징은 단면 칠하기입니다.","거칠기는 표면 상태입니다."],"t":"공차 = 허용 범위"},"2020-4-기관3-5":{"w":"6, 12, 4[Ω] 병렬: 1 ÷ (1/6 + 1/12 + 1/4) = 1 ÷ (6/12) = 2[Ω]. 여기에 3[Ω]이 직렬이므로 합성저항은 2 + 3 = 5[Ω]입니다.","x":["틀린 값입니다.","모두 더한 값입니다.","정답. 2 + 3 = 5[Ω]","틀린 값입니다."],"t":"병렬은 역수의 합의 역수"},"2020-4-기관3-8":{"w":"I = V ÷ R = 440 ÷ 125 = 3.52[A]입니다.","x":["틀린 값입니다.","정답. 440 ÷ 125 = 3.52[A]","틀린 값입니다.","틀린 값입니다."],"t":"I = V / R"},"2020-4-기관3-12":{"w":"그림은 세 축전지의 (+)끼리, (−)끼리 연결한 병렬 연결입니다. 병렬 연결하면 전압은 그대로 12[V]이고 용량은 더해져 80 × 3 = 240[Ah]가 됩니다.","x":["축전지 1개의 값입니다.","정답. 병렬 = 전압 그대로, 용량 합산","직렬 연결일 때의 값입니다.","전압과 용량을 모두 더한 잘못된 값입니다."],"t":"축전지 직렬 = 전압 합, 병렬 = 용량 합"},"2020-4-기관3-14":{"w":"열선 길이를 절반으로 하면 저항이 절반이 됩니다. P = V²/R 이므로 같은 전압에서 전력은 2배, 2[kW]가 됩니다.","x":["틀립니다.","틀립니다.","틀립니다.","정답. 2[kW]"],"t":"R 절반 → P 2배"},"2020-4-기관3-16":{"w":"비례추이는 2차(회전자) 저항을 바꾸면 토크 곡선이 슬립 방향으로 비례해 옮겨가는 성질로, 3상 권선형 유도전동기에 해당합니다.","x":["동기전동기가 아닙니다.","농형은 2차 저항을 바꿀 수 없습니다.","직류기가 아닙니다.","정답. 3상 권선형 유도전동기"],"t":"비례추이 = 권선형 유도전동기"},"2020-4-기관3-17":{"w":"전기드릴의 접지선을 선체에 연결하면 누전 시 전류가 선체로 흘러 사람이 감전되지 않습니다.","x":["단락 방지가 아닙니다.","정답. 감전 예방","모터 보호가 아닙니다.","발전기 트립과 관계없습니다."],"t":"접지 = 감전 방지"},"2020-4-기관3-18":{"w":"Ns = 120 × 60 ÷ 6 = 1,200[rpm]. N = Ns × (1 − s) = 1,200 × 0.96 = 1,152[rpm]입니다.","x":["틀린 값입니다.","8극일 때의 값입니다.","동기속도입니다.","정답. 1,200 × 0.96 = 1,152[rpm]"],"t":"N = Ns(1 − s)"},"2020-4-기관3-19":{"w":"맥동 직류를 평탄하게 만드는 회로는 콘덴서를 쓴 평활회로(R-C 평활회로 등)입니다.","x":["정류회로입니다.","저항만으로는 평활이 안 됩니다.","정류회로입니다.","정답. R-C 평활회로"],"t":"평활 = C 사용"},"2020-4-기관3-22":{"w":"빛을 받으면 전류가 흐르는 포토 다이오드가 광센서로 쓰입니다.","x":["증폭 소자입니다.","빛을 냅니다.","정답. 포토 다이오드","교류 스위칭 소자입니다."],"t":"빛 검출 = 포토 다이오드"},"2020-4-기관3-23":{"w":"N형 반도체는 실리콘에 5가 원소(인, 비소 등)를 넣어 만들며, 이 불순물을 도너(donor)라 합니다. P형은 3가 원소인 억셉터를 넣습니다.","x":["도핑은 불순물을 넣는 과정입니다.","억셉터는 P형을 만드는 불순물입니다.","정공은 P형의 캐리어입니다.","정답. N형 = 도너(5가)"],"t":"N형 = 도너(5가), P형 = 억셉터(3가)"},"2020-4-기관3-24":{"w":"일정한 기준전압을 얻는 데는 제너 다이오드를 씁니다.","x":["해당하지 않습니다.","UJT가 아닙니다.","정답. 제너 다이오드","FET가 아닙니다."],"t":"기준전압 = 제너"},"2020-4-직무일반-1":{"w":"Abstract log(적요일지)는 한 항차가 끝난 뒤 그 항차의 주요 내용(항해시간, 연료 소비 등)을 요약한 기록입니다.","x":["Bell book은 기관 명령 기록부입니다.","정답. Abstract log = 항차 요약","Condition report는 상태 보고서입니다.","Engine room log book은 매일 쓰는 기관일지입니다."],"t":"Abstract log = 항차 요약"},"2020-4-직무일반-3":{"w":"그림은 관을 세 방향으로 나누는 T자 모양 부속품인 티(tee)입니다.","x":["정답. T자 모양 = 티","니플은 짧은 양쪽 수나사 관입니다.","엘보는 방향을 90°·45°로 꺾는 부속품입니다.","플러그는 관 끝을 막는 마개입니다."],"t":"티 = 분기, 엘보 = 방향 전환"},"2020-4-직무일반-4":{"w":"부식으로 얇아진 외판 두께는 한쪽 면에서 초음파를 보내 반사 시간으로 두께를 재는 초음파 두께 측정법으로 잽니다.","x":["정답. 두께 측정 = 초음파","자기탐상은 표면 균열 검사용입니다.","다이체크는 표면 균열 검사용입니다.","침투탐상은 표면 균열 검사용입니다."],"t":"두께 측정 = 초음파"},"2020-4-직무일반-6":{"w":"슬러지는 소각하거나, 육상으로 양륙하거나, 저장 후 수용시설로 보냅니다. 15[ppm] 기름여과장치로 처리하는 것은 빌지입니다.","x":["정답(옳지 않은 것). 여과장치는 빌지용입니다.","소각합니다.","양륙합니다.","저장 후 이송합니다."],"t":"슬러지 ≠ 여과장치"},"2020-4-직무일반-7":{"w":"유출된 기름이 퍼지는 것을 막기 위해 선박 주위에 오일펜스를 둘러칩니다. 그 뒤 유회수기로 거두고 흡착재로 닦아 냅니다.","x":["유회수기는 기름을 거두어들이는 장비입니다.","흡착재는 기름을 빨아들이는 재료입니다.","정답. 확산 방지 = 오일펜스","유겔화제는 기름을 굳히는 약제입니다."],"t":"확산 방지 = 오일펜스"},"2020-4-직무일반-9":{"w":"일산화탄소(CO)는 헤모글로빈과 산소보다 훨씬 강하게 결합해 적은 양으로도 산소 운반을 막습니다.","x":["정답. 일산화탄소","이산화탄소가 아닙니다.","미연탄화수소가 아닙니다.","이산화질소가 아닙니다."],"t":"CO = 헤모글로빈 결합"},"2020-4-직무일반-10":{"w":"연료유 수급 후 기관일지에는 수급량, 수급 시간, 비중·점도 등 사양을 기록합니다. 선장과 책임사관의 성명은 기록 항목이 아닙니다.","x":["기록합니다.","기록합니다.","정답(아닌 것). 성명은 기록하지 않습니다.","기록합니다."],"t":"수급 기록 = 양·시간·사양"},"2020-4-직무일반-11":{"w":"검역 감염병에는 콜레라, 페스트, 황열 등이 있습니다. 장티푸스는 검역 감염병이 아닙니다.","x":["검역 감염병입니다.","정답(아닌 것). 장티푸스","검역 감염병입니다.","검역 감염병입니다."],"t":"검역 = 콜레라·페스트·황열"},"2020-4-직무일반-13":{"w":"더운 찜질은 혈관을 넓혀 통증과 근육 경련을 완화하고 화농을 촉진합니다. 혈관을 수축시키는 것은 냉찜질입니다.","x":["목적입니다.","정답(아닌 것). 혈관 수축은 냉찜질","목적입니다.","목적입니다."],"t":"온찜질 = 혈관 확장, 냉찜질 = 수축"},"2020-4-직무일반-14":{"w":"이중저 탱크에는 연료유, 청수, 평형수 등을 저장합니다. 청정유는 서비스 탱크에 저장합니다.","x":["정답(아닌 것). 청정유는 서비스 탱크","저장합니다.","저장합니다.","저장합니다."],"t":"청정유 = 서비스 탱크"},"2020-4-직무일반-20":{"w":"소화전에는 소화 호스, 노즐, 스패너(연결용)를 비치합니다. 안전등은 비치하지 않습니다.","x":["비치합니다.","비치합니다.","비치합니다.","정답(아닌 것). 안전등"],"t":"소화전 = 호스·노즐·스패너"},"2020-4-직무일반-21":{"w":"밀폐된 장소의 화재는 전원·통풍을 차단하고 주변을 냉각해 확산을 막은 뒤 고정식 소화설비 등으로 끕니다. 휴대용 포말 소화기를 들고 들어가는 것은 매우 위험합니다.","x":["전원 차단은 올바른 조치입니다.","통풍 차단은 산소 공급을 막는 올바른 조치입니다.","인접 격실 냉각은 확산 방지 조치입니다.","정답(옳지 않은 것). 휴대 소화기로 진입하는 것은 위험합니다."],"t":"밀폐 구역 화재 = 차단·냉각·고정식 소화"},"2020-4-직무일반-22":{"w":"선박법은 국적, 톤수 측정·등록, 한국선박의 권리·의무 등을 정합니다. 안전설비는 선박안전법의 내용입니다.","x":["선박법입니다.","정답(아닌 것). 안전설비는 선박안전법","선박법입니다.","선박법입니다."],"t":"안전설비 = 선박안전법"},"2020-4-직무일반-23":{"w":"임시검사는 용도 변경, 길이 변경 등 개조, 무선설비 신설 때 받습니다. 검사증서 유효기간이 끝나면 정기검사를 받습니다.","x":["임시검사 대상입니다.","정답(아닌 것). 정기검사 대상입니다.","임시검사 대상입니다.","임시검사 대상입니다."],"t":"유효기간 만료 = 정기검사"},"2020-4-직무일반-24":{"w":"해기사 면허의 유효기간은 5년입니다.","x":["틀립니다.","틀립니다.","틀립니다.","정답. 5년"],"t":"해기사 면허 5년"},"2020-4-직무일반-25":{"w":"유조선이 아닌 선박의 기관구역용 폐유저장용기는 총톤수 5~10톤 미만 20[ℓ], 10~30톤 미만 60[ℓ], 30~50톤 미만 100[ℓ], 50~100톤 미만 200[ℓ]입니다.","x":["5톤 이상 10톤 미만 기준입니다.","10톤 이상 30톤 미만 기준입니다.","30톤 이상 50톤 미만 기준입니다.","정답. 50톤 이상 100톤 미만 = 200[ℓ]"],"t":"폐유저장용기 20 → 60 → 100 → 200ℓ"},"2020-4-영어-1":{"w":"\"모든 공기 ( )에 압축공기를 충전했다.\" vessels, tanks, reservoirs는 공기탱크지만 coolers(냉각기)는 알맞지 않습니다.","x":["공기 용기입니다.","정답(적합하지 않은 것). coolers","공기 탱크입니다.","공기 저장조입니다."],"t":"air reservoir = 공기탱크"},"2020-4-영어-2":{"w":"수관(water tubes), 노(furnace), 연소실 청소는 보일러 정비입니다.","x":["정답. Boiler","소각기가 아닙니다.","냉각기가 아닙니다.","응축기가 아닙니다."],"t":"water tube·furnace = 보일러"},"2020-4-영어-4":{"w":"보일러 점화 전에 노 안을 송풍기로 환기하는 것은 Pre-purge(프리퍼지)입니다. 소화 후 환기는 Post-purge입니다.","x":["Post-purge = 소화 후 환기","정답. Pre-purge = 점화 전 환기","Surface blow down = 수면 분출","Bottom blow down = 수저 분출"],"t":"pre = 전, post = 후"},"2020-4-영어-6":{"w":"at once = 즉시 = instantly.","x":["때때로","자주","자주","정답. instantly"],"t":"at once = instantly"},"2020-4-영어-7":{"w":"\"주기관 섬프 탱크의 양을 확인했다.\" amount = 양.","x":["정답. amount","인화점","점도","연소점"],"t":"ascertain amount = 양 확인"},"2020-4-영어-8":{"w":"plummer block = 중간축 베어링(intermediate bearing)입니다.","x":["중간축이 아니라 베어링입니다.","정답. intermediate bearing","프로펠러축입니다.","추력 베어링입니다."],"t":"plummer block = 중간축 베어링"},"2020-4-영어-10":{"w":"\"분사 압력(injection pressure)을 30[MPa]로 조정했다.\"","x":["온도","정답. pressure","유량","점도"],"t":"injection pressure = 분사 압력"},"2020-4-영어-11":{"w":"hydrostatic test = 수압 시험 = water pressure test 입니다.","x":["정답. water pressure test = 수압 시험","humidity test = 습도 시험","tension test = 인장 시험","deformation test = 변형 시험"],"t":"hydrostatic test = 수압 시험"},"2020-4-영어-13":{"w":"응축기 덮개의 아연판(zinc plates)은 해수 부식을 막는 방식(anti-corrosion)용입니다.","x":["정답. anti-corrosion","노킹 방지가 아닙니다.","안정기가 아닙니다.","침식 방지가 아닙니다."],"t":"zinc = 부식 방지"},"2020-4-영어-15":{"w":"보일러 연도(uptake)에 설치해 배기가스 흐름을 조절하는 장치는 댐퍼(damper)입니다.","x":["정답. damper","수트 블로어는 그을음 제거","버너는 연소 장치","송풍기는 통풍 장치"],"t":"damper = 가스 흐름 조절"},"2020-4-영어-16":{"w":"프로펠러축이 지나가는 관은 stern tube(선미관)입니다.","x":["덕트가 아닙니다.","틀립니다.","정답. stern tube","틀립니다."],"t":"stern tube = 선미관"},"2020-4-영어-17":{"w":"시간당 해리(nautical miles per hour)로 나타낸 속도는 knot(노트)입니다.","x":["배럴","와트","동력","정답. knot"],"t":"knot = 해리/시"},"2020-4-영어-21":{"w":"뜨겁고 찬 정도를 재는 도구는 Thermometer(온도계)입니다.","x":["습도계","정답. Thermometer","열량계","염분계"],"t":"thermometer = 온도계"},"2020-4-영어-22":{"w":"F.W.E.(Finished With Engine, 기관 사용 종료) 후에는 테스트 콕을 열고, 보조 송풍기를 멈추고, 에어 러닝을 하고, 터닝기어를 연결(engage)해 주기관을 돌립니다. 터닝기어를 분리(disengage)하는 것은 시동 준비 때 하는 일입니다.","x":["테스트 콕을 엽니다.","보조 송풍기를 멈춥니다.","에어 러닝을 합니다.","정답(아닌 것). F.W.E. 후에는 터닝기어를 연결합니다."],"t":"F.W.E. 후 = engage turning gear"},"2020-4-영어-24":{"w":"보일러 압력을 방출해 폭발을 막는 것은 Safety valve(안전밸브)입니다.","x":["역지밸브","정답. Safety valve","Relief valve는 주로 액체용","바이패스 밸브"],"t":"보일러 = safety valve"},"2020-4-영어-25":{"w":"흡·배기밸브가 모두 닫히고 피스톤이 올라가며 공기를 압축하는 것은 압축행정입니다.","x":["흡입행정이 아닙니다.","배기행정이 아닙니다.","작동행정이 아닙니다.","정답. Compression stroke"],"t":"압축행정"},"2021-1-기관3-14":{"w":"주파수가 낮아지면 동기속도가 줄어 회전속도가 감소하고, 전압이 같으면 자속이 늘어 여자전류가 커지므로 전류는 증가합니다.","x":["정답. 속도↓, 전류↑","반대입니다.","전류는 증가합니다.","속도는 감소합니다."],"t":"주파수↓ → 속도↓·전류↑"},"2021-1-직무일반-2":{"w":"정박 중 기관일지에는 연료유 수급 시각과 양, 기관부 작업, 유류·청수 사용량과 잔량 등을 기록합니다. 조타기 유압유 잔량·압력은 기록 사항이 아닙니다.","x":["기록합니다.","기록합니다.","정답(아닌 것). 조타기 유압유는 기록하지 않습니다.","기록합니다."],"t":"정박 일지 = 수급·작업·소비량"},"2021-2-기관2-3":{"w":"랜턴링은 글랜드패킹 가운데에 끼우는 링으로, 송출측 압력수를 받아 패킹부를 밀봉·냉각·윤활합니다. 추력을 상쇄하는 역할은 없습니다(추력 상쇄는 밸런스 디스크).","x":["정답(옳지 않은 것). 추력 상쇄는 랜턴링의 역할이 아닙니다.","패킹 가운데에 있습니다.","냉각과 윤활을 돕습니다.","송출측과 연결되어 압력수를 받습니다."],"t":"랜턴링 = 봉수 공급"},"2021-2-기관2-7":{"w":"콜레서(coalescer)는 빌지 속의 아주 작은 기름방울을 섬유 필터에 흡착시켜 서로 뭉치게 해 큰 방울로 만듭니다. 커진 기름방울은 위로 잘 떠올라 분리됩니다.","x":["기름을 잘게 부수면 분리가 더 어려워집니다.","정답. 작은 기름 입자를 뭉쳐 큰 입자로 만듭니다.","물만 통과시키는 여과 필터와는 원리가 다릅니다.","기름만 통과시키는 장치가 아닙니다."],"t":"콜레서 = 작은 기름방울을 모아 큰 방울로"},"2021-2-직무일반-7":{"w":"오존층파괴물질기록부는 프레온 등 오존층파괴물질에 대한 사항을 기록합니다. 황산화물은 연료유 공급서 등으로 관리합니다.","x":["맞습니다.","맞습니다.","맞습니다.","정답(옳지 않은 것). 오존층파괴물질을 기록합니다."],"t":"ODS 기록부 = 프레온 등"},"2021-2-직무일반-23":{"w":"4급 기관사는 연근해·평수구역에서 일정 추진력 이하 선박의 기관장이 될 수 있습니다. 무제한수역을 항행하는 추진력 1,500[kW] 이상, 총톤수 500톤 이상 어선의 기관장은 상위 면허가 필요합니다.","x":["승선 가능합니다.","승선 가능합니다.","승선 가능합니다.","정답(승선 불가). 무제한수역 대형 어선"],"t":"4급 기관장 = 제한된 수역·추진력"},"2021-3-기관1-2":{"w":"실린더 헤드는 연소실을 이루고 대각선으로 나누어 조이며 열응력으로 균열이 생기기 쉽습니다. 냉각수 측 부식 방지에는 주석이 아니라 아연봉(방식 아연)을 설치합니다.","x":["연소실을 형성합니다.","대각선으로 조입니다.","균열이 생기기 쉽습니다.","정답(옳지 않은 것). 방식용은 아연봉입니다."],"t":"방식봉 = 아연"},"2021-3-기관1-6":{"w":"피스톤핀은 트렁크형 기관에서 피스톤과 커넥팅로드를 연결하고 힘을 전달하며, 표면 경화강으로 만듭니다. 크로스헤드형 기관에는 피스톤핀이 없고 크로스헤드핀이 있습니다.","x":["트렁크형에서 피스톤과 커넥팅로드를 연결합니다.","힘을 전달합니다.","표면 경화강을 씁니다.","정답(옳지 않은 것). 크로스헤드형에는 피스톤핀이 없습니다."],"t":"피스톤핀 = 트렁크형 기관"},"2021-3-기관2-19":{"w":"탄산가스(CO₂) 아크 용접은 와이어가 연속으로 공급되어 연속 용접이 가능하므로 생산성이 높습니다. 실드가스는 CO₂이고, 전류 밀도가 높으며, 스패터는 많은 편입니다.","x":["아르곤·헬륨은 TIG·MIG용입니다.","스패터가 많습니다.","전류 밀도가 높습니다.","정답. 연속 용접, 생산성 높음"],"t":"CO₂ 용접 = 와이어 연속 공급"},"2021-3-기관2-21":{"w":"피크 탱크(선수·선미 탱크)는 트림 조정, 선수 손상 시 침수 범위 한정, 선미 진동 완화 등에 쓰입니다. 모양이 좁고 복잡해 화물창으로 쓰지 않습니다.","x":["트림 조정에 씁니다.","침수 범위를 한정합니다.","정답(옳지 않은 것). 화물창으로 쓰지 않습니다.","진동을 완화합니다."],"t":"피크 탱크 = 밸러스트·트림용"},"2021-3-직무일반-14":{"w":"주기관 진동이 심하면 노킹, 위험회전수 운전, 베드 볼트 이완·절손, 각 실린더 출력 불균형 등을 점검합니다. 연료유 여과기 막힘은 출력 저하·정지의 원인이지 진동 점검 사항이 아닙니다.","x":["정답(옳지 않은 것). 여과기 막힘은 진동 점검 사항이 아닙니다.","노킹을 확인합니다.","위험회전수를 확인합니다.","베드 볼트를 확인합니다."],"t":"진동 점검 = 노킹·위험회전수·베드 볼트"},"2021-3-직무일반-16":{"w":"Crash astern은 전속 전진 중 충돌 위험 등 비상시 주기관을 긴급히 후진시키는 기능입니다.","x":["위험회전수 회피 기능과 다릅니다.","정답. 전진 중 긴급 후진","부하 변동 시 정지 기능이 아닙니다.","윤활유 압력 저하 시에는 정지(셧다운)만 합니다."],"t":"Crash astern = 긴급 후진"},"2021-3-직무일반-17":{"w":"선택(우선) 차단은 발전기 과부하 시 덜 중요한 부하부터 차단하는 기능입니다. 발전기가 전동기처럼 도는 것을 막는 것은 역전력 계전기의 기능입니다.","x":["트립 코일이 있습니다.","덜 중요한 기기부터 차단합니다.","과부하 시 선택 부하를 차단합니다.","정답(옳지 않은 것). 역전력 보호에 대한 설명입니다."],"t":"선택 차단 = 과부하 시 비중요 부하 차단"},"2021-3-직무일반-24":{"w":"4급 기관사는 연근해·평수구역에서 일정 추진력 이하 선박의 기관장이 될 수 있습니다. 무제한수역을 항행하는 추진력 1,500[kW] 이상, 총톤수 500톤 이상 어선의 기관장은 상위 면허가 필요합니다.","x":["승선 가능합니다.","승선 가능합니다.","승선 가능합니다.","정답(승선 불가). 무제한수역 대형 어선"],"t":"4급 기관장 = 제한된 수역·추진력"},"2021-4-기관2-9":{"w":"갑판 유압기기는 유압펌프 1대로 여러 대의 유압모터(윈치 등)를 구동할 수 있습니다.","x":["개수 제한이 없습니다.","같을 필요가 없습니다.","정답. 펌프 1대로 여러 모터 구동","펌프 없이 모터만으로는 안 됩니다."],"t":"유압 = 펌프 1대 → 모터 여러 대"},"2021-4-기관2-22":{"w":"피크 탱크(선수·선미 탱크)는 트림 조정, 선수 손상 시 침수 범위 한정, 선미 진동 완화 등에 쓰입니다. 모양이 좁고 복잡해 화물창으로 쓰지 않습니다.","x":["트림 조정에 씁니다.","침수 범위를 한정합니다.","정답(옳지 않은 것). 화물창으로 쓰지 않습니다.","진동을 완화합니다."],"t":"피크 탱크 = 밸러스트·트림용"},"2021-4-기관2-23":{"w":"수밀격벽은 침수 범위를 한정하고 방화벽 역할을 하며, 기관실 앞·뒤는 수밀격벽으로 합니다. 주로 수직 횡격벽으로 설치해 횡강도를 형성합니다.","x":["침수를 한정합니다.","방화벽 역할도 합니다.","기관실 전후는 수밀격벽입니다.","정답(옳지 않은 것). 주로 수직 횡격벽입니다."],"t":"수밀격벽 = 수직 횡격벽"},"2021-4-기관3-9":{"w":"콘덴서는 병렬로 연결하면 용량이 더해지므로 연결할수록 전체 용량이 커집니다. 직렬로 연결하면 C1C2/(C1 + C2)로 작아집니다.","x":["직렬 합성용량은 C1C2/(C1+C2)입니다.","병렬에서는 작은 용량을 무시할 수 있습니다.","병렬 합성용량은 C1 + C2입니다.","정답. 병렬로 연결할수록 용량 증가"],"t":"콘덴서 병렬 = 합, 직렬 = 곱/합"},"2021-4-직무일반-6":{"w":"선박해양오염비상계획서에는 방제조직, 선원이 취할 방제조치, 선장의 보고 절차, 연안국에 통보할 기관과 연락처 등이 들어갑니다. 통보 대상은 기국이 아니라 연안국(사고 해역 국가)입니다.","x":["방제조직이 포함됩니다.","보고 절차가 포함됩니다.","방제조치가 포함됩니다.","정답(아닌 것). 기국이 아니라 연안국 연락처입니다."],"t":"비상계획서 = 연안국 연락처"},"2022-1-기관1-21":{"w":"연소하면 황산화물, 질소산화물, 매연(입자상 물질) 등이 직접 나옵니다. 오존은 대기 중에서 광화학 반응으로 생기는 2차 오염물질입니다.","x":["정답(아닌 것). 오존은 연소에서 직접 나오지 않습니다.","연소에서 직접 나옵니다.","연소에서 직접 나옵니다.","연소에서 직접 나옵니다."],"t":"오존 = 2차 생성물"},"2022-1-기관2-6":{"w":"갑판 유압기기는 유압펌프 1대로 여러 대의 유압모터(윈치 등)를 구동할 수 있습니다.","x":["개수 제한이 없습니다.","같을 필요가 없습니다.","정답. 펌프 1대로 여러 모터 구동","펌프 없이 모터만으로는 안 됩니다."],"t":"유압 = 펌프 1대 → 모터 여러 대"},"2022-1-기관2-17":{"w":"드릴 작업 때는 가공물을 바이스로 고정하고, 장갑을 끼지 않으며(말려 들어감), 얇은 가공물은 나무 받침을 대고 작업합니다.","x":["손으로 잡으면 위험합니다.","장갑은 말려 들어가 위험합니다.","정답. 나무 받침대","가공물을 돌리면 위험합니다."],"t":"드릴 = 장갑 금지, 바이스 고정"},"2022-2-기관2-14":{"w":"냉매는 수액기 출구 밸브를 닫고 보충합니다.","x":["충전관의 공기는 냉매 가스로 배제합니다.","응축기에 냉각수를 흘리며 합니다.","정답(옳지 않은 것). 수액기 출구 밸브는 닫습니다.","용기 무게로 보충량을 압니다."],"t":"냉매 보충 = 수액기 출구 밸브 닫기"},"2022-2-기관2-21":{"w":"피크 탱크(선수·선미 탱크)는 트림 조정, 선수 손상 시 침수 범위 한정, 선미 진동 완화 등에 쓰입니다. 모양이 좁고 복잡해 화물창으로 쓰지 않습니다.","x":["트림 조정에 씁니다.","침수 범위를 한정합니다.","정답(옳지 않은 것). 화물창으로 쓰지 않습니다.","진동을 완화합니다."],"t":"피크 탱크 = 밸러스트·트림용"},"2022-2-직무일반-5":{"w":"선급 검사는 정기검사 5년, 연차검사 매년(기준일 전후 3개월), 보일러검사 2.5년 등입니다. 입거검사는 정기검사 기간(5년) 동안 2번 받습니다.","x":["정기검사는 5년입니다.","연차검사는 전후 3개월 이내입니다.","정답(옳지 않은 것). 입거검사는 5년에 2번입니다.","보일러검사는 2.5년입니다."],"t":"입거검사 = 5년에 2회"},"2022-2-직무일반-25":{"w":"분뇨마쇄소독장치 기술기준에는 악취 방지, 순환수장치·보조탱크 합계 150[ℓ] 이상, 육상 수용시설로 배출할 충분한 용량의 배출펌프 등이 있습니다. 발생가스 고압경보장치는 기준에 없습니다.","x":["악취 발산 방지는 기준입니다.","정답(옳지 않은 것). 고압경보장치는 기준에 없습니다.","배출펌프 용량 기준은 맞습니다.","합계 150[ℓ] 이상은 기준입니다."],"t":"분뇨마쇄소독장치 = 150ℓ 이상"},"2022-3-기관2-8":{"w":"갑판 유압기기는 유압펌프 1대로 여러 대의 유압모터(윈치 등)를 구동할 수 있습니다.","x":["개수 제한이 없습니다.","같을 필요가 없습니다.","정답. 펌프 1대로 여러 모터 구동","펌프 없이 모터만으로는 안 됩니다."],"t":"유압 = 펌프 1대 → 모터 여러 대"},"2022-3-기관2-9":{"w":"콜레서(coalescer)는 빌지 속의 아주 작은 기름방울을 섬유 필터에 흡착시켜 서로 뭉치게 해 큰 방울로 만듭니다. 커진 기름방울은 위로 잘 떠올라 분리됩니다.","x":["기름을 잘게 부수면 분리가 더 어려워집니다.","정답. 작은 기름 입자를 뭉쳐 큰 입자로 만듭니다.","물만 통과시키는 여과 필터와는 원리가 다릅니다.","기름만 통과시키는 장치가 아닙니다."],"t":"콜레서 = 작은 기름방울을 모아 큰 방울로"},"2022-3-직무일반-14":{"w":"무인화 선박에서 정전되면 먼저 S/B 예비발전기가 자동 기동해 약 45초 이내에 전력을 공급합니다. 예비발전기가 규정 시간 안에 전력을 공급하지 못하면 비상발전기가 전력을 공급합니다.","x":["정전과 동시에 예비발전기가 기동합니다.","S/B 순서대로 기동합니다.","정답(옳지 않은 것). 예비발전기가 먼저 기동합니다.","예비발전기가 실패하면 비상발전기가 공급합니다."],"t":"정전 → 예비발전기 먼저 → 실패 시 비상발전기"},"2022-3-직무일반-15":{"w":"Crash astern은 전속 전진 중 충돌 위험 등 비상시 주기관을 긴급히 후진시키는 기능입니다.","x":["위험회전수 회피 기능과 다릅니다.","정답. 전진 중 긴급 후진","부하 변동 시 정지 기능이 아닙니다.","윤활유 압력 저하 시에는 정지(셧다운)만 합니다."],"t":"Crash astern = 긴급 후진"},"2022-3-직무일반-24":{"w":"4급 기관사는 연근해·평수구역에서 일정 추진력 이하 선박의 기관장이 될 수 있습니다. 무제한수역을 항행하는 추진력 1,500[kW] 이상, 총톤수 500톤 이상 어선의 기관장은 상위 면허가 필요합니다.","x":["승선 가능합니다.","승선 가능합니다.","승선 가능합니다.","정답(승선 불가). 무제한수역 대형 어선"],"t":"4급 기관장 = 제한된 수역·추진력"},"2022-3-영어-23":{"w":"디젤기관에서 연료는 피스톤이 가장 높은 위치(highest)인 상사점(TDC) 부근에서 분사됩니다.","x":["lowest가 틀립니다.","정답. TDC, highest","BDC가 틀립니다.","BDC가 틀립니다."],"t":"분사 = TDC 부근"},"2022-4-기관2-22":{"w":"피크 탱크(선수·선미 탱크)는 트림 조정, 선수 손상 시 침수 범위 한정, 선미 진동 완화 등에 쓰입니다. 모양이 좁고 복잡해 화물창으로 쓰지 않습니다.","x":["트림 조정에 씁니다.","침수 범위를 한정합니다.","정답(옳지 않은 것). 화물창으로 쓰지 않습니다.","진동을 완화합니다."],"t":"피크 탱크 = 밸러스트·트림용"},"2022-4-직무일반-15":{"w":"Crash astern은 전속 전진 중 충돌 위험 등 비상시 주기관을 긴급히 후진시키는 기능입니다.","x":["위험회전수 회피 기능과 다릅니다.","정답. 전진 중 긴급 후진","부하 변동 시 정지 기능이 아닙니다.","윤활유 압력 저하 시에는 정지(셧다운)만 합니다."],"t":"Crash astern = 긴급 후진"},"2023-1-기관1-2":{"w":"밸브 개폐시기 선도는 흡·배기밸브가 열리고 닫히는 시기를 상사점·하사점 전후의 크랭크 각도로 나타낸 그림입니다.","x":["정답. 크랭크 각도","압력으로 나타내지 않습니다.","회전속도가 아닙니다.","피스톤 위치가 아니라 크랭크 각도입니다."],"t":"밸브 선도 = 크랭크 각도"},"2023-1-직무일반-8":{"w":"선박해양오염비상계획서에는 방제조직, 선원이 취할 방제조치, 선장의 보고 절차, 연안국에 통보할 기관과 연락처 등이 들어갑니다. 통보 대상은 기국이 아니라 연안국(사고 해역 국가)입니다.","x":["방제조직이 포함됩니다.","보고 절차가 포함됩니다.","방제조치가 포함됩니다.","정답(아닌 것). 기국이 아니라 연안국 연락처입니다."],"t":"비상계획서 = 연안국 연락처"},"2023-3-직무일반-20":{"w":"모든 선박은 다른 소화장치와 관계없이 소화펌프·소화전·호스로 된 수(물) 소화장치를 기본으로 갖춰야 합니다.","x":["정답. 수 소화장치","선택 설비입니다.","선택 설비입니다.","선택 설비입니다."],"t":"기본 소화장치 = 물(소화전)"},"2023-4-기관2-9":{"w":"콜레서(coalescer)는 빌지 속의 아주 작은 기름방울을 섬유 필터에 흡착시켜 서로 뭉치게 해 큰 방울로 만듭니다. 커진 기름방울은 위로 잘 떠올라 분리됩니다.","x":["기름을 잘게 부수면 분리가 더 어려워집니다.","정답. 작은 기름 입자를 뭉쳐 큰 입자로 만듭니다.","물만 통과시키는 여과 필터와는 원리가 다릅니다.","기름만 통과시키는 장치가 아닙니다."],"t":"콜레서 = 작은 기름방울을 모아 큰 방울로"},"2023-4-직무일반-1":{"w":"무인화 선박에서 정전되면 먼저 S/B 예비발전기가 자동 기동해 약 45초 이내에 전력을 공급합니다. 예비발전기가 규정 시간 안에 전력을 공급하지 못하면 비상발전기가 전력을 공급합니다.","x":["정전과 동시에 예비발전기가 기동합니다.","S/B 순서대로 기동합니다.","정답(옳지 않은 것). 예비발전기가 먼저 기동합니다.","예비발전기가 실패하면 비상발전기가 공급합니다."],"t":"정전 → 예비발전기 먼저 → 실패 시 비상발전기"},"2023-4-직무일반-21":{"w":"모든 선박은 다른 소화장치와 관계없이 소화펌프·소화전·호스로 된 수(물) 소화장치를 기본으로 갖춰야 합니다.","x":["정답. 수 소화장치","선택 설비입니다.","선택 설비입니다.","선택 설비입니다."],"t":"기본 소화장치 = 물(소화전)"},"2024-2-기관1-16":{"w":"프로펠러축이 부러지는 원인은 재질 불량, 비틀림 진동, 부식에 의한 강도 저하, 축심 불일치 등입니다. 추력 베어링의 마멸은 축의 전후 위치에 영향을 주지만 프로펠러축 절손의 직접 원인은 아닙니다.","x":["재질 불량은 절손 원인입니다.","정답(아닌 것). 추력 베어링 마멸은 직접 원인이 아닙니다.","비틀림 진동은 피로 파괴의 원인입니다.","부식으로 강도가 떨어지면 부러지기 쉽습니다."],"t":"프로펠러축 절손 = 재질, 비틀림 진동, 부식"},"2024-3-직무일반-1":{"w":"출거 전에는 물에 잠기는 곳(시체스트·선저밸브, 프로펠러·선미관, 선외밸브)의 조립 상태를 반드시 확인해야 합니다. 청정기 조립 상태는 출거 후에도 확인할 수 있습니다.","x":["정답(아닌 것). 청정기는 출거 전 필수 확인 사항이 아닙니다.","선저밸브는 반드시 확인합니다.","프로펠러·선미관은 반드시 확인합니다.","선외밸브는 반드시 확인합니다."],"t":"출거 전 = 수선 아래 장치 확인"},"2024-4-직무일반-4":{"w":"스톱밸브(글로브·앵글밸브)는 작동이 확실하고 밀착이 좋아 기관실에 많이 쓰이지만, 유체가 S자로 꺾여 흐르므로 완전히 열어도 저항(에너지 손실)이 큽니다. 손실이 가장 적은 것은 게이트(슬루스)밸브입니다.","x":["기관실에 많이 씁니다.","작동이 확실합니다.","글러브·앵글밸브로 나뉩니다.","정답(옳지 않은 것). 스톱밸브는 손실이 큰 편입니다."],"t":"손실 최소 = 게이트밸브"},"2024-4-직무일반-20":{"w":"기관실 화재 예방은 순찰, 청결 유지, 통풍, 누유 방지 등입니다. 비상 빌지 펌프 확인은 침수 대비책입니다.","x":["순찰은 예방법입니다.","청결 유지는 예방법입니다.","정답(옳지 않은 것). 침수 대비책입니다.","통풍은 예방법입니다."],"t":"빌지 펌프 = 침수 대비"},"2020-2-기관1-25":{"w":"점도가 높으면 유막은 두꺼워지지만 마찰 저항(점성 저항)은 커집니다.","x":["정답(옳지 않은 것). 점도가 높으면 마찰 저항이 커집니다.","맞습니다.","맞습니다.","맞습니다."],"t":"고하중 = 고점도, 고속 = 저점도"},"2020-2-직무일반-15":{"w":"무인화 선박에서 정전되면 먼저 S/B 예비발전기가 자동 기동해 약 45초 이내에 전력을 공급합니다. 예비발전기가 규정 시간 안에 전력을 공급하지 못하면 비상발전기가 전력을 공급합니다.","x":["정전과 동시에 예비발전기가 기동합니다.","S/B 순서대로 기동합니다.","정답(옳지 않은 것). 예비발전기가 먼저 기동합니다.","예비발전기가 실패하면 비상발전기가 공급합니다."],"t":"정전 → 예비발전기 먼저 → 실패 시 비상발전기"},"2020-2-직무일반-16":{"w":"Crash astern은 전속 전진 중 충돌 위험 등 비상시 주기관을 긴급히 후진시키는 기능입니다.","x":["위험회전수 회피 기능과 다릅니다.","정답. 전진 중 긴급 후진","부하 변동 시 정지 기능이 아닙니다.","윤활유 압력 저하 시에는 정지(셧다운)만 합니다."],"t":"Crash astern = 긴급 후진"},"2020-3-기관1-17":{"w":"미첼형 스러스트 베어링은 칼라 하나의 앞뒤에 6~8개의 부채꼴 패드가 있어 쐐기형 유막으로 큰 추력을 받습니다. 추력 칼라는 1개입니다.","x":["맞습니다.","맞습니다.","정답(옳지 않은 것). 추력 칼라는 1개","맞습니다."],"t":"미첼형 = 칼라 1개 + 부채꼴 패드"},"2020-3-기관2-5":{"w":"공기는 압축되므로 유압 조종장치 관 속에 공기가 있으면 조타륜을 돌려도 그 움직임이 바로 전달되지 않습니다. 운동의 전달이 정확하지 않게 됩니다.","x":["압력계 지시값이 높아지는 것은 아닙니다.","정답. 공기가 압축되어 움직임이 정확히 전달되지 않습니다.","조종장치 관 속 공기의 대표 현상이 아닙니다.","조종장치 관 속 공기의 대표 현상이 아닙니다."],"t":"유압 관 속 공기 → 전달이 부정확"},"2020-3-직무일반-10":{"w":"오존층파괴물질기록부는 프레온 등 오존층파괴물질에 대한 사항을 기록합니다. 황산화물은 연료유 공급서 등으로 관리합니다.","x":["맞습니다.","맞습니다.","맞습니다.","정답(옳지 않은 것). 오존층파괴물질을 기록합니다."],"t":"ODS 기록부 = 프레온 등"},"2020-3-직무일반-17":{"w":"선택(우선) 차단은 발전기 과부하 시 덜 중요한 부하부터 차단하는 기능입니다. 발전기가 전동기처럼 도는 것을 막는 것은 역전력 계전기의 기능입니다.","x":["트립 코일이 있습니다.","덜 중요한 기기부터 차단합니다.","과부하 시 선택 부하를 차단합니다.","정답(옳지 않은 것). 역전력 보호에 대한 설명입니다."],"t":"선택 차단 = 과부하 시 비중요 부하 차단"},"2020-3-직무일반-20":{"w":"전기화재를 막으려면 절연저항을 규정치 이상으로 유지해야 합니다.","x":["예방법입니다.","예방법입니다.","정답(아닌 것). 절연저항은 높게","예방법입니다."],"t":"절연저항 = 높게"},"2020-3-직무일반-23":{"w":"4급 기관사는 연근해·평수구역에서 일정 추진력 이하 선박의 기관장이 될 수 있습니다. 무제한수역을 항행하는 추진력 1,500[kW] 이상, 총톤수 500톤 이상 어선의 기관장은 상위 면허가 필요합니다.","x":["승선 가능합니다.","승선 가능합니다.","승선 가능합니다.","정답(승선 불가). 무제한수역 대형 어선"],"t":"4급 기관장 = 제한된 수역·추진력"},"2020-4-직무일반-8":{"w":"오존층파괴물질기록부는 프레온 등 오존층파괴물질에 대한 사항을 기록합니다. 황산화물은 연료유 공급서 등으로 관리합니다.","x":["맞습니다.","맞습니다.","맞습니다.","정답(옳지 않은 것). 오존층파괴물질을 기록합니다."],"t":"ODS 기록부 = 프레온 등"},"2020-4-직무일반-17":{"w":"무인화 선박에서 정전되면 먼저 S/B 예비발전기가 자동 기동해 약 45초 이내에 전력을 공급합니다. 예비발전기가 규정 시간 안에 전력을 공급하지 못하면 비상발전기가 전력을 공급합니다.","x":["정전과 동시에 예비발전기가 기동합니다.","S/B 순서대로 기동합니다.","정답(옳지 않은 것). 예비발전기가 먼저 기동합니다.","예비발전기가 실패하면 비상발전기가 공급합니다."],"t":"정전 → 예비발전기 먼저 → 실패 시 비상발전기"},"2020-4-직무일반-19":{"w":"열작업 때는 반대편 격실에도 감시원을 두고, 가스 용기를 세우고, 혼자 작업하지 않습니다. 작업 구역은 통풍이 되어야 하므로 개폐구를 모두 닫아 두는 것은 옳지 않습니다.","x":["맞습니다.","맞습니다.","맞습니다.","정답(옳지 않은 것). 통풍을 유지합니다."],"t":"열작업 = 통풍·감시원"}};
